body:
[Corollary 19 (Finite-time empirical $W_2$ propagation of chaos) of arXiv:2608.28827, 'Quantitative Target Convergence and Uniform-in-Time\\ Propagation of Chaos for Langevin-Re'] Under Assumptions~\ref{ass:core-target},
\ref{ass:W2}, and \ref{ass:concentration},
\begin{equation}
  \E W_2^2(\mu_t^N,\mu_t)
  \le C\left\{
    \frac{e^{L_\mathrm{cpl}t}-1}{N}+r_{N,d}
  \right\}
  \le Cr_{N,d}e^{L_\mathrm{cpl}t}.
\end{equation}

