[Deff occ-meas of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] For any $x \in \mathcal{M}$ and $t > 0$ let $\mu_t^x$ denote the empirical occupation measure 
    \begin{equation}
    \mu_t^x(\omega) \coloneqq \frac{1}{t}\int_0^t \delta_{X_s^x(\omega)}ds,    
    \end{equation}
    where $\delta_y$ is the Dirac  measure concentrated at $y$, that is, $\delta_y f = f(y)$. Note that $\omega \in \Omega$, and therefore $\mu_t^x$ is a random measure which depends on $\omega$, but often this dependence is suppressed.

[Definition 3 of arXiv:2603.26936, 'Sharp Riemannian heat kernel estimates on the cut locus and the Parabolic Anderson model'] For $\epsilon\geq0$, let $c_\epsilon:=(2+\epsilon)$ and define two Gaussian type functions \begin{equation}
        G^\epsilon_t(r):=t^{-\frac{d}{2}}\exp\left(-\frac{r^2}{c_\epsilon t}\right),\quad\text{and}\quad \tilde{G}^\epsilon_t(r):=(t^{-\frac{d-1}{2}}\vee 1)G^\epsilon_t(r).
    \end{equation}

[Definition of arXiv:2412.08886, 'On domination for (non-symmetric) Dirichlet forms'] Let $({\mathscr E},{\mathscr F})$ and $({\mathscr E}',{\mathscr F}')$ be two Dirichlet forms on $L^2(E,m)$. 
\begin{itemize}
\item[(1)] We say that ${\mathscr E}'$ is \emph{subordinate to} ${\mathscr E}$ if ${\mathscr F}'\subset {\mathscr F}$ and (equation eq:21 of the paper) holds for all non-negative $f,g\in {\mathscr F}'$.  Furthermore, ${\mathscr E}'$ is \emph{strongly subordinate to} ${\mathscr E}$ if, in addition,  ${\mathscr F}'$ is dense in ${\mathscr F}$ with respect to the ${\mathscr E}_1$-norm.
\item[(2)] We say that ${\mathscr E}$ is a \emph{Silverstein extension} of ${\mathscr E}'$ if $\mathrm{b}{\mathscr F}'$ is an algebraic ideal in $\mathrm{b}{\mathscr F}$ and ${\mathscr E}={\mathscr E}'$ on $\mathrm{b}{\mathscr F}'\times \mathrm{b}{\mathscr F}'$.  
\end{itemize}

[Lemma 6 of arXiv:2506.18313, 'A stochastic model for the diffusion of competing opinions with trend-following, oppositio'] Assume for all $\varepsilon > 0$ that
\begin{equation}

    \displaystyle\sum_{n=1}^{\infty} \frac{1}{v_n} \dE\left[\vert\Delta Z_n\vert^2 \mathbb{I}_{\{\vert\Delta Z_n\vert\geq\varepsilon\sqrt{v_n}\}}\vert\mathcal{F}_{n-1}\right] < \infty \ \  \text{ a.s.},
\end{equation}
and for some $a>0$ that,
\begin{equation}

    \displaystyle\sum_{n=1}^{\infty} \frac{1}{v_n^a} \dE\left[\vert\Delta Z_n\vert^{2a} \mathbb{I}_{\{\vert\Delta Z_n\vert\leq\sqrt{v_n}\}}\vert\mathcal{F}_{n-1}\right] < \infty \ \  \text{ a.s. }
\end{equation}
Then, as $n$ diverges, $(Z_n)$ satisfies that
\begin{equation}
\displaystyle\lim_{n\to\infty}\displaystyle\frac{1}{\log v_{n}}\sum_{k=1}^n \left(\frac{v_{k}-v_{k-1}}{v_{k}}\right) \mathbb{I}\left\{\frac{Z_k}{\sqrt{v_{k-1}} } < x \right\} = G (x) \ \  \text{ a.s.,}
\end{equation}
where $\mathbb{I}\{\cdot\}$ denotes  the indicator function of events and $G$ stands for the distribution function of a normal random variable $N(0,\sigma^2)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 16 ($\rashlexpctparam$ local stability of  $\emprashomonset$ at $x$) of arXiv:2609.01397, 'Measuring consistency via ensemble margin and local prediction variability: Auditing decis'] Given  a Rashomon set $\emprashomonset$, a test point $x \in \dtest$, a perturbed sample of $x$, $\localtest \in \ltwohsphere(x,\sigma)$, and a small constant $\rashlexpctparam > 0$, $\emprashomonset$ is said to be locally $\rashlexpctparam$ stable if, 
\begin{align}
    \abs{f(\localtest)-\E_{\rf}[\rf(\localtest)]} \le \rashlexpctparam, \:\: \text{for all}\:\: f \in \emprashomonset, \localtest \in \ltwohsphere(x,\sigma).
\end{align}

[Lemma 48 of arXiv:2608.20252, '2608.20252'] We have $E_{\nu_\rho}\big[\|\eta\|\big]<\infty$ and hence the measure $\nu_\rho$ fully charges $\Omega'$, that is 
\begin{equation}

\nu_\rho(\Omega') \ =\  1.\end{equation}
Moreover, we have $E_{\nu_\rho}\big[\|\eta\|^2\big]<\infty$.

