[Prop 47 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $(\alpha^{(i)}_n)_{n \in \mathbb{N}_+}$, $i=1,2$, be two sequences of 
diverging sequence of constants such that~\eqref{e:seqConst} holds. 
Let $T>0$ and let $\{\mcb P^n_s\colon s\in[0,T]\}$ be a 
real--valued stochastic processes on $[0,T]$.  
Assume that there exist $\alpha\in(0,1)$ and $C=C(T)>0$, such that uniformly in $n$,
\begin{align}
\sup_{0\leq s\leq T}\E\left[ |\mcb P_s^{n}|\right]&\leq C\,,\\
\E\left[|\mcb P_t^{n}-\mcb P_s^{n}|\right]&\leq C(t-s)^{\alpha}\,,\qquad \text{for all $s,t\in[0,T]$.}
\end{align}
Then, for any $t\in[0,T]$, and Lebesgue-a.e. $k_1,k_2\in\R$
we have
\begin{equation}
\lim_{n\to\infty} \E\left[\left| \int_0^t\mcb P_s^{n} e^{-2\pi \iota  \frac{k_1\alpha_n^{(1)}+k_2\alpha_n^{(2)}}{n}}\dd s\right|\right]=0\,. 
\end{equation}

[Corollary 15 of arXiv:2608.30304, '2608.30304'] Let $n\ge1$, $a\ge A_0$ and $-\tfrac12\le b\le A_0$. If $1+x>\rho_{n,a}$, with
$\rho_{n,a}$ as in \eqref{eq:mixed-cap-region}, then
\begin{equation}
F_{n,a,b}(x)\le\theta_1\bigl\{F_{n-1,a,b+1}(x)+F_{n-1,a,b+2}(x)\bigr\},
\qquad \theta_1=3.6 .
\end{equation}

[Defn def:Hlambda of arXiv:2411.03482, 'Ergodicity of 2D singular stochastic Navier--Stokes equations'] For any $\lambda > 0$, set $\mathcal{H}_{\lambda,i} = \Delta_{i + \log^{+}_{2}(\lambda)}$ and define the projections 
	\begin{equs}
		\mathcal{H}_{\lambda}: \mathcal{S}'(\mathbf{T}^2; \mathbf{R}^2) &\rightarrow \mathcal{S}'(\mathbf{T}^2; \mathbf{R}^2)\;, &\quad \mathcal{L}_{\lambda}: \mathcal{S}'(\mathbf{T}^2; \mathbf{R}^2) &\rightarrow \mathcal{S}(\mathbf{T}^2; \mathbf{R}^2)\;,\\
		f & \mapsto  \sum_{i \geq 0} \mathcal{H}_{\lambda,i} f \;, & f &\mapsto f - \mathcal{H}_{\lambda} f\;.
	\end{equs}
	We write 
	\begin{equ}
		\mathcal{P}_{\lambda, K} = \mathbf{1}_{\lambda \le K} (\mathcal{H}_\lambda - \mathcal{H}_K)
	\end{equ}
	to denote the frequency part between $\lambda$ and $K$.

[Lemma lemma-5.8 of arXiv:2412.08964, 'Phase transition and critical behavior in hierarchical\\integer-valued Gaussian and Coulom'] For each~$\alpha_0\in(0,\ffrac12)$ there exists~$\tilde\epsilon>0$ such that 
\begin{equation}

\sum_{j\ge1}\Gamma^\star_j(0) t_\star^{-j}=1
\end{equation}
holds true for all~$\beta>\beta_\text{\rm c}$ with~$1/\beta>1/\beta_\text{\rm c}-\tilde\epsilon$ and all~$\alpha\in[0,\alpha_0]$. Moreover, for such~$\alpha$ and~$\beta$ we have $t_\star\ge1$ with $t_\star>1$ when~$\alpha\ne0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma-1.5 of arXiv:2412.08964, 'Phase transition and critical behavior in hierarchical\\integer-valued Gaussian and Coulom'] Suppose $\boldsymbol\lambda\in\Sigma'$ and~$A\in(0,1)$ are such that $\sup_{q\ge0}\lambda(q+1)/\lambda(q)\le A$. For all $r\ge1$ and~$q_1,\dots,q_r\ge0$ we then have
    \begin{equation}

        \sum_{\begin{subarray}{c}
\ell_1,\dots,\ell_r\in\mathbb Z\\ \forall i\le r\colon |\ell_i|\ge q_i
\end{subarray}}
\prod_{i=1}^r \lambda(\ell_i) \le \Bigl(\frac{2}{1-A}\Bigr)^r\prod_{\begin{subarray}{c}
i=1,\dots,r\\ q_i\ge1
\end{subarray}
}\bigl[\lambda(1)A^{q_i-1}\bigr],
    \end{equation}
with the product on the right no larger than $A^{q_1+\dots+q_r}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 (Finite-dimensional spectral-growth theorem) of arXiv:2607.26377, '\textbf{Entire Logarithmic Signatures\\ of Bounded-Variation Paths in Finite Dimensions}'] Let $q\geq1$ and let $A:\C\to M_q(\C)$ be entire, with $A(0)=0$, and suppose
\begin{equation}
\norm{\e^{A(z)}}\leq C\e^{\tau\abs{z}}
\qquad (z\in\C)
\end{equation}
for constants $C\geq1$ and $\tau\geq0$, where $\norm{\cdot}$ is an operator norm. Then $z\mapsto\sigma_k(A(z))$ is a polynomial of degree at most $k$ for $1\leq k\leq q$.

If, in addition, $A(z)=zH+O(z^2)$ as $z\to0$ for some $H\in M_q(\C)$, then
\begin{equation}
\det(\zeta I-A(z))=\det(\zeta I-zH)
\end{equation}
for all $z,\zeta\in\C$. Consequently,
\begin{equation}
\tr(A(z)^p)=z^p\tr(H^p)
\qquad (p\geq1).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 5 of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Let $W$ be an $N\times N$ GUE matrix. For any $n_1,n_2\in\N\cup\{0\}$ and multi-indices $\bm{k}\in\N^{n_1},\bm{l}\in\N^{n_2}$ it holds that    
\begin{equation}
\E(\bm{k},\bm{l}):=\E \left[\eta^{|\bm{k}|+|\bm{l}|}\Delta(\bm{k}) \overline{\Delta(\bm{l})}\right] = \Phi_0(\bm{k},\bm{l}) + \mathcal{O}(\eta),

\end{equation}
uniformly in $z\in \mathcal{D}$. Here $\Phi_0$ is an explicit function of $\bm{k}$ and $\bm{l}$ given later in \eqref{eq:Phi_0_expl} which does not depend on $N$ and $z$. Similarly, the implicit constant in $\mathcal{O}(\eta)$ does not depend on $N$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem P-comm-two-param of arXiv:2609.01300, 'Virasoro Constraints for Orbifold Curves'] \begin{equation}
  [P(x),\widehat {\mathcal{A}}(b,y)]
