[Theorem 8 of arXiv:2506.17109, 'Limit theorems under nonlinear expectations dominated by sublinear expectations'] Let a nonlinear expectation $\mathbb{\tilde{E}}[\cdot]$ be
dominated by a sublinear expectation $\mathbb{\hat{E}}[\cdot]$ on
$(\Omega,\mathcal{H})$, and let $\{(X_{n,i},Y_{n,i}):n\in \mathbb{N}$,
$i=1$,$\ldots$,$n\}$ be a sequence of $2d$-dimensional random vectors such
that $(X_{n,i},Y_{n,i})\overset{d}{=}(X_{n,1},Y_{n,1})$ and $(X_{n,i}
,Y_{n,i})$ is independent of $(X_{n,1}$,$\ldots$,$X_{n,i-1}$,$Y_{n,1}$
,$\ldots$,$Y_{n,i-1})$ for $n\in \mathbb{N}$, $i=2$,$\ldots$,$n$ under
$\mathbb{\tilde{E}}[\cdot]$ and $\mathbb{\hat{E}}[\cdot]$ respectively.
Suppose that
\begin{equation}
\mathbb{\hat{E}}[X_{n,1}]=\mathbb{\hat{E}}[-X_{n,1}]=0\text{ for }
n\in \mathbb{N},\text{ }\lim_{N\rightarrow \infty}\sup_{n\geq1}\mathbb{\hat{E}
}\left[  (n|X_{n,1}|^{2}-N)^{+}+(n|Y_{n,1}|-N)^{+}\right]  =0, 
\end{equation}
and for each given $(A,p)\in \mathbb{S}_{d}\times \mathbb{R}^{d}$,
\begin{equation}
\tilde{G}(A,p):=\lim_{n\rightarrow \infty}n\mathbb{\tilde{E}}\left[  \frac
{1}{2}\langle AX_{n,1},X_{n,1}\rangle+\langle p,Y_{n,1}\rangle \right]  \text{
exists,} 
\end{equation}
where $\mathbb{S}_{d}$ denotes the space of $d\times d$ symmetric matrices.
Then for each $\phi \in C_{b.Lip}(\mathbb{R}^{2d})$, we have
\begin{equation}
\lim_{n\rightarrow \infty}\mathbb{\tilde{E}}\left[  \phi \left(  \sum_{i=1}
^{n}X_{n,i},\sum_{i=1}^{n}Y_{n,i}\right)  \right]  =u^{\phi}(1,0,0),

\end{equation}
where $u^{\phi}$ is the unique viscosity solution of the following PDE:
\begin{equation}
\partial_{t}u-\tilde{G}(D_{x}^{2}u,D_{y}u)=0\text{, }u(0,x,y)=\phi(x,y).

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma1 of arXiv:2412.06086, 'Zeros of conditional Gaussian analytic functions, random sub-unitary matrices and q-series'] $F(x,t;q)$ is the unique solution of
    \begin{align}
        xF(x,t;q)=e^{(1-q)t}\frac{\partial}{\partial t}F(x,qt;q)

    \end{align}
    that is regular at $x=0$ and satisfies $F(0,t;q)=1$.

[Proposition Useful proposition of arXiv:2607.18531, 'Doubly reflected BSDEs driven by Inhomogeneous simple Lévy processes: Applications to gene'] Assume given two $\mathbb{F}$-stopping times $\tau$, $\sigma$ such that $\tau \in \mathcal{T}_0^T$ and $\sigma \in \mathcal{T}_{\tau}^T$. Then, for any $\beta >2$, there exists a constant $\mathfrak{C}_{\beta}>0$ such that,
	\begin{equation*}
		\begin{split}
			&\mathbb{E}^{\mathcal{F}_\tau} \left[ \sup_{\tau \leq t \leq \sigma} e^{\beta A_t} \left| \overline{Y}_t \right|^2  \right]+ \mathbb{E}^{\mathcal{F}_\tau}\left[\int_\tau^\sigma e^{\beta A_s} \left| \overline{Y}_s \right|^2 dA_s \right]\\
			&\qquad+\mathbb{E}^{\mathcal{F}_\tau}\left[\int_\tau^\sigma e^{\beta A_s}  \left|\overline{Z}_s \right|^2 ds \right]+\mathbb{E}^{\mathcal{F}_\tau}\left[\int_\tau^\sigma e^{\beta A_s}   \|\overline{V}_{s}\|^2_\lambda ds \right] \\
			&  \leq \mathfrak{C}_{\beta}\Biggl\{ \mathbb{E}^{\mathcal{F}_\tau}\left[e^{\beta A_\sigma} \left| \overline{Y}_{\sigma} \right|^2\right]+\mathbb{E}^{\mathcal{F}_\tau}\left[\int_{\tau}^\sigma e^{\beta A_s} \left|\dfrac{ \bar{f}(s,Y^{\prime}_s,Z^{\prime}_s,V'_s)}{\alpha_s}\right|^2 ds \right]\\
			&\qquad +\mathbb{E}^{\mathcal{F}_\tau}\left[\int_{\tau}^{\sigma}e^{\beta A_s}\left\{ \bar{L}_{s-}^{+}dK^{+}_s+\bar{L}_{s-}^{-} dK^{\prime,+}_s \right\}\right] 
			+\mathbb{E}^{\mathcal{F}_\tau}\left[\int_{\tau}^{\sigma}e^{\beta A_s}\left\{\bar{U}_{s-}^{-}dK^{-}_s+\bar{U}_{s-}^{+}dK^{\prime,-}_s \right\}\right] \Biggr\}.
		\end{split}
	\end{equation*}

[Lemma 7 of arXiv:2506.18313, 'A stochastic model for the diffusion of competing opinions with trend-following, oppositio'] Assume that $(\xi_n)$ satisfies, for some integer $m\ge 1$ and for some real number $h > 2m$, that
\begin{equation}

    \displaystyle\sup_{n\ge 0}\dE\left[\vert\xi_{n+1}\vert^h\vert\mathcal{F}_{n}\right] < \infty \ \  \text{ a.s. }
\end{equation}
If in addition the explosion coefficient $f_n=\frac{v_{n}-v_{n-1}}{v_{n}}$ tends almost surely to zero, then
\begin{equation}
    \displaystyle\lim_{n\to\infty} \frac{1}{\log v_n}\sum_{k=1}^n f_k \left( \frac{Z_k^2}{v_{k-1}} \right)^m = \frac{\sigma^{2m} (2m)!}{2^m m!} \ \  \text{ a.s. }
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop Green_metric_upper_tail_strong of arXiv:2411.04988, '{\bf A relation between isoperimetry and total variation decay with applications to graphs'] Let $G=(V,E)$ be a locally finite graph with degrees bounded by $M\geq 2$ and let $d$ be a metric on $V$. There exists a universal positive constant $c$ such that
\[\mathbf{P}_x\left(\max_{0\leq m \leq n} d(X_0,X_m) \geq \lambda \sup_y \max_{0\leq m \leq n} \mathbf{E}_y \left[d(X_0,X_m)\right]  \right) \leq \exp\left[1-\frac{c \lambda}{M^2\log M}\right]\]
for every $x\in V$,  $\lambda \geq 1$, and integer $n\geq 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary c:purejumppareto of arXiv:2604.03979, 'Stationary Distributions in Monotone Markov Models: Theory and Applications'] Let $h \equiv x_0$, $\nu = \delta_0$, and $\mu =
    \mathrm{Exp}(\theta)$ for some $\theta > 0$. In this setting, for the income
    level $Y = e^X$, the tail of the unique stationary distribution is Pareto:
    for $y > y_0 \coloneq e^{x_0}$,

    \begin{equation}
        \mathbb P(Y > y)
        = q \left(\frac{y}{y_0}\right)^{-\alpha}
        \quad \text{with} \quad
        \alpha \coloneq \frac{\lambda_2 \theta}{\lambda_1 + \lambda_2}.
    \end{equation}

[Lemma lem:wp:marginalSDE of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Suppose $(U, W)$ satisfy Assumption (as:results:lyapunov of the paper) and $(\mu, \gamma, \mathbf{X})$ is a linear growth solution to $\kappa$-MLFE{} on $[0, T]$ with potentials $(U, W)$  and initial condition $\lambda \in \mathcal{Q}_{\kappa, d}$. Then for all $t \in [0, T]$, the edge time marginal $\bar{\mu}_t$ satisfies $\bar{\mu}_t = \mathcal{L}(\bar{X}_0(t), \bar{X}_1(t))$, where $(\bar{X}_0, \bar{X}_1)$ solve the following SDE with initial condition $\bar{\lambda}$:
        \begin{equation}
        \begin{aligned}
            d{\bar{X}}_0(t) &= \gamma(t, \bar{X}_0(t), \bar{X}_1(t)) dt + \sqrt{2}d\tilde{B}_0(t), \\
            d{\bar{X}}_1(t) &= \gamma(t, \bar{X}_1(t), \bar{X}_0(t)) dt + \sqrt{2}d\tilde{B}_1(t), 
                    \end{aligned}

    \end{equation}
    where $\tilde{B}_0, \tilde{B}_1$ are independent $d$-dimensional Brownian motions. Moreover, we have
    \begin{equation*}
    \int_0^T \int_{\ensuremath{\mathbb{R}}^d \times \ensuremath{\mathbb{R}}^d} \frac{|\nabla_{(x_0, x_1)} \bar{\mu}_t(x_0, x_1)|^2}{\bar{\mu}_t(x_0, x_1)} dx_0 dx_1 dt < \infty.
\end{equation*}

