[Lemma 22 (resolvent regularity) of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] \label[lemma]{lem:resolvent-regularity}
For every $h > 0$ and $f\in L^{\infty}([0,\infty))$,
$v = (I - h\mathcal{L}_1)^{-1} f$
satisfies $\|v\|_\infty \le \|f\|_\infty$ and $v\in C^2((0,\infty))$.  For
$\delta\in(1,2)$, $v$ has a boundary cusp of order $x^{2-\delta}$, and,  as $x\downarrow 0$,
\begin{equation}
  v(x)-v(0)=c_v\,x^{2-\delta}+o(x^{2-\delta}),\qquad
  v'(x)=c_v(2-\delta)\,x^{1-\delta}+o(x^{1-\delta}),
\end{equation}
with $c_v$ generically nonzero. Note that $v$ is in general \emph{not} differentiable
at $0$ in the ordinary sense ($v'(0^+)=+\infty$). The
\emph{scale} derivative $dv/ds$ is finite at the boundary, and
\begin{equation}
  \frac{dv}{ds}(0^+)=\tfrac{\alpha}{\mu}\bigl(v(0)-f(0)\bigr)
\end{equation}
 when $f$ is continuous at $0$.

[Cor 36 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $ \gamma \in [1, \; 2]$, $\lambda \in (0, 1)$, $0 \leq s \leq t \leq T$ and $\omega = \min \{\gamma, \; 3/2\}$. Assume that
    \begin{equation} 
    \exists C >0, \; \forall n \in \mathbb{N}_+, \quad  \Theta(n) K_n \leq n^{\omega}.   
    \end{equation}
    Then there exists some $\delta_1 \in (0, \;1]$ and some $f: \mathbb{N}_+ \mapsto \mathbb{R}$ satisfying $\lim_{n \rightarrow \infty} f(n)=0$, such that
	\begin{align*}
		 \mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{ & \frac{\Theta(n) K_n}{\sqrt{n}} \int_s^t \dd r \sum_x \sum_{y=x+1}^{\infty} [  H ( \tfrac{y - r v_n }{n}  ) - H ( \tfrac{x - r v_n }{n}  )  ] a(y-x)   \bar{\xi} _x^{\alpha}( \eta_r^n ) \bar{\xi} _y^{\beta}( \eta_r^n ) \\
		- & \frac{\Theta(n) K_n}{n \sqrt{n} } \sum_{z=1}^{L_n-1}  za(z) \int_s^t \dd r \sum_{x}   \nabla H ( \tfrac{ \lfloor x - r v_n \rfloor }{n}  )   \Psi_{x,L_n}^{\alpha,\beta}(\eta_r^n)  \Bigg\}^{2} \Bigg] \leq \widehat{C} (t-s)^{1 + \delta_1} f(n), 
	\end{align*}
for every $n \in \mathbb{N}_+$, where $L_n:=n^{1 - \lambda}$. Furthermore, if $H \in C_c^2(\mathbb{R})$, the role of $\widehat{C}$ is fulfilled by some constant $C(H)$ satisfying \eqref{Cinvshift}.

[Theorem 43 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Let $0<\gamma\le1$, let $A\in C(\Delta_T^2;B_\alpha)$, and assume that $\hdd A\in Z\hC^{\gamma}(\Delta_T^3;B_\alpha)$ belongs to the admissible selection domain of the chosen rule $\mathsf s$.  Define a path $I^{\mathsf s}_{\gamma,\alpha}(A)_t:=\mathcal J^{\mathsf s}_{\gamma,\alpha}(A)_{t0}$. Then
\begin{equation}

\hdd I^{\mathsf s}_{\gamma,\alpha}(A)
=
\mathcal J^{\mathsf s}_{\gamma,\alpha}(A).
\end{equation}
Equivalently,
\begin{equation*}
(\hdd I^{\mathsf s}_{\gamma,\alpha}(A))_{ts}=A_{ts}-\bigl(\hat\Lambda^{\mathsf s}_{S,\gamma,\alpha}(\hdd A)\bigr)_{ts}.
\end{equation*}
The path is the unique path satisfying \eqref{eq:convolution-primitive-identity} and $I^{\mathsf s}_{\gamma,\alpha}(A)_0=0$.

[Lemma lem:end-pf-d-regular of arXiv:2411.12076, 'Explicit solutions of the SI and Bass models on sparse Erd\H{o}s-R\'enyi and regular netwo'] For any $j \in \cal M$, 
	\begin{equation}

		\lim_{M \to \infty} \mathbb{E}_{{\cal G}_{M,d}^{\rm regular}} \left[  \frac{\prod_{i=1}^d [S^{k_i,p_j}_j]}{([S^{p_j}_j])^{d-1}}  \right]
		=
		\left(\frac{1}{e^{-pt}(1-I^0)}\right)^{d-1}
		\prod_{i=1}^d 
		\lim_{M \to \infty} 
		\mathbb{E}_{{\cal G}_{M,d}^{\rm regular}} \left[ [S^{k_i,p_j}_{j}]  \right].
	\end{equation}

