[Lemma 20 of arXiv:2510.23130, 'Hidden regular variation for stochastic recursions with diagonal matrices\ \thanks{E.D. wa'] Under the assumptions of Theorem \ref{thm:main:blocks}, let $n_0 = \lceil \log t \slash \rho \rceil $. 

	For every $\eps $ there is $t_0=t_0(\eps )$ such that for every $\ell \leq \sqrt{n_0}$ and $n=n_0+\ell$ we have
	\begin{equation}
		\P \left ( n_0\rho <S _{n,1}< n_0 \rho +1, n_0+\log \eps  <S _{n,2}< n_0 \rho +\log \eps +1\right )\geq c \eps ^{-\xi^* _2} t^{-\xi^*_1-\xi^*_2}n_0^{-1}.
	\end{equation}
	and
	\begin{equation}
		\P \left ( n_0\rho <S _{n,1}< n_0 \rho +1, n_0\rho +\log \eps <S _{n,2}< n_0 \rho +\log \eps +1\right )\leq c' \eps ^{-\xi^* _2} t^{-\xi^*_1-\xi^*_2}n_0^{-1}.
	\end{equation}

