[Thm 2. thm: convergence in the vague topology of arXiv:2412.08236, 'Aging and sub-aging for Bouchaud trap models on resistance metric spaces'] [{[Noda_pre_Metrization]}] 
  The function $d_{V}^{S, \rho_{S}}$ is a complete, separable metric on $\mathcal{M}(S)$.
  Let $\mu, \mu_{1}, \mu_{2}, \ldots$ be 
  Radon measures on $S$.
  Then these conditions are equivalent:
  \begin{enumerate}
    \item $\mu_{n}$ converges to $\mu$ with respect to $d_{V}^{S, \rho_{S}}$;
    \item $\mu_{n}^{(r)}$ converges weakly to $\mu^{(r)}$ for all but countably many $r>0$;
    \item $\mu_{n}$ converges vaguely to $\mu$, that is, for all continuous functions $f : S \to \mathbb{R}$ with compact support,
      it holds that 
      \begin{equation}
        \lim_{n \to \infty} \int_{S} f(x)\, \mu_{n}(dx) = \int_{S} f(x)\, \mu(dx).
      \end{equation}
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 21 of arXiv:2607.18104, '2607.18104'] For $p>0$, let $\mathbb{T}^{(p)}$ denote the $1$-dimensional torus of length $p$, and recall that
 \begin{equation*}
     (\mathbb{T}^{(p)} \times \R)^{2}_{\uparrow} = \left\{ (x,s;y,t) \in \big(\mathbb{T}^{(p)} \times \R\big)^2 \colon s<t \right\} . 
 \end{equation*}
Then we define the $\boldsymbol{p}$\textbf{-periodic directed landscape} as
\begin{equation*}
   \Lpp(x,s;y,t) := p^{-1/2}\Lp_1(px,p^{3/2}s;py,tp^{3/2})
\end{equation*} for all $(x,s;y,t) \in (\mathbb{T}^{(p)} \times \R)^{2}_{\uparrow}$, where $\Lp_1$ is a $1$-periodic directed landscape on  $(\mathbb{T} \times \R)^2_{\uparrow}$.

[Lem 11 of arXiv:2609.00598, 'Supercritical mean--field limit for magnetized Hamiltonian dynamics'] Let $f_{\varepsilon}\in W^{1,\infty}([0,T]\times \mathbb{T}^{2}\times \mathbb{R}^{2})$ be a non-negative solution, with finite second velocity moment and sufficient decay as \(\lvert\xi\rvert\to\infty\), to  \eqref{magnetized vp with quasineutral scaling}, 
and let the total energy be defined by 
\begin{align*}
\mathcal{F}_{\varepsilon}(t):= \frac{1}{2}\int_{\mathbb{T}^{2}\times \mathbb{R}^{2}}\left\vert \xi\right\vert^{2}f_{\varepsilon}(t,x,\xi)\ \dd x\dd \xi
+\frac{\varepsilon}{2}\int_{\mathbb{T}^{2}}\left\vert \nabla_{x} 
\Phi_{\varepsilon}\right\vert^{2}(t,x)\ \dd x.    
\end{align*}
Then
\begin{align*}
\frac{\dd}{\dd t}\mathcal{\mathcal{F}}_{\varepsilon}(t)=0 
\qquad \mbox{for all}\ t\in [0,T],   
\end{align*}
that is,
\begin{align*}
\mathcal{F}_{\varepsilon}(t)=\mathcal{F}_{\varepsilon}(0)
\qquad \mbox{for all}\ t\in [0,T].     
\end{align*}

