body:
[Theorem thm:main of arXiv:2412.04579, 'Solvable Families of Random Block Tridiagonal Matrices'] For $\beta =1$ and $2$, the symmetrized joint eigenvalue density of $\mathtt{H}_{n,\beta}(r,s)$ can be computed explicitly in the following cases:
 \begin{align}
 \frac{1}{Z_{n, \beta, r, 2}} |\Delta({\lambda})|^{\beta}
 \left( \sum_{(\mathcal{A}_1,\dots,\mathcal{A}_r)\in {\mathcal P}_{r,n}} \prod_{j=1}^r \Delta(\mathcal{A}_j)^2 \right) {\rm e}^{- \frac{\beta}{4}\sum_{i=1}^{rn} \lambda_i^2} \qquad
 \mbox{for}\ r \ge 2, \ \beta s=2, 
 \end{align}
and
 \begin{align}

 \frac{2^n}{Z_{n, \beta, 2, \beta s}} \Delta({\lambda})^{\beta+\frac{\beta s}{2}} \left|\operatorname{Pf} \left(\frac{{\bf{1}}_{i \neq j}}{\lambda_i -\lambda_j} \right)\right|^{\frac{\beta s}{2}} {\rm e}^{- \frac{\beta}{4}\sum_{i=1}^{2n}\lambda_i^2} \qquad \mbox{for} \ r = 2, \ \beta s = 2,4.
 \end{align}
It further holds that
\begin{align*}
Z_{n, \beta, r, \beta s} ={}&(n r)! (2\pi)^{\frac{nr}{2}}
\left(\frac{\beta}{2}\right)^{a_{n,\beta,r,s}} \Gamma\left(\frac{\beta}{2}\right)^{-nr} \prod_{k=1}^{nr} \Gamma\left(\frac{\beta}{2}\left(k+s \left\lceil\frac{k}{r}\right\rceil\right)\right)\\
& \times \begin{cases}
 1, &\beta s=2,\\
 \left(\dfrac{\beta}{12}\right)^n, &\beta s=4,
\end{cases}
\end{align*}
with $a_{n,\beta,r,s}=
-\frac{\beta}{4} n r (n (r+s)+s)+\bigl(\frac{\beta}{4}-\frac{1}{2}\bigr){nr}$
for all $n$, $\beta = 1$ and $2$, and combinations of $r$ and $s$ in (equation density1 of the paper) and (equation density2 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Ltran of arXiv:2510.22701, 'Gaussian fluctuations in Mean Field Stable matchings'] Suppose that $\rho$ satisfies the conditions stipulated in Theorem (Tclt2 of the paper).  Then, under the quantile coupling, as $n\to\infty$,
    \begin{align}
        &\frac{\operatorname{\mathbb E} |C_{n,n}^{\scriptscriptstyle\rm{Wei}} - C_{n,n}^\rho| } {n^{1/2-1/d}} \longrightarrow 0 ;\\
        &\frac{\mathrm{Var}\bclr{C_{n,n}^{\scriptscriptstyle\rm{Wei}}-C_{n,n}^\rho}}{n^{1-2/d}}\longrightarrow 0 ;\\
        &\frac{\big|\mathrm{Var}\bclr{C_{n,n}^{\scriptscriptstyle\rm{Wei}}}-\mathrm{Var}\bclr{C_{n,n}^\rho}\big|}{n^{1-2/d}}\longrightarrow 0.
    \end{align}

