[Lemma ratio-tilt of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Let $A$ be any Borel subset of $R^{2}$. Then 
\begin{equation}
\frac{E^{P_{i}}[X_{1}X_{2}\,1_{\{(X_{1},X_{2})\in A\}}]}{
E^{P_{i}}[X_{1}X_{2}]}=E^{\tilde{P}_{i}}[1_{\{(X_{1},X_{2})\in A\}}],\qquad
i=1,2.  
\end{equation}
In particular, for the upper sets 
\begin{equation}
A_{s_{1},s_{2}}=\{(x_{1},x_{2})\colon x_{1}\geq s_{1},\ x_{2}\geq s_{2}\}

\end{equation}
we have 
\begin{equation}
\frac{E^{F_{C_{i}}}\![X_{1}X_{2}\,1_{\{X_{1}\geq s_{1},X_{2}\geq s_{2}\}}]}{
E^{F_{C_{i}}}[X_{1}X_{2}]}=E^{\tilde{P}
_{i}}[1_{A_{s_{1},s_{2}}}(X_{1},X_{2})],\qquad i=1,2.  
\end{equation}

