body:
[Lemma 79 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Assume that   $(\Omega, \mathscr{F}, \mathbb{F}, \mathbb{P})$ is a filtered probability space with a right continuous filtration   $\mathbb{F}=(\mathscr{F}_t)_{t \in [0,T]}$
such that on this probability space two i.i.d. copies of  $\ell^2$-cylindrical $\mathbb{F}$-adapted  Wiener processes are defined. 
Suppose also that $(\mO,\mathcal{E})$ is a measurable space and $\tilde{\kappa}$ is a non-negative measure on it such that the Hilbert space  $\rK\coloneqq L^2(\mO,\mathcal{E},\tilde{\kappa})$ is separable. 
 Assume that 
\[\sigma: [0,\infty) \times \Omega \times \mO \to \rU^\prime\] is  
 $\mathscr{P}(\mathbb{F}) \times \mathcal{E}/\mathscr{B}(\rU^\prime)$-measurable function.
Assume that 
$M=(M_t: t \in [0,T])$ is  a $\rU^\prime$-valued continuous local martingale  such that for each $u \in \rU$,
  \begin{equation}
    \dualitybig{M_t}{u}{\rU}{\rU^\prime}{2} - \int_0^t \int_\mO \dualitybig{\sigma_s(x)}{u}{\rU}{\rU^\prime}{2} \, \tilde{\kappa} (\d x)\, \d s \in \mathcal{M}_{\loc}^c(\mathbb{D},\mathbb{P}).
 \end{equation}
Then there exists a  $\rK$-cylindrical Wiener process $W$  such that
for every $t \in [0,T]$, 
  \begin{equation}
    M_t= \int_0^t  \sigma_s \d W_s    \mbox{ in } \rU^\prime \mbox{ $\mathbb{P}$-a.s.}
  \end{equation}
where we  used the notation introduced in \eqref{eqn-M_t=int_0^t xi_s  d W_s}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 7 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Consider the trilinear form $b_1$ defined by
   \begin{equation}
b_1: \StokesV \times \zero{H}{2}(\domO) \times W^{1,4}(\domO) \ni 
   (\bu,\phi,\psi)\mapsto  \sum_{i=1}^d \int_{\domO} \nabla (\bu_i(x) \partial_i \phi(x)) \cdot \nabla \psi(x)\,\d x \in \mathbb{R}.
  \end{equation}
Since $H^1 \embed L^4$ by the Sobolev embedding Theorem, the Lebesgue integral on the RHS of 
\eqref{eqn-b_1-trilinear-form-1} exists. Then, by the H\"older inequality, we deduce that there exists a  positive constant $C$ such that the following estimates hold for all $\bu \in \StokesV,\,\phi \in H^2(\domO)$, and $\psi \in W^{1,4}(\domO)$:
\begin{equation}
\begin{aligned}
&\lvert b_1(\bu,\phi,\psi) \rvert
\leq \lvert \nabla \bu \rvert_{\mathbb{L}^2} \Vert \nabla \phi \Vert_{\mathbb{L}^4} \Vert \nabla \psi \Vert_{\mathbb{L}^4} + \Vert \bu \Vert_{\mathbb{L}^4} \left(\sum_{i,j=1}^d \lvert \partial_i(\partial_j \phi) \rvert_{L^2}^2 \right)^{1/2} \Vert \nabla \psi \Vert_{\mathbb{L}^4}
\\
&\leq \lvert \nabla \bu \rvert_{\mathbb{L}^2} \Vert \nabla \phi \Vert_{\mathbb{L}^4} \Vert \nabla \psi \Vert_{\mathbb{L}^4} + \Vert \bu \Vert_{\mathbb{L}^4} \Vert \phi \Vert_{H^2} \Vert \nabla \psi \Vert_{\mathbb{L}^4}
\leq C \Vert \bu \Vert_{\StokesV} \Vert \phi \Vert_{H^2} \Vert \psi \Vert_{W^{1,4}}. 
\end{aligned}
\end{equation}

