[Theorem thm:upper of arXiv:2608.23638, 'Replicable Conformal Prediction'] Let $F$ be continuous, let Assumption~(ass:margin of the paper) hold, let $k=\lceil(1-\alpha)(n+1)\rceil\le n$, and let $n\ge4/(f_{\min}\Delta)$. Two analysts run \textsc{ReCal}{} with shared $(\beta,u)$, $u\sim\mathrm{Unif}[0,\beta)$, on independent samples of size $n$. Then:
\textbf{(i)} $\displaystyle\mathbb{P}[\tau\neq\tau']\le\frac{B_n}{f_{\min}\beta}+4e^{-nf_{\min}^{2}\Delta^{2}/2}$, where $B_n:=\sqrt{2\alpha(1-\alpha)/n}+\sqrt2/n$;
\textbf{(ii)} for every fixed offset $u$, marginal coverage is $\ge k/(n+1)\ge1-\alpha$, with no margin condition; and for $\delta$ with $e_n(\delta):=\sqrt{\log(2/\delta)/(2n)}+2/n\le f_{\min}(\Delta-\beta)$, with probability $\ge1-\delta$ over the sample and then \emph{simultaneously for every} $u\in[0,\beta)$, $1-\alpha-e_n(\delta)\le F(\tau)\le1-\alpha+e_n(\delta)+f_{\max}\beta$;
\textbf{(iii)} on $\{\tau=\tau'\}$ the two deployed classifiers (same score) coincide at every test input. (Proof: Appendix~(app:upper of the paper).) (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm main2 of arXiv:2411.13926, 'Random walks on random walks:\\ non-perturbative results in high dimensions'] Consider the RWRW model  on $\mathbb{Z}^d$ with $\lambda \in [0,\infty)$. 
\begin{itemize}
\item[a)] (weak) annealed Functional Central Limit Theorem (waFCLT):\\
If $d\geq 5$ and there is an $\alpha \in \ensuremath{\mathbb{R}}^d$ such that the variance of $\alpha \cdot X_n$ diverges, then there is a slowly varying function  $h\colon [0,\infty) \rightarrow \ensuremath{\mathbb{R}}$ such that
\begin{equation}
\left( \frac{\alpha \cdot X_{\lfloor nt\rfloor}- \alpha \cdot v\lfloor nt\rfloor}{\sqrt{nh(n)}} \right)_{t \in [0,1]} \overset{P_{\ensuremath{\mathbb{P}}}}{\implies} (B_t)_{t \in [0,1]}
\end{equation}
where $\overset{P_{\ensuremath{\mathbb{P}}}}{\implies}$ denotes convergence in distribution under the annealed law $P_{\ensuremath{\mathbb{P}}}$ as $n\rightarrow \infty$ with respect to the Skorohod topology and  $(B_t)$  is a standard Brownian motion on $\ensuremath{\mathbb{R}}$.\\  
If, moreover, $d\geq 9$, then there is a $\sigma \in (0,\infty)$ such that $h(n)=\sigma$. 
\item[b)] annealed Functional Central Limit Theorem (aFCLT):\\
If $d\geq 9$ and $(X_t)$ is truly d-dimensional, then 
\begin{equation}
\left( \frac{ X_{\lfloor nt\rfloor}- v\lfloor nt\rfloor}{\sqrt{n}} \right)_{t \in [0,1]} \overset{P_{\ensuremath{\mathbb{P}}}}{\implies} (B_t^{\Sigma})_{t \in [0,1]}
\end{equation}
where $(B_t^{\Sigma})$ is a Brownian motion on $\ensuremath{\mathbb{R}}^d$ with covariance matrix $\Sigma>0$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 10 (Scaled barrier convergence) of arXiv:2609.03916, 'Halfspace Theorems for Anisotropic Minimal Surfaces and Perimeter Minimizers'] The scaled barriers satisfy
\begin{equation}
  \Phiop[b_t](x)=t^{-1}\Phiop[b](x/t)>0,
\end{equation}
and
\begin{equation}
  b_t\to0
  \quad\text{in }C^2_{\mathrm{loc}}(\R^2\setminus\{0\})
  \quad\text{as }t\downarrow0.
\end{equation}
For each fixed $t$, the height of $\operatorname{graph}b_t$ is proper and tends
to $-\infty$ along its end. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop tensor of arXiv:2602.17579, 'Non-equilibrium functional inequalities for finite Markov chains'] Let $d \geq 1$. For each $i\in \{1,\ldots,d\}$ let $\ensuremath{\mathbb{Z}}_i$ be a finite state space, $M_i$ be an irreducible  generator on $\ensuremath{\mathbb{Z}}_i$ and $\zeta_i\in \mathcal{P}_+(\ensuremath{\mathbb{Z}}_i)$. Define 
    \begin{equation*}
    \displaystyle
        \ensuremath{\mathbb{Z}} \coloneqq\prod_{i=1}^d \ensuremath{\mathbb{Z}}_i, \quad
        \zeta \coloneqq\zeta_1\otimes\ldots\otimes \zeta_d \in \mathcal{P}_+(\ensuremath{\mathbb{Z}}), \quad
        M \coloneqq\frac1d\sum_{i=1}^d \underbrace{I\otimes \ldots I}_{i-1} \otimes M_i \otimes \underbrace{I\otimes\ldots\otimes I}_{d-i} \in \ensuremath{\mathbb{R}}^{|\ensuremath{\mathbb{Z}}| \times |\ensuremath{\mathbb{Z}}|}.
    \end{equation*}
    Then, $M$ is an irreducible generator on $\ensuremath{\mathbb{Z}}$ and $\zeta$ satisfies the gPI and gLSI with constants 
    \begin{equation*}
        \alpha_{\gPI}(\zeta, M) =\frac1d \min_{1 \leq i \leq d} \alpha_{\gPI}(\zeta_i, M_i), \ \ \alpha_{\gLSI}(\zeta, M) =\frac1d \min_{1 \leq i \leq d}\alpha_{\gLSI} (\zeta_i, M_i).
    \end{equation*}

