body:
[Corollary cor:volume of arXiv:2602.19192, 'Bakry--\'Emery Curvature of the Fractional Laplacian\\ via Fractional Brownian Covariance'] The $\Gamma_2$-ellipsoid
$E_2 = \{f : \Gamma_2(f,f) \leq 1\}$ and the $\Gamma$-ellipsoid
$E_1 = \{f : \Gamma(f,f) \leq 1\}$ on $\mathcal{T}_N^+$ satisfy
\begin{equation}
  \frac{\mathrm{vol}(E_1)}{\mathrm{vol}(E_2)}
  = (\det M)^{1/2} = \bigl((2N-1)!!\bigr)^{1/2}
  = \bigl(\mathbb{E}[X^{2N}]\bigr)^{1/2},
\end{equation}
where $X \sim \mathcal{N}(0,1)$.
At $\gamma = 1$, the $\Gamma_2$-form is $(2N-1)!!^{1/2}$ times
more concentrating than the $\Gamma$-form in $N$-dimensional volume.

[Lemma xnuni of arXiv:2411.05204, '\Large\bf Sample Path Properties of the Fractional Wiener--Weierstrass Bridge'] If $H<K$ we define $ X ^{(n)}$ as in ((Xn of the paper)), and $ \varepsilon _n=\alpha^n,\ N_n=nH,\ \delta_n=b^{-nH}$.\footnote{Without loss of generality, we assume $N_n$ is always an integer, by using instead $\lfloor nH\rfloor$ or $\lceil nH\rceil$. } Then we have
\begin{align}
\sum_{n=1}^\infty{\mathbb P}\Bigg(\sup_{\substack{t,s\in[0,1]\\ |t-s|< \varepsilon _n/\delta_n}}\big|X^{(N_n)}(t)-X^{(N_n)}(s)\big|\leq \frac{1}{L}\left(\frac{ \varepsilon _n}{\delta_n}\right)^{H}\sqrt{-\log ( \varepsilon _n/\delta_n)}\Bigg)<\infty.\end{align}

[Definition def:IVGFFwithpotentialV of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] Given an integer $L \in \ensuremath{\mathbb{N}}$ and an inverse temperature $\beta \geq 0$, we define the integer-valued height function with potential $V$ to be the probability distribution on the set $\Omega_{\Lambda_L}^\ensuremath{\mathbb{Z}}$ given by the identity

\begin{equation} 
    \mu_{\Lambda_L , \beta}^{\ensuremath{\mathbb{Z}}-V} (\left\{ \varphi \right\}) := \frac{1}{Z_{\Lambda_L,\beta}^{\ensuremath{\mathbb{Z}}-V}} \exp \left( - \sum_{x \sim y}  V \left( \frac{ \varphi(x) - \varphi(y)}{\sqrt{\beta}} \right)\right).
\end{equation}
We denote by $\mathrm{Var}_{L , \beta}^{\ensuremath{\mathbb{Z}}-V}$ the variance with respect to the measure $\mu_{L , \beta}^{\ensuremath{\mathbb{Z}}-V}$.

[Prop valoriHgamma of arXiv:2506.08202, 'Stochastic dissipative systems in Banach spaces driven by L\'evy noise'] Let $\delta\geq 0$. Assume that $\nu(H\setminus H_\delta)=0$, $m =0$,   and  
\begin{equation}
\int_H{\left|z\right|}_\delta^2\nu(dz) = \int_{H_{\delta}}{\left|z\right|}_\delta^2\nu(dz) <+\infty. 
\end{equation}
Then the following statements hold.
\begin{enumerate}
\item $\{L(t)\}_{t\geq 0}$ is a Lévy process on $H_\delta$.
\item $\{L_A(t)\}$ is a mean square continuous $H_{\gamma}$-valued stochastic process, for every $\gamma<1/2+\delta$,  namely for every $t_0\geq 0$ we have
\begin{equation}
\lim_{t\rightarrow t_0}\mathbb{E}\left[{\left\|L_A(t)-L_A(t_0)\right\|}_\gamma^2\right]=0,
\end{equation}
in the case $t_0=0$ we consider only the right limit in (equation Mean-cont of the paper).
\end{enumerate}

