[Corollary 3 of arXiv:2608.26618, 'A Unified Descriptive-Complexity Framework for Model Selection under Correlated Designs'] For every $\lambda \geq \lambda_{\rm sel}$, if the following conditions hold:
\begin{itemize}
    \item[(\romannumeral 1)]
    There exists a sufficiently large constant $c_1>1$ such that, for every
    $S\in\mathcal M_{\mathrm{sub}}$,
    \begin{equation}
    \mathrm{APP}(S)\ge
    c_1\Bigg(
    \Delta^-(S)\log n
    +\lambda\Bigl((s^*\log p)^{\frac{2}{\alpha}}-(s\log p)^{\frac{2}{\alpha}}\Bigr)
    +\log^{\frac{2}{\alpha}}\binom{s^*}{\Delta^-(S)}
    \Bigg).
    \end{equation}

    \item[(\romannumeral 2)]
    There exists a constant $\kappa>0$ such that
    $
    2B_S<u_S
    $ for all $S\in\mathcal M_w \text{ with } s>(1+\kappa)s^*.
    $
    Moreover, for every $S\in\mathcal M_w$ with $s\le (1+\kappa)s^*$,
\begin{equation}
\begin{aligned}
\mathrm{APP}(S)\ge{}&
\lambda\left\{
\log
\binom{s^*}{\Delta^-(S)}
\binom{p-s^*}{\Delta^+(S)}
\right\}^{\frac{2}{\alpha}}
+2(s^*-s)\log n
\\
&+2\lambda\left\{
(s^*\log p)^{\frac{2}{\alpha}}
-(s\log p)^{\frac{2}{\alpha}}
\right\}
+\log\log n
+8(r_S-\widetilde r_S).
\end{aligned}
\end{equation}
\end{itemize}
Then
\[
\Pr\!\left(
\min_{S\in\mathcal M_n,\;S\neq S^*}\mathrm{DCIC}(S)>\mathrm{DCIC}(S^*)
\right)\to 1
\qquad \text{as } n\to\infty.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 56 (Second-order singular group-dual transfer) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] Assume \eqref{eq:group-growth}, let
$D/4<\sigma\le D/2$, $c_x=\langle x\rangle^{-\sigma}$, and fix
$1\le r<\infty$.  With $\beta=D-2\sigma$, suppose
\begin{equation}

 a>\beta,\qquad b>\beta,\qquad
 a+b>\beta+\frac Dr.
\end{equation}
Then $T_{2,N}^{a,b}(c)$ converges, as $N\to\infty$, to a common random
operator $T_2^{a,b}(c)$ in
$L^p(\Omega;\Sch_r(\ell^2(\Gamma)))$ for every $1\le p<\infty$ and almost
surely in $\Sch_r$.  Define
\begin{equation}

 \eta_*:=
 \min\left\{
  \frac{4\sigma-D}{2},\,
  a-\beta,\,
  b-\beta,\,
  a+b-\beta-\frac Dr
 \right\}>0.
\end{equation}
For every $0<\eta<\eta_*$ and $1\le p<\infty$,
\begin{equation}

 \norm{T_{2,N}^{a,b}(c)-T_2^{a,b}(c)}
      _{L^p(\Omega;\Sch_r)}
 \le C_{\Gamma,D,\sigma,a,b,r,\eta}(p+r)N^{-\eta}.
\end{equation}
For a common realization and every $t\ge1$,
\begin{align}

 \Prob\!\left(
  \norm{T_{2,N}^{a,b}(c)-T_2^{a,b}(c)}_{\Sch_r}
  >\mathrm e\,C_{\Gamma,D,\sigma,a,b,r,\eta}
    (t+r)N^{-\eta}
 \right)
 \le\mathrm e^{-t}.
\end{align}
Moreover, for every $0<\eta<\eta_*$,
\begin{equation}

 \norm{T_{2,N}^{a,b}(c)-T_2^{a,b}(c)}_{\Sch_r}
 =O_\omega(N^{-\eta})
 \qquad\text{almost surely}.
\end{equation}

