[Lemma 32 (Concentration of the Stein witness map) of arXiv:2608.28827, 'Quantitative Target Convergence and Uniform-in-Time\\ Propagation of Chaos for Langevin-Re'] Under Assumptions~\ref{ass:core-target}, \ref{ass:ksd-kernel} and \ref{ass:concentration}, there are constants $c_{\mathrm{KSD}}>0$ and $1\le C_{\mathrm{KSD}}<\infty$ such that
\begin{equation}
    \int\exp\left(
      c_{\mathrm{KSD}}\sqrt N\,
      \KSD_\pi(\mu_X^N,\mu_t)
    \right)\,d\mu_t^{\otimes N}(X)
    \le C_{\mathrm{KSD}}
\end{equation}
uniformly in $N$ and $t$.

[Lemma Suf cond for admissible 1 of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] Let $g: \mathbb N\to \mathbb R_+$ be a given function. If there exists $\delta>0$ such that
     \begin{equation}
         \liminf_{k\to \infty}\frac{g(k+1)-g(k)}{(\ln k)^{1+\delta}}>0,
     \end{equation}
     then $\{g(k)\}_{k\geq 1}$ is $(\gamma,\delta)$-admissible for any $0<\gamma<1$. In particular, if there exists $\beta>0$ such that
     \begin{equation}
         \liminf_{k\to \infty}\frac{g(k+1)-g(k)}{k^{\beta}}>0,
     \end{equation}
     then $\{g(k)\}_{k\geq 1}$ is $(\gamma,\delta)$-admissible for any $0<\gamma<1$ and $\delta>0$.

