[Conjecture of arXiv:2512.19897, 'On the convoy of the ASEP speed process'] Conditionally on the event $U_0 = u$ with $x = \tfrac{1+u}{2}$, the size of the ASEP convoy is asymptotically a universal folded normal random variable. More specifically, we have
     \begin{equation}
    \frac{\# \mathcal{C}_0^{n,\left(q\right)}}{\sqrt{n}}
    \Big|_{ U_0 =u }\xrightarrow[n \to \infty]{d}
    \bigl|\mathcal{N}\left(0,2x\left(1-x\right)\right)\bigr|,
\end{equation} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Lemma lem:one-arm-fubini of arXiv:2607.18070, 'The Brownian loop-catcher'] For every nonnegative Borel functional \(g\) on loops surrounding \(z\),
\begin{equation*}
 \mathbb{E}\!\left[\int g(\ell)\,\mu_U^{c,z}(d\ell)\right]
 =\int g(\ell)F_\mathbb{D}^{-1,1}(\ell)\,\mu_\mathbb{D}^{c,z}(d\ell).
\end{equation*}

[Propo 10 of arXiv:2606.19925, 'Asymptotic properties for fully coupled delayed forward-backward stochastic differential e'] Assume that conditions $({\bf A1})$-$({\bf A3})$ are satisfied and the notation of \eqref{N1}. Then, the family $(X^{\varepsilon,t,x}(.) : 0 <\varepsilon< 1)$ of random variables of the solutions of the following perturbed delayed SDE 
\begin{eqnarray*}
X^{t,x,\varepsilon}(s)&=& x+\int^{s\vee t}_{t} b^{\varepsilon}(r,X_r^{t,x,\varepsilon})dr+\sqrt{\varepsilon}\int^{s\vee t}_t \sigma^{\varepsilon}(r,X_r^{t,x,\varepsilon})dW(r) 
\end{eqnarray*}
obey a large deviations principle in $C([t, T]; R^n)$, with the good rate function $I$ defined as
\begin{eqnarray*}
I_1(\phi)=
\left\{
\begin{array}{ll}
\displaystyle\inf\left\{\frac{1}{2}\int^T_t\|\varphi(s)\|^2ds,\;\; \phi'(s)=b(s,\phi(s))+\sigma(s,\phi(s))\varphi(s),\; s\in [t,T]\right\}&,\;\; \varphi\in L^2([t,T],\R^n)\\\\
+\infty	& otherwise.
\end{array}
\right.
\end{eqnarray*}
Moreover, the level sets of $I$ are compact and for every Borel subset $A$ of $C([t, T]; \R^n)$, we have
\begin{eqnarray*}
-\inf_{g\in }I(g)\leq \liminf_{\varepsilon\rightarrow 0}\varepsilon\log(\P (X^{t,x,\varepsilon}\in A))\leq-\inf_{g\in \overline{A} }I(g)
\end{eqnarray*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:three_term_relation of arXiv:2507.22011, 'Random Lozenge Waterfall:\\Dimensional Collapse of Gibbs Measures'] We have
	\begin{equation}

		\mathfrak{a}(x)\hspace{1pt}
		\mathcal{F}_n(x-\tfrac12)
		+
		\mathfrak{a}(x+\tfrac12)\hspace{1pt}
		\mathcal{F}_n(x+\tfrac12)
		=
		-q^n\hspace{1pt} \mathcal{F}_n(x),
		\qquad n,x\in \tfrac12 \mathbb{Z},\quad n\ge0,
	\end{equation}
	where $\mathfrak{a}$
	is given by
	\begin{equation*}
		\mathfrak{a}(x)\coloneqq
		\biggl[
			\frac{-\kappa^2 q^{2x-1}}
			{ (1-\kappa ^2 q^{2x})(1-\kappa ^2 q^{2x-1})}
		\biggr]^{\frac12},\qquad x\in \tfrac12 \mathbb{Z}.
	\end{equation*}

