[Lemma 18 of arXiv:2609.00245, 'Higher-order Gaussian bounds for maximally subelliptic boundary value problems'] \cite[Assumption \ref*{Form::Assumption::EstBdry::MaxSubOnSmoothing}\ref*{Form::Item::EstBdry::MaxSubOnSmoothing::InHkWOnCubegeqOneHalf},\ref*{Form::Item::EstBdry::MaxSubOnSmoothing::dtplusOplOnDIsFunction}]{StreetAPrioriEstimatesMaximallySubellipticQuadraticForms}
    hold. Namely,
    \(\forall U(t,x)\in \DSet\), 
    \begin{equation*}
        U\big|_{\R\times \Cubengeq{1/2}}\in \LtSpace*[\R][\HsVTwoSpace{\kappa}[\Cubengeq{1/2}][\C^M]],
    \end{equation*}
    where \(\HsVTwoSpace{\kappa}\) is defined in \eqref{Eqn::Result::DefineHsWSpace}.
    Moreover, \(\opLTwo U\big|_{\R\times \Cubengeq{1/2}}\), when taken in the sense of distributions,
    agrees with a function in \(\LtSpace*[\R \times \Cubengeq{1/2}][\C^M]\).

[Lemma lem:measurability-pattern of arXiv:2606.10973, 'Quasisymmetric rigidity of the Brownian sphere'] We may choose $b_1$ sufficiently small so that there exists a sufficiently small parameter $b_2 \in (0, b_1)$ for which, with probability strictly greater than $1/2$,
    \begin{equation*}
        \inf\{D_{\Phi_2}(x, y) : x \in B_{b_2}(u^-), \ y \in B_{b_2}(u^+)\} > \sup\{D_{\Phi_2}(x, y) : x \in B_{b_2}(v^-), \ y \in B_{b_2}(v^+)\}.
    \end{equation*}

[Lemma lem:symanti of arXiv:2505.12187, 'Speeding up quantum Markov processes through lifting'] Under (asspA of the paper), the following hold:
\begin{itemize}
    \item Both $\mathcal{L}_A$ and $\mathcal{L}_S$ admit $\sigma$ as an invariant state, i.e.,
    \begin{align*}
        \mathcal{L}_S^\dag(\sigma) = \mathcal{L}_A^\dag(\sigma) = 0\,,   
    \end{align*}
    and thus $\mathcal{L}_\gamma^\dag(\sigma) = 0$ for all $\gamma > 0$.
    \item $\mathcal{L}_S$ is the generator of a $\sigma$-KMS detailed balanced quantum Markov semigroup. 
    \item The fixed-point algebra $\mathcal{F}(\mathcal{L}_\gamma)$ is characterized by 
    \begin{align} 
        \mathcal{F}(\mathcal{L}_\gamma) = \ker(\mathcal{L}_\gamma) = \ker(\mathcal{L}_A) \cap \ker(\mathcal{L}_S)\,,
    \end{align}
    which is independent of $\gamma$. 
\end{itemize}

