[Definition def_moment of arXiv:2606.28067, 'Ergodic approximation for the invariant distribution: An abstract framework for law-depend'] {\textbf{Moments}: We denote  $\Gamma _{p}(\mu ,\nu ):=1+\|\mu\|_p+\|\nu\|_p$  and similarly
			\begin{enumerate}
				\item $\Gamma _{p}(\mu )=\Gamma _{p}(\mu ,\mu )$
				\item For random variables $X,Y$ with laws $(\mathcal{L}(X),\mathcal{L}(Y))=(\mu ,\nu )$, $\Gamma _{p}(X,Y)=\Gamma _{p}(\mu ,\nu )$ and $\Gamma
				_{p}(X)=\Gamma _{p}(X,X)$.
				\item For two sequences of random variables $(X,\hat{X})=(X_{k},\hat{X}_{k})_{k\in \mathbb{N}}$ with laws $(\mathcal{L}(X),\mathcal{L}(\hat{X}))=(\mathcal{L}(X_{k}),\mathcal{L}(\hat{X}_{k}))_{k\in \mathbb{N}}$, we let $\Gamma _{p}(X,\hat{X}):=\max_{k}\Gamma _{p}(X_{k},\hat{X}_{k})$ and $\Gamma
				_{p}(X)=\Gamma _{p}(X,X)$.
			\end{enumerate}
		}

[Prop 34 of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] Let $N\geq M\geq 1$ be fixed integers and let $y=(y_1,\dots,y_M)$ be a half-space configuration. Then, the function \eqref{eq:F initial coord function} has the following alternative expression:
	\begin{multline}

		\mathcal{F}_y(w_1,\dots,w_N)=\alpha^{N-M} \sum_{T\subseteq\{1,\dots,N\}\atop\abs{T}=M} \sum_{\sigma\in\mathcal{B}_M} \prod_{1\leq i<j\leq M} \left[\frac{w_{T_{\sigma(i)}}-qw_{T_{\sigma(j)}}}{w_{T_{\sigma(i)}}-w_{T_{\sigma(j)}}}\frac{1-w_{T_{\sigma(i)}}w_{T_{\sigma(j)}}}{1- qw_{T_{\sigma(i)}}w_{T_{\sigma(j)}}}\right] \prod_{i=1}^M\varphi_{y_i}\left(
		w_{T_{\sigma(i)}}\right) \\ \times\prod_{i=1}^M\prod_{j=1\atop j\notin T}^{N} \left[\frac{w_{T_{\sigma(i)}}-qw_{j}}{w_{T_{\sigma(i)}}-w_{j}}\frac{1-w_{T_{\sigma(i)}}w_{j}}{1- qw_{T_{\sigma(i)}}w_{j}}\right].
	\end{multline}

