body:
[Theorem thKM of arXiv:2607.14792, 'On the degree distribution of large tentacular Bienaymé--Galton--Watson trees'] Let $\eta$ be an offspring distribution such that $\eta(0) >0$ and $\eta(1) >0$ and denote by $F$ its generating function. Let $(S_n)_{n\geq0}$ be a random walk started from $S_0=0$ with step distribution $\eta$. Assume $k_n=o(n)$ and $k_n\rightarrow \infty$. Then
    \begin{equation}
    \sup_{k\geq -k_n} \left| \sqrt{k_n} \frac{b_n^{k_n+k}}{F(b_n)^{n-k_n}}\mathbb{P}\left(S_{n-k_n} = k_n+k\right) - \frac{1}{\sqrt{2\pi}}e^{-\frac{k^2}{2k_n}}\right| \xrightarrow[n \rightarrow \infty]{} 0,
\end{equation}
where $b_n$ is defined by
 \[b_n\frac{F'(b_n)}{F(b_n)}=\frac{k_n}{n-k_n}.\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 7 (Marginal cut balance) of arXiv:2607.20823, 'Fluctuation impossibility results for stochastic burst networks'] For every $i\in\{1,\dots,N\}$ and every $j\ge1$,
\begin{equation}
        \sum_v\mathcal J_i(j;v)=0.

\end{equation}
Equivalently,
\begin{equation}
        \frac{j\pi_i(j)}{\tau_i}
        =
        \sum_{n=0}^{j-1}
        \pi_i(n)m_i(n)T_{i,j-n}.

\end{equation}

[Definition def:supermartingale of arXiv:2512.21026, 'Minimax Duality in Game-Theoretic Probability\thanks{Work in progress: mistakes are likely'] Let $(\mathcal{Y},\hat\mathcal{Z},T)$ be a sequential gamble space.
  A sequence $\{X_t:\mathcal{Y}^t\to\overline{\mathbb{R}}\}_{t\leq T}$ is a \emph{game-theoretic supermartingale} if for all $t< T$ and situations $s\in\mathcal{Y}^t$, we have 
  \begin{align}

    \overline{\textsf{\textbf{E}}}[ X_{t+1} \mid s] \leq X_t(s)~,
  \end{align}
  and a \emph{game-theoretic martingale} if $\textsf{\textbf{E}}[ X_{t+1} \mid s] = X_t(s)$.

