         \mathrm{Var}(W_{n,2}) &= \sum^{m_n}_{k=1} \operatorname{\mathbb E} \widehat \Delta^2_{n,k} = \sum^{\lambda_n-1}_{k=1} \operatorname{\mathbb E} \widehat \Delta^2_{n,k} + (1+o(1))\sum^{m_n}_{k=\lambda_n} \operatorname{\mathbb E} V_{n,k},  
    \end{align} 
