body:
[Lemma 20 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the notation from Definition \ref{Def.IGP}. Then, for any $\{ B_i \in \Omega(a, b, x_i , y_i) \}_{i = 1}^k$
\begin{equation}
{\bf 1}_{A} \cdot \mathbb{P}\left( L_{i + k_1-1}\llbracket a,b \rrbracket = B_{i} \mbox{ for $i \in \llbracket 1, k \rrbracket$} \, \vert  \mathcal{F}_{\mathrm{ext}} \right) \overset{a.s.}{=} {\bf 1}_{A} \cdot \mathbb{P}_{\ice, \operatorname{Geom}}^{a,b, \vec{x}, \vec{y}, f, g} \left( \cap_{i = 1}^k\{ Q_i = B_i \} \right),
\end{equation}
where $\mathcal{F}_{\mathrm{ext}} = \sigma\left\{L_i(j): (i,j) \in \Sigma \times \llbracket T_0, T_1 \rrbracket \setminus \llbracket k_1, k_2 \rrbracket \times \llbracket a+1, b-1 \rrbracket\right\}$.

[Lemma lem.Homogenization of arXiv:2606.13442, 'Scaling limit of additive functionals for reversible non-gradient exclusion process: criti'] The following estimates hold for the corrector $\phi_{m,e_i}^z$ and the flux $\mathbf{g}_{m,e_i, b}^z$:
		\begin{enumerate}
			\item [gu2025relaxation]
			The local corrector $\phi^z_{m, e_i}$ is a local function in $\mathcal{F}_0({z+{\scaleobj{1.2}{\square}}_m^-})$.
			\item [gu2025relaxation] The local corrector $\phi^z_{m,e_i}$ is centered  
			\begin{align*}
				\mathbb{E}_\rho \left[\phi^z_{m,e_i}\right] = 0.
			\end{align*}
			\item [gu2025relaxation] The local corrector $\phi^z_{m,e_i}$ satisfies the following $H^1$ and $L^2$ estimates: for all ${\rho \in (0,1)}, m \in \mathbb{N}$ and $z \in \mathcal{Z}_m$, we have 
			\begin{align*}
				\sum_{b\in\overline{(z+{\scaleobj{1.2}{\square}}_m)^*}}\mathbb{E}_{\rho}\left[c_b(\eta)\left(\pi_b\phi^z_{m,e_i}\right)^2\right] &\leqslant 16\, (\tfrac{c_+}{c_-})\chi(\rho)3^{dm},\\
				\mathbb{E}_\rho\left[\left(\phi^z_{m,e_i}\right)^2 \right] &\leqslant 16\, (\tfrac{c_{+}}{c_{-}})\, \chi(\rho) 3^{(d+2)m}.
			\end{align*}
			\item[gu2025relaxation]
			There exists an exponent $\alpha(d,c_{-},c_{+},\mathbf{r}) \in \left(0,\frac{1}{2}\right)$ and a positive constant $C(d,c_{-},c_{+},\mathbf{r}) < \infty$, such that for every $v : \mathcal{X} \to \mathbb{R}$, we have 
			\begin{align*}
				\left\vert \frac{1}{\vert {\scaleobj{1.2}{\square}}_m \vert} \sum_{b \in \overline{(z+{\scaleobj{1.2}{\square}}_m)^*} }\bracket{\pi_b v, \mathbf{g}_{m,e_i,b}^z} \right\vert \leqslant C 3^{-\alpha m}\left(\frac{1}{\vert {\scaleobj{1.2}{\square}}_m \vert} \sum_{b \in \overline{(z+{\scaleobj{1.2}{\square}}_m)^*} }\mathbb{E}_\rho\left[(\pi_b v)^2\right]\right)^{\frac{1}{2}}.
			\end{align*}
			\item [funaki2024quantitative]
			There exists a constant $C(d,c_{-},c_{+})$ such that the $L^\infty$ and $L^{p}$ norm for the corrector $\phi_{m,e_i}^z$ satisfy the following estimates:
			\begin{align*}
				&\norm{\phi_{m,e_i}^z}_{L^\infty}\leqslant Cm3^{(d+2)m},\qquad\forall m\in\mathbb{N},\  z\in \mathcal{Z}_m,\\
				&\norm{\phi_{m,e_i}^z}_{L^p}\leqslant C(p)3^{(d+2)m},\qquad \forall p\in[1,\infty),\quad \forall m\in\mathbb{N},\  z\in \mathcal{Z}_m.
			\end{align*}
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:spectralgapVshape of arXiv:2509.02996, 'Group-averaged Markov chains: mixing improvement'] In the setting of this subsection, we have
	\begin{align*}
		\lambda(((P_\beta)_{la})_{ra}) \geq \dfrac{1-e^{-\beta}}{36n^3}.
	\end{align*}
	where we recall $\lambda(P)$ is the right spectral gap of $P$ as defined in (equation eq:rightspectralgap of the paper).

