body:
[Thm five hodge no psi of arXiv:2609.02409, 'Membranes and Maps'] Suppose that $\sum_{i=1}^5 \epsilon_i =0$. (conj:index of the paper) is equivalent to the equality
    \begin{equation}

        \mathsf{H}(~;\epsilon_1,\ldots, \epsilon_5;u)
        =
        \frac{1}{2}
        \sum_{g>1}
            \frac{B_{2g-2}}{2g-2}
            \left[
                \frac{\sum_{i=1}^5 2\sinh(u\epsilon_i)}
                {\prod_{i=1}^5 2\sinh(\tfrac{u\epsilon_i}{2}) }
            \right]_{2g-2} u^{2g-2} \,,
    \end{equation}
    where $B_k$ are Bernoulli numbers and $[\,\cdot\,]_{2g-2}$ denotes the coefficient of $u^{2g-2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 3 of arXiv:2605.04168, 'Error analysis for learning fractional stochastic differential equations with applications'] Assume hypotheses of Theorem \ref{thm:main} hold true. Let $\phi$ be a bounded differentiable activation and $D_\phi$ the corresponding uniformly bounded dictionary with bounded input weights. Let $q,q_2,\rho\geq 2$ as in Theorem \ref{thm:main}. If $b,\sigma\in B_1(D_\phi)$, then 
\begin{align*}
\inf_{b_n,\sigma_n\in \Sigma_{n,1}(D_\phi)}\mathcal{E}_{\texttt{appr},\alpha}(n) &\leq  \frac{C(q,q_2,\rho)\, K_\phi}{\sqrt{n}},
\end{align*}
where $K_\phi = \sup_{d\in D_\phi}\Vert d\Vert_{W^{2,pq}(K)}$, with $p=q_2,\rho$, provided that $pq\ge2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:poly-approx-sigmoid-network of arXiv:2512.04371, 'Constructive Approximation under Carleman's Condition, \\ with Applications to Smoothed An'] Suppose that $\mu$ is a probability  distribution over $\RR^d$. 
Then, for any $f\in \cH_{\text{sigmoid}}$, there exists a polynomial $p$ of
\begin{enumerate}
    \item  degree $O\big(\log(1/\varepsilon )^r\big)$ under $r$-strictly sub-exponential distribution $\mu$; 
    \item degree $O\big( \varepsilon^{-O(1)}\big)$ under sub-exponential distribution $\mu$,
\end{enumerate}
such that $\|f - p\|_{\mu} \leq \varepsilon$.

[Corollary cor:Coneinftynrm of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Under the assumptions of Proposition~(prop:Gammajbounds2 of the paper),  
if $\Lambda = \Lambda_N$ and $j \le N$,
\begin{align}
	&\sum_{y \in \Lambda} \big| C^{(\vec{\textbf{a}})} (y) \big|  \lesssim  L^{(2-\eta) N} + ( \textbf{a}^{(\emptyset)} )^{-1} ,   \qquad
	\sum_{y \in \Lambda} |w_j (y)| \lesssim \tilde{\chi}_j L^{(2-\eta) j}
\end{align}

