[Proposition 22 of arXiv:2608.15914, 'Absorption cutoff and stationary singularities for rounded Gaussian random dynamical syste'] Assume $A<A_{\mathrm{lat}}$, fix $\varrho\in(0,1)$, and let
  $x_N\in[-1,1]^N$. Let $\bar T_N\in\N_0$ be a sequence such that
  \begin{equation*}
    \frac{\bar T_N}{N}\exp\{C(\log\log N)^2\}\to0
    \quad\mbox{for every fixed }C<\infty .
  \end{equation*}
  Then
  \begin{equation}
    \sup_{0\leq t\leq \bar T_N}
    \frac{
      \abs{\mathscr H_t^{(N)}-\bar h_{t,N}}
    }{
      \bar h_{t,N}+(\log N)^{-1}
    }
    \xrightarrow{\Pp}0 .
  \end{equation}

