body:
[Proposition 3 of arXiv:2605.09706, 'A dyadic construction of a three-dimensional attractive point interaction Markov family'] Fix $T,\beta,\varepsilon>0$ and $x\in \overline E_\varepsilon$. There exists a unique probability measure $\mathbb P_{x}^{T,\beta,\varepsilon}$ on $\big(\Omega^{\mathbb D_T}_\varepsilon,\mathcal F^{\mathbb D_T}_\varepsilon\big)$ such that, under $\mathbb P_{x}^{T,\beta,\varepsilon}$, the coordinate process $\{X_t\}_{t\in\mathbb D_T}$ has initial distribution $\delta_x$ and is a time--inhomogeneous Markov process with transition kernels $\big\{\mathsf K^{T,\beta,\varepsilon}_{[s,t]}\big\}_{\substack{s,t\in\mathbb D_T\\ s<t}}$ with respect to the canonical filtration $\{\mathcal F_t^{\mathbb D_T,\varepsilon}\}_{t\in\mathbb D_T}$, in the sense that for every $s,t\in\mathbb D_T$ with $0\le s<t\le T$ and every bounded Borel function
$f:\overline E_\varepsilon\to\mathbb R$,
\begin{align}
\mathbb E_x^{T,\beta,\varepsilon}\!\left[
f(X_t)\,\big|\,\mathcal F_s^{\mathbb D_T,\varepsilon}
\right]
\,=\,
\int_{\overline E_\varepsilon}
f(y)\,
\mathsf K^{T,\beta,\varepsilon}_{[s,t]}(X_s,dy)
\qquad
\mathbb P_x^{T,\beta,\varepsilon}\textup{-a.s.}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem T:LND_t of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] \index{conditional variance}
  Assume $\alpha > 0$, $\beta \in (0, 2]$, $\gamma \ge 0$,
  $H \in (0, 1)$, and $\ell \in (0, 2d)$. 
    Assume the Dalang condition~(equation E:main of the paper), i.e., $\rho>0$ and $\ell < 2\alpha$. 
    Then, for all $0 < S < T < \infty$,
  there exist positive finite constants $C$ and $C'$ depending on $S, T, \alpha,
    \beta, \gamma, H, d, \ell$ such that the following statements hold.
  \begin{enumerate}[\rm (i)]

    \item If $\beta \in (0,2)$,\index{strong local nondeterminism (SLND)!one-sided} then for all $x \in \mathbb{R}^d$, for all integers $n
            \ge 1$, and for all $t, t_1, \dots, t_n \in [S, T]$ with $\max\{ t_1,
            \dots, t_n\} \le t$,
          \begin{align}
            \ensuremath{\mathrm{Var} }\left( u(t, x)\big|u(t_1, x), \dots, u(t_n, x) \right) \ge C \min_{1 \le j\le n} (t-t_j)^{2\rho}.
          \end{align}
          Consequently, for all $t, t' \in [S, T]$, for all $x \in \mathbb{R}^d$,
          \begin{align}
            \mathbb{E} \left[ \left(u(t, x) - u(t', x)\right)^2 \right] \ge C |t'-t|^{2\rho}.
          \end{align}
          In addition, there exists $\delta > 0$ such that for all $t, t' \in [S, T]$ with
          $|t'-t| \le \delta$, for all $x \in \mathbb{R}^d$,
          \begin{align}
            \mathbb{E} \left[ \left(u(t', x) - u(t, x)\right)^2 \right] \ge \begin{cases}
                                                                      C' |t'-t|^2 (1+|\log(t'-t)|) & \text{if } \rho = 1, \\
                                                                      C' |t'-t|^2                  & \text{if } \rho > 1.
                                                                    \end{cases}
          \end{align}

    \item If $\beta = 1$, then (equation LNDt:CondVar of the paper) can be strengthened\index{strong local nondeterminism (SLND)!two-sided} as
          follows: for all $x \in \mathbb{R}^d$, for all integers $n \ge 1$, and for all $t,
            t_1, \dots, t_n \in [S, T]$,
          \begin{align}
            \ensuremath{\mathrm{Var} }\left( u(t, x)\big|u(t_1, x), \dots, u(t_n, x) \right) \ge C \min_{1 \le j\le n} |t-t_j|^{2\rho}.
          \end{align}

    \item If $\beta = 2$, $\gamma \in [0, 1]$, and $H \in [1/2, 1)$, then
          for all $x \in \mathbb{R}^d$, for all integers $n \ge 1$, and for all $t, t_1,
            \dots, t_n \in [S, T]$ with $\max_j |t-t_j| \le S$,
          \begin{align}
            \ensuremath{\mathrm{Var} }\left( u(t, x) \big| u(t_1, x), \dots, u(t_n, x) \right) \ge C \min_{1\le j \le n}|t-t_j|^{2(\gamma+H+\frac{1}{2}-\frac{\ell}{\alpha})}.
          \end{align}
          and for all $t, t' \in [S, T]$, for all $x \in \mathbb{R}^d$,
          \begin{align}
            \mathbb{E}\left[ \left( u(t', x) - u(t, x) \right)^2 \right] \ge \begin{cases}
                                                                       C' |t'-t|^{2(\gamma+H+\frac{1}{2}-\frac{\ell}{\alpha})} & \text{if } \gamma + H + \frac12 - \frac\ell\alpha < 1, \\
                                                                       C'|t'-t|^2 (1+|\log(t'-t)|)                             & \text{if } \gamma + H + \frac12 - \frac\ell\alpha = 1, \\
                                                                       C' |t'-t|^2                                             & \text{if } \gamma + H + \frac12 -\frac\ell\alpha > 1.
                                                                     \end{cases}
          \end{align}
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary STABSS of arXiv:2603.12774, 'Synchronization by noise for stochastic differential equations driven by fractional Browni'] Let the hypotheses of the second statement of Theorem (ASASiid of the paper) hold. Then for every \( \epsilon > 0 \), we can find a random, non-empty, open set \( U(\omega) \subset \mathbb{R}^d \), such that for
	\begin{align}
		\mathcal{C}:=\left\lbrace \omega : \ \ \lim_{n \to \infty} \text{\emph{diam}}\left(\Phi^{n}_{\omega}(U(\omega))\right) = 0 \right\rbrace,
	\end{align}
	we have \( {\mathbb{P}}(\mathcal{C}) > 1 - \epsilon \), where the diameter of a subset $S\subseteq \mathbb{R}^d$ is defined as \( \text{\emph{diam}}(S)=\sup\{ |x-y| : x,y\in S\} \). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 (Small region principle for antisymmetric functions) of arXiv:2609.02225, '\textbf{The direct moving plane method for weak solutions of the fractional $p$-Laplacian}'] Let $n\ge2$, $0<s<1$ and $1<p\le2$. Let $D$ be an open set such that $D\subset\Omega_\lambda$ with $|D|>0$ and $u\in W^{s,p}_0(B_1)\cap L^\infty(B_1)$ satisfy
\begin{equation}
\begin{cases}
(-\Delta)^s_pu_\lambda-(-\Delta)^s_pu
+c(x)(u_\lambda-u)\ge0
        &\text{weakly in }D,\\
u_\lambda-u\ge0
        &\text{a.e. in }\Sigma_\lambda\setminus D.
\end{cases}
\end{equation}
Suppose that $-1<\lambda<0$ and
\begin{equation}
        c(x)\ge-M
        \qquad\text{for a.e. }x \in D
\end{equation}
for some $M\ge0$.
Then there exists $\delta=\delta\bigl(n,s,p,M,\|u\|_{L^\infty(B_1)}\bigr)>0$ such that, if $|D|\le\delta$, then
\[
u_\lambda\ge u \qquad\text{a.e. in }\Sigma_\lambda.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:covering-L2-cont of arXiv:2608.21805, 'Logarithmic derivatives of variational and singular stochastic partial differential equati'] Under Assumptions (ass:LR of the paper), (ass:diff2 of the paper), (ass:SC of the paper), and (ass:nondeg of the paper), for each $h$ satisfying Assumption (ass:nondeg of the paper),
\begin{equation}
  \mathbb{E}\Bigl[\int_0^t \lVert v_h(r) \rVert_U^2\,\mathrm{d}r\Bigr] \;=\; \mathbb{E}\bigl[\ip{h}{\gamma_t^{\dagger} h}_H\bigr] \;\leq\; \lVert h \rVert_H\,\bigl(\mathbb{E}[\norm{\gamma_t^{\dagger}h}_H^2]\bigr)^{1/2} \;<\; \infty.
\end{equation}
Moreover, the map $h \mapsto v_h \in L^2(\Omega; H_W)$ is linear on $\operatorname{Ran}(\gamma_t)$; whenever $h_1, h_2$ additionally satisfy the domain hypotheses of Theorem~(thm:covering-regularity of the paper), the pathwise linearity of $\gamma_t^{\dagger}$ on $\operatorname{Ran}(\gamma_t)$ and the linearity of $\operatorname{Dom}(\delta_U)$ give $v_{\alpha h_1 + \beta h_2} = \alpha v_{h_1} + \beta v_{h_2} \in \operatorname{Dom}(\delta_U)$ and $\delta_U(v_{\alpha h_1 + \beta h_2}) = \alpha\,\delta_U(v_{h_1}) + \beta\,\delta_U(v_{h_2})$ for all $\alpha, \beta \in \mathbb{R}$.

