\begin{equation}
    \Wop^{\geq k}(f) \leq \sum_{\kappa\in \Nbb^n:|\kappa|=k} \Vop^\kappa(f)  \leq \Vop^k(f) \leq \left\|\left|\grad^k f\right|\right\|_{\Leb^2}^2.
\end{equation}

