[Proposition 21 (Baseline-corrected posterior cloning) of arXiv:2608.21709, 'Posterior Information Dynamics of Diffusion Models for Linear Inverse Problems'] Define the conditional cloning observable
\begin{equation}

\phi_r(t)
=
\E_{Z_t\mid r}
\left[
\sum_{c\in\{\pm1\}}P(C=c\mid Z_t,r)^2
\right].
\end{equation}
Then
\begin{equation}

\phi_r(\infty)
=
\alpha_+^2+
\alpha_-^2
=
\sum_cP(C=c\mid r)^2.
\end{equation}
Therefore the dynamic class-speciation signal is
\begin{equation}

\Delta\phi_r(t)=\phi_r(t)-\phi_r(\infty),
\end{equation}
or, when \(\phi_r(\infty)<1\),
\begin{equation}

\widetilde\phi_r(t)
=
\frac{\phi_r(t)-\phi_r(\infty)}
{1-\phi_r(\infty)}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:S^d-regular-def of arXiv:2411.12076, 'Explicit solutions of the SI and Bass models on sparse Erd\H{o}s-R\'enyi and regular netwo'] Let 
	$[S^{ \text{\rm d-reg}}]  := 1- f^{ \text{\rm d-reg}}$. Then for any $ j \in \cal M$, 
	\begin{equation}

		[S^{ \text{\rm d-reg}}] = 
		\lim_{M \to \infty} \mathbb{E}_{{\cal G}_{M}^{\text{\rm d-reg}}} \big[\,[S_j]\, \big],  \qquad [S_j] = 1-f_j.
	\end{equation}

