[Theorem thm:construction of arXiv:2412.09087, 'General Markovian randomized equilibrium existence and construction in zero-sum Dynkin gam'] \enskip

\begin{enumerate}[(i)]
\item The equilibrium value of our game (Definition (def:equilibrium-defs of the paper)) exists and coincides with the equilibrium value $V$ of the associated game (Proposition (thm:assoc-game of the paper)). In particular, Proposition (asso-game:characterization of the paper) provides a characterization of the equilibrium value and Figure (fig-assoc of the paper) provides an illustrative example. 

\item  A global Markovian randomized $\epsilon$-Nash equilibrium exists for each $\epsilon>0$, and the equilibrium value $V$ can be attained using Markovian randomized stopping times. 
In particular, for each fixed $\epsilon>0$, the pair $(\tau_{\Psi^{(1)}},\tau_{\Psi^{(2)}})$ is a global Markovian randomized $\epsilon$-Nash equilibrium when
\begin{align}
\begin{split}
\Psi^{(1)}_t &:= A_t^{(1)}+\infty \mathbb{I}\{\tau^{D_1^{*} \backslash ({B^{h<g<f}} \cup {B^{h<f\leq g}})} \leq t \},\\
\Psi^{(2)}_t &:= A_t^{(2)}+\infty \mathbb{I}\{\tau^{D_2^{*} \backslash ({B^{g<f<h}} \cup {B^{f\leq g<h}})} \leq t \}, 
\end{split}
\end{align}
with 
\begin{align}
\begin{split}
A_t^{(1)}:&= \int_0^t \gamma^{(1)}_\epsilon(X_s)  \mathbb{I}{\{X_s \in  D_1^{*} \cap (B^{h<g<f} \cup {B^{h<f\leq g}})  \}}ds + \sum_{y \in \mbox{iso}(D_1^{*} \cap (B^{h<g<f} \cup {B^{h<f\leq g}}) )} \Gamma_\epsilon^{1}(y) l_t^y,\\
A_t^{(2)}:&= \int_0^t \gamma^{(2)}_\epsilon(X_s)  \mathbb{I}{\{X_s \in  D_2^{*} \cap 
({B^{g<f<h}} \cup {B^{f\leq g<h}}) \}}ds + \sum_{y \in \mbox{iso}(D_2^{*} \cap ({B^{g<f<h}} \cup {B^{f\leq g<h}}))} \Gamma_\epsilon^{2}(y) l_t^y,
\end{split}
\end{align}
where $\gamma^{(i)}_\epsilon(\cdot)$ and $\Gamma^{(i)}_\epsilon(\cdot)$ are real-valued functions $i=1,2$ (specified in Constructions (construction1 of the paper)--(construction2 of the paper), Appendix (appendix-construction of the paper)).
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop.near of arXiv:2512.19897, 'On the convoy of the ASEP speed process'] Consider sequences $\{q_n\left(x\right)\}_{n = 0}^{\infty}$ of orthogonal polynomials with respect to $d\mu\left(x\right)$, such that
    \begin{equation}
        b_n q_{n+1}\left(x\right) + a_n q_{n}\left(x\right) + b_{n-1} q_{n-1}\left(x\right) = xq_n\left(x\right). 
    \end{equation}
    Suppose that $\lim_{n \to \infty } b_n = \frac{1}{2}$, $\lim_{n \to \infty } a_n = 0$, in addition,
    \begin{equation}
        \frac{q_{n+1}\left(1\right)}{q_n\left(1\right)}  \simeq 1 + \frac{\alpha+\frac{1}{2}}{n} + o\left(1\right), \quad \alpha > -1.
    \end{equation}
    Let $\hat{q}_n\left(x\right) = \frac{q_n\left(x\right)}{q_n\left(1\right)}$, 
    \begin{equation}
        \lim_{n \to \infty}\hat{q}_n\left(1 - \frac{z^2}{2 n^2}\right)  = 2^\alpha \Gamma\left(\alpha+1\right)z^{-\alpha}J_{\alpha}\left(z\right),
    \end{equation}
    where $J_{\alpha}\left(z\right)$ is the first kind Bessel function. The convergence holds uniformly for $z$ in a compact subset of $\mathbb{R}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition eq:sharp-tail-cost of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[proposition]{prop:sharp-one-spike}
If \(\xi\) is sharp sub-Gaussian, then for every \(a>0\) and \(\eta>0\),
\begin{equation}
 \liminf_{N\to\infty}-\frac1N\log
 \mathbb P\left(\frac\xi{\sqrt N}\in[a,a+\eta]\right)
 \ge\frac{a^2}{2}.
\end{equation}
Hence a single localized tensor entry cannot occur at a smaller exponential cost than in the standard Gaussian model.

[Lemma 7 of arXiv:2607.18104, '2607.18104'] For each $\varepsilon>0$, define $\mathsf{G}_{\varepsilon}$ to be the event that for all $(x,s;y,t) \in [0,1]^{4}_{\uparrow}$ with $\big|\sl^{-1}(x,s;y,t)\big|\leq \varepsilon^{-\frac{1}{2}}$ and for all $\pi\in \mathfrak{G}_{(x,s),(y,t)}$, the geodesic $\pi$  is $\varepsilon\text{-good}$. There exists $\varepsilon_0>0$ and $c,C>0$ such that for all $\varepsilon\in \big(0,\varepsilon_0\big)$, 
    \begin{equation}
        \P(\mathsf{G}_{\varepsilon}) \geq  1-C\exp(-c\varepsilon^{-1/4}) . 
    \end{equation}

[Lemma 24 (Asymptotics along $\Gamma_{x,\alpha}$ in the red arc region with $\alpha_0 \neq 0, \pi$) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] Let $\alpha_0 \in (0,\pi)$ such that ${\m} < x(\alpha_0) < {\M}$. Let $r = \sqrt{a^2 + b^2}$ and define $\alpha = \alpha(a,b) \in (0,\pi)$ such that $\cos(\alpha) = \frac{a}{\sqrt{a^2 + b^2}}, \qquad 
\sin(\alpha) = \frac{b}{\sqrt{a^2 + b^2}}.$
Then, the following asymptotic holds as $r \to +\infty$ and $\alpha \to \alpha_0$:
\begin{equation}
\frac{1}{2i\pi} \int_{\Gamma_{x,\alpha}} \left( 
\frac{
\phi^{z_0}(x) \gamma(x, Y^+(x), Z^+(x)) e^{-a x - b Y^+(x)} 
+ e^{(a_0 - a)x} \left(
e^{(b_0 - b) Y^+(x)} \fc_{b_0 > 0}
+ e^{b_0 Z^+(x) - b Y^+(x)} \fc_{b_0 < 0}
\right)
}{
\partial_y \gamma_+(x, Y^+(x))
}
\right) dx 
\end{equation}
\[
\underset{r \to +\infty \atop \alpha \to \alpha_0}{\sim}
C^+(\alpha_0) h_{\alpha_0}(z_0)
\frac{e^{-r(\cos(\alpha)x(\alpha) + \sin(\alpha)y(\alpha))}}{\sqrt{r}},
\]
where $C^+(\alpha_0)$ and $h_{\alpha_0}(z_0)$ are defined in \eqref{C(alpha)} and \eqref{Harm1}.

