body:
[Lemma fromulationcingty of arXiv:2608.30443, 'On smooth holosphere solutions to compressible Euler equation'] Let $\mathcal G$ be given by (equation fialfrmaulg of the paper) and consider the decomposition 
\begin{equation}

\left|\begin{array}{l}
\mathcal G=\sum_{k=0}^{K-1}g_k u^k+r_{\mathcal G},\\
\Theta=\sum_{k={0}}^{K-1}\theta_k u^k+r_\Theta,
\end{array}\right.
\end{equation}
where
\begin{equation}

\left|\begin{array}{l}
\theta_k=(-1)^kw_{\gamma-1,\nu_b+1}(k) S_k, \ \ 0\le k\le K-1,\\
S_k=\frac{\gamma}{a(\gamma-2)}\sum_{j=0}^k\frac{(-1)^jg_j}{(j+\nu_b+2)w_{\gamma,\nu_b}(j)},
\end{array}\right.
\end{equation}
then the unique solution to the fixed point problem
\begin{equation}

r_\Theta=(-1)^{K-1}S_{K-1}M_0(u)-\mathcal T(r_\mathcal G).
\end{equation}
generates the unique solution $\Theta$ to (equation thetaeqaiotjoihs of the paper) which satisfies:
\begin{equation}

\forall k\ge 0, \ \ \mathop{\rm lim}_{u\downarrow 0} \frac{\Theta^{(k)}(u)}{k!}=\theta_k
\end{equation}
where $(\theta_k)_{k\ge 0}$ is computed by induction from (equation vneineionvioenvionoe of the paper).

[Proposition 3 of arXiv:2608.29736, '2608.29736'] Let $(M^n,\omega)$ be a compact K\"ahler manifold of complex
 dimension $n\geq 2$. Let $\chi$ be another K\"ahler form. Suppose that the $J$-semistable condition~\eqref{topintegralnonnegative}--~\eqref{$J$-semistablecondition} holds.
Then for any modified nef class $\beta$, we have \begin{equation}
    \int_M F_{n-1}(\chi)\wedge\beta \geq c\int_M \omega^{n-1}\wedge \beta,
    \end{equation}
    where \begin{equation}
   c= \frac{2n\displaystyle\int_M\Big(\chi^n-n\chi^{n-1}\wedge\omega\Big)+\int_M \omega^n}{8n^2\displaystyle\int_M\chi\wedge\omega^{n-1}}.\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:modewise of arXiv:2605.17082, 'Spectral Purification in Reversible Markov Chains: Hidden Parameters, Observable Equivalen'] Let $g_k = \sum_{i=2}^n c_i \lambda_i^k \phi_i$. Then
\begin{equation}
E_k - E_{k+1} = \sum_{i=2}^n (1 - \lambda_i^2) \, n_i(k).
\end{equation}
Equivalently, in terms of the relaxation spectrum $\mu_i = 1 - \lambda_i$,
\begin{equation}
E_k - E_{k+1} = \sum_{i=2}^n (2\mu_i - \mu_i^2) \, n_i(k),
\end{equation}
where $n_i(k) = |c_i|^2 \lambda_i^{2k}$.

