    \begin{align*}
    \begin{split}
        \,{\mathbb{E}}\left[\sum_{i,j=1}^m \left(\vert j-i \vert +1\right)I_j\right]&=\sum_{j=1}^m\left(j^2-j(m+1)+\frac{m(m+3)}{2}\right)\,{\mathbb{E}}\left[I_j\right]\\
        &= \frac{n(m^2+3m-1)}{3}.
        \end{split}
    \end{align*}
Furthermore, we get for the second moment
\begin{align*}
\begin{split}
