body:
[Defn 3 (Kinetic measure) of arXiv:2607.28238, 'Well-posedness and large deviations for the obstacle problem of first-order stochastic con'] A map $q$ from $\Omega$ to the set of nonnegative, finite measures over $\mathbb{T}^N\times [0,T]\times\mathbb{R}$ is said to be a kinetic measure, if
\begin{description}
  \item[1.] $ q$ is measurable, that is, for each $\phi\in C_b(\mathbb{T}^N\times [0,T]\times \mathbb{R}), \langle q, \phi \rangle: \Omega\rightarrow \mathbb{R}$ is measurable,
  \item[2.] $q$ vanishes for large $\xi$, i.e.,
\begin{equation}
\lim_{R\rightarrow +\infty}\E[q(\mathbb{T}^N\times [0,T]\times B^c_R)]=0,
\end{equation}
where $B^c_R:=\{\xi\in \mathbb{R}: |\xi|\geq R\}$.
  \item[3.] for every $\phi\in C_b(\mathbb{T}^N\times \mathbb{R})$, the process
\[
(\omega,t)\in\Omega\times[0,T]\mapsto \int_{\mathbb{T}^N\times [0,t]\times \mathbb{R}}\phi(x,\xi)\dd q(x,s,\xi)\in\mathbb{R}
\]
is predictable.
\end{description}

[Lem 13 ({Reformulation of Penrose~\cite[Theorem~6.7) of arXiv:2604.24624, 'Limit distributions of the threshold radius for the maximum degree and the associated poin'] {Penrose.2003}}]
    Let $A \subset \BZ_{\geq 0}$ and, $(r_n)_{n \in \BN}$ and $(\lambda(n))_{n \in \BN}$ be sequences of positive numbers.
    Define
    \begin{align*}
        &I_1(n) := \lambda(n)^2 \int_{\BR^d} F(dx) \int_{B(x; 3r_n)} F(dy) P[\CP_{\lambda(n)}(B_x^n) \in A]P[\CP_{\lambda(n)}(B_y^n) \in A],\\
        &I_2(n) := \lambda(n)^2 \int_{\BR^d} F(dx) \int_{B(x; 3r_n)} F(dy) P[\{\CP_{\lambda(n)}^y(B_x^n) \in A\} \cap \{\CP_{\lambda(n)}^x(B_y^n) \in A\}],
    \end{align*}
    where $B_x^n := B(x;r_n)$ and $\CP_{\lambda(n)}^x := \CP_{\lambda(n)} + \delta_x$.
    Then,
    \begin{equation*}
        d_\text{TV}(W_{A,\lambda(n)}', \text{Po}(E[W_{A,\lambda(n)}'])) \leq \min\left(3, \frac{1}{E[W_{A,\lambda(n)}']}\right) (I_1(n) + I_2(n))
    \end{equation*}
    holds, where $d_\text{TV}$ denotes the total variation distance and $W_{A,\lambda(n)}' := \sum_{j \in A} W_{j,\lambda(n)}'$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 16 of arXiv:2609.02478, 'Improved Weyl bounds on short intervals'] Under the hypotheses of \cref{cor:discrepancy},
\begin{equation}
  G(P;\mathcal I)
  \ll_{d,\varepsilon}
  \frac pH
  \left(p^{1/d}+H^{1-1/\Delta_d}\right)H^\varepsilon.
\end{equation}

