[Lemma 26 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] Let $X,Y,Z$ be random elements on the same probability space, with $Y$ independent of $(X,Z)$. For any test function $f(x,y)$ on the value space of $(X,Y)$, define
\[
g(x) := \mathbb{E}[f(x,Y)].
\]
Then
\begin{align}
    \mathbb{E}\big(f(X,Y)\mid Z\big) = \mathbb{E}\big(g(X)\mid Z\big).
\end{align}
In particular, if there exists a random element $W$, independent of $Y$ and distributed as $(X \mid Z)$, then
\begin{align}
    \mathbb{E}\big(f(X,Y)\mid Z\big) = \mathbb{E}\big(f(W,Y)\big).
\end{align}

[Lemma lem-Borel-disjoint-union of arXiv:2411.12623, 'Random signed measures'] Let $-\mathcal{M}_T=\{-\mu:\mu\in\mathcal{M}_T\}$ and let 
	\begin{equation*}
		\mathfrak{B}_{ \mathcal{M}_T\cup-\mathcal{M}_T\setminus\{0\} }=\{A_1\cup A_2:A_1\in \mathcal{B}_{\mathcal{M}_T\setminus\{0\}},A_2 \in\mathcal{B}_{-\mathcal{M}_T\setminus\{0\}}\}.
	\end{equation*}
	Then, $( \mathcal{M}_T\cup-\mathcal{M}_T\setminus\{0\},\mathfrak{B}_{ \mathcal{M}_T\cup-\mathcal{M}_T\setminus\{0\} },\hat{\mathfrak{B}}_{ \mathcal{M}_T\cup-\mathcal{M}_T\setminus\{0\} } )$ is a localized Borel space with $\hat{\mathfrak{B}}_{ \mathcal{M}_T\cup-\mathcal{M}_T\setminus\{0\} }=\{A_1\cup A_2:A_1\in \hat{\mathcal{B}}_{\mathcal{M}_T\setminus\{0\}},A_2 \in\hat{\mathcal{B}}_{-\mathcal{M}_T\setminus\{0\}}\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 32 of arXiv:2609.03403, 'Hyperpositive functions, sector bounded functions and a trace formula'] In the above notation, assume that $G>0$ and define
    \begin{equation}
    \begin{split}
      \Psi(z)=\begin{pmatrix}(iT+T^{-1})^{1/2}&T^{-1/2}\\ 0&T^{1/2}\end{pmatrix}+&\\
&\hspace{-5cm}+
      \begin{pmatrix}-tTB_+^*+B_-^*\\ TB_-^*+B_+^*\end{pmatrix}
      (zI_{a_\zeta}+A_\zeta^*)^{-1}G^{-1}\begin{pmatrix}B_+(T^{-1}+tT)^{1/2}&B_-T^{1/2}+B_+T^{-1/2}\end{pmatrix},
    \end{split}
  \end{equation}
  with block decomposition $\Psi=(\Psi_{ij})_{i,j=1,2}$ into $\mathbb C^{m\times m}$-valued functions. Then the solutions of Problem \ref{CF1>0} are given by
  the linear fractional transformation
  \begin{equation}

F(z)=(\Psi_{11}(z)\widetilde{\sigma}(z)+\Psi_{12}(z))(\Psi_{21}(z)\widetilde{\sigma}(z)+\Psi_{22}(z))^{-1}
\end{equation}
when $\widetilde{\sigma}$ runs through the set of $\mathbb C^{m\times m}$-valued bounded functions which take strictly contractive values on the imaginary axis.

[Lemma 26 of arXiv:2506.15736, 'Coming down from infinity for coordinated particle systems'] Let $(X_n(t))_{t \geq 0}$ be a coordinated particle system on a finite set of sites $V = \{v_1, \ldots, v_N\}$ with no death and no reproduction. The initial state will be given by $X_n(0) = (n, \ldots, n)$ where there are $n$ particles at each site. We shall now define $f_n(t) = E[|X_n(t)|]$ to be the expected total number of blocks at time $t$. Define $w_n(t)$ to be the solution to the integral equation 

    \begin{align*}
        w_n(t) = nN - \int_0^t \Omega(w_n(s))\;ds.
    \end{align*}

    \noindent Then $f_n(t) \leq w_n(t)$ for all $t \geq 0$.

