[Definition 3 of arXiv:2607.28215, 'Almost stochastic dominance via optimal transport'] For two $E$-valued random variables $X,Y$ we define
\begin{align*}
X \le_{st} Y \quad \Longleftrightarrow \quad \E[f(X)] \le \E[f(Y)] \ \ \text{for all bounded measurable increasing }f:E \to \R.
\end{align*}

[Lemma 37 of arXiv:2606.17501, 'Critical spectral behavior and large deviations for geometric $\alpha$-stable processes'] For any $x \in \mathbb{R}^{d}$ and $\theta \in \mathbb{R}$, the following inequality holds:
  \begin{align*}
    \limsup_{t \to \infty} \frac{1}{t} \log \mathbb{E}_{x} \left[ \exp(\theta A_{t}^{\mu}) \right] \le -\lambda_{\infty}(\theta\mu).
  \end{align*}

[Definition 45 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Fix $m \in \mathbb{N}$,  $t_1 < \cdots < t_m$, and set $\mathcal{T} = \{t_1, \dots, t_m\}$. If $
u = (
u_{t_1}, \dots, 
u_{t_m})$ is an $m$-tuple of locally finite measures on $\mathbb{R}$, we define the (locally finite) measure $\mu_{\mathcal{T},
u}$ on $\mathbb{R}^2$ by
 egin{equation}
\mu_{\mathcal{T},
u}(A) = \sum_{t \in \mathcal{T}} 
u_t(A_{t}), \mbox{ where } A_{t} = \{ y \in \mathbb{R}: (t,y) \in A\}.
\end{equation}

[Theorem thm:radial-qf of arXiv:2608.18293, 'Critical tensor covariance at the Marchenko--Pastur threshold'] Under (equation eq:base-assumptions of the paper) and (equation eq:critical-scaling of the paper), there exists a deterministic sequence $\varepsilon_n\to0$ such that for every deterministic complex $p\times p$ matrix $A$,
\begin{equation}
  \mathbb{E}\left|
  \frac{x^{\mathsf T}Ax}{p}
  -R_n\frac{\operatorname{Tr} A}{p}
  \right|^2
  \le \varepsilon_n\|A\|_{\mathrm{op}}^2.

\end{equation}
For all sufficiently large $n$, one may take
\begin{equation}
  \boxed{\quad
  \varepsilon_n=\bigl(\sqrt{\delta_n}+\sqrt{\kappa_n}\bigr)^2,
  \quad}

\end{equation}
where
\begin{equation}
  \delta_n=\frac{vd}{n-d}e^{vd^2/(n-d)},
  \qquad
  \kappa_n=
  \frac{8d(n-d)}{n(n-1)}
  \exp\!\left(\frac{2vd^2}{n-d}\right).

\end{equation}
Both terms tend to zero.

[Lemma limlo of arXiv:2411.18359, 'Large systems of symmetrized trapped Brownian Bridges and Schr\"odinger processes'] If $\phi:{\mathcal X } \to \mathbb{R}$ is lower semi continuous and the Large Deviations lower bound holds with $I:{\mathcal X } \to [0,\infty]$ then
\begin{equation}
    \liminf_{\epsilon \to 0}\epsilon\log \mathbb{E}[e^{\frac{\phi( Z_\epsilon)}{\epsilon}}]\geq\sup_{x\in {\mathcal X }}\{\phi(x)-I(x)\}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

