[Theorem thm:final of arXiv:2603.00773, 'Long-time $L^p$ Wasserstein contraction for diffusion processes without global dissipativi'] For $\overline{\rho},\overline{\rho}',\overline{S},\overline{M},\overline{\theta},\overline{q}>0$, $\overline{S_2}>\overline{S}$ and $p\geqslant 1$, there exist $\overline{\delta},\overline{C},\overline{\lambda}>0$ (depending only and explicitly on $\overline{\rho},\overline{\rho}',\overline{S},\overline{S_2},\overline{M},\overline{\theta},\overline{q},p$) such that the following holds. Let  $d\in\mathbb N^*$, $b\in\mathcal C^1(\mathbb R^d,\mathbb R^d)$ and $\sigma\in\mathbb R^{d\times d}$ satisfying Assumptions~(assum:decomposeYZ of the paper) and (assum:Contract_at_infty of the paper) with
\begin{equation}

\min(\rho_1,\rho_2) \geqslant \overline{\rho}\,,\quad \max(L_1,L_2,L_3,|Q|,|Q^{-1}|,|\sigma|) \leqslant \overline{M}\,,\quad S^* \leqslant \overline{S},\quad \theta \geqslant \overline{\theta},
\end{equation}
and such that, moreover, for all $x\in\mathbb R^d$ and $v\in\mathbb R^d$ with $v\cdot Q v= 1$,
\begin{equation}

v\cdot Q \nabla b(x) v \leqslant \left\{\begin{array}{ll}
\overline{\delta}&  \text{if }|x| < \overline{S} \\
- \overline{\rho} & \text{if }|x|\geqslant\overline{S}\,,
\end{array}\right.
\end{equation}
and  the invariant measure\footnote{whose existence and uniqueness is implied by Theorem~(thm:contractionMarkov of the paper) applied with $p=1$.} $\mu_\infty$ of~(equation eq:EDS_X of the paper) satisfies
\begin{equation}

\mu_\infty\left( \mathcal B(0,\overline{S_2})\right) \leqslant 1 - \overline{q}\,,
\end{equation}
where $\mathcal B(x,r)=\{y\in\mathbb R^d,\ |y-x|\leqslant r\}$.  

Then, the $L^p$ Wasserstein contraction~(equation eq:contraction_def of the paper) holds with $C = \overline{C}$ and $\lambda = \overline{\lambda}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 23 (Gaussian predictive excess) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] \label[lemma]{lem:gp-pred-formula}
Let $P$ be a Gaussian law on $L^2(\bP_X)$. Let $m_P$ be the mean function of $P$ and $v_P$ be the variance of $f(x)$ for $f\sim P$. Then
    \begin{equation}
    \cM_t(P)-\cM_t(\delta_{f^\star})
    =\frac12\int \sbr{ g\del[3]{\frac{v_P(x)}{\sigma_\xi^2}}
    +\frac{\{m_P(x)-f^\star(x)\}^2}{\sigma_\xi^2+v_P(x)} }\bP_X(\d x),
    \end{equation}
where $g(u)=\log(1+u)-u/(1+u)$. In particular,
    \begin{equation}
    0\le \cM_t(P)-\cM_t(\delta_{f^\star})
    \le\frac1{2\sigma_\xi^2}\W^2(P,\delta_{f^\star}).
    \end{equation}

