body:
[Lemma 15 of arXiv:2607.08129, '2607.08129'] For $\delta>0$, set
\begin{equation}
 V_n(\delta)
 :=\sup_{\substack{0\le s\le t\le1\\t-s\le\delta}}
 \frac1{n\log n}
 \sum_{\sqrt n<p\le n}(\log p)^2
 \Prob(s<x_{n,p}G_{n,p}\le t).
\end{equation}
Then
\begin{equation}
 \limsup_{n\to\infty}V_n(\delta)
 \le2c_\theta\delta,
 \qquad 0<\delta\le1.
\end{equation}

[Lemma lem:expr-after-shuffling of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Let $T\in\trees$.
	For every $\mathtt{u}\inT$, we have
	\begin{align*}
	\overline{p_{({\boldsymbol{\sigma}}_{T})_*\,{\boldsymbol{S}}_{T}}}\cdot\bigl({\boldsymbol{\sigma}}_{T}\cdot\mathtt{u}\bigr)
		=\boldsymbol{g}_{T}\cdot\mathtt{u}.
	\end{align*}

