[Theorem 5 of arXiv:2608.12070, 'Central limit theorems for a heavy-tailed subcritical Galton-Watson process with state-dep'] Suppose the process $\mathbf{X}=\{X_n:n\geq0\}$ is defined by \eqref{111} and satisfies {\bf (B)}. Then as $n\to \infty$,  
\begin{align*}
\frac{S_n-  n\beta\pi_0/(1-m)}{a_n}\stackrel{d}{\rightarrow} \pi_0^{-1/\alpha}\zeta_\alpha,
\end{align*}
where $a_n$ and $\zeta_\alpha$ are the same as in Theorem \ref{th02}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:criterion-edge of arXiv:2606.30517, '\textsc{Convergence towards Ideal Poisson--Voronoi tessellations with a focus on Diestel--'] Let $E$ be the weighted edge-measured graph corresponding to a weighted graph $G$, and let $\mathbf{o}\in G$.


			If the following conditions hold for some sequence $(\lambda_n)_{n \geq 1}$, then the limit measure $\nu \coloneqq \lim_{n \to \infty}\lambda_n \iota_n^*\mu$‌ exists in $\mathcal M$.
			\begin{enumerate}[label=(\roman*)]
				\item  $\restrict{F}{\mathbb N}$ is log-regularly varying with index $b>0$, and
				\item  the measures $\lambda_n\alpha_0^n$ and $\lambda_n\alpha_1^n$, defined in~(equation eq:inter-level of the paper) and~(equation eq:same-level of the paper) (representing same-level and inter-level edges), regarded as measures on $\overline{G}^2$, converge weakly to finite measure $\alpha_0$ and $\alpha_1$ on $(\partial G)^2$ respectively.

			\end{enumerate}

			Moreover, under (thm:criterion-edge:1 of the paper) and~(thm:criterion-edge:2 of the paper), $\nu$ exists and is nonzero if and only if $\lim_{n \to \infty} \lambda_n F(n) = p^{\xi}$ for some $\xi\in\mathbb R$, where $p=e^b$. 

			In this case, if the total mass of $\alpha_i$ is $c_i$ for $i=0,1$, then the claims of (thm:critArithmetic of the paper)  hold for $\varphi \coloneqq \frac{2 c_0+c_1}{c_0+c_1} \restrict{\mathrm{Leb}}{[0,1/2]} + \frac{c_1}{c_0+c_1} \restrict{\mathrm{Leb}}{[1/2,1]}$ and 
			\begin{equation}

				\nu_t \coloneqq
				\begin{cases}
					\frac {2}{2 c_0+c_1} \left(\pi\circ\edge{0}{\cdot,\cdot,t}\right)^*(\alpha_0) + \frac {1}{2 c_0+c_1} \left(\pi\circ\edge{1}{\cdot,\cdot,t}\right)^*(\alpha_1), & 0\leq t\leq 1/2\\
					\frac {1}{c_1} \left(\pi\circ\edge{1}{\cdot,\cdot,t}\right)^*(\alpha_1), & 1/2<t\leq 1.
				\end{cases}
			\end{equation}

[Theorem 12 of arXiv:2604.15226, '\bfseries Nonlinear Schrödinger equations with spatial white noise potential on full space'] Let $\sigma\in(\frac{1}{2},1)$. For any $v_0\in L_\sigma^2(\IR^2)\cap H^\sigma(\IR^2)$ and $(p,q)$ a Strichartz pair such that
\begin{equation}
\sigma>1-\frac{1}{p},
\end{equation} 
there exists a time $T>0$ until which there exists a unique solution
\begin{equation}
v\in\CC([0,T],L_\sigma^2(\IR^2)\cap H^\sigma(\IR^2))\cap L^p([0,T],W^{\gamma,q}(\IR^2))
\end{equation}
to the mild formulation
\begin{equation}
v_t=S_tv_0-i\int_0^tS_{t-s}e^{(m-1)X}|v_s|^{m-1}v_s\drm s
\end{equation}
with $p>m-1$. In particular, there exists a unique mild solution for $\sigma_m<\sigma<1$ with
\begin{equation}
\sigma_m=1-\frac{1}{m-1}
\end{equation}
for any $m\ge2$. Moreover, the solution depends continuously on the initial data $v_0\in L_\sigma^2(\IR^2)\cap H^\sigma(\IR^2)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 15 of arXiv:2605.30616, 'Brownian motion: the hyperbolic number setting'] We set
\begin{equation}
E_{\mathbb{H}}Z=U\begin{pmatrix}\iint_{(-\infty,\lambda_{1}]\times(-\infty,\lambda_{2}]}ug_{1}(u,v)dudv & 0\\
0 & \iint_{(-\infty,\lambda_{1}]\times(-\infty,\lambda_{2}]}vg_{2}(u,v)dudv
\end{pmatrix}U.
\end{equation}

[Definition 15 of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] Let $\left(\mathcal{X},\rho\right)$ be a metric space. A map $f:\mathcal{X}\rightarrow\mathcal{X}$ is said to be a contraction mapping if there exists a real constant $k\in[0,1)$ such that
    \begin{equation*}
        \rho(f(x),f(y)) \leq k\rho(x,y),\quad \forall x,y\in\mathcal{X}.
    \end{equation*}

[Proposition 18 of arXiv:2604.23656, 'Doubly Reflected Backward SDEs Driven by $G$-Brownian Motion with Quadratic Generator'] Let $\xi,f$ satisfies (H1) and (H3). Assume that $L,U\in S^{2p}_G(0,T)$ satisfies $L_t\leq N_1\leq U_t$, q.s. for any $t\in[0,T]$, where $p>1$ and $N_1\in\mathbb{R}$. Suppose that $(Y,Z,A)\in \mathcal{S}^{2p}_G(0,T)$ is a solution to the doubly reflected $G$-BSDE with parameters $(\xi,g,L,U)$ such that $(Y,A)$ satisfies $(\textmd{ASC}_{2p})$. Moreover, assume that 
    \begin{align*}
        \|L_z(1+|Z|)\|_{BMO_G}<\phi(q):\left(1+\frac{1}{q^2}\log \frac{2q-1}{2(q-1)}\right)^{\frac{1}{2}}-1,
    \end{align*}
    where $q$ satisfies $p>\frac{q}{q-1}$. Then, there exists a constant $C:=C(T,L_z,L_y,\bar{\sigma},N_1)$, such that for any $t\in[0,T]$
    \begin{align*}
        \|Y_t\|_{L^\infty_G}\leq C\left(1+\|\xi\|_{L^\infty_G}+\left\|\int_0^T|g(s,0,0)|^2ds\right\|_{L^\infty_G}^{\frac{1}{2}}\right).
    \end{align*}

