[Question of arXiv:2609.00436, 'A counterexample to the stable forking conjecture'] \begin{itemize}
            \item Do supersimple theories of finite $\mathrm{SU}$-rank satisfy the conclusion of the stable forking conjecture?

            \begin{itemize}
                \item Is the conclusion of the stable forking conjecture satisfied for $a, b  \subset \mathbb{M} \models T$, for a supersimple theory $T$ and $a\mathop{\mathpalette\setbox0=\hbox{$x$}\kern\wd0\hbox to 0pt{\mathchardef \nn=12854\hss$\nn$\kern1.4\wd0\hss}\hbox to 0pt{\hss$\mid$\hss}\lower.9\ht0 \hbox to 0pt{\hss$\smile$\hss}\kern\wd0{}} b$, where $\mathrm{SU}(a)=\mathrm{SU}(b) = 3$?\footnote{As stated in the introduction, Brower proves the case where $\mathrm{SU}(a) = 2$ and $\mathrm{SU}(b) < \omega$, improving on work of Peretz, so this is the least-rank case that remains open.}
            \end{itemize}
            \item Do countably categorical simple theories satisfy the conclusion of the stable forking conjecture?
        \end{itemize} (Stated as a question by the paper; open unless the paper says otherwise.)

[Corollary eq:continuous and discrete decomposition of M of arXiv:2509.02996, 'Group-averaged Markov chains: mixing improvement'] Assume $P\in \mathcal{S}(\pi)$. Let $G$ be any finite group acting on $\mathcal{X}$. Under Assumption (assum:pi and G of the paper), suppose the state space $\mathcal{X}$ is continuous, $\mathfrak{m}$ has no positive point mass, and $P$ has the form of (equation eq:continuous and discrete decomposition of P of the paper) with $A_{gx}=gA_x$, then for $M$ satisfying
    \begin{equation}
        M(x,dy)=M_c(x,y)\mathfrak{m}(dy)+\sum_{z\in GA_x}r(x,z)\delta_z(dy)=:M_c(x,dy)+M_d(x,dy),
    \end{equation}
    where $GA_x:=\{gz: g\in G, z\in A_x\}$ and $r(x,z)>0$, we have 
    \begin{align*}
        	D_{KL}^\pi(P\|M) &= D_{KL}^\pi(P\|(P_{la})_{ra})+D_{KL}^\pi((P_{la})_{ra}\|M), \quad  M\in \mathcal{LI}(G)\cap \mathcal{RI}(G)\cap \mathcal{S}(\pi), \\
        	D_{KL}^\pi(P\|M) &= D_{KL}^\pi(P\|P_{la})+D_{KL}^\pi(P_{la}\|M), \quad  M\in \mathcal{LI}(G)\cap \mathcal{S}(\pi),\\
        	D_{KL}^\pi(P\|M) &= D_{KL}^\pi(P\|P_{ra})+D_{KL}^\pi(P_{ra}\|M), \quad  M\in \mathcal{RI}(G)\cap \mathcal{S}(\pi).
        \end{align*}

