[Lemma lem-Interactesti of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] Assume that the interaction potential $v$ satisfies Assumption (V). Then, for any $M \in(0,\infty)$, with $\mathfrak r_{M }^{{{\scriptscriptstyle{({v}})}}}=M+\sup{\operatorname {supp}}(v)$,  for  any configuration $\omega\in {\mathcal L }^{{{\scriptscriptstyle{({M }})}}} $, and for any $R\in(1,\infty)$ and any $z,z'\in 2R\mathbb{Z}^d$,
\begin{equation}
\begin{aligned}
F_{W_z,W_{z'}}\big((\omega_{W_z},\varpi_{W_z}),(\omega_{W_{z'}},\varpi_{W_{z'}})\big)
&\leq \beta \|v\|_\infty \Big(\int_{{\mathcal B}_{\mathfrak r_{M }^{{{\scriptscriptstyle{({v}})}}}}(W_z\cap W_{z'})}{\rm d} x\,\widetilde{ \mathfrak N}_{{\mathcal B}_{\mathfrak r_{M }^{{{\scriptscriptstyle{({v}})}}}}(x)}^{{{\scriptscriptstyle{({ \ell}})}}}(\omega_{W_z},\varpi_{W_z})^2\Big)^{1/2}\\
&\qquad \times\Big(\int_{{\mathcal B}_{\mathfrak r_{M }^{{{\scriptscriptstyle{({v}})}}}}(W_z\cap W_{z'})}{\rm d} x\,\widetilde {\mathfrak N}_{{\mathcal B}_{\mathfrak r_{M }^{{{\scriptscriptstyle{({v}})}}}}(x)}^{{{\scriptscriptstyle{({ \ell}})}}}(\omega_{W_{z'}},\varpi_{W_{z'}})^2\Big)^{1/2},
\end{aligned}
\end{equation}
where ${\mathcal B}_r(A)$ denotes the $r$-ball around a compact set $A$.

