  \begin{align}
    \lambda(B)^k
    &=\BE  \lambda_{Z^c}(B)^k+\BE \eta_Z(B)^{(k)}\\ 
    &\quad +\sum^{k-1}_{i=1}\binom{k}{i}
      \BE \int_{B^{k-i}}\lambda_B(Z(\eta+\delta_{\bx})^c)^i \,
      \I\big\{x_1,\ldots,x_{k-i}\in Z(\eta+\delta_{\bx})\big\}
      \,\lambda^{k-i}(d\bx).\notag      
  \end{align}

