[Pro pro2.02 of arXiv:2603.13873, '{Solvability of BSDEs with possibly unbounded stochastic coefficients \\ on a general weig'] Let the assumptions of (pro2.01 of the paper) hold. Then there exists a constant $C_{\bar{p},\theta}^2 >0$ depending only on $\bar{p}$ and $\theta$ such that for each $0\leq r\leq t< +\infty$,
\begin{align*}
\begin{split}
&\mathbb{E}\left[\sup_{s\in[t\wedge\tau,\tau]}\left(e^{\bar{p}
\int_{0}^{s}\bar{\rho}_{r}{\rm d}r}|y_s|^{\bar{p}}\right)\bigg|\mathcal{F}_{r\wedge\tau}\right]
+\mathbb{E}\left[\int_{t\wedge\tau}^{\tau}\bar{p}e^{\bar{p} \int_{0}^{s}\overline{\rho}_r{\rm d}r}(\bar{\rho}_s-\bar{\mu}_s-\frac{\theta}
{2[1\wedge(\bar{p}-1)]}{\bar\nu_s}^2)|y_s|^{\bar{p}}{\rm d}s\bigg|\mathcal{F}_{r\wedge\tau}\right]\\
&\ \  \leq
C_{\bar{p},\theta}^2\mathbb{E}\left[e^{\bar{p}\int_{0}^{\tau}\bar{\rho}_{r}{\rm d}r}|\xi|^{\bar{p}}+\left(
\int_{t\wedge\tau}^{\tau}e^{ \int_{0}^{s}\bar{\rho}_r{\rm d}r}f_s{\rm d}s\right)^{\bar{p}}\bigg|\mathcal{F}_{r\wedge\tau}\right].
\end{split}
\end{align*}

[Theorem 5 (Trace bound with modular constants) of arXiv:2608.27657, '\bfseries Stein Kernels and Normal Approximation\\ for Log-Concave Bilinear Forms'] Suppose that, for some \(C_q,C_{\rm en}\geq0\), one has
\[
  \Var(Y^{\mathsf T}AY)
  \leq C_q\Tr(A^2),
  \qquad
  \E\Tr(AHAH)
  \leq C_{\rm en}\Tr(A^2)
\]
for every \(A\in\mathsf S_n\).  Then
\begin{equation}
  0\preceq\Gamma_{\rm tr}
  \preceq
  \left(\frac{C_q}{4}+C_{\rm en}\right)I_{\mathsf S_n}.
  \tag{3.14}
\end{equation}
More precisely, the full slack has the positive decomposition
\begin{equation}
\begin{aligned}
  \left(\frac{C_q}{4}+C_{\rm en}\right)I_{\mathsf S_n}
  -\Gamma_{\rm tr}
  ={}&
  \frac14\left(C_qI_{\mathsf S_n}-\Gamma_{\rm quad}\right)\\
  &+\left(C_{\rm en}I_{\mathsf S_n}-\mathsf U\right)
  +\frac34\mathsf D.
\end{aligned}
  \tag{3.15}
\end{equation}

Under the estimates in \cref{thm:letwin}, \(C_q=8\) and
\(C_{\rm en}=2\).  Hence
\begin{equation}
\begin{aligned}
  4I_{\mathsf S_n}-\Gamma_{\rm tr}
  ={}&
  \frac14\left(8I_{\mathsf S_n}-\Gamma_{\rm quad}\right)
  +\left(2I_{\mathsf S_n}-\mathsf U\right)
  +\frac34\mathsf D
  \succeq0,
\end{aligned}
  \tag{3.16}
\end{equation}
and, for every deterministic symmetric \(A\),
\begin{equation}
  \boxed{
  \Var\!\left(\Tr(AH)\right)
  \leq4\Tr(A^2).}
  \tag{3.17}
\end{equation}
In particular,
\begin{equation}
  \Var(\Tr H)\leq4n.
  \tag{3.18}
\end{equation}

