[Theorem 7 of arXiv:2506.15037, '2BSDE with uncertain horizon and application to stochastic control in erratic environments'] Assume that $\xi$ is an $\mathcal G_{T\wedge \tau}-$measurable random variable such that $\|\xi\|_{L_{0,\hat{\chi}}^{2}}<\infty$ and \eqref{BSDE:eq} admits a unique solution $(\mathcal Y^\mathbb P,\mathcal Z^\mathbb P,\mathcal M^\mathbb P ) \in  \mathbb S^2_{0,\hat\chi}(\mathbb F,\mathbb P)\times \mathbb H^2_{0,\hat\chi}(\mathbb F,\mathbb P)\times \mathbb M_{0,\hat\chi}(\mathbb F,\mathbb P)$ for any $\p\in \mathcal P_0$. Then, the 2BSDE \eqref{2bsde:eq} admits a solution $(Y,Z,U,M,K)\in  \mathbb S^2_{0,\hat\chi}(\mathbb G^{\mathcal P_0+})\times \mathbb H^2_{0,\hat\chi}(\mathbb G^{\mathcal P_0+})\times \mathbb J^{2}_{0,\hat\chi}(\mathbb G^{\mathcal P_0+}) \times \mathbb I^2_{0,\hat\chi}((\mathbb G^{\mathbb P +})_{\p\in \mathcal P_0})\times \mathbb M_{0,\hat\chi}((\mathbb G^{\mathbb P +})_{\p\in \mathcal P_0})$ given by

\begin{align}
\nonumber &Y_t= Y_t^b \mathbf 1_{t<\tau} + \xi^{a}_\tau \mathbf 1_{t\geq \tau},\, Z_t=Z_t^b \mathbf 1_{t<\tau},\; M_t^{\mathbb P}=M_t^{b,\mathbb P}  \mathbf 1_{t<\tau},\; K_t^{\mathbb P}= K_t^{b,\mathbb P}  \mathbf 1_{t<\tau},\; U_t^{\mathbb P}=(\xi^{a}_t-Y_t^b)\mathbf 1_{t<\tau},\\
& \forall t<T,\; \mathbb P\text{-a.s.}, \p\in \mathcal P_0
\end{align}

[Corollary 24 (Functional Santal\'o inequality for unconditional log-concave measures) of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $\mu$ be a probability measure on $\R^n$ with an unconditional, log-concave density with respect to Lebesgue measure. Let $f\in\mathcal{F}(\mathcal{K}_e^n)$ and let $g:\R^n\to\R_+$ be measurable. Suppose that $\Omega:\R_+\to\R_+$ is measurable and non-increasing and that
\[
    f(x)^{\frac12}g(y)^{\frac12}
    \leq
    \Omega(\langle x,y\rangle), \qquad \forall \,\, x,y\in\R^n \text{such that} \, \langle x,y\rangle>0.
\]
Then,
\begin{equation}

    \left(\int_{\R^n}f(x)\,d\mu(x)\right)^{\frac12}
    \left(\int_{\R^n}g(y)\,d\mu(y)\right)^{\frac12}
    \leq
    \int_{\R^n}\Omega(|x|^2)\,d\mu(x).
\end{equation}

[Lemma 5 (Specific relative entropy is uniformly controlled by finite-volume conditional relative entropies) of arXiv:2608.13677, 'Asymptotically complete free-energy dissipation: \\ a coarse MLSI holds at any positive te'] \label[lemma]{lemma:specific_entropy_controlled_by_finite_volume_conditional_entropies}
    There is a sequence \(\epsilon_n \xrightarrow[n \to \infty]{} 0\) such that for all \(n \in \mathbb{N}\) and all \(\mu \in \mathcal{P_\theta}\) it holds
    \begin{align}
        h(\mu)
        \,\leq\, \frac{h_{\Lambda_n \vert \Lambda_n^c}(\mu)}{\vert \Lambda_n\vert} + \epsilon_n.
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:fk of arXiv:2603.28161, 'Boundary four-point connectivities of conformal loop ensembles'] Let $R_{\rm{FK}}(\lambda)=\frac{P^{(12)(34)}_{\rm{FK}}(x_1,x_2,x_3,x_4)}{P^{\rm total}_{\rm{FK}}(x_1,x_2,x_3,x_4)}$, and for $x\in(0,1)$, define
\begin{equation}
g(x) = -\frac{(1 - x)^{3/2} \left( (2 - 4x) \, {}_2F_1\!\left(\frac{3}{2}, \frac{7}{2}; 3; 1 - x\right) - 3x(1 - x) \, {}_2F_1\!\left(\frac{5}{2}, \frac{9}{2}; 4; 1 - x\right) \right) x^{3/2}}{2\left(x + (1 - x)^2\right)^2}.
\end{equation}
Then we have $R_{\rm{FK}}(\lambda)=A_{\rm{FK}}\int_0^\lambda g(x)dx$, with $A_{\rm{FK}}=(\int_0^1 g(x)dx)^{-1}\approx1.19948$. (Proof in the paper; no proof environment follows the statement in the TeX.)

