[Theorem 21 of arXiv:2606.14443, 'SEMICLASSICAL LIMIT OF POLYAKOV-LIOUVILLE MEASURE and Q-Curvature Uniformization ON EVEN-D'] Let $(\psi_j)_{j\in\N}$ be a complete $L^2$-orthonormal system consisting of eigenfunctions of~$\mathsf p$, each with corresponding eigenvalue~$\nu_j$. Let $(\xi_j)_{j\in \N}$ be a sequence  of independent and identically distributed standard Gaussian variables. For each~${\ell} \in \mathbb{N}$, we define the random test function
	\begin{align*}
		\tilde h_{\ell}(x)\coloneqq  \sum_{j=1}^{\ell} \frac{\psi_j(x)}{\sqrt{\nu_j+m}}\, \xi_j, \qquad x \in M \fstop
	\end{align*}
	Then, the covariance of the random field $\tilde h_{\ell}$ is given by:
	\begin{equation*}
		\tilde	k_{\ell}(x,y)\coloneqq  {\E}\Big[\tilde h_{\ell}(x)\, \tilde h_{\ell}(y)\Big]=\sum_{j=1}^{\ell} \frac{\psi_j(x)\, \psi_j(y)}{\nu_j+m}\comma \qquad x, y \in M \fstop
	\end{equation*}

	Moreover, for all $\varepsilon > 0$, the field~$\tilde h_{\ell}$, regarded as a random element of ${H}^{-\varepsilon}$, converges as~${\ell} \to \infty$ to a massive co-polyharmonic Gaussian field $\tilde h_0$ in $L^{2}(\mathbb{P})$ and $\mathbb{P}$-a.s.
	In particular, $\tilde h \in  H^{-\varepsilon}$ $\mathbb{P}$-a.s..

[Corollary 4 of arXiv:2609.03418, 'Sampling and Density Theorems for the Fractional Opdam--Cherednik Transform'] For $j\in\mathbb Z\setminus\{0\}$, set $D_j:=\mathcal I(\mu_j,\mu_j)$.
Then $D_j\neq0$, and
\begin{align}
\mathcal I(\mu_k,\mu_j)=
D_j\delta_{jk},
\quad j,k\in\mathbb Z\setminus\{0\}.
\end{align}
Moreover,
\begin{align}
\int_{-1}^{1}
G_{\mu_j}^{\alpha,\beta}(-x)
A_{\alpha,\beta}(x) dx
=0,\quad j\in\mathbb Z\setminus\{0\}.
\end{align}
Consequently, if
$$ g(x) = c_0+\sum_{k\in\mathbb Z\setminus\{0\}} c_kG_{\mu_k}^{\alpha,\beta}(x) $$
is the Riesz-basis expansion of
$g\in L^2((-1,1),A_{\alpha,\beta})$, then
\begin{align}
c_j=\frac{1}{D_j}
\int_{-1}^{1}
g(x)G_{\mu_j}^{\alpha,\beta}(-x)
A_{\alpha,\beta}(x)\,dx,
\quad j\neq0.
\end{align}

[Corollary CorGroundStateVisitation of arXiv:2608.11178, 'A submartingale for the probability of avoiding the origin in one-point interaction ground'] Fix \(d\in\{2,3\}\), \(T,\gamma>0\), and \(x\in\mathbb R^d\setminus\{0\}\). The following hold.
\begin{enumerate}[(i)]
\item The probability that the ground-state diffusion does not hit the
origin by time \(T\) is given by
\begin{align}
\mathbb P_x^{T,\gamma}[\tau>T]
=
\frac{
K_{d/2-1}\!\left(
\sqrt{2\lambda_\gamma}\,|x|,
\lambda_\gamma T
\right)
}{
K_{d/2-1}\!\left(
\sqrt{2\lambda_\gamma}\,|x|
\right)
}.\nonumber
\end{align}

\item Conditionally on the event \(\{\tau\le T\}\), the first hitting
time \(\tau\) has density on \((0,T]\) given by
\begin{align}
\frac{
\mathbb P_x^{T,\gamma}
\left[
\tau\in dt
\,\middle|\,
\tau\le T
\right]
}{dt}
=
\frac{\left(
\frac{|x|}{\sqrt{2\lambda_\gamma}}
\right)^{d/2-1}}{
K_{d/2-1}
\left(
\sqrt{2\lambda_\gamma}|x|
\right)
-
K_{d/2-1}
\left(
\sqrt{2\lambda_\gamma}|x|,
\lambda_\gamma T
\right)
}\,
\frac{1}{2t^{d/2}}
e^{-\lambda_\gamma t-\frac{|x|^2}{2t}}
,
\qquad
0<t\le T. \nonumber
\end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 23 of arXiv:2506.15736, 'Coming down from infinity for coordinated particle systems'] Suppose a coordinated particle system $(X(t))_{t \geq 0}$ on a finite set of sites $V$ has no death and no reproduction. Assuming that $|X(t)| < \infty$, the expected rate of change in total number of particles at time $t$ is given by

    \begin{align*}
         \lim_{h \downarrow 0} \frac{1}{h}E\left[\sum_{v\in V} X_v(t+h) - X_v(t) \Big| X(t)\right]=-\sum_{v \in V} \psi_v(X_v(t)),
    \end{align*}

    \noindent where $\psi_v$ is the non-asymptotic processing speed of the $\Lambda_v$-coalescent.

