body:
[Proposition 11 of arXiv:2605.11877, 'Fluctuation analysis for a randomly perturbed dynamical system with state-dependent impuls'] There exists a constant $C=C(\sfT)>0$ such that for $\eps \in (0,1)$, we have
\begin{equation*}
\begin{aligned}
|R^\eps_{\lambda^\eps_t}-r(t)| &\le C\left\{\|J^\eps_\cdot-1\|_\infty + \eps \sup_{s \in [0,\sfT]} |W_s|\right\} \ind_{G^\eps_\sfN} + Ce^{\varrho \Ren^\eps_t}\left\{1 + \eps (\Ren^\eps_\sfT+1) \sup_{s \in [0,\sfT]} |W_s| \right\} \ind_{\Omega\setminus G^\eps_\sfN},\\
|\Theta^\eps_{\lambda^\eps_t}-\theta(t)| &\le \left\{2\delta+ 2\varepsilon^p \sup_{[0,\thinspace \sfT]} |B_t|\right\} \ind_{G^\eps_\sfN} + \left\{ 4\sfT + 2\eps^p \sup_{[0, \sfT]} |B_t|\right\} \ind_{\Omega\setminus G^\eps_\sfN}.
\end{aligned}
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 of arXiv:2511.06196, 'Central limit theorem for high temperature spin models via martingale embedding'] Let \(A \subset \{1,\ldots,n\}\) and choose arbitrary \(\epsilon > 0\).
Then, for some \(C_{t,\epsilon}, c_\epsilon > 0\), independent of \(n\) and \(A\), we have
\begin{equation*}
\sup_{\sigma \in \{-1,1\}^{A}}
\E\Big|\sum_{k,j=1}^nm_{ijk}^{[A]}\Big|^{2+\epsilon}
\le C_{t,\epsilon}
\end{equation*}
for all \(i\in \{1,\ldots,n\}\) and \(0 \le t < c_\epsilon\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:common-reference-final of arXiv:2606.29557, 'Propagation of chaos for Belavkin equations beyond pure states'] For every \(t\in[0,T]\),
\begin{equation}
  \mathbb E_{\mathbb Q^{N,\alpha}}
  \left[
    \left\|
      \rho_t^{N,\alpha}
      -
      \rho_t^{N,\beta}
    \right\|_1
  \right]
  \le
  2d_N.

\end{equation}
The same estimate holds for every marginal:
\begin{equation}
  \mathbb E_{\mathbb Q^{N,\alpha}}
  \left[
    \left\|
      \rho_t^{N:n,\alpha}
      -
      \rho_t^{N:n,\beta}
    \right\|_1
  \right]
  \le
  2d_N,
  \qquad
  1\le n\le N.

\end{equation}

