[Theorem thm:ville-expectation of arXiv:2512.21026, 'Minimax Duality in Game-Theoretic Probability\thanks{Work in progress: mistakes are likely'] Let $(\mathcal{Y},\hat\mathcal{Z},T)$ be a real-valued sequential gamble space.
  Then for all $X:\mathcal{Y}^T\to\overline{\mathbb{R}}$ we have
  \begin{align}

    \overline{\textsf{\textbf{E}}} X = \inf\{ X_0 \mid \{X_t \in \mathbb{R}\}_t \text{ game-theoretic supermartingale}, X_T > X \}~,
  \end{align}
  where $X_\infty := \liminf_{t\to\infty} X_t$.

[Lemma 7 of arXiv:2604.27519, 'Quantitative homogenization of the maximal action of curves in a Brownian potential'] \begin{align}
\mathbb{E}A_{L/2}^+-2\mathbb{E}A^-_L+\mathbb{E}A_{L/4}^{-}\lesssim\|A^-_{L/4}-\mathbb{E}A^-_{L/4}\|_1+1.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 38 of arXiv:2606.17501, 'Critical spectral behavior and large deviations for geometric $\alpha$-stable processes'] Let $B(R)$ be the open ball of radius $R$ centered at the origin. 
  Let $C^{B(R)}(\theta)$ be the spectral function restricted to the open ball $B(R)$,
  that is,
  \begin{align}

    C^{B(R)}(\theta) := -\inf \left\{ \mathcal{E}^{\alpha}(u,u) - \theta \int_{B(R)}^{ } u^{2} d\mu :
    u \in \mathcal{F}^{B(R)},\ \int_{B(R)}^{ } u^{2} dx = 1\right\},
  \end{align}
  where
  \begin{align}

    \mathcal{F}^{B(R)} := \left\{ u \in \mathcal{F}^{\alpha}: u = 0\ \text{$m$-a.e. on } B(R)^{c} \right\}.
  \end{align}
  Then, we have
\begin{align}
  \lim_{R\to\infty} C^{B(R)}(\theta) = C(\theta). 
\end{align}

