body:
[Lemma 26 (Nesterov label-noise contribution) of arXiv:2609.02728, 'Momentum in large-batch training: Polyak enlarges the critical batch size, Nesterov improv'] Assume the stable small-step condition \(\eta\lambda_1\le c_{\rm st}\), where \(c_{\rm st}>0\) is a
sufficiently small universal constant.  There exist constants \(C,c_-,c_+>0\) such that if
\[
    k\ge
    C\max\left\{\frac1{1-\rho},\frac{1-\rho}{\eta}\right\},
\]
then
\[
    c_-\frac{\sigma^2}{B}
    \min\left\{
        \left(\frac{\eta}{1-\rho}\right)^{\frac1\beta},
        \frac{\eta}{1-\rho}
    \right\}
    \le
    \frac{\eta^2\sigma^2}{B}\sum_{\tau=0}^{k-1}\mathcal K_{\nesterov}(\tau)
    \le
    c_+\frac{\sigma^2}{B}
    \min\left\{
        \left(\frac{\eta}{1-\rho}\right)^{\frac1\beta},
        \frac{\eta}{1-\rho}
    \right\}.
\]
Hence the Nesterov label-noise floor is
\[
    \frac{\eta^2\sigma^2}{B}\sum_{\tau=0}^{k-1}\mathcal K_{\nesterov}(\tau)
    \eqsim
    \frac{\sigma^2}{B}
    \min\left\{
        \left(\frac{\eta}{1-\rho}\right)^{\frac1\beta},
        \frac{\eta}{1-\rho}
    \right\}.
\]

[Prop 15 of arXiv:2506.21087, 'Quasi-Stationary Distributions of Interacting Dynamical Systems and their approximation'] Assume \ref{condhzero} and \ref{condhun} and that,
\begin{equation}
\|\delta_{x}R^{\alpha}_{t}-\delta_{y}R^{\alpha}_{t}\|_{\TV}\overset{t\to+\infty}{\longrightarrow}0 \quad\textnormal{uniformly in $(x,y,\alpha)\in \MM\times\MM\times {\cal F}(\ER_+,{\cal P}(E))$}.
\end{equation}
Then,
    \begin{itemize}
    \item[(i)] There exists a map $\alpha\mapsto \mu^\star_\alpha$ from ${\cal C}(\ER_+,{\cal P}(\MM))$ to ${\cal P}(\MM)$ such that
        \begin{equation}
        \sup_{\mu,\alpha}\|\mu R^{\alpha}_{t}-\mu^\star_\alpha\|_{\TV}\overset{t\to+\infty}{\longrightarrow}0.
    \end{equation}
  \item[(ii)]  The convergence result also holds for $\Phi^{\alpha}_{t}(\mu)$:
    \begin{equation}
        \sup_{\mu,\alpha}\|\Phi^{\alpha}_{t}(\mu)-\mu^\star_\alpha\|_{\TV}\overset{t\to+\infty}{\longrightarrow}0.
    \end{equation}
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

