[Defi GKato of arXiv:2411.19543, 'Feller property and convergence for semigroups of time-changed processes'] {\rm Let $\mu$ be a positive Radon measure on $X$. 
We say that $\mu$ is
\begin{enumerate}
\item[\rm(1)] a $G$-bounded (Green-bounded) measure if 
\[
G^\mu1:=\int_X G(\cdot,y)\,d\mu(y) \in \mathscr{B}_b(X).
\]
\item[\rm(2)] a $G$-Kato (Green-Kato) measure if   $G^\mu1\in C_0(X)$.
\end{enumerate}
}

[Corollary 7 (The 6\,dB/bit rule) of arXiv:2608.25188, 'Transforms for LLM Quantization:\\ The Great Inversion and Format Co-Design'] Under the high-resolution noise model of \Cref{lem:bennett}, for a symmetric $b$-bit uniform quantizer with AbsMax scale on a group of RMS $\sigma$ and max $M$, the signal-to-quantization-noise ratio is
\begin{equation}
\mathrm{SQNR}
= \frac{\sigma^2}{\Delta^2/12}
= 12\,(2^{b-1}-1)^2\,\Big(\tfrac{\sigma}{M}\Big)^2 ,
\qquad
\mathrm{SQNR}_{\mathrm{dB}} \approx 6.02\,b + 4.77 - 20\log_{10}\mathrm{CF}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 2 (Theorem \ref{Thm A E FPS}) of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] The indicator function $\ind_{\Ns_{\varepsilon}(A)}$ satisfies the following asymptotic expansion:
for every $N\geq 0$,
\begin{displaymath}
\ind_{\Ns_{\varepsilon}(A)}
=
\dfrac{1}{\sqrt{2\pi}}
\sum_{k=0}^{N} (-1)^{k}
\dfrac{1}{2^{k} k! (k+1/2)}
\dfrac{\psi_{2k+1,A}}{\big(\frac{1}{2\pi}\vert\log \varepsilon\vert\big)^{k + 1/2}}
~+~R_{N,\varepsilon},
\end{displaymath}
where the error term $R_{N,\varepsilon}$ satisfies, as $\varepsilon \to 0$,
\begin{displaymath}
\forall \eta >0,~
\E\big[\Vert R_{N,\varepsilon} \Vert_{H^{-\eta}(\C)}^{2}\big]^{1/2}
=\, o (\vert\log \varepsilon\vert^{-(N+1/2)}).
\end{displaymath} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:mildsolutions of arXiv:2609.03980, 'Decay Rates and Domain Dependence of a Coupled Wave-Heat System with Spatially Dependant H'] For each accretive $S\in L^\infty(\Omega_h,\mathbb{C}^{n\times n}) $,
    the operator $A_S$ generates a contractive $C_0$-semigroup $T_S = (T_S(t))_{t \ge 0}$ on $ L^2(\Omega_w)\times L^2(\Omega_w)^n \times L^2(\Omega_h)$ with fixed space 
    $$
        \ker(A_S) 
        = 
        \left\{
            \begin{pmatrix}
                0\\w_2\\0
            \end{pmatrix}
            ~\middle|~ 
            w_2 \in H^{\operatorname{div}}(\Omega_w), \; {\operatorname{div}} w_2 = 0, \; {\operatorname{tr}}^{\gamma}_N(w_2)=0
        \right\}
    $$ 
    and $T_S(t)$ converges strongly as $t \to \infty$. 
    Moreover, 
    \begin{align*}
        \ker(A_S)^\perp = L^2(\Omega_w)\times \nabla H^1_{\Gamma_w}(\Omega_w)\times L^2(\Omega_h)
    \end{align*} 
    is invariant under $T_S$, and its restriction $T_S^\perp \coloneq T_S|_{\ker(A_S)\perp}$ is generated by $A_S^\perp  \coloneq  A_S|_{\ker(A_S)\perp}$ and converges strongly to $0$ as $t \to \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm Bernstein of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] Let  $\mu > -\frac12$, ${\kappa}_1,\ldots, k_{d_2} > -1$. Then for every polynomial $f$ of degree at most $n$, 
\begin{align}
  &  \sum_{i=1}^{d_1}  \left \| \frac{\sqrt{(1-|\bm y|)^2- \|\bm x\|^2}}{\sqrt{1-|\bm y|}} \partial_{x_i} f \right \|_{\mu,{\boldsymbol{\kappa}}}^2  
   + \sum_{1 \le i< j \le d_1}  \left\|   \frac{1}{\sqrt{1-|\bm y|}} D_{i,j}^{(\bm x)} f \right \|_{\mu,{\boldsymbol{\kappa}}}^2 \\
  &\qquad +  \sum_{1\le i< j \le d_2} \left \| (\partial_{y_j} - \partial_{y_j}) f  \right \|_{\mu,{\boldsymbol{\kappa}}}^2 +
     \sum_{i=1}^{d_2} \left \| \frac{\sqrt{y_i}}{\sqrt{1-|\bm y|}}  {\mathfrak D}_i f \right \|_{\mu,{\boldsymbol{\kappa}}} \le {\lambda}_n^{\mu,{\boldsymbol{\kappa}}} \| f |_{\mu,{\boldsymbol{\kappa}}}^2.  \notag
\end{align}
Moreover, the inequality is sharp in the sense that the equality is attained by some polynomial of degree $n$, and 
so is the inequality  
\begin{align}
  \sum_{1\le i< j \le d_2} \left \| (\partial_{y_j} - \partial_{y_j}) f  \right \|_{\mu,{\boldsymbol{\kappa}}}^2 +
     \sum_{i=1}^{d_2} \left \| \frac{\sqrt{y_i}}{\sqrt{1-|\bm y|}}  {\mathfrak D}_i f \right \|_{\mu,{\boldsymbol{\kappa}}} \le {\lambda}_n^{\mu,{\boldsymbol{\kappa}}} \| f |_{\mu,{\boldsymbol{\kappa}}}^2.
\end{align}

[Proposition 21 of arXiv:2608.03497, 'Connective Constants on Nested Fractal Graphs'] If \(N=4k_N+\ell_N\notin\{3,5\}\), where
\(\ell_N\in\{1,2,3\}\), then the functions in
\eqref{eq:ngasket-crossings} satisfy
\begin{equation}
  \begin{aligned}
  X_0
    &=e^{-(k_N+1)\beta}
      +e^{-(3k_N+\ell_N-1)\beta},&
  Y_0
    &=e^{-2(k_N+1)\beta}
      +e^{-(2k_N+\ell_N-2)\beta},\\
  X_{m+1}
    &=X_m^2
      \bigl(Y_m^{k_N}+Y_m^{3k_N+\ell_N-2}\bigr),&
  Y_{m+1}
    &=X_m^2
      \bigl(Y_m^{2k_N+\ell_N-3}+Y_m^{2k_N+1}\bigr).
  \end{aligned}

\end{equation}

For \(N=3\),
\begin{equation}
  \begin{aligned}
  x_0&=e^{-\beta},&
  y_0&=e^{-2\beta},\\
  x_{m+1}
    &=(x_m+y_m)^2+x_m^2(x_m+2y_m),&
  y_{m+1}
    &=x_my_m(x_m+2y_m).
  \end{aligned}

\end{equation}

For \(N=5\), put
\[
  \bar\phi_m=\phi_{1,m}+\phi_{2,m},
  \qquad
  \bar\theta_m=\theta_{1,m}+\theta_{2,m}.
\]
Then
\begin{equation}
  \begin{aligned}
  (\phi_{1,0},\phi_{2,0},\theta_{1,0},\theta_{2,0})
    &=(e^{-2\beta},e^{-3\beta},e^{-\beta},e^{-4\beta}),\\
  \phi_{1,m+1}
    &=\bar\phi_m^2\bar\theta_m(1+\theta_{1,m}),\\
  \phi_{2,m+1}
    &=\bar\phi_m^2\bar\theta_m\theta_{2,m},\\
  \theta_{1,m+1}
    &=\bar\phi_m^2+
      \bar\theta_m^2\theta_{1,m}\phi_{1,m}
      (\phi_{1,m}+2\phi_{2,m}),\\
  \theta_{2,m+1}
    &=\bar\theta_m^2\theta_{2,m}\phi_{1,m}
      (\phi_{1,m}+2\phi_{2,m}).
  \end{aligned}

\end{equation}

[Lemma lma:residuehalf of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] Write $P_i = \rho_i^B(m_{i,3}) = \left(\begin{smallmatrix}1&p_i\\0&1\end{smallmatrix}\right)$. Set
\begin{equation*}
	K_i(t) = \epsilon_{i+2}\Sigma_i(t)(\ell_{i+2}) \ \ \ \ \ q_i(t) := (K_i(t))_{21}
\end{equation*}
Then there is a nonzero real number $s$ such that $q_i(t) = \frac{2s}{p_i}t + O(t^2)$, and $\theta(t) = \frac{8s^2}{p_1p_2}t^2 + O(t^3)$. Consequently, $p_1p_2 > 0$, and $\frac{q_1(t)q_2(t)}{\theta(t)} = \frac12 + O(t)$.

[Lem 17 of arXiv:2607.28865, 'First-Passage Percolation on Spread-out line graphs: Microscopic Regime'] Fix $j>2\ell-2$ and set
\begin{align*}
    \fL_0:=\{0,1,\ldots,\ell-1\},
    \qquad
    \fR_j:=\{j-\ell+1,\ldots,j\}.
\end{align*}
For $u\in\{\ell-1,\ldots,j-\ell\}$, let
\begin{align*}
    \cC_u^{(j)}
    :=
    \{(x,y)\in\cE[0,j]:x\le u<y\}.
\end{align*}
Then, for every $S\subseteq\cE[0,j]$, the following hold.
\begin{enumeratei}
    \item If $|S|<\lc$, then deleting $S$ does not disconnect $\fL_0$ from $\fR_j$.

    \item If $|S|=\lc$ and deleting $S$ disconnects $\fL_0$ from $\fR_j$, then
    $S=\cC_u^{(j)}$ for a unique $u\in\{\ell-1,\ldots,j-\ell\}$.  Moreover, for every
    $e\in\cC_u^{(j)}$, there is a simple $\fL_0$-$\fR_j$ path whose unique edge in
    $\cC_u^{(j)}$ is $e$.
\end{enumeratei}

