[Corollary cor:PlaracloseKL of arXiv:2509.02996, 'Group-averaged Markov chains: mixing improvement'] Assume that $\pi,G,P,M,\mathcal{X}$ satisfy the assumptions as stated in Theorem (thm:bisection of the paper). We have
	\begin{align*}
		D^{\pi}_{KL}(P_{da} \| \Pi) &\geq D^{\pi}_{KL}((P_{la})_{ra} \| \Pi).
	\end{align*}
	In particular,
	\begin{align*}
		D^{\pi}_{KL}(\overline{P} \| \Pi) &\geq D^{\pi}_{KL}((P_{la})_{ra} \| \Pi), \quad D^{\pi}_{KL}(\widetilde{P} \| \Pi) \geq D^{\pi}_{KL}((P_{la})_{ra} \| \Pi), \\
		D^{\pi}_{KL}(P_{la} \| \Pi) &\geq D^{\pi}_{KL}((P_{la})_{ra} \| \Pi), \quad D^{\pi}_{KL}(P_{ra} \| \Pi) \geq D^{\pi}_{KL}((P_{la})_{ra} \| \Pi).
	\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem.vinf.convex of arXiv:2605.14149, 'The mean-field limit of online stochastic vector balancing'] For each $t_0 \in [0,1]$, $\mathcal{V}^{\infty}(t_0,\cdot)$ is $L$-convex, meaning that for any square-integrable random variables $X_0,X_0'$ defined on some common probability space $(\Omega, \mathcal{F}, \mathbb{P})$, we have
    \begin{align*}
        \mathcal{V}^{\infty}\Big(t_0, \mathcal{L}\big(\lambda X_0 + (1-\lambda) X'_0 \big) \Big) \leq \lambda \mathcal{V}^{\infty}\big(t_0,\mathcal{L}(X_0)\big) + (1-\lambda) \mathcal{V}^{\infty}\big(t_0,\mathcal{L}(X'_0)\big),
    \end{align*}
    for $0 \leq \lambda \leq 1$. Moreover, $\mathcal{V}^{\infty}(t_0,\cdot)$ is even, in the sense that
    \begin{align*}
        \mathcal{V}^{\infty}(t_0, \mathcal{L}(X_0)) = \mathcal{V}^{\infty}\big(t_0,\mathcal{L}(-X_0)\big).
    \end{align*}
    As a consequence, $\mathcal{V}^{\infty}(t_0,\cdot)$ obtains a global minimum at $\delta_0$.

[Theorem 84 (Rayleigh’s monotonicity principle) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] Let $\weight, \weight'$ be weights on $G$ with $\weight(e) \leq \weight'(e)$ for all edges $e \in E$. If $A,B \subset V$ are two disjoint sets, then
\begin{equation*}
    \effR{\weight'}{A}{B} \leq \effR{\weight}{A}{B},
\end{equation*}
i.e.\ the effective resistance is a non-increasing function of the weights. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma dist of arXiv:2412.02486, 'On the curvatures of \\ random complex submanifolds'] ~Using the above notations,  the following holds. 
	\begin{enumerate}
\item Assume $3r>2n-2$. Then,
for any $s \in H_1 $, 
	$$\dist (s, \Delta_1) = (n-r)^{-1}\min_{(X,Y)\in (\mathbb{C} \mathbb{P}^{n-r-1})^2}\|s(X,Y)\|_{\mathrm{FS}}.$$
\item Assume $3r>2n-2$. Then,
for any $s \in H_2 $, 
$$\dist (s, \Delta_2) = (n-r)^{-1}\min_{X\in \mathbb{C} \mathbb{P}^{n-r-1}}\|s(X)\|_{\mathrm{FS}}.$$
\item For any $s \in H_3 $, 
$$\dist (s, \Delta_3) = (n-r)^{-1}\min_{X\in \mathbb{C} \mathbb{P}^{n-r-1}}\|s(X)\|_{\mathrm{FS}}.$$
\end{enumerate}
In all three cases, the distance is computed with respect to the $\mathscr{L}^2$-metric induced by the Fubini--Study metric on $\mathcal{O}(1)$, see Equation (equation prod of the paper) and Example (example of the paper).

[Maintheorem 1 of arXiv:2608.28964, '2608.28964'] For the equation \eqref{eq NS},\eqref{eq xi} with $\xi=\eta^{s}$ given by \eqref{eq eta_s}, and any $B_0>0$, there exists an integer $N=N(B_0)\in\N^+$ such that the following holds. If $\{b_j\}_{j\in\N^+}$ satisfies
	\begin{equation*}
	\sum_{j\in\N^+}b_j^2\leq B_0\quad\text{and}\quad b_j\neq0\quad\text{for }1\leq j\leq N,
	\end{equation*}
    then there exists a probability measure $\mu$ on $\mathcal H^1$ and constants $C,\alpha,\gamma>0$ such that
	\begin{equation}
	\left|\E\varphi(u(t,u_0))-\int_{\mathcal H^1}\varphi d\mu\right|\leq Ce^{-\alpha t}\exp\left(C\gamma\|u_0\|_{\mathcal H^1}^2\right)\|\varphi\|_{\mathcal H^1,\gamma}
	\end{equation}
    for any $\varphi\in\mathcal{O}_{\mathcal H^1,\gamma}$, $u_0\in \mathcal H^1$ and $t\geq0$, where
	\begin{equation*}
	\mathcal{O}_{\mathcal H^1,\gamma}=\left\{\varphi\in C^1(\mathcal H^1):\|\varphi\|_{\mathcal H^1,\gamma}<\infty\right\},\quad\|\varphi\|_{\mathcal H^1,\gamma}=\sup_{u\in \mathcal H^1}\left(e^{-\gamma\|u\|_{\mathcal H^1}^2}(|\varphi(u)|+\|\nabla\varphi(u)\|_{\mathcal H^1})\right).
	\end{equation*}
    Moreover, there exists a  stationary solution $u^s$ of equation \eqref{eq NS} such that the pair $(u^s,\eta^s)$ is jointly stationary and
	\begin{equation}
	\law(u^s(t))=\mu\quad\forall\,t\in\R.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:hittingtime of arXiv:2607.08914, 'Linear spreading speed in non-monotone population models'] There are $0<v_1<v_2<\infty$ and $\Cl{c:htsmall},\Cl{c:htbig}\in(0,\infty)$
  such that for every $\eta_0$ which is non-zero only at the origin, every
  $x\in \mathbb{N}$, and $a>0$,
  \begin{equation*}
    \begin{split}
      \mathbb{P}_{\eta_0}(\tau_\mathrm{hit}(x)<x/v_2) &= 0,
      \\ \mathbb{P}_{\eta_0}(x/v_1 + a \le \tau_\mathrm{hit}(x)< \infty)
      & \le \Cr{c:htbig} e^{-\Cr{c:htsmall}\sqrt {x + av_1}}.
    \end{split}
  \end{equation*}

