[Lemma 3 of arXiv:2608.29316, 'Powers of the Dirac Operator on $S^1\times S^{n-1}$'] Let $\m(V)$ and $\nu(V)$ be the eigenvalues of $\a^0A$ and $A\a^0$ on $V$ type $K=\spin(2)\times\spin(n)$ finite space, respectively. Then, with respect to the diagrams
\begin{equation*}
\setlength{\extrarowheight}{7pt}
\left(\begin{array}{cc}
\frac{\m(V_{NW})}{\m(V_O)}&\frac{\m(V_{NE})}{\m(V_O)}\\
\frac{\m(V_{W})}{\m(V_O)}&\frac{\m(V_{E})}{\m(V_O)}\\
\frac{\m(V_{SW})}{\m(V_O)}&\frac{\m(V_{SE})}{\m(V_O)}\\
\end{array}\right)\text{ and }
\left(\begin{array}{cc}
\frac{\nu(V_{NW})}{\nu(V_O)}&\frac{\nu(V_{NE})}{\nu(V_O)}\\
\frac{\nu(V_{W})}{\nu(V_O)}&\frac{\nu(V_{E})}{\nu(V_O)}\\
\frac{\nu(V_{SW})}{\nu(V_O)}&\frac{\nu(V_{SE})}{\nu(V_O)}\\
\end{array}\right),
\end{equation*}
we get
\begin{equation*}
\setlength{\extrarowheight}{7pt}
\left(\begin{array}{cc}
\frac{-f+J+1+r+\Xi\e/2}{-f+J+1-r-\Xi\e/2}&\frac{f+J+1+r-\Xi\e/2}{f+J+1-r+\Xi\e/2}\\
\frac{-f+1/2+r-\Xi\e J}{-f+1/2-r+\Xi\e J}&\frac{f+1/2+r+\Xi\e J}{f+1/2-r-\Xi\e J}\\
\frac{-f-J+1+r-\Xi\e/2}{-f-J+1-r+\Xi\e/2}&\frac{f-J+1+r+\Xi\e/2}{f-J+1-r-\Xi\e/2}
\end{array}\right)\text{ and }
\left(\begin{array}{cc}
\frac{-f+J+1+r-\Xi\e/2}{-f+J+1-r+\Xi\e/2}&\frac{f+J+1+r+\Xi\e/2}{f+J+1-r-\Xi\e/2}\\
\frac{-f+1/2+r+\Xi\e J}{-f+1/2-r-\Xi\e J}&\frac{f+1/2+r-\Xi\e J}{f+1/2-r+\Xi\e J}\\
\frac{-f-J+1+r+\Xi\e/2}{-f-J+1-r-\Xi\e/2}&\frac{f-J+1+r-\Xi\e/2}{f-J+1-r+\Xi\e/2}
\end{array}\right).
\end{equation*}

