[Lemma bnevent of arXiv:2605.22787, 'Invariant measures for half-space geometric LPP: classification and the one force--one sol'] Fix $\varepsilon\in (0,1)$.
    There exists $\delta,\rho_0,R>0$ and $N\in \mathbb{N}$ all depending on $\varepsilon,q,c$ such that
 for all $n\ge N$ and $m \in \llbracket 0,\rho_0 n^{2/3}\rrbracket$, the following holds.
 \begin{enumerate}[label=(\roman*), font=\normalfont]
 \item  When $c\in [0,1)$,
     \begin{align}
        \mathbb P\left( L_{2}^n(m)+\frac{(j-m)q}{1-q} \ge L_{3}^n(j)+n^{1/3}\delta \mbox{ for all }j\in \llbracket0,m\rrbracket\right) \ge 1-\varepsilon,
    \end{align}
    and
    \begin{align}
        \mathbb P\left( \sup_{j\in \llbracket 0, n^{2/3}\rrbracket} L_{2}^n(j)-L_3^n(j) \le R n^{1/3}\right) \ge 1-\varepsilon.
    \end{align}
     \item  When $c\in [1,q^{-1})$,
     \begin{align}
        \mathbb P\left( L_{1}^n(m)+\frac{(j-m)q}{c-q} \ge L_{2}^n(j)+n^{1/3}\delta \mbox{ for all }j\in \llbracket0,m\rrbracket\right) \ge 1-\varepsilon.
    \end{align}
 \end{enumerate}

