[Proposition 22 of arXiv:2606.19115, 'Finite free perpetuities'] Fix \(a\geq 1\) and \(b\ge 1\). Then by Proposition \ref{prop:pff_shift_factorization}, $q_n=p_{n,(a,b)}$ satisfies \eqref{eq:fixedq} and by Proposition \ref{pro:conv_pn},
\begin{itemize}
    \item[(i)] $\meas{p_{n,(a,a+b)}}\weak  f\mathcal{B}'_{a,a+b}=:\mu_{\A}$,
    \item[(ii)] $\meas{q_n}\weak f\mathcal{B}'_{a,b}=:\mu_{\X}$.
\end{itemize}
Moreover, by Corollary \ref{cor:iterated_approximation} applied to  \eqref{eq:fixedq}, we obtain 
\begin{align}
\mu_\X = \mu_{\A}\boxtimes (\delta_1\boxplus \mu_{\X}).
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemm l:large-TF-is-uncompetitive of arXiv:2607.18194, 'Temperature chaos in directed polymers'] For $z,w\in J^\delta$, define the set of paths
    \begin{align*}
        \mathrm{BigTF}^\delta(z;w) \coloneqq  
        \left\{
            \pi \in C([0,\delta^{3/2}]) : \pi(0)=z,\quad \pi(\delta^{3/2})=w,\quad 
            \exists r\in[0,\delta^{3/2}]\text{ such that }
            \pi(r) \not\in J^{\delta'}
        \right\}.
    \end{align*}
    Define also the event
    \begin{align}
        {\mathsf{BigTFCostly}^{\delta}} \coloneqq  
        \left\{
            \inf_{z,w\in J^\delta}
            \left(
                \mathcal{L}(0,z;\delta^{3/2},w) - 
                \sup_{\pi\in \mathrm{BigTF}^\delta(z;w)}
                \int_0^{\delta^{3/2}} d\mathcal{L}\circ \pi
            \right)
            \geqslant 
            \delta^{1/2}\log^7(1/\delta)
        \right\}.
    \end{align}
    There exist $C,c>0$ such that for all sufficiently small $\delta$,
    \begin{align*}
        \mathbb{P}\left( {\mathsf{BigTFCostly}^{\delta}} \right)
        \geqslant 1- Ce^{-c\log^2(1/\delta)}.
    \end{align*}

