[Lemma 17 of arXiv:2609.00183, '2609.00183'] Assume $\Ord_{\phi,v}(0,R_0)\leq \Lambda$ and $\sup_{B_{\sigma_j}(0)}|\nabla u| \leq M$. For any $\theta\in (0,1)$, there exists $C>0$ depending only on $\theta$, $M$, $X$, and $\Lambda$ such that for all $x\in B_{R_0/64}(0)$ and all $0<R\leq R_0/16$, we have
    \begin{equation}
        \int_{B_{R/2}(x)\backslash B_{\theta R}(x)}\abs{|y-x|\pder[v]{r}-\BDOrd_{\phi,v}(x,r)v(y)}^2dy\leq CRI_{\phi,v}(x,R)(W_{\theta R/2}^R(x)+R^2).
    \end{equation}

[Lemma of arXiv:2605.28770, 'Cutoff profiles for conjugacy invariant random walks on symmetric groups'] Let $r\geq 1$. As $n\to \infty$ we have
    \begin{equation}
        n^{\downarrow r} = n^r \left( 1 - \frac{T(r-1)}{n} + O_r\left( \frac{1}{n^2} \right)\right).
    \end{equation}

[Theorem 50 of arXiv:2604.04267, 'On Sharpest Tail Bounds for Functions \\ of Tail Bounded Random Variables'] Let $f \in \mathcal{B}_2^n, \ V \subset \mathbb{R}^n$ be closed, $G \ni 0$ closed, and $c \in [0,1]^n$. Then
\begin{equation} 
 P(\mathscr{S}_2(f,G,c) \in V) \leq P\big(\mathscr{S}_2\big(f,\overline{\#_0(G \cap V)},c\big) \in V\big).
\end{equation}

