body:
[Maintheorem 3 of arXiv:2608.30077, 'Lie groupoid integration of singular isometries of the Poincaré disk'] The quotient
\begin{equation*}
\mathcal{G}_n\rightrightarrows \Dbarstar
\end{equation*}
is a Lie groupoid integrating
\begin{equation*}
A_n=\mathfrak{sl}_2(\mathbb R)\ltimes \Dbarstar.
\end{equation*}
Moreover, $\mathcal{G}_n\rightrightarrows \Dbarstar$ is not an action groupoid over $\Dbarstar$, but its restriction to the boundary is:
\begin{equation*}
\mathcal{G}_n|_{\partial \Dbarstar}
\cong
\psun\ltimes S^1 .
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 30 (Inverse Function Theorem) of arXiv:2608.30990, 'Convergence of symmetries: nilpotency, dimension, and perfectness'] Let $U \subset \mathbb{R}^n $ be an open set and $\Theta : U \to \mathbb{R}^n$ a differentiable function with  $\Theta ( 0 ) = 0 $ and 
    \begin{equation}
          \Vert \tfrac{\partial }{\partial t_j} \Theta (t_1, \ldots , t_n) - \text{e} _j  \Vert \leq \tfrac{1}{2n}        
    \end{equation}
    for all $j \in \{ 1, \ldots , n \}$ and  $ (t_1, \ldots , t_n) \in  U$. Assume $r > 0 $ is such that $[-r,r ] ^{\times n} \subset U$. Then for each $x\in B_{r/4}(0)$ there are unique  $t_1, \ldots , t_n \in (-r, r)$ such that 
    \[      \Theta ( t_1, \ldots , t_n ) = x.                       \]

[Theorem thm:clausius of arXiv:2605.17082, 'Spectral Purification in Reversible Markov Chains: Hidden Parameters, Observable Equivalen'] For every relaxation trajectory,
\begin{equation}
\sum_{k=0}^{\infty} D_{\mathrm{KL}}(p_{k+1} \| p_k)
\;=\; S_{\mathrm{spec}}(0) \;+\; \sum_{k=0}^{\infty} \frac{\mathrm{Cov}_{p_k}(\lambda^2,\; \log(1/p_k))}{\rho_k}.
\end{equation}

[Theorem 5 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the notation from Definition \ref{Def.ScaledLPPBot} and let $\hsai$ be as in Proposition \ref{Prop.PHSALE}. 
\begin{enumerate}
\item[(a)] If $c \in [0,1)$, then 
\begin{equation}
\left(\lpplenc_i(t): i \in \mathbb{N}, t \in [0,\infty) \right) \Rightarrow \left((2f)^{-1/2} \hsai_i(ft) - 2^{-1/2}f^{3/2}t^2 : i \in \mathbb{N}, t \in [0,\infty)\right).
\end{equation}
\item[(b)] If $c \in (1, q^{-1})$, then
\begin{equation}
\left(\lpplenc_{i+1}(t): i \in \mathbb{N}, t \in [0,\infty) \right) \Rightarrow \left((2f)^{-1/2} \hsai_i(ft) - 2^{-1/2}f^{3/2}t^2 : i \in \mathbb{N}, t \in [0,\infty)\right).
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop Prop_UniversalSpaceOfDiracBundles_TangentBundle of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] For every ${\mathbf{p}} = (g;\gamma,\nabla) \in \mathbf{Dir}$ the tangent space $T_{\mathbf{p}}\mathbf{Dir}$ decomposes into the tame Fréchet subspaces
  \begin{equation*}
    T_{\mathbf{p}}\mathbf{Dir} = H_{\mathrm{BG},{\mathbf{p}}} \oplus V_{\mathscr{G},{\mathbf{p}}} \oplus V_{\nabla,\mathrm{Uh};{\mathbf{p}}}
  \end{equation*}
  defined as follows:  
  \begin{enumerate}
  \item

    $H_{\mathrm{BG},{\mathbf{p}}}$ is the horizontal distribution at ${\mathbf{p}} \in \mathbf{Dir}$ of the \defined{Bourguignon--Gauduchon connection} [Bourguignon1992];
    that is:
    the unique Ehresmann connection on $\mathbf{Dir} \to \mathbf{Met}$ which horizontally lifts $\dot g \in T_g\mathbf{Met}$ to $(\dot g;\dot\gamma^\mathrm{BG},\dot\nabla^\mathrm{BG}) \in T_{\mathbf{p}}\mathbf{Dir}$ defined by
    \begin{equation*}
      \dot\gamma^\mathrm{BG}
      \coloneq
      \frac12 \sum_{i=1}^d \dot g(-,e_i) \gamma(e_i)

      \quad\text{and}\quad

      \dot\nabla^\mathrm{BG}      
      \coloneq \frac18 \sum_{i,j=1}^d \paren{\nabla_{e_i} \dot g}(e_j,-) [\gamma(e_i),\gamma(e_j)].
    \end{equation*}
    Here and throughout $(e_1,\ldots,e_d)$ denotes a local $g$--orthonormal frame.
  \item

    $V_{\mathscr{G},{\mathbf{p}}}$ is generated by the action of the \defined{gauge group} $\mathscr{G}(S) \coloneq \Gamma\paren{X,\mathrm{O}(S)}$ on $\mathbf{Dir}$;
    that is:
    \begin{equation*}
      V_{\mathscr{G},{\mathbf{p}}}
      \coloneq
      \set[\big]{
        (0;[\xi,\gamma],-\nabla\xi)
        :
        \xi \in \Gamma\paren{X,{\mathfrak o}(S)}
      }.
    \end{equation*}    
  \item

    $V_{\nabla,\mathrm{Uh};{\mathbf{p}}}$ consists of infinitesimal variations of the spin connection in Uhlenbeck gauge;
    that is:
    \begin{equation*}
      V_{\nabla,\mathrm{Uh};{\mathbf{p}}}
      \coloneqq
      \set[\big]{
        (0;0,\dot\nabla)
        :
        \dot\nabla \in \Omega^1\paren{X,{\mathfrak o}_{\mathrm{C\ell}}(S)} ~\textnormal{satisfying}~
        {\rm d}_\nabla^*\dot\nabla = 0
      }.
    \end{equation*}
    Here ${\mathfrak o}_\mathrm{C\ell}(S)$ denotes the bundle of skew-adjoint endomorphisms of $S$ which commute with the Clifford multiplication $\gamma$.
  \end{enumerate}
  In fact,
  the vertical tangent space $T_{\mathbf{p}}{\mathbf{Dir}}/{\mathbf{Met}}$ contains every infinitesimal variation of the spin connection;
  that is:
  \begin{equation*}
    V_{\nabla,{\mathbf{p}}}
    \coloneq
    \set*{
      ({\mathbf{p}};0;0,\dot\nabla) : {\mathbf{p}} \in \mathbf{Dir}, \dot\nabla \in \Omega^1\paren{X,{\mathfrak o}_{\mathrm{C\ell}}(S)}
    }
    \subseteq V_{\mathscr{G},{\mathbf{p}}} \oplus V_{\nabla,\mathrm{Uh};{\mathbf{p}}}.
    \qedhere
  \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] With the same assumptions and notations as in Theorem~\ref{th:convBessel},
assuming further that $\sup_{t\in[0,T]} \big\| m_0(F_t) \big\|_{L^\infty_{x}}$ is finite, the following holds:

\begin{itemize}
\item If $\sigma>0$, then for any $q\in [1,+\infty)$, there exists $C = C(q,d,\gamma,p,A,\sigma)>0$ such that for any $N\in \N^*$,
\begin{align*}
\Big(\E & \sup_{t\in[0,T]} \big\|u^{N}_t-u_t \big\|_{L^2_{x}}^{2q}\Big)^{\frac{1}{q}} + \Big(\E \Big|\int_{0}^{T} \big\| \nabla (u_{s}^{N}- u_{s}) \big\|_{L^2_{x}}^{2} \dd s \Big|^{q}\Big)^{\frac{1}{q}}\\
& \leq C \bigg( \big(\E \big\| u^{\circ,N}-u^\circ \big\|_{\gamma, p}^{2q}\big)^{\frac{1}{q}} +   \big(\E \big\| \langle v \rangle^{k} (F_{0}^{N}-\vartheta^N\ast F^\circ) \big\|_{L^{2}_{x,v}}^{2q}\big)^{\frac{1}{q}}\\
&\quad + N^{-2(\alpha-\beta)} +N^{-2\beta(\gamma-\frac{d}{p})} + N^{-(\frac{1}{2} - d\beta -(d+1)\alpha)} + \ratetilde^2 \bigg) + C \rate^2 .
\end{align*}

\item If $\sigma=0$, then for any $q\in [1,+\infty)$ and any $\varepsilon>0$, there exists $C = C(q,d,\gamma,p,A,\varepsilon)>0$ such that for any $N\in \N^*$,
\begin{align*}
\Big(\E & \sup_{t\in[0,T]} \big\|u^{N}_t-u_t \big\|_{L^2_{x}}^{2q}\Big)^{\frac{1}{q}} + \Big(\E \Big|\int_{0}^{T} \big\| \nabla (u_{s}^{N}- u_{s}) \big\|_{L^2_{x}}^{2} \dd s \Big|^{q}\Big)^{\frac{1}{q}} \\
& \leq C \bigg( \big(\E \big\| u^{\circ,N}-u^\circ \big\|_{\gamma, p}^{2q}\big)^{\frac{1}{q}} +   \big(\E \big\| \langle v \rangle^{k} (F_{0}^{N}-\vartheta^N\ast F^\circ) \big\|_{L^{2}_{x,v}}^{2q}\big)^{\frac{1}{q}} +\ratetilde^2 \\
&\quad + N^{-2(\alpha-\beta)} + N^{-2\beta(\gamma-\frac{d}{p})+\varepsilon} + N^{-(\frac{1}{2} - d\beta -(d+1)\alpha)}
\bigg) \, \frac{1}{1-\tilde\gamma} e^{CT\big(1+\sigma_{N}^{-2} + \sigma_{N}^{-\frac{1}{1-\tilde\gamma}}\big)}
 + C \rate^2.
\end{align*}

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Coro 2 (Case of $\Rr^d$) of arXiv:2609.01105, 'Obstruction to quasi-invariance of Gaussian measures under transport flows on Riemannian M'] Assume that~\((M,g)\) is the Euclidean space $\Rr^d$ equipped with the flat metric. Then the following statements are equivalent: 
\begin{enumerate}[(i)]
    \item Gaussian measure $\mu_\alpha$ is quasi-invariant under the flow of \eqref{eq:transport}; 
    \item Gaussian measure $\mu_{\alpha}$ is invariant under the flow of \eqref{eq:transport}, that is, for all $t \in \mathbb{R}$ there holds $\mu_\alpha^t = \mu_{\alpha}$;
    \item vector field $u$ is of the form $u(t,x)=a(t) x + b(t)$ for some $a \in L^1_{\rm loc}(\mathbb{R},A_d(\mathbb{R}))$, where~\(A_d(\Rr)\) is the set of skew-symmetric matrices, and $b \in L^1_{\rm loc}(\mathbb{R},\mathbb{R}^d)$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lem-subspace of arXiv:2506.18827, 'Random walk reflected off of infinity, with applications to uniform spanning forests and s'] Fix a finite, non-empty set $\mathcal A\subset\mathcal V\mathcal G$. 
Let
\begin{equation} 
  \mathring\Theta_{\mathcal A}  := \mathopen{}\mathclose\bgroup\originalleft\{ \theta \in \Theta : \text{$\theta = \nabla f$ for some $f : \mathcal V\mathcal G \to \mathbbm R$ with $f|_{\mathcal A} \equiv 0$} \aftergroup\egroup\originalright\} . 
\end{equation} 
Then $\mathring\Theta_{\mathcal A}$ is a closed linear subspace of $\Theta$. The orthogonal complement $\mathring\Theta_{\mathcal A}^\perp$ is described as follows. We say that $\eta \in \Theta$ is an \textbf{cycle modulo $\mathcal A$} if there exists a path $P : [0,N]\cap\mathbbm Z \to\mathcal V\mathcal G$ such that either $P(0) = P(N)$ or $P(0) , P(N) \in \mathcal A$ with the following property. For each $e = (x,y) \in \overrightarrow{\mathcal E}\mathcal G$, $\eta(e)$ is equal to the number of times $i$ such that $(P(i-1) ,P(i)) = (x,y)$ minus the number of times $i$ such that $(P(i-1), P(i)) = (y,x)$. Then $\mathring\Theta_{\mathcal A}^\perp$ is the closure of the linear span of the set of cycles modulo $\mathcal A$.

