[Theorem 6 (Solution of the SN Stein equation) of arXiv:2606.28678, '2606.28678'] Let $(\mathfrak{Y}_t)_{t\geq0}$ be the SOU process in \eqref{eq:SOU.process} with transition semigroup $(\mathcal{P}^{\mathrm{SOU}}_t)_{t\geq0}$, extended generator $\mathcal{A}_{M,\Psi,\Sigma}^{\mathrm{SOU}}$ given by \eqref{eq:SOU.generator}, and stationary limiting distribution $\gamma_{M,\Psi,\Sigma}$ from Proposition~\ref{prop:SOU.distribution}. For every test function $h$ belonging either to $C^{0,\beta}(\mathcal{S}^d)$ for some $\beta\in(0,1]$ or to $\mathrm{Lip}_{p}^{\mathrm{s}}(\mathcal{S}^d)$ for some $p\in\N_0$, the function
\begin{equation}
f_h(Y) \leqdef -\int_0^{\infty}\Big\{\mathcal{P}^{\mathrm{SOU}}_t h(Y)-\EE[h(\mathfrak{Y}_{\infty})]\Big\} \, \rd t, \qquad Y\in\mathcal{S}^d,
\end{equation}
is well defined pointwise and solves the SN Stein equation \eqref{eq:Stein.equation.symmetric.normal} in the pointwise sense, i.e., for every $Y\in\mathcal{S}^d$, $\lim_{s\downarrow0} \{\mathcal{P}_s^{\mathrm{SOU}}f_h(Y)-f_h(Y)\}/s = h(Y)-\EE[h(\mathfrak{Y}_{\infty})]$. Moreover, if $h\in C^{0,\beta}(\mathcal{S}^d)$ for some $\beta\in(0,1]$, then
\begin{equation}
|f_h(Y)|
\leq \frac{1}{\beta} [h]_{\beta,\mathcal{S}} \, d_{\mathrm{HK},\beta}^{\mathcal{S}}(\delta_Y,\gamma_{M,\Psi,\Sigma})
\leq \frac{1}{\beta}[h]_{\beta,\mathcal{S}} \Big\{\EE\big[\|\mathfrak{Y}_{\infty} - M\|_F^{\beta}\big] + \|Y - M\|_F^{\beta}\Big\},
\end{equation}
where $\delta_Y$ is the unit point mass at $Y$ and $\mathfrak{Y}_{\infty}\sim \gamma_{M,\Psi,\Sigma}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:manygoodblocks of arXiv:2607.08914, 'Linear spreading speed in non-monotone population models'] There exist $\varepsilon'>0$ and $c_0, r_1 \in \mathbb{N}$ such that for every
  $\ell, r\in \mathbb{N}$ with $r\ge r_1$, letting $n= r c_0 T_\mathrm{bl} \in \mathbb{L}_{\mathrm{time}}$,
  \begin{equation}

    \mathbb{P}_{\zeta }\Big( \exists z \in B_{\ell}(0) \cap \mathbb{L}_{\mathrm{space}} :
      \abs[\big]{ B^\mathrm{bl}_{r}(z) \cap W(\eta_n) }
      \ge \frac{1}{2} p_\nu V_r \Big)
    \ge \varepsilon'
  \end{equation}
  uniformly over all $\zeta  \in E^{\mathbb{Z}}$ such that
  $\{ x \in B_\ell(0) : \zeta (x) \neq0 \} \neq \emptyset$.

[Lemma 1 of arXiv:2607.24533, 'Colored Markov-Modulated Brownian Motion for Preemptive Workload Stacks'] Suppose that Assumptions~\ref{assump:intensity} and~\ref{assump:stability} hold, and let $\ell$ be a depleting color whose higher-color return operators have already been constructed. Define its accumulated active time and right-continuous inverse by
\begin{align*}
\kappa_\ell(t)&=\int_0^t\1_{\{A(s)=\ell\}}\,\dd s,
&
\gamma_\ell(u)&=\inf\{t\ge0:\kappa_\ell(t)>u\}.
\end{align*}
Up to depletion, the time-changed process
\begin{align*}
\widehat X_\ell(u)=X_\ell(\gamma_\ell(u)),
\qquad
\widehat J_\ell(u)=J(\gamma_\ell(u))
\end{align*}
is an MMBM with drift and volatility matrices $\vect\Delta_\mu^{(\ell)}$ and $\vect\Delta_\sigma^{(\ell)}$, and phase intensity matrix $\widetilde{\vect T}^{(\ell)}$. Its depletion time $\widehat\tau_0^{(\ell)}=\inf\{u\ge0:\widehat X_\ell(u)=0\}$ is almost surely finite, the corresponding real-time depletion epoch $\tau_0^{(\ell)}$ is almost surely finite, and $J(\tau_0^{(\ell)})=\widehat J_\ell(\widehat\tau_0^{(\ell)})$ almost surely. Moreover, for every $y>0$, $x>0$, and $j,k\in E$,
\begin{align*}
\E&\left[\int_0^{\tau_0^{(\ell)}}\1_{\{A(s)=\ell,\,J(s)=k,\,X_\ell(s)\in\dd x\}}\,\dd s\ \Big|\ A(0)=\ell,\,X_\ell(0)=y,\,J(0)=j\right]
\\
&=
\E\left[\int_0^{\widehat\tau_0^{(\ell)}}\1_{\{\widehat J_\ell(u)=k,\,\widehat X_\ell(u)\in\dd x\}}\,\dd u\ \Big|\ \widehat X_\ell(0)=y,\,\widehat J_\ell(0)=j\right],
\end{align*}
so the two occupation densities agree entry by entry as $p\times p$ matrices.

[Theorem 6 (Central limit theorem for the final stifler density) of arXiv:2609.00292, 'Extinction, Survival and Fluctuations for the Spatial Maki--Thompson Model on Infinite Gra'] There exists $\sigma_{\kappa}
        ^{2}>0$ such that
    \[
        |B_{n}|^{1/2}\bigl(\kappa_{n}-\kappa\bigr) \xrightarrow[n\to\infty]{d}
        \mathcal{N}(0,\sigma_{\kappa}^{2}).
    \] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem LUE right soft of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] ([cai2025mesoscopicratesconvergencehermitian], right soft edge) Consider an LUE $L_{a,N}$ such that $\lim\limits_{N\rightarrow\infty}\frac{N}{n}=\gamma\in(0,1]$ where $n:=N+a$. Let $I\subset[s,+\infty)$ for $s>-\infty$. Define parameters:
    \begin{equation*}
      \begin{array}{ll}
      \mu^R_{k,m}:=\left(\sqrt{k+\frac{1}{2}}+\sqrt{m+\frac{1}{2}}\right)^2,\\
      \sigma^R_{n,m}:=\left(\sqrt{k+\frac{1}{2}}+\sqrt{m+\frac{1}{2}}\right)\left(\left(k+\frac{1}{2}\right)^{-\frac{1}{2}}+\left(m+\frac{1}{2}\right)^{-\frac{1}{2}}\right)^{\frac{1}{3}},
      \end{array}
    \end{equation*}
\begin{equation*}
    \mu_R=\left(\frac{1}{\sqrt{\sigma_{n-1,N}^{R}}}+\frac{1}{\sqrt{\sigma_{n,N-1}^{R}}}\right)\left(\frac{1}{\mu^R_{n-1,N}\sqrt{\sigma_{n-1,N}^{R}}}+\frac{1}{\mu^R_{n,N-1}\sqrt{\sigma_{n,N-1}^{R}}}\right)^{-1}
\end{equation*}
and
\begin{equation*}
    \sigma_R=\left(\frac{\sqrt{\sigma_{n-1,N}^{R}}}{\mu^R_{n-1,N}}+\frac{\sqrt{\sigma_{n,N-1}^{R}}}{\mu^R_{n,N-1}}\right)\left(\frac{1}{\mu^R_{n-1,N}\sqrt{\sigma_{n-1,N}^{R}}}+\frac{1}{\mu^R_{n,N-1}\sqrt{\sigma_{n,N-1}^{R}}}\right)^{-1}.
\end{equation*}
Let $\mathcal{X}_{L_{a,N}}^{RS}$ denote the right-soft-edge-scaled point process for $L_{a,N}$ with the kernel $K_{L_{a,N}}^{RS}(x,y):=\sigma_{R}K_{L_{a,N}}(t_{R_{N}}(x),t_{R_{N}}(y))$ where $t_{R_N}(x):=\mu_{R}+\sigma_{R}x$ for any $x\in I$. Then on $A\subset I$, for any $s\in\mathbb{R}$, there exists an $n(s,\gamma)\in\mathbb{N}$ such that for any $N>n(s,\gamma)$,
\begin{equation}
    W_1(\mathcal{N}_{L_{a,N}}^{RS},\mathcal{N}_{Ai})\le\frac{g(s)e^{-s}}{N^{\frac{2}{3}}}
\end{equation}
for $g(s)$ some continuous non-increasing function of $s$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 109 (cf.\ Theorem \ref{T:Overlap} and {\cite[Theorem 1.1) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] {Mak24}}]
    Let $K_n$ be the complete graph and assume that $(\omega_e)_{e \in E}$ are independently uniformly distributed on $[0,1]$. Then for $\beta = \beta(n)$ the disorder strength, we have with high probability that
    \begin{equation*}
        \mathcal{O}(\beta) = 
        \begin{dcases}
            (1 + o(1)) \beta \frac{e^{2\beta} - 1}{(e^\beta - 1)^2} & \text{ if } 0 < \beta \ll n/\log n, \\
            (1 - o(1)) n & \text{ if } \beta \gg n (\log n)^2.
        \end{dcases}
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem vthm of arXiv:2411.18359, 'Large systems of symmetrized trapped Brownian Bridges and Schr\"odinger processes'] (Varadhan) Let ${\mathcal X }$ be a Hausdorff regular space and Suppose that the family $\mu_\epsilon$ satisfies the LDP with a good rate function $I:{\mathcal X } \to [0,\infty]$. Moreover, Let $Z_\epsilon$ be a family of ${\mathcal X }$ valued random variables and let $\phi:{\mathcal X } \to \mathbb{R}$ be any continuous function. Assume further either the tail condition
\begin{equation}
    \lim_{M\to \infty} \limsup_{\epsilon \to 0}\epsilon\log \mathbb{E}\big[e^{\frac{\phi(Z_\epsilon)}{\epsilon}}|\phi(Z_\epsilon)>M\big]=-\infty
\end{equation}
or the following moment condition for some $\gamma >1$
\begin{equation}
    \limsup_{\epsilon \to 0}\epsilon\log \mathbb{E}[e^{\frac{\gamma\phi( Z_\epsilon)}{\epsilon}}]<\infty
\end{equation}
then
\begin{equation}
    \lim_{\epsilon \to 0}\epsilon\log \mathbb{E}[e^{\frac{\phi( Z_\epsilon)}{\epsilon}}]=\sup_{x\in {\mathcal X }}\{\phi(x)-I(x)\}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

