body:
[Theorem 4 (Finite supercritical exit for $\beta_1=0$) of arXiv:2608.20638, 'Provable Edge-of-Stability for Adam on a One-Dimensional Quadratic'] Let $T\in\Nzero$ and let $\delta>0$ satisfy
\[
    2+\delta\le w_{\max}.
\]
Assume
\[
    \beta_1=0,
    \qquad
    w_T\ge 2+\delta,
    \qquad
    x_T\ne 0.
\]
Define
\begin{equation}
    N_{\delta,T}^{\mathrm{imp}}
    :=
    \min\left\{
        n\in\Npos:
        L_n(T,\abs{x_T})
        >
        \left(
            \frac{\eta}{2+\delta}-\varepsilon
        \right)^2
    \right\}.

\end{equation}
Then this minimum is finite and
\begin{equation}
    \tau_\delta(T)
    \le
    N_{\delta,T}^{\mathrm{imp}}
    \le
    N_{\delta,T}^{\mathrm{exp}}
    <\infty,

\end{equation}
where
\begin{equation}
    N_{\delta,T}^{\mathrm{exp}}
    :=
    1+
    \left\lfloor
    \frac{
        \log\!\left(
            1+
            \frac{
                (A_\delta-\beta_2)
                \left(
                    \dfrac{\eta}{2+\delta}-\varepsilon
                \right)^2
            }
            {(1-\beta_2)x_T^2}
        \right)
    }
    {\log A_\delta}
    \right\rfloor .

\end{equation}

[Definition def:circle-endpoint-exponent of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Define
\begin{equation}
A_{\mathrm{loc}}(W)
=
\sup_{q>1}
\max\left\{
0,\,
\frac{q-1-\log_2\mathbb{E}[W^q]}{q}
\right\},
\end{equation}
where the term corresponding to \(q\) is interpreted as \(0\) whenever \(\mathbb{E}[W^q]=\infty\).

[Lemma 27 of arXiv:2506.11937, 'Random rotational invariance of integration by parts formulas within a Bismut-type approac'] Let $\ g(\lambda, X) : \mathbb{R} \times M \rightarrow \mathbb{R}$ be an integrable function for all $\lambda$, differentiable with continuity with respect to $\lambda$ and such that $\mathbb{E}_{\mathbb{P}}[|\partial^2_{\lambda}g(\lambda,X)|]<\infty.$ Then
  \begin{equation*}
      \partial_{\lambda}\mathbb{E}_{\mathbb{P}}[g(\lambda,X)] = \mathbb{E}_{\mathbb{P}}[\partial_{\lambda}g(\lambda,X)].
  \end{equation*}

