\[
\limsup_{n\to\infty}
\frac{|S_n|}{A_n(2\log\log n)^{1/2}}
=1
\quad\text{a.s.}
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma E1 and E2 of arXiv:2412.08932, 'Gaussian heat kernel asymptotics for conditioned random walks'] For any $\varepsilon \in  [0, \frac{1}{2}]$ and $\gamma > 0$, 
there exists a constant $c>0$ such that for any $n \geqslant 1$ and $x \in \bb R$, 
\begin{align}
E_{x, n, \varepsilon} \leqslant  V(x)  \leqslant  \left( 1 + n^{-(1/2 - \varepsilon) \delta} \right) E_{x, n, \varepsilon}
 + c \frac{1 +V(x)}{n^{\gamma/8}}. 
\end{align}

[Lemma Lemma1.5ext of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] Let $\Lambda \subseteq \ensuremath{\mathbb{Z}^d}_n$ be a finite set and let $\nu \in \mathcal{P} ( \left\{ 0 , 1 \right\}^{\Lambda})$ be probability measure satisfying the three following assumptions:
        \begin{enumerate}
        \item[(i)] For any $x \in \ensuremath{\mathbb{Z}^d}_n \setminus \ensuremath{\mathbb{Z}^d},$ $\nu \left( r_x = 1 \right) = 1$;
        \item[(ii)] The marginal of $\nu$ on the set $\{0 , 1\}^{\Lambda \cap \ensuremath{\mathbb{Z}^d}}$ is strictly positive;
        \item[(iii)] For any vertex $x \in \Lambda \cap \ensuremath{\mathbb{Z}^d}$ and any configuration $r_1 \in \Lambda \setminus \{ x \}$ which is equal to $1$ on $\Lambda\setminus \ensuremath{\mathbb{Z}^d}$, one has the inequality
        \begin{equation*}
            \nu \left( r_x = 1 \, | \, r = r_1 ~ \mbox{in} ~ \Lambda \setminus \{ x \} \right) \leq p.
        \end{equation*}
        \end{enumerate}
        Then $\mathbb{P}_{\Lambda,p}$ stochastically dominates $\nu$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Def charge of arXiv:2607.19511, 'A Conditional Probability Hierarchy for Stochastic Choice\footnote{We thank Samson Abramsk'] Fix an arbitrary set $X$ and let $\cal E$ be a family of subsets of $X$.  A function $\mu : {\cal E} \rightarrow \mathbb{R}^+$ is a \textbf{positive real partial charge on} $(X, {\cal E})$ if:
\begin{equation}~
\sum_{i = 1}^m {\rm {\bf 1}}_{C_i} \leq \sum_{j = 1}^n {\rm {\bf 1}}_{D_j}
\end{equation}
pointwise on $X$, for any $C_i, D_j \in \cal E$, implies:
\begin{equation}~
\sum_{i = 1}^m \mu(C_i) \leq \sum_{j = 1}^n \mu(D_j).
\end{equation}

[Corollary cor:dense-grid-decay-centered-profiles-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Fix \(q\in(1,2)\) with \(\rho(q)<1\), and let
\(0<\beta<\beta_X(q)\).  Choose a grid parameter
\(\alpha_{\mathrm{gr}}>1\).  Let \(\Gamma_n(\alpha_{\mathrm{gr}})\) be the dense
grid from Definition~(def:dense-grids-paper of the paper).  Then, almost surely,
\begin{equation}
    \max_{\eta\in\Gamma_n(\alpha_{\mathrm{gr}})}
    |H_n(\eta)|
    \le
    2^{-\beta n}
\end{equation}
for all sufficiently large \(n\).

