[Definition 51 ({\cite[Definition 2.11) of arXiv:2607.18104, '2607.18104'] {ACH:ScalingASEP}}]
For a given family of Bernoulli paths $h^{\varepsilon}_0 \colon \Z \rightarrow \Z$, and $\varepsilon>0$, we define the \textbf{rescaled ASEP height function} $(y,t) \mapsto \hAeps(\hfix^{\varepsilon}_0;y,t)$ by
\begin{align*}
\hAeps(\hfix^{\varepsilon}_0;y,t) := \sigma(\alpha)^{-1}\varepsilon^{\frac{1}{3}}\Big(2\mu(\alpha)\varepsilon^{-1}t &+\mu^{\prime}(\alpha)\beta(\alpha)y\varepsilon^{-\frac{2}{3}} \\
&- \hA(h^{\varepsilon}_0,0;2\alpha t \varepsilon^{-1} + \beta(\alpha)y\varepsilon^{-\frac{2}{3}},2(1-q)^{-1}\varepsilon^{-1}t) \Big) 
\end{align*} whenever the argument for $\hA$ is an integer, and linear interpolation otherwise. Here, we obtain $\hfix^{\varepsilon}_0$ from $h^{\varepsilon}_0$ by the rescaling
\begin{equation}
    \hfix^{\varepsilon}_0(x) := \sigma(\alpha)^{-1}\varepsilon^{\frac{1}{3}}\Big(\mu^{\prime}(\alpha)\beta(\alpha)x\varepsilon^{-\frac{2}{3}} - h^{\varepsilon}_0(\beta(\alpha)x\varepsilon^{-\frac{2}{3}}) \Big).
\end{equation}

[Proposition prop1 of arXiv:2608.00295, 'Quadratic Perturbations of Markov Systems'] Let $A_1=	\begin{pmatrix}
a_1 & b_1\\
c_1 & d_1 
\end{pmatrix}$ and $A_2=	\begin{pmatrix}
a_2 & b_2\\
c_2 & d_2 
\end{pmatrix}$ be $2\times 2$ stochastic matrices, and $b_{1,2}=\begin{pmatrix}
\alpha_{1,2}^{(1)}\\
\alpha_{1,2}^{(2)}
\end{pmatrix}\in \mathbb{R}^2,$ $b_{2,1}=\begin{pmatrix}
\alpha_{2,1}^{(1)}\\
\alpha_{2,1}^{(2)}
\end{pmatrix}\in \mathbb{R}^2$ null-sum vectors. 
We define the nonlinear operator 

$$T(A_1,A_2;b_{1,2}, b_{2,1}):\mathbb{R}^2\times \mathbb{R}^2\to \mathbb{R}^2\times \mathbb{R}^2,$$ 
determined by 
\begin{equation}
T(A_1,A_2;b_{1,2},b_{2,1})\begin{bmatrix}
v_1\\
v_2
\end{bmatrix}=\begin{bmatrix}
A_1v_1+\langle v_1,v_2\rangle b_{1,2}\\
A_2v_2+\langle v_2,v_1\rangle b_{2,1}
\end{bmatrix}.
\end{equation}
The following are equivalent. 
\begin{enumerate}
\item For each of the four possible choices of $\pm$ sign of the null-sum vectors $b_{1,2}$ and $b_{2,1}$,  the maps $T(A_1,A_2;\pm b_{1,2}, \pm b_{2,1})$ induce  well defined nonlinear operators from $\Delta_1\times \Delta_1$ to $\Delta_1\times \Delta_1$. 
\item The entries of  $A_1$, $A_2$, $b_{1,2}$ and $b_{2,1}$ satisfy the  following inequalities
\begin{eqnarray}

\begin{aligned}
|\alpha_{1,2}^{(1)}|\leq \min \{a_1,b_1\},\\
|\alpha_{2,1}^{(1)}|\leq \min \{a_2,b_2\},\\
|\alpha_{1,2}^{(2)}|\leq \min \{c_1,d_1\}, \\
|\alpha_{2,1}^{(2)}|\leq \min \{c_2,d_2\}.
\end{aligned}

\end{eqnarray}
\end{enumerate}

