	\begin{equation}
		\frac{D H_t^{\psi_2^+}(x,y)}{H_t^{\psi_2^+}(x,y)}=I_1(x,y,t) +I_2(x,y,t),
	\end{equation}
	where $|I_1(x,y,t)|\lesssim t^{-3/2}$ and $I_2(x,y,t)\geq 0$.

