body:
[Prop p:chaos-expansion of arXiv:2607.18194, 'Temperature chaos in directed polymers'] Every square-integrable random variable $X\in L^2(\Xi,\mathcal{F},\mathbb{P})$ admits an $L^2(\Xi,\mathcal{F},\mathbb{P})$-orthogonal expansion (called a \emph{(Wiener) chaos expansion}) of the form
    \begin{align*}
        X = \sum_{n=0}^\infty I_n(f_n),
        \qquad\qquad f_n\in L^2(\mathbb{R}^{2n}),
    \end{align*}
    where the equality is as elements of $L^2(\Xi,\mathcal{F},\mathbb{P})$.

    For $X,Y\in L^2(\Xi,\mathcal{F},\mathbb{P})$ with chaos expansions $X=\sum_{n=0}^\infty I_n(f_n)$ and $Y=\sum_{n=0}^\infty I_n(g_n)$, 
    we have
    \begin{align}
        \mathbb{E}[XY] = \sum_{n=0}^\infty n! \langle\widetilde{f}_n, \widetilde{g}_n\rangle_{L^2(\mathbb{R}^{2n})},
    \end{align}
    by Parseval's identity and (l:properties-of-I of the paper)(orthogonality of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm lem:conv_muN_detailed of arXiv:2606.24385, 'Gradient Mean-Field Dynamics with Measure-Valued States: Well-Posedness, Chaos, and Long-T'] Suppose that (A1 of the paper)-(A8 of the paper) hold true. Let $({\mathcal X}(t),{\boldsymbol{\lambda}}(t))$ be the unique strong solution to (equation system2 of the paper) in ${\mathcal{M}}_{\rm ad}^2(\hat{\mathscr Y}^N)$ with initial condition $\overline{{\boldsymbol Y}}_{0}\in L^{2}(\hat{{\mathscr Y}}^{N})$. Then there exists a unique measure-valued process
\begin{align}
\mu_{\cdot} \in C([0,T]; {\mathscr{P}}_1({\mathscr Y})\cap {\mathscr{P}}_{2}({\mathscr Y}))    
\end{align}
satisfying the nonlinear McKean--Vlasov SDE
\begin{align}
\begin{dcases}
{\rm d} Y(t) &= H(Y(t), \Lambda(t), \mu(t)) \, {\rm d} t + \sqrt{2\sigma_x} \, {\rm d} B(t),\\
{\rm d} \Lambda(t) &= {\mathbb R}(Y(t), \Lambda(t), \mu(t)) \, {\rm d} t + \sqrt{2\sigma_\lambda} \, \Pi_{\Lambda(t)} \, {\rm d} W^Q(t),\\
\mu(t)&={\rm law}(Y(t),\Lambda(t)),
\end{dcases}
\end{align}
with initial law $\mu_0 = \mathcal L(\overline{X}^1_0, \overline{\lambda}^1_0)$. Moreover, the empirical measure $\mu^N_t$ converges in expectation of the Wasserstein-1 distance to $\mu(t)$:
\begin{align}
\lim_{N\rightarrow +\infty}\sup_{t \in [0,T]} {\mathbb E} \big[{\mathcal W}_1(\mu^N(t), \mu(t)) \big] =0.
\end{align}
In particular, the system (equation system2 of the paper) is \emph{chaotic with limit law $\mu(t)$ in the sense of (defn:propchaos of the paper)}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 44 (Functional Santal\'o inequalities on $\operatorname{RCD}(K, \infty)$-spaces) of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $(X,d,\mu)$ be an $\operatorname{RCD}(K,\infty)$ probability space for some $K > 0$. For any pair of measurable functions $f, g: X \to [0,\infty)$ and any non-decreasing measurable function $W: \R_+ \to (0, \infty)$ satisfying the pointwise relation
    \begin{equation}

    f(x)^{\frac{1}{2}} g(y)^{\frac{1}{2}} \leq W\left(\frac{d(x,y)}{2}\right) \quad \text{for all } x, y \in X,
    \end{equation}
    one has the functional inequality
    \begin{equation}

    \left( \int_X f(x) \, d\mu(x) \right)^{\frac{1}{2}} \left( \int_X g(y) \, d\mu(y) \right)^{\frac{1}{2}} \leq  \int_{\R} W\left(\frac{|r|}{\sqrt{K}}\right) \, d\gamma(r).
    \end{equation}

