body:
[Lemma 21 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $p\geq 2$ and let $(X_N=I_p(f_N), N\geq 1)$ 
		satisfy \eqref{c1}. Let $Y_N=I_q(g_N)$ with 
		$ap\leq q<(a+1)p$ for some integer $a\geq 1$, and 
		$\sup_N\|g_N\|_{H^{\otimes q}}<\infty$. Define 
		recursively $h_{0,N}:=g_N$ and, for $r=1,\ldots,a$:
		\begin{equation}
			h_{r,N} := \frac{f_N\otimes_p h_{r-1,N}}
			{\|f_N\|^2_{H^{\otimes p}}}\in H^{\odot(q-rp)},
		\end{equation}
		and
		\begin{equation*}
			g_{r,N}^{(2)} := h_{r-1,N} 
			- \frac{(q-(r-1)p)!}{p!(q-rp)!}
			f_N\widetilde\otimes h_{r,N},
			\qquad
			\varepsilon_{r,N} := I_{q-(r-1)p}(g_{r,N}^{(2)}),
		\end{equation*}
		so that $f_N\otimes_p g_{r,N}^{(2)}=0$ for each 
		$r=1,\ldots,a$. Then for every $N\geq 1$, in the 
		\textbf{non-critical case} $ap<q<(a+1)p$:
		\begin{equation}
			Y_N = \sum_{r=1}^a \frac{X_N^r}{p^r\sigma^{2r}}
			Y_{r,N} + \varepsilon_N + r_N,
		\end{equation}
		and in the \textbf{critical case} $q=ap$:
		\begin{equation}
			Y_N = \sum_{r=1}^{a-1}\frac{X_N^r}{p^r\sigma^{2r}}
			Y_{r,N} + \frac{\rho_a}{p^a\sigma^{2a}}X_N^a 
			+ \varepsilon_N + r_N,
		\end{equation}
		where in both cases $\varepsilon_N$ is asymptotically 
		independent of $X_N$ and $r_N\to 0$ in $L^2(\Omega)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem all-near-giant of arXiv:2606.01627, 'The geometry of the giant component of random geometric graphs'] Fix $\beta >0$ and $\lambda_0 > \lambda_c$.      There are constants $c = c(\lambda_0,d,\beta,M) > 0$ and $n_0 = n_0(\lambda_0,d,\beta,M)$ so that if $r \leq n^{-\beta}$ and $\lambda \geq \lambda_0$ then the event \begin{equation*} \mathcal{B} = \left\{\text{for all } y \in M, d_M(y,\mathring{y}) \leq r \log^2 n \right\}
    \end{equation*}
    satisfies $\mathbb{P}(\mathcal{B}^c) \leq \exp(-c \log^2 n)$ for all $n \geq n_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

