body:
[Proposition prop:diff-coker of arXiv:2609.00233, 'A survey on mapping class groups of 3-manifolds'] There is an exact sequence
\begin{multline*}
\bigoplus_i \pi_1 \Diff^+(T_i) \xrightarrow{\sum_i \iota_i} \pi_0 \overline{\Diff}^+(M,(B_h),(T_i),(M_j)) \rightarrow \\
 \rightarrow \pi_0 \overline{\Diff}^+(M,(B_h),(T_i),(M_j)) \Big/ \bigoplus_i \pi_1 \Diff^+(T_i) \rightarrow 1
\end{multline*}
where $\pi_1 \Diff^+(T_i) \cong \pi_1 \Diff^+(T^2) \cong \mathbb Z^2$ for every $i$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 3 (Conditional propagation of chaos) of arXiv:2606.14170, 'Uniform-in-time error estimates for McKean-Vlasov SDEs with common noise and stochastic al'] Let $X_0^{i,N}=X_0^i$ for all $i\in\mathbb{S}_N$. Suppose that Assumptions \ref{A1} and \ref{A2} hold and that $\sigma_0\sigma_1\neq 0$. Then there exists a constant $C>0$ such that for any $t>0$ and $i\in\mathbb{S}_N$, 
\begin{align*}
\mathcal{W}_1\big(\mathcal{L}(\mu_t^i),\mathcal{L}(\nu_t^{i,N})\big)\le C\psi(N),
\end{align*}
in the case of $\mathbb{E}|X_0^i|^q<\infty$ for some $q>1$, where $\mu_t^i=\mathcal{L}(X_t^i\vert \mathcal{F}_t^W)$ stands for the regular conditional distribution of $X_t^i$, determined by \eqref{NIPS}, $\nu_t^{i,N}=\mathcal{L}(X_t^{i,N}\vert \mathcal{F}_t^W)$ stands for the conditional distribution of $X_t^{i,N}$, determined by \eqref{IPS} with $\widetilde{b}(x,\mu)=b(x,\mu), \theta_t=\overline\theta_t=t$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 6 of arXiv:2605.03100, 'Berry-Esseen bounds for multivariate martingale difference sequences in the Kolmogorov dis'] \cite[Lemma 2.3]{fang2021highdimensional}
For every $\mathcal{A} \in \mathscr{H}_d$, $\sigma>0$ and $\bm{x} \in \mathbb{R}^d$, define
\begin{align}
\varphi_{\mathcal{A},\sigma}(\bm{x}) = \mathbb{P}_{\eta \sim \mathcal{N}(\bm{0},\bm{I}_d)}(\bm{x} + \sigma\bm{\eta} \in \mathcal{A}).
\end{align}
Then it can be guaranteed that for every $s \in \mathbb{N}_+$, there exists a constant $C_s$ depending only on $s$, such that
\begin{align*}
\|\nabla^s \varphi_{\mathcal{A},\sigma}(\bm{x})\|_1 \leq C_s\sigma^{-s}\log_+^{\frac{s}{2}} d.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 134 (Theorem 6.4 \cite{Kr_26_1}) of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Let $ \alpha>0,q_{1},q_{2}\in(1,\infty),q>\max(q_{1},q_{2})$, $k>0$, $b(t,x)\geq0$. Then for any $f(t,x)\geq0$
\begin{equation}

\|bP_{\alpha,k}f\|_{L_{q_{1},q_{2}}}
\leq N\|b\|_{\dot E_{q,q,\alpha} }
\|f\|_{L_{q_{1},q_{2}}},
\end{equation}
where $N$ depends only on $d,q_{i},q,\alpha,k$.
In particular, for any $u\in C^{\infty}_{0}$
\begin{equation}

\|b Du \|_{L_{q_{1},q_{2}}}
\leq N\|b\|_{\dot E_{q,q,1} }K,
\quad \| b u\|_{L_{q_{1},q_{2}}}
\leq N\|b\|_{\dot E_{q,q,2} }K,
\end{equation}
where $K=\|D^{2}u,\partial_{t}u\|_{L_{q_{1},q_{2}}}$
and $N$ depends only $d,q_{i},q$. (Proof in the paper; no proof environment follows the statement in the TeX.)

