[Thm 3 (Theorem~\ref{thm:cond prob Fredholm pf empty} in the main text) of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] Let $N>0$ be a fixed even integer. Let $\Psi(x,y)=Q_{1,1}(x,y)$ with $Q$ defined in \eqref{eq:Qintro}, and let $\Phi_0(x),\dots,\Phi_{N-1}(x)$ be a family of polynomials where $\Phi_k$ is of degree $k$. Assume that these polynomials satisfy the following skew-biorthogonality relations:
    \begin{align}
        \begin{split}
            \sum_{x,y=1}^\infty \Phi_{2i}(x) \Psi(x,y) \Phi_{2j}(y) & = 0, \\
            \sum_{x,y=1}^\infty \Phi_{2i+1}(x) \Psi(x,y) \Phi_{2j+1}(y) & = 0, \\
            \sum_{x,y=1}^\infty \Phi_{2i}(x) \Psi(x,y) \Phi_{2j+1}(y) & = -\delta_{i,j},
        \end{split}
    \end{align}
    for all $0\leq i,j< N/2$. Furthermore, for a fixed integer $m\geq 0$, let $\{p_1,\dots,p_m\}\subseteq\{1,\dots,N\}$ be indices denoting particle labels such that $p_1<p_2<\cdots<p_m$. Then the half-line TASEP with empty initial conditions has conditional joint distribution given by a Fredholm Pfaffian of the form
    \begin{equation}
        \mathbb{P}\left[\bigcap_{k=1}^m \left\{X_{t}(p_k) > a_k\right\} \given \abs{X_t} = N\right] = \pf\left(J - \bar\chi_a K\bar\chi_a\right)_{\ell^2(\{p_1,\dots,p_m\}\times \mathbb{N})},
    \end{equation}
    where $\bar\chi_a(p,x) = \mathbbm{1}_{x\leq a_p}$ and $a_1,\dotsc,a_k\geq0$. The correlation kernel $K$ is given explicitly in terms of the $\Phi_{i}(x)$ polynomials in Section~\ref{se:EmptyIC}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2608.27569, 'Laplace and Dolbeault operators on Sasakian manifolds'] Let $(M^{2n+1},g,\xi )$ be a compact Sasakian
manifold. For $0\leq r,s\leq n$ and $t\in \{0,1\}$, let $H_{\overline{
\partial }}^{r,s,t}\left( M\right) $, respectively $H_{\partial
}^{r,s,t}\left( M\right) $, be the cohomology groups defined by
\begin{equation*}
H_{\overline{\partial }}^{r,s,t}\left(M\right) =\frac{\ker(\overline{
\partial }:\Omega ^{r,s,t}\rightarrow \Omega ^{r,s+1,t})}{\limfunc{im}
(\overline{\partial }:\Omega ^{r,s-1,t}\rightarrow \Omega ^{r,s,t})},~\text{
respectively }H_{\partial }^{r,s,t}\left( M\right) =\frac{\ker (\partial
:\Omega ^{r,s,t}\rightarrow \Omega ^{r+1,s,t})}{\limfunc{im}(\partial :\Omega
^{r-1,s,t}\rightarrow \Omega ^{r,s,t})}.
\end{equation*}
Then the natural map $\Omega^{r,s,t}\to  H_{\bullet
}^{r,s,t}\left( M\right); \omega \mapsto \left[ \omega \right] $ induces isomorphisms 
\begin{eqnarray*}
\mathcal{H}_{\overline{\partial }}^{r,s,t} &=&\ker (\Delta _{\overline{
\partial }}^{r,s,t})=\ker (\left. \overline{\partial }\right\vert _{\Omega
^{r,s,t}})\cap \ker (\left. \overline{\partial }^{\ast }\right\vert _{\Omega
^{r,s,t}})\cong H_{\overline{\partial }}^{r,s,t}\left( M\right) , \\
\mathcal{H}_{\partial }^{r,s,t} &=&\ker (\Delta _{\partial }^{r,s,t})=\ker
(\left. \partial \right\vert _{\Omega ^{r,s,t}})\cap \ker (\left. \partial
^{\ast }\right\vert _{\Omega ^{r,s,t}})\cong H_{\partial }^{r,s,t}\left(
M\right) ,
\end{eqnarray*}
which may be infinite dimensional. There is a countable set of charges $q\in 
\mathbb{R}$ such that the $iq$-eigenspace $\Omega ^{r,s,t}(q)$ of $\mathcal{L
}_{\xi }$ on $\Omega ^{r,s,t}$ is nonzero, and the spaces above are Hilbert
sums of the spaces
\begin{eqnarray*}
\mathcal{H}_{\overline{\partial }}^{r,s,t}(q) &=&\ker (\left. \Delta _{
\overline{\partial }}\right\vert _{\Omega ^{r,s,t}(q)})\cong H_{\overline{
\partial }}^{r,s,t}\left( q\right) , \\
\mathcal{H}_{\partial }^{r,s,t}(q) &=&\ker (\left. \Delta _{\partial
}\right\vert _{\Omega ^{r,s,t}(q)})\cong H_{\overline{\partial }
}^{r,s,t}\left( q\right) ,
\end{eqnarray*}
all of which are finite dimensional. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 (Multivariate hard-edge determinant field) of arXiv:2608.27641, 'Hard-Edge Determinant Fields and Second-Moment Universality for Random Matrix Ratios'] Under the assumptions above, there exists a random element
\[
Q_{\boldsymbol{\Sigma}}
\in
\operatorname{Hol}\left(\mathbb{C}^r\right)
\]
such that
\begin{equation}
Q_{\boldsymbol{\Sigma}}^{[K]}
\overset{\mathbb{P}}{\rightarrow}
Q_{\boldsymbol{\Sigma}}
\quad
\text{in }
\operatorname{Hol}\left(\mathbb{C}^r\right),
\qquad
Q_n
\overset{\mathrm{d}}{\rightarrow}
Q_{\boldsymbol{\Sigma}}
\quad
\text{in }
\operatorname{Hol}\left(\mathbb{C}^r\right).

\end{equation}
Moreover,
\(
Q_{\boldsymbol{\Sigma}}\left(\boldsymbol{0}\right)=1
\text{ almost surely}.
\)

For every nonzero
\(\boldsymbol{v}\in\mathbb{C}^r\), define
\[
\sigma_{\boldsymbol{v}}^2
:=
\boldsymbol{v}^\top
\boldsymbol{\Sigma}
\overline{\boldsymbol{v}}.
\]
Then \(\sigma_{\boldsymbol{v}}>0\), and
\begin{equation}
Q_{\boldsymbol{\Sigma}}
\left(\,\cdot\,\boldsymbol{v}\right)
\overset{\mathrm{d}}{=}
Q\left(
\sigma_{\boldsymbol{v}}\,\cdot
\right)
\qquad
\text{in }
\operatorname{Hol}\left(\mathbb{C}\right),

\end{equation}
where \(Q\) is the scalar limiting entire function from
Theorem~\ref{thm:determinant-field}. Consequently,
\[
\mathcal{Z}\left(
Q_n\left(\,\cdot\,\boldsymbol{v}\right)
\right)
\overset{\mathrm{d}}{\rightarrow}
\sum_{Z\in\operatorname{Gin}_{\infty}}
\delta_{Z/\sigma_{\boldsymbol{v}}}
\qquad
\text{in }
\mathcal{N}\left(\mathbb{C}\right).
\]

[Lemma lem:estimateoffro of arXiv:2604.22510, 'Asymptotics of Multi-Scale McKean--Vlasov Diffusions with Super-Linear Kernels: a Lifted S'] For any $p\geq 2$, there exist constants $\beta, C_p>0$ such that for any $\mu\in\mathscr{P}_{\kappa}({\mathbb R}^n)$, $\gamma\in\mathscr{P}_p({\mathbb R}^m),y\in{\mathbb R}^m$,
	\begin{equation}
		\sup_{t\geq 0}\tilde {\cal E}|Y_{t}^{\mu,\gamma}|^p\lesssim_p(1+M_p(\gamma)),
	\end{equation}	
	\begin{align}
		\tilde {\cal E}|Y_{t}^{\mu,\gamma,y}|^p\leq e^{-\beta t}|y|^p+C_{p}(1+M_p(\gamma)).
	\end{align}

