[Thm box-crossing of arXiv:2605.14910, 'Sharp Phase Transition for the Formation of Infinite Tubes'] Let $1\le k\le d-1$.
  Then the following statements hold$:$
  \begin{enumerate}
    \item If $p<p_c^{\mathrm{tube}}$, then for every $w>0$,
    \[
    \lim_{n\to\infty}\mathbb{P}_p(\mathcal{H}_{w,n})=0;
    \]
    \item If $p>p_c^{\mathrm{tube}}$, then for all sufficiently large $w>0$ $($depending on $p$$)$,
    \[
    \lim_{n\to\infty}\mathbb{P}_p(\mathcal{H}_{w,n})=1.
    \]
  \end{enumerate}
  In particular,
  \[  \lim_{w\to\infty}\lim_{n\to\infty}\mathbb{P}_p(\mathcal{H}_{w,n})=
  \begin{cases}
    0     &\text{$p<p_c^{\mathrm{tube}}$,}\\
    1     &\text{$p>p_c^{\mathrm{tube}}$.}
  \end{cases}
  \] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 25 of arXiv:2607.28614, 'Tampered Memory Elephant Random Walk on one-dimensional integer lattice'] Let $\br_{ \mu{n}}$ be the error as in \eqref{Eq: error_vector}. Then, as $n \to \infty$, 
\begin{equation}

(n+1)\E \left[\lVert \br_{ \mu{n}} \rVert^2\right] \rightarrow 0,
\end{equation}
and 
\begin{equation}

\sum_{k=1}^n \br_{ \mu{n}} = o\left(\sqrt\frac{n}{\log n}\right), \text{ a.s.} 
\end{equation} 
Furthermore, if $\rho^*<\frac{1}{2}$ then for any $0< \delta_0< \frac{1}{2}$, 
\begin{equation}

\sum_{k=1}^n \br_{ \mu{n}} = o\left(n^{1-\rho^* -\delta_0}\right), \text{ a.s.} 
\end{equation}

[Lem decconditions of arXiv:2412.09535, 'Local limit theorem for joint subgraph counts'] Suppose there is a nonempty subset $\mathcal{H}' \subseteq \mathcal{H}$ and some $\eps > 0$ such that
\begin{cond}
    \item  \label[scond]{scond:g1} We have one of the following:
    \begin{cond}
        \item  \label[scond]{scond:g1a} $\Delta^2_H N_{H, e} \leq n^{-\eps}$ for all $H \in \mathcal{H}'$ and $e \in A$;
        \item  \label[scond]{scond:g1b} For $e \in A$ we always have
        \[\abs*{\sum_{H \in \mathcal{H}'} \Delta_H \;\smashoperator{\sum_{\substack{H'\cong H \\ E(H') \cap A = \set{e}}}} \zeta_{E(H') \setminus A}} \leq 1.1\pi\sqrt{p(1-p)}.\]
    \end{cond}
    \item  \label[scond]{scond:g2} $\sum_{H \in \mathcal{H}'} \sum_{e \in A} \Delta^2_H N_{H, e} \geq n^\eps$;
    \item  \label[scond]{scond:g3} $\sum_{e \in A}  \Delta^2_H N_{H, e} \leq n^{-\eps}$ for all $H \in \mathcal{H} \setminus \mathcal{H}'$;
    \item  \label[scond]{scond:g4} $\sum_{\abs{S} \geq 2} \Delta^2_H N_{H, S} \leq n^{-\eps}$ for all $H \in \mathcal{H}$;
    \item  \label[scond]{scond:g5} We have
    \[\sum_{(H_1,H_2,H_3,H_4) \in Q} \Delta_{H_1}\Delta_{H_2}\Delta_{H_3}\Delta_{H_4} \leq n^{-\eps} \paren*{\sum_{H \in \mathcal{H}'} \sum_{e \in A} \Delta^2_H N_{H, e}}^2,\]
    where $Q$ is the set of quadruples $(H_1,H_2,H_3,H_4)$ of subgraphs such that
    \begin{cond}
        \item  \label[scond]{scond:g5a} $H_1, H_2, H_3, H_4$ are isomorphic to elements of $\mathcal{H}'$ and are rainbow ($\Delta_{H_i}$ denotes $\Delta_H$ where $H\in\mathcal{H}'$ is isomorphic to $H_i$);
        \item  \label[scond]{scond:g5b} $E(H_1) \cap A = E(H_2) \cap A = \set{e}$ for some $e \in A$;
        \item  \label[scond]{scond:g5c} $E(H_3) \cap A = E(H_4) \cap A = \set{e'}$ for some $e' \in A$;
        \item  \label[scond]{scond:g5d} $(E(H_1) \cup E(H_2)) \cap (E(H_3) \cup E(H_4))$ is nonempty;
        \item  \label[scond]{scond:g5e} No edge lies in exactly one of the $E(H_i)$.
    \end{cond}
\end{cond}
Then $\sete_{G(n,p)}[e^{if}] = n^{-\omega_{\lambda,\ell,\eps}(1)}$.

[Lemma 5 (Stability under the parameter shifts) of arXiv:2608.30304, '2608.30304'] Let $s_0=A_0+\tfrac12$. If $n\ge1$, $S\ge s_0$ and $j\in\{1,2\}$, then
\begin{equation}
 \mathcal E_{n-1}(S+j)\le1.4\,\mathcal E_n(S).
\end{equation}

[Lemma 28 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] Assume \eqref{H1}. Then for any $\delta>0$, uniformly for $1\le k\le q_n(h^*)$, $j\in [\delta n,\, h(q_n)-\delta n]$ and $1\le m\le k$, 
    \begin{align}
        \p_n\big(X^{(k)}_{j-1} \le m-1 \,\big|\, X^{(k)}_j = m\big) \lesssim \frac{m^2}{n}.
    \end{align}

