[Dfn 7 ($\BL^{\kappa}$ metric) of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Let $(X,d^X)$ be a metric space and define $\calM(X)_{\mathrm{fin}}$ by
\begin{equation*}
    \calM_{\mathrm{fin}}(X):=\{\mu:\mu\;\mathrm{is\;a\;finite\;Radon\;measure\;on\;}X\}.
\end{equation*}
For $\kappa\in (0,1]$, we define a function $d_{\BL^{\kappa}}^X$ on $\calM(X)_{\mathrm{fin}}\times \calM(X)_{\mathrm{fin}}$ as follows.
\begin{align}
  d_{\BL^{\kappa}}^X(\mu,\nu):=\sup\left\{ \left| \int_X f d(\mu-\nu)\right|:\|f\|_{\BL^{\kappa}(X)}\leq 1 \right\}\in [0,\infty],\quad \mu,\nu\in \calM(X)_{\mathrm{fin}}.
\end{align}

[Prop 16 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] Let $M>0$ and suppose there is a sequence $(u_l,w_l)_{l\ge 1}$ in $\mathcal{S}_{M,rad}$ satisfying
\begin{equation}
	\lim_{l\to\infty} \mathcal{L}(u_l,w_l) = -\infty\,.
\end{equation} 
Then $M=M_c$.

