body:
[Lemma 6 of arXiv:2608.21255, 'Laws of the iterated logarithm for random Dirichlet series with general weights'] Let $(a_k)$ be as defined in \eqref{a_k_1}, $s_n=2^{-1}\eee^{-n^2}$ for $n\in\mn$. Assume that $\eta$ has an arbitrary distribution with mean zero and variance $\sigma^2\in (0,\infty)$. Then
    \begin{equation}
        v(s_n)={\rm Var}[X(s_n)] 
        ~\sim~\sigma^2\eee^{n^2-1},\quad n\to\infty
    \end{equation}
and 
\begin{equation}
\lim_{n\to\infty}\big(\eee^{-n^2/2+s_n\log\lfloor k_n\rfloor}X(s_n)-\eta_{\lfloor k_n\rfloor}\big)=0,\quad \text{{\rm a.s.}}
\end{equation}

