[Lemma mgf-above-n-asymptotic of arXiv:2504.02207, 'Finite-Time behaviors of M/M/$n$ Queue: Mixing Time, Mean Queue Length and Tail Bounds'] Let $\delta$ be a given positive real number, $n \geq 2$ be a positive integer and denote $\lambda = n-n^{1-\alpha}$ where $\alpha \in (0,+\infty)$. We have
    \begin{align}
        \frac{1}{n^\alpha \br{1-\br{\frac{\lambda}{n}}^{\frac{\delta}{\delta+1}}}} \leq 1 + \frac{1}{\delta}.
    \end{align}
    Moreover, we also have
    \begin{align}
        \lim_{n \rightarrow \infty} \frac{1}{n^\alpha \br{1-\br{\frac{\lambda}{n}}^{\frac{\delta}{\delta+1}}}} = 1 + \frac{1}{\delta}.
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition p:diffeo_conjugation of arXiv:2606.11503, 'Percolation on hierarchical lattices'] Let $U, \tilde{U} \subset \mathbb{R}$ be open sets and consider a $C^{k+1}$ diffeomorphism $f:U \to \tilde{U}$, for some $k \geq 1$. Assume there exists $u_{\star} \in U$ such that $f(u_{\star}) = u_{\star}$ and such that $\zeta = f'(u_{\star})$ satisfies $|\zeta| \neq 1$. There exists a $C^{k}$ diffeomorphism $h: V \to \tilde{V}$ between open neighborhoods of $u_{\star}$ and the origin such that $h(u_{\star}) = 0$ and such that
\begin{equation}
f(x) = h^{-1} \Big( \zeta h(x) \Big), \quad \text{for all } x \in V.
\end{equation}
Furtheremore, the diffeomorphism $h$ is unique up to multiplication by constants. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2512.09308, 'On asymptotic behavior of solutions to random fractional Riesz-Bessel equations with cycli'] [seneta2006regularly]
A function $L(\cdot)$ is slowly varying at infinity if it is real-valued, positive, and measurable on $[A,\infty)$ for some $A>0$, and satisfies the following condition for every $\lambda >0$:
\begin{equation*}
    \lim_{x\to \infty} \frac{L(\lambda x)}{L(x)}=1.
\end{equation*}

[Lem 9 of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] For all $p \in (0,1)$,
\begin{align*}
    p(1-p)\sqrt{\frac{2\beta_p}{1 - 2p}} \le \frac{1}{2},
\end{align*}
with equality if and only if $p = 1/2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:properties-Phi-Pi of arXiv:2606.21556, 'Mean field limit of non-exchangeable interacting diffusions on co-evolutionary networks'] Under Assumption (assump:plasticity-function of the paper) on the plasticity function \(\Gamma\), there exists a unique continuous map \(\Phi: [0,T]\times \mathcal{C}^d_T \times \mathcal{C}^d_T \times \mathbb{R} \to \mathbb{R}\) such that for any \(\gamma_1,\gamma_2 \in \mathcal{C}^d_T\) and any \(w \in \mathbb{R}\), the function \(t\mapsto \Phi(t,\gamma_1,\gamma_2,w)\) is the unique solution to the initial value problem:
	\[
		\begin{aligned}
		&\frac{d}{dt}w(t) = \Gamma(\gamma_1(t),\gamma_2(t),w(t)), \quad t\in [0,T],\\
		&w(0) = w.
		\end{aligned}
	\]
	Furthermore, the flow map \(\Phi\) satisfies the following properties:
	\begin{enumerate}[label=(\roman*)]
		\item \textbf{(\(\Phi\) is non-anticipative):} There exists a family of functionals \((\Phi_t)_{t\in [0,T]}\), with \(\Phi_t: \mathcal{C}^d_t\times \mathcal{C}^d_t\times \mathbb{R} \to \mathbb{R}\), such that 
		\[
			\Phi(t,\gamma,\bar{\gamma},w) = \Phi_t(\gamma_{[0,t]},\bar{\gamma}_{[0,t]},w).
		\]
		\item \textbf{(\(\Phi\) is Lipschitz):}  
		\[
			\vert \Phi(t,\gamma_1,\bar{\gamma}_1,w_1) - \Phi(t,\gamma_2,\bar{\gamma}_2,w_2) \vert \leq L_{\Phi}(t) \left(\Vert \gamma_1-\gamma_2\Vert_{\ast,t} + \Vert \bar{\gamma}_1-\bar{\gamma}_2\Vert_{\ast,t} + \vert w_1-w_2\vert \right),
		\]
		with \(L_{\Phi}(t) = e^{L_{\Gamma}t}\left(1+tL_{\Gamma}\right)\).
		\item \textbf{(\(\Phi\) has linear growth in the weight variable):} 
		\begin{equation}
		\vert \Phi(t,\gamma,\bar{\gamma},w)\vert \leq B_{\Phi}(t)(1+ \vert w\vert), 
		\end{equation}
		with \(B_{\Phi}(t) = (1+B_{\Gamma}t)e^{L_{\Gamma}t}\).
	\end{enumerate}

	Let us denote the product of the flow map and the kernel \(K\) by \(\Pi: [0,T]\times \mathcal{C}_T^d\times \mathcal{C}_T^d\times \mathbb{R} \to \mathbb{R}^d\), defined as 
	\[
		(t,\gamma,\bar{\gamma},w) \mapsto \Phi(t,\gamma,\bar{\gamma},w)K(\gamma(t),\bar{\gamma}(t)).
	\] 
	If the kernel \(K\) satisfies Assumption (assump:interaction-kernel of the paper), then the map \(\Pi\) inherits the
	following properties:
	\begin{enumerate}[label=(\roman*), resume]
		\item \textbf{(\(\Pi\) is Lipschitz):}  
		\begin{equation} 
			\vert \Pi(t,\gamma_1,\bar{\gamma}_1,w_1) -\Pi(t,\gamma_2,\bar{\gamma}_2,w_2)\vert \leq L_{\Pi}(t)(1+\vert w_1\vert) \left( \Vert \gamma_1-\gamma_2 \Vert_{\ast,t}+\Vert \bar{\gamma}_1-\bar{\gamma}_2 \Vert_{\ast,t} +\vert w_1-w_2\vert\right), 
		\end{equation}
		with \(L_{\Pi}(t) = (B_K L_{\Phi}(t)+B_{\Phi}(t)L_K)\).
		\item \textbf{(\(\Pi\) has linear growth in the weight variable):}  
		\begin{equation} 
		\vert \Pi(t,\gamma,\bar{\gamma},w)\vert \leq B_{\Pi}(t)(1+ \vert w\vert), 
		\end{equation}
		with \(B_{\Pi}(t) = B_{\Phi}(t)B_K\).
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

