[Lemma 38 of arXiv:2606.24887, '2606.24887'] There exists a constant $\mathcal{C}\ge 1$, such that the following holds. Let $\mathfrak{c} = \mathfrak{c}(\nu, \delta)>0$ be as in \cref{lem:roughboundsGT} and $ \frac{\Gamma^2}{64 \mathfrak c} \leq d \leq N^{\delta/2}$. If $x \in T \subset [N]$ are deterministic and $\abs{T} +1\le \mathfrak{c}d/\Gamma^2$ then for any $0 < \epsilon \le 1$ and $i \in \{1,2\}$ we have
		\begin{equation}
			\theta^{\bset{T}} \mathbb{P} \big( \big |\Phi_x^{i,\bset{T}}\big| > \epsilon \, \big| \, H^{\bset{T}} \big) \le \ee^{-\frac{ \epsilon^2 d}{2^6(\ee\Gamma)^2}}, ~~ \theta^{\bset{T}} \mathbb{P} \big( \big|\Psi_x^{i,\bset{T}}\big| > \epsilon \, \big| \, H^{\bset{T}} \big) \le    \ee^{-\frac{ \epsilon^2 d}{2^6(\ee\Gamma)^2}},
		\end{equation}
	and for any $u \notin T$
		\begin{equation}
			\big| \Phi_x^{i,\bset{Tu}} - \Phi_x^{i,\bset{T}} \big| \le K^2d^{-1},~~~~ \theta^{\bset{T}}\big|\Psi_x^{i,\bset{Tu}} - \Psi_x^{i,\bset{T}}\big| \le \mathcal{C}  \frac{\Gamma + \beta^{i}_x\Gamma^3}{d}
		\end{equation}
		with very high probability.

