[Corollary 13 (Time-zero centering and same-sample selection) of arXiv:2608.30261, 'Estimating Population-Risk Curves Along Nonconvex Gradient Flows from the Training Sample'] \label[corollary]{cor:regularity-event-oracle}
Under the hypotheses and notation of \cref{thm:oracle}, fix
$\delta\in(0,1-\tau_n)$ and let $\mathcal O_{n,\delta}$ be the event supplied
by \cref{thm:oracle}.
\begin{enumerate}
\item If the chained route uses the deterministic integrable anchor
$(t_0,\lambda_0)=(0,\lambda_0)\in\cH$ and all flows start from the common
deterministic initialization in \eqref{eq:full-flow}, then, on
$\mathcal O_{n,\delta}$,
\begin{equation}
 \sup_{(t,\lambda)\in\cH}
 \left|\bigl\{\widetilde\Score_n(t,\lambda)
              -\widetilde\Score_n(0,\lambda_0)\bigr\}
       -\bigl\{\Risk_S(t,\lambda)-\Risk_S(0,\lambda_0)\bigr\}\right|
 \leq\mathfrak r_n(\delta).
\end{equation}
\item For either concentration route, let
$\zeta_n:\Omega\to[0,\infty)$ be $\mathcal F$-measurable.  If an
$\mathcal F/\mathcal B(\cH)$-measurable selector
$(\widehat t,\widehat\lambda):\Omega\to\cH$ satisfies
\begin{equation}
 \widetilde\Score_n(\widehat t,\widehat\lambda)
 \leq\inf_{(t,\lambda)\in\cH}\widetilde\Score_n(t,\lambda)+\zeta_n,
\end{equation}
then, on $\mathcal O_{n,\delta}$,
\begin{equation}
 \Risk_S(\widehat t,\widehat\lambda)
 -\inf_{(t,\lambda)\in\cH}\Risk_S(t,\lambda)
 \leq2\mathfrak r_n(\delta)+\zeta_n.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:int_onefold_moll of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] For all $h\in H_0^1 \cap H^2 = D(A)$, the Bochner integral $\int_{(0,1)} \bar{h}_x \gamma_{\varepsilon}(\delta_x^{\mathrm{ext}}(\cdot))\, dx$ is a well-defined element of $L^2(L, \mu^{\beta})$, i.e.\ it holds
	\begin{equation}
		\left[I: (0,1) \to L^2(L, \mu^{\beta}): x \mapsto \bar{h}_x \gamma_{\varepsilon}(\delta_x^{\mathrm{ext}}(\cdot)) \right] \in \mathcal{L}(\lambda\rvert_{(0,1)}, L^2(L, \mu^{\beta})).
	\end{equation}

[Theorem 215 of arXiv:2601.16377, '2601.16377'] The fundamental solution $\boldsymbol{\mathcal{F}}(z_1,z_2)$ depends only on $H$, $\boldsymbol{\Theta}$ and $\alpha_1 < \beta_1 < \cdots < \alpha_H < \beta_H$. It does so in a smooth way, and satisfies
 \begin{equation}

 \mathcal{F}_{h_1,h_2}(z_1,z_2) = \mathcal{F}_{h_2,h_1}(z_2,z_1).
 \end{equation}
 for any $h_i \in [H]$ and $z_i \in \widehat{\amsmathbb{C}} \setminus [\alpha_{h_i},\beta_{h_i}]$ with $i = 1,2$. In particular, $\mathcal{F}_{h_1,h_2}(z_1,z_2)$ is a holomorphic function of $(z_1,z_2) \in \big({\amsmathbb{C}} \setminus [\alpha_{h_1},\beta_{h_1}]\big) \times \big({\amsmathbb{C}} \setminus [\alpha_{h_2},\beta_{h_2}]\big)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:conditional-estimates-detailed of arXiv:2609.00556, 'Higgs--Demailly System and Positivity of Higgs Bundles'] Assume $f\geq-C_0$.  Then, for every integer $k\geq0$ and
$0<\gamma<1$, there is a constant $C_{k,\gamma}$, independent of $t$, such
that
\begin{equation}
 \|f\|_{C^{k+2,\gamma}}+\|g\|_{C^{k+2,\gamma}}
 +\|g^{-1}\|_{C^{k+2,\gamma}}\leq C_{k,\gamma}.
\end{equation}
Moreover, $A_t\geq c\operatorname{Id}_E$.

[Lemma Lemma1.5 of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] Let $\Lambda \subseteq \ensuremath{\mathbb{Z}^d}$ be a finite set and let $\nu$ be a strictly positive probability measure on $\left\{ 0 , 1 \right\}^{\Lambda}$. We assume that for any vertex $x \in \Lambda$ and any configuration $r_1 \in \Lambda \setminus \{ x \}$, one has the inequality
        \begin{equation*}
            \nu \left( r_x = 1 \, | \, r = r_1 ~ \mbox{in} ~ \Lambda \setminus \{ x \} \right) \leq p.
        \end{equation*}
        Then $\mathbb{P}_{\Lambda,p}^{\mathrm{site}}$ stochastically dominates $\nu$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma LE1 of arXiv:2604.06012, 'Large fringe trees for random trees with given vertex degrees'] Let ${\mathbf{n}}$ be a degree statistic and let $T\in\mathbb T$ with $|T|\leqslant|{\mathbf{n}}|$.
Then
\begin{align}
  \operatorname{\mathbb E{}} N_T({\mathcal T}_{\mathbf{n}}) 
= \frac{|{\mathbf{n}}|}{(|{\mathbf{n}}|)_{|T|}} \prod_{i\geqslant0}(n(i))_{n_T(i)}
= \frac{|{\mathbf{n}}|}{(|{\mathbf{n}}|)_{|T|}} \prod_{i\in\mathcal D(T)}(n(i))_{n_T(i)}
.\end{align}
Hence,
\begin{align}
  \operatorname{\mathbb E{}} N_T({\mathcal T}_{\mathbf{n}}) 
\leqslant \frac{|{\mathbf{n}}|^{|T|+1}}{(|{\mathbf{n}}|)_{|T|}} \prod_{i\in\mathcal D(T)}p_i({\mathbf{n}})^{n_T(i)}
=\frac{|{\mathbf{n}}|^{|T|+1}}{(|{\mathbf{n}}|)_{|T|}} \pi_{\mathbf{p}({\mathbf{n}})}(T)
,\end{align}
and for every $C>0$ there is a $C'\geq 0$ such that if\/ $|T|^2\leqslant C|{\mathbf{n}}|$, then
\begin{align}
  \operatorname{\mathbb E{}} N_T({\mathcal T}_{\mathbf{n}}) 

\leqslant |{\mathbf{n}}|\pi_{\mathbf{p}({\mathbf{n}})}(T)\cdot\Bigpar{1+C'\frac{|T|^2}{|{\mathbf{n}}|}}.
\end{align}

