[Lem exists an outer edge of arXiv:2508.13827, 'Surface sums in two-dimensional large-$N$ lattice Yang--Mills: Cancellations and explicit '] Let $\mathbb{T}^*=\mathbb{T}^*_{p,q,M}(\mathfrak{p})= \{T_1^*,T_2^*\}$ be a spanning pair of trees avoiding $p$ and $q$ generated from $\mathfrak{p} =\{p_i\}_{i=1}^{\infty}$ of size $M\geq 1$ and $\ell$ be a loop. Then, for any loop $\Bar{\ell}$ with all its edges in $E(\mathbb{T}^*, \ell)$ such that $n^{\times}_{p}(\mathbb{T}^*, \Bar{\ell})\geq 1$ (resp.\ $n_{p,q}^{\times}(\mathbb{T}^*, \Bar{\ell})\geq 1$), there exists an edge $\Bar{e}$ of $\Bar{\ell}$ such that: 
    \begin{enumerate}
        \item[1.] $\Bar{e}\in E^{\times}(\mathbb{T}^*)$;
        \item[2.] $\Bar{e}$ is the outermost edge of $\Bar{\ell}$ in $\mathfrak{p}^{\Bar{e}}$, for all $\mathfrak{p}^{\Bar{e}}\in \mathfrak{P}_{\mathbb{T}^*}(\Bar{e})$; 
        \item[3.] $\Bar{e}\notin \mathcal{E}(p)$ (resp.\ $\Bar{e}\notin \mathcal{E}(\{p,q\})$).
    \end{enumerate}
    Furthermore, for such an edge $\Bar{e}$, either $\Bar{e}\in \mathcal{I}(\mathfrak{p})$; in which case, taking $k\in \mathbb{N}$ such that $\mathfrak{e}(p_k,p_{k+1})$ corresponds to $\Bar{e}$,
    \begin{enumerate}
    \item[{\crtcrossreflabel{4a}[item:3a]}.]  the path $\Bar{\mathfrak{p}} = \{\Bar{p}_i\}_{i=1}^{\infty}:=\{p_{i+k-1}\}_{i=1}^{\infty}$ connects $\Bar{e}$ to infinity;
    \end{enumerate}
    or $\Bar{e}\notin \mathcal{I}(\mathfrak{p})$; in which case, fixing any $\{p_i^{\Bar{e}}\}_{i=1}^{\infty} =\mathfrak{p}^{\Bar{e}}\in \mathfrak{P}_{\mathbb{T}^*}(\Bar{e})$ and taking $k\in \mathbb{N}$ such that $\mathfrak{e}(p_k^{\Bar{e}},p_{k+1}^{\Bar{e}})$ corresponds to $\Bar{e}$,
    \begin{enumerate}
         \item[{\crtcrossreflabel{4b}[item:3b]}.] 
         the path $\Bar{\mathfrak{p}} = \{\Bar{p}_i\}_{i=1}^{\infty}:=\{p^{\Bar{e}}_{i+k-1}\}_{i=1}^{\infty}$ connects $\Bar{e}$ to infinity. Moreover, in this case $\Bar{p}_1\notin\mathfrak{p}$.
    \end{enumerate}

[Lemma lem:Lambda-diamond of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] For $v \in \mathcal{V}^m$, set $P(v) \vcentcolon= I + B_v(v, v) \in \mathrm{End}(E^m)$.  Then $P(v)$ is invertible with $P(v)^{-1} = I - B_v(\mathcal{T}v, \mathcal{T}v)$, and the edge weights $(C_k, \Lambda_k)$ with
    \begin{equation}
        \Lambda_k(u) \vcentcolon= P(u) D_k(u) P(\mathcal{S}_k u)^{-1}

    \end{equation}
    satisfy the diamond equations (equation eq:diamond-C-ij of the paper)--(equation eq:diamond-mixed-ij of the paper) on $\mathcal{G}^m$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:lemflow of arXiv:2411.02541, 'The hockey-stick conjecture for\\ activated random walk'] \thlabel{lem:flow}
  Let $u$ be an extended odometer on $\ii{0,n}$.
  Let $f_v=\rt{u}{v}-\lt{u}{v+1}$, the net flow from $v$ to $v+1$.
  Let $s_v=\sum_{i=1}^v\1\{\mathsf{instr}_i(u(i))=\ensuremath{\mathtt{sleep}}\}$.
  Then $u$ is stable on $\ii{1,n-1}$ for initial configuration $\sigma$ if and only if
  \begin{align}
    f_v = f_0 + \sum_{i=1}^v\abs{\sigma(i)} - s_v\quad\text{for all $v\in\ii{0,n-1}$.}
  \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

