[Lemma 11 of arXiv:2605.17328, 'Transportation cost inequalities for mean reflection SPDEs with white noise'] {\rm(\cite[Lemma 3.1]{KS2019})}
{\rm There exists an adapted  random field $g=\left\{g(s,x)\right\}_{(s,x)\in[0,T]\times[0,1]}$ such that $\mathbb{Q}$-a.s. for all $t\in[0,T]$,}
\begin{align*}
\int^{t}_0\int_0^1 g^2(s,x)\mathrm{d}s\mathrm{d}x<\infty,
\end{align*}
{\rm and $\widetilde{W}:[0,T]\times[0,1]\rightarrow\RR$ defined by}
\begin{equation}
\begin{split}
\widetilde{W}(t,x):=W(t,x)-\int^t_0\int_0^xg(s,y)\mathrm{d}s\mathrm{d}y,
\end{split}
\end{equation}
{\rm is a Brownian sheet under the measure $\mathbb{Q}$.
Moreover,}
\begin{align*}
M_t=\exp\left(\int^t_0\int^1_0g(s,x){W}(\mathrm{d}s,\mathrm{d}x)-\frac{1}{2}\int^{{t}}_0\int^1_0 g^2(s,x)\mathrm{d}s\mathrm{d}x\right),\,\,\mathbb{Q}\text{-a.s.},
\end{align*}
\begin{align}
H(\nu|\mu)=\frac{1}{2}\mathbb{E}^{\mathbb{Q}}\left[\int^T_0\int^1_0 g^2(s,x)\mathrm{d}s\mathrm{d}x\right],
\end{align}
{\rm where $\mathbb{E}^{\mathbb{Q}}$ stands for the expectation under the measure $\mathbb{Q}$.} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 9 of arXiv:2604.19924, 'Fluctuation theory for spectrally negative Lévy processes killed by additive functionals'] Let $x \leq b$ and $q \geq 0$. Then
			\begin{align}
				\E_x\left[e^{-q\tau_b^+-A_{\tau_b^+}};\,\tau_b^+<\infty\right]
				= \frac{u^{(q)}_{{\mathbf{T}}(\nu_A)}(x)}{u^{(q)}_{{\mathbf{T}}(\nu_A)}(b)}.
			\end{align}
			Moreover, for any bounded, non-negative measurable function $f:\R\to\R$,
			\begin{align}
				\E_x\left[\int_0^{\tau_b^+} e^{-qt-A_t} f(X_t)\,dt\right]
				= \int_{-\infty}^b f(y)\left(
				\frac{u_{{\mathbf{T}}(\nu_A)}^{(q)}(x)}{u_{{\mathbf{T}}(\nu_A)}^{(q)}(b)}
				W_{{\mathbf{T}}(\nu_A)}^{(q)}(b,y)
				- W_{{\mathbf{T}}(\nu_A)}^{(q)}(x,y)
				\right)dy,
			\end{align}
			where $W_{{\mathbf{T}}(\nu_A)}^{(q)}$ and $u^{(q)}_{{\mathbf{T}}(\nu_A)}$ are the unique solutions to \eqref{volterra_sf_w} and \eqref{fun_u}, respectively.

