body:
[Definition def:fw-natural of arXiv:2607.14993, 'Sharp phase transition for percolation with short-range dependencies'] Let $M, N \in \mathbb N^*$. Let $h : (m, \beta) \in \llbracket 0, M \rrbracket \times \mathbb R_+^* \mapsto h_m(\beta) \in [0, 1[$ and $\zeta : \llbracket 0, N \rrbracket^2 \to \llbracket 0, M \rrbracket$. We assume that $\zeta$ and $h$ have the following properties.
  \begin{itemize}
    \item $\forall (n_1, n_2) \in \llbracket 0, N \rrbracket^2, \zeta(n_1, n_2) = \zeta(n_2, n_1)$
    \item $\zeta$ is nondecreasing with respect to the product order.
    \item $0 = h_0 < h_1 < \ldots < h_M$ and for all $m \in \llbracket 1, M \rrbracket$, $h_m$ is increasing and of class $C^1$.
    \item For all $m \in \llbracket 1, M \rrbracket, h_m' > \frac {1 - h_m} {1 - h_{m-1}} h_{m-1}'$.\footnote{The meaning of this inequality will made be clear in Remark~(rem:Bernoulli-compat of the paper).}
  \end{itemize}
  Let $q_\nu$ be a probability distribution on $\llbracket 0, N \rrbracket$ such that $q_\nu(N) > 0$. Let
  \begin{equation}
    (\Omega, \mathcal F, \mathbb P) = (\llbracket 0, N \rrbracket, \mathcal P(\llbracket 0, N \rrbracket), q_\nu)^{\otimes \mathbb Z^d} \otimes ([0, 1], \mathcal B([0, 1]), \mu)^{\otimes E},
  \end{equation}
  where $\mu$ is the Lebesgue measure on $[0, 1]$. For a configuration $(\nu, U) \in \Omega$ the edge $e \in E$ is open if $$h_{\zeta(\nu_x, \nu_y)}(\beta) \geqslant U_e.$$

[Theorem 14 of arXiv:2606.31596, 'The Invariant Measure of Multiscale Markov Chains via Fast Arborescence Factorization'] Let $x \in \hat V$. The weight of the set $\mathcal T_{x}$ of arborescences of $(V,E)$ and the reduced weight of the set $\hat{\mathcal T}_{x}$ of arborescences of $(\hat V,\hat E)$ are related by:
\begin{equation} 
	r\left(\mathcal{T}_x\right) = r\left(\mathcal{F}_{\hat V}\right)\, \hat{r}\left(\hat{\mathcal{T}}_x\right)
\end{equation}
where $\mathcal{F}_{\hat V}$ denotes the collection of spanning forests of $(V,E)$ with root set $\hat V$.

[Lemma lem:dotG of arXiv:2411.07157, 'Rough differential equations in the flow approach'] For every $N\in\N$, we have
\begin{equs}        
    \norm{\mathcal{P}_{N,\mu}\dot G_\mu}_{\mathcal{L}^{p,\infty}}&\lesssim \mu^{-1/p}\;\mathrm{for}\;\mathrm{all}\;p\in[1,\infty]
    \end{equs}
uniformly in $\mu\in(0,1]$.

[Theorem thm:uld_regularity of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] Adopt Assumption~(as:regularity of the paper) and let $\boldsymbol{P}_T$ denote the Markov kernel corresponding to running~(eq:ULD of the paper) for time $T > 0$.
    Then, for all $q\geqslant 1$ and all $x,\bar x,p,\bar p\in\mathbb{R}^d$,
    \begin{align}
        \mathsf{R}_q(\delta_{x,p} \boldsymbol{P}_T \mathbin{\|} \delta_{\bar x,\bar p}\boldsymbol{P}_T)
        &\leqslant qC(\alpha,\beta,\gamma,T)\,\Bigl\{\norm{x-\bar x}^2 + \frac{1}{\gamma_0^2}\,\norm{p-\bar p}^2\Bigr\}\,,
    \end{align}
    where
    \begin{align*}
        C(\alpha,\beta,\gamma,T)
        \lesssim \frac{1}{\gamma} \,\Bigl(\frac{\omega}{\exp(c\omega T)-1}\Bigr)^3 + \gamma\,\frac{\omega}{\exp(c\omega T)-1}\,, \qquad
        \gamma_0
        &\gtrsim \gamma + \frac{\one_{T\leqslant 1/\abs{\omega}}}{T}\,,
    \end{align*}
    where $c > 0$ is a universal constant ($c=1/48$ suffices) and
    \begin{align*}
        \omega
        \coloneqq
        \begin{cases}
            \alpha/(3\gamma) & \text{ if } \gamma \geqslant \sqrt{32\beta} \text{ \textbf{ (high friction setting)}}
            \\
            -\sqrt\beta/3 & \text{ if }\gamma < \sqrt{32\beta} \text{ \textbf{ (low friction setting)}}
        \end{cases}
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 38 of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] Given $k\ge \ell\ge 1$, $\sigma\in(0,1/10)$ and $f\in C_\cc(\R^{\ell})$ let
\begin{equation}

\Xi_k(f):=E\Biggl(f\Bigl(\{X_j+j\slb\}_{j=1}^{\ell}\Bigr)\biggl(\,\prod_{j=1}^{k} \wt P(M_{j}'\le t)|_{t:=X_j+j\slb}\biggr)\,1_{\{X_k\in[k^{\sigma},k^{1-\sigma}]\}}X_k\Biggr),
\end{equation}
where~$X$ is the random walk with step distribution $\NN(0,1/2)$. Let~$\delta\in(0, 1/2)$. Then $\epsilon_{n,k}(u,f)$ defined for each~$u>0$ and $n\ge k$ by
\begin{equation}

E_{Q_{n,u,u}}\Bigl(f\bigl(\{h(x_0)-h(x_j)\}_{j=1}^\ell\bigr)\Bigr)=\frac{4u}n\Xi_k(f)+\frac un\epsilon_{n,k}(u,f)
\end{equation}
obeys
\begin{equation}

\lim_{k\to\infty}\limsup_{n\to\infty}\sup_{n^{\delta}\le u\le n^{1-\delta}}\bigl|\epsilon_{n,k}(u,f)\bigr|=0.
\end{equation}
Moreover, writing $1$ for the constant function equal to~$1$, we have
\begin{equation}

0<\inf_{k\ge1}\Xi_k(1)\le\sup_{k\ge1}\Xi_k(1)<\infty.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

