body:
[Lemma 197 (Remarkable structure in the $\ingoingcharacteristicsurfacetwoarg{\ubar_2}{[u_1,u_2) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] }$ boundary terms in the elliptic-hyperbolic integral identities]  Let $\SigmatTan = \tander^N \vortrenormalized$ or $\tander^N \GradEnt$. Then, for any $u_1 \le u_2$, the following identity holds:
\begin{align}
		\begin{split} 
			- \int_{\ingoingcharacteristicsurfacetwoarg{\ubar}{[u_1,u_2]}} \frac{1}{\upmu} \weight^{\blowupratetoporderacoustic} \newuL_\alpha \ehcurrent^\alpha \volingoingnullhypersurface  & = -\int_{\ingoingcharacteristicsurfacetwoarg{\ubar_1}{[u_1,u_2]}} \left\{ \, ^{(\SigmatTan)}\Currentboundaryerrorhavetocontrolprincipalweighted{\blowupratetoporderacoustic}  + \, ^{(\SigmatTan)}\Currentboundaryerrorhavetocontrollowerorderweighted{\blowupratetoporderacoustic}  \right\} \volingoingnullhypersurface \\
			& \ \ - \int_{\doublenulltoritwoarg{\ubar}{u_2}} \frac{1}{\upmu} \coercivequadraticformintoriboundaryterms[\SigmatTan,\SigmatTan]  \weight^{\blowupratetoporderacoustic} \, \voldoublenulltori 
			+ \int_{\doublenulltoritwoarg{\ubar}{u_1}} \frac{1}{\upmu}\coercivequadraticformintoriboundaryterms[\SigmatTan,\SigmatTan]   \weight^{\blowupratetoporderacoustic} \, \voldoublenulltori,
		\end{split}
	\end{align}
where:
	\begin{align} 
		\coercivequadraticformintoriboundaryterms[\SigmatTan,\SigmatTan]  \eqdef	 \frac{1}{2} |\SigmatTan|_{\gfour}^2 - \frac{\ingoingmu}{\MagnitueofinnerproductofnewLandnewuL}  \SigmatTan^\alpha \newuL_\alpha   \SigmatTan^\beta \breve{\slashed{\Transport}}_\beta 
	\end{align}
	and:
	\begin{subequations}
		\begin{align}
			\, ^{(\SigmatTan)}\Currentboundaryerrorhavetocontrolprincipalweighted{\blowupratetoporderacoustic} & = \left\{ \frac{1}{\upmu}  \, ^{(\SigmatTan)}\Currentboundaryerrorhavetocontrolprincipal^{(\textnormal{Flat})} 
			+ 2\frac{\ingoingmu}{\upmu \MagnitueofinnerproductofnewLandnewuL}   \,^{(\SigmatTan )}\Currentboundaryerrorhavetocontrolprincipal^{(\textnormal{Non-flat})} \right\}  \weight^{\blowupratetoporderacoustic}  \\
			\begin{split}
				\, ^{(\SigmatTan)}\Currentboundaryerrorhavetocontrollowerorderweighted{\blowupratetoporderacoustic} & =  \left\{\frac{1}{\upmu} \, ^{(\SigmatTan)}\Currentboundaryerrorhavetocontrollowerorder^{(\textnormal{Flat})} 
				+ 2 \frac{\ingoingmu}{\upmu \MagnitueofinnerproductofnewLandnewuL}  \,^{(\SigmatTan)}\Currentboundaryerrorhavetocontrollowerorder^{(\textnormal{Non-flat})}\right\} \weight^{\blowupratetoporderacoustic} \\
				& \ \  + \left\{\frac{\newuL \upmu}{2\upmu^2} |\SigmatTan|_{\gfour}^2
				+ \newuL\left( \frac{1}{\upmu}\right) \SigmatTan^\alpha \uLunit_\alpha \SigmatTan^\beta \breve{\slashed{\Transport}}_\beta 
				+ \breve{\slashed{\Transport}} \left( \frac{\ingoingmu}{\upmu \MagnitueofinnerproductofnewLandnewuL} \right) ( \SigmatTan^\alpha\newuL_\alpha)^2  \right. \\
				 & \ \ \ \ \left. + \frac{1}{\upmu}  \SigmatTan^\alpha \SigmatTan^\beta \newuL(\uLunit_\alpha \breve{\slashed{\Transport}}_\beta)
				 + \frac{1}{2 \upmu}  \SigmatTan^\alpha \uLunit_\alpha   \SigmatTan^\beta \breve{\slashed{\Transport}}_\beta \mytr_{\gnulltori} \deform{\newuL} 
				 -   \frac{1}{4\upmu} |\SigmatTan|_{\gfour}^2 \mytr_{\gnulltori} \deform{\newuL}  \right\} \weight^{\blowupratetoporderacoustic},
			\end{split}
		\end{align}
	\end{subequations}
