[Lemma cover_from_high_density of arXiv:2608.00399, 'The Heavy-tailed Frog Model'] Let $\ell^*$ and $m$ be as defined above.
    For any $c > 0$, there exist $\delta > 0$ and $\varepsilon > 0$ depending on $d, \lambda, K$, and $\alpha$ such that, if $A \subseteq \mathbb{T}^d_L$ satisfies
    \begin{align*}
        \frac{|A \cap B_v|}{|B_v|} \ge 1-\delta \qquad \text{for every } v \in \mathbb{T}^d_m,
    \end{align*}
    then 
    \begin{align}
        \mathbb P_L \left( \tau_{\mathrm{cov}}^{(1-\varepsilon)\lambda, A} \ge (1 + c) \ell^* \right) \rightarrow 0 \quad \text{as } L \to \infty.
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 37 of arXiv:2608.09700, 'A general paracontrolled ansatz for singular SPDEs'] Suppose we are given a smooth admissible stochastic data $\mcZ=(Z_\tau)$. Let a tree $\tau= X^k \Xi_\ell \prod_{j=1}^n\mcI_{b_j}(\tau_j) \, $ with $|\tau|<0$.
	\begin{enumerate}
		\item If $k\ne 0$ or $|\mcI_{b_j}(\tau_j)|>0$ for some $j\in\bbrack{1,n}$, then
		\begin{equation}
			\sum_{\substack{q\geq 0 \\ \tau_q\prec\dots\prec\tau_1\prec\tau}}\sum_{k\geq 0} \frac{1}{k!}{\bf C}_k(Z_{\downarrow^k\tau/\tau_1},\dots,Z_{\tau_{q-1}/\tau_q}, Z_{\tau_q}^\circ) = 0.
		\end{equation}
		\item Otherwise 
		\begin{equation}
			\sum_{\substack{q\geq 0 \\ \tau_q\prec\dots\prec\tau_1\prec\tau}}\sum_{k\geq 0} \frac{1}{k!}{\bf C}_k(Z_{\downarrow^k\tau/\tau_1},\dots, Z_{\tau_{q-1}/\tau_q}, Z_{\tau_q}^\circ) = \xi_\ell \prod_{j=1}^n  \overline Z_{\mcI_{b_j}(\tau_j)}.
		\end{equation}
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:dim_equal_degree of arXiv:2510.21186, 'Weingarten Calculus with Virtual Isometries'] For $\pi \in S_n$, we have
\[
\Wg_{n,n}(\pi)= \sum_{\tau \in S_{n-1}}
a_n(\pi, \tau) \Wg_{n-1,n-1}(\tau),
\]
where the function $a_n\colon S_n \times S_{n-1} \to \mathbb{C}$ is defined by
\begin{equation} 
a_n(\pi, \tau)= \sum_{t=0}^{\mathsf{f}(\pi, \tau)} (-1)^{n-t+1}
\binom{\mathsf{f}(\pi, \tau)}{t} \frac{1}{n^{\uparrow (n-t)}},
\end{equation}
and $\mathsf{f}(\pi,\tau)= |\{i \in \{1,2,\dots, n-1\} \mid
\pi (\tau(i))=i \}|$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 17 of arXiv:2607.02489, '2607.02489'] Let $(\mathsf{K},\EuScript{K})$ be a
measurable space and let $\upbeta\in\RPP$. For every
$\kS\in\mathsf{K}$, let $\fS_{\kS}\colon\HS\to\RR$ be a convex 
differentiable function such that $\nabla\fS_{\kS}$ is
$\upbeta$-Lipschitzian. Further, let
$k\colon(\upOmega,\FE,\PP)\to(\mathsf{K},\EuScript{K})$ be a random
variable and set 
\begin{equation}

(\forall\xS\in\HS)\quad\fS(\xS)
=\Int_{\upOmega}\fS_{k(\upomega)}(\xS)\PP(d\upomega).
\end{equation}
Assume that $\Argmin\fS\neq\emp$ and that there exists an
increasing function $\uppsi\colon\RP\to\RP$ such that
\begin{equation}

(\forall\xS\in\HS)\quad
\int_{\upOmega}\norm1{\nabla\fS_{k(\upomega)}(\xS)}^2
\PP(d\upomega)
\leq\uppsi\brk1{\norm{\xS}}.
\end{equation}
Let $x_{0}\in L^2(\upOmega,\FE,\PP;\HS)$, let
$\mathsf{p}\in\left]2/3,1\right]$, and set $(\forall\nnn)$
$\upgamma_{\nS}=(\nS+1)^{-\mathsf{p}}$. Iterate
\begin{equation}

\begin{array}{l}
\textup{for}\;\nS=0,1,\ldots\\
\left\lfloor
\begin{array}{l}
k_{\nS}\;\textup{is a copy of}\;k\;\textup{and it is independent
of}\;\FE_{\nS}\\
x_{\nS+1}=x_{\nS}-\upgamma_{\nS}\nabla\fS_{k_{\nS}}(x_{\nS}).
\end{array}
\right.\\
\end{array}
\end{equation}
Then, $\Pas$,
\begin{equation}
\fS(x_{\nS})-\inf\fS(\HS)
=
\begin{cases}
\mathrm{o}\brk2{\dfrac{1}{\mathsf{n}^{1-\mathsf{p}}}},&\text{if}\;
\mathsf{p}\in\left]2/3,1\right[;\\[3mm]
\mathrm{o}\brk2{\dfrac{1}{\ln(\mathsf{n})}},
&\text{if}\;\mathsf{p}=1.
\end{cases}
\end{equation}

[Definition eq:defXYGFF of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] We fix an integer $L \in \ensuremath{\mathbb{N}}$, an integer $n \in \ensuremath{\mathbb{N}}^*$ and three inverse temperatures $\beta, \beta_1, \beta_2 > 0$ and define three models of height functions (see Figures~(fig:XYheight of the paper) and~(fig:XYGFFheight of the paper)):
\begin{itemize}
    \item The first one is the XY height function on the multigraph $\ensuremath{\mathbb{Z}}^d_{n-\mathrm{mult}}$ with inverse temperature $n \beta$ on each edge, i.e.,
    \begin{equation*}
        \mu_{\Lambda_L, n, \beta}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}}(\left\{ \varphi \right\}) := \frac{1}{Z_{\Lambda_L, n, \beta}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}}}  \prod_{x \sim y}    \left(I_{\left(\varphi(x) - \varphi(y)\right)} \left(n \beta \right)\right)^n.
    \end{equation*}
    \item The second one is an XY height function multigraph $\ensuremath{\mathbb{Z}}^2_{n- \mathrm{mult}}$ with $n \geq 2$ and with two inverse temperatures $\beta_1 , n \beta_2  \geq 0$ (see Figure~(fig:XYheight of the paper)):
\begin{equation*}
        \mu_{\Lambda_L, n, \beta_1 , \beta_2}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}}(\left\{ \varphi \right\}) := \frac{1}{Z_{\Lambda_L, n, \beta_1,  \beta_2 }^{\ensuremath{\mathbb{Z}}-\mathrm{XY}}}\prod_{x \sim y} \left( I_{\left(\varphi(x) - \varphi(y)\right)} \left( \beta_1 \right) \right)^2   \left( I_{\left(\varphi(x) - \varphi(y)\right)} \left(  n \beta_2 \right) \right)^{n-2}.
\end{equation*}
    \item The third one is a height function on the multigraph $\ensuremath{\mathbb{Z}}^2_{3-\mathrm{mult}}$ where the interaction between two vertices is a product of the integer-valued Gaussian distribution and the modified Bessel function (see Figure~(fig:XYGFFheight of the paper))
    \begin{equation} 
        \mu_{\Lambda_L, \beta_1 , \beta_2}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}/\mathrm{GFF}}(\left\{ \varphi \right\}) := \frac{1}{Z_{\Lambda_L, \beta_1 , \beta_2 }^{\ensuremath{\mathbb{Z}}-\mathrm{XY}/\mathrm{GFF}}} \prod_{x \sim y} \left( I_{\left(\varphi(x) - \varphi(y)\right)} \left( \beta_1 \right) \right)^2 \exp \left( - \frac{\left( \varphi(x) - \varphi(y) \right)^2}{2\beta_2} \right).
    \end{equation}
    We refer to this model as the $\ensuremath{\mathbb{Z}}$-XY/GFF height function.
\end{itemize}
We denote by $\mathrm{Var}_{L, n,  \beta}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}}$, $\mathrm{Var}_{L, n, \beta_1 , \beta_2}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}}$ and $\mathrm{Var}_{L, \beta_1 , \beta_2}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}/\mathrm{GFF}}$ the variances with respect to these three measures.

[Prop pro:limit_thm_2.2 of arXiv:2412.03370, 'TASEP with a general initial condition and a deterministically moving wall'] Recall $\tilde{x}_n(0)=x_n^f$ and suppose $\{x_n^f, n \in \mathbb{N}\}$ fulfils Assumption~(assumpt:2.9 of the paper). Then, it holds 
	\begin{equation}
	\begin{aligned} 
	\lim_{T \to \infty} \mathbb{P}(\tilde{x}_{\alpha T}(T) > g_\alpha T - S T^{1/3})
	&= \mathbb{P} \left( \sup_{\tau \in \mathbb{R}} \{ \mathcal{A}_2(\tau) - \tau^2 - y(-\tau) \} < c_1^{-1} S \right)
	\end{aligned}  
	\end{equation}
	with $g_\alpha = 1-d^{-1}-d\alpha$ and $c_1 = (1-d^{-1})^{2/3} d^{1/3}$. 

	Suppose $\{x_n^f,n \in \mathbb{N}\}$ fulfils Assumption~(assumpt:2.7 of the paper). Then, we have $g_\alpha = 1-2\sqrt{\alpha}$. If $d = \tfrac{1}{\sqrt{\alpha}}$, then it holds
	\begin{equation}
	\begin{aligned} 
	\lim_{T \to \infty} \mathbb{P}(\tilde{x}_{\alpha T}(T) > g_\alpha T - S T^{1/3})
	&= \mathbb{P} \left( \sup_{\tau \leq 0} \{ \mathcal{A}_2(\tau) - \tau^2 - y(-\tau) \} < c_1^{-1} S \right).
	\end{aligned}   
	\end{equation}
	If $d < \tfrac{1}{\sqrt{\alpha}}$, then it holds
	\begin{equation}
	\lim_{T \to \infty} \mathbb{P}(\tilde{x}_{\alpha T}(T) > g_\alpha T - S T^{1/3}) = F_{\textup{GUE}}(c_1^{-1} S).    
	\end{equation}
	In both cases, we have $c_1 = (1-\sqrt{\alpha})^{2/3} \alpha^{-1/6}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lm:reflec-pos of arXiv:2605.16162, 'Deconfinement For $\mathrm{SO}(3)$ Lattice Yang--Mills at Strong Coupling'] For any hyperplane $P=\{(x_1,\dots,x_d) \in \R^d:x_i=a\}$ with $a \in \Z$ and any matrix valued local observable $F$ which only depends on edges on one side of $P$ (which may include edges contained in $P$), we have $\langle \mrm{Tr}( F (\Theta_P F)^*)\rangle \in \R$ with,
    \begin{equs}
        \langle \mrm{Tr}( F (\Theta_P F)^*)\rangle \geq 0.
    \end{equs}
    As a direct corollary we have the Cauchy-Schwarz inequality. That is for any matrix-valued local observables $F$ and $G$ which both only depend on edges on one side of $P$, we have,
    \begin{equs}
        |\langle \mrm{Tr}(F (\Theta_P G)^* )\rangle|^2 \leq \langle \mrm{Tr}(F (\Theta_P F)^*) \rangle \langle \mrm{Tr}(G (\Theta_P G)^*) \rangle.
    \end{equs}
    Moreover, if $\mathrm{Tr}(F (\Theta_P F)^*)$, $\mathrm{Tr}(F (\Theta_P G)^*)$, $\mathrm{Tr}(G (\Theta_P F)^*)$, and $\mathrm{Tr}(G (\Theta_P G)^*)$ are all gauge invariant, then (equation eq:Reflection-Positivity of the paper) and (equation eq:Cauchy-Schwarz of the paper) also hold if $P$ is half integer hyperplane ($P=\{(x_1,\dots,x_d) \in \R^d:x_i=a\}$ with $a \in \frac{1}{2}\Z$). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 9 (Damped super-Brownian motion) of arXiv:2604.01852, 'The on/off Brownian snake'] Recall the processes $(\Tilde{\mathcal{Z}}_y^{(\varepsilon)})_{y \geq 0}$, $\varepsilon>0$ from Corollary \ref{corollary bbm extra killing} on the probability space $(\Omega, \mathcal{F}, \mathbb{P}_{(\mu_{\rm d},\mu_{\rm a})})$. Then, for $s>0$, we have the existence of a scaling limit $\Tilde{\mathcal{Z}}_s$ given by 
    \begin{equation*}
        \varepsilon \Tilde{\mathcal{Z}}^{(\varepsilon)}_s \xrightarrow[\varepsilon \rightarrow 0]{a.s.} \Tilde{\mathcal{Z}}_s.
    \end{equation*}
    Furthermore, for any continuous bounded function $\Phi: \mathbb{R}^d \rightarrow [0,\infty)$, we have 
    \begin{equation}
        \langle \Tilde{\mathcal{Z}}_s, \Phi \rangle \coloneqq \int_x \Phi(x) \Tilde{\mathcal{Z}}_s(dx) = \sum_{i \in \Tilde{I}} \int_{r=0}^{\sigma(f^i)} \Phi(\hat{w}^i_r)\mathbbm{1}_{\hat{\Tilde{v}}^i_r =0}dL^i_s(r)
    \end{equation}
    where, for $i \in \Tilde{I}$, $L^i_s(\cdot)$ are the local times for the excursions $f^i$ defined in \eqref{equation normalised local time}. Furthermore this measure-valued process $(\Tilde{\mathcal{Z}}_s)_{s \geq 0}$ has the finite dimensional distributions of a superprocess with continuous sample paths and with initial state $\Tilde{\mathcal{Z}}_0 = \mu_{\rm a}$. We call this superprocess \emph{damped super-Brownian motion with parameter $4$ and damping rate $c$} or \emph{$\text{DSBM}(4, c)$}. 
    \par
    Finally, when the prelimiting processes $\Tilde{\mathcal{Z}}^{(\varepsilon)}_s$ which are $\text{BBM}(2/\varepsilon, 2/\varepsilon+c)$ are replaced by $\text{BBM}(\gamma/2\varepsilon, \gamma/2\varepsilon + c)$ then the limit in distribution is another superprocess that we call \emph{damped super-Brownian motion with parameter $\gamma$ and damping rate $c$} or \emph{$\text{DSBM}(\gamma, c)$}. 
    \begin{proof}
        We can apply Lemma \ref{lemma snake exit open set general} to the Brownian snakes that form the damped Brownian snake of Definition \ref{definition damped Brownian snake}. For the snakes process $(w^i, t^i, \Tilde{v}^i)$, $i \in \Tilde{I}$, we let the exit set $D$ be given by $\mathbb{R}^d \times [0, y) \times \{0\}$. It is elementary to show that the exit local time in this case has associated Lebesgue-Steiltjes measure given by $\mathbbm{1}_{\hat{\Tilde{v}}^i_r =0}dL^i_s(r)$. By the analogous arguments that were given in Theorem \ref{theorem ooSBM ffd convergence} we obtain the a.s. convergence and the representation for $\Tilde{\mathcal{Z}}_y$.
        \par
        The scaling limit here is analogous to the standard scaling limit result for SBM given in Proposition \ref{proposition SBM existence} and it is an instance of the general result given in \cite[Chapter II]{le1999spatial} which shows the existence of superprocesses as scaling limits.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 7 of arXiv:2609.03455, '2609.03455'] The modular curve attached to $\G_0(2)\cap\G(7)$ admits an affine model
\begin{equation}
 \left\{ \ 
 \begin{aligned}
 &2\u(\u-1)t^3-(\u^2-\u-1)t^2
       -2\u t+\u=0,\\
 &\psi^7=\u^4(\u-1).
 \end{aligned}
 \right.
\end{equation}
After the change of variable $T=1/t-1$, the first equation becomes
\begin{equation}
 P_\u(T)
 =
 T^3+T^2-\frac{\u^2-1}{\u}T
 +\frac{(\u-1)^2}{\u}=0.
\end{equation}

