[Theorem thm: applications in information theory of arXiv:2411.17109, 'On the maximal correlation of some stochastic processes'] Let $X_1,X_2,\ldots,X_n$ be independent real-valued continuous random variables. Let $S\subset T$ be two nested non-empty random subsets of $[n]=\{1,2,\ldots,n\}$, which are independent of $X=(X_1,X_2,\ldots,X_n)$. Let $R$ be the maximal correlation coefficient between $(S,X_S)$ and $(T,X_T)$ given by (equation eq: R Y Z of the paper), where $X_{S}=(X_i)_{i\in S}$ and $X_{T}=(X_j)_{j\in T}$. Denote by $I(Z)=\int_{-\infty}^{\infty}\frac{(f'(z))^2}{f(z)}\,\mathrm{d}z$ the Fisher information of the continuous random variable $Z$ with the density $f(z)$. Then we have that
\begin{equation}
\sum_{t\subset[n]}P(T=t)I(\sum_{j\in t}X_j)\mu_t^2\leq R^2\sum_{s\subset[n]}P(S=s)I(\sum_{i\in s}X_i)\lambda_s^2,
\end{equation}
where $\mu_t=\sum_{s\subset[n]}P(S=s|T=t)\lambda_s$ for $t\subset[n]$ and $(\lambda_s)_{s\subset[n]}$ is an arbitrary real vector. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 10 of arXiv:2608.27143, 'An approximate zero bias transformation for random sums: Applications to sampling with out'] Let $n_1, n_2, n_3\in \mathbb{N}$ be such that $n_1< n_2< n_3$. Let $X_1,X_2,\ldots$ be mean zero random variables with finite variances.
Suppose that
$X_1,\ldots,X_{n_1}$, $X_{n_1+1},\ldots X_{n_2}$, $X_{n_2+1},\ldots X_{n_3}$    and  $X_{n_3+1}, X_{n_3+2}, \ldots $ 
form four independent groups of i.i.d.\ random variables, where the distributions may differ among the four groups. Let $W=\sum_{i=1}^N X_i$, where $N$ is a Poisson random variable  with parameter $\lambda$, independent of $\{X_i\}_{i=1}^\infty$, and let
 $\sigma^2$ be defined as in \eqref{TH:AI1}. Then
			\begin{align}
				d_1\!\left(\mathcal{L}(W/\sigma), \mathcal{L}(Z) \right)
				&\le \frac{1}{\sigma^3} \sum_{i=1}^{n_{1}} 
				\left(\mathbb{E}|X_1|^3 + 2\,\mathbb{E} X_1^2 \,\mathbb{E}|X_1|\right) P^2(N \ge i) \nn\\[4pt]
				&\quad + \frac{1}{\sigma^3} \sum_{i=n_{1}+1}^{n_2} 
				\left(\mathbb{E}|X_{n_{1}+1}|^3 + 2\,\mathbb{E} X_{n_{1}+1}^2  \,\mathbb{E}|X_{n_{1}+1}|\right) P^2(N \ge i)\nn \\[4pt]
				&\quad + \frac{1}{\sigma^3} \sum_{i=n_{2}+1}^{n_3} 
				\left(\mathbb{E}|X_{n_{2}+1}|^3 + 2\,\mathbb{E} X_{n_{2}+1}^2  \,\mathbb{E}|X_{n_{2}+1}|\right) P^2(N \ge i)\nn \\[4pt]
				&\quad + \frac{1}{\sigma^3} \sum_{i=n_{3}+1}^{\infty} 
				\left(\mathbb{E}|X_{n_{3}+1}|^3 + 2\,\mathbb{E} X_{n_{3}+1}^2  \,\mathbb{E}|X_{n_{3}+1}|\right) P^2(N \ge i) \nn\\[4pt]
				&\quad + \frac{2\sqrt{2}}{\sqrt{\pi}} 
				\Bigg(1 -\sum_{i=1}^{n_1}\frac{1}{\lambda^2_1\sigma^2} \, {P}^2(N \ge i) -\sum_{i=n_1+1}^{n_2}\frac{1}{\lambda^2_2\sigma^2} \, {P}^2(N \ge i)\nn\\&\quad\quad\quad\quad  -\sum_{i=n_2+1}^{n_3}\frac{1}{\lambda^2_3\sigma^2} \, {P}^2(N \ge i)-\sum_{i=n_3+1}^{\infty}\frac{1}{\lambda^2_4\sigma^2} \, {P}^2(N \ge i)\Bigg).
			\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 2 of arXiv:2606.27078, 'Semimartingale Optimal Transport with Jumps: A General Framework and Equivalent Formulatio'] Let $\Theta\subseteq\mathbb{R}^d\times\mathbb{S}_+^d\times\mathcal{L}$ be closed, convex, and satisfy Assumptions~\ref{B} and~\ref{J}. Moreover, let the cost function $L$ satisfy Assumption~\ref{L}. Then we have
\begin{equation}
V(\mu_0,\mu_1)=\mathcal{V}(\mu_0,\mu_1)\quad \text{for all } \mu_0,\mu_1\in\mathcal{P}(\mathbb{R}^d),
\end{equation}
and the infimum in \eqref{SOT} is attained by some $\mathbb{P}^{\ast}\in\mathfrak{P}_{\Theta}(\mu_0,\mu_1)$ whenever $V(\mu_0,\mu_1)<\infty$.

