body:
[Lemma 1 (Weighted weak law of large numbers) of arXiv:2608.24616, '2608.24616'] For each $t$, let $(p_j(t))_{j\geq1}$ be nonnegative random weights,
independent of the iid sequence $(X_j)$, such that
$\sum_jp_j(t)\leq1$ almost surely.  If
\begin{equation*}
  p_*(t):=\sup_jp_j(t)\longrightarrow0
  \quad\text{in probability},
\end{equation*}
then, under $\E X=0$ and $\E|X|<\infty$,
\begin{equation*}
  \sum_jp_j(t)X_j\longrightarrow0
  \quad\text{in probability}.
\end{equation*}

[Proposition 14 of arXiv:2609.03403, 'Hyperpositive functions, sector bounded functions and a trace formula'] Let $G$ be a $\mathbb C^{m\times m}$-valued contractive function satisfying $\det G(z)\not \equiv 0$, analytic in $\mathbb C_r$ and extended to $\mathbb C\setminus i\mathbb R$ via
        \eqref{Gext}. The function $K_G(z,w)$ so extended is positive definite on
        \begin{equation}

        \Omega(G)=\mathbb C\setminus\left\{i\mathbb R\cup\left\{z\in\mathbb C\setminus i\mathbb R,
            \det G(z)=0\right\}\right\}.
\end{equation}
        The corresponding reproducing kernel Hilbert space of functions analytic in $\Omega(G)$, denoted by $\mathcal H_{ext}(G)$, has the
        following properties, where $\alpha\in\Omega(G)$:\smallskip

       $(1)$ $\mathcal H_{ext}(G)$ is $R_\alpha$-invariant.\\
$(2)$ For every $c\in\mathbb C^m$, the function $R_\alpha Sc\in\mathcal H(G)$ and for $\alpha$ such that $\det S(\alpha)\not=0$ it holds that
\begin{equation}

  (R_\alpha G)(z)=-2\pi K_G(z,-\overline{\alpha})G(-\overline{\alpha})^{-*},
\end{equation}
\begin{equation}
  K_G(\alpha,-\overline{\alpha})=-\frac{1}{2\pi}G^\prime(\alpha)G(\alpha)^{-1}

\end{equation}
and
\begin{equation}
\|R_\alpha Gc\|^2_{\mathcal H(G)}=2\pi c^*\frac{I-G(\alpha)^*G(\alpha)}{\alpha+\overline{\alpha}}c.
\end{equation}
$(3)$ With moreover $\beta\in\Omega(G)$ and $f,g\in\mathcal H_{ext}(G)$,
\begin{equation}
  \langle R_\alpha f,g\rangle_{\mathcal H_{ext}(G)}+  \langle f,R_\beta g\rangle_{\mathcal H_{ext}(G)}+(\alpha+\overline{\beta})
  \langle R_\alpha f,R_\beta g\rangle_{\mathcal H_{ext}(G)}=2\pi g(\beta)^*f(\alpha).

  \end{equation}
  $(4)$ We have
  \begin{equation}
    \ker R_\alpha=\left\{0\right\}.

  \end{equation}

[Proposition pro-marked-signed of arXiv:2411.12623, 'Random signed measures'] A $T$-marked signed point process $\xi$ on $S$ has independent $S$-increments iff a.s.
	\begin{equation*}
		\xi=\eta_+-\eta_-+\sum_{k}(\delta_{s_k}\otimes\delta_{\tau_k})
	\end{equation*}
	for some independent Poisson processes $\eta_+$ and $\eta_-$ on $S\times T$ with $E[\eta_+(\{s\}\times T)]\equiv 0$ and $E[\eta_-(\{s\}\times T)]\equiv 0$, some distinct points $s_1,s_2,...\in S$, and some independent random elements $\tau_1,\tau_2,...\in T^{\Delta}$ with distributions $\nu_1,\nu_2,...$, such that the measures
	\begin{equation*}
		\rho_1=\mathbb{E}[\eta_+]+\sum_{k}(\delta_{s_k}\otimes\nu_{k}),\quad\text{and}\quad 	\rho_2=\mathbb{E}[\eta_-]
	\end{equation*}
	on $S\times T$ are locally finite. Here $\rho_1$ and $\rho_2$ determine uniquely $\mathcal{L}(\xi)$, and any measures $\rho_1$ and $\rho_2$ on $\mathcal{M}_{S\times T}$ with $\sup_{s}\rho_1(\{s\}\times T)\leq 1$ and  $\sup_{s}\rho_2(\{s\}\times T)=0$ may occur. Further, $\eta_+$ and $\eta_-$ are the Jordan decomposition of the non-fixed atomic component of $\xi$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 14 of arXiv:2604.08127, 'Asymptotics of Brownian occupation measures \\ with unusually large intersections'] For any integer $m \ge 0$,

        \begin{equation}
            \int_{[0, t]^{2m}} \left| \mathbb{E} \left[ \prod_{i=1}^m \Delta_{\epsilon}(W(s_i) - \widetilde{W}(r_i)) \right] \right|\mathrm{d} \mathbf{s} \mathrm{d}\mathbf{r} \le C^m \epsilon^{m/12} (m!)^2 \left( \frac{t^m}{m!} \right)^{17/12}
        \end{equation}

[Theorem 1 (Main theorem) of arXiv:2607.23980, 'Sharp small-deviation inequalities for sums of independent\\nonnegative random variables'] Let $n\ge1$, let $X_1,\ldots,X_n$ be independent nonnegative random variables with $\E X_i\le1$, and put $S=\sum_iX_i$. For $\delta>0$, set
\begin{equation}
 b_{n,\delta}=
 \begin{cases}
 \displaystyle \delta\left(\frac{n}{n+\delta}\right)^n,&0<\delta<1,\\[0.8em]
 \displaystyle \left(1-\frac1{n+\delta}\right)^n,&\delta\ge1.
 \end{cases}
\end{equation}
Then
\begin{equation}
 \Pp\left(S<\E S+\delta\right)\ge b_{n,\delta}.
\end{equation}
For every $n$ and every $\delta\ge1$, the bound is optimal. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm NewLDP of arXiv:2609.02682, 'LDP for tensor forms'] Suppose $\{Q_n\}_{n\ge 1}$ is a sequence of symmetric, zero-diagonal $v$-tensors, such that   \begin{align}\|W_{Q_n}- W_\infty\|_{\square^*}\xrightarrow{n\to\infty}0,
\end{align}
 for some $W_{\infty}\in \mathcal{W}_v$.

Then the following conclusions hold:
 \begin{itemize}
     \item[(i)] Suppose ${\bf{X}}=(X_1,\ldots,X_n)$ where $X_i \overset{\text{i.i.d.}}{\sim} \mu$. Then $N_n(Q_n,\phi,{{\bf X}})$ satisfies an LDP with speed $n$, and the good rate function
 \begin{equation*}
J_{W_\infty}(t):=\inf_{{\boldsymbol f}\in \mathcal{F}_c:\ { G}_{{W_\infty},\phi}({\boldsymbol f})={t}}  \left\{ \int_0^1\sum_{r=1}^c f_{r}(u)\log \frac{f_{r}(u)}{\mu_r}du\right\},
\end{equation*}
with $G_{W,\phi}(\cdot)$ as in (def:g2 of the paper).
\item[(ii)] For any $\beta\in\mathbb{R}$ with $Z_{Q_n}(\beta,\mu)$ as in (equation eq:gibbs_pottsloppartition of the paper), we have
\begin{align}
\lim\limits_{n\rightarrow \infty} Z_{Q_n}(\beta,\mu)=\sup_{{\boldsymbol f}\in \mathcal{F}_c}\left\{ \beta{G}_{{W_\infty},\phi}({\boldsymbol f})
-\int_0^1\sum_{r=1}^c f_r(u)\log \frac{f_r(u)}{\mu_r}\,du\right\}.
		\end{align}


 Moreover, the maximizers of the above optimization problem are attained.
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma covariance identity of arXiv:2606.01683, 'Singular-value gap of nonreversible Markov processes'] For $u\ge s$ and $g,h \in L^2(\mu)$,
\begin{align*}
\mathds{E}_\mu[\overline{g(X_s)}h (X_u)]
=
\langle g,P_{u-s}h\rangle.
\end{align*}

[Thm 7 of arXiv:2608.30445, 'Derivation of a linearly elastic elliptic membrane shell theory in the framework of magnet'] There exist constants $\varepsilon_1>0$ and $C_1>0$ such that
			\[
			\left\{
			\sum_\alpha\|v_\alpha\|_{H^1(\Omega)}^2
			+\|v_3\|_{L^2(\Omega)}^2
			\right\}^{1/2}
			\leq
			C_1
			\left\{
			\sum_{i,j}
			\|\epsilon_{i\|j}(\varepsilon;\boldsymbol v)\|_{L^2(\Omega)}^2
			\right\}^{1/2}
			\]
			for every $0<\varepsilon\leq\varepsilon_1$ and every
			$\boldsymbol v\in\boldsymbol V(\Omega)$. Here, the constant $C_1$ is independent of the thickness $2\varepsilon$. (Proof in the paper; no proof environment follows the statement in the TeX.)

