[Proposition 28 (Canonical/modulated identity) of arXiv:2608.24863, 'Uniform Logarithmic Sobolev Inequalities for the 2D Coulomb Gas at the Diffusive Temperatu'] One has the exact thermal-equilibrium splitting
\begin{equation}
 \mathbb P_{N,\beta}=\mathbb Q_{N,\beta}(\mu_\beta),
 \qquad
 \D\mathbb P_{N,\beta}
 =\mathsf K_{N,\beta}(\mu_\beta)^{-1}e^{-\beta A_{N,\beta}}\,\D\mu_\beta^{\otimes N}.
\end{equation}

[Lemma 2 (The Hilbert endpoint) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] For every $S\subset[m]$,
\begin{equation}

 \norm{\Flat_S(K)}_{\Sch_2}=\norm K_{\cK_m}.
\end{equation}
Consequently,
\begin{align*}
 \Prof_{m,2}(K)&=\norm K_{\cK_m},\\
 \Prof_{m,r}(K)&\ge\Prof_{m,2}(K)\quad(1\le r\le2),\\
 \Prof_{m,r}(K)&\le\Prof_{m,2}(K)\quad(2\le r\le\infty).
\end{align*}

[Lemma lemma-3.6 of arXiv:2412.08964, 'Phase transition and critical behavior in hierarchical\\integer-valued Gaussian and Coulom'] For all $\beta>0$, $n\ge k\ge0$ and~$q\in\mathbb Z$,
\begin{equation}

\frac{a_k(q)}{a_k(0)}\le\theta_k^{q^2}\biggl(\,\hat c\,\prod_{j=0}^{ k-1}(b\theta_j)\biggr)^{|q|},
\end{equation}
where $\hat c:=\sup_{\ell\ge0}\frac{a(\ell+1)}{a(\ell)}$ for~$\ell\mapsto a(\ell)$ being the Fourier coefficients of~$\nu$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 9 (Chaos asymptotics, \(H^*(m)>1/2\)) of arXiv:2604.27242, 'Statistical Inference for Homogenization Limits Driven by Wiener or Hermite Processes'] Let \(\delta(\varepsilon)>0\) be such that \(\delta(\varepsilon)\xrightarrow{\varepsilon\rightarrow 0} 0\) and \(\varepsilon/\delta\rightarrow 0\) as \(\varepsilon\rightarrow 0\). For \(\varepsilon\) small enough and \(H\neq 3/4\) we have the asymptotic behaviour
\begin{align}

\mathbb{E}[T_{2}^2]&\sim D_{\star}(H,m)\,\delta^{2(2-2H)\wedge 1},\\ 
\mathbb{E}[T_{2m-2r}^2]&\leq \bigl(D^{\mathrm{Diag}}_{H,m,r}+D^{\mathrm{Off}}_{H,m,r}\bigr)\delta^{2(m-r)(2-2H)\wedge 1}\quad 1\leq r< m-1,
\end{align}
where \(D_{\star}(H,m)\) is defined in \eqref{eq: D star} and the prefactors \(D^{\mathrm{Diag}}_{H,m,r}, D^{\mathrm{Off}}_{H,m,r}>0\), depending only on \(H,m\) and \(r\), are read off Lemmas~\ref{lem: asymptotic variance m=1 H>1/2}--\ref{lem: asymptotic variance m>1 H>1/2}; only \(D_{\star}(H,m)\) is used by name in the rest of the paper. The borderline value \(H=3/4\) carries an additional \(|\log\delta|\) factor in the second-chaos asymptotic. In particular,
\begin{equation}

\mathbb{E}[(C_{\varepsilon, \delta}-\mathbb{E}[C_{\varepsilon, \delta}])^2]\sim D_{\star}(H,m)\,\delta^{2(2-2H)\wedge 1}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 (Least-favorable location for top-$t$ selection) of arXiv:2609.03466, 'Least-Favorable Location for Binomial Top-$t$ Selection'] Fix $k\ge2$, $1\le t<k$, and $\delta\in(0,1)$. There is $n_0=n_0(k,t,\delta)$ such that $\mathcal M_{n,k,t,\delta}$ is a singleton for all $n\ge n_0$. If $k=2t$, then
\begin{equation}
 p_{n,k,t}^*=\frac{1-\delta}{2}
 \qquad(n\ge n_0).

\end{equation}
If $k\ne2t$, then
\begin{equation}
 p_{n,k,t}^*
 =\frac{1-\delta}{2}
 +(k-2t)\Cd n^{-1/2}e^{-n\Gam}\{1+o(1)\}.

\end{equation}
Thus the displacement is to the right when $k>2t$ and to the left when $k<2t$. Consequently, for every $M>0$,
\begin{equation}
 n^M|p_{n,k,t}^*-\pc|\longrightarrow0.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2607.11608, '2607.11608'] Let $s\in \R$ and $f_M$ as in \eqref{fM}. Then, 
\begin{align}	
&\int_{\R^d}|f_M|^2dx=1, \\
& \int_{\R^d} |f_M|^{p}dx \sim M^{\frac{dp}{2}-d}, \\
& \int_{\R^d} |\mathcal{L}^{\frac{s}{2}}f_M|^{2}dx\les M^{2s},

\end{align}
for any $p>0$, $M\gg 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 27 of arXiv:2609.01114, 'Unbalanced spectral Tur\'an problem for color-critical graphs with prescribed large maximu'] Let	$ V_i':=V_i\setminus (L\cup K) $. Then, for every $i\in[p]$, every $j\in[p]\setminus\{i\}$, and every $v\in V_i'$, we have
	\begin{equation*}
		d_{V_j'}(v)\geq
		\begin{cases}
			\bigl(\frac1p-16\varepsilon\bigr)D, & \text{if } p=2,\\
			\bigl(\frac1p-20\varepsilon\bigr)D, & \text{if } p\geq 3.
		\end{cases}
	\end{equation*}

[Definition 38 ($\ell_{t,u}$-differential) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] If $\varphi$ is a scalar function, then we define $\angrmd \varphi$ 
to be the following $\ell_{t,u}$-tangent one-form:
\begin{align} 
\angrmd \varphi 
& \eqdef \smoothtorusproject \rmd \varphi.
\end{align}

[Lemma Lem: Song3 of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] For $\phi\in C_{lip}(\mathbb{R}^d)$, let $v\in C_b^{1,1+\beta}(\mathbb{R}_+\times \mathbb{R}^d)$ with some $\beta\in (0,1]$ be the solution to the following PDE:
		\begin{equation}
			\begin{cases}
				\partial_tv(t,x)-p(\nabla_xv(t,x))=f(t,x), \ (t,x)\in \mathbb{R}_+\times \mathbb{R}^d,\\
				v(0,x)=\phi(x),
			\end{cases}
		\end{equation}
		where $p(a)=\hat{\mathbb{E}}[\langle a, X\rangle]$ for some $X\in \mathcal{H}^d$ with $\hat{\mathbb{E}}[|X|^{1+\beta}]<\infty$. Then for any $0\leq t\leq \bar{t}\leq 1$, we have
		\begin{equation*}
			\begin{split}
				v(\bar{t},0)-\hat{\mathbb{E}}[v(t, (\bar{t}-t)X)]\geq -4(\bar{t}-t)^{\beta}\int_t^{\bar{t}}|\nabla_x v(s,\cdot)|_{\beta}ds\times \hat{\mathbb{E}}[|X|^{1+\beta}]-\int_t^{\bar{t}}\hat{\mathbb{E}}\big[-f(s,(\bar{t}-s)X)\big]ds,
			\end{split}
		\end{equation*}
		and
		\begin{equation*}
			\begin{split}
				v(\bar{t},0)-\hat{\mathbb{E}}[v(t,(\bar{t}-t)X)]\leq 4(\bar{t}-t)^{\beta}\int_t^{\bar{t}}|\nabla_x v(s,\cdot)|_{\beta}ds\times \hat{\mathbb{E}}[|X|^{1+\beta}]+\int_t^{\bar{t}}\hat{\mathbb{E}}\big[f(s,(\bar{t}-s)X)\big]ds.
			\end{split}
		\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma gl2decomp of arXiv:2609.01990, 'Jacquet-Zagier treatment of the beyond endoscopy trace formula for \(\GL_2\)'] Let \(E\) be a well-positioned étale quadratic extension of \(\mathbb{Q}_q\) with respect to \(\theta \in \text{M}_q(\mathbb{Q}_q)\) (identify \(E\) with its image \(\iota(E)\)). If \(E\) is non-split, then 
    \[
    \text{GL}_2(\mathbb{Q}_q) = \bigsqcup_{r=0}^{\infty} E^{\times} a(q^{-r}) \text{GL}_2(\mathbb{Z}_q), \qquad a(t):= \begin{pmatrix}
        t & 0 \\ 0 & 1
    \end{pmatrix}
    \]
    If \(E\) is split, we identify \(\theta\) with \((\lambda_1,\lambda_2) \in \mathbb{Q}_q \times \mathbb{Q}_q\), and then we have 
    \[
    \text{GL}_2(\mathbb{Q}_q) = \bigsqcup_{r=0}^{\infty} \begin{pmatrix}
        \lambda_1 & \lambda_2 \\ 1 & 1
    \end{pmatrix} A\: \: n(q^{-r})\text{GL}_2(\mathbb{Z}_q), \qquad n(x) =\begin{pmatrix}
        1 & x \\ 1&0
    \end{pmatrix}, \qquad A = \left\{a(t) : t \in \mathbb{Q}_q^{\times} \right\}
    \]

