[Proposition prop:four-dimensional-global-minimizer of arXiv:2608.30904, 'Entire monotone solutions of the anisotropic Allen--Cahn equation in dimension 5'] There exists a nonconstant $O(2)\times O(2)$-invariant $E_{1,4}$ global minimizer $v\in C^{1,\alpha}_{\mathrm{loc}}(\mathbb R^4)$, $-1<v<1$.  Moreover,
\begin{equation}
-\operatorname{div} a_4(Dv)+W'(v)=0
\qquad\text{in }\mathbb R^4,
\end{equation}
and
\begin{equation}
Dv(0)=0.
\end{equation}

[Definition 53 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] A probability measure $\mathbb{P}_T$ on space $\bZ_T$ is said to be a solution to the martingale problem $(\bX_0,\bF,\newG_0)$, where  $\bX_0\coloneqq  (\bu_{0},\phi_{0}) \in\mathbb{H}$,  i.e. the problem \eqref{eqn-compact-modified-stochastic-CHNSEs-3}, if and only if 
\begin{trivlist}
\item[(i)] for almost every $\bX$ belonging to the support of the measure $\mathbb{P}_T$, the function $\cp$ defined by
              \begin{equation}
                \cp(t)=  \Atwo \phi(t) +  \psi^\prime(\phi(t)) - \avg{\psi^\prime(\phi(t))}, \;\; t\in [0,T]    
              \end{equation}
belongs to $L^{2}(0,T;\newone{H})$ and 
\item[(ii)] 
for every $z \in \mathscr{V}$, the process $M_t^{z}$ defined on the canonical sample space $\bZ_T$ in \eqref{eqn-M^z_t} 
is a continuous $\mathbb{D}$ local martingale. 
\end{trivlist}

[Theorem 1 of arXiv:2609.00867, '2609.00867'] Under Assumption~\ref{ass:kernel-density}, for every \(\beta\ge0\),
\begin{equation}
 1\le\sup_{N\ge2}
 \cZ_{N,\rho}(\beta;g_{d,s}^{(m)})<\infty.
\end{equation}
More precisely, for \(0\le\beta\le1\),
\[
 0\le\sup_{N\ge2}
 \log\cZ_{N,\rho}(\beta;g_{d,s}^{(m)})
 \le C_{d,s,m,\rho}\beta^2,
\]
and for \(\beta\ge1\),
\begin{equation}
 \sup_{N\ge2}\log\cZ_{N,\rho}(\beta;g_{d,s}^{(m)})
 \le C_{d,s,m,\rho}
 \begin{cases}
  \beta\log(2+\beta),&s=0,\\
  \beta^{d/(d-s)},&0<s<d/2.
 \end{cases}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:pair-easy of arXiv:2601.07808, 'Supercritical long-range percolation on graphs of polynomial growth: the truncated one-arm'] \label[lemma]{lem:trivial_isoperimetry}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 2$, let $A \subset G$ be a finite subset, and let $r \in \mathbf{N}$.

    Then

    \begin{equation}
        \# 
        P(A,r)
        =
        \sum_{x \in A}
        \sum_{y \not\in A}
        \mathbf{1}
        \left(
            d_G(x,y)
            =
            r
        \right)
        \leq 
        c_{\mathrm{iso}}
        \left(
            \# 
            \partial A
        \right)^{d/(d-1)}
        \# S(r).
    \end{equation}

[Theorem thm:giants_MCMs of arXiv:2607.16911, 'Multipartite random graphs with given degrees: local limit, revisiting the giant, distance'] Under the assumptions of Theorem (thm:loc_lim of the paper), consider the branching process $(\mathcal T_\infty,\varnothing)$ that arises as the local limit of the graph sequence $(G_n)_{n \geq 1}$, and let $\eta$ denote its extinction probability.     
    \begin{itemize}
    \item [1.]\textbf{Supercritical regime.} Suppose condition (equation eq:ext_BP_condition of the paper) does not hold, so that $\eta<1$. Then
        \begin{align*}
        \liminf_{n \to \infty}\frac{\Exp{|\mathcal C^{(1)}_n|}}{n}>0.
            \addtocounter{equation}{1}\tag{\theequation} 
        \end{align*}


        \item [2.]\textbf{Subcritical regime.} If condition (equation eq:ext_BP_condition of the paper) holds, so that $\eta=1$, then as $n \to \infty$ we have $\frac{|\mathcal C^{(1)}_n|}{n}\ensuremath{\stackrel{\mathbb{P}}{\rightarrow}} 0.$
        \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:Cnk of arXiv:2412.05503, 'Critical scaling profile for trees and connected subgraphs \\ on the complete graph'] Let $n \ge 3$, $N = \binom n 2$, and $t=\sqrt{3e}$.
For $0 \le \frac k n \le \frac {t^2}{3e}$, we have
\begin{align} 
C(n, n+k) \lesssim   \binom N {n+k}
	\bigg( \frac 2 e \bigg)^n   \bigg( \frac{ t^2 n }{ 3 k }\bigg)^{k/2} .
\end{align}

[Lemma lemmas7.1 of arXiv:2608.01279, 'Stochastic heat equation with nondegenerate Hölder diffusion coefficient: uniqueness below'] Let $\mathcal{E}_n$ denote the following small constant 

\begin{equation}
\mathcal{E}_n=\delta_n^p+\delta_n^\gamma
+\varepsilon_n^2\delta_n^{p-2}.

\end{equation}
Then, for every \(T<\infty\), we can find $C_T>0$ depending only on $T,p,s,c_g,[g]_{C^\beta}$ such that
\begin{equation}
\sup_{t\le T}\mathbb E f_{\delta_n}
\big(r_s(D(t\wedge\tau_*^n))\big)
\le C_T\mathcal{E}_n.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:mat-slln of arXiv:2411.09516, 'Sharp Matrix Empirical Bernstein Inequalities\footnote{NeurIPS 2025 Poster}'] Let $ \mathbf{S} _n = \sum_{i=1}^n  \mathbf{Z} _i$ be a matrix martingale and $\{U_n \}$ an increasing positive predictable process on $\mathcal{F}$. For any $p\in[1,2]$, on the set
\begin{equation}
    \left\{ \lim_{n \to \infty} U_n = \infty,  \; \sum_{n=1}^\infty U_n^{-p}  \mathbb E [ \operatorname{norm}^p( \mathbf{Z} _n) | \mathcal{F}_{n-1} ] < \infty \right\},
\end{equation}
the process $U_n^{-1}  \mathbf{S} _n$ converges to 0 almost surely. Here, $\operatorname{norm}(\cdot)$ is any matrix norm.

[Corollary 6 of arXiv:2604.22644, '2604.22644'] Let $D_1$ be the duration of the first excursion regardless of whether it terminates at $0$ or $N$, i.e., $D_1=\min\{\theta_1,\tau_N\}$. The expected value of the first hitting time to $N$ is given by:
\begin{align}
    E[\tau_N] = \frac{E[D_1]}{ \displaystyle \int_0^1 \frac{p}{S(N;p)} dp },
\end{align}
where $E[D_1] = \frac{d}{dq} \Big( E[q^{\theta_1} I(e_1 \text{ does not reach } N)] + E[q^{\tau_N} I(e_1 \text{ reaches } N)] \Big) \Big|_{q=1}$, and $S(N;p)$ is the scale function defined in Theorem \ref{thm1}.

