[Theorem 11 (Hausdorff dimension in the high-Hurst regime) of arXiv:2606.11994, 'Sample Path Properties of the\\ Fractional Wiener--Weierstrass Bridge II'] If
$  H>K$,  $H>1/2$, then  
\begin{equation*}
  \dimH\Graph(Y)=2-K
  \qquad\text{$\Pp$-a.s.}

\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm Thm_fsop of arXiv:2608.30548, 'Finite speed of propagation and waiting time phenomena for stochastic porous media equatio'] Let $u$ be the unique kinetic solution to (equation Eq_SPME_intro of the paper) under the assumptions (equation equation_n_m_together of the paper)--(equation Eq_ass_B3 of the paper). Then $u$ has finite speed of propagation.  Furthermore, if, for a given $x_0 \in \mathbb{T}^d\setminus \mathrm{supp}(u_0)$, there exists $r_0>0$ such that
  for the parameter 
  \begin{equation}

    \theta =  \frac{2(\alpha+1)+d(m-1)}{2(n-1)}
  \end{equation}
  and some $f\in \mathscr C_{2r_0,\kappa}$, where 
    \[
        \kappa = \left( \frac{\alpha+m}{\alpha+1}, \frac{2(\alpha+2n-1) + d(m+1-2n)}{2(\alpha+1)+d(m+1-2n)} \right), 
    \]
  we have
    \begin{equation}
        \sup_{r\in (0,r_0)} \ \frac{1}{f(r)r^{\theta}} \ \int_{B_{R_0+r}(x_0)\setminus B_{R_0}(x_0)} u_0^{\alpha+1} < +\infty, 
       \end{equation}
        then $u$ exhibits a waiting time phenomenon  associated with the ball $B_{R_0}(x_0)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 20 of arXiv:2607.29534, 'Expected signatures via partial integration, coordinate change and symmetrization'] Consider a deterministic path $A=(A_t)_{t\in [0,T]}$ satisfying Assumption~\ref{ass:mambo} and let $\mathbb{P}\in \mathcal{P}_A$, such that the one-dimensional marginals of the canonical process satisfy \eqref{eq:moment-deter-real}. Then \begin{equation}
        \wh{\bmu}^\mathbb{P}_{0,T}(A) =\wh{\bmu}^\mathbb{Q}_{0,T}(A) \quad \Leftrightarrow \quad \mathbb{P}=\mathbb{Q}, \qquad \forall \,  \mathbb{Q} \in \mathcal{P}_A.
    \end{equation}

[Lemma 41 of arXiv:2605.09459, 'Multipoint connectivity in the branching interlacement process'] Let $\mathcal{A} \in \mathbb{A}_{k,n,m}$. For each $\vec{a} = (u,v) \in \mathcal{A}_i$, let
  \[
    \delta(\vec{a}) = \begin{cases}
      0 & \text{if } \vec{a} \text{ has no parent of if they have different colors}, \\
      1 - \frac{\indic{u \in V^b}}{\mathrm{deg}_{\mathcal{A}_i}(u) - 1}(2 - \indic{\mathrm{deg}_{\mathcal{A}_i}(u) = 2}) &\text{otherwise.}
      \end{cases}
  \]
  Then for $\vec{e} \in \mathcal{A}$,
  \begin{equation}

    x(\vec{e}) + y(\vec{e}) - 1 \leq z(\vec{e}) + \sum_{\vec{a} \in \mathcal{A}(\vec{e})} \delta(\vec{a}) \leq x(\vec{e}) + y(\vec{e}).
  \end{equation}

