[Definition def:branching-number:growth of arXiv:2411.14111, 'Stochastic processes on preferential attachment models'] The \emph{branching number} of a tree $\Gamma$, denoted by $\rm{br}(\Gamma)$, is defined as
	\eqan{
		\rm{br}(\Gamma)=&~\inf\Big\{ \lambda>0:\liminf\limits_{\Pi\to\infty}\sum\limits_{u\in\Pi} \lambda^{-|u|}=0 \Big\}\\
		=&~\sup\Big\{ \lambda>0:\liminf\limits_{\Pi\to\infty}\sum\limits_{u\in\Pi} \lambda^{-|u|}=\infty \Big\}\nn\\
		=&~\inf\Big\{ \lambda>0:\inf\limits_{\Pi}\sum\limits_{u\in\Pi} \lambda^{-|u|} \Big\}
		~,\nn}
	whereas the \emph{growth} of $\Gamma$, denoted by $\rm{gr}(\Gamma)$, is defined as
	\eqn{
		{\rm{gr}}(\Gamma)=\inf\Big\{ \lambda>0:\liminf\limits_{n\to \infty} {M_n}\lambda^{-n}=0\Big\}=\liminf\limits_{n\to\infty}M_n^{1/n}
		~,}
	where $M_n$ is the size of the $n$-th generation in the tree $\Gamma$.

[Definition 4 of arXiv:2504.02435, 'Poisson-Voronoi percolation in higher rank'] A countable group~$\Gamma$ has the {\em FIID sparse unique infinite cluster property} if there exists a Cayley graph ${\rm Cay}(\Gamma)$ of~$\Gamma$ such that
    \begin{equation} 
    \inf \bigg\{ \int_{\omega\in \mathcal U(G)} {\rm deg}_\omega(1_{\Gamma}) \, d \mu(\omega) \colon \mu\in F_{{\rm IID}}(\Gamma,\mathcal U({\rm Cay}(\Gamma))) \bigg\} = 0,
    \end{equation}
    where $\mathcal U({\rm Cay}(\Gamma))$ is the set of subgraphs of ${\rm Cay}(\Gamma)$ with a unique infinite cluster, $F_{{\rm IID}}(\Gamma,\mathcal S(\Gamma))$ is the set of $\Gamma$-invariant probability measures on $\mathcal U({\rm Cay}(\Gamma))$ which are factors of iid~processes on $\Gamma$ and $1_\Gamma$ denotes the identity of $\Gamma$.

[Lemma 3 (Packet domination) of arXiv:2609.02156, 'The higher-dimensional Shepp problem: an exact criterion for random ball coverings of tori'] For $t>0$,
\begin{equation}
 \e^{G(t)}
 \le1+\e^d\sum_{k\ge k_*}
 (\e^{\whatA_k}-\e^{\whatA_{k-1}})
 \exp\!\left(-\frac{dt}{2\ell_k}\right).
\end{equation}

