body:
[Definition def:lattice-ym of arXiv:2605.16162, 'Deconfinement For $\mathrm{SO}(3)$ Lattice Yang--Mills at Strong Coupling'] The \textit{lattice Yang-Mills measure} with Wilson action, and gauge group $G$ is the measure on $G^{E_{\Lambda}^+}$ given by
\begin{equs}
    d\mu_{G,\Lambda, \beta}(Q) := \frac{1}{Z_{\Lambda, \beta}} \exp(S_{\Lambda,\beta}(Q)) dQ,
\end{equs}
where the action is given by
\begin{equs}
    S_{G,\Lambda,\beta}(Q):=\sum_{p \in \mc{P}_{\Lambda}^+}\beta \mrm{Re}\mathrm{Tr}(Q_p)
\end{equs}
and $dQ = \prod_{e \in E_\Lambda^+} dQ_e$, and each $dQ_e$ is an independent copy of Haar measure on $G$ for each edge $e \in E_{\Lambda}^+$. Finally, the partition function,
\begin{equs}
Z_{\Lambda, \beta} :=\int_{G^{E_{\Lambda}^+}}\prod_{p \in \mc{P}_{\Lambda}^+} \exp(\beta \mathrm{Tr}(Q_p)) dQ.
\end{equs}
Since we always set $G=\mathrm{SO}(3)$, we will often use the notation $\langle \cdot \rangle_{\mu_{\Lambda, \beta}}$ or $\langle \cdot \rangle_{\Lambda, \beta}$ or even just $\langle \cdot \rangle$ to denote the expectation with respect to the probability measure $\mu_{G,\Lambda, \beta}$.

[Proposition e:renewal finite second moment of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Suppose that
    \begin{equation}
        \int x^2\,  \BQ(dx) < \infty,
    \end{equation}
    and choose $\sigma^2:= \int x^2\,  \BQ(dx)-\mu^2$.
    Then, as $k\to 0$,
    \begin{equation}
        g(k) = \frac{\sigma^2}{\mu^3} + o(1).
    \end{equation}
    Hence, $\Phi$ is solely $0$-uniform with 
    \begin{equation}
        \frac{\BV[\Phi(B_r)]}{\lambda_d(B_r)} \xrightarrow{r\to\infty} \frac{\sigma^2}{\mu^3}.
    \end{equation}
    \begin{proof}
        By Taylor's theorem and~(equation e:renewal finite second moment of the paper), as $k\to 0$,
        \begin{equation*}
            \hat\BQ(k) = 1-i\mu k - \frac{1}{2}(\sigma^2+\mu^2)k^2 + o(k^2).
        \end{equation*}
        Therefore, as $k\to 0$,
        \begin{align*}
            \Re(1-\hat\BQ(k)) &= \frac{1}{2}(\sigma^2+\mu^2) k^2 + o(k^2),\\
            \Im(1-\hat\BQ(k)) &= \mu k + o(k^2).
        \end{align*}
        These can be inserted in~(equation e:renewal bartlet formula of the paper) to obtain, as $k\to 0$,
        \begin{align*}
            g(k) &= \frac{1}{\mu}\bigg(1+2\Re\bigg(\frac{\hat\BQ(k)}{1-\hat\BQ(k)}\bigg)\bigg) \nonumber\\
            &= \frac{1}{\mu} \bigg(2\Re\bigg(\frac{1}{1 - \hat\BQ(k)}\bigg) - 1\bigg) \nonumber\\
            &= \frac{1}{\mu}  \bigg(2\frac{\frac{1}{2}(\sigma^2+\mu^2) k^2 + o(k^2)}{\frac{1}{4}(\sigma^2+\mu^2)^2 k^4 + o(k^4) + \mu^2 k^2 + o(k^3)} - 1\bigg) \nonumber\\
            &= \frac{1}{\mu} \bigg(\frac{\sigma^2+\mu^2}{\mu^2} - 1 + o(1)\bigg) \nonumber\\
            &= \frac{\sigma^2}{\mu^3} + o(1).
        \end{align*}
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2607.29020, 'Entropic Symmetrization Resistance'] \label[definition]{def:Bern_Ir}
For $r \in [0,1]$ we define the \emph{index set $I^r$} to be 
\[ 
I^r = \begin{cases}
    \mathbb{N} = \{1, 2, \dots \} & \text{ when } r = 0 \\
    \mathbb{Z} & \text{ when } r \in (0,1) \\
    \mathbb{N}_0 = \{0, 1, 2, \dots \} & \text{ when } r = 1 .
    \end{cases}
\]

[Theorem sum-Jn of arXiv:2604.24914, 'SPDEs with time-independent\\ L\'evy colored noise'] Suppose that Hypotheses A', B', D' and E' hold. Then $f_n^{*}(\cdot,x;t)\in \mathcal{H}^{\otimes n}$ for any $n\geq 1$ and $(t,x)\in \mathbb{R}_{+}\times \mathbb{R}^d$. If in addition,
\begin{equation}

\sum_{n\geq 1}m_2^n t^n J_n(t)<\infty \quad \mbox{for any $t>0$},
\end{equation}
then equation (equation mult-eq of the paper) has a unique solution.

