  \item[(i)] For all $\gamma>0$ and $\alpha<H+\gamma$, 
\begin{align} 
 \lim_{\epsilon\to 0} \epsilon^{1/(H+\gamma)} \log \pr\left(\sup_{0\le  t\le 1}t^{-\alpha}\left| I_{\gamma}(B_H)(t) \right|<a_H \epsilon\right) 
 =-\frac{\kappa_{H+\gamma}}{1-\alpha/(H+\gamma)}. 
