[Lemma lem:centered-cubic-label of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] Put
\begin{equation}
 S_1=\sum_{i=1}^t(\ell_i-1),\qquad
 S_2=\sum_{i=1}^t(\ell_i^2-1),\qquad
 Y_x=2x+4-S_1,\qquad L=S_2-4,
\end{equation}
and define
\begin{equation}
 P_{\boldsymbol\ell}(x)=Y_x^3+LY_x.
\end{equation}
Then
\begin{equation}
 48\sum_{0\leq j_i<\ell_i}M_{x-J}
 =R P_{\boldsymbol\ell}(x)
\end{equation}
whenever all $x-J\geq0$.  Consequently every set in
Lemma~(lem:stable-suspended-chart of the paper) satisfies the exact integer identity
\begin{equation}
 48|hA_t|=R\,G_{\boldsymbol\ell}(u,v,b,c),
\end{equation}
where
\begin{equation}
 G_{\boldsymbol\ell}(u,v,b,c)=
 P_{\boldsymbol\ell}(h)-P_{\boldsymbol\ell}(u)
 +P_{\boldsymbol\ell}(v)-P_{\boldsymbol\ell}(b)
 -P_{\boldsymbol\ell}(c)\in\mathbb Z_{>0}.
\end{equation}
Uniformly on the construction,
\begin{equation}
 |hA_t|\asymp_t Rh^3\asymp_t h^{t+3}.
\end{equation}

[Defn def:tr of arXiv:2609.02682, 'LDP for tensor forms'] Given a hypergraphon $W\in \mathcal{W}_v $, and functions $\phi:[c]^v\to \mathbb{R}$ and ${\boldsymbol{f}}\in \mathcal{F}_c$, we define
 \begin{align}
\notag\mathcal T_r^{(m)}[W,\phi,{\boldsymbol f}](x)
:=&
\int_{[0,1]^{v-1}}
W(x_1,\ldots,x_{m-1},x,x_{m+1}, \ldots, x_v)\\
&\sum_{\substack{s_1,\ldots,s_{m-1},s_{m+1},\ldots,s_v\in[c]}}
\phi(s_1,\ldots,s_{m-1},r,s_{m+1},\ldots,s_v)
\prod_{\substack{a=1\\ a\neq m}}^v f_{s_a}(x_a)\prod_{\substack{a=1\\ a\neq m}}^vdx_a,
\end{align}
for $m\in[v], r\in [c]$.

[Lemma lem:hitting-time of arXiv:2604.20008, 'Mixing times of Langevin dynamics for \\ spiked matrix models'] Suppose that $\alpha>1$ and $\theta>\theta_{0,L}$, and let $C_E$ denote the lower bound obtained from Corollary (coro:m_easy of the paper) for the region $|m(x)| < \mathsf{m}_{3}$. Fix any initialization $X_0$ and let $\tau_{m,\varepsilon} $ denote the first time $|m_t| \geq \varepsilon$, then for any $r>0$ we have 
    \begin{align*}
        \mathbb P[ \tau_{m,\varepsilon} > T+r ] \leq  2e^{-r}\,,\quad
        \text{ where } \quad &T=\frac1{C_E}\Big( \log \sqrt{N}+\log(\sqrt{\frac{\beta C_E}2}\arcsin\varepsilon)\Big)\,.
    \end{align*}
    In particular, $|m_t|$ hits the threshold $\mathsf{m}_{3}$ of~(equation eq:def-of-m-1-2-3 of the paper)  with probability at least $1-2e^{-100}$ in time $T_{\text{hit}}$, where $T_{\text{hit} }$ is given by: 
    \begin{align} 
        T_{\text{hit}}=100 \frac{ \tfrac{1}{2} \log N+\log (\sqrt{\frac12\beta (\lambda_1-\lambda_2)(\mathsf{m}_{\textsc{e}}^2-\mathsf{m}_{3}^2)}\arcsin \mathsf{m}_{3})}{(\lambda_1-\lambda_2)(\mathsf{m}_{\textsc{e}}^2-\mathsf{m}_{3}^2)}\,.
    \end{align}
    Note that if $\lambda_1 - \lambda_2 = \Omega(1)$, then $T_{hit} = O(\log N)$.

