[Theorem 18 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] Let $H\in\left(0,1\right)$ and $(\mathbf{x}_t)_{t\geq 0}$ be a solution to \eqref{eq:fast system simplified} in the setting \nameref{S2}. For any $\tau\ge0$, it holds that
\begin{align}
    \begin{split}
    &V_\infty(\tau)\left[ \mathbf{e}_{j_1}^*(\lambda), \mathbf{e}_{j_2}^*(\lambda) \right]\\
    =& \left(-\zeta_{j_1}(\lambda)-\overline{\zeta_{j_2}(\lambda)}\right)^{-1} H \left\langle  \mathbf{e}_{j_2}^*(\lambda), Q \mathbf{e}_{j_1}^*(\lambda)\right\rangle P(\zeta_{j_1}(\lambda),\zeta_{j_2}(\lambda),H,\tau) ,
    \end{split}
\end{align}
with $\zeta_1(\lambda)= A(\lambda) + i B(\lambda)= \overline{\zeta_2(\lambda)}$ and for any $j_1,j_2\in\{1,2\}$. Under the assumption that $\Sigma$ is not null, it follows that
\begin{align}
    |V_\infty(\tau)\left[ \mathbf{v}_1, \mathbf{v}_2 \right]|\asymp& |A(\lambda)|^{-1},
\end{align}
for almost every $\tau\ge0$ and any $\mathbf{v}_1, \mathbf{v}_2 \in \R^2$ such that
\begin{equation} 
    \begin{split}
        &e^{-i B(\lambda^*)\tau} \left\langle  \mathbf{e}_{1}^*(\lambda^*), Q \mathbf{e}_{1}^*(\lambda^*)\right\rangle \overline{\left\langle \mathbf{v}_1, \mathbf{e}_{1}(\lambda^*) \right\rangle} \left\langle \mathbf{v}_2, \mathbf{e}_{1}(\lambda^*) \right\rangle\\
        &+
        e^{i B(\lambda^*)\tau} \left\langle  \mathbf{e}_{2}^*(\lambda^*), Q \mathbf{e}_{2}^*(\lambda^*)\right\rangle \overline{\left\langle \mathbf{v}_1, \mathbf{e}_{2}(\lambda^*) \right\rangle} \left\langle \mathbf{v}_2, \mathbf{e}_{2}(\lambda^*) \right\rangle \neq 0.
    \end{split}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 of arXiv:2609.03084, 'Convergence rates to traveling waves for an FKPP model with nonlinear advection'] Assume that $U$ and $U_\epsilon$ solve on the positive half line
        \begin{align*}
            U'' + 2U' + U-A(U) - \chi A'(U)U' = 0\\
            U''_\epsilon + (2-\epsilon)U'_\epsilon + U_\epsilon - A(U_\epsilon) - \chi A'(U_\epsilon)U_\epsilon' = 0,
        \end{align*}
        as well as 
        \[U(0) - U_\epsilon(0) = O(\epsilon), \quad U'(0) - U'_\epsilon(0) = O(\epsilon),\]
        as $\epsilon \to 0$. In addition assume
        \begin{equation}
            U, U' = O(ze^{-z}) 
        \end{equation}
        as $z \to \infty$. Then for any $\eta > 0$, there exists $\epsilon_\eta$ such that for all $0 < \epsilon \leq \epsilon_\eta$ and
        $z \geq 0$,
        \begin{equation}
            |U(z)-U_\epsilon(z)| \leq (\epsilon e^{-z})^{1-\eta}. 
        \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 15 (Uniform global $C^0$ estimate) of arXiv:2608.29736, '2608.29736'] There exists \(C>0\), independent of \(t\), such that
\begin{equation}
-C\leq u_t\leq0\qquad\text{on }M,\qquad 0<t\leq t_0.
\end{equation}

