body:
[Corollary cor:optimalGaussian of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] Let $\kappa>1$ and set
\begin{equation*}
 h_*=\frac{2}{\sqrt{\kappa+1}},
 \qquad
 \gamma_*=\sqrt{\kappa+1}\,\log\frac{\sqrt\kappa+1}{\sqrt\kappa-1},
\end{equation*}
so that
\begin{equation*}
 \beta_*=e^{-\gamma_*h_*}=\left(\frac{\sqrt\kappa-1}{\sqrt\kappa+1}\right)^2,
 \qquad
 s_*=\frac{h_*^2}{2}(1+\beta_*)=\frac{4}{(\sqrt\kappa+1)^2}.
\end{equation*}
Let $U_H(x)=\frac12x^\top Hx$ on $\mathbb R^d$ with $\mathrm{Id}_d\preceq H\preceq\kappa\mathrm{Id}_d$, and write $Q=Q_{h_*,\gamma_*}^{U_H}$. Then $Q$ has a unique invariant law $\pi_H$, and $\pi_H$ is a centered Gaussian. For every initial state $z\in\mathbb R^d\times\mathbb R^d$,
\begin{equation*}
 \limsup_{n\to\infty}\lVert \delta_zQ^n-\pi_H\rVert_{\mathrm{TV}}^{1/n}
 \le\sqrt{\beta_*}=\frac{\sqrt\kappa-1}{\sqrt\kappa+1},
\end{equation*}
and for suitable $z$ the limit exists and equals $\sqrt{\beta_*}$. Moreover, there are initial states $z,\widetilde z$ with
\begin{equation*}
 \lim_{n\to\infty}\norm{\delta_zQ^n-\delta_{\widetilde z}Q^n}_{\mathrm{TV}}^{1/n}
 =\sqrt{\beta_*}.
\end{equation*}

[Defn 18 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let $\phi\in\text{\rm SCL}\,(\T^n)$. We define the function of \emph{degree of regularity} of $\phi$ as
	\begin{align*}
		R_\phi(x)=
		\begin{cases}
			\inf\{\lambda\geqslant0: |p-D\phi(x)|\leqslant\lambda\cdot d(y,x),\forall y\in\T^n, p\in D^+\phi(y)\},&x\in \reg(\phi),\\
			+\infty,&x\in\cut(\phi),
		\end{cases}
	\end{align*}
	and the sub-level set of $R_\phi$ as
	\begin{align*}
		F(\phi,\lambda)=\{x\in\T^n: R_\phi(x)\leqslant\lambda\},\qquad\lambda\geqslant0.
	\end{align*}

[Prop cubePartitionSize of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] Assume (equation e:local_dependence of the paper), (equation e:rarely_bad of the paper) for $\mathcal{G}$, then for every $t \geqslant 1$, there exists a finite positive constants $C$ depending on $t,s,K,d$ there, such that 
		\begin{equation}
			\mathbb{P}[	{\scaleobj{1}{\square}} \notin\Lambda(\mathcal{G}, t, C)] \leqslant C \exp\left(- C^{-1}  \size({\scaleobj{1}{\square}})^{\frac{ds}{d+t+s}}\right).
