body:
[Prop 27 (Exact fixed-weight formula) of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] For $a > 0$ and $p \in (0, 1/2]$,
\begin{align}
    \nu^{\SG}_{\max}(p,a)
    = \inf_{0 < \lambda < 1/a} \frac{1}{\lambda}\,g_p^{-1}\!\left(\frac{\lambda^2}{2(1 - a\lambda)}\right)
    = a \inf_{0 < \theta < 1} \frac{1}{\theta}\,g_p^{-1}\!\left(\frac{\theta^2}{2a^2(1-\theta)}\right).

\end{align}
Consequently,
\begin{align}
    c^{\SG}(1,a)
    = \sup_{0 < p \le 1/2} \frac{a(1-p)}{1 + \log\frac{1}{2p}}
    \inf_{0 < \theta < 1} \frac{1}{\theta}\,g_p^{-1}\!\left(\frac{\theta^2}{2a^2(1-\theta)}\right).

\end{align}

