body:
[Theorem Liggett, Schonmann, Stacey of arXiv:2509.10990, 'On the Continuity of Enhancement Percolation'] For any $d,k \in \mathbb{N}, \epsilon > 0$ there is a $\delta > 0$ so that if $X$ is a $k$-dependent site percolation on $\mathbb{Z}^d$ that satisfies
    \[\mathbb{P}\left( v \in X \mid X \cap \left( \Lambda_k\left( v \right) \setminus v \right) = \omega \right) > 1-\delta\]
    for any $v \in \mathbb{Z}^d, \omega \subset \mathbb{Z}^d,$ then $X$ stochastically dominates a Bernoulli site percolation with parameter $1-\epsilon.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 2 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] Let $p=1$ and~\eqref{co:1}--\eqref{co:3} be satisfied. Then~\eqref{eq:SIS epidemic model} admits a unique strong solution $I$ such that $I_{0} = \xi_{0}$ a.s.~and
\begin{equation}
\E\big[I_{t}\big] \leq e^{\int_{0}^{t}\hat{b}_{k+2}(s,N(s))\,\mathrm{d}s}\E\big[\xi_{0}\big] + \int_{0}^{t}e^{\int_{s}^{t}\hat{b}_{k+2}(\tilde{s},N(\tilde{s}))\,\mathrm{d}\tilde{s}}\hat{b}_{0}(s,N(s))\,\mathrm{d}s
\end{equation}
for all $t\geq 0$. Moreover, the following two assertions hold:
\begin{enumerate}[(i)]
\item If $\hat{b}_{k+2}^{+}(\cdot,N)$ and $\hat{b}_{0}(\cdot,N)$ are integrable, then $\sup_{t\geq 0}\E[I_{t}] < \infty$. In this case, we have $\lim_{t\uparrow\infty} \E[I_{t}] = 0$ as soon as $\int_{0}^{\infty}\hat{b}_{k+2}^{-}(s,N(s))\,\mathrm{d}s = \infty$.

\item If $\xi_{0} = i_{0}$ a.s.~and~\eqref{co:4} holds, then $0 < I < N$ a.s.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma drift-lemma-super-HW of arXiv:2504.02207, 'Finite-Time behaviors of M/M/$n$ Queue: Mixing Time, Mean Queue Length and Tail Bounds'] Let $V$ be defined as in (equation eqn: mmn-lyapunov of the paper) and $\cL$ be the generator of the $M/M/n$ queue in the super Halfin-Whitt regime (i.e. $\alpha > 1/2$) with arrival rate $\lambda_n = n-n^{1-\alpha}$. Then, there exists $\gamma_n \geq \br{\sqrt{n}-\sqrt{\lambda_n}}^2$ and a function $b: \Z_{\geq 0} \rightarrow \R_{\geq 0}$ such that:
    \begin{align}

        \cL V(q) \leq -\gamma_n V(q) + b(q)1_K \, \forall q \in \Z_{\geq 0}
    \end{align}
    where $K = \{[\lfloor 2\lambda_n \rfloor - n]^+,...,n-1\}$.







    Furthermore, we have $b(q) \leq L \, \forall q \in K$ for some constant $L > 0$ and $2 \leq n \leq 7$ and for $n > 7$, we have
    \begin{align}

        b(q) =  
        \begin{cases}
            \frac{n^{1-2\alpha}}{1-n^{-\alpha}} e^{\frac{n^{1-2\alpha}}{1-n^{-\alpha}}} \,\, &\forall q \in K-\{n-1\} \\
            n^{1-\alpha}\bigg(1 + \frac{1}{4(n^\alpha-1)}\bigg) &\text{if } q = n-1 \\
             0 \,\, &\forall q \not \in K.
        \end{cases}
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:small-jumps of arXiv:2608.28004, 'Hausdorff Dimension of the Set of Extreme Points\\ of a Random Countable Stable Zonotope'] For every \(q>0\), there exists \(C_q<\infty\), depending only on \(d\),
\(\alpha\), and \(q\), such that
\begin{equation}
    \mathbb E\bigl[(1+M_Q)^N V_Q^{\,q}\bigr]
    \leq C_q\,\delta^{q}
\end{equation}
uniformly over all positive integers \(n\) and all \(Q\in\mathcal Q_n\).

[Corollary COR33 of arXiv:2412.08886, 'On domination for (non-symmetric) Dirichlet forms'] \begin{itemize}
\item[(1)] A set $N\subset G$ is ${\mathscr E}^G$-polar if and only if it is ${\mathscr E}$-polar.
\item[(2)] Let $G_1\subset G$.  Then, $G_1$ is ${\mathscr E}$-quasi-open  if and only if it is ${\mathscr E}^G$-quasi-open.
\end{itemize}

[Theorem afixed_t of arXiv:2412.06086, 'Zeros of conditional Gaussian analytic functions, random sub-unitary matrices and q-series'] For every
$x\in \mathbb{C}\backslash \big((-\infty, 0] \cup [1, +\infty)\big)$
and $t\ge 0$,
\begin{align}
F(x,t;q)=\exp \left[
{-\frac 1 \varepsilon\, {\operatorname{Li}}_2(x)+\frac{1}{2} \log (1-x) + t x + O(\varepsilon)}
\right]
\;, \quad \varepsilon=-\log q \to 0^+
\end{align}
Equation (equation F1 of the paper) also holds true as $x$ approaches zero at an angle $\phi $ with the positive real axis provided that $\phi \not= \pi$.

[Corollary thm:main-upper of arXiv:2605.16244, 'Analysis of a twisted Bose--Einstein Markov chain with applications to sampling Catalan st'] For $n\ge2$,
\begin{equation}
 \lambda_{2,\mathrm{PF}} = \lambda_2(K_{\mathrm{PF}})
 =\frac{n}{2(n+1)}.

\end{equation}
For every $t\ge1$,
\begin{equation}
 d_{K_{\mathrm{PF}}}(t)
 \le
 n\sqrt{\frac{n+1}{2}}\lambda_{2,\mathrm{PF}}^{t/2}.

\end{equation}
Finally, for every fixed $0<\varepsilon<1$,
\begin{equation}
 t_{\mathrm{mix},K_{\mathrm{PF}}}(\varepsilon)
 \le3\log_2n+O_\varepsilon(1).
\end{equation}

[Definition 9 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] Given regularisation scales $0 < \delta < \eps$, throughout this section, we define the smooth and stationary random noise assignment $\tilde{\pi}^{\eps, \delta}: \tilde{\mfL}_- \to C^\infty(\mbR^2)$
	\begin{align*}
		\tilde{\pi}^{\eps, \delta} \<b0> &= \xi_\eps, \quad \tilde{\pi}^{\eps, \delta} \<p0> = \xi_{\delta}, \quad \tilde{\pi}^{\eps, \delta} \<s(1)0> = \eps^{-1/2} \partial_x K \ast \xi_{\eps, \delta}
		\\
		\tilde{\pi}^{\eps, \delta} \<bs(2)0> &= \eps^{-1/2} \partial_x K \ast \xi_{\eps, \delta} \partial_x K \ast \xi_{\eps} - \ell(\<bs(2)0>), \\
		\tilde{\pi}^{\eps, \delta} \<ps(2)0> &= \eps^{-1/2} \partial_x K \ast \xi_{\eps, \delta} \partial_x K \ast \xi_{\delta} - \ell(\<ps(2)0>),
	\end{align*}
	where $\ell(\<bs(2)0>)$ and $\ell(\<ps(2)0>)$ are such that $\mathbb{E}[\tilde{\pi}^{\eps, \delta} \tau(0)] = 0$ for $\tau \in \{\<bs(2)0>, \<ps(2)0>\}$.

	We write $\tilde{Z}^{\eps, \delta} = (\tilde{\Pi}^{\eps, \delta}, \tilde{\Gamma}^{\eps, \delta})$ for the corresponding BPHZ model.

[Prop 9 of arXiv:2510.24562, 'Hard wall repulsion for the discrete Gaussian free field in random environment on $\mathbb'] For every $\varepsilon \in (0,1)$ and $\rho \in [0,1)$
    \begin{equation}
        \lim_{N \to \infty} \sup_{\omega \in \Omega_{\lambda,\Lambda}} \sup_{\cS} \sup_{z \in V_N^\varepsilon}P^\omega_z [H_S = \infty] = 0 \,.
    \end{equation}

