body:
[Proposition 11 of arXiv:2608.21551, '\bf Sparse Separable Factor Analysis in the Complex Domain with an Application to Local Fi'] For $j=1,\ldots,d$, let $\Lambdab_j\in\CC^{p_j\times k_j}$ be a nonzero true loading matrix, and let $\widehat{\Lambdab}_j$ denote its estimate. Define the orthogonal projector onto the column space of $\widehat{\Lambdab}_j$ by
\begin{align*}
  \widehat{\Pb}_j
  &=
  \widehat{\Lambdab}_j
  \left(
    \widehat{\Lambdab}_j^\star
    \widehat{\Lambdab}_j
  \right)^+
  \widehat{\Lambdab}_j^\star,
\end{align*}
where $+$ denotes the Moore--Penrose pseudoinverse. The weighted null-space projection error is
\begin{align}
  \operatorname{err}_{\Lambdab_j}^2
  &=
  \frac{
    \left\|
      \left(
        \Ib_{p_j}-\widehat{\Pb}_j
      \right)
      \Lambdab_j
    \right\|_F^2
  }{
    \|\Lambdab_j\|_F^2
  }.

\end{align}

Let $  \Lambdab_j = \Ub_j\Deltab_j\Vb_j^\star$ be a ``compact'' singular value decomposition of $\Lambdab_j$, where
$r_j=\operatorname{rank}(\Lambdab_j)$. For $i=1,\ldots,r_j$, let $\ub_{(j)i}$ denote the $i$th column of $\Ub_j$, and let $d_{(j)i}>0$ be the corresponding singular value. Define $\omega_{(j)i}\in[0,\pi/2]$ by
\begin{align}
  \cos\left(\omega_{(j)i}\right)
  &=
  \left\|
    \widehat{\Qb}_j^\star\ub_{(j)i}
  \right\|_2,

\end{align}
where the columns of $\widehat{\Qb}_j$ form an orthonormal basis for the column space of $\widehat{\Lambdab}_j$. The
angle between $\ub_{(j)i}$ and the estimated loading space is $\omega_{(j)i}$. Then,
\begin{align}
  \operatorname{err}_{\Lambdab_j}^2
  &=
  \sum_{i=1}^{r_j}
  v_{(j)i}
  \sin^2\left(\omega_{(j)i}\right),
  \qquad
  v_{(j)i}
  =
  \frac{
    d_{(j)i}^2
  }{
    \displaystyle
    \sum_{\ell=1}^{r_j}d_{(j)\ell}^2
  }.

\end{align}
In particular, $\operatorname{err}_{\Lambdab_j}^2\in[0,1]$.

[Lemma 16 of arXiv:2607.13401, 'Total variation cutoff for Kac's walk on the sphere'] For every \(0\le s_0<\infty\), there are constants
\(\eta_0=\eta_0(s_0)>0\) and \(C=C(s_0)<\infty\) such that the following
holds.  Let \(\alpha,\beta\in\mb R^m\) satisfy
\[
        \sum_i\alpha_i=\sum_i\beta_i=0,
        \qquad
        \norm{\alpha}_\infty\norm{\beta}_\infty\le\eta_0 .
\]
Then, for every \(|s|\le s_0\),
\begin{equation}
        \mb E_\Pi
        \exp\left\{
        s\sum_{i=1}^m\alpha_i\beta_{\Pi(i)}
        \right\}
        \le
        \exp\left\{
        C s^2
        \frac{\norm{\alpha}_2^2\norm{\beta}_2^2}{m}
        \right\},
\end{equation}
where \(\Pi\) is a uniform random permutation of \(\{1,\ldots,m\}\).

[Lemma 227 (Precise $L^2$ estimates for the top-order fully modified quantities) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $N = \Ntop$,  let
$\tander^N \in \mathfrak{P}^{(N)}$ be the set of order $N$ $\ell_{t,u}$-tangential commutator operators from
Def.\,\ref{D:STRINGSOFCOMMUTATIONVECTORFIELDS}. Let $\blowuprateofwaveWRTnumberofcommutations(N) = \blowupratetoporderwave$ denote the blowup rate of the wave variables defined in \eqref{E:BLOWUPRATEOFWAVEWRTNUMBEROFCOMMUTATORS}. Let $\varsigma_0$ be the constant featured in Lemma\,\ref{L:PRELIMINARYBELOWTOPORDERL2ESTIMATESFOREIKONALFUINCTIONQUANTITIES} (see also Remark\,\ref{R:SMALLNESSCONSTANTFORBELOWTOPORDERACOUSTICVARIABLES}). Let $\sumofbrevexvisquared$ be the function from \eqref{E:FACTORINTOPACOUSTICENERGYNEEDEDFORSHARPCONSTANTS}. 
Then if $\varsigma_1 \in(0,1]$ is sufficiently small, the following estimates hold for
$(\ubar,u) \in [\leftubar,\ubarboot) \times [\moreinterestingu_1,\moreinterestingu_2]$, where the implicit constants are \textbf{independent} of $\varsigma_0$ and $\varsigma_1$:
\begin{align}
		\begin{split} 
			& \int_{\ingoingcharacteristicsurfacetwoarg{\ubar}{[\moreinterestingu_1,u]}} \ReciprocalLunitAppliedtoTimeFunction^2\sumofbrevexvisquared^2 \left( \, \fullymodquant{\tander^N}\right)^2 \weight^{\blowupratetoporderwave} \, \volingoingnullhypersurface + \blowupratetoporderwave 
			\int_{\characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]}} \ReciprocalLunitAppliedtoTimeFunction^2 \sumofbrevexvisquared^2 \left( \, \fullymodquant{\tander^N}\right)^2 \weight^{\blowupratetoporderwave - 1} \voldiamond \\
			 & \ \ \le \boxed{2.81} \weakspacetimetransvelocitycontrol_N(\ubar,u) + \boxed{2.33} \totalbulkcontrolprecisefullymodifiedchi(\ubar,u) \\

			 & \ \ + \Errortoparg{N}(\ubar,u).
		\end{split}
	\end{align}

[Corollary 28 of arXiv:2608.12291, 'When should one stop the most exciting game?\\ {\tiny Sequential Inference for win-marting'] The second spatial derivative of the value function admits the representation
    \begin{equation*}
        \partial_{xx} V_T(t,x)=\begin{cases}
            -2\frac{c(t)+\partial_tV_T(t,x)}{\sigma^2(x)} & \text{for }(t,x)\in\mathcal{C}_T\\
            g''(x)&\text{for }(t,x)\in(\mathcal{D}_T)^\circ.
        \end{cases}
    \end{equation*}

[Lemma 7 of arXiv:2512.04297, 'Mixing at the Batchelor Scale for White-In-Time Flows'] Let $f_0 \in L^2_0(\tor^2) \setminus \{0\}$. For every $(k,l)\in \Z^2 \setminus \{0\}$ we have 
    \begin{equation}
        \P\big(\widehat{f}_{k,l}(t) = 0, \forall\, t\geq 0\big) = 0.
    \end{equation}

