[Lemma lem:weightedmean of arXiv:2604.22510, 'Asymptotics of Multi-Scale McKean--Vlasov Diffusions with Super-Linear Kernels: a Lifted S'] Assume that there exist positive constants ${\rm{Lip}}(\ell)$, ${\rm{Lip}}(h)$, $ c_u, c_l$ such that for all $x, \hat{x} \in {\mathbb R}^n, y, \hat{y}\in{\mathbb R}^m,$
	\begin{align*}
		|h(y)-h(\hat{y})|\leq\,\,& {\rm{Lip}}(h)\big(|y|+|\hat{y}|\big)|y-\hat{y}|\,,\\[1mm]
		c_l\leq\, h(y)-\underline{h}\leq\,\,& c_u\,,\\[1mm]
		|\ell(x, y)-\ell(\hat{x}, \hat{y})|\leq\,\,& {\rm{Lip}}(\ell)\big(|x|+|y|+|\hat{x}|+|\hat{y}|\big)\big(|x-\hat{x}|+|y-\hat{y}|\big)\,,\\[1mm]
		\ell(x, y)-\underline{\ell}\leq\,\,& c_u\big(1+|x|^2+|y|^2\big)\,,
	\end{align*}
	where $\underline{h}\mathrel{\mathop:}= \inf_{x\in{\mathbb R}^m} h(y)>-\infty$ and  $\underline{\ell}\mathrel{\mathop:}= \inf_{x\in {\mathbb R}^n, y\in{\mathbb R}^m} \ell(x, y)>-\infty$. Then, for any $\nu,  \hat{\nu}\in\mathscr{P}_4({\mathbb R}^m)$, $\mu,  \hat{\mu}\in\mathscr{P}_4({\mathbb R}^n)$, it holds that	
	\begin{align}
		&|{\rm{M}}_{\beta}^h(\nu)|^2\leq  \,\, {\rm{e}}^{-2\beta(c_l-c_u)}M_2(\nu)\,,\\
		&|{\rm{M}}_{\beta}^h(\nu)-{\rm{M}}_{\beta}^h(\hat{\nu})|\leq {\rm{e}}^{\alpha c_u} (1+\alpha {\rm{Lip}}(h)(1+ {\rm{e}}^{\alpha c_u})p_k)\,\, \mathbb{W}_2(\nu,\hat{\nu})\,,\\
		&|{\rm{M}}_{\alpha}^{\ell}(\mu, \nu)-{\rm{M}}_{\alpha}^{\ell}(\hat{\mu}, \hat{\nu})|\nonumber\\
&\lesssim_{\alpha, {\rm{Lip}}(\ell)}\,\, \big(M_4(\mu)+M_4(\hat{\mu})+M_4(\nu)+M_4(\hat{\nu})\big)\big(\mathbb{W}_2(\mu,\hat{\mu})+\mathbb{W}_2(\nu,\hat{\nu})\big)\,.
	\end{align}
	If in addition, there is $M>0$ such that
	for any $y_0\in{\mathbb R}^m$,
	\begin{align}
		\ell(x, y_0)-\underline{\ell}\geq\,\,& c_l|x|^2\,,\,\,\,\,\,\,\text{for all} \,\,\,|x|> M+|y_0|,
	\end{align}
	then it holds that
	\begin{align}
		|{\rm{M}}^{\ell}_{\alpha}(\mu, \nu)|^2\lesssim_{\alpha, M, c_u, c_l}\,\,& (1+M_2(\mu)+ M_2(\nu))\,.
	\end{align}

