[Proposition 28 (Asymptotic inversion, \protect{\autocite[Theorem 1.5.12) of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] {BinghamGoldieTeugels1987RegularVariation}}]

Let \(f\) be a regularly varying function with index \(\beta >0\), then
there is a \(\frac{1}{\beta}\)-varying function \(g\) such that

\begin{equation*}{
 f(g(x)) \sim g(f(x)) \sim x \ \text{ as } x \to +\infty.
}\end{equation*}
Moreover, \(g\) is unique up to asymptotic equivalence. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition jets of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp We say that {\small$\mathsf{F}:\R^{\Z}\to\R$} is a \emph{local function} if there exists a subset $\mathbb{I}\subseteq\Z$ independent of $N$ such that for any {\small${\boldsymbol{\phi}}\in\R^{\Z}$}, the value {\small$\mathsf{F}[{\boldsymbol{\phi}}]$} depends only on {\small${\boldsymbol{\phi}}_{\x}$} for $\x\in\mathbb{I}$; we often refer to {\small$\mathbb{I}$} as the \emph{support} of {\small$\mathsf{F}$}. 

Fix any {\small$\mathfrak{k}=0,1,2$}. We let {\small$\mathrm{Jet}_{\mathfrak{k}}^{\perp}$} tbe the set of local functions whose {\small$\mathfrak{k}$}-jet is zero, i.e. {\small$\mathsf{F}\in\mathrm{Jet}_{\mathfrak{k}}^{\perp}$} if and only if

\begin{align*}
\partial_{\sigma}^{\ell}\E^{\sigma}\mathsf{F}[\bphi]|_{\sigma=0}=0 \quad\text{for all } \ell=0,\ldots,\mathfrak{k}.
\end{align*}

[Lemma lem:expected-variance-degree-differences of arXiv:2608.06159, 'Majority Dynamics on Resampled Sparse Erd\H{o}s--R\'enyi Graphs:\\[0.5ex] Gaussian Winner '] Under Assumption~(ass:sparse-er of the paper), whenever both camps are nonempty, the expected degree differences on day $t$ are
    \begin{align}
        m_{t}^{\gR} = p(\Delta_t+1), \qquad m_{t}^{\gB} = p(1-\Delta_t). 
    \end{align}
Furthermore, the variances of the degree differences on day $t$ satisfy
\begin{align}
    v_{t}^{\gR}=v_{t}^{\gB}=(N-1)p(1-p)\asymp \log(N). 
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:MC of arXiv:2605.22787, 'Invariant measures for half-space geometric LPP: classification and the one force--one sol'] Fix $q\in(0,1)$ and $c\in[0,1)$.  Then for each $k\in\mathbb{Z}_{\geq0}$ and $n\in\mathbb{N}$,
\begin{equation}
        \begin{split}
            \mathsf{p}_0(\lambda)& =  c^{\lambda_1-\lambda_2} h_{0,n}^k (\lambda_1-\lambda_2) {\bf 1}_{\{\lambda_2=0\}},\\
            \mathsf{p}_{x,x+1}(\mu,\lambda)&=(1-q)^{2 }s_{\lambda/\mu}(q )\frac{h_{x+1,n}^k (\lambda_1-\lambda_2)}{h_{x,n}^k (\mu_1-\mu_2)} \quad\mbox{ for }x \in \llbracket 0,n-1 \rrbracket,
        \end{split}
    \end{equation} 
are the initial and transitional laws of a Markov chain $\{\lambda^j\}_{j=0}^n$ on state space $\mathsf{Sign}_2$, which has joint law
\[  \mathbb{P}  (\lambda^{0},\dots,\lambda^{n}) \propto c^{\lambda^{0}_1-\lambda^{0}_2}s_{\lambda^{1}/\lambda^{0}}(q)\dots s_{\lambda^{n}/\lambda^{n-1}}(q) {\bf 1}_{\{\lambda_2^0=0\}} {\bf 1}_{\{\lambda^{n}_1-\lambda^n_2=k\}}.\]

