body:
[Theorem thm:main_bd_integral of arXiv:2411.09482, 'Anomalous Regularization in Kazantsev-Kraichnan Model'] Let $d\ge 2$, $s\in (0,d/2)$ and $\alpha\in (0,1)$ with $s+\alpha>1$. There exist $\eta_{d,s,\alpha}\in \mathbb{R}$, $\rho_{d,s,\alpha}\ge 0$ such that the matrix-valued integral $\mathbb H_{d,s,\alpha} (n)$ defined in (equation eq:H_def of the paper) satisfies for every $n\in\mathbb{R}^d\smallsetminus\{0\}$, for all $v\in \mathbb{S}^{d-1}$ with $v\cdot n=0$,
    \begin{equation}
        |v \cdot \mathbb H_{d,s,\alpha} (n) v +\eta_{d,s,\alpha}|n|^{-2s+2-2\alpha}| \leqslant \rho_{d,s,\alpha}|n|^{-2s}.
    \end{equation}
    The constant $\eta_{d,s,\alpha}$ takes the form, for some $C_{d,s,\alpha}>0$,



    \begin{multline*}
        \eta_{d,s,\alpha} = C_{d,s,\alpha} \Big(  (d-1)(s+\alpha-1)(d+2-2s-2\alpha) -\alpha(d-1)(d+2\alpha) +4\alpha (s+\alpha-1) \Big)
    \end{multline*}
    hence $\eta_{d,s,\alpha}$ is strictly positive if and only if (hp:main_hp of the paper) on $d$, $s$ and $\alpha$ is met. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:main of arXiv:2607.19844, 'Binomial probabilities at a fixed distance from the mode:\\ size-biasing and the complete '] Fix $R\in\mathbb N$.  As $N\to\infty$, uniformly for $p$ in a compact subset of $(0,1)$ and for
	integers $r$ with $|r|\le R$, with $\nu=\lceil Np\rceil$ and $h=h_N=\nu-Np$,
	\begin{equation}
		\Pr\{X=\nu+r\}
		\sim\frac{Np}{Np+h+r}\cdot\frac{1}{\sqrt{2\pi Npq}}\;
		\exp\left(\sum_{k\ge1}\frac{1}{N^{k}}
		\left[\widetilde A_k(h;p)-\frac{\Xi_k(p)}{k}\,S_k(h,r)\right]\right),
	\end{equation}
	and equivalently
	\begin{equation}
		\Pr\{X=\nu+r\}
		\sim\frac{1}{\sqrt{2\pi\,(\nu+r)(N-\nu-r)/N}}\;
		\exp\left(\sum_{k\ge1}\frac{1}{N^{k}}
		\left[\widehat A_k(h;p)-\frac{\Xi_k(p)}{k}\,T_k(h,r)\right]\right).
	\end{equation}
	Equivalently, after either exponential is re-expanded multiplicatively and truncated after
	the term $N^{-M}$, the relative remainder is $O(N^{-M-1})$, uniformly in $|r|\le R$ and in
	$p$ on the chosen compact subset of $(0,1)$.

[Lemma keyprop0 of arXiv:2605.27949, 'Yaglom limits of continuous-state branching processes in Brownian random environment \than'] For any $p>\frac\eta2,$  we have
\begin{eqnarray}
\int_0^\infty\int_0^\infty (\gamma y)^{-p}G(y,v)\,\mathrm{d} v\,\mathrm{d} y =2^{p - 2} \gamma^{- p}  \frac{\left[ \Gamma \left( \frac\eta2 \right)\Gamma\left( p-\frac\eta2  \right)  \right]^2}{\Gamma\left( p \right)},
\end{eqnarray}
and
{\small\begin{eqnarray}
\int_0^\infty\int_0^\infty (\gamma y+2yv{\lambda}^{-\beta} )^{-p}G(y,v)\,\mathrm{d} v\,\mathrm{d} y
= 2^{p - 2} \gamma^{- p} \frac{ \left[\Gamma \left( \frac\eta2 \right)\Gamma \left( p - \frac\eta2 \right)\right]^2}{\Gamma \left( p \right)} \left( \frac{\gamma  \lambda^\beta}{2} \right)^{\frac\eta2} U \left( \frac\eta2, 1, \frac{\gamma  \lambda^\beta}{2} \right).
\end{eqnarray}} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition gcmeasure of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] Fix any $\sigma\in\R$. Consider the product probability measure below on {\small$\R^{\Z}$}:

\begin{align}
\mathbb{P}^{\sigma}[\d{\boldsymbol{\phi}}]:=\prod_{\x\in\Z}\mathcal{Z}_{\upsilon_{\sigma},\mathscr{U}}^{-1}\exp\left[-\mathscr{U}[{\boldsymbol{\phi}}_{\x}]+\upsilon_{\sigma}{\boldsymbol{\phi}}_{\x}\right]\d{\boldsymbol{\phi}}_{\x}.
\end{align}

Here, {\small$\mathcal{Z}_{\upsilon_{\sigma},\mathscr{U}}$} is a normalizing partition function, and {\small$\upsilon_{\sigma}\in\R$} is chosen so that {\small$\E^{\sigma}{\boldsymbol{\phi}}_{\x}=\sigma$} for all $\x\in\Z$, where {\small$\E^{\sigma}$} is expectation with respect to {\small$\mathbb{P}^{\sigma}$}. (Well-defined-ness of {\small$\mathbb{P}^{\sigma}$} will follow from Assumption (assump:potential of the paper).)

[Lem 7 of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] For all $p \in (0, 1/2]$,
\begin{align*}
    (1 - p)\sqrt{\frac{2\beta_p}{1 - 2p}} \le 1 + \log\frac{1}{2p},
\end{align*}
with equality if and only if $p = 1/2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

