body:
[Theo 11 of arXiv:2608.30357, 'Mean convergence for Banach space-valued random elements indexed in measure spaces'] Let $\{K_n : n \ge 1\} \subseteq \cK(\cX)$ and let $p \in [1, \infty)$. Assume that $\{X^n_s : s \in S_n, n \ge 1\}$ is $(\nu_n)$-$\CUI(p)$ w.r.t. $\{K_n\}$. Assume for any $n \ge 1$, there exists $D_n \in \cS_n \otimes \cS_n$ such that:
	\begin{enumerate}[\rm (a)]
		\item  $\lim_{n \to \infty} N(K_n, \ep)^{1 - (\frac{1}{p} \wedge \frac{1}{2})} \lt\|K_n\rt\| ((\nu_n \otimes \nu_n) (D_n))^{\frac{1}{p} \wedge \frac{1}{2}} = 0$ for all $\ep >0$,

		\item  $X^n_s$ and $X^n_t$ are diagonally negatively dependent for $(\nu_n \otimes \nu_n)$-a.e.\ $(s, t) \in (S_n \times S_n) \backslash D_n$.
	\end{enumerate}
	Then, we have 
	\begin{align}
		\lim_{n \to \infty} \bE \lt\| \int_{S_n} \lt(X^n_s - \bE X^n_s\rt) \nu_n(\od s) \rt\|^p = 0,
	\end{align}
	and in particular, $\int_{S_n} \lt(X^n_s - \bE X^n_s\rt) \nu_n(\od s)  \to 0$ in probability as $n \to \infty$.

