body:
[Corollary 2 of arXiv:2605.28801, 'Microscopic Weak Selection Principle for the Logistic Branching Brownian Motion with selec'] For any $T>0$, the cumulative distribution function associated with the empirical measures defined in \eqref{eq: defemp0} converges in probability to a deterministic limit $F(t,\cdot)$, which is a weak solution of the FKPP equation, i.e. for a  given initial CDF $F_0$,
	\begin{equation}
		\left\{
		\begin{aligned}
			\partial_t F (t,x)  &=  \frac{1}{2}\partial_{xx} F (t,x)  - F(t,x)  (1-  F(t,x)), \qquad t\leq T, x\in\mathbb{R}\\
			F(0,x) & =  F_0(x), \qquad x\in\mathbb{R}         
		\end{aligned}
		\right..
	\end{equation}
	Furthermore, if $F_0(x) = \mathbb{1}_{\{x>0\}}$ and $U$ is a classical solution to the FKPP equation in the interval $[0,T]$, then $F$ coincides with $U$ in that time interval, i.e. $U(t,\cdot) = F(t,\cdot)$ for $ t\in[0,T]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 2 (Canonical representation of a distribution as a filtered process) of arXiv:2604.22159, 'Adapted optimal transport between filtered Gaussian processes'] For $\mu \in \cP_2(\bR^{Nd})$, we define 
\begin{equation} 
\bX^{\mu} := (\bR^{Nd}, \cB(\bR^{Nd}), \mu, (\cF_t)_{t = 1}^N, (X_t)_{t = 1}^N),
\end{equation}
where $X_t(\omega) = \omega_t$ is the canonical process on $(\bR^{Nd}, \cB(\bR^{Nd}))$ and has law $\cL(X) = \mu$, and $\cF_t = \sigma(X_s: s \leq t)$ is the natural filtration induced by $X$. We call $\bX^{\mu} \in \cFP_2$ the canonical representation of $\mu$ as a filtered process.

[Corollary 18 of arXiv:2604.05910, '\textbf{Well-posedness and Hurst parameter estimation for fluid equations driven by fracti'] {\em(Young integral for transport-type noise)}
        Let $Y\in C([0,T];\cB_{\alpha-1/2})\cap C^\gamma([0,T];\cB_{\alpha-\gamma-1/2})$.\\Then 
     there exists a map $\mathcal{I}: C([0,T];\cB_{\alpha-1/2})\cap C^\gamma([0,T];\cB_{\alpha-\gamma-1/2})  \to C([0,T];\cB_\alpha)\cap C^\gamma([0,T];\cB_{\alpha-\gamma}) $ such that $\mathcal{I}_0=0$, 
   \begin{align*}
\mathcal{I}_t =\int_0^t S_{t -s}Y_s dW^H_s       =\lim\limits_{\pi\in\cP([0,t]),|\pi|\to 0} \sum\limits_{[u,v]\in\pi} S_{t-u} Y_u W^H_{u,v}, 
   \end{align*}
which satisfies the following estimates for all $0\leq s \leq t \leq T$:
\begin{align}
    \Big\| \int_s^t S_{t-r}Y_r~d W^H_r -S_{t-s}Y_s W^H_{s,t} \Big\|_{\alpha-\gamma}\lesssim [W^H]_\gamma \max\{ \|Y\|_{0,\alpha-1/2}, \|Y\|_{\gamma,\alpha-1/2-\gamma}\} (t-s)^{2\gamma-1/2}
    \end{align}
    and
    \begin{align}
    \Big\| \int_s^t S_{t-r}Y_r~d W^H_r -S_{t-s}Y_s W^H_{s,t} \Big\|_{\alpha}\lesssim [W^H]_\gamma \max\{ \|Y\|_{0,\alpha-1/2}, \|Y\|_{\gamma,\alpha-1/2-\gamma}\} (t-s)^{\gamma-1/2}.
\end{align}

[Proposition prop_slow of arXiv:2604.14851, 'Pool model: a mass preserving multi particle aggregation process'] For an arbitrary C\'adl\'ag function ${\mathcal{E}}_t$ such that 
	 \begin{equation} 

	\liminf_{t\to\infty} \frac{{\mathcal{E}}_t}{t^{\frac{1}{3}}}=\infty
	, \end{equation} 
	and that 
	 \begin{equation} 

	\limsup_{t\to\infty} \frac{{\mathcal{E}}_t}{t^{1-\alpha}}\le 1
	 \end{equation} 
	for some $\alpha\in (0,1)$, there is some $\beta>0$ such that for all $T_0\ge 0$ there is a $t_1>T_0$ such that 
	 \begin{equation} 

	{\mathcal{E}}_{t_1-t_1^\beta}\ge {\mathcal{E}}_{t_1}-2.
	 \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma-H-1 of arXiv:2411.04500, '\LARGE Probabilistic Approaches to The Energy Equality in Forced Surface Quasi-Geostrophic'] For any $ f\in L^2{(\mathbb{T}^2)},$ there exists a constant $ C>0 $ such that
	\begin{equation*} 
		\left\|f R_i f\right\|_{\mathcal{H}^1(\mathbb{T}^2)} \leqslant C\|f\|_{L^2(\mathbb{T}^2)}^2, \quad i=1,2,
	\end{equation*}
	where $ R_i f $ is the i-th Riesz transform of $ f. $ (Proof in the paper; no proof environment follows the statement in the TeX.)

