[Lemma lem:two-edges_delta=1/gamma-1 of arXiv:2509.23496, 'Crossing probabilities in geometric inhomogeneous random graphs'] Suppose $2<\delta=\frac 1 \gamma-1$. The two-edges crossing probabilities are given~by 
    \begin{align*}
        \pi_{(u),R}^{(2)} 
        &\asymp \pi_{(u),R}+ \big(u^{-\gamma} R^{d(1-\delta)}\log R \big)\wedge 1\\
        &\asymp \begin{cases}
                    u^{-\gamma} R^{d(1-\delta)}\log R & \text{ on } \{u \geq (\log R)^{-\frac 1 {1- 2\gamma}}\},\\
                    u^{-\gamma \delta} R^{d(1-\delta)} & \text{ on } \{R^{d(\frac 1 {\gamma \delta}-\frac 1 \gamma)} \leq u \leq (\log R)^{-\frac 1 {1- 2\gamma}}\},\\
                    1 & \text{ on } \{u\leq R^{d(\frac 1 {\gamma \delta}-\frac 1 \gamma)} \}.
                \end{cases}
    \end{align*}
    \begin{align*}
        \pi_{r,R}^{(2)} 
        &\asymp \pi_{r,R}+ r^{\frac d \delta} R^{d(1-\delta)} \log R 
        \asymp \begin{cases}
                    r^{\frac d \delta} R^{d(1-\delta)}\log R & \text{ on } 
                    \{ r^d \leq  (\log R)^{\frac \delta {\delta-1}}\} ,\\
                    r^d R^{d(1-\delta)} & \text{ on } \{(\log R)^{\frac \delta {\delta-1}} \leq r^d, R\geq 2r  \}.
                \end{cases}
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2606.29131, '2606.29131'] Suppose that Assumption {\rm\ref{a1-1}(iii)} and Assumption {\rm\ref{a1-2}} hold, and that there exists $\beta>0$ such that
\begin{equation}
\lim_{\e \to 0}\xi_{4,\beta}(\e)=0.
\end{equation} Fix this $\beta$, and let $v_n:\R^d\to \R$  be defined as \eqref{e2-14a} with $h\in \M_{\beta}$.
For any $n\ge1$, there is a constant $C(n)>0$ such that for all $\e\in (0,1)$
\begin{equation}
\|v_{n}^\e\|_{L^2(\R^d;dx)}\le
C(n)\left(\xi_{2,\beta}(\e)+\xi_{4,\beta}(\e)\right)^n,
\end{equation}
where $\xi_{2,\beta}(\e)$ and $\xi_{4,\beta}(\e)$ are defined by \eqref{e1-8a} and \eqref{e2-3-12} respectively. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:finite of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] Suppose that $\mathbf{q} \in \mathcal{Q}$ satisfies $q_{\ell} > 0$, $q_{h} = 0$, $h \ge \ell + 1$ with some $\ell \ge 2$ and $|\mathbf{q}| \ge 2$. We denote by $k = k(\mathbf{q})$ the second largest element in $\mathbf{q}$, i.e., 
                \begin{align}
                    k := \max\left\{1 \le h \le \ell -1 ; q_{h} > 0 \right\}.
                \end{align}
            Then, for any $i \in {\mathbb{Z}}$, (equation def:step_M of the paper) converges weakly to the Brownian motion with variance $G_{k}\left(\mathbf{q}\right)$ under $\nu_{\mathbf{q}}$, where $G_{k}\left(\mathbf{q}\right)$ is given by 
                \begin{align}
                    G_{k}\left(\mathbf{q}\right) &= \frac{4q_{\ell}}{\left(1 - q_{\ell}\right)^{2(\ell-k)}} \left(1 + \frac{4 q_\ell}{\left(1 - q_{\ell}\right)^{2(\ell-k)}}\right)^{-\frac{3}{2}}.
                \end{align}
            In addition, for any $i \in {\mathbb{Z}}$, the limit $\Lambda^{M{,i}}_{\mathbf{q},k}\left(\lambda\right)$ exists {and does not depend on $i$}. In addition,  $\Lambda^{M}_{\mathbf{q},k}\left(\lambda\right) {:= \Lambda^{M{,0}}_{\mathbf{q},k}\left(\lambda\right)}$ is a smooth monotone convex function, which is explicitly given by 
                \begin{align}
                    \Lambda^{M}_{\mathbf{q},k}\left(\lambda\right) &= \log\left(\frac{\left(1 - q_{\ell}\right)^{\ell-k}e^{\lambda} }{2} + \sqrt{\frac{\left(1 - q_{\ell}\right)^{2( \ell - k)}e^{2\lambda}}{4} + q_{\ell}}\right).
                \end{align}
            In particular, the assumptions of Theorem (thm:main of the paper) ((item:1 of the paper)) and ((item:2 of the paper)) are satisfied with the above $\mathbf{q}$ and $k, \ell$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm quantitative_discrete_continuous_convergence of arXiv:2411.13964, 'Long-time analysis of a pair of on-lattice and continuous run-and-tumble particles with ja'] \begin{itemize}
  \item[(i)] There exists a coupling of the continuous process $X$ and
    a sequence of discrete processes $(Y^L)_{L \ge 2}$ with parameters
    scaling as in ($*$) such that for all $T > 0$
    \begin{align*}
      \mathbb{P}\left( \sup_{t \le T} \left| i_L(y^L(t)) - x(t) \right| \ge \epsilon \right) \le \frac{1}{\epsilon} \left( \frac{\ell}{L - 1} + 8 \sqrt{\frac{T \left((\eta T)^2 + 3 \eta T + 1 \right)\ell}{L - 1}} \right)
		\end{align*}
		where $\eta = 2\omega$ (resp. $\eta = 2\max(\alpha,
                \beta)$) for the instantaneous-tumble transition rates of the
                $\sigma^i$ (resp. the finite-tumble transition rates).
              \item[(ii)] One has
		\begin{align*}
                  \Big( (i_L(y^L(t)), (\sigma^1(t), \sigma^2(t))) \Big)_{t\ge 0} \overset{\text{\normalfont Law}}{\longrightarrow} \Big(X(t)\Big)_{t \ge 0}
		\end{align*}
                in the Skorokhod space $\mathcal D[0, +\infty)$.
              \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 (Fisher-information continuity) of arXiv:2608.30579, '2608.30579'] The set $\overline{\mathcal I_{a,l}}$ is compact in $L^1_{1+x^2}$, and hence also compact in $L^1$.
Moreover, the Fisher-information functional
\begin{equation}
    p\mapsto J(p)
\end{equation}
is continuous on $\overline{\mathcal I_{a,l}}$ with respect to the $L^1$ topology.
Equivalently, if $p_n,p\in \overline{\mathcal I_{a,l}}$ and
\begin{equation}
    \Vert p_n-p\Vert_{L^1}\rightarrow 0, \, n \rightarrow \infty. 
\end{equation}
then
\begin{equation}
    J(p_n)\to J(p).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma representation of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] We have the following pathwise identity on a set of full measure:
		\begin{align}
			\int _{s}^{t}B^{\epsilon}_{s-r,u-r}\otimes \mathrm{d} B_{u}^{\epsilon}=\int_{0}^1\rho(z)\int _{s-\epsilon z}^{t-\epsilon z}B^{\epsilon}_{s-r,u+\epsilon z-r}\otimes \mathrm{d}B_{u} \mathrm{d}z=\int _{0}^1\rho(z)\int _{s-\epsilon z}^{t-\epsilon z}B^{\epsilon}_{s-r,u+\epsilon z-r}\otimes \mathrm{d}^{\circ}B_{u} \mathrm{d}z.
		\end{align}
		\begin{proof}
			Note that the integrals in (equation eqn:pathwise of the paper) are defined pathwise, since \(B^{\epsilon}\) is smooth and \(B\) is a Hölder continuous path (almost surely for \(\gamma < H\)). Using integration by parts, we obtain:
			\begin{align*}
				\int _{s-\epsilon z}^{t-\epsilon z}(B^{\epsilon})^{i}_{s-r,u+\epsilon z-r}\mathrm{d}B^{j}_{u}=(B^{\epsilon})^{i}_{s-r,t-r}B^{j}_{t-\epsilon z}-\int_{s-r}^{t-r}B^{j}_{u+r-\epsilon z}\mathrm{d}(B^{\epsilon})^{i}_{u}.
			\end{align*}
			Consequently,
			\begin{align*}
				\int _{\mathbb{R}}\rho(z)&\int _{s-\epsilon z}^{t-\epsilon z}(B^{\epsilon})^{i}_{s-r,u+\epsilon z-r}\mathrm{d} B^{j}_{u} \mathrm{d}z\\&=\int_{\mathbb{R}}\rho(z)(B^{\epsilon})^{i}_{s-r,t-r}B^{j}_{t-\epsilon z}\mathrm{d}z-\int_{\mathbb{R}}\int_{s-r}^{t-r}\rho(z)B^{j}_{u+r-\epsilon z}\mathrm{d}(B^{\epsilon})^{i}_{u} \mathrm{d}z\\
				&=(B^{\epsilon})^{i}_{s-r,t-r}(B^{\epsilon})^{j}_{t}-\int_{s-r}^{t-r}(B^{\epsilon})^{j}_{u+r}\mathrm{d}(B^{\epsilon})^{i}_{u}.
			\end{align*}
			From integration by parts,
			\begin{align*}
				(B^{\epsilon})^{i}_{s-r,t-r}(B^{\epsilon})^{j}_{t}-\int_{s-r}^{t-r}(B^{\epsilon})^{j}_{u+r}\mathrm{d}(B^{\epsilon})^{i}_{u}
				=\int _{s}^{t}(B^{\epsilon})^{i}_{s-r,u-r}\mathrm{d} (B^{\epsilon})_{u}^{j},
			\end{align*}
			which implies the claim.
		\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 2.3 of arXiv:2604.22510, 'Asymptotics of Multi-Scale McKean--Vlasov Diffusions with Super-Linear Kernels: a Lifted S'] (Laplace principle)
	The sequence  $\{X^\varepsilon\}_{\varepsilon\in(0,1)}$ is said to be satisfied the Laplace
	principle upper bound (respectively, lower bound) on $\mathcal{E}$ with a rate function $I$ if for each bounded continuous real-valued function $\Lambda$ : $\mathcal{E} \to \mathbb{R}$
	\begin{equation*}
		\limsup_{\varepsilon\to0}-\varepsilon\log\mathbb{E}\Big\{\exp[-\frac{1}{\varepsilon}\Lambda(X^\varepsilon)]\Big\}\leq\inf_{x\in\mathcal{E}}\big(\Lambda(x)+I(x)\big),
	\end{equation*}
	(respectively,
	\begin{align*}
		\liminf_{\varepsilon\to0}-\varepsilon\log\mathbb{E}\Big\{\exp[-\frac{1}{\varepsilon}\Lambda(X^\varepsilon)]\Big\}\geq\inf_{x\in\mathcal{E}}\big(\Lambda(x)+I(x)\big)).
	\end{align*}

[Lemma lem:lclt of arXiv:2601.10624, 'Source localisation in simple random walks'] Let $d \geqslant 1$ and let $(X_n)_{n \geqslant 0}$ be a simple random walk on $\mathbb{Z}^d$. Then, we have
    \begin{equation*}
        \mathbb{P}(X_{2n} = 0) \leqslant \left(\frac{2d}{\pi n}\right)^{\frac{d}{2}}, \text{ for all } n \in \mathbb{N}.
    \end{equation*}

