        \item[2.] $z_{k+2}=z_{k+4}$.
    \end{itemize}

[Lemma 12 of arXiv:2607.09246, 'Scaling limit of 1+1 dimensional directed polymer with power-law tail and spatial correlat'] Assume that conditions \textbf{(A)} and \textbf{(B)} hold.
Assume moreover that \(\alpha>2\). Choose and fix
$q\in(2,\min\{\alpha,3\})$ such that \(\mathbb E_{\mathbb Q}[|\xi|^q]<\infty\).
We also use the parameter choices for \(\beta_N\) in \eqref{beta_N}
and \(k_N\) in \eqref{k_N}. Then, for every fixed \(m\ge1\),
the truncated chaos expansions \(\mathfrak Z_N^{\le m}(\beta_N;\overline\omega)\)
and \(\mathfrak Z_N^{\le m}(\beta_N;\mu)\) possess the same limiting
distribution as \(N\to\infty\). That is, for any test function
\(f\in C_b^{(3)}(\mathbb R)\),
\begin{equation}
\lim_{N\to\infty}
\left|
\mathbb E_{\mathbb Q}
\left[f\left(\mathfrak Z_N^{\le m}(\beta_N;\overline\omega)\right)\right]
-
\mathbb E_{\mathbb Q}
\left[f\left(\mathfrak Z_N^{\le m}(\beta_N;\mu)\right)\right]
\right|=0 .

\end{equation}

[Proposition 8 of arXiv:2605.28801, 'Microscopic Weak Selection Principle for the Logistic Branching Brownian Motion with selec'] The process $(\boldsymbol{Z}^c(t))_{t\geq 0}$ has an unique stationary distribution $\boldsymbol{\nu}^c$ on $\mathbb{E}$, such that 
	\[\boldsymbol{\nu}^c(dx_1,\cdots,dx_n,n) = \boldsymbol{\nu}^{c,n}(dx_1,\cdots,dx_n)\pi(n),\]
	such that $\int_{\mathbb{R}^n}  \boldsymbol{\nu}^{c,n}(dx_1,\cdots,dx_n)=1$ for each $n\in \mathbb{N}$. In addition, for any initial distribution $\boldsymbol{\psi}_{\pi}$,
	\begin{equation}
		\lim_{t \rightarrow\infty} \| P_{\boldsymbol{\psi}_{\pi}} \left(\boldsymbol{Z}^c(t) \in \cdot\right) - \boldsymbol{\nu}^c(\cdot)\|_{TV} =0.
	\end{equation}

[Lemma 6 of arXiv:2606.11142, 'Strong invariance principles for diffusions, Markov chains and their perturbations.'] The following estimate holds for the densities on the grid:
\begin{equation*}
\int_{\mathbb{R}^{m \times d}} |P^m_x(z) - P^m_{\epsilon,x}(z)| dz \le C m \Delta_{\epsilon,\gamma,q},
\end{equation*}
where $z = (z_1, \dots, z_m)$ and $dz = dz_1 \dots dz_m$.

