[Lemma only_one_vertex_connection_set_lower_bound_technical_calculation of arXiv:2606.09386, 'High-degree vertices in uniform recursive directed acyclic graphs with freezing'] Let $\mathbf x$ be a choice sequence that satisfies Assumption~$\hyperref[ass:A]{\mathbf{x}}$(item:geq1 of the paper)  and let $d=d(n),k=k(n)\in\mathbb{N}$.  Then,
\begin{equation}
\mathbb{P}(u_n(v)-\widetilde{u}_n(v)> k,\deg_n(v)\geq d)\leq\theta^{-d} \mathbb{P}(u_n(v)-\widetilde{u}_n(v)> k).
\end{equation}

[Definition 36 of arXiv:2606.13459, 'Symmetric Cooperative Motion in Higher Dimensions'] Let $u_{0}$ be a Radon measure on $\R^{d}$. We say that $u$ is a distributional solution of \eqref{e.pme} (the initial value problem) if $u$ is a distributional solution in the above sense, and if for all $\vp \in C_{c}(\R^{d})$, 
	\begin{equation*}
		\lim_{t \to 0^{+}} \int_{\R^{d}}u(x,t)\vp(x) \,dx = \int_{\R^{d}} \vp(x) u_{0}(dx).
	\end{equation*}
	In such a case we call $u_{0}$ the \emph{initial trace} of $u$. For $u_{0} \in L^{1}_{\loc}(\R^{d})$, we use the embedding of $u_{0}$ as a Radon measure, namely $u_{0}(dx) = u_{0}\,dx$, in the above definition.

[Proposition prop:moment-identities of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] Let $A=(a_i)$ and $B=(b_i)$ be the spoke and rim labels of a geodesic Leech labeling. Then
\begin{equation}
  (m-2)\sum_i a_i+3\sum_i b_i=\frac{N(N+1)}2,
\end{equation}
\begin{equation}
  \sum_{t\in T(A)}t=3\sum_i b_i,
\end{equation}
and
\begin{equation}
\begin{aligned}
  \frac{N(N+1)(2N+1)}6
  ={}&\left(\sum_i a_i\right)^2
  +(m-3)\sum_i a_i^2
  -2\sum_i a_i a_{i+1}\\
  &+3\sum_i b_i^2
  +2\sum_i b_i b_{i+1}
\end{aligned}
\end{equation}
hold. In particular,
\[
  \sum_{t\in T(A)}t\equiv0\pmod3.
\]

