[Definition Dynamic Programming Principle in the case of infinite horizon of arXiv:2608.08299, 'Non-linear optimal stopping with Bermudan strategies: the infinite horizon case'] We say that an admissible non-negative family $\phi$ satisfies the Dynamic Programming Principle (abridged DPP) in the case of infinite horizon, if the following property holds true: \\
For all $k \in \mathbb{N}$, 
\begin{equation}
    \phi(\theta_k)=\max\left(\xi(\theta_k), \rho_{\theta_k,\theta_{k+1}}[\phi(\theta_{k+1})]\right).
\end{equation}

[Thm meso-main of arXiv:2609.00110, 'Phase Transition and Fluctuation Results for First-Passage Percolation on Spread-Out Cycle'] Assume that the edge weights satisfy Assumption~(ass:weight of the paper). Fix $\mathsf{u}\in(0,1/2)$ and let $T_n^{(\ell)}(0,\mathsf{u}_n)$ be the first-passage time defined in~(equation eq:fixed-target-Tn of the paper). The following holds.
\begin{enumeratea}
 \item  When $1\ll \ell\log\ell \ll n$, we have
 \begin{align} 
 \frac{\mathfrak{a}_\ell\ell}{\mathsf{u}_n} \cdot T_n^{(\ell)}(0,\mathsf{u}_n)
 \stackrel{\pr}{\to}
 \frac1{\mathsf{v}^\star}
 \text{ and }
 \frac{\mathfrak{a}_\ell\ell}{\mathsf{u}_n} \cdot\E T_n^{(\ell)}(0,\mathsf{u}_n)
 \to \frac{1}{\mathsf{v}^\star} \text{ as }n\to\infty,
\end{align}
where $\mathsf{v}^\star\in (0,\infty)$ is the constant defined in~(equation def:vstar of the paper).

 \item  When $1\ll\ell\ll n$, there is a constant $C=C(\theta,\mathsf{u})\in (0,\infty)$ such that, for all large $n$,
\begin{align} 
 C^{-1}\cdot \left( \frac n{\ell^{2+2/\theta}} \vee\frac1{\ell^{2/\theta}} \right)
 \leqslant \var\bigl(T_n^{(\ell)}(0,\mathsf{u}_n)\bigr)
 \leqslant C\cdot \frac{n}{\ell^{1+2/\theta}}\cdot (\log\ell)^{2\gth}.
\end{align}

 \item  When $\ell\ll n^{1/4}(\log n)^{-3\gth/2}$, we have
 \begin{align}
 \frac{T_n^{(\ell)}(0,\mathsf{u}_n)-\E T_n^{(\ell)}(0,\mathsf{u}_n)}{\sqrt{\var\bigl(T_n^{(\ell)}(0,\mathsf{u}_n)\bigr)}}
 \Rightarrow\N(0,1)\text{ as } n\to\infty.
\end{align}
\end{enumeratea} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 of arXiv:2506.20411, 'Maximal Counts in the Stopped Occupancy Problem'] For  $K>1$
and $t_0, t_1$ given by \eqref{trt}
the $K$-variate extreme-value processes
\begin{equation}
((\widehat{M}_{n,n-i+1}(t))_{i=1}^K,~ t\in[t_0,t_1]) ~~~{\rm and~~~}   ((\widehat{M}_{n,i}(t))_{i=1}^K,~ t\in[t_0,t_1])
\end{equation}
are asymptotically independent.

[Lem omega of arXiv:2504.19942, 'The edge-averaging process on graphs \\ with random initial opinions'] Let $G=(V,E)$ be either the $n$-cycle or the infinite path $\mathbb Z$ and let $o\in V$. Suppose that $t_*=\min(t,n^2)\ge 120$ and let $J$ be the set of vertices in $V$ whose distance from $o$ is less than $4\sqrt{t}$. Define the event 
\begin{equation}
    \Omega := \big\{ m_t(J) \ge 1/2,  \  Q_t \le 6t_*^{-1/2} \big\},
\end{equation}
where $m_t(J):=\sum _{v\in J} m_t(v)$. Then $\mathbb P (\Omega ) \ge 4/5$.

