body:
[Theorem thm:main-approx of arXiv:2606.29557, 'Propagation of chaos for Belavkin equations beyond pure states'] Assume that
\begin{equation}
  \delta_N
  :=
  \left\|
    \rho_0^N-\gamma_0^{\otimes N}
  \right\|_1
  \longrightarrow0.

\end{equation}
Then propagation of chaos holds.  More precisely, for every fixed $n\ge1$ and
$T>0$, there exists a constant $C>0$ depending on $n, T,  h,V,L^{(1)},\ldots,L^{(m)},\eta $ 
such that
\begin{equation}
\begin{aligned}
  \sup_{0\le t\le T}
  \mathbb E\left[
    \left\|
      \rho_t^{N:n}
      -
      \Gamma_t^n
    \right\|_1
  \right]
   \le C\delta_N+ 
     \frac{C}{N^{1/4}}{\mathbf 1}_{\{\eta=1\}} + \frac{C}{N^{1/16}}{\mathbf 1}_{\{0<\eta<1\}}.
\end{aligned}

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 10 (Continuity Criterion) of arXiv:2605.19084, 'Limit Profiles for Separation Distance'] Let $P_n$ be reversible Markov chains on finite state spaces $\Omega_n$, with continuous-time kernels $e^{-t(I-P_n)}$, stationary measures $\pi_n$, eigenvalue gaps $\lambda_{n,j}$, and orthonormal eigenbases $\{f_{n,j}\}$ in $\ell^2(\pi_n)$. Fix starting states $x_n$, and assume that $\Phi_x(c):=\lim_{n\to\infty}s_{n,x_n}(t_n+cw_n)$ exists for all $c\in\mathbb R$. If, for every $c\in\mathbb R$,
$$\limsup_{n\to\infty}w_n\max_{y\in\Omega_n}\sum_{j=2}^{|\Omega_n|}|f_{n,j}(x_n)f_{n,j}(y)|\lambda_{n,j}e^{-(t_n+cw_n)\lambda_{n,j}}\leq g_x(c)$$
for a locally bounded function $g_x$, then $\Phi_x$ is continuous. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 (\cite{Pit99}, Corollary 5) of arXiv:2606.10336, 'From Pitman's local times representation to the Gorin-Shkolnikov identity and beyond'] The process $\{\ell_x\}_{x \ge 0}$ solves the SDE:
\begin{equation}

d\ell_x = \left( 4 - \frac{\ell_x^2}{1 - \int_0^x \ell_y dy}\right) dx + 2 \sqrt{\ell_x} dB_x, \quad \ell_0 = 0,
\end{equation}
stopped at $0$.
Here $\{B_x\}_{x \ge 0}$ is standard Brownian motion. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 8 of arXiv:2609.02050, '2609.02050'] The diagram $D=(D_1,\ldots, D_n)$ satisfies one of the conditions illustrated in Theorem~\ref{thm-lower}, if and only if the equality $\det\left(Y^C_D\right)=\det\left(Y^{C'}_D\right)$ holds for each pair $(C,C')$ satisfying
		\begin{equation}
			|C_j|=|C'_j|=|D_j| \text{ for }j\in[n] \text{ and } {\bf x}^C={\bf x}^{C'}.
		\end{equation}

[Proposition 12 of arXiv:2608.15914, 'Absorption cutoff and stationary singularities for rounded Gaussian random dynamical syste'] Let $P_{A,N}$ be the transition kernel of $X^{(N)}$ in
  \cref{eq:unrounded-chain}. Then, for every bounded measurable
  $f:[-1,1]^N\to\R$,
  \begin{equation}
    P_{A,N}f(x)
    =
    \int_{[-1,1]^N} f(z)\,J_{A,N}(r_N(x),\mathrm{d}z).
  \end{equation}
  Consequently, for every deterministic $x\in[-1,1]^N$, with
  $q=r_N(x)$, and every $t\geq1$,
  \begin{equation}
    P_{A,N}^t(x,\cdot)=K_{A,N}^{t-1}(q,\cdot)J_{A,N},
    \qquad
    (r_N)_\#P_{A,N}^t(x,\cdot)=K_{A,N}^{t}(q,\cdot).
  \end{equation}

  If $\nu_{A,N}$ is invariant for $K_{A,N}$, then
  $\pi_{A,N}:=\nu_{A,N}J_{A,N}$, that is,
  \begin{equation}
    \pi_{A,N}
    =
    \int_0^1 J_{A,N}(q,\cdot)\,\nu_{A,N}(\mathrm{d}q)
  \end{equation}
  is an invariant law for $P_{A,N}$. Conversely, if $\pi_{A,N}$ is invariant
  for $P_{A,N}$ and $\nu_{A,N}:=(r_N)_\#\pi_{A,N}$, then $\nu_{A,N}$ is
  invariant for $K_{A,N}$ and $\pi_{A,N}$ is given by
  \cref{eq:gaussian-vector-stationary-from-q}.

  For this pair of invariant laws and $t\geq1$,
  \begin{equation}
    \norm{K_{A,N}^t(q,\cdot)-\nu_{A,N}}_{\TV}
    \leq
    \norm{P_{A,N}^t(x,\cdot)-\pi_{A,N}}_{\TV}
    \leq
    \norm{K_{A,N}^{t-1}(q,\cdot)-\nu_{A,N}}_{\TV}.
  \end{equation}

