[Corollary corollary_repl_lemma_2 of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] For any function $H \in C^{1,2}( {\Omega_T})$ and for every $\delta >0$, it holds that
\begin{equation} 
\lim_{\epsilon \to 0} \lim_{N\to+\infty}  \mathbb{P}_{\nu_N} \left( \sup_{0 \leq t \leq T}\Big | \int_0^t [\langle h_{-}(\eta_s), H_s\rangle - F_-(\pi^N_s \ast \iota_\epsilon(\epsilon_N)) H_s(0)] ds \Big | > \delta \right) =0,
\end{equation}
and
\begin{equation} 
\lim_{\epsilon \to 0} \lim_{N\to+\infty}  \mathbb{P}_{\nu_N} \left( \sup_{0 \leq t \leq T} \Big | \int_0^t [\langle h_{+}(\eta_s), H_s\rangle - F_+(\pi^N_s \ast \iota_\epsilon(\tau_N)) H_s(1)] ds \Big | > \delta \right) =0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 10 of arXiv:2512.05340, 'The rate of convergence of the critical mean-field $O(N)$ magnetization via multivariate n'] Let $V$ satisfy Assumption~\ref{assumption: assumptions on V}, let $P_t$ denote the semigroup corresponding to~\eqref{eq: overdamped langevin},
  and let $h \in \smoothlip$. For any $x, u, v, w \in \RR^{d}$ the following hold:
    \begin{align}
        \left|D P_{t}h(x)[u]\right| &\leq C_{1}\, e^{-\theta t}\, |u|,
        \\

         |D^{2} P_{t}h(x)[u, v]| &\leq S(t)\, e^{-\theta t/2}\, |u||v|,\\

        |D^{3} P_{t}h(x)[u, v, w]| &\leq Q(t)\, e^{-\theta t/4}\, |u||v||w|, 
    \end{align}
    where $S:(0,\infty)\to(0,\infty)$ and $Q:(0,\infty)\to(0,\infty)$ are given by
    \begin{equation}
      S(t):= \frac{s_{-1/2}}{\sqrt{t}} + s_0
    \end{equation}
    and
    \begin{equation}
      Q(t):= \frac{q_{-1}}{t} + \frac{q_{-1/2}}{\sqrt{t}} + q_0 + q_1 t + q_2 t^2
    \end{equation}
    where $\theta,C_1,s_{-1/2},s_0,q_{-1},q_{-1/2},q_0,q_1,q_2\in(0,\infty)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm t:P0 of arXiv:2504.07255, 'A Tail-Respecting Splitting Numerical Scheme\\ for L\'evy-Driven SDEs With Superlinear Dri'] Let assumptions $\mathbf{H}^\mathrm{diss}_A$, $\mathbf{H}_{a,b,c}^{\mathrm{Lip}_b}$,
$\mathbf{H}_{\nu,p},$
$\mathbf{H}_A^{\mathrm{Lip}_+}$,
and
$\mathbf{H}_{A_x,A_{xx}}$ hold.
Then, for any $T\in[0,\infty)$, any
$p_X\in [p, p+\kappa-1)$
and any
\begin{equation}\begin{aligned}

\gamma
<\begin{cases}
\frac{p(p+\kappa-1 - p_X)}{(\chi+2)(\kappa-1)+\chi p},&\quad p\leq \chi+2, \\
\frac{p+\kappa-1 - p_X}{\kappa+\chi-1},  &\quad  p> \chi+2,
\end{cases}
\end{aligned}\end{equation}
we have
\begin{equation}\begin{aligned} \sup_{t\in[0,T]}
 \mathbf{E}\|X^n_t-X_t\|^{p_X}
\leq_C  h_n^{\gamma }(1+\|x\|^{p+\kappa-1}),\quad x\in\mathbb{R}^d.
\end{aligned}\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

