body:
[Proposition prop:kpz-red-compat of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The system
(equation eq:kpz-red-Lx of the paper)--(equation eq:kpz-red-Lt of the paper) is
compatible\footnote{That is, the two computations of $\Psi_{xt}$,
obtained by applying $\partial_t$ to (equation eq:kpz-red-Lx of the paper) and
$\partial_x$ to (equation eq:kpz-red-Lt of the paper), agree for arbitrary Cauchy
data $\Psi$, $\Psi_a$, $\Psi_{aa}$.} if and only if
\begin{equation}

2\Lambda_a+C_x+C_{aa} =0,
\end{equation}
\begin{equation}

2C_t-\Lambda_x+\Lambda_{aa}
+\tfrac23 C_{aaa}-2C_aC+2[C,\Lambda] =0.
\end{equation}

