[Lem 9 of arXiv:2605.26669, '2605.26669'] (Slutsky) \cite[Page 19]{S}
Let $X_n \stackrel{d}{\longrightarrow} X$ and $Y_n \stackrel{P}{\longrightarrow} c$, where $c$ is a finite constant. Then
\begin{enumerate}[$(i)$]
 \item $X_n+Y_n\stackrel{d}{\longrightarrow} X+c$;

 \item $X_n Y_n\stackrel{d}{\longrightarrow} c X$;

 \item $\frac{X_n}{Y_n} \stackrel{d}{\longrightarrow} \frac{X}{c}$ if $c\neq 0$.

\end{enumerate}

[Corollary cor:monoTreelambda of arXiv:2607.29409, 'The Zombie Infection Model'] Consider a tree $G=(V,E)$, parameters
		$\mu,\lambda \in (0,\infty)$ and $c\geq1$, and an initial set $\Delta \subset V$ consisting of one connected cluster. Then the following holds:
		\begin{enumerate}[label=\alph*)]
			\item There is a coupling $\widehat{\BP}^{\ZIM}$ of $\big(\eta_{t}^{(1)}
				\big)\sim\BP^{\ZIM}_{\lambda,\mu,G,\Delta}$ and $\big(\eta_{t}^{(2)}\big
				)\sim\BP^{\ZIM}_{c\lambda,\mu,G,\Delta}$ such that
				\begin{equation}
					\widehat{\BP}^{\ZIM}\!\left
					( \eta_{t/c}^{(2)}\geq \eta_{t}^{(1)}\: \forall \: t\in [0,\infty) \right
					) =1.
				\end{equation}

			\item There is a coupling $\widehat{\BP}^{\SIR}$ of $\big(\xi_{t}^{(1)}
				\big)\sim\BP^{\SIR}_{\lambda,\mu,G,\Delta}$ and $\big(\xi_{t}^{(2)}\big
				)\sim\BP^{\SIR}_{c\lambda, \mu,G,\Delta}$ such that
				\begin{equation}
					\widehat{\BP}^{\SIR}\!\left
					( \xi_{t/c}^{(2)}\geq \xi_{t}^{(1)}\: \forall \: t\in [0,\infty) \right
					) =1.
				\end{equation}
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:growth_f_implies_assumption of arXiv:2605.15401, 'Noise Tradeoffs, Stationary Information Flow, and Structural Balance in Unit-Birth Network'] Consider the continuous time Markov chain on $S=\mathbb{Z}_{\ge0}^N$ with generator
(equation eq:generator of the paper). Assume there exists $\varepsilon\in(0,1)$ such that
\begin{equation}
\varepsilon \ \le\ f_i(v)\qquad\text{for all }i\in\{1,\dots,N\}\text{ and all }v\in\mathbb{Z}_{\ge0}^{N-1}.
\end{equation}
Assume further that there exist constants $A,B\in[0,\infty)$ such that, for all $x\in S$,
\begin{equation}
\sum_{i=1}^N f_i(x_{-i}) \ \le\ A + B\,s(x),
\qquad s(x) = x_1 + \cdots + x_N,
\end{equation}
and that
\begin{equation}
B \ <\ \frac{1}{\tau_{\max}},
\qquad \tau_{\max}:=\max_{1\le i\le N}\tau_i.
\end{equation}
Then Condition~(condition:regularity_minimal of the paper) holds, and the corresponding
CTMC satisfies Assumption~(ass:standing of the paper).

[Prop 12 of arXiv:2608.26642, '2608.26642'] \begin{enumerate}
  \item Assume that $I-T_q^\mu$ is invertible. Then the unique solution to equation (\ref{q-eq}) is
 \begin{align}
   f=\frac{(I-T_q^\mu)^{-1}1}{\mu[(I-T_q^\mu)^{-1}1]+\frac{1}{r_q(0)}},\qquad C=\frac{1}{\mu[(I-T_q^\mu)^{-1}1]+\frac{1}{r_q(0)}}.
 \end{align}
 \item Assume that $1$ belongs to the spectrum of $T_q^\mu$. Then there exists a function $f_q^\mu \in C(K)$ such that
\begin{align}
  \ker (I-T_q^\mu)=\mathrm{span}(f_q^\mu),\qquad  \mu[f_q^\mu]=1.
\end{align}
Moreover, the unique solution to equation (\ref{q-eq}) is
\begin{align}
f=f_q^\mu,\qquad C=0.
\end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 4 (Exact nested-set reduction {\cite{FengProfiles}}) of arXiv:2606.29530, 'Cutoff profiles for colored top-\texorpdfstring{$m$}{m}-to-random shuffles with growing bl'] For every $n,p\ge1$, $1\le m\le n$, $k\ge0$, and $x\in G_{n,p}$,
\begin{equation}
        \frac{(Q_{n,p}^{(m)})^{*k}(x)}{U_{n,p}(x)}
        =\sum_{u=0}^{L_p(x)}P_k^{(m)}(u)u!p^u.
\end{equation}
Consequently, for every continuous $\Phi:[0,\infty)\to\R$,
\begin{equation}
        \sum_{x\in G_{n,p}}U_{n,p}(x)\Phi\!\left(\frac{(Q_{n,p}^{(m)})^{*k}(x)}{U_{n,p}(x)}\right)
        =\sum_{\ell=0}^{n}U_{n,p}\{L_p=\ell\}\Phi\!\left(\sum_{u=0}^{\ell}P_k^{(m)}(u)u!p^u\right).
\end{equation}
Moreover,
\begin{equation}
        \sepd\!\left((Q_{n,p}^{(m)})^{*k},U_{n,p}\right)
        =
        \begin{cases}
        1-P_k^{(m)}(0)-P_k^{(m)}(1),&p=1,\\
        1-P_k^{(m)}(0),&p\ge2.
        \end{cases}
\end{equation}

[Definition def:xi-model of arXiv:2602.12595, '\textbf{Michel Talagrand and the Rigorous Theory of Mean Field Spin Glasses}'] A broad class of models has centered Gaussian Hamiltonians with covariance
\begin{equation}
\mathbb{E}\big[H_N(\sigma^1)H_N(\sigma^2)\big]=N\,\xi(R_{1,2}),
\end{equation}
where \(\xi:[-1,1]\to\mathbb{R}\) is even and typically \(\xi(q)=\sum_{p\ge 1}\beta_p^2 q^p\) with \(\sum_p \beta_p^2<\infty\).

[Dfn 19 of arXiv:2608.29148, '2608.29148'] A pseudo-Riemannian metric $\wt g$ of signature $(2n+2, 2)$ on $\wt{\mathcal{G}}$ is called a {\it pre-ambient  metric} if it satisfies the following conditions:
\begin{itemize}
\item[(i)]  $\wt g$ is homogeneous of degree $2$: $\d_s^*\wt g=s^2 \wt g,\ s\in\mathbb{R}_+$.
\item[(ii)] The restriction of $\wt g$ to $T\mathcal{G}$ agrees with the tautological $2$-tensor 
$\boldsymbol{g}$.
\end{itemize}

[Lemma 4 of arXiv:2609.00988, 'Covering Projective Height Balls by Subspaces in Rigid Adelic Spaces'] There are constants $c_4>0$ and $C_4\ge1$, effectively computable from $d,r_2, |D_K|$, such that for every $T\ge0$:
\begin{enumerate}
\item[(i)]
\[
c_4\,(1+T^d)\le N_K(T)\le C_4\,(1+T^d);
\]
\item[(ii)]
\begin{equation}
N_K(2T)\le C_4N_K(T).
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 4 (Kernel-perturbation certificate) of arXiv:2608.21496, '2608.21496'] If $f,g\in\cF$ agree under every actual audit kernel, then
\begin{equation}
|\langle\widetilde k,f-g\rangle|
\le
\inf_{a\in\mathbb R^p}
\left\{
\left\|k-\sum_{j=1}^p a_jv_j\right\|_1
+\delta_k+\sum_{j=1}^p|a_j|\delta_j
\right\}.

\end{equation}
For one world, the centered reconstruction from the actual audit means $\widetilde y_j=\langle\widetilde v_j,f\rangle$ satisfies, for every $a$,
\begin{equation}
\left|
\langle\widetilde k,f\rangle
-\left\{\frac12+\sum_{j=1}^p a_j(\widetilde y_j-\tfrac12)\right\}
\right|
\le\frac12
\left\{
\left\|k-\sum_{j=1}^p a_jv_j\right\|_1
+\delta_k+\sum_{j=1}^p|a_j|\delta_j
\right\}.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

