[Theorem thm:main1 of arXiv:2504.18739, 'discrete analogues of second-order Riesz transforms'] \begin{itemize}
\item[(i)] 
For any bounded matrix-valued function $A$, 
\begin{equation}
   \mathbb{E}_{(0, T)}|\mathcal{P}_A^Tf(X_T)|^p\leq (p^\ast -1)^p\|A\|^p\sum_{n\in \mathbb{Z}^d}|f(n)|^p\frac{P_T(n)}{H_T(0)}.
\end{equation} 
\item[(ii)] 
For any bounded matrix-valued function $A$ satisfying the additional property~(equation Non-Symm of the paper) in Theorem~(thm:MartTrans of the paper),
\begin{equation}
    \mathbb{E}_{(0, T)}|\mathcal{P}_A^Tf(X_T)|^p\leq C_{p,b,B}^p\|A\|^p\sum_{n\in \mathbb{Z}^d}|f(n)|^p\frac{P_T(n)}{H_T(0)},
\end{equation} 
In particular, if $b=0, B=1$, then $C_{p, b, 1}=\gamma(p)$ as in~(equation ChoiAsym of the paper). 
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop uniqueness of solution for single-location master loop equation in the 't Hooft limit of arXiv:2411.11676, 'Surface sums for lattice Yang--Mills in the large-$N$ limit'] Given any $L\geq 1$, there exists $\upbeta_*(L,d)>0$ such that if $|\upbeta|\leq \upbeta_*(L,d)$, then there is a unique function $\phi_{\infty}:\mathcal{S}\to \mathbb{R}$ such that 
\begin{enumerate}
	\item $\phi_{\infty}(\emptyset) = 1$;
	\item $\phi_{\infty}$ is invariant under backtrack erasures, i.e.\ for any loop $\ell = \pi_1ee^{-1} \pi_2$, we have that $\phi_{\infty}(\ell) = \phi_{\infty}(\pi_1\pi_2)$;
	\item $|\phi_{\infty}(s)|\leq L^{|s|}$, for all $s\in \mathcal{S}$;
	\item $\phi_{\infty}(s)$ satisfies the master loop equation (equation eq:limiting_master_loop_eq of the paper),  for all non-empty $s\in \mathcal{S}$.
\end{enumerate}

[Thm t:XucpG of arXiv:2504.07255, 'A Tail-Respecting Splitting Numerical Scheme\\ for L\'evy-Driven SDEs With Superlinear Dri'] Let $c\equiv 0$ and let assumptions
$\mathbf{H}^\mathrm{diss}_A$,
$\mathbf{H}_{a,b,c}^{\mathrm{Lip}_b}$,
$\mathbf{H}_A^{\mathrm{Lip}_+}$,
and
$\mathbf{H}_{A_x,A_{xx}}$ hold.
Then, for any $T\in[0,\infty)$, $r\in(0,\infty)$ and $\lambda\in (0,\Lambda)$
\begin{align}

\sup_{t\in[0,T]}
\mathbf{E}\Big[ \Big(\mathrm{e}^{\frac{\lambda}{1+\kappa}\|X^n_t\|^{1+\kappa}}
+\mathrm{e}^{\frac{\lambda}{1+\kappa}\|X_t \|^{1+\kappa}} \Big)\|X^n_t-X_t\|^r\Big]
\leq_C h_n^\frac{r}{2}(1+\|x\|^{r(1+\chi)})\mathrm{e}^{\frac{\lambda}{1+\kappa}\|x\|^{1+\kappa}},\quad x\in\mathbb{R}^d,
\end{align}
and for any $T\in[0,\infty)$, $r\in(0,\infty)$ and $\lambda\in (0,\frac{\Lambda}{2})$
\begin{align}

&\mathbf{E}\Big[ \sup_{t\in[0,T]}\Big(\mathrm{e}^{\frac{\lambda}{1+\kappa}\|X^n_t\|^{1+\kappa}}
+\mathrm{e}^{\frac{\lambda}{1+\kappa}\|X_t \|^{1+\kappa}} \Big)\|X^n_t-X_t\|^r\Big]
\leq_C h_n^\frac{r}{2}(1+\|x\|^{r(1+\chi)})\mathrm{e}^{\frac{\lambda}{1+\kappa}\|x\|^{1+\kappa}},\quad x\in\mathbb{R}^d.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition thm:sublinear-accelerating of arXiv:2608.05105, 'Cluster-Cluster model in $\mathbb{Z}^d$'] Let \(q=-\alpha\in(0,1)\). Then
\[
    0<T_q<\infty.
\]
More precisely, define
\begin{equation}

    \kappa_q
    :=
    \inf_{0<u<1}
    \frac{
        u^q+(1-u)^q-u^{2q}-(1-u)^{2q}
    }{
        2u^q(1-u)^q
    }.
\end{equation}
Then \(\kappa_q>0\), and
\begin{equation}

    \frac1q
    \le
    T_q
    \le
    \min\left\{
        \frac1{\kappa_q},
        \frac1{1-2^{-q}}
    \right\}.
\end{equation}

Furthermore, if
\[
    M_q(t):=A_{\alpha}(t)=\sum_{k\ge1}k^q p_k(t),
\]
then, for every \(t<T_q\),
\begin{equation}

    \frac1{T_q-t}
    \le
    M_q(t)
    \le
    \frac1{\kappa_q(T_q-t)}.
\end{equation}
Consequently,
\begin{equation}

    \bigl(q(T_q-t)\bigr)^{-1/q}
    \le
    \mu(t)
    \le
    \left(
        \frac{T_q}{T_q-t}
    \right)^{1/\kappa_q},
    \qquad 0\le t<T_q,
\end{equation}
and
\begin{equation}

    \left(
        \frac{T_q-t}{T_q}
    \right)^{1/\kappa_q}
    \le
    d(t)
    \le
    \bigl(q(T_q-t)\bigr)^{1/q}.
\end{equation}

[Proposition 6 (Center-of-mass factorization) of arXiv:2608.24863, 'Uniform Logarithmic Sobolev Inequalities for the 2D Coulomb Gas at the Diffusive Temperatu'] Let
\begin{equation}
 c_N=N^{-1/2}\sum_{i=1}^Nz_i,
 \qquad
 r_k:=\frac{z_1+\cdots+z_k-kz_{k+1}}{\sqrt{k(k+1)}},
 \quad 1\le k\le N-1,
\end{equation}
and set $Z^{\rm rel}:=(r_1,\ldots,r_{N-1})$.  The map $Z\mapsto(c_N,Z^{\rm rel})$ is unitary and, in these coordinates,

\begin{equation}
 \mathbb P_{N,\beta}=\gamma_\beta^{(2)}\otimes \mathbb P_{N,\beta}^{\rm rel},
\end{equation}
where $\gamma_\beta^{(2)}(dc)=(\beta/2\pi)e^{-\beta|c|^2/2}\D c$ and $\mathbb P_{N,\beta}^{\rm rel}$ is the law of $Z^{\rm rel}$.  Consequently,
\begin{equation}
 \rho(\mathbb P_{N,\beta})=\min\{\beta,\rho(\mathbb P_{N,\beta}^{\rm rel})\}.
\end{equation}

[Lemma lem:ising-slepian of arXiv:2607.29330, 'Large deviations for the maximum of\\ the generalized TAP free energy'] The processes defined in~(equation def:X of the paper) and~(equation def:tildeX of the paper) satisfy
		\[
		\mathbb{E}
		\sup_{\substack{\mathbf{m}\in[-1,1]^N\\ \alpha\in\mathbb{N}^L}}
		X(\mathbf{m},\alpha)
		\le
		\mathbb{E}
		\sup_{\substack{\mathbf{m}\in[-1,1]^N\\ \alpha\in\mathbb{N}^L}}
		\widetilde X(\mathbf{m},\alpha).
		\]

