[Lemma 2 (Ordering the product spectrum) of arXiv:2608.22179, '\bf Token-Level Likelihood-Array Regression for Membership Inference and AI-Generated Text'] Arrange \(\{\kappa_j\kappa_k:1\leq j<k\}\) in nonincreasing order as \(\rho_1\geq\rho_2\geq\cdots\). Under \eqref{eq:supp_eigen_upper},
\[
\rho_\ell
\leq
C\left\{\frac{\ell}{\log(e\ell)}\right\}^{-\nu},
\qquad \ell\geq1,
\]
and
\[
\sum_{\ell\geq1}\frac{\rho_\ell}{\rho_\ell+\lambda}
\leq
C\lambda^{-1/\nu}\log(e/\lambda),
\qquad 0<\lambda\leq1.
\]
If the two-sided condition \eqref{eq:supp_eigen_two_sided} holds, both bounds are sharp:
\begin{equation}
  \rho_\ell
  \asymp
  \left\{
  \frac{\ell}{\log(e\ell)}
  \right\}^{-\nu},

\end{equation}
and
\begin{equation}
  \sum_{\ell\geq1}
  \frac{\rho_\ell}{\rho_\ell+\lambda}
  \asymp
  \lambda^{-1/\nu}\log(e/\lambda),
  \qquad 0<\lambda\leq1.

\end{equation}

[Prop P-prop of arXiv:2411.15954, 'A gradient model for the Bernstein polynomial basis'] For each natural number $L<N$ fixed and any $0\leq \ell\leq L$, it holds that 
\begin{enumerate}[label=(\roman*)]
        \item \textit{Mobile Clusters}: any box of length $L+2$ with \textit{at least} $\ell+1$ particles and at least one vacant site is a mobile cluster;

        \item There are blocked configurations; 

        \item Interpolation: $\text{PMM}_L(L)=\text{PMM}(L)$;

        \item \textit{Range}: For each $\eta\in\Omega_N$ it holds that $\mathbf{p}_{\ell;L}(\eta)\in [0,1]$. 

        \item Monotony: the sequence $(\mathbf{p}_{\ell;L})_{0\leq \ell\leq L}$ is non-increasing;

        \item Equilibrium expected value: for any $\rho\in[0,1]$, it holds that  $\int_{\Omega_N}
            \mathbf{p}_{\ell;L}\mathrm{d}\nu_\rho^N=\alpha^\ell$.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: character bound finite level general with M sigma with extra 2r assumption for fixed points of arXiv:2605.28770, 'Cutoff profiles for conjugacy invariant random walks on symmetric groups'] Let $r\geq 0$. As $n\to \infty$, uniformly over all $\lambda \vdash n$ such that $\lambda_1 = n-r$ and every $\sigma \in {\ensuremath{\mathfrak{S}}} _n$ such that $f_1(\sigma) \geq 2r$, we have
    \begin{equation}
        |{\ensuremath{\textup{RT}}} (\lambda, \alpha)| \lesssim_r M(\sigma)^r,
    \end{equation}
where $\alpha$ is the cycle structure of $\sigma$ written in weakly increasing order.

[Theorem thm_main_SID of arXiv:2411.08846, 'On the Number of Crossings and Bouncings\\ of a Diffusion at a Sticky Threshold'] Let $\cC{0}{},\cC{1}{},\cC{2}{},\cB{0}{},\cB{1}{},\cB{2}{},
\cD{1}{},\cD{2}{} $ be the quantities defined in 
Section~(sec_intro of the paper) for the process $X$.
Then, 
\begin{enumerate}
	[label={ (\roman*)}]
	\item  for every diverging sequence $(u_n)_n$, 
	\begin{equation}
		\bigbraces{\cB{0}{n,\cdot}(X)/u_n}, \bigbraces{\cC{0}{n,\cdot}(X)/u_n}  \convergence{\Prob_x\text{-}\mathrm{ucp}} 0,
	\end{equation} 
	\item  $ \bigbraces{\cB{1}{n,\cdot}(X) /\sqrt n}, \bigbraces{\cC{1}{n,\cdot}(X) /\sqrt n}, \bigbraces{\cD{1}{n,\cdot}(X) /\sqrt n} \convergence{\Prob_x\text{-}\mathrm{ucp}}
	\frac{4}{\sigma(0)} \sqrt{\frac 2 \pi} \loct{X}{0}{} $, 
	\item  $ \bigbraces{\cB{2}{n,\cdot}(X) /n}, \bigbraces{\cC{2}{n,\cdot}(X) /n},
	\bigbraces{\cD{2}{n,\cdot}(X) /n}
	\convergence{\Prob_x\text{-}\mathrm{ucp}} \rho \loct{X}{0}{} $, 
\end{enumerate}
where as per~(equation eq_stickySDE of the paper), $\rho \loct{X}{0}{t}= \int_{0}^{t} \mathbbm{1}_{\{X_s = 0\}} \,\mathrm{d} s $, for all $t\ge 0 $. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 4 ($\rashexpctparam$-stability of  $\emprashomonset$ at $x$) of arXiv:2609.01397, 'Measuring consistency via ensemble margin and local prediction variability: Auditing decis'] Given  a Rashomon set $\emprashomonset$, a test point $x \in \dtest$, and a small constant $\rashexpctparam > 0$, $\emprashomonset$ is said to be $\rashexpctparam$ stable at $x$ if, 
\begin{align}
    \abs{f(x)-\E_{\rf}[\rf(x)]} \le \rashexpctparam, \:\: \text{for all}\:\: f \in \emprashomonset.
\end{align}

[Proposition eq:FO-derivative of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[proposition]{prop:integrand-influence}
Let
\[
 F_O(J)=e^{\Psi_O(J)}.
\]
For each \(1\le r\le m+1\),
\begin{equation}
 \left\lvert\partial_I^rF_O(J)\right\rvert\le C_rq_N^rF_O(J),
\end{equation}
uniformly over \(O\in\mathcal O_{N,L}\), \(I\in[N]^p\), and \(J\in\mathbb R^{N^p}\).  The same estimate holds for
\begin{equation}
 F(J):=\mathcal Z_{N,L}^J(V,\varepsilon,f).
\end{equation}

[Lemma 29 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $J\subseteq [n]$, $f:\cube^n\to \Rbb$, $p\in [1,2]$ and $q\in [1,2)$,
\begin{equation*}
    \left\|f\right\|_{\Leb^\infty}^{2-p} \left\|\Dop_J f\right\|_{\Leb^p}^{p} \geq \Vop_J(f) \left[1+\frac{q}{2|J|(2-q)} \ln^{+}\left(\frac{\Vop_J(f)}{\left\|\Dop_J f\right\|_{\Leb^q}^{2}}\right)\right]^{|J|}.
\end{equation*}

