body:
[Lemma 58 (Iterated lattice convolution and cutoff tails) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] Let $m\ge2$, let
\[
 \frac{(m-1)D}{m}<\alpha\le D,
 \qquad v(x)=\langle x\rangle^{-\alpha},
 \qquad h_k=v^{*k}\quad(1\le k\le m),
\]
where convolution is on $\mathbb Z^D$.  Put
\[
 \rho=D-\alpha,
 \qquad \gamma_k=D-k\rho=k\alpha-(k-1)D>0.
\]
If $\alpha<D$, then
\begin{equation}

 h_k(z)\le C\langle z\rangle^{-\gamma_k}.
\end{equation}
If $\alpha=D$, then
\begin{equation}

 h_k(z)\le C\langle z\rangle^{-D}
                 \log(e+\langle z\rangle)^{k-1}.
\end{equation}
For $M\ge1$, let
\[
 h_{k,>M}(z):=
 \sum_{x_1+\cdots+x_k=z}
 \prod_{j=1}^kv(x_j)
 \mathbf1_{\{\max_j|x_j|>M\}}.
\]
If $\alpha<D$, then
\begin{equation}

 h_{k,>M}(z)\le
 C\max\{M,\langle z\rangle\}^{-\gamma_k}.
\end{equation}
At $\alpha=D$,
\begin{equation}

 h_{k,>M}(z)\le
 C\max\{M,\langle z\rangle\}^{-D}
 \log\!\bigl(e+\max\{M,\langle z\rangle\}\bigr)^{k-1}.
\end{equation}
Consequently, if $E\subset\mathbb Z^D$ and $\#E\le C_0R^D$, then
\begin{align}

 \sum_{z\in E}h_k(z)&\le C
 \begin{cases}
  R^{k\rho},&\alpha<D,\\
  \log(e+R)^k,&\alpha=D,
 \end{cases}\\

 \sum_{z\in E}h_{k,>M}(z)&\le C
 \begin{cases}
  R^{k\rho}\min\{1,(R/M)^{\gamma_k}\},&\alpha<D,\\
  \log(e+R)^k\min\{1,(R/M)^{\vartheta}\},&\alpha=D,
 \end{cases}
\end{align}
where the endpoint estimate holds for every $0<\vartheta<D$, with a
constant depending on $\vartheta$.

