[Lemma lem:rec-geometry of arXiv:2604.13968, 'Divisible sandpiles via random walks in random scenery'] Let $C_R\coloneqq 2/(1-B^{-\alpha})$.  There exist constants $c_N, C_N, C_{\mathrm{ball}}>0$ depending only on $B$ and~$\alpha$ such that the following hold.
		\begin{enumerate}
			\item[\textup{(a)}] For every $m\geq 1$, $L_m\leq R_m\leq C_R\,L_m$.
			\item[\textup{(b)}] For every $m\geq 0$, $c_N\,R_m^{d_f}\leq N_m\leq C_N\,R_m^{d_f}$.
			\item[\textup{(c)}] For every $m\geq 1$ and every $1\leq t\leq R_m$, $|B_{H(m)}(x,t)\setminus\{x\}|\leq C_{\mathrm{ball}}\,t^{d_f}$.
		\end{enumerate}

