[Prop masterLayerCake of arXiv:2609.02743, 'Sharp mean-field estimates for diffusive log/Riesz gases in the Hilbert--Schmidt regime'] Let $\mu\in\mathcal{P}({\mathbb{R}}^\mathsf{d})$, and let $L\ge1$ be the universal constant in (equation eq:Ustattail of the paper).  Let $g:({\mathbb{R}}^\mathsf{d})^2\rightarrow{\mathbb{R}}$ be a symmetric, measurable two-body kernel and $w:{\mathbb{R}}^\mathsf{d}\to{\mathbb{R}}$ a measurable one-body function, and consider the statistics
\begin{align}
\Xi_N(X_N)\coloneqq -\frac{1}{2N}\sum_{1\le i\ne j\le N}\tilde g(x_i,x_j)+\frac1N\sum_{i=1}^N w(x_i),
\qquad N\ge1.
\end{align}
Let $U_0\ge1$ be a threshold, and suppose that for every $N\ge1$ and every $u\ge U_0$ there exist a bounded symmetric kernel $q_{N,u}$ and a number $\mathsf m_{N,u}>0$ such that the following hold.
\begin{enumerate}[(M1)]
\item\emph{(Event reduction)}  For $\mu^{\otimes N}$-a.e.\ configuration $X_N$,
\begin{align}
\Xi_N(X_N)\ge u
\quad\Longrightarrow\quad
-\frac{1}{2N}\sum_{1\le i\ne j\le N}\tilde q_{N,u}(x_i,x_j)\ge u.
\end{align}
\item\emph{(Deterministic diagonal bound)}  For every configuration $X_N$,
\begin{align}
-\frac{1}{2N}\sum_{1\le i\ne j\le N}\tilde q_{N,u}(x_i,x_j)\le \mathsf m_{N,u}.
\end{align}
\item\emph{(Norm bounds)}
\begin{align}
\|\tilde q_{N,u}\|_{L^\infty L^2(\mu)}^2\le \frac1{L},
\qquad
\|\tilde q_{N,u}\|_{L^2(\mu^{\otimes2})}^2\le \frac1{L},
\qquad
\|\mathcal{T}_{\tilde q_{N,u}}\|_{\mathrm{op}}\le\frac1{L}.
\end{align}
\end{enumerate}
Suppose, finally, that there exists $N_0\ge1$ such that
\begin{align}
2L^2\,\sup_{u\ge U_0}\ \min\brac[\big]{u,\ \mathsf m_{N,u}}\,\pa[\big]{1+\|\tilde q_{N,u}\|_{L^\infty}}\le N
\qquad\text{for every }N\ge N_0,
\end{align}
the supremum being finite also for $N<N_0$.  Then, writing $\mathsf S_N$ for the supremum in (equation eq:masterLayerCondition of the paper),
\begin{align}
\sup_{N\ge1}\ {\mathbb{E}}_{\mu^{\otimes N}}\brak[\big]{e^{\Xi_N}}
\le \max\brac[\Big]{\max_{1\le N<N_0}e^{U_0+\mathsf S_N},\ e^{U_0}+L},
\end{align}
the inner maximum being absent when $N_0=1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition Proposition3 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Suppose that (A1 of the paper)-(A7 of the paper) hold and that $\varphi$ is an $h$-dependent descendant characteristic, for some $h \in \mathbb{N}_{0}$,  satisfying (C1 of the paper)-(C3 of the paper). Then, for every $t \in \mathbb{R}$, 
\begin{align}
\mathcal{Z}^{\varphi}_{t} \coloneqq \sum_{u \in \mathcal{I}} \varphi_{u}(t- S(u))
\end{align}
\noindent converges unconditionally in $L^{1}(\Omega, \mathcal{F}, \mathbb{P})$ and almost surely over every admissible ordering of $\mathcal{I}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:rate of arXiv:2608.21931, 'Interacting Urn Schemes on Finite Ancestral Directed Acyclic Graphs'] In the sum-reinforcement scheme, suppose first that
$G_v=\emptyset$ (equivalently, $m_1=0$), that is, all oldest ancestors
of $v$ are stubborn. Then
\begin{equation}
    \sqrt{n}(U_n-u)
    \stackrel{d}{\longrightarrow}
    N_{mk}\bigl(0,H'\Gamma_uH\bigr)
    \qquad\text{as }n\rightarrow\infty.
\end{equation}

Suppose next that $G_v\neq\emptyset$. If $\gamma<\frac{1}{2}$, then
\begin{equation}
    \sqrt{n}(U_n-u)
    \stackrel{d}{\longrightarrow}
    N_{mk}(0,\Sigma_1)
    \qquad\text{as }n\rightarrow\infty,
\end{equation}
where
\begin{equation}
    \Sigma_1
    :=
    \int_0^{\infty}
    \bigl(e^{(\frac{1}{2}I_{mk}-D_u)x}\bigr)'
    H'\Gamma_uH
    e^{(\frac{1}{2}I_{mk}-D_u)x}
    \,dx.
\end{equation}

If $\gamma=\frac{1}{2}$, then
\begin{equation}
    \frac{\sqrt{n}}{(\log n)^{\nu-\frac{1}{2}}}
    (U_n-u)
    \stackrel{d}{\longrightarrow}
    N_{mk}(0,\Sigma_2)
    \qquad\text{as }n\rightarrow\infty,
\end{equation}
where
\begin{equation}
    \Sigma_2
    :=
    \lim_{n\rightarrow\infty}
    \frac{1}{(\log n)^{2\nu-1}}
    \int_0^{\log n}
    \bigl(e^{(\frac{1}{2}I_{mk}-D_u)x}\bigr)'
    H'\Gamma_uH
    e^{(\frac{1}{2}I_{mk}-D_u)x}
    \,dx.
\end{equation}

Finally, if $\frac{1}{2}<\gamma<1$, then
\begin{equation}
    \frac{n^{1-\gamma}}{(\log n)^{\nu-1}}(U_n-u)
    -
    \sum_{\substack{l:\,\Re(\lambda_l)=\gamma,\nu_l=\nu}}
    e^{i\Im(\lambda_l)\log n}\xi_l\mathbf{r}_l
    \stackrel{a.s.}{\longrightarrow}0
    \qquad\text{as }n\rightarrow\infty,
\end{equation}
where $i=\sqrt{-1}$, and $\xi_l$'s are complex random variables defined
for all $l$ such that $\Re(\lambda_l)=\gamma$ and $\nu_l=\nu$.
Here, $\mathbf{r}_l$ is a specific left eigenvector (possibly generalized)
of $D_u$ corresponding to the eigenvalue $1-\lambda_l$. More precisely,
if $\Re(\lambda_l)=\gamma$, then $\mathbf{r}_l$ is the
$(\nu_1+\nu_2+\cdots+\nu_l)$-th row of the matrix $T^{-1}$.

Moreover, if $D_u$ is diagonalizable in $\mathbb{R}^{mk\times mk}$, then
there exists a real random vector $L$ such that
\begin{equation}
    \frac{n^{1-\gamma}}{(\log n)^{\nu-1}}(U_n-u)
    \stackrel{a.s.}{\longrightarrow}
    L
    \qquad\text{as }n\rightarrow\infty.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:est for iid of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] Let $\{X_k\}_{k\geq 1}$ be a d-dimensional i.i.d. sequence such that $\hat{\mathbb{E}}[|X_1|^{1+\beta}]<\infty$ for some $\beta\in (0,1]$ and $v\in C_b^{1,1+\beta}(\mathbb{R}_+\times \mathbb{R}^d)$ be the solution to equation (equation PDE of the paper) with $p(a)=\hat{\mathbb{E}}[\langle a, X_1\rangle]$. Set $S_n=\frac{1}{n}\sum_{i=1}^nX_i$. Then we have
        \begin{equation}
           \begin{split}
				v(1,0)-\hat{\mathbb{E}}[\phi(S_n)]&\geq -4n^{-\beta}\int_0^1|\nabla_xv(s,\cdot)|_{\beta}ds\times \hat{\mathbb{E}}[|X_1|^{1+\beta}]+\underline{f},
			\end{split}
        \end{equation}
        where 
		$
			\underline{f}=\inf_{\{0\leq t\leq 1,x\in \mathbb{R}^d\}}f(t,x)
	$ with $f$ defined as in (equation PDE of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm jointr1r2 of arXiv:2412.00610, 'Joint Poisson Convergence of Monochromatic Hyperedges in Multiplex Hypergraphs'] Fix integers $2 \le r_1 < r_2$. Let $\bm H_n = (H_n^{(1)}, H_n^{(2)})$ be a sequence of 2-hypermultiplexes on the same set of vertices $V_n$, such that 
$H_n^{(1)}$ is $r_1$-uniform, $H_n^{(2)}$ is $r_2$-uniform, $|E(H_n^{(1)})| \to \infty,$ and $|E(H_n^{(2)})| \to \infty$. Suppose $V_n$ is colored uniformly at random with $c_n$ colors as in (equation eq:cn of the paper), such that the following hold: 
      \begin{itemize}
      \item  There exist constants $\lambda_1, \lambda_2 \ge 0$ such that 
            \begin{align}
            \frac{|E(H_n^{(1)})|}{c_n^{r_1-1}} \to \lambda_1,~\frac{|E(H_n^{(2)})|}{c_n^{r_2-1}} \to \lambda_2 . 
            \end{align}

      \item  For all $t_1 \in [2, r_1 - 1]$ and $t_2 \in [2, r_2 - 1]$, 
      \begin{align}
      \frac{|\cK(t_1, H_n^{(1)})|}{c_n^{2r_1-t_1-1}} \to 0 \text{ and } \frac{|\cK(t_2, H_n^{(2)})|}{c_n^{2r_2-t_2-1}} \to 0 , 
      \end{align} 
     where $\cK(\cdot, \cdot)$ is defined in (equation defn:K of the paper). 
  \end{itemize} 
Then 
  $$\bm T(\bm H_n)= \left(\begin{array}{l}
    T(H_n^{(1)}) \\
    T(H_n^{(2)})
    \end{array}\right) \dto \left(\begin{array}{l}
      Z_1\\
      Z_2
      \end{array}\right) , $$
    where $Z_1 \sim \Pois(\lambda_1), Z_2 \sim \Pois(\lambda_2)$ are independent. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Mainresultd 3 (Exact profile formulas) of arXiv:2609.04143, 'The Geometry of Real Anisotropic Bohnenblust--Hille Constants'] Let $m\ge2$.
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.35em]
\item For every $0\le s\le1$,
\begin{equation}
 \max_{\substack{\mathbf q\in\mathcal B_m\\ \sigma(\mathbf q)=s}}
 C_{\mathbf q}^{(m)}
 =2^{(m-1)s/2}.
\end{equation}
The maximum is attained by every permutation of
\[
 \mathbf q_s=\left(\frac{2}{1+s},2,\ldots,2\right).
\]

\item For every Bohnenblust--Hille exponent $\mathbf q$ with $\sigma(\mathbf q)>0$ and $Y_1(\mathbf q)\ge1/2$,
\begin{equation}
 C_{\mathbf q}^{(m)}
 =2^{\frac{\sigma(\mathbf q)}{2}\left(1+(m-2)Y_1(\mathbf q)\right)}.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 3 of arXiv:2606.00648, 'Asymptotic estimates for multiple point ranges of transient random walks on graphs'] For every $\epsilon > 0$, there exists $\theta(\epsilon) > 0$ such that 
for every random variable $Y$ on a probability space satisfying $|Y| \le 1$, 
\begin{equation}
E\left[\exp(\theta(\epsilon) Y) \right] \le 1 + \theta(\epsilon) (E[Y] + \epsilon) \le \exp\left(  \theta(\epsilon) (E[Y] + \epsilon) \right). 
\end{equation}

[Lem SK_dist_limit of arXiv:2608.25362, 'Fluctuations of the free energy of the Sherrington--Kirkpatrick model with ferromagnetic i'] {CDP17}}]
    For $\boldsymbol{\beta}\in\mathcal{B}$ and $h\in\mathds{R}$ with $h\ne0$,
    \begin{align*}
        \lim_{N\to\infty} d_{TV}\Big( \frac{F_N^{SK}(\boldsymbol{\beta},h) - \bar F_N^{SK}(\boldsymbol{\beta},h)}{\sqrt{\nu/N}},\; g \Big) = 0,
    \end{align*}
    where $g$ is a standard Gaussian random variable and $d_{TV}(X,Y) := \sup_A \left\vert\pr(X\in A) - \pr(Y\in A)\right\vert$. (Proof in the paper; no proof environment follows the statement in the TeX.)

