body:
[Thm TH1 of arXiv:2411.15724, 'Wasserstein Convergence Rates for Empirical Measures of Random Subsequence of $\{nα\}$'] Let $X_1,X_2,\ldots$ be integer-valued i.i.d. random variables with characteristic function $\varphi$, and let $S_j = \sum_{i = 1}^{j} X_i$. Let $\alpha$ be an irrational number such that
$$\| q \alpha \| \geq C q^{-\gamma}$$
holds for any $q \in \mathbb N$ with some constants $\gamma \geq 1$ and $C > 0$. Suppose that
\begin{equation}
|1-\varphi(x)| \ge c|  x |^{\beta}.
\end{equation}
holds in an open neighborhood of $0$ with constants $c > 0$ and $0< \beta \le 2$. Set $\mu_n = \frac{1}{n} \sum_{j = 1}^{n} \delta_{\{ S_j \alpha \}}$, $n \geq 1$. Then for $1 \leq p < \infty$,
\begin{equation*}
\mathbb E \big[\mathbb W_p(\mu_n,\mu) \big] =
\begin{cases}
O \big( \frac{1}{\sqrt{n}} \big) , & \textrm{if } \beta \gamma < 2;\\
O\big( \frac{(\log n)^{1 - \frac{1}{p \vee 2}}}{\sqrt{n}}  \big), & \textrm{if } \beta \gamma =2;\\
O\big( \frac{1}{n^{1/(\beta \gamma)}} \big),& \textrm{if } \beta \gamma >2,
\end{cases}
\end{equation*}
where the implied constants depend on $p$ and conditions on $\alpha$ and $\varphi$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 of arXiv:2608.29361, 'Convergence of the subcritical $\gamma$-LQG metric to the critical $2$-LQG metric as $\gam'] There exist universal constants $c_0,c_1>0$ such that the following holds for all $S>1,z \in \CC$, and all $t > 0$. A.s., we have that
\begin{equation*}
    \mathbb{P}\left[M_{e^{-t}}(z) > S \giv h_{e^{-t}}(z) - h_1(z) \right] \leq c_0 (S/4)^{-b(\xi) \sqrt{M(\xi)}} + c_0 e^{-c_1 (\log S)^2}.
\end{equation*}

[Proposition of arXiv:2604.16206, 'Extrapolation of max--stable random fields with Fr\'echet marginals'] The tail dependence function $l_{\mathbf{B}_T}$ of $\mathbf{B}_T=(B_{t_1},\ldots, B_{t_n})$  equals
    \begin{align*}
        l_{\mathbf{B}_T}((x_1,\ldots,x_n))&=\int_{\mathbb{R}^n}\bigvee_{j=1}^n x_j e^{z_j-\frac{1}{2}\sigma^2(t_j)}f_{\Sigma_n}(\mathbf{z})d \mathbf{z}\\
        &=\int_{0}^{+\infty}\left[1-F_{\Sigma_n}\left(\log\frac{y}{x_1}+\frac{\sigma^2(t_1)}{2},\ldots,\log\frac{y}{x_n}+\frac{\sigma^2(t_n)}{2}\right)\right]dy
    \end{align*}
   for $\mathbf{x}=(x_1,\ldots,x_n)\in\mathbb{R}_+^n$,  where  $\mathbf{z} = (z_1,\ldots,z_n)$, $d\mathbf{z} = dz_1\ldots dz_n$, and $\Sigma_n$ is the covariance matrix of the underlying Gaussian random vector $(Y_{t_1},\ldots,Y_{t_n}).$

[Theorem u-pth-moment of arXiv:2607.02742, 'Gaussian fluctuations for the parabolic Anderson model with L\'evy white noise'] Let $p\in [2,3)$ be such that $m_p<\infty$. Let $u$ be the mild solution of
(equation pAm of the paper). Then, 
\begin{equation}

    \sup_{(t,x)\in [0,T]\times \mathbb{R}} \mathbb{E}|u(t,x)|^p <\infty \quad \mbox{for any $T>0$}.
\end{equation}

