[Lemma 27 of arXiv:2606.14443, 'SEMICLASSICAL LIMIT OF POLYAKOV-LIOUVILLE MEASURE and Q-Curvature Uniformization ON EVEN-D'] Let $h$ and $(h_{\ell})_{\ell\in\N}$ be given by \eqref{eq: white noise trunc}. Then
	\begin{align*}
		\mathcal B^*_{\gamma,l}=\{\scalar{h-h_{\ell}}{\varphi}\geq \gamma^2\}\cup \{\mu^*_{\ell}-\mu^*\geq \gamma^3\},
	\end{align*}
	where 
	\begin{align*}
		\mu^*_{\ell}=\mu^{\gamma h_{\ell}}(\varphi),\quad \mu^*=\mu^{\gamma h}(\varphi).
	\end{align*}
	Then there exists a constant $c>0$ such that for all $0<\gamma\leq 1$ 
	\begin{align*}
		\P[\mathcal B^*_{\gamma,\ell(\gamma)}]\leq \exp(c\gamma^{-2}\log \gamma),
	\end{align*}
	where ${\ell}(\gamma)=\lceil e^{\gamma^{-1/6}}\rceil$.

