[Definition def:cycles of arXiv:2607.02367, 'Flux solutions for stochastic chemical systems with sources and sinks'] The space of the cycles of a chemical system  $(\Omega, \mathcal R, \mathcal R_s,  \mathcal K, \mathcal K_s )$ is defined as
\begin{equation*}
\mathcal W := \left\{  w \in \mathbb R^{r + |\Omega_c|} : \sum_{\rho=1}^{r } w(\rho) S_\rho + \sum_{ k \in \Omega_c } w(k ) =0 \right\}. 
\end{equation*}

[Lemma 13 of arXiv:2606.31596, 'The Invariant Measure of Multiscale Markov Chains via Fast Arborescence Factorization'] $2\leq h\leq n$. Let $C_1,\dots,C_h$ be a partition of $\hat V$ and $T^h=T^h(C_1,\dots,C_n)$ defined as after \eqref{peRk}. Then:
\begin{equation}
	\sum_{(y_2,\dots ,y_h)\in T^h}r(s,y_2)\cdots r(s,y_h) 	\,=\, 
\left(r^\textup{out}(s)\right)^{h-2}\;\sum_{y\in C_1}r(s,y)
\end{equation}

[Definition Def_ModuliSpaceOfRamifiedEuclideanLineBundles of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] {Doan2024}}]

  The \defined{moduli space of ramified Euclidean line bundles} over $X$ is constructed as follows:
  \begin{enumerate}
  \item

    Denote by $\mathbf{Sub}$ the \emph{set} of closed codimension-two submanifolds $Z \subseteq X$.
    Equip $\mathbf{Sub}$ with the following tame Fréchet manifold structure described in [Hamilton1982:NashMoser].

    Given $Z \in \mathbf{Sub}$ and a tubular neighbourhood $\jmath \mskip0.5mu\colon\thinspace NZ \supseteq U \to X$ of $Z$,
    define the map $\phi_\jmath^{-1} \mskip0.5mu\colon\thinspace \Gamma\paren{Z,NZ} \supseteq \Gamma\paren{Z,U} \to \mathbf{Sub}$ by
    \begin{equation*}
      \phi_\jmath^{-1}(v) \coloneq \im \paren{\jmath \circ v}.
    \end{equation*}
    Denote by $\phi_\jmath$ the inverse of $\phi_\jmath^{-1} \mskip0.5mu\colon\thinspace \Gamma\paren{Z,U} \to \im \phi_\jmath^{-1}$.
    Equip $\Gamma\paren{Z,NZ}$ with the usual structure of a tame Fréchet space;
    see [Hamilton1982:NashMoser].
    The charts constructed in [Hamilton1982:NashMoser] are of the form $\phi_\jmath$. 
  \item

    Denote by $\mathbf{Ram}$ the \emph{set} of isometry classes of ramified Euclidean line bundles $(Z,{\mathfrak l})$ over $X$ with smooth $Z$.
    Consider the map
    \begin{equation*}
      \mathrm{Br} \mskip0.5mu\colon\thinspace \mathbf{Ram} \to \mathbf{Sub}
    \end{equation*}
    assigning to $(Z,[{\mathfrak l}])$ the branching locus $Z$.
  \item

    For every open subset $U \subseteq X$ denote by $\mathbf{Sub}_U \subseteq \mathbf{Sub}$ the open subset of those $Z \in \mathbf{Sub}$ for which:
    \begin{enumerate}
    \item
      $Z \subseteq U$, and
    \item
      the restriction ${\rm H}^1\paren{X{\backslash} Z,\set{\pm 1}} \to {\rm H}^1\paren{X{\backslash} U,\set{\pm 1}}$ is an isomorphism.
    \end{enumerate}
    The subset $\mathbf{Sub}_U$ is open and the monodromy representations assemble into an injection
    \begin{equation*}
      \tau_U \mskip0.5mu\colon\thinspace \mathrm{Br}^{-1}(\mathbf{Sub}_U) \to \mathbf{Sub}_U \times {\rm H}^1\paren{X{\backslash} U,\set{\pm 1}}.
    \end{equation*}
    Equip $\mathbf{Ram}$ with the coarsest \emph{topology} with respect to which the maps $\tau_U$ are continuous.
  \item

    With respect to the above topology $\mathrm{Br} \mskip0.5mu\colon\thinspace \mathbf{Ram} \to \mathbf{Sub}$ is a locally finite covering map; cf.~[tomDieck2008:AlgebraicTopology].
    In particular, $\mathbf{Ram}$ inherits the structure of a tame Fréchet manifold from $\mathbf{Sub}$.
    Moreover, for every $(Z,[{\mathfrak l}]) \in \mathbf{Ram}$,
    \begin{equation*}
      T_{(Z,[{\mathfrak l}])}\mathbf{Ram} = T_Z\mathbf{Sub} = \Gamma\paren{Z,NZ}.
    \end{equation*}
  \end{enumerate}
  In the following $(Z,[{\mathfrak l}])$ is frequently abbreviated to $[{\mathfrak l}]$.
  This is harmless, because $Z$ can be recovered as $\mathrm{Br}({\mathfrak l})$.
  \qedhere

[Proposition p: hyperfluctuating points in lattice of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] The point process $\Psi$, defined as in~(equation e: hyperfluctuating points in lattice of the paper), is solely $(-d+2+p)$-uniform. This degree is negative iff $d\geq 3$.
    \begin{proof}
        Let $\tilde\Phi:=\Z^d+U$ and define the invariant transport kernel $K$ by
        \begin{equation}
            K_x := \I\{\Phi(\{x\})=1\} \delta_{x+\frac{1}{2}e_1} + \I\{\Phi(\{x\})=0\} \delta_{x-\frac{1}{2}e_1}, \quad x\in\R^d.
        \end{equation}
        Note that therefore $\Psi = K\tilde\Phi$, and
        \begin{equation}
            K^\ast_x = \delta_{(\Phi(\{x\})-\frac{1}{2})e_1}, \quad x\in\R^d.
        \end{equation}
        Now we apply Theorem~(t:main theorem of the paper) with the parameter $\tilde{p}:=-d+2+p$. As $K$ is a probability kernel and the transport distance is bounded by $\frac{1}{2}$, Condition~(c:condition square-integrable general with p of the paper) is obviously fulfilled. Let us now define $\Psi_q$ for $q\in\N_0$ like in~(equation e:Psi_q definition of the paper), whereby
        \begin{equation}
            \Psi_q(dy) = \Big(\Big(\Phi(\{y\})-\frac{1}{2}\Big)e_1\Big)^{\otimes q} \tilde\Phi(dy).
        \end{equation}
        Hence, for $q\in2\N_0$, we have $\Psi_q = \frac{1}{2^q}e_1^{\otimes q}\tilde\Phi$, which implies that it is $\infty$-uniform. Moreover, for $q\in2\N_0+1$, we have $\Psi_q = \frac{1}{2^{q-1}}e_1^{\otimes q}\Phi-\frac{1}{2^q}e_1^{\otimes q}\tilde\Phi$, which implies that it is $(-d+p)$-uniform. In total, Theorem~(t:main theorem of the paper) yields that $\Psi$ is $(-d+2+p)$-uniform, where the dominant contribution comes from $\Psi_1$. We improve this result by applying Theorem~(t: main theorem rate of the paper) to show that $\Psi$ is not beyond $(-d+2+p)$-uniform. Let $0\neq f\in\cC_c^\infty(\R^d, [0,\infty))$ be isotropic and define $f_r:=f(\frac{\cdot}{r})$ for $r>0$. Now we have to show that
        \begin{equation}
            \limsup_{r\to\infty} \frac{\BV\big[\Psi_1\big(f_r'\big)\big]}{r^{2d-(2+p)}} > 0.
        \end{equation}
        Using what we calculated so far and the variance formula~(equation e: spectral covariance formula of the paper), we obtain that, as $r\to\infty$,
        \begin{align*}
            \frac{\BV\big[\Psi_1\big(f_r'\big)\big]}{r^{2d-(2+p)}} &= \frac{1}{4^{q-1}r^{2d-(2+p)}}\BV[\Phi(\partial_1 f_r)] + o(1)\nonumber\\
            &= \frac{r^{2+p}}{4^{q-1}(2\pi)^d}\int k_1^2 |\hat{f}(rk)|^2\,\hat\beta_\Phi(dk) + o(1)\nonumber\\
            &= \frac{r^{p}}{4^{q-1}d(2\pi)^d}\int \|rk\|^2 |\hat{f}(rk)|^2\,\hat\beta_\Phi(dk) + o(1),
        \end{align*}
        where we applied the invariance of $f$ and the distribution of $\Phi$ under isometries of the lattice in the last step. The function $k\mapsto \|k\|\hat{f}(k)$ is isotropic, and while we formally do not satisfy the conditions in Proposition~(p:asymptotic variance test function zero integral of the paper), we can use an argument similar to it to show that if
        \begin{equation*}
            \limsup_{r\to\infty} r^{p}\int \|rk\|^2 |\hat{f}(rk)|^2\,\hat\beta_\Phi(dk) = 0,
        \end{equation*}
        then $\Phi$ must be beyond $(-d+p)$-uniform. However, we assumed that this is not the case, whereby the $\limsup$ must be positive. This fact concludes the proof, as~(equation e: Psi_1 limit condition hyperfluctuating points of the paper) has been proven.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem-level-set-concentration of arXiv:2607.22324, 'The conclave process'] {}
    Suppose that $X =(X_1,\ldots,X_n) \sim \mathsf{Mult}(n;\frac{1}{n}, \ldots,\frac{1}{n})$. Define 
    \begin{align*}
        \mathbf M=\max_{1 \leq i \leq n}X_i\,, \quad Y_j = \#\{i: X_i = j\}\,.
    \end{align*}
    Then we define $\aleph>0$ to be the unique positive integer such that $\aleph! \leq n < (\aleph+1)!$, and define the events
    \begin{align*}
        &\mathcal D_{\mathsf{unique}} = \{ Y_{\mathbf M} = 1 \} \,,
        \quad \mathcal D_{\mathsf{max}} = \left\{ |\mathbf M-\aleph| \leq 2 \right\} \,, \\
        &\mathcal D_{\mathsf{lb}} = \left\{ Y_j\geq \frac{0.4n}{ej!} \mbox{ for all }0 \leq j \leq \aleph-1 \right\} \,,  \\
        &\mathcal D_{\mathsf{ub}} = \left\{ Y_j\leq \frac{10n}{e((j-4)\vee 0)!} \vee 9\aleph^8 \mbox{ for all } 0 \leq j \leq \aleph+2 \right\} \,,\\
    \end{align*}
    Then we have $\mathbb P(\mathcal D_{\mathsf{unique}}) \wedge \mathbb P(\mathcal D^c_{\mathsf{unique}}) \geq \frac{1}{30\aleph}$. 
    and
    \begin{align}
        \mathbb P(\mathcal D_{\mathsf{max}} \cap \mathcal D_{\mathsf{lb}} \cap \mathcal D_{\mathsf{ub}} | \mathcal D_{\mathsf{unique}}), \quad \mathbb P(\mathcal D_{\mathsf{max}} \cap \mathcal D_{\mathsf{lb}} \cap \mathcal D_{\mathsf{ub}} | \mathcal D_{\mathsf{unique}}^c) = 1 - o(1)\,.
    \end{align}

[Proposition 10 of arXiv:2608.27156, 'Traveling Waves in Equity Markets with\\Rank-Based Entry and Exit'] In the setting of Theorem~\ref{thm:relaxation}, with $\tilde f'$ locally Lipschitz, let $U_0$ and $c_0$ be the front and speed in the canonical frame \eqref{eq:canonical} from Step 1 of the proof, and let
\begin{equation*}
    \mathcal{L}\psi \;=\; \pp^2_{zz}\psi + c_0\,\pp_z\psi + \tilde f'(U_0)\,\psi
\end{equation*}
be the linearization about the front in the moving frame, acting on the space $C_{\mathrm{unif}}(\R)$ of bounded uniformly continuous functions. Then zero is a simple eigenvalue of $\mathcal{L}$, and the rate in \eqref{eq:relaxation} may be taken to be any $\gamma < \gamma_1$, where the spectral gap $\gamma_1 > 0$ is the distance from zero to the rest of the spectrum. Moreover,
\begin{equation}
    \gamma_1 \;\leq\; \gamma_0 \;:=\; \min\big(|\tilde f'(0)|,\ |\tilde f'(1)|\big),
\end{equation}
where $\gamma_0$ is the edge of the essential spectrum of $\mathcal{L}$, and equality holds in \eqref{eq:gamma-zero} if and only if zero is the only eigenvalue of $\mathcal{L}$ above the essential spectrum.

[Lemm l:nested of arXiv:2607.18194, 'Temperature chaos in directed polymers'] Let $\{B_r\}_{r>0}\subset \mathcal{B}(\mathbb{R}^2)$ be an increasing collection of Borel sets: $B_{r}\subset B_{r'}$ for all $0<r<r'$.
    Then
    \begin{align}
        \mathcal{F}_{\bigcap_{r>0}B_r} = \bigcap_{r>0}\mathcal{F}_{B_r}
    \end{align}
    and
    \begin{align}
        \mathcal{F}_{\bigcup_{r>0}B_r} = 
        \bigvee_{r>0}\mathcal{F}_{B_r}.
    \end{align}

[Lemma 37 of arXiv:2512.07202, 'Hitting Probabilities for Hypoelliptic Differential Equations Driven by Fractional Brownia'] Let \( \mathcal{V} = \{V_\alpha\}_{\alpha=1}^d \subseteq C_b^\infty(\mathbb{R}^N; \mathbb{R}^N) \) be a family of equiregular $C^\infty_b$-vector fields on \( \mathbb{R}^N \). For every compact set \( K \subseteq \mathbb{R}^N \), there exist positive constants \( \varepsilon_0\) and \( C_{1,\mathcal{V},K} < C_{2,\mathcal{V},K} \), such that
\begin{equation}
    C_{1,\mathcal{V},K} \varepsilon^Q \leqslant |B_d(q,\varepsilon)|_{\mathrm{Vol}} \leqslant C_{2,\mathcal{V},K} \varepsilon^Q
\end{equation}
for all \( q \in K \) and \( \varepsilon < \varepsilon_0 \), where 

$Q$ denotes the homogeneous dimension (see Definition \ref{defofhomodim}). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi 6 of arXiv:2506.15736, 'Coming down from infinity for coordinated particle systems'] For a coordinated particle system that has $b$ particles at site $u \in V$, the rates at which $k$ of these particles coalesce, die, migrate to site $v \in V$, or reproduce at site $v \in V$ are

    \begin{align*}
        \lambda_{b,k}^{(v)} &= \int_{0}^1 z^k(1-z)^{b-k} \frac{\Lambda_v(dz)}{z^2},\\
        d_{b,k}^{(v)} &= \int_{0}^1 z^k(1-z)^{b-k} \frac{D_v(dz)}{z},\\
        m_{b,k}^{(u,v)} &= \int_{0}^1 z^k(1-z)^{b-k} \frac{M_{uv}(dz)}{z},\\
        r_{b,k}^{(u,v)} &= \int_{0}^1 z^k(1-z)^{b-k} \frac{R_{uv}(dz)}{z},
    \end{align*}

    \noindent respectively. Similarly we can write the total rate of mergers at site $v \in V$ when there are $b$ particles present as

    \begin{align*}
        \lambda_b^{(v)} = \sum_{k = 2}^b \binom{b}{k} \lambda_{b,k}^{(v)}.
    \end{align*}

    \noindent Similar formulas hold for the total rates of death, migration, and reproduction and we shall denote these quantities $d_b^{(v)}, m_{b}^{(u,v)},$ and $r_{b}^{(u,v)}$ respectively. Note we may drop the superscript denoting the site if $|V| = 1$ or the site is clear from context.

[Lemma 8 of arXiv:2605.21424, 'A dice game, a multinomial walk, and the inverted Dirichlet distribution'] Let \(m\ge 2\) be an integer, \(n_1,\ldots,n_m\in \N_{\ge 1}\) and 
\(p_1,\ldots,p_m\in (0,1)\) with  \(p_1+\ldots+p_m=1\).
Let $(A_2,\dotsc,A_m)$ have a negative multinomial distribution with parameters $(n_1;p_2,\dotsc,p_m)$ and $(X_2,\dotsc,X_m)\sim \operatorname{ID}(n_2,\dotsc,n_m;n_1)$. Then
\begin{align*}
\mathbb{P}(A_2\leq n_2-1,\dotsc,A_m\leq n_m-1)=\mathbb{P}\left(X_2>\frac{p_2}{p_1},\dotsc,X_m>\frac{p_m}{p_1}\right).
\end{align*}

