[Proposition 3 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, let $E_*\in\mb D_0$ be a regular right edge in the sense of Definition~\ref{def:reg_r_edge}. Then there exists $\eps_*>0$ such that
        \begin{align}
                \rho(E)=c_{\rm edge}(E_*-E)^{1/2}+O(E_*-E),\qquad E\in[E_*-\eps_*,E_*], 
        \end{align}
        where $c_{\rm edge}$ is given by \eqref{eq:dens_sqrt} and satisfies $c_{\rm edge}\sim1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary co-incited-5 of arXiv:2411.12623, 'Random signed measures'] The representation $((representation-ultra of the paper))$ can be written as
	\begin{equation*}
		\xi=\alpha+\sum_{k}(\delta_{s_k}\otimes\beta_k)+\int\int (\delta_s\otimes\mu)\eta(ds\,d\mu)
	\end{equation*}
	where $\eta$ is a Poisson process on $S\times(\mathcal{M}_T\cup-\mathcal{M}_T\setminus\{0\})$. Let $F$ the L\'{e}vy measure of $\eta$. Then, the characteristic function of $\xi$ is
	\begin{align*}
		&\mathbb{E}\left[e^{it\xi(B\times C)}\right]\\&=\exp\bigg(it\alpha(B\times C) +\int_{\mathcal{M}_T\cup-\mathcal{M}_T\setminus\{0\}}e^{it\mu(C)} -1F(B\times d\mu)\bigg)\prod_{i=1}^{k}\mathbb{E}\left[e^{it \beta_i(C)\delta_{s_i}(B)}\right],
	\end{align*}
	where $t\in\mathbb{R}$, $B\in\hat{\mathcal{S}}$ and $C\in\hat{\mathcal{T}}$. When $\xi$ has no fixed atoms, then $\xi_+$ and $\xi_-$ are independent and they are given by
	\begin{equation*}
		\xi_+=\alpha_++\int\int (\delta_s\otimes\mu)\eta_+(ds\,d\mu),\quad\text{and}\quad 	
		\xi_-=\alpha_-+\int\int (\delta_s\otimes\mu)\eta_-(ds\,d\mu).
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop prop1 of arXiv:2507.18080, 'An upper bound for the lower tail of the mass of balls under the Critical $2d$ stochastic '] Let $u_0, \phi\in C_{c,+}({\mathbb{R}}^2)$ and $\vartheta\in {\mathbb{R}}$. Then, we have \begin{align*}
\mathscr{Z}^\vartheta_t(u_0,\phi)\geq0 
\end{align*} 
for all $t\geq 0$ almost surely.

Moreover, we have \begin{align*}
E\left[\mathscr{Z}^\vartheta_t(u_0,\phi)\right]=\int_{{\mathbb{R}}^2\times {\mathbb{R}}^2}u_0(x)p_t(x,y)\phi(y)\text{\rm d} x\text{\rm d} y.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 14 of arXiv:2607.13308, 'No infinite clusters at criticality for two-dimensional dependent percolation under abstra'] Given $\varepsilon>0$< there exists $\uc{c:approximation_environment}>0$ such that, for every $\lambda \in \R$, $r \geq 2$, and $x \in \Z^{2}$,
\begin{equation}
\P \big( \omega_{\lambda}(x) \neq \omega_{\lambda}^{r}(x) \big) \leq \uc{c:approximation_environment}r^{-\beta+1+\varepsilon}.
\end{equation}

