body:
[Definition def:F-DDSDE of arXiv:2607.00800, 'Brownian motion in Minkowski normed spaces'] \ 
\begin{enumerate}[(i)]
    \item A (\emph{probabilistically weak}) \emph{solution} to (equation eq:DDSDE of the paper) is a quadruple consisting of a stochastic basis $(\Omega, \mathcal F, (\mathcal F_t)_{t\geq 0}, \mathbb{P})$, an $(\mathcal F_t)$-standard Brownian motion $W = (W_t)_{t\geq 0}$, a family of probability densities $u(t) \in \mathfrak{C}$, $t>0$,  and an $(\mathcal F_t)$-adapted stochastic process $X = (X_t)_{t\geq 0}$ on $\Omega$ such that $\mathcal{L}(X_t)  = u(t,x) \,\mathrm d x$ for all $t>0$,
    \begin{equation*}
        \mathbb{E}\bigg[ \int_0^T \Bigl( \bigl|b\bigl(X_t,\mathcal{L}(X_t)\bigr)\bigr| + \bigl|a\bigl(X_t,\mathcal{L}(X_t)\bigr) \bigr| \Bigr) \,\mathrm d t \bigg] < \infty, \quad \forall T>0
    \end{equation*}
    (where $\mathbb{E}$ denotes the expectation with respect to $\mathbb{P}$),
    and, $\mathbb{P}$-a.s.,
    \begin{equation*}
        X_t -X_0 = \int_0^t b\bigl( X_r,\mathcal{L}(X_r) \bigr) \,\mathrm d r + \int_0^t \sqrt{2a\bigl(X_r,\mathcal{L}(X_r)\bigr)} \,\mathrm d W_r,\quad \forall t\geq 0.
    \end{equation*}
Below, we usually simply refer to $X$ instead of the entire quadruple as a solution.
\item For each solution $X$, we call its path law $P = \mathcal{L}(X)$ (a probability measure on $C([0,\infty);\mathbb{R}^d)$) a \emph{solution path law} to (equation eq:DDSDE of the paper).
\item We say that solutions to (equation eq:DDSDE of the paper) with initial datum $\zeta \in \mathcal P$ are \emph{weakly unique} if $\mathcal{L}(X) = \mathcal{L}(Y)$ for any two solutions $X,Y$ with $\mathcal{L}(X_0) = \mathcal{L}(Y_0) = \zeta$. 
\end{enumerate}

[Prop 2 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] Let $p\in (2d,\infty)$ and assume that the initial value $(u^0,w^0)$ satisfies~\eqref{a1}. Then the corresponding solution $(u,w)$ to~\eqref{E} satisfies
\begin{equation*}
\mathcal{L}(u,w)(t)+\int_0^t \mathcal{D}(u,w)(s)\,\rd s\le \mathcal{L}\big(u^0,w^0\big)\,,\quad t\ge 0\,,
\end{equation*}
where
\begin{equation*}
	\mathcal{D}(u,w):=\int_\Omega u\big\vert \nabla\big(\phi'(u)-\mathcal{K}[ w-\langle  w \rangle]\big)\big\vert^2\,\rd x+\|\nabla \mathcal{K}[u-w - \langle u-w\rangle]\|_2^2\ge 0\,.
\end{equation*}
In particular, $\mathcal{L}$ is a Lyapunov functional for~\eqref{E}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 186 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Let $\sigma,b,\scB\in B^{0,\infty}$.
  Let $f\in C^{\infty}_{0}$. Then for any integer $n>d/4$
there exist constants $\widetilde{D\sigma'}$
and $\tilde b'$, depending only
\index{$S$@Miscelenea!$\widetilde{D\sigma'}$}
\index{$S$@Miscelenea!$\bar b_{R}$@$\tilde b'$}
on $d ,\delta,p_{0},n$ such that if  
\begin{equation}

\widetilde{D\sigma}_{ p_{0},\rho_{0}}\leq \widetilde{D\sigma'},\quad \tilde b_{ p_{0},\rho_{0}}
\leq\tilde b' ,
\end{equation}
then
\begin{equation}

 \sum_{n=1}^{\infty}\int_{\Gamma_{n}(t_{0})}T_{0,t_{n }}
Q_{t_{n},...,t_{0}}f(x_{0})\,d t_{n } \cdot...\cdot d t_{1}\leq
N\Big(\int_{\bR^{d}}|Df|^{4n}\,dx\Big)^{1/(2n)},
\end{equation}
where $N$ depends only on $d,\delta,p_{0},\rho_{0},n,t_{0}$
and $T_{t,s}, Q_{...}$ are taken from 
Section~\ref{section 7.3.1}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:projectFrob of arXiv:2411.08295, 'Improving the convergence of Markov chains via permutations and projections'] Let $M \in \mathcal{M}$, $Q \in \mathcal{I}(\pi) \cap \mathcal{L}$ and $N \in \mathcal{M}(\pi,Q)$. We have
	\begin{align*}
		\left\lVertM - N\right\rVert_F^2 = \norm{M - \overline{M}(Q)}_F^2 + \norm{\overline{M}(Q) - N}_F^2.
	\end{align*}
	In particular, this yields $\overline{M}(Q)$ is the unique projection of $M$ onto $\mathcal{M}(\pi,Q)$ under the squared-Frobenius norm. (Proof in the paper; no proof environment follows the statement in the TeX.)

