[Lemma lem:uniformestimateofXY of arXiv:2604.22510, 'Asymptotics of Multi-Scale McKean--Vlasov Diffusions with Super-Linear Kernels: a Lifted S'] $(i)$ For some $p\geq 2$, we have
		\begin{align}
			&\sup_{\varepsilon,\delta\in(0,1)}\mathbb{E}\Big[\sup_{t\in [0, T]}|X_{t}^{\varepsilon}|^{p}\Big]\lesssim_{p,T}(1+\mathbb{E}|\xi|^p+\mathbb{E}|\zeta|^{\frac{pq}{2}})\,, \\
			&\sup_{\varepsilon,\delta\in(0,1)}\sup_{t\geq 0}\mathbb{E}|Y_{t}^{\varepsilon}|^{p}\lesssim_{p}(1+\mathbb{E}|\zeta|^p).
		\end{align}

		$(ii)$ For any $T>0$, $0\leq t< t+h\leq T$ and $\varepsilon,\delta\in(0,1)$, we have
		\begin{align}
			\mathbb{E}|X^{\varepsilon}_{t+h}-X^{\varepsilon}_{t}|^2\lesssim_T(1+\mathbb{E}|\xi|^{\kappa}+\mathbb{E}|\zeta|^{\frac{\kappa q}{2}})h^2+(1+\mathbb{E}|\xi|^{2}+\mathbb{E}|\zeta|^{q})\varepsilon h.
		\end{align}

[Lemma lem:boosted small of arXiv:2606.24465, 'History estimation in random recursive trees:\\Pointwise approach via iterated Jordan cent'] There exists a constant $C>0$ such that for any $v\in [n]$ and for any $t \geq 1$, the random variable $\phi_n^{{\scriptscriptstyle{({2}})}}(v)$ satisfies 
    \begin{equation}
        \mathbb{P} \left( \phi_n^{{\scriptscriptstyle{({2}})}}(v) \leq \left( \frac{n}{t v} \right)^2 \right) \leq C \frac{1+\log t}{t^2},
    \end{equation}
    Furthermore, for every $\varepsilon > 0$, there exists a constant $c>0$ so that for any $n\geq 3$, $v\in [n/4]$ and $t\in\big(\sqrt{2},\tfrac{n}{v \sqrt{3}} \wedge (n/v)^{1-\varepsilon}\big)$,
    \begin{equation}
        \mathbb{P} \left( \phi_n^{{\scriptscriptstyle{({2}})}}(v)
    \leq
    \left( \frac{n}{t v} \right)^2 \right) \geq c \frac{\log t}{t^2}.
    \end{equation}
    Moreover, there exists a constant $c^\prime>0$ so that for any $n\geq 3$, $v\in [n/4]$ and $t\in\big(1, \frac{1}{\sqrt{3}} (n/v) \big)$,
    \begin{equation}
        \mathbb{P} \left( \phi_n^{{\scriptscriptstyle{({2}})}}(v)
    \leq
    \left( \frac{n}{t v} \right)^2 \right) \geq c \frac{1}{t^2}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 13 (McLeish, 1974) of arXiv:2609.00292, 'Extinction, Survival and Fluctuations for the Spatial Maki--Thompson Model on Infinite Gra'] Let $\{Z_{n,j}:n\ge1,\ 1\le j\le b_{n}\}$ be a martingale-difference
    array with respect to filtrations $(\mathcal{H}_{n,j})_{0\le j\le b_n}$.
    Assume that
    \begin{enumerate}
        \item $\sup_{n\ge1}\mathbb{E}\left[ \max_{1\le j\le b_n}|Z_{n,j}|^{2}
                      \right ] <\infty;$

        \item $\max_{1\le j\le b_n}|Z_{n,j}| \xrightarrow[n\to\infty]{\mathbb{P}}
                  0;$

        \item $\sum_{j=1}^{b_n}Z_{n,j}^{2}\xrightarrow[n\to\infty]{\mathbb{P}}
                  1.$
    \end{enumerate}
    Then
    \[
        \sum_{j=1}^{b_n}Z_{n,j}\xrightarrow[n\to\infty]{d}\mathcal{N}(0,1).
    \] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary thm:Jacobi-inverse of arXiv:2608.30904, 'Entire monotone solutions of the anisotropic Allen--Cahn equation in dimension 5'] For any $\gamma\in(\mu,1-\mu)$ and $k\ge0$,
\begin{equation}
 J_\Gamma:
 C^{k+2,\alpha}_\gamma
 \longrightarrow
 C^{k,\alpha}_{\gamma+2}
\end{equation}
is an isomorphism on axis-smooth invariant functions, and
\begin{equation}
 \|f\|_{C^{k+2,\alpha}_\gamma}
 \le C_k\|J_\Gamma f\|_{C^{k,\alpha}_{\gamma+2}}.
\end{equation}

[Theorem 2 of arXiv:2604.15152, 'The Multinomial Allocation Model and the Random Box Load'] For $0\le r,t\le n$ and $r\ne t$,  the following three approximation formulas hold
\begin{align}
\rE[\hat q_r]&=\rE[p_{r}(\xi)]+(2n)^{-1}\rE[p_{r}(\xi)(r-(\xi-r)^2)]+n^{-2}R_1(n,r), \\
\rV[\hat q_r]&=n^{-1}\alpha\rE[p_{r}(\xi)(1-p_{r}(\xi))]-n^{-1}(\rE[p_{r}(\xi)(\xi-r)])^2+n^{-2}(R_2(n,r,r)+\alpha R_1(n,r)), \\
\rC[\hat q_r,\hat q_t]&=-n^{-1}\alpha \rE[p_{r}(\xi)p_{t}(\xi)]-n^{-1}\rE[p_{r}(\xi)(\xi-r)]\,\rE[p_{t}(\xi)(\xi-t)]+n^{-2}R_2(n,r,t), 
\end{align}
where provided  $q_1\le1/4$, 
\begin{align}
- (r!)^{-1} \beta^r(r^32^{r-1}+4) &\le R_1(n,r) \le (r!)^{-1}\beta^rr^2(2r^2+ 4\beta^2),  \\

- (r!t!)^{-1}\beta^{2u}L_2(u,\beta) &\le R_2(n,r,t) \le (r!t!)^{-1}\beta^{2u} K_2(u,\beta), 
\end{align}
with $u=\max(r,t)$ and
\begin{align*}
L_2(r,\beta)&=12+2\beta+5(r^3+\beta)2^{r}+\beta^2(r^2+1),\\
K_2(r,\beta)&=8+12r^3 2^{r}+4\beta r+  \beta^2 2^{2r+6} r^2.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 14 of arXiv:2608.02319, 'Averaging Principle for Ordinary Differential Equations in a Multiscale Random Environment'] For all $n,k\geq1$, $0<S<T$, $x\in E$ and $y\in\mathbb R^d$ we set
\begin{align*}
\phi_{S,T}^{n,k}(y,x)=\mathbf E_{x}\big[f_1(\mathbf Z_S^{n,y})\,f_2(\mathbf Z_T^{n,y})\mathbf 1_{\{\tau_{k-1}^n<S<T\leq\tau_k^n\}}\big].
\end{align*}
Let $L>0$, then for all $n,k\geq1$, $T>0$ there exist $M_T^k>0$ such that for all $z,y\in\mathbb R^d$ and $x\in E$
\begin{align*}
\lvert\phi_{S,T}^{n,k}(y,x)-\phi_{S,T}^{n,k}(z,x)\rvert&\leq2\,\|f_1\|_\infty\,\|f_2\|_\infty\,\big(\mathbf P_x(S\leq\tau_k^n,L_S^n>L)+\mathbf P_x(T\leq\tau_k^n,L_T^n>L)\big)\\
&+\lvert y-z\rvert\,\big(\|f_1'\|_\infty\,\|f_2\|_\infty\,e^{SL}+\|f_1\|_\infty\,\|f_2'\|_\infty\,e^{TL}\big),
\end{align*}
where for all $t>0$ and $n\geq1$
\begin{align*}
L_t^n:=\sup_{s\in[0,t]}L_{\mathbf I_s^n}.
\end{align*}

