        e_{\orange{j}}e_{\orange{i}}
    \right)
    =
    \left(
        e_{\orange{i}}e_{\orange{j}}
        -
        e_{\orange{j}}e_{\orange{i}}
    \right)\boxtimes 1
    +
    1\boxtimes
    \left(
        e_{\orange{i}}e_{\orange{j}}
        -
        e_{\orange{j}}e_{\orange{i}}
    \right).
\end{equation*}
