[Theorem thm:metastable-mixing-rate of arXiv:2604.20008, 'Mixing times of Langevin dynamics for \\ spiked matrix models'] Suppose $\beta = \frac{\alpha}{\theta}$ with $\alpha >1$ and $\theta > \theta_{0,L}(\alpha)$. Then  
    \begin{align*}
       \lim_{N \to \infty} \frac{1}{N} \log t_{\mathsf{mix}} = \Delta_{\alpha,\theta}\,, 
    \end{align*}
    where 
    \begin{align*}
        \Delta_{\alpha,\theta} := \lim_{\varepsilon\to 0} \lim_{N\to\infty} -\frac{1}{N} \log \pi_{\beta} (|m|\le \varepsilon) \, .
    \end{align*}
    This limit exists $\mathbb P_M$-almost surely, and its value is given explicitly by 
    \begin{align}
        \Delta_{\alpha,\theta} : = \begin{cases}
            \frac{\alpha}{2} - \frac{(\alpha - 1)^2}{4\theta^2} - \frac{1}{2} \log \alpha - \frac{1}{2} & 1 < \alpha \leq \theta \\ 
            \frac{\alpha}{2}(1-\frac{1}{\theta})^2  - \frac{1}{2}\log \theta - \frac{1}{4\theta^2} + \frac{1}{4} & \alpha >\theta
        \end{cases}\,.
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:correlation_inductivestep of arXiv:2608.05089, 'Correlation decay in area-tilted line ensembles'] For all large enough $M$ in the above definitions, there exist constants $\lambda_0 > 1$
and $q > 0$ such that the following holds for all $\lambda \geqslant \lambda_0$.
For any independent $\lambda$-tilted line ensembles $\mathbf{X}$ and $\mathbf{Y}$, we have the following for all
$\tau \in \mathcal{T}_b$ and $\sigma \in [b]$ {almost surely}:
\begin{equation}
    \mathbb{P} \mleft[
        \mathsf{Reverse}_{\tau\sigma}(\mathbf{X},\mathbf{Y})
        \;\middle|\;
        \mathsf{Reverse}_\tau(\mathbf{X},\mathbf{Y}), \;
        \mathcal{E}^{|\tau|+2,\infty}_{I_{\tau\sigma}}(\mathbf{X}), \;
        \mathcal{E}^{|\tau|+2,\infty}_{I_{\tau\sigma}}(\mathbf{Y})
    \mright] \geqslant q.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:7 of arXiv:2410.23250, 'Strict inequalities for arm exponents in planar percolation'] For every $\delta\in(0,1/1000)$ there exists $C(\delta)\in (0,\infty)$  such that
  \begin{equation}
       \forall k\ge \frac1\delta\qquad \mathbb P(\mathcal A_k\setminus\mathcal B^\delta_k)\le C(\delta)\cdot \phi_k^{\mathrm{sep}}.
  \end{equation}

