[Theorem 1 of arXiv:2605.23461, 'An almost sure invariance principle for the Takagi--van der Waerden class functions'] Suppose that \eqref{Assump2:A_n_to_infinite} and \eqref{Assump2:last_term} hold. Then, there exists a probability space $(\onetorus \times [0,1), \Borelsigma(\onetorus)\otimes \Borelsigma([0,1)), \nu)$ on which a random variable $U$ uniformly distributed over $\onetorus$ and a standard Brownian motion $\{B(t)\colon t\ge 0\}$ are defined such that
  \begin{equation}
    f_{r,a}(U+h) - f_{r,a}(U) = h\cdot B\bigl(V_{m(h)}\bigr) + o\bigl(h\cdot V_{m(h)}^{\frac{1}{2}-\lambda}\bigr) \quad \text{as $h\to 0$, $\nu$-a.s.,}
  \end{equation}
  for each $\lambda <\delta/32$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:Evv of arXiv:2604.20094, 'Persistence and local extinction for superprocesses in random environments'] Suppose $f\in C_c^+  ({\mathbb R}^d) $
  	and $v$ is the unique solution to (equation eq:PAM of the paper).  For each $(t, x, y)\in (0, \infty)\times {\mathbb R}^d \times {\mathbb R}^d$,
  	\begin{align}
  			{\mathbf E}   \left[v(t,x)v(t,y)\right]
  			= E_{(x,y)} \left[ \exp\left(\int_0^t {\mathcal C} (B_s, B'_s)ds\right) (f\otimes f)(B_t, B'_t)\right].
	\end{align}

[Proposition 5 (Positive homogeneity) of arXiv:2609.02595, 'Minimal Radial Sub-Gamma Envelopes for Infinitely Divisible Random Vectors'] For every \(a\geq0\) and \(t\in\R^d\),
\begin{equation}
 C_X(at)=aC_X(t).
\end{equation}

[Lemma 7 of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] Assume the same notation as in the paragraph of~\eqref{eqn::multitime_aux1}-\eqref{eqn::multitime_driving_annulus}.
The Brownian loop measure
\begin{equation}
	\blm_{r,\bs{t}}:=\blm \left(\A_r;\gamma_{[0,t_1]}^{1},\ldots,\gamma_{[0,t_n]}^{n} \right)
\end{equation} 
solves the following differential equations: for all $j\in\{1, \ldots, n\}$, 
\begin{equation} 
	\partial_{t_j} \blm_{r,\bs{t}} = -\frac{1}{3} \LS \mathfrak{\covmap}_{\bs{t},j} (\zeta_{t_j}^j) +  \mathfrak{\covmap}_{\bs{t},j} (\zeta_{t_j}^j)^2 \left( \LE (\Mod(\A_r \setminus \bs{\gamma}_{[\bs{0},\bs{t}]})) +\frac{1}{\Mod(\A_r \setminus \bs{\gamma}_{[\bs{0},\bs{t}]})} \right) - \left( \LE (r-t_j) + \frac{1}{r-t_j} \right),
\end{equation}
where $\LE(t)$ is defined in~\eqref{eqn::Def_LE}.

