[Definition admissible of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp We say that a local function {\small$\mathfrak{q}:\R^{\Z}\to\R$} is \emph{admissible} if:

\begin{enumerate}
\item it has the form {\small$\mathfrak{q}=N^{-1+\k/2}\mathfrak{f}$} with {\small$\mathfrak{f}\in\mathrm{Jet}_{\k}^{\perp}$} for some {\small$\k\in\{0,1,2\}$};
\item {\color{black}{\small$\mathfrak{f}_{}[\bphi]$}} depends only on {\small$\bphi_{\w}$} for either {\small$\w\in\{1,\ldots,\mathfrak{l}\}$} or {\small$\w\in\{-\mathfrak{l},\ldots,0\}$} for some {\small$\mathfrak{l}=\mathrm{O}(1)$};
\item we have the deterministic local polynomial estimate below for some positive {\small$\mathrm{C}\lesssim1$}:

\begin{align}
|{\color{black}\mathfrak{f}}[{\boldsymbol{\phi}}]|&\lesssim 1+ \sum_{|\w|\lesssim1}|\bphi_{\w}|^{\mathrm{C}}.
\end{align}

\end{enumerate}

[Lemma lemma_Gl of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For any $d\ge 3$, there exist $C,c>0$ such that for any $D\subset \widetilde{\mathbb{Z}}^d$, $N\ge 1$, $A\subset \widetilde{B}(cN)$ and $l\ge 1$, 	\begin{equation}
		\mathbb{P}\big(\mathsf{G}_{\ge l}^{D}(\partial B(N),A)   \big) \le \big[CN^{2-d}\mathrm{cap}(A)\big]^{l}. 
	\end{equation}

[Lemma lemma-step2 of arXiv:2607.08187, 'Asymptotic behaviours of critical branching random walk in $\mathbb{R}^d$'] For each $\delta\in (0,1)$, it holds that 
	\begin{equation}
		\limsup_{x\to +\infty}\sup_{\mathbf{z} \in \overline{D}_\delta}\sup_{\mathbf{y},\mathbf{y}+\mathbf{z}\in  \overline{D}_1}\frac{1}{x^2}  \mathbb{E}_{x\mathbf{y}}\left(|\tau_x-\tau_{x}^\mathbf{z} |\right) \leq  \frac{9\delta}{\eta^2}.
	\end{equation}

