body:
[Thm scp of arXiv:2509.10984, 'Weak Existence and Uniqueness for Super-Brownian Motion with Irregular Drift'] Suppose that almost surely, $X_0 = f \in \mathcal{C}_c^+(\mathbb{R})$. Let $(X_t)_{t\geq 0}$ be the solution to (equation eq:SPDE1 of the paper) with $h$ given by 
\begin{equation}
	h(x) = \int_0^\infty(1-\ee^{-\lambda x})\nu^1(d\lambda) + b_1\mathbbm{1}_{x>0} , \quad x\in \mathbb{R}_+,
\end{equation}
 with $b_1 \in \mathbb{R}$ such that $h(0)\geq 0$. Then there exists $T_0>0$ such that for all $t \in [0,T_0]$ we have
\begin{equation}
	\mathbb{P}(\mathrm{Leb}(\{ x\in \mathbb{R} \colon X_t(x) > 0\}) < \infty) = 1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition EM:d2 of arXiv:2604.16206, 'Extrapolation of max--stable random fields with Fr\'echet marginals'] Let $(X_1,X_2)$ be a simple max-stable random vector. Then for $\sigma_1,\sigma_2>0$ we have
    \begin{equation}
    \mathcal{E}_H (\sigma_1 X_1, \sigma_2 X_2)=\frac{1}{1+\sigma_1}+\frac{1}{1+\sigma_2}-\frac{2}{1+l_{(X_1,X_2)}((\sigma_1,\sigma_2))}.
    \end{equation}

[Lemma 12 (Adapted linear realization of the arguments in the Hermite polynomials.) of arXiv:2607.14361, 'NeuralChaos: Optimal Adapted Approximation of Square Integrable Predictable Processes'] Let $T>0$ be a (fixed) time-horizon, $I_{\rm H}, J_{\rm H} \in \mathbb{N}$, and $i_{0} \in \mathbb{N}$ such that $J_{\rm H}\leq 2^{i_0}-1$. In addition, let $\Lambda_{I_{\rm H}, J_{\rm H}, i_0}\eqdef\{(i,k)\,:\,i_0 \leq i \leq i_0 + I_{\rm H},\,\,0 \leq k \leq J_{\rm H}\}$; in particular, $\# \Lambda_{I_{\rm H}, J_{\rm H}, i_0}=(I_{\rm H}+1)(J_{\rm H}+1)$ (cf.~Lemma \ref{lem:emulation}). Let $0<s_0<s_1<\ldots<s_{n_{\rm grid}} \leq T$ be the ordered dyadic sampling grid of Lemma \ref{lem:emulation}, where $n_{\rm grid}=(J_{\rm H}+1)(I_{\rm H}+2)$. Define the Brownian sample matrix  $\mathbf{W}^{I_{\rm H}, J_{\rm H}, i_0} \eqdef [W_{s_0}^{\top},\ldots,W_{n_{\rm grid}}^{\top}]^{\top} \in \mathbb{R}^{(n_{\rm grid}+1)\times D}$, and, for every $(i,k)\in\Lambda_{I_{\rm H}, J_{\rm H}, i_0}$ and $r \in [D]_{+}$
\begin{equation}
 Z_{i,k}^r= \tfrac{2^{i/2}}{\sqrt{T}} \,W^r_{\frac{Tk}{2^i}}
    -\tfrac{2^{i/2+1}}{\sqrt{T}}\,W^r_{\frac{T(1+2k)}{2^{i+1}}}
    +\tfrac{2^{i/2}}{\sqrt{T}}\,W^r_{\frac{T(k+1)}{2^i}}.
\end{equation}
Enumerate $\Lambda_{I_{\mathrm H},J_{\mathrm H},i_0} =
\{(i_\ell,k_\ell):\ell\in [R_{\mathrm H}]_{+}\}$ so that the terminal information times $\theta_\ell\eqdef \frac{(k_\ell+1)T}{2^{i_\ell}}$ are non-decreasing, i.e., $\theta_1\le\theta_2\le\cdots\le\theta_{R_{\mathrm H}}$, with arbitrary ordering among ties. If  $\mathbf{Z}^{I_{\mathrm H},J_{\mathrm H},i_0}\eqdef [Z_{i_1,k_1}^{\top},Z_{i_2,k_2}^{\top},\ldots,Z_{i_{R_{\mathrm H}},k_{R_{\mathrm H}}}^{\top}]^{\top}$, then there exists a deterministic matrix $A^{I_{\mathrm H},J_{\mathrm H},i_0} \in \mathbb R^{R_{\mathrm H}\times(n_{\mathrm{grid}}+1)}$ such that $A^{I_{\mathrm H},J_{\mathrm H},i_0}
W^{I_{\mathrm H},J_{\mathrm H},i_0}=
Z^{I_{\mathrm H},J_{\mathrm H},i_0}$. Moreover, $\left\|A^{I_{\mathrm H},J_{\mathrm H},i_0}\right\|_0 = 3R_{\mathrm H} = 3(I_{\mathrm H}+1)(J_{\mathrm H}+1)$.

[Definition def:cut of arXiv:2606.05830, '{ Biased Random Walk on $\mathbb Z_+$ with Traps of Linearly Increasing Depth}\footnote{Su'] Let $(X_n)_{n\ge0}$ be a Markov chain on a countable state space. For $n \ge 1$, if
  \begin{align*}
    \{X_0,\dots,X_{n-1}\}\cap \{X_n,X_{n+1},\dots\}=\emptyset,
  \end{align*}
  then $n$ is called a \emph{cut time} and $X_n$ is called a \emph{cutpoint} of the chain.

[Corollary cor: limit of hazard rate term of arXiv:2608.23756, 'Measure-valued fluid limits for partial service queues\\with correlated patience and servi'] The following property holds with probability one:
	\begin{equation}

		\bar \boldsymbol{D}_t(\varphi) = \int_0^t \angled{\varphi_s\left[\bar r\left(\bar\boldsymbol{\mu}_s\right) h_g^x + h_g^y\right]}{\bar\boldsymbol{\mu}_s}ds
	\end{equation}
	for all $t \geq 0$ and $\varphi \in C_b(\mathbbm{R}_+^3)$.

[Proposition prop_2 of arXiv:2412.03774, '{ Refining Concentration for \\Gaussian Quadratic Chaos with\\ Applications in Sonar and C'] Let $A$ be positive-semidefinite and 
\begin{eqnarray}

\alpha=\|A\|,\,\,\,\,\,\beta=\|A\|_2^2.
\end{eqnarray}
For $\frac{2}{3}<a<1$, let 
\begin{eqnarray}

b=\frac{3a-2}{a(2a-1)},\,\,\,\,\,c=\frac{3a-2}{2(1-a)^2}.
\end{eqnarray}
 Then 
\begin{eqnarray}

\Pr(\boldsymbol{\Delta}>t)\leq e^{\Lambda(t, a)},
\end{eqnarray}
where 
\begin{eqnarray}

\Lambda(t, a)=\left\{\begin{array}{cc}
    -\frac{t}{2a\alpha}+\frac{\beta}{2a^2\alpha^2}\Big(\sqrt{1+\frac{2a\alpha t}{\beta}}-1\Big)  & \frac{\alpha t}{\beta}\leq c   \\
    -\frac{bt}{2\alpha}+\frac{b^2\beta}{4(1-ab)\alpha^2}  &  \frac{\alpha t}{\beta}> c 
\end{array}\right..
\end{eqnarray}

[Proposition 47 of arXiv:2606.15425, 'Well-posedness of stochastic parabolic equations with gradient nonlinearities and applicat'] Again, assume the setting of the preceding propositions. As $h \to 0$, we obtain the uniform the convergence  
\begin{equation}
\norm{z_{t+\cdot}}_{L^\infty(\Omega;(\mathbb W_1 \cap \mathbb W_\delta)(h))} \to 0
\end{equation}
for any fixed $t \geq 0$, and in particular, 
\begin{equation} 
\norm{z}_{L^\infty(\Omega;(\mathbb W_1 \cap \mathbb W_\delta)(h))} \to 0,
\end{equation}
with the obvious truncation at time $\tau$ if $h, t+h > \tau$.

