[Definition 102 (Modified versions of the derivatives of $\mytr_{\gtorus} \upchi$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] The \emph{fully modified quantity} $\fullymodquant{\tander^N}$ is defined to be: 
	\begin{subequations}
		\begin{align}
			\fullymodquant{\tander^N} & \eqdef \upmu \tander^N \mytr_{\gtorus} \upchi + \tander^N \mathfrak{X},
			 \\
			\mathfrak{X} & \eqdef - \vec{G}_{\Lunit \Lunit} \diamond \muX \wavearray - \frac{1}{2} \upmu \mytr_{\gtorus} \angG \diamond \Lunit \wavearray - \frac{1}{2} \upmu \vec{G}_{\Lunit \Lunit} \diamond \Lunit \wavearray + \upmu \angG_{\Lunit}^{\#} \diamond \cdot \angrmD \wavearray. 
		\end{align}
	\end{subequations}
	The \emph{partially modified quantity} $\partialmodquant{\tander^N}$ is defined to be:
	\begin{subequations}
		\begin{align}
			\partialmodquant{\tander^N} 
			& 
			\eqdef 
			\tander^N \mytr_{\gtorus} \upchi 
			+ 
			\partialmodquantinhom{\tander^N}, 

			\\
			\partialmodquantinhom{\tander^N} 
			& \eqdef 
			- 
			\frac{1}{2} \mytr_{\gtorus} \angG \diamond \Lunit \tander^N \wavearray 
			+ 
			\angG_{\Lunit}^{\#} \diamond \cdot \angrmD \tander^N \wavearray. 

		\end{align}
	\end{subequations}
	The ``$0^{\text{th}}$-order'' version of \eqref{E:PARTIALMODIFIEDQUANTITYINHOM} is simply:
	\begin{align} 
		\widetilde{\mathfrak{X}} 
		& \eqdef - \frac{1}{2} \mytr_{\gtorus} \angG \diamond \Lunit \wavearray + \angG_{\Lunit}^{\#} \diamond \cdot \angrmD \wavearray.
	\end{align}

[Lemma 28 (Moment Formulas) of arXiv:2608.18834, 'The Parabolic Anderson Model's Total Mass at Small Times: Geometry, Fluctuations, and Reno'] Let $\ka,\th>0$.
Let us denote
\begin{align}

\msf J(\th)=
\begin{cases}
\displaystyle\int_{-1}^1(1-|v|)\int_{\mbb R^2}\mr e^{-\th(|a|+|b|)}\mr e^{\mr iva-|v|\cdot|b|}|a|^{1-2H_0}|b|^{d-H-1}\d a\dd b\dd v,&H_0<1,
\vspace{5pt}\\
\displaystyle\int_{-1}^1(1-|v|)\int_{\mbb R}\mr e^{-\th|b|}\mr e^{-|v|\cdot|b|}|b|^{d-H-1}\d b\dd v,&H_0=1,
\end{cases}
\end{align}
and the constant
\begin{align}

\mf a=
\begin{cases}
\displaystyle\frac{1}{2^{H+3}\Ga(d-H)\Ga(1-H_0)}\prod_{j=0}^d\frac{\Ga(2H_j+1)}{\Ga(H_j)}&H_0<1,
\vspace{5pt}\\
\displaystyle\frac{1}{2^{H+2}\Ga(d-H)}\prod_{j=1}^d\frac{\Ga(2H_j+1)}{\Ga(H_j)}&H_0=1.
\end{cases}
\end{align}
In all cases,
\begin{align}

\mbf E\big[\tfrac{\ka^2}{2}\be^\th_1(B)\big]=\ka^2\mf a\,\msf J(\th).
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lem 4.7 of arXiv:2411.01847, 'Well-Posedness of Stochastic Chemotaxis System'] For all $m \in \mathbb{N}$ and $T \geq 0$, we have
    $$u \in L^\infty([0, T \wedge \tau_m]; C (\bar{\mathcal{O}})) \cap L^2([0, T \wedge \tau_m]; W^{1,2}(\mathcal{O}))$$ almost surely,

    \begin{align}
        \lim_{n \rightarrow \infty} \mathbb{E} \left( \int_0^{T \wedge \tau_m} \| \nabla U_n(t) - \nabla u(t) \|_2^2dt \right) = 0,
    \end{align}

    and
    \begin{align}
        \lim_{n \rightarrow \infty} \mathbb{E} \left( \sup_{t \in [0, T \wedge \tau_m]} \| U_n(t) - u(t) \|_\infty \right) = 0.
    \end{align}

