[Corollary loc:concentreExpo3 of arXiv:2603.00773, 'Long-time $L^p$ Wasserstein contraction for diffusion processes without global dissipativi'] Under the settings of Proposition~(prop:concentration of the paper), for any $R,t>0$ and Lipschitz function $\varphi$ with Lipschit constant $L_\varphi$,
  \begin{equation}

\sup_{x\in \mathcal B(0,R)} \mathbb E_{x} \left( \exp \left(  \int_0^t   \varphi(X_s)   \text{d} s  \right)\right) \leqslant  A e^{r t}  \,,
 \end{equation}
 with
 \[A= \exp\left(      \frac{ L_\varphi C}{\lambda} \left( R + \int_{\mathbb R^d} |y| \mu_\infty(\text{d} y)\right)  \right)\,, \qquad		r =  \mu_\infty(\varphi) +   \frac{  |\sigma|^2 C^2  L_\varphi^2 }{\lambda^2} \,.\]

[Lemma Lemma_off_diagonals of arXiv:2506.17168, '{\bf Scaling limits for sample autocovariance operators of Hilbert space-valued linear pro'] Let $C_N$ be as in (equation eq:CN-vector of the paper). Consider a linear combination of an off-diagonal tuple
\begin{equation*}
\quad Q_{2}(C_{N}) \in L^2(\mathbb{Y}^2:\mathbb R^{(H+1)}), \quad Q_{2}(C_{N})(r,s) \doteq \sum_{j_{1} \neq j_{2}} C_{N}(j_{1},j_{2},r,s)\varepsilon_{j_{1}}(r) \varepsilon_{j_{2}}(s) .
\end{equation*}
Assume that there exists a kernel $f \in \mathcal{H}^2$, such that, denoting $f^\sigma(r,s,x,y) \doteq f(r,s,x,y) \sigma(r) \sigma(s)$ and $\bar f \doteq (f,\dots, f) \in L^{2}(\mathbb R^{2}: L^2(\mathbb{Y}^2:\mathbb R^{(H+1)}))$, the functions defined in (equation eq:def-cntilde of the paper) satisfy, as $N \to \infty$,
\begin{equation} 
\| \widetilde{C}_{N}^\sigma-\bar f^\sigma \|_{L^{2}(\mathbb R^{2}: L^2(\mathbb{Y}^2:\mathbb R^{(H+1)}))} \to 0.
\end{equation}
Then,
\begin{equation*}
    Q_{2}(C_{N}) \overset{\operatorname{d}}{\to} \mathcal{I}_{2}(\bar f) \doteq \begin{pmatrix}
        \mathcal{I}_{2}^\sigma(f) \\
        \vdots \\
        \mathcal{I}_{2}^\sigma(f)
    \end{pmatrix} , \quad \text{weakly in } L^2(\mathbb{Y}^2:\mathbb R^{(H+1)}),
\end{equation*}
where each coordinate of the limit is understood in the sense of Definition (def:double-in-banach of the paper).

