body:
[Proposition L1uniq of arXiv:2605.13479, '\LARGE Dean-Kawasaki Equation with Biot-Savart and Keller-Segel Interactions: Existence an'] Given interaction $\mathcal{V}[\cdot]$ as in (equation ker-V of the paper) under the condition (equation eq:small-KS of the paper), we let $\rho^1_0,\rho^2_0 \in \mathrm{Ent}(\mathbb{T}^2)$. If $\rho^1$ and $\rho^2$ are renormalized kinetic solutions of  (equation control-1 of the paper) in the sense of Definition (ske-kinetic of the paper) with control $g$ and initial condition initial  $\rho^1_0$ and $\rho^2_0$ respectively, and further 
\begin{align}
\rho^2 \in \mathcal{C}_0,
\end{align}
then we have
\begin{equation}
\|\rho^1-\rho^2\|_{L^{\infty}_{[0,T]}L^1_{\mathbb{T}^2}}\lesssim \|\rho_0^1-\rho_0^2\|_{L^1_{\mathbb{T}^2}}, 
\end{equation}
for some implicit constant which depends on $\rho^2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 6 (Unequal-shape asymptotic relative efficiency) of arXiv:2609.00774, 'Semi-Supervised Classification with Informative Missing Labels in Weibull Mixture Models'] Assume the conditions of \Cref{thm:risk-hessian}. Under an unequal-shape two-component Weibull mixture, suppose the Bayes' rule has two simple decision boundaries $0<y_1<y_2$. For the $\mathrm{full}$ estimator relative to the estimator based on the completely classified sample,
\begin{equation}
\ARE_{\mathrm{full}:\mathrm{CC}}^{\mathrm{U}}
=
\frac{
\displaystyle
\sum_{j=1}^{2}
\omega_j\,
g_U(y_j)^\top
\J_{\mathrm{CC},U}^{-1}
g_U(y_j)
}{
\displaystyle
\sum_{j=1}^{2}
\omega_j\,
g_U(y_j)^\top
\J_{\mathrm{full},U}^{-1}
g_U(y_j)
}.

\end{equation}

[Prop horizontal-splitting-beta-uniform of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] There exists $C,c_1,c_2,s_0>0$ (independent of $\beta$) such that for all $\beta>\beta_0$ the following holds. If $R$ is an $\ell \times e^{ - \beta} \bar \alpha \sqrt{\ell}$ rectangle with $\sqrt{C \log \ell} \le\bar \alpha \le (1/ s)\sqrt{\ell}$, and $\Delta$ has length $s \bar \alpha^2$ for $s \ge s_0$, we have 
    \begin{align*}
        \pi^{(-,+,\Delta)}(\mathcal V^c) \le \ell^{c_1} e^{ - c_2 \bar\alpha^2}\,.
    \end{align*}

[Theorem 14 of arXiv:2606.17501, 'Critical spectral behavior and large deviations for geometric $\alpha$-stable processes'] Let $G_{\beta}$ be the $\beta$-potential operator, that is,
\begin{align}

  G_{\beta} \mu(x)
  &:= \int_{\mathbb{R}^{d}}^{ } G_{\beta}(x,y) \mu(dy)
    := \int_{\mathbb{R}^{d}}^{ } \left( \int_0^{ \infty} e^{-\beta t} p_{t}(x,y) dt\right) \mu(dy).
\end{align}
  If $\mu \in \mathcal{K}$, then for $\beta \ge 0$, 
  \begin{align}

    \int_{\mathbb{R}^{d}}^{ } u(x)^{2} \mu(dx) \le \left\| G_{\beta} \mu \right\|_{\infty}
    \mathcal{E}_{\beta}^{\alpha}(u,u),\quad u \in \mathcal{F}^{\alpha}\
    (u \in \mathcal{F}_{e}^{\alpha}\ \text{if $\beta = 0$}),
  \end{align}
  where $\mathcal{E}_{\beta}^{\alpha}(u,u)
  = \mathcal{E}^{\alpha}(u,u) + \beta \int_{\mathbb{R}^{d}}^{ } u(x)^{2} dx$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 4 of arXiv:2606.18877, 'Ergodic Properties of Non-Linear Density-Dependent Perturbations of the Ornstein--Uhlenbec'] Under the same assumptions as in Lemma~\ref{lem:unifbound}, there exists a unique probability density \(\pi\) solving the stationary form of~\eqref{eq:NFPE}. Moreover, \(\pi\in C^1(\R^d)\) and satisfies 
\begin{equation}
\pi(x)=g^{-1}(-\Phi(x)+\mu),\quad x\in\mathbb{R}^{d}
\end{equation}
where 
\begin{eqnarray}
g(r)=\int_{1}^{r}\frac{1}{s\,\Xi(s)}\,ds,\quad r> 0,
\end{eqnarray}
and $\mu$ is the unique number in $\mathbb{R}$ such that 
\begin{equation}
\int_{\mathbb{R}^{d}}g^{-1}(-\Phi(x)+\mu)\,dx=1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 27 (Uniqueness of the nonzero vector invariant law) of arXiv:2608.15914, 'Absorption cutoff and stationary singularities for rounded Gaussian random dynamical syste'] Fix $A>0$ and $N\geq1$ for which $K_{A,N}$ admits a nonzero invariant law
  $\nu_{A,N}$ on $(0,1]$. Then $P_{A,N}$ has a unique invariant probability
  $\pi_{A,N}$ on $[-1,1]^N$ with $\pi_{A,N}(\{0\})=0$, namely
  \begin{equation}
    \pi_{A,N}=\nu_{A,N}J_{A,N}.
  \end{equation}

