[Lemma 26 (Weighted Volterra decomposition identity) of arXiv:2605.09706, 'A dyadic construction of a three-dimensional attractive point interaction Markov family'] Let \(s,t>0\), \(a,b\ge 0\), and \(\lambda>0\). Then
\begin{align}
\int_0^\infty e^{\lambda v}
\int_0^v
P_s(v+a-u)\,P_t(u+b)\,du\,dv
&=
\int_0^\infty e^{\lambda v}
\int_0^\infty
P_s(a+r)\,P_t(v+r+b)\,dr\,dv \nonumber \\
&+
\int_0^\infty e^{\lambda u}
\int_0^\infty
P_s(u+a+r)\,P_t(r+b)\,dr\,du \nonumber \\
&+
2\lambda
\int_0^\infty\int_0^\infty
e^{\lambda(u+v)}
\int_0^\infty
P_s(u+a+r)\,P_t(v+r+b)\,dr\,du\,dv. \nonumber
\end{align}

[Definition 5 (Convolution-induced Grassmann map) of arXiv:2609.03361, 'Grassmann--Pl\"ucker Parametrization of Convolutional Filter Subspaces:\ Regularity and Cl'] Define
\begin{equation}
  \Gamma_{\cC}:\Gr(q,\cK)\longrightarrow\Gr(q,H),
  \qquad U\longmapsto\cC(U).
\end{equation}

[Lemma lem: compare of arXiv:2411.07840, 'Central limit theorem for the focusing $Φ^4$-measure in the infinite volume limit'] Then there is a constant $c_0>0$ such that $u\in H^1(\mathbb{R})$ with $\|u\|_2\le D$:
\begin{equation}
H(u)\ge I(D)+c_0\inf_{x_0\in \mathbb{R}}\|u-Q(\cdot-x_0)\|_{H^1(\mathbb{R})}^2.
\end{equation}
There is a constant $c$ such that $u\in H^1(\mathbb{T}_L)$ with $\int u\,\mathrm{d}x =0$ and $\|u\|_2\le M$:
\begin{equation}
H_L(u)\ge E_0(M)+c_0\inf_{x_0\in \mathbb{T}_L} \|u-Q(\cdot-x_0)\|_{H^1(\mathbb{T}_L)}^2+e^{-cL^{\frac{1}{2}}}.
\end{equation}
\begin{proof}
Let $u\in H^1(\mathbb{T}_{L})$ be such that $\int_{\mathbb{T}_L} u\,\mathrm{d}x=0$, then there is a point $x^* \in [-\frac{L}{2},\frac{L}{2})$ such that $u(x_0)=0$. Define
\begin{equation}
v(x)=\begin{cases}
    0, & x< -L\\
    u(L+x^*+x), & -L\le x\le -x^*\\
    u(-L+x^*+x), & -x^* <x \le L\\
    0, & x>2L
    \end{cases}
\end{equation}
Then $v(x)\in H_1(\mathbb{R})$ and $p\ge 1$,
\begin{align*}
\|u\|_{L^p(\mathbb{T}_L)}&=\|v\|_{L^p(\mathbb{R})},\\
\|u\|_{H^1(\mathbb{T}_L)}&=\|v\|_{H^1(\mathbb{R})},
\end{align*}
so 
\begin{align*}
H_L(u)&\ge H(v)\\
&\ge  H(Q)+c_0\inf_{x_0\in \mathbb{R}} \|v-Q(\cdot-x_0)\|_{H^1(\mathbb{R})}^2\\
&\ge H(Q)+c_0\inf_{x_0\in \mathbb{R}}\|v-Q(x-x_0)\|_{L^2(\mathbb{R})}^2.
\end{align*}
Suppose $\mathrm{dist}(x_0,\pm L)\ge L^{\frac{1}{2}}$,
then
\begin{equation}
\|v-Q(\cdot-x_0)\|_{L^2(\mathbb{R})}^2\ge \int_{-\frac{L}{2}}^{\frac{L}{2}} |v-Q(\cdot-x_0)|^2\,\mathrm{d}x,
\end{equation}
where in the last line we $x-x_0$ is \emph{not} interpreted mod $L$.
Let $|x_0-\frac{L}{2}|<L^{\frac{1}{2}}$. In particular $x_0>0$ and if $-\frac{L}{2}\le x\le 0$, then
\[|x-x_0|\ge \frac{L}{2}-L^{\frac{1}{2}}>\frac{L}{4}.\]
So we have
\begin{equation}
\begin{split}
&\|v-Q(\cdot-x_0)\|_{L^2(\mathbb{R})}^2\\
=&\int_{-\infty}^{-\frac{L}{2}}|Q(x-x_0)|^2\,\mathrm{d}x+ \int_{-\frac{L}{2}}^0|v-Q(x-x_0)\|^2\,\mathrm{d}x\\
&+\int_0^{\frac{L}{2}}|v(x)-Q(x-x_0)|^2\,\mathrm{d}x+\int_{\frac{L}{2}}^\infty|Q(x-x_0)|^2\,\mathrm{d}x\\
\ge& \int_0^{\frac{L}{2}}|v(x)-Q(x-x_0)|^2\,\mathrm{d}x+\int_{\frac{L}{2}}^\infty|Q(x-x_0)|^2\,\mathrm{d}x\\
&+ \int_{-\frac{L}{2}}^0|v(x)|^2\,\mathrm{d}x+O(e^{-cL})
\end{split}
\end{equation}
For the second term, we have
\begin{align*}
\int_{\frac{L}{2}}^{\infty}|Q(x-x_0)|^2\,\mathrm{d}x&\ge \int_{\frac{L}{2}}^{\frac{L}{2}+x_0}|Q(x-x_0)|^2\,\mathrm{d}x\\
&=\int_{\frac{L}{2}-x_0}^{\frac{L}{2}}|Q(y)|^2\,\mathrm{d}y\\
&\ge  \int_{0}^{\frac{L}{2}}|Q(y)|^2\,\mathrm{d}y+O(e^{-cL})\\
&=\int_{-\frac{L}{2}}^{0}|(\tau_{x_0}Q)(x)|^2\,\mathrm{d}x+O(e^{-cL})
\end{align*}
So we have
\[\int_{\frac{L}{2}}^\infty|Q(x-x_0)|^2\,\mathrm{d}x\\
+ \int_{-\frac{L}{2}}^0|v(x)|^2\,\mathrm{d}x\ge \int_{-\frac{L}{2}}^0|v(x)-(\tau_{x_0}Q)(x)|^2\,\mathrm{d}x+O(e^{-cL}).\]
Since $-\frac{L}{2}\le x-x_0\le \frac{L}{2}$ for $x\in [0,\frac{L}{2}]$, we have
\[\int_0^{\frac{L}{2}}|v(x)-Q(x-x_0)|^2\,\mathrm{d}x=\int_0^{\frac{L}{2}}|v(x)-(\tau_{x_0}Q)(x)|^2\,\mathrm{d}x.\]
It follows that
\[\|v-Q(\cdot-x_0)\|_{L^2(\mathbb{R})}^2\ge \|u-\tau_{x_0-x^*}Q\|_{L^2([-L,L])}+O(e^{-cL}).\]
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 19 of arXiv:2606.15843, 'Long-time behaviour of DLRA for SDEs'] Suppose that Assumptions (H4), (H5), (H7) and (H8) hold. Moreover, for any $p\ge 2$, suppose $2L_{b,7}-(p-1)L_{\sigma,1}>1$ holds, where $L_{b,7}$ and $L_{\sigma,1}$ are in (H8) and (H3), respectively. Then, for all $t \ge 0$, it holds that 
    \begin{equation}
        \bb E[Y_t^{(\mu)}Y_t^{(\mu)\top}]\succeq \rrm e^{-\frac{t}{\varepsilon}}\bb E[Y_0^{(\mu)}Y_0^{(\mu)\top}]+\varepsilon\frac{L_{\sigma,3}}{2}(1-\frac{\big(\bb E[|Y_0^{(\mu)}|^p\big)^{2/p}}{1+M^{2/p}})(1-\rrm e^{-\frac{t}{\varepsilon}})I_r,
    \end{equation}
    where $\varepsilon=\frac{L_{\sigma,3}}{2L_{b,6}(1+M^{2/p})}$, and $M$ is defined in Eqn.~\eqref{eqn:M}.

