[Proposition prop:pr_pentagonal of arXiv:2606.23547, 'The location of the largest exponential spacing and Euler’s generalized pentagonal numbers'] For $r\geq1$,
\begin{equation}
p_r
=
r\sum_{\ell=0}^{\infty}\Biggl[
\frac{1}{r(\ell+1)}
+\sum_{m=1}^{\infty}(-1)^m
\left(
\frac{1}{r(\ell+1)+g_m^-}
+\frac{1}{r(\ell+1)+g_m^+}
\right)
\Biggr].
\end{equation}
Here, for each fixed $\ell$, the inner series with respect to $m$ is
evaluated first.

[Definition 8 of arXiv:2607.29534, 'Expected signatures via partial integration, coordinate change and symmetrization'] For $p\geq 1$, a weakly geometric $p$-rough path on $\mathbb{R}^d$ is a map \begin{equation*}
        \mathbf{X}=(1,\mathbb{X}^{(1)},\dots, \mathbb{X}^{(\lfloor p \rfloor)}): \Delta_{0,T}^2 \rightarrow G^{\lfloor p \rfloor}(\R^d),
    \end{equation*} with the following three properties \begin{enumerate}
        \item $\mathbf{X}$ is of finite $p$-variation, in the sense that $$\Vert \mathbf{X} \Vert_{p-var}:=\sup_{\mathcal{P}\in \mathcal{D}([0,T])}\max_{1\leq k \leq \lfloor p \rfloor}   \Big (\sum_{[u,v] \in \mathcal{P}} \Vert \mathbb{X}^{(k)}_{u,v} \Vert_{(\mathbb{R}^d)^{\otimes k}}^{p/k} \Big )^{k/p}<\infty.$$

        \item Chen's relation holds: $\mathbf{X}_{s,t} = \mathbf{X}_{s,u} \otimes \mathbf{X}_{u,t}$ for all $0 \leq s \leq u \leq t \leq T$.
        \item The shuffle-identity holds: $\langle w,\mathbf{X}_{s,t} \rangle\langle v,\mathbf{X}_{s,t} \rangle = \langle w\shuffle v,\mathbf{X}_{s,t} \rangle $ for all $(s,t)\in \Delta_{0,T}^{(2)}$ and $w,v \in \mathcal{W}$ with $|wv|\le \lfloor p \rfloor$.
    \end{enumerate}
    Finally, a weakly geometric rough path is called geometric, if it is the limit of a sequence $\pi_{\leq \lfloor p \rfloor}(\Sig{X^n})$, where $(X^n) \subset C^{1-var}$ with respect to the $p$ rough path norm $\Vert \cdot \Vert_{p-var}$. We denote by $\mathscr{C}^{p-var}_g([0,T|;\mathbb{R}^d)$ the space of weakly, resp. by $\mathscr{C}_{g}^{p-var,0}([0,T];\mathbb{R}^d)$ the space of geometric rough paths.

[Theorem 13 (Simultaneous realization of every separable support) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] Let $(S_s)_{s\ge1}$ be any countable family of separable real Hilbert
spaces.  There are linear isometries
\begin{equation}
 J_s:S_s\longrightarrow
 \cK_s^{\mathrm{sp}}
 \subset
 \bigl(L^2(\R)^{\odot s},s!\ip{\cdot}{\cdot}\bigr)_{\mathcal U}

\end{equation}
such that all non-total contractions between their ranges vanish.
The ranges have representatives which are smooth, collision-null, and
have proper contraction norms $O(N^{-1/2})$ on every finite-dimensional
part of the support.

