[Lemma lem:bulk-rem of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] There exists $C>0$ such that for every $\varepsilon > 0$, the following statements hold.
\begin{enumerate}
\item[(i)] For every $u \in \mathcal L$, 
\begin{equation}
\|{\rm rem}_\varepsilon(u)\|_{\mathcal L} \leq C \left(\| \Xi_\infty(W)\|_{\mathfrak S} + \|\Xi^\partial_\infty(\varphi_-,\varphi_+)\|_{\boldsymbol{
\mathcal B}}+ \|u\|_{\mathcal L}\right).
\end{equation}
\item[(ii)] For every $T \in (0,\infty]$ and $u \in \mathcal L$, 
\begin{equation}
\|Z_T({\rm rem}_\varepsilon(u))\|_{L^4} \leq \left(\|\Xi_\infty(W)\|_{\mathfrak S} + \|\Xi^\partial_\infty(\varphi_-,\varphi_+)\|_{\boldsymbol{
\mathcal B}} + \|Z_T(u)\|_{L^4}\right).
\end{equation}
\item[(iii)] For every $\varepsilon > 0$, there exists $c_\varepsilon > 0$ such that, for every $u \in \mathcal L$,
\begin{equation}
	\|\ell^{\varphi_-,\varphi_+}_\infty({\rm rem}_\varepsilon(u))\|_{\mathcal H}^2 \leq c_\varepsilon \left( (1+\|\Xi_\infty (W)\|_{\mathfrak S} + \|\Xi^\partial_\infty(\varphi_-,\varphi_+)\|_{\boldsymbol{
\mathcal B}})^4 + \|Z_\infty(u)\|_{L^4}^4 + \|u\|_{\mathcal L}^2 \right).
\end{equation}
Furthemore, the map $u \to \ell_{\infty}({\rm rem}_{\varepsilon})$ is a continuous from $\mathcal{L}_{w} \to \mathcal{H}$
\end{enumerate}

[Lemma lem-u-bar is a semimartingale of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] The process $\duality{\overline{u}}{\phi}\coloneqq \bigl\{\duality{\overline{u}(t)}{\phi}:\, t\in [0,T]\bigr\}$
is a $\mathbb{R}$-valued semimartingale.
Moreover, its quadratic variation process is equal to the quadratic variation process of the process $\fourIdx{}{}{}{\phi}{\overline{M}}$, i.e.\ $\overline{\mathbb{P}}$-a.s.
\begin{equation}
[\duality{\overline{u}}{\phi},\duality{\overline{u}}{\phi}](t) =[\fourIdx{}{}{}{\phi}{\overline{M}},\fourIdx{}{}{}{\phi}{\overline{M}}](t), \;\; t\in [0,T].
\end{equation}

[Prop cmj-package of arXiv:2609.00110, 'Phase Transition and Fluctuation Results for First-Passage Percolation on Spread-Out Cycle'] Fix $\varepsilon\in(0,1/2)$ and $y\in\mathds{R}$.
There exist non-negative random variables $W_{1,n},W_{2,n}$, defined on the probability space carrying the coupling above, such that
\begin{align}
 (W_{1,n},W_{2,n})\Rightarrow(W_1,W_2),
\end{align}
and, for $i=1,2$,
\begin{align}
 \sup_{\mathfrak{s}_0\leqslant s\leqslant \mathfrak{s}_1}
 \abs{e^{-s}N_i(s)-W_{i,n}}
 \stackrel{\pr}{\to}0.
\end{align}
Moreover, if
\begin{align*}
 A_v^{(i)}(s)
 :=s-\mathfrak{a}_\ell\widehat\mathsf{T}_i(v),
 \qquad
 v\in\mathcal{C}_i(s),
\end{align*}
then, for every continuous $g$ satisfying $|g(a)|\leqslant Ce^{\eta a}$ for some $\eta<1$, and also for every bounded Riemann-integrable $g$,
\begin{align}
 \sup_{\mathfrak{s}_0\leqslant s\leqslant \mathfrak{s}_1}
 \abs{
 \frac1{N_i(s)}
 \sum_{v\in\mathcal{C}_i(s)}g\bigl(A_v^{(i)}(s)\bigr)
 -\int_0^\infty g(a)e^{-a}\,\mathrm d a
 }
 \stackrel{\pr}{\to}0.
\end{align}
For every fixed $k\in\mathds{Z}\setminus\{0\}$ and every bounded Riemann-integrable $g$,
\begin{align}
 \sup_{\mathfrak{s}_0\leqslant s\leqslant \mathfrak{s}_1}
 \abs{
 \frac1{N_i(s)}
 \sum_{v\in\mathcal{C}_i(s)}
 g\bigl(A_v^{(i)}(s)\bigr)e^{2\pi \mathrm{i}kv/n}
 }
 \stackrel{\pr}{\to}0.
\end{align}

