[Theorem 16 of arXiv:2605.25715, '2605.25715'] Let $C=(c_{ij})_{1 \leq i,j \leq d}$ be a matrix of functions such that $c_{ij}=-c_{ji} \in H^{1,p}_{loc}(\mathbb{R}^d)$ with $p \in (d, \infty)$ for all $1 \leq i,j \leq d$. Let  $G$ be a $d \times d$ matrix of real numbers, $S$ be a symmetric matrix satisfying \eqref{SOHHDlinalg1} with $A=id$ (cf. Proposition \ref{propintegrep}(i)), and $\Phi(x) = \frac12 \langle Sx, x \rangle$. Define the vector field $\mathbf{G}_0$ by
$$
\mathbf{G}_0(x) := Gx + C(x)^T Sx + \frac12 {\rm div} C(x), \quad x \in \mathbb{R}^d.
$$
Then, the following statements hold:
\begin{itemize}
\item[(i)] The decomposition
\begin{equation} 
\mathbf{G}_0(x) = \nabla \Phi(x) + \mathbf{B}(x),
\end{equation}
where $\mathbf{B}(x) = (G-S)x + C^T Sx + \frac12 {\rm div} C(x)$, is a WHHD for $\mathbf{G}_0$.
\item[(ii)] Assume that
\begin{equation} 
\langle\mathrm{div} C(x), Sx \rangle = 0 \quad \text{for a.e. } x \in \mathbb{R}^d.
\end{equation}
Then, \eqref{decomposipol} is an OHHD for $\mathbf{G}_0$.
Moreover, for any triple of constants $k_0, k_1, k_2 \in \mathbb{R}$, the vector field defined by
\begin{equation} 
\mathbf{G}_1(x):= \nabla \Phi(x)+k_0(G-S)x + k_1C(x)^T Sx +k_2 {\rm div} C(x)
\end{equation}
is an OHHD. 

\item[(iii)] Suppose that \eqref{orthogonalit} holds and that $G$ is a Hurwitz matrix.
Then, for any triple of constants $k_0, k_1, k_2 \in \mathbb{R}$, \eqref{orthogong1} is the unique OHHD for $\mathbf{G}_1$. Furthermore, $\mu(dx) = e^{\langle Sx, x \rangle}\,dx$ is the unique infinitesimally invariant measure for $(L^{\mathbf{G}_1},C_0^{\infty}(\mathbb{R}^d))$ and the unique invariant measure for the semigroup associated to the closed extension of $(L^{\mathbf{G}_1},C_0^{\infty}(\mathbb{R}^d))$ and its associated stochastic process, both constructed in \cite{LST22}. 
\end{itemize}

[Lemma lemTransferGnm of arXiv:2411.18563, 'Lower tails for triangles inside the critical window'] Fix $c >0$, $\zeta \in[0, 1]$. Let $\varepsilon>0$. Suppose $\lambda = (1+o(1))c/\sqrt{n}$ and that whp for $G \sim \mu_{\lambda,\zeta}$,
    \begin{align}
        |G| &= (1+o(1)) M, &
        X(G) = (1+o(1)) T,\\
    \end{align}
    where $M = \Theta(n^{3/2})$ and either $\zeta = 1$ and $T=0$ or else $T = \Theta(n^{3/2})$. Set $T_0 = T - \varepsilon n^{3/2}$. Then
    \begin{equation}
        \mathbb{P}_{\lambda,\zeta} \left(\left(|G| = M\right) \wedge\left( T_0 \leq X(G) \leq T\right) \right) = \exp( - o(n^{3/2})  ) \,.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 of arXiv:2606.29131, '2606.29131'] Let $\Lambda_\e^6 f(x,y)$ be defined in \eqref{e2-3-4}.
For every $\beta>0$, there exists $C_2:=C_2(\beta)>0$ such that for every $f\in \M_{\beta}$, $x\in \R^d$ and $y\in \T^d$,
\begin{equation}
|\Lambda_\e^6 f(x,y)|\le C_2\left(\e+\gamma_{3,\beta}(\e)+\gamma_9(\e)\right)\left(\sum_{i=1}^3\|f\|_{\M_{\beta},i}\right)\|\phi_0\|_\infty
(1+|x|)^{-d-\beta}.
\end{equation}

