[Definition 24 (Mass retracts) of arXiv:2604.04267, 'On Sharpest Tail Bounds for Functions \\ of Tail Bounded Random Variables'] A mass retract \index{Mass retract} is a measurable function $\gamma$ on $\mathbb{R}^n$ such that 
   \begin{align}
      0 \leq' \gamma(x) \leq' x, \ &\forall x \in [0,\infty)^n  \\
      \gamma(x) = x, \  \ &\forall x \notin [0,\infty)^n. 
   \end{align} 
   A mass retract $\gamma$ is said to be of $U$, for $U \subset \mathbb{R}^n$ measurable, iff $\gamma(U) \subset U$ and $\forall x \notin U, \ \gamma(x) = x$.

[Theorem thm:sub for noninvariant of arXiv:2411.00663, 'Ergodicity and Mixing of invariant capacities and applications'] Let $(\Omega,\mathcal{F},P)$ be a probability space (not necessarily standard), and $T:\Omega\to \Omega$ be an invertible measurable transformation. Suppose that the limit $\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}P\circ T^{i}$ exists, denoted by $Q$. 	Suppose that $\{f_n\}_{n\in\mathbb{N}}$ is a sequence of $\mathcal{F}$-measurable functions satisfying the following conditions:
	\begin{longlist}
		\item there exists $\lambda >0$ such that $-\lambda n\le f_n(\omega)\le \lambda n$ for any $n\in\mathbb{N}$, and $\omega\in\Omega$;
		\medskip
		\item for each $k,n\in\mathbb{N}$, $f_{n+k}\le f_n+f_k\circ T^n$.
	\end{longlist} 
	If $Q$ is ergodic, then there exists a constant $c\in\mathbb{R}$ such that 
	\[\lim_{n\to\infty}\frac{1}{n}f_n=c,\text{ }P\text{-a.s.}\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 7 of arXiv:2605.25719, 'A note on convergence rate for reflected BSDEs with quadratic generators by penalization m'] Under the assumptions of Theorem \ref{th2}, define
\begin{equation*}
\begin{aligned}
&p_{t}^{n,\lambda}=E^{\mathcal{F}_{t}}[Y_{\phi(n,t)}^{n,\lambda}]-Y^{n,\lambda}_{t}, \\
&q_{t}^{n,\lambda}=\lambda (E^{\mathcal{F}_{t}}[Y_{\phi(n,t)}^{n,\lambda}]-S_{t})^{-}-\lambda(Y^{\lambda}_{t}-S_{t})^{-}.
\end{aligned}
\end{equation*}
Then $\vert p_{t}^{n,\lambda} \vert \leq C(1+\lambda)\frac{1}{n}+C\lambda^{max\{4-2\varepsilon,\frac{4}{\epsilon}-2\}}\left(\frac{1}{n} \right)^{\frac{\varepsilon}{2}}:=P^{n,\lambda}$, $\vert q_{t}^{n,\lambda} \vert \leq C\lambda :=Q^{n,\lambda}$.
\begin{proof}
From \eqref{e3} we have
\begin{equation*}
p_{t}^{n,\lambda}=-E^{\mathcal{F}_{t}} \left[ \int_{t}^{\phi(n,t)}  f^{\lambda} \left( s,E^{\mathcal{F}_{s}}\left[ Y_{\phi(n,s)}^{n,\lambda} \right],Z_{s}^{n,\lambda} \right)  \right],t\in[0,T].
\end{equation*}
Then 
\begin{equation*}
\begin{aligned}
\vert p_{t}^{n,\lambda} \vert &\leq E^{\mathcal{F}_{t}} \left[ \int_{t}^{\phi(n,t)} \vert f^{\lambda} \left( s,E^{\mathcal{F}_{s}}\left[ Y_{\phi(n,s)}^{n,\lambda} \right],Z_{s}^{n,\lambda} \right) \vert \right]\\
&\leq C(1+M_{\lambda}+\lambda)\frac{T}{n}+CE^{\mathcal{F}_{t}} \left[ \int_{t}^{\phi(n,t)}\vert Z_{s}^{n,\lambda} \vert^{2-\varepsilon}ds \right]\\
&\leq C(1+M_{\lambda}+\lambda)\frac{T}{n}+CE^{\mathcal{F}_{t}} \left[ \left( \int_{t}^{\phi(n,t)}\vert Z_{s}^{n,\lambda} \vert^{2}ds \right)^{1-\frac{\varepsilon}{2}} \left( \phi(n,t)-t \right)^{\frac{\varepsilon}{2}} \right]\\
&\leq C(1+M_{\lambda}+\lambda)\frac{T}{n}+CN_{\lambda}^{2-\varepsilon}\left(\frac{T}{n} \right)^{\frac{\varepsilon}{2}}\\
&=C(1+\lambda)\frac{T}{n}+C\lambda^{max\{4-2\varepsilon,\frac{4}{\epsilon}-2\}}\left(\frac{T}{n} \right)^{\frac{\varepsilon}{2}}.
\end{aligned}
\end{equation*}
On the other hand, 
\begin{equation*}
\begin{aligned}
\vert q_{t}^{n,\lambda} \vert &\leq C\lambda \left[ (E^{\mathcal{F}_{t}}[Y_{\phi(n,t)}^{n,\lambda}])^{-}+\Vert S^{+} \Vert_{\mathcal{S}^{\infty}(R)}+\Vert Y^{\lambda} \Vert_{\mathcal{S}^{\infty}(R)} \right]\\
&\leq C\lambda 
\end{aligned}
\end{equation*}
from Lemma \ref{l2} and \ref{boundary_lemma}.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

