body:
[Theorem 4 (Modified, $L$-fold, coupled spherical integration for rank $M(N)\geq 1$) of arXiv:2608.03273, 'On the Asymptotic of Coupled Spherical Integrals: An Operator-Valued Extension of the Free'] Let $L=O(1)$, $M(N)=O\left(N^{1/2-\epsilon}\right)$ for some $\epsilon >0$, and $D_{l,i}= O_{l,i}\Sigma_{l,i} V^\dagger$ have a single non-zero singular value $\sqrt{\theta_{l,i}}$ at the $i^\mathrm{th}$ on-diagonal position of $\Sigma_{l,i}$. 
Define the modified, $L$-fold coupled HCIZ integral by
\begin{align}
    J_N^{(\beta)}\left(\left\{D_{l,i}\right\},\left\{E_{lk,i}\right\}\right)
    =
    \int
        \exp\left\{
            \sum_{i=1}^{M(N)}
            \sum_{l,k=1}^{L}
                N\mathrm{tr}\left(
                    D_{k,i} D_{l,i}^\dagger
                    U_l^\dagger
                    E_{lk,i}
                    U_k
                \right)
        \right\}
        \prod_{l=1}^{L}
            \mathrm d m_N^{(\beta)}(U_l)
            .
\end{align}
The block matrix $Z_{N,i}$ is structured as in Definition~\ref{def:operator_valued_convergence}, i.e. the block at position $(l,k)$ of $Z_{N,i}$ is $E_{lk,i}$ with $E_{lk,i} = E_{kl,i}^\dagger\in \mathbb A^{N\times N}$ for all $(l,k)$, $Z_{N,i}$ converges to some $Z_{i}$ with finite moments as $N\uparrow\infty$, is R-cyclic, and $||E_{lk,i}||_\infty<\infty$ for all $(l,k,i)$ as $N\uparrow\infty$.
If all $\theta_{l,i}$ are sufficiently small, such that
\begin{align}
-P_{i}=-\mathrm{diag\left\{\frac{2\theta_{1,i}}\beta,\ldots,\frac{2\theta_{L,i}}\beta\right\}}
    \in \left\{\left.G_{Z_{i}}^{\mathcal D_L}(S) \right| S^{Z_i}\in\mathcal S_{\{-\}^L}\right\},
\end{align}
then
\begin{align}
    \lim_{N\uparrow\infty} \frac{1}{NM(N)}
    \log J_N^{(\beta)}\left(\left\{D_{l,i}\right\},\left\{E_{lk,i}\right\}\right)
    =
    \lim_{N\uparrow\infty}
    \frac{1}{M(N)}
    \sum_{i=1}^{M(N)}
        \frac{\beta}{2}
        \int_{0}^1
            \mathrm{tr}\left(
                R_{Z_{i}}^{\mathcal D_L}(P_i w) P_i
            \right)
            \mathrm d w.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 3 of arXiv:2604.19924, 'Fluctuation theory for spectrally negative Lévy processes killed by additive functionals'] Let $A$ be a PcNAF and $\nu_A$ its Revuz measure. Then, for any $x \in \R$,
	\begin{align}
		A_t=\int_{\R} L^a_t \, \nu_A(da), \qquad t \geq 0, 
	\end{align}
	$\p_x$-a.s. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition e: correlation moment integrability of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] In the setting of Proposition~(p:mixing condition uniformity of the paper), if $p\in[0,\infty)\setminus2\N_0$, then one can guarantee that $S_\Phi$ exists and has an expansion of the form~(equation e: sf asymptotics of the paper) with $a=0$ if 
    \begin{equation}
        \int (\|y\|+1)^p\, |\beta_\Phi|(dy) < \infty,
    \end{equation}
    and if 
    \begin{equation}
        \int y^{\otimes q}\, \beta_\Phi(dy) = 0
    \end{equation}
    for $q\in2\N_0$ with $q < p$. If $p\in2\N_0$ and if $\Phi$ is isotropic or $p=0$, then under the same conditions one obtains~(equation e: sf asymptotics of the paper) with
    \begin{equation}
        a = \frac{(-1)^{\frac{p}{2}}}{p!}\int y_1^p\, \beta_\Phi(dy).
    \end{equation}
    If $p\in2\N$ and $\Phi$ is not isotropic, then the coefficient, and even the leading order in the asymptotics of $S_\Phi$ can be direction-dependent. Still, $\Phi$ is beyond $p$-uniform iff~(equation e: correlation zero integral of the paper) holds also for $q=p$. If $p\in[-d, 0)$,~(equation e: correlation moment integrability of the paper) cannot guarantee that $\hat\beta_\Phi$ has a density, but it still implies that $\Phi$ is beyond $p$-uniform.
    \begin{proof}
         If~(equation e: correlation moment integrability of the paper) holds for $p\geq 0$, then $\hat\beta_\Phi$ has a continuous density. Further, since 
        \begin{equation*}
            e^{-i\langle k, y\rangle} = \sum_{q=0}^{\lfloor p \rfloor} \frac{(-i)^q}{q!} \langle k,y\rangle^q + o(|\langle k, y\rangle|^p), \quad k, y\in\R^d,
        \end{equation*}
        as $\langle k,y\rangle\to 0$, one can calculate that
        \begin{equation}
            S_\Phi(k) = \sum_{q=0}^{\lfloor p \rfloor} \frac{(-i)^q}{q!} \int y^{\otimes q}\, \beta_\Phi(dy)\,  k^{\otimes q} + o(\| k\|^p)
        \end{equation}
        as $k\to 0$. Hence, the assertion follows from the assumption of~(equation e: correlation zero integral of the paper). Note that isotropy of $\Phi$ implies isotropy of $\beta_\Phi$, whereby $\int \langle k, x\rangle^p\, \beta_\Phi(dy)$ is constant for $k\in\partial B_\varepsilon$ for every $\varepsilon>0$.

        If~(equation e: correlation moment integrability of the paper) holds for $p\in[-d,0)$, then 
        \begin{equation*}
            \frac{\BV[\Phi(B_r)]}{r^{d-p}} = \int r^p\frac{\I_{B_r}\star \I_{B_r}(y)}{r^d} \, \beta_\Phi(dy)
            \xrightarrow{r\to \infty} 0
        \end{equation*}
        by the theorem of dominated convergence. Hence, $\Phi$ is beyond $p$-uniform by Theorem~(t:asymptotic variance test function of the paper).
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:disk+QT of arXiv:2411.19810, 'Radial conformal welding in Liouville quantum gravity'] Fix $W,W_1,W_2,W_3>0$ such that $W_2+W_3=W_1+2$ or $W_1+W_3=W_2+\gamma^2-2$. There exists some constant $c:=c_{W,W_1,W_2,W_3}\in (0,
	\infty)$ such that
	\begin{equation}
	    \mathrm{QT}(W+W_1,W+W_2,W_3)\otimes \mathrm{SLE}_\kappa(W-2;W_2-2,W_1-W_2) = c\int_0^\infty {\mathcal{M}}^\mathrm{disk}_{0,2}(W;\ell)\times\mathrm{QT}(W_1,W_2,W_3;\ell)d\ell.
	\end{equation}
	That is, if we draw an independent $\mathrm{SLE}_\kappa(W-2;W_1-2,W_2-W_1)$ curve $\eta$ on a sample from $\mathrm{QT}(W+W_1,W+W_2,W_3)$ embedded as $(D,\phi,a_1,a_2,a_3)$, then the quantum surfaces to the left and right of $\eta$ are corresponding independent quantum disks and triangles conditioned on having the same interface quantum length. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Deff fxn-vanish of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] For an arbitrary set $A$ and functions $f: A \to [-\infty,\infty]$ and $g:A \to [0,\infty]$, we say $f$ vanishes over $g$ if one of the following equivalent conditions holds: \begin{enumerate}

        \item $\forall \epsilon > 0, \exists M > 0$ such that $|f|\mathbbm{1}_{|f|>M} \leq \epsilon g$
        \item $\forall \epsilon > 0, \exists N > 0$ such that $|f| \leq \epsilon g + N$
    \end{enumerate}

[Proposition 10 of arXiv:2604.27242, 'Statistical Inference for Homogenization Limits Driven by Wiener or Hermite Processes'] Suppose that \(m>2\) and \(H\in(3/4,1-1/(2m))\). Then:
\begin{itemize}
    \item If \(H^*(m)>1/4\), then \(r_I\geq r_S\).
    \item If \(H^*(m)<1/4\), then \(r_I\leq r_S\).
    \item If \(H^*(m)=1/4\) then \(r_I=r_S\).
\end{itemize}

