[Theorem 5 of arXiv:2506.08775, 'Markovian multivariate Hawkes population processes: Efficient evaluation of moments'] Fix $t,\tau\in{\mathbb R}_+$, and let $\bm{Q}(0)= \bm{0}$, $\bm{\lambda}(0)=\bm{\overline{\lambda}}$. Then, for any  $\bm{y},\bm{z}\in[-1,1]^d$, $\bm{r},\bm{s} \in \rr_+^d$,
\begin{align}
\begin{split}
    \zeta_\tau(t,\bm{r},\bm{y},\bm{s},\bm{z}) &= \zeta(t, \bm{y}\odot\hat{\bm{z}}(t), \bm{r} + \tilde{\bm{s}}(t+\tau))
    \prod_{j=1}^d \exp\Big(-\overline{\lambda}_j \alpha_j \int_t^{t+\tau} \tilde{s}_j(u)\ddiff u\Big)\\
    &=\prod_{j=1}^d
    \exp\Big(-\overline{\lambda}_j\tilde{r}_j(t) - \overline{\lambda}_j\alpha_j \int_0^t \tilde{r}_j(v)\ddiff v -\overline{\lambda}_j \alpha_j \int_t^{t+\tau} \tilde{s}_j(u)\ddiff u\Big).
\end{split}
\end{align}
Here $\zeta(\cdot)$ is given by Eqn.~\eqref{eq: zeta characterization in terms of s(u)}, and, for $j\in[d]$, the functions $\hat{z}_j(\cdot)$, $\tilde{s}_j(\cdot)$ and $\tilde{r}_j(\cdot)$ satisfy
\begin{align} 
\begin{split}
    &\hat{z}_j(u) = 1 + (z_j-1)e^{-\mu_j(t+\tau-u)}, \\
    &\frac{\mathrm{d} \tilde{s}_j(u)}{\mathrm{d} u} + \alpha_j \tilde{s}_j(u) + \big(1 + (z_j - 1)e^{-\mu_j(u-t)}\big) \beta_j(\tilde{\bm{s}}(u)) - 1 = 0,\\
    &\frac{\ddiff \tilde{r}_j(v)}{\ddiff v} + \alpha_j \tilde{r}_j(v) + \big(1 + (y_j-1)e^{-\mu_jv} + y_j(z_j-1)e^{-\mu_j(v+\tau)}\big)\beta(\tilde{\bm{r}}(v)) - 1 = 0,\\
\end{split}
\end{align}
with boundary condition $\tilde{s}_j(t) = s_j$ and $\tilde{r}_j(0) = r_j+\tilde{s}_j(t+\tau)$, and where $0\leqslant v \leqslant t$ and $t \leqslant u \leqslant t+\tau$. (Proof in the paper; no proof environment follows the statement in the TeX.)

