[Theorem 6 (Potential-bearing Robin--Lieb localization) of arXiv:2608.30211, '2608.30211'] Let $D$ be a uniformly $C^{2,\gamma}$ domain, let $V\in L^\infty(D)$ be real,
and let $\varrho\in[0,1]$.  For every $R>0$,
\begin{equation}
 \lambda(-\Delta+V,D,\varrho)
 \geq \inf_{z\in\R^d}
 \lambda(-\Delta+V,D\mid B_R(z),\varrho)
 -\lambda_1(B_1)R^{-2},
\end{equation}
where empty intersections are assigned eigenvalue $+\infty$.

[Lemma 21 (Canonical truncation morphism) of arXiv:2608.30875, 'A Decomposition Theorem for Topological Semi-small Maps'] Let $f : X \longrightarrow Y$ be a continuous map of topological spaces and let
        	$Rf_* : D(X) \to D(Y)$ be the right derived direct image
        	functor between the unbounded derived categories of sheaves of abelian groups.
        	For every integer $k$ there exists a unique natural transformation
        	\begin{align*}
        \gamma_\mathcal{F}:	\tau_{\leq k} \circ Rf_*  \longrightarrow  Rf_* \circ \tau_{\leq k}	
        	\end{align*}
        	of functors $D(X) \longrightarrow D(Y)$, which makes the following diagram commutative
        	 	\begin{align*}
        		\begin{array}{ccccc}
        			\tau_{\leq k}Rf_*\mathcal{F} & \longrightarrow & Rf_*\mathcal{F} & \longrightarrow &
        			\tau_{\geq k+1}Rf_*\mathcal{F} \\
        			\downarrow{\gamma_\mathcal{F}} & & \parallel & & \\
        			Rf_*\tau_{\leq k}\mathcal{F} & \longrightarrow & Rf_*\mathcal{F} & \longrightarrow &
        			Rf_*\tau_{\geq k+1}\mathcal{F}
        		\end{array}	
        	\end{align*}

[Lemma Lemma-on-difference-U_M-for-critical of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] Given $b>0$, there exists $K, C_1, C_2>0$\footnote{We stress that we are here and in (equation quant-bound-for-super-critical-for-difference of the paper) writing ``there exists a $K>0$" rather than writing ``for all $K>0$". We expect (equation quant-bound-for-super-critical-for-difference of the paper), (equation quant-bound-for-difference-critical of the paper) to hold for all $K>0$ rather than only for $K$ large enough. We were able to verify (equation quant-bound-for-super-critical-for-difference of the paper), (equation quant-bound-for-difference-critical of the paper) only for large enough $K>0$, which will be sufficient for our purposes.} such that for all $t$ large enough and $z\in [-\frac{1}{4}\log t , b t]$,
    \begin{align}
        C_1 t^{-\frac{3}{2}} (z+\log t)e^{-\sqrt 2 z}e^{-\frac{z^2}{2t}}\le u_M(t,  &\sqrt{2}t + z - K ) - u_M(t, \sqrt{2}t + z + K ) \\ \nonumber & \le C_2 t^{-\frac{3}{2}} (z+\log t)e^{-\sqrt 2 z}e^{-\frac{z^2}{2t}}.
    \end{align}

[Theorem 22 of arXiv:2608.19976, 'Random valuations'] If $\Phi$ is a $\sigma$-continuous non-negative stationary isotropic
  ID valuation with independent increments, then the corresponding
  L\'evy measure on $\sC\times(0,\infty)$ is given by
  \begin{equation}

    \nu(\sC_L\times A)
    =\sum_{k=0}^{d} \int_A \int_{G(d,k)}
    \E(V_{d-k}(Y_{E,r}+\Pi_{E^\perp}L))\gamma_k(dE) a_{k,r}\mu(dr)
  \end{equation}
  for each compact set $L$ in $\R^d$ and Borel $A\subset(0,\infty)$,
  where $\gamma_k$ is the normalised Haar measure on $G(d,k)$,
  $Y_{E,r}$ is a random compact convex set in $E^\perp$ such that
  $Y_{RE,r}$ has the same distribution as $RY_{E,r}$ for each
  deterministic rotation $R$, and $a_{k,r}$ is a measurable non-negative
  function of $r>0$. If $K\in\Kd$, then
  \begin{equation}

    \nu(\sC_K\times A)=\sum_{k=0}^{d} \sum_{j=0}^{d-k}
    c_{0,d}^{d-k-j,k+j} 
    V_{d-k-j}(K) \int_A \E V_j(Y_{E,r})a_{k,r}\mu(dr).
  \end{equation}

[Lemma of arXiv:2505.10256, 'Stochastic Oscillators out of equilibrium:\\ scaling limits and correlation estimates'] There exists some $C=C(T)>0$ such that for every $z\in\mathbb Z$, 
