_{N\rightarrow{+\infty}}} \,
\mathbb{E}_{N}\Big[\sup_{0\leq{t}\leq{T}}|\langle\pi^{e,N}_{t},h_{z}\rangle|^{2}\Big] 
\le C(1+z^2\alpha^2(1+\alpha)\mathbf{1}_{\kappa=1}
+ z^4).
\end{equation*}

