[Lemma lem:prelimitingtransbounds of arXiv:2608.11603, 'Continuous-time directed polymers to the Critical SHF via moments'] {}
	Fix $\alpha,  \alpha' \in \mathsf{Pair}[\![n]\!]$ such that $\alpha \neq \alpha'$. For $a > 0, p>2$ and $q$ such that $p^{-1} + q^{-1} =1$ and $t > 0$, the following bounds hold true: 
	\begin{subequations}{}
		\begin{align}
			\Vert \mathcal{P}_{\varepsilon}(t)\Vert_{\operatorname{op}} & \leqslant 1  \\
			\Vert \mathsf{p}_{\varepsilon}(t)\Vert_{q} & \leqslant ct^{-\frac{1}{p}}  \\

			\normop{\mathcal{P}^{\ast}_{\varepsilon\alpha}(t)} = \normop{\mathcal{P}_{\varepsilon\alpha}(t)} & \leqslant ct^{-\tfrac{1}{2}} \\
			\normop{\mathcal{P}_{\varepsilon\alpha\alpha'}(t)} & \leqslant ct^{-1}  \\
			\NORmop{\int_{0}^{\infty}e^{- t}\mathcal{P}_{\varepsilon\alpha \alpha'}(t) \, \mathrm{d} t \,} & \leqslant c  \\
			\normop{\prediagtrans{\theta}{\alpha}(t)} & \leqslant ct^{-1}|\log\big( t \wedge \tfrac{1}{2} \big) |^{-2}e^{ct}  \\
		\Norm{\mathcal{P}^{\ast}_{\varepsilon\alpha}(t)}_{2,0 \to q,a}	=\Norm{\mathcal{P}_{\varepsilon\alpha}(t)}_{p,a \to 2,0} & \leqslant ct^{-\frac{1}{p}} \, .  
		\end{align}
	\end{subequations}
	Consequently, there exists $c > 0$ such that
	\begin{equation*}
		\sup_{0 <\varepsilon <1/c}\normop{\mathcal{Q}_{\varepsilon}^{[\![n]\!], \theta}(t)} \leqslant ce^{ct} \, .
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

