[Lemma L:ML-Est of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Suppose that $\theta+ H>1$, $H\in (0,1)$, and $\beta\in (0,2]$. Then we have:
    \begin{enumerate}[\rm (i)]
      \item Suppose one of the following conditions: i) $\beta\in(0,2)$, and ii) $\beta = 2$, $\theta \geq 3$. Then, with  $C_{\beta,\theta} > 0$, for
          all $t>0$ and $\lambda>0$, it holds that
          \begin{align}
            \int_0^t w^{(\theta-1) / H} \left| E_{\beta,\theta}\left(-\lambda w^\beta \right)\right|^{1/H}\ensuremath{\mathrm{d} } w
            \le C_{\beta,\theta}\:\frac{t^{(\theta + H-1) /H}}{1+(t\lambda^{1/\beta})^{\min\left(\beta /H,(\theta + H-1) /H\right)}};
          \end{align}

    \item If $\beta = 2$ and $\theta \in [2,3)$, for some positive constant $C_{\theta}$, for all
          $t>0$ and $\lambda>0$, it holds that
          \begin{align}
            \int_0^t w^{(\theta-1) / H} \left| E_{2,\theta}\left(-\lambda w^2 \right)\right|^{1/H}\ensuremath{\mathrm{d} } w
            \le C_{\theta}\:\frac{t^{(\theta + H-1) /H}}{1+(t\lambda^{1/2})^{(\theta - 1)/H}}.
          \end{align}

  \end{enumerate}

[Lemma kappa-bousfield of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let ${\mathcal{C}}$ be globally presentable. A left adjoint $F\colon{\mathpalette\ulhelper{{\mathfrak d\kern-.25pt}{\mathfrak S\kern-.5pt\mathfrak p}}}\hbox{\rule[-2pt]{0pt}{0pt}}_\textup{lvl}\to{\mathcal{C}}$ factors through ${\mathpalette\ulhelper{\mathfrak d\kern-.25pt}}\hbox{\rule[-2pt]{0pt}{0pt}}{\mathfrak S\kern-.5pt\mathfrak p}_\textup{gl}$ if and only if $F$ inverts the natural transformations $\kappa$ from the previous construction for all compact Lie groups $G$ and representations $V,W$.
    \begin{proof}
        The left adjoint $F$ factors through the localization if and only if its right adjoint $U\colon{\mathcal{C}}\to{\mathpalette\ulhelper{{\mathfrak d\kern-.25pt}{\mathfrak S\kern-.5pt\mathfrak p}}}\hbox{\rule[-2pt]{0pt}{0pt}}_\textup{lvl}$ factors through the full subcategory ${\mathpalette\ulhelper{\mathfrak d\kern-.25pt}}\hbox{\rule[-2pt]{0pt}{0pt}}{\mathfrak S\kern-.5pt\mathfrak p}^\Omega$. By definition, this precisely amounts to requiring that the pastings
        \[
            \begin{tikzcd}
                {\mathcal{C}}\arrow[from=d,"="]\arrow[r, "U"]&{\mathpalette\ulhelper{{\mathfrak d\kern-.25pt}{\mathfrak S\kern-.5pt\mathfrak p}}}\hbox{\rule[-2pt]{0pt}{0pt}}_\textup{lvl}\arrow[r,"\ev_V"]\arrow[from=d,"="{description}]\arrow[dr,Rightarrow,"\tilde\sigma"{description},shorten=1em] &[2em] \ul{{\mathfrak S\kern-.4pt}}_{\textup{gl},*}(\mathbb B{G}\times-)\\
                {\mathcal{C}}\arrow[r, "U"']& {\mathpalette\ulhelper{{\mathfrak d\kern-.25pt}{\mathfrak S\kern-.5pt\mathfrak p}}}\hbox{\rule[-2pt]{0pt}{0pt}}_\textup{lvl}\arrow[r,"\ev_{V\oplus W}"'] & \ul{{\mathfrak S\kern-.4pt}}_{\textup{gl},*}(\mathbb B{G}\times-)\arrow[u,"\Omega^W"']
            \end{tikzcd}
        \]
        are equivalences for all compact Lie groups $G$ and $G$-representations $V,W$. However, as a natural transformation is an equivalence if and only if its total mate is so and since passing to mates is compatible with pastings, this is in turn equivalent to the pastings
        \[
            \begin{tikzcd}
                {\mathcal{C}}\arrow[d,"="']\arrow[from=r, "F"']&{\mathpalette\ulhelper{{\mathfrak d\kern-.25pt}{\mathfrak S\kern-.5pt\mathfrak p}}}\hbox{\rule[-2pt]{0pt}{0pt}}_\textup{lvl}\arrow[from=r,"{\textbf{\textup{O}}(V,-)\otimes_G{-}}"']\arrow[d,"="{description}]\arrow[from=dr,Rightarrow,"\kappa"{description},shorten=1em] &[4em] \ul{{\mathfrak S\kern-.4pt}}_{\textup{gl},*}(\mathbb B{G}\times-)\\
                {\mathcal{C}}\arrow[from=r, "F"]& {\mathpalette\ulhelper{{\mathfrak d\kern-.25pt}{\mathfrak S\kern-.5pt\mathfrak p}}}\hbox{\rule[-2pt]{0pt}{0pt}}_\textup{lvl}\arrow[from=r,"\;{\textbf{\textup{O}}(V\oplus W,-)\otimes_G{-}}"] & \ul{{\mathfrak S\kern-.4pt}}_{\textup{gl},*}(\mathbb B{G}\times-)\arrow[from=u,"\Sigma^W"]
            \end{tikzcd}
        \]
        being equivalences, which precisely amounts to $F$ inverting the maps $\kappa$.
    \end{proof}

