body:
[Theorem 18 of arXiv:2506.10522, 'On the Law of the Iterated Logarithm for $m$-dependent stationary random variables under s'] Let $\{X_n;n=1,2,\cdots\}$ be a sequence of independent random variables under $\sles$. Denote $s_n^2=\sum_{i=1}^n\mbE[X_i^2]$, $\underline{s}_n^2=\sum_{i=1}^n\mbe[X_i^2]$, $t_n=\sqrt{2\log\log s_n^2}$ and $a_n=s_nt_n$. Suppose that condition (CC) is satisfied. Assume that 
    \begin{equation}
        \frac{\underline{s}_n^2}{s_n^2}\to r > 0,

    \end{equation}
    \begin{equation}
        s_n^2\to\infty, \quad |X_n|\leq \alpha_n\frac{s_n}{t_n} \text{ with } \alpha_n\to 0

    \end{equation}
    and
    \begin{equation}
        \frac{\sum_{j=1}^n|\mbE[X_j]|+|\mbe[X_j]|}{a_n}\to0.

    \end{equation}
     are satisfied, then for $V = \V^{\mathcal{P}}, \mathbb{C}^*$ or $\Vstar$,
    \begin{equation}
        V\left(C\left\{\frac{\sum_{i=1}^n X_i}{\sqrt{2s_n^2\log\log s_n^2}}\right\}=[-\sqrt{t},\sqrt{t}]\right)=
        \begin{cases}
            1 & \text{ if } t\in[r, 1],\\
            0 & \text{ if } t\notin[r,1].
        \end{cases}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 17 of arXiv:2607.22416, 'A multi-player optimal stopping game based on a spider Brownian bridge'] \begin{enumerate}
\item $M^\phi= (M^{\phi}_t)_{0 \leq t \leq 1}$ given by $M^{\phi}_t = \sqrt{1-t} \phi\left( \frac{R_t}{\sqrt{1-t}} \right)$ is a non-negative local martingale. 
\item For $j \in \{ 1,2, \ldots , N \}$, $M^{\psi,j} =  (M^{\psi,j}_t)_{0 \leq t \leq 1}$ given by $$M^{\psi,j}_t = \sqrt{1-t} \psi\left( \frac{R_t}{\sqrt{1-t}} \right) \left( \mathbb{I}_{ \{ \Theta_t = \theta_j \} } - p_j \right)$$ is a local martingale. 
\item Suppose $C \in \RR$ and $D \in \RR^N$ is such that $\sum_{j=1}^N p_j D_{j}=0$. Then $M = (M^{C,D}_t)_{0 \leq t \leq 1}$ given by
\[ M^{C,D}_t = C \sqrt{1-t} \phi\left( \frac{R_t}{\sqrt{1-t}} \right) + \sum_{j=1}^N D_j \sqrt{1-t} \psi\left( \frac{R_t}{\sqrt{1-t}} \right) \mathbb{I}_{ \{ \Theta_t = \theta_j \} }
 \]
is a local martingale.
\end{enumerate}

[Proposition 6 of arXiv:2608.30089, 'On the Coefficients of Hurwitz-Type Matrix Polynomials'] For $n\geq1$, the matrix polynomial  $\f_n$ is an HTM polynomial if and only if $\f_n$ has the following
 representation:
 \begin{equation}
 \f_n(z)=\left\{
 \begin{array}{cl}
   (-1)^m(P_{1,m}^*(-\bar z^2)-z\, Q_{1,m}^*(-\bar z^2)), & n=2m, \\
  (-1)^m(Q_{2,m}^*(-\bar z^2)+z\,  P_{2,m}^*(-\bar z^2)), & n=2m+1,
 \end{array}
 \right. 
\end{equation}
where $P_{k,m}$ and  $Q_{k,m}$ for $k=1,2$ are polynomials defined in Definition \ref{def2p}.
The matrix polynomials
$P_{k,m}$ and  $Q_{k,m}$
are constructed from the Markov parameters associated with \(\mathbf f_n\). (Proof in the paper; no proof environment follows the statement in the TeX.)

