body:
[Lemma 28 of arXiv:2607.21392, 'Gaussian Convexity Principles for Sharp Moderate Deviations of Gaussian Maxima and Critica'] There are constants $q_-<q_+$, $L>-q_-$, $c_0>0$, and, for every sufficiently large $N$, a deterministic point $\gamma_N\in \mathcal{I}_N
=\bigl(2+q_-N^{-2/3},2+q_+N^{-2/3}\bigr)$ such that, with $b_N=2-LN^{-2/3}$,
\begin{equation}
r_N(\gamma_N)\ge c_0N^{2/3}.
\end{equation}
Here $r_N$ is the density of the finite measure $\mathbb Q_N(\mu_1\in dx,\ \mu_4\ge b_N)=r_N(x)\,dx.$ Moreover,
\begin{equation}
0<\gamma_N-b_N\le(q_++L)N^{-2/3}.
\end{equation}

[Lemma lem:parameters of arXiv:2609.02234, 'An $n(\log n)^{o(1)}$ bound for nested cycles without geometric crossings'] For all sufficiently large $n$ (in terms of $k$), the parameters above satisfy
\begin{equation}
  b\ge2,\qquad s\le n^{1/2},\qquad 8Qs\le L^{a_*}<n,\qquad
  \omega(m)\le\omega_*\quad(1\le m\le8Qs);
\end{equation}
the two Hall margins
\begin{equation}
  3\omega_*<\frac{\omega(n)}{16r},
  \qquad 2b\omega_*<\frac{\omega(n)}{16r};
\end{equation}
the two routing budgets
\begin{equation}
    Q(R+1)\le\frac{b^{p+1}}4,\qquad
    Q+4Qb^p+Q(R+2h+2)+\frac{4s}{b}\le\frac{s}{64};
\end{equation}
and
\begin{equation}
  R+2h+2\le2R,
  \qquad R\le133L\Lambda^2,
  \qquad r^2\log r\le2c^2\omega(n).
\end{equation}

