[Lemma 73 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Fix $T_1 \in \mathbb{N}$, $\vec{y} \in \mathfrak{W}_2$, $q \in (0,1)$, $c \in [0, q^{-1})$, and complex numbers $\hat{q}, \hat{c} \in \mathbb{C}$ with $|\hat{q}| = q$ and $|\hat{c}| = c$. Then, the series
\begin{equation}
 \sum_{\mathfrak{B} \in \Omega_{\ice}(T_1, \vec{y})} W(\mathfrak{B};\hat{q},\hat{c})  =:Z(T_1, \vec{y}; \hat{q},\hat{c}),
\end{equation}
converges absolutely. In addition, we have the following formula 
\begin{equation}
Z(T_1, \vec{y}; \hat{q},\hat{c}) = \frac{\hat{q}^{y_1 - y_2}}{2 \pi \im} \oint_{C_{r_1}}du \frac{H_{T_1}(u)H_{T_1}(\hat{q}^2/u)}{u^{y_1 - y_2 + 1}(1- u\hat{c}/\hat{q})} - \frac{\hat{q}^{y_1 - y_2+2}}{2\pi \im}\oint_{C_{r_2}}du \frac{H_{T_1}(u) H_{T_1}(\hat{q}^2/u)}{u^{y_1 - y_2 + 3}(1 - \hat{q}\hat{c}/u)},
\end{equation}
where $H_{T_1}(x) = (1- x)^{-T_1}$. The contours $C_{r_i}$ are positively oriented circles that are centered at the origin where $r_1, r_2 \in (q^2,1)$, $r_1$ is sufficiently close to $q^2$ and $r_2$ is sufficiently close to $1$, so that $cr_1/q < 1$ and $qc/r_2 < 1$.

[Theorem 2 of arXiv:2609.00867, '2609.00867'] Under Assumption~\ref{ass:kernel-density}, let \(g=g_{d,s}^{(m)}\).
Let \((\kappa_j)_{j\ge1}\) be the nonnegative eigenvalues of \(A_{g,\rho}\)
in nonincreasing order, repeated according to multiplicity, and let
\((Z_j)_{j\ge1}\) be independent standard Gaussian variables.  Then
\begin{equation}
 \cU_{N,\rho}(g)
 \xrightarrow[N\uparrow\infty]{\mathrm{law}}
 \cQ_{g,\rho}
 :=\frac12\sum_{j\ge1}\kappa_j(Z_j^2-1),
\end{equation}
where the series on the right-hand side converges in \(L^2\) and belongs to
the second Wiener chaos.
Moreover, for every \(\beta>0\),
\begin{align}
 \cZ_{\infty,\rho}(\beta;g)
 :=\lim_{N\uparrow\infty}\cZ_{N,\rho}(\beta;g)
 &=\E e^{-\beta\cQ_{g,\rho}}\notag\\
 &=\dettwo(\Id+\beta A_{g,\rho})^{-1/2},             
\end{align}
and
\begin{equation}
 \lim_{N\uparrow\infty}\log\cZ_{N,\rho}(\beta;g)
 =\log\cZ_{\infty,\rho}(\beta;g)
 =\frac12\sum_{j\ge1}
 \bigl(\beta\kappa_j-\log(1+\beta\kappa_j)\bigr).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 36 of arXiv:2608.15914, 'Absorption cutoff and stationary singularities for rounded Gaussian random dynamical syste'] Let \cref{ass:gaussian-stable-selected} hold. Then, for every
  $0<C_0<\infty$ there are
  constants $C,c_0>0$ such that, with
  $T_N:=\lfloor C_0\log N\rfloor$ and
  \begin{equation*}
    \tau_\ast^{(N)}
    :=
    \inf\{t\geq s_\ast:Z_t^{(N)}\notin I_\ast\},
  \end{equation*}
  one has, for all sufficiently large $N$,
  \begin{equation}
    \Pp\left(\tau_\ast^{(N)}\leq T_N\right)
    \leq
    C T_N\exp(-c_0N),
  \end{equation}
  and
  \begin{equation}
    \sup_{0\leq t\leq T_N}
    \Ee\left[
      \left(Z_t^{(N)}-q_{t,N}\right)^2
    \right]
    \leq \frac{C}{N} .
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] We have the following convergence as $m \to \infty$:

\begin{equation}
S_{\text{{\tiny $2,\!\varepsilon,\!z_0$}}}(\tilde{v}_m) \longrightarrow S_{\text{{\tiny $2,\!\varepsilon,\!z_0$}}}(\tilde{v}) \quad \left\{
\begin{array}{l}
\text{in} \quad C([0,T]\,;L^2(\Omega)),\\[0.1cm]
\text{weakly in} \quad W^{1,2}(0,T\,;L^2(\Omega)),
\end{array}
\right.
\end{equation}

whenever a sequence $\{\tilde{v}_m\}_{m \in \mathbb{N}} \subset \mathcal{V}(v_0)$ and a function $\tilde{v} \in \mathcal{V}(v_0)$ satisfy the following convergences 
as $m \to \infty$:

\begin{equation}
\tilde{v}_m \longrightarrow \tilde{v} \quad \left\{
\begin{array}{l}
\text{in} \quad C([0,T]\,;L^2(\Omega)),\\[0.1cm]
\text{weakly in} \quad W^{1,2}(0,T\,;L^2(\Omega)).
\end{array}
\right.
\end{equation}

