[Lemma LEM-ST-A-1-TT of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] The terminal stopping time ${\mathfrak{t}}$ admits
\begin{equation*}
\mathbb{P}\left( {0 < {\mathfrak{t}} \leqslant T} \right) = 1 ,
\end{equation*}
and
\begin{equation*}
\left[ {0,\mathfrak{t}} \right] = \mathop {\lim }\limits_{q \to \infty } \mathop  \cap \limits_{j = 1}^q \left[ {0,{\mathfrak{t}_j}} \right] .
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition conditionnal expectation of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] Let $\mathcal{A}$ be a unital algebra and $\mathcal{B}$ a unital subalgebra of $\mathcal{A}$. An \emph{operator-valued probability space} $(\mathcal{A},\mathcal{B},\Delta)$ consists of $\mathcal{B}\subset\mathcal{A}$ and a map $\Delta :\mathcal{A}\rightarrow\mathcal{B}$ satisfying
        \begin{align}
            \Delta(b)&=b\quad\quad\forall b\in\mathcal{B},\\
            \Delta(b_{1}ab_{2})&=b_{1}\Delta(a)b_{2}\quad\quad\forall a\in\mathcal{A},\quad\forall b_{1},b_{2}\in\mathcal{B}.
        \end{align}
        Such a map $\Delta$ is called a \emph{conditional expectation}.

        Let $K$ be an arbitrary index set. We write $\mathcal{B}\langle X_{k}: k \in K\rangle$ for the free non commutating algebra generated by $\mathcal{B}$ and the non commutating indeterminate $(X_{k})_{k\in K}$. We call an element of $\mathcal{B}\langle X_{k}: k \in K\rangle$ a $\mathcal{B}$-valued polynomial. The \emph{operator-valued distribution} (or $\Delta$-distribution for short) of a family $\mathbf{A} = (A^{(k)} )_{k\in K} \subset \mathcal{A}$ is the linear map of operator-valued moments
        \begin{equation}
            \Delta_{\mathbf{A}}:\mathcal{B}\langle X_{k}: k \in K\rangle\rightarrow\mathcal{B},\quad P\mapsto\Delta(P(\mathbf{A})).
        \end{equation}

        We say that the families $\mathbf{A}_{1} = (A^{(k)}_{1} )_{k\in K} ,\cdots , \mathbf{A}_{L} = (A^{(k)}_{L} )_{k\in K} \subset \mathcal{A}$ are \emph{free with amalgamation over $\mathcal{B}$} (or free over $\mathcal{B}$ for short) if
        \begin{equation}
            \Delta\left((P_{1}(\mathbf{A}_{l_{1}})-\Delta(P_{1}(\mathbf{A}_{l_{1}})))\cdots(P_{n}(\mathbf{A}_{l_{n}})-\Delta(P_{n}(\mathbf{A}_{l_{n}})))\right)=0,
        \end{equation}
        for any $\mathcal{B}$-polynomials $P_{1},\cdots,P_{n}\in\mathcal{B}\langle X_{k}: k \in K\rangle$ whenever $l_{j}\neq l_{j+1}$ for $1\leq j\leq n-1$.

[Theorem thm:value-two-criterion of arXiv:2608.16119, 'Fully nonlinear parabolic equations under a fixed reference diffusion: weighted \texorpdfs'] Under Assumptions~(ass:reference-diffusion of the paper) and
(ass:bochner-regularity of the paper), every regular time weight satisfies
\begin{equation*}
 C_w(X)=2
 \quad\Longleftrightarrow\quad
 \mathscr R_{w,t}\succeq0
 \quad \mathfrak m\text{-a.e.}
