[Prop 24 of arXiv:2606.17472, '2606.17472'] If $\E_0[X_1^2]=\infty$, then we have
\begin{align*}
  \mu_{[a,b]}(dy)&:=\delta_b(dy),\\
  k([a,b])&:=0.
\end{align*}
If $\E_0[X_1^2]<\infty$, then we have on $[a,b]$ 
\begin{align*}

  \mu_{[a,b]}(dy)&=\frac{\sigma^2}{2\E_0[X_1^2]}\delta_a(dy)+\frac{1}{\E_0[X_1^2]}\overline{\overline{\Pi}}(a-y)1_{(a,b)}dy\\
  &\qquad +\left(\frac{1}{2}+\frac{1}{2\E_0[X_1^2]}\int_{(-\infty,a-b)}(a-b-x)^2 \Pi(dx)\right)\delta_b(dy),
   \stepcounter{equation}\tag{\theequation}
\end{align*}and 
\begin{align*}

k([a,b])&=\frac{b-a}{2\E_0[X_1^2]}+\frac{1}{(\E_0[X_1^2])^2}\int_{(a,b)}(y-a)\overline{\overline{\Pi}}(a-y)dy\\
&\qquad +\frac{b-a}{2(\E_0[X_1^2])^2}\int_{(-\infty,a-b)}(a-b-x)^2 \Pi(dx),
  \stepcounter{equation}\tag{\theequation}
\end{align*}
where $\Pi$ denotes the \Levy\ measure, $\overline{\Pi}(y):=\Pi(-\infty,y)$, and $\overline{\overline{\Pi}}(z):=\int_{-\infty}^z\overline{\Pi}(y)dy$.

