[Proposition prop:squares_joint_distributions of arXiv:2507.22011, 'Random Lozenge Waterfall:\\Dimensional Collapse of Gibbs Measures'] For the hexagon with $L$-dependent sides as in (def:prelimit_barcode_kernel of the paper),
	for any $m$ and any distinct $t_1,\ldots,t_m\in \mathbb{Z}$,
	$|t_i|<L$, we have
	\begin{equation}

		\operatorname{\mathbb{P}}\bigl\{
			\textnormal{there are square lozenges at
			$(t_i+T_0,X_0)$, $i=1,\ldots,m$}
		\bigr\}
		=
		\det
		\bigl[
			K^{\mathrm{barcode}}_{(L)}(t_i,t_j)
		\bigr]_{i,j=1}^m.
	\end{equation}

[Proposition 8 of arXiv:2609.04143, 'The Geometry of Real Anisotropic Bohnenblust--Hille Constants'] Let $\mathbf q=(q_1,\ldots,q_m)$ be a Bohnenblust--Hille exponent.

\begin{enumerate}
\item If $p=\min_{1\le i\le m}q_i$ and $\mathbf q^+=(q_1,\ldots,q_m,2)$, then
\[
 C_{\mathbf q^+}^{(m+1)}\le A_p^{-1}C_{\mathbf q}^{(m)}.
\]

\item Suppose that two adjacent coordinates of $\mathbf q$ are $(q,p)$ with $1\le p\le q\le2$, and let $\mathbf q'$ be obtained by replacing them by $(p,q)$. Then
\[
 \textcolor{black}{C_{\mathbf q}^{(m)}\le C_{\mathbf q'}^{(m)}.}
\]
Consequently, if $\mathbf t$ is any permutation of the vector with $k$ copies of $p$ followed by $m-k$ copies of $2$, then
\[
 \textcolor{black}{C_{\mathbf t}^{(m)}
 \le C_{(\underbrace{p,\ldots,p}_{k},\underbrace{2,\ldots,2}_{m-k})}^{(m)}.}
\]

\item Let $2\le k\le m$. If $p_k\le q_i\le2$ for every $1\le i\le m$, then
\begin{equation}
 C_{\mathbf q}^{(m)}
 \le A_{p_k}^{-(m-k)}B_{\R,k}^{\mult}.
\end{equation}
\end{enumerate}

