[Lemma lem:vecmeas_variationformula of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] (Variation Formula and Variation of Weak Limits) Let X be a metric space with Borel $\sigma$-field $\mathcal{B}(X)$ and let $B$ be a Banach space. Then the following holds:
	\begin{itemize}
		\item[(i)] For all $V \in \mathrm{ca}(\mathcal{B}(X),B)$ it holds
		\begin{equation}
			\| V \| = \sup\bigg\{ \sum_{i \in I} \Big\| \int_X f_i \, dV \Big\|_B \,\Big|\, (f_i)_{i\in I} \text{ is a partition of unity} \bigg\},
		\end{equation}
		where we call $(f_i)_{i \in I}$ a \emph{partition of unity} iff $(f_i)_{i \in I}$ is a family of continuous (bounded) functions in $[0,1]^X$ with a finite index set $I$ s.th.\ it holds $\sum_{i\in I} f_i = 1$.
		\item[(ii)] Let $(V_n)$ be a sequence of vector measures in $\mathrm{ca}(\mathcal{B}(X),B)$, converging weakly to the vector measure $V \in \mathrm{ca}(\mathcal{B}(X),B)$. Then it holds $\| V \| \leq \liminf_n \| V_n \|$. In particular, if $(V_n)$ is uniformly bounded w.r.t.\ $\| \cdot \|$, then $V$ is of bounded variation.
	\end{itemize}

