\widetilde{T}_{w^{-1}}^{-1}=q^{-\ell(w)} \sum_{y \leq w}(-1)^{\ell(y) - \ell( w)} R_{y, w}(q) \widetilde{T}_y.
\end{equation*}
Equivalently, using \eqref{eq:RIdentity}, we have  
\begin{align*}
{T}_{w^{-1}}^{-1}&=\sum_{y \leq w}(-1)^{\ell(y) - \ell( w)} R_{y, w}(q) q^{\ell(y)} {T}_y\\
&= \sum_{y \leq w}q^{\ell(w)}R_{y, w}(\tfrac1q) {T}_y.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

