[Lemma 13 (Rate of convergence for \textup{($i$)}) of arXiv:2608.29465, 'Deciding When to Decide:\\Testing Operational Suboptimality Under Distributional Shift'] Suppose the assumptions of Lemma~\ref{lem:termI_consistency} hold. Let $\varepsilon_n$ denote the uniform convergence rate of the empirical OCE risk over $\mathcal{Z} \times \Theta$ such that $\varepsilon_n = O_p(n^{-1/2})$ (as established in Lemma \ref{lem:rate_oce_criterion}). Under the $\kappa$-degree local inverse stability condition (Assumption \ref{assm:error_bound_P0}), it holds that:
\begin{equation}

\mathrm{dist}(\hat\theta,\Theta_{\rm inv})=O_p\!\big(\varepsilon_n^{1/\kappa}\big).
\end{equation}
Furthermore, the deployment optimality gap satisfies:
\begin{equation}

\Big|\Delta(z_0;\hat \theta,\rho,\mathbb P_1)-\Delta(z_0;\theta^\star,\rho,\mathbb P_1)\Big|
\le \delta_{\rm inv}+O_p\!\big(\varepsilon_n^{1/\kappa}\big).
\end{equation}
In particular, since $\varepsilon_n \asymp n^{-1/2}$, we have $\mathrm{dist}(\hat\theta,\Theta_{\rm inv})=O_p(n^{-1/(2\kappa)})$. If $\delta_{\rm inv}=0$, the gap strictly converges at the rate $O_p(n^{-1/(2\kappa)})$.

[Theorem thm:unstable_manifold of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Assume the same setting as in Theorem (thm:stable_manifold of the paper). Furthermore, suppose that \( \mu_1 > 0 \) holds for the first Lyapunov exponent and $\mu^{+}:=\min\lbrace\mu_j : \ \mu_j>0\rbrace$. Then there exists a $\theta_r$-invariant set of full measure $\tilde{\Omega}$ and a family of immersed submanifolds \( U^{\upsilon}_{loc}(\omega)\) of \( E_\omega \), for \( 0 < \upsilon < \mu^{+} \) and \( \omega \in \tilde{\Omega} \), satisfying the following properties for every \( \omega \in \tilde{\Omega} \):
			\begin{itemize}
				\item[(i)] There exist random variables \( \tilde{\rho}_{1}^{\upsilon}(\omega) \) and \( \tilde{\rho}_{2}^{\upsilon}(\omega) \), positive and finite on \( \tilde{\Omega} \), such that
				\begin{align*}
					\liminf_{p \to \infty} \frac{1}{p} \log \tilde{\rho}_i^{\upsilon}(\theta_{-pr} \omega) \geq 0, \quad i = 1, 2,
				\end{align*}
				and
				\begin{align*}
					&\left\lbrace \xi_{\omega} \in E_\omega\, :\, \exists \lbrace \xi_{\theta_{-pr}\omega}\rbrace_{p\geqslant 1} \text{ s.t. } \varphi^{m}_{\theta_{-pr}\omega}(\xi_{\theta_{-pr}\omega}) = \xi_{\theta_{(m-p)r}\omega} \text{ for all } 0 \leq m \leq p, \right. \\
					&\quad \left.\sup_{p \geqslant 0} \exp(p\upsilon)\Vert \xi_{\theta_{-pr}\omega} - Y_{\theta_{-pr}\omega} \Vert_{E_{\theta_{-pr}\omega}} < \tilde{\rho}_{1}^{\upsilon}(\omega)\right\rbrace \subseteq U^{\upsilon}_{loc}(\omega) \\
					&\quad \subseteq \left\lbrace\xi_{\omega} \in E_\omega\, :\, \exists \lbrace \xi_{\theta_{-pr}\omega}\rbrace_{p\geqslant 1} \text{ s.t. } \varphi^{m}_{\theta_{-pr}\omega}(\xi_{\theta_{-pr}\omega}) = \xi_{\theta_{(m-p)r}\omega} \text{ for all } 0 \leq m \leq p, \right. \\
					&\quad \left. \sup_{p\geqslant 0} \exp(p\upsilon)\Vert \xi_{\theta_{-pr}\omega} - Y_{\theta_{-pr}\omega} \Vert_{E_{\theta_{-pr}\omega}} < \tilde{\rho}_{2}^{\upsilon}(\omega)\right\rbrace.
				\end{align*}

				\item[(ii)] The tangent space at \( Y_{\omega} \) to \( U^{\upsilon}_{loc}(\omega) \) is given by
				\begin{align*}
					T_{Y_{\omega}}U^{\upsilon}_{loc}(\omega) = {U}_{\omega}:=\oplus_{i: \mu_{i}>0}H^{i}_{\omega}.
				\end{align*}

				\item[(iii)] For \( m \geqslant M(\omega) \),
				\begin{align*}
					U^{\upsilon}_{loc}(\omega) \subseteq \varphi^{m}_{\theta_{-mr}\omega}( U^{\upsilon}_{loc}(\theta_{-mr}\omega)).
				\end{align*}

				\item[(iv)] For \( 0 < \upsilon_{1} \leqslant \upsilon_{2} < \mu^{+} \),
				\begin{align*}
					U^{\upsilon_{2}}_{loc}(\omega) \subseteq U^{\upsilon_{1}}_{loc}(\omega).
				\end{align*}
				Also, for \( m \geqslant M(\omega) \),
				\begin{align*}
					U^{\upsilon_{1}}_{loc}(\omega) \subseteq \varphi^{m}_{\theta_{-mr}\omega}( U^{\upsilon_2}_{loc}(\theta_{-mr}\omega)),
				\end{align*}
				and consequently, for \( \xi_{\omega} \in U^{\upsilon}_{loc}(\omega) \),
				\begin{align*}
					\limsup_{p\rightarrow \infty} \frac{1}{p}\log\Vert \xi_{\theta_{-pr}\omega} - Y_{\theta_{-pr}\omega}\Vert_{E_{\theta_{-pr}\omega}} \leqslant -\mu^{+}.
				\end{align*}

				\item[(v)] 
				\begin{align*}
					\limsup_{p \rightarrow \infty} \frac{1}{p}\log\left[\sup\left\lbrace\frac{\Vert \xi_{\theta_{-pr}\omega} - \tilde{\xi}_{\theta_{-pr}\omega}\Vert_{E_{\theta_{-pr}\omega}}}{\Vert \xi_{\omega} - \tilde{\xi}_{\omega}\Vert_{E_{\omega}}}\, :\, \xi_{\omega} \neq \tilde{\xi}_{\omega},\ \xi_{\omega}, \tilde{\xi}_{\omega} \in U^{\upsilon}_{loc}(\omega)\right\rbrace\right] \leqslant -\mu^{+}.
				\end{align*}
			\end{itemize}

[Proposition 18 of arXiv:2609.03875, 'Measure theory without infinities'] Let $\fm{\Theta}{\Lambda}$ be a family of sets such that $A\cap B\in \Theta(\lambda)\cap\Theta(\lambda')$ for every $\lambda,\lambda'\in \Lambda$, $A\in\Theta(\lambda)$, and $B\in\Theta(\lambda')$. Let $\mathcal Q = \bigcup_{\lambda\in \Lambda} \Theta(\lambda)$.
  \begin{enumerate}
  \item [(i)] Let $\Theta(\lambda)$ be a semi-ring for every $\lambda\in \Lambda$. Then $\mathcal{Q}$ is a semi-ring.
  \item [(ii)] Let $\Theta(\lambda)$ be a $\delta$-ring for every $\lambda\in \Lambda$. Then $\kappa(\mathcal Q)$ is a $\delta$-ring.
  \item [(iii)] Let $\mf A$ be an HTM. A map $\fm{\eta}{\mathcal{Q}}$ is an $\mf A$-valued $\sigma$-additive function if and only if $\eta|_{\Theta(\lambda)}$ is an $\mf A$-valued $\sigma$-additive function for every $\lambda\in \Lambda$. 
  \end{enumerate}

