[Corollary 36 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] The conclusion of \cref{thm:canonical-packet} holds in each of the following cases.
\begin{enumerate}[label=\textup{(\roman*)}]
\item $\epsilon_t=0$ for all $t$ and $\mu$ is any partition;
\item $\epsilon_t=1$ for all $t$ and $\mu=\delta=(n-1,n-2,\ldots,0)$.
\end{enumerate}

[Lemma 47 of arXiv:2605.28677, 'Weak universality for stochastic reaction-diffusion models\\ with long-range correlated no'] For every $k \in \NN \setminus \{0 \} $, we have  
	$ \EE [ W_{k , \varepsilon}( Z_{\varepsilon}
	) ]= 0 $. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 13 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] The projected process $(J_n,S_n)_{n\geq0}$ under the split construction is the original Markov renewal chain. The split embedded chain is positive Harris recurrent and its invariant probability $\widehat\pi$ satisfies

\begin{equation*}
\widehat\pi(\mathfrak a)=\varepsilon\pi(C).
\end{equation*}

Consequently, if the split chain starts from the atom, the mean return time to $\mathfrak a$ is

\begin{equation*}
\Ee_{\mathfrak a}[\tau_{\mathfrak a}]=\frac{1}{\varepsilon\pi(C)},
\end{equation*}

where $\tau_{\mathfrak a}$ denotes the first return time to $\mathfrak a$ after time zero. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop translation-invariance of arXiv:2604.14122, 'The scaling limit of random walk and\\ the intrinsic metric on planar critical percolation'] Let $U\subset[0,1]^2$ be open and simply connected. Let $D_1$ be the support of $(\mathcal{X}\cap \overline{V},\mathfrak{d}_V)_{V\in\mathfrak{C}_U}$ and $D_2$ be the support of $U^*$. Let $\mu_U(\cdot\mid\cdot)$ be a probability kernel from $D_2$ to $D_1$ such that $\mu_U(\cdot\mid U^*)$ is a.s.\ equal to the conditional law of $(\mathcal{X}\cap \overline{V},\mathfrak{d}_V)_{V\in\mathfrak{C}_U}$ given $U^*$. Then for each $z \in \mathbf C$ such that $U+z\subset[0,1]^2$ one can choose versions of $\mu_U$ and $\mu_{U+z}$ such that for all events $A$ in $D_1$ and $u \in D_2$ we have
\begin{equation*}
    \mu_U(A\mid u)=\mu_{U+z}(A+z\mid u+z).
\end{equation*}
where $A+z$ denotes the event that the translated metrics $(\mathcal{X}\cap \overline{V}-z,\mathfrak{d}_{V}(\cdot+z,\cdot+z))_{V\in\mathfrak{C}_{U+z}}$ are in the event $A$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 15 of arXiv:2608.07239, 'Unified framework for asymptotically uniform iterative construction of generalised random '] Consider the iterative directed hypergraph process on $V$, $\d^{(1)}$, $\d^{(2)}$, $\d'^{(1)}$, $\d'^{(2)}$, and $X$. Let $$d_{\max}:=\max\{d_1^{(1)},\ldots,d_n^{(1)},d_1^{(2)},\ldots,d_n^{(2)},d_1'^{(1)},\ldots,d_m'^{(1)},d_1'^{(2)},\ldots,d_m'^{(2)}\},$$ and for $k^{(1)},k^{(2)}\geq1$, let $c_{k^{(1)},k^{(2)}}$ be the required number of hyperarcs of order $(k^{(1)},k^{(2)})$, and let $x_{k^{(1)},k^{(2)}}$ be the number of hyperarcs in $X$ of order $(k^{(1)},k^{(2)})$. Define
		\begin{align}
			\rho_{k^{(1)},k^{(2)}}&:=k^{(1)}!k^{(2)}!\binom{c_{k^{(1)},k^{(2)}}}{2}\left(\frac{\lambda_{\d^{(1)}}}{s^{(1)}}\right)^{k^{(1)}}\left(\frac{\lambda_{\d^{(2)}}}{s^{(2)}}\right)^{k^{(2)}}
			\\&\leq\binom{c_{k^{(1)},k^{(2)}}}{2}\left(\frac{k^{(1)}\lambda_{\d^{(1)}}}{s^{(1)}}\right)^{k^{(1)}}\left(\frac{k^{(2)}\lambda_{\d^{(2)}}}{s^{(2)}}\right)^{k^{(2)}},
			\\\rho_X&:=\sum_{(D,C)\in X}\frac{c_{|D|,|C|}|D|!|C|!}{(s^{(1)})^{|D|}(s^{(2)})^{|C|}}\prod_{v_{i^{(1)}}\in D}d_{i^{(1)}}^{(1)}\prod_{v_{i^{(2)}}\in C}d_{i^{(2)}}^{(2)}
			\\&\leq\sum_{k^{(1)}=1}^{d_{\max}}\sum_{k^{(2)}=1}^{d_{\max}}x_{k^{(1)},k^{(2)}}c_{k^{(1)},k^{(2)}}\left(\frac{k^{(1)}d_{\max}}{s^{(1)}}\right)^{k^{(1)}}\left(\frac{k^{(2)}d_{\max}}{s^{(2)}}\right)^{k^{(2)}}.
		\end{align}
		Assume that $s^{(1)}\leq s^{(2)}$ and consider the asymptotics as $s^{(1)}\to\infty$. Assume that $d_{\max}=O((s^{(1)})^{\sfrac14}/\log(s^{(1)}))$ and $\rho_{1,1},\rho_X=o(1)$. Then the total probability of rejection in the iterative edge-colored bipartite graph process is $O(d_{\max}^2/s^{(1)})$ in both iterations, and the probability of rejection afterwards is $O(\rho_{1,1}+\rho_{1,2}+\rho_{2,1}+\rho_X+1/s^{(1)})$. In particular, for $s^{(1)}$ large enough, there exists a simple directed hypergraph with out- and in degree sequences $\d^{(1)}$ and $\d^{(2)}$ and with hyperarcs not in $X$ and with orders $(d_1'^{(1)},d_1'^{(2)}),\ldots,(d_m'^{(1)},d_m'^{(2)})$. Furthermore, any such directed hypergraph is sampled with probability $(1+O(\mathscr{E}+\rho_{1,1}+\rho_X))\mathscr{P}$, where $\mathscr{E}:=\mathscr{E}(s^{(1)},d_{\max}^2)$ and
		\begin{align}
			\mathscr{P}&:=\exp\left(\tfrac12\lambda_{\d^{(1)}}\lambda_{\d'^{(1)}}+\tfrac12\lambda_{\d^{(2)}}\lambda_{\d'^{(2)}}+\lambda_{\d^{(1)},\d^{(2)}}\lambda_{\d'^{(1)},\d'^{(2)}}\right)
			\\&\quad\cdot\frac1{s^{(1)}!s^{(2)}!}\prod_{i=1}^{n}d_i^{(1)}!d_i^{(2)}!\prod_{k^{(1)}=1}^{d_{\max}}\prod_{k^{(2)}=1}^{d_{\max}}((k^{(1)}!k^{(2)}!)^{c_{k^{(1)},k^{(2)}}}(c_{k^{(1)},k^{(2)}})!),
		\end{align}
		which is asymptotically uniform. The total number of such directed hypergraphs is thus $(1+O(\mathscr{E}+\rho_{1,1}+\rho_X))\mathscr{P}^{-1}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 28 (Kunita) of arXiv:2506.11937, 'Random rotational invariance of integration by parts formulas within a Bismut-type approac'] Let $\Sigma=\mathbb{R}^e$ be the parameter set and let $\ p > min(e,2)$. Suppose that
    \begin{equation}
        \sup_{\lambda} \mathbb{E}\Bigg[\int_0^T |g_{\lambda}(r)|^p dr \Bigg] < \infty], \ \ \mathbb{E}\Bigg[\int_0^T |g_{\lambda}(r)-g_{\lambda'}(r)|^p dr \Bigg] < c_p |\lambda - \lambda'|^p
    \end{equation}
    where $\ g_{\lambda}(r)$ is $\ n$-times continuously differentiable with respect to $\lambda$ and, for $\ |i|\leq n$, the derivatives $\partial_{\lambda}^ig_{\lambda}(r)$ satisfy $\ (\ref{lemma tecnico 1})$. Then the family of stochastic integrals $\ (\int_0^t g_{\lambda}(r) dW_r)_t$ has a modification
which is $\ n$-times continuously differentiable with respect to $\lambda$ a.s. Forall $\ |i| \leq n$, we have that
    \begin{equation*}
        \partial^i_{\lambda}\int_0^t g_{\lambda}(r) dW_r = \int_o^t \partial^i_{\lambda}g_{\lambda}(r) dW_r \  \ \forall (t,\lambda) \ a.s.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

Let $( ar{M},  ar{g})$ be a Lorentzian manifold with future-directed timelike unit normal vector field $e_0$ along a spacelike hypersurface $\Sigma$. The second fundamental form $h$ of $\Sigma$ is the symmetric bilinear form defined for tangent vectors $X, Y \in T\Sigma$ by $h(X, Y) =  ar{g}( ar{
