		&= \sum_{m,n=1}^d \sigma_{(m,m),(n,n)} \cdot t","release_manifest_digest":"sha256:14cfdd0dd8976dfd88782bb548cf8daff91f077c4142c999d6b063286b43aaa7","revision_digest":"sha256:8fd8f8a4269690503c063068aa74fa7381c09b352f5a6695081fc35f4f74e397","source_id":"arxiv:2411.14876","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

body:
[Ppn 27 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Recall $F^{\rv}$ from \eqref{e:F.rv}
and $F^{\rvi}$ from \eqref{e:F.rvi}. For all $t\in \R$, we have
    \[
        \P(F^{\rv} \ge t) \le 4\P(F^{\rvi} \ge t)\,.
    \]

\begin{proof}
Recall from \eqref{e:F.rv} that the function $F^{\rv}$ is defined by the supremum of the function $\acute{F}$ over $\|\by\|^2=N$. The function $\acute{F}$ is given by the sum of $F_w$ from \eqref{e:F.w}, $F_v$ from \eqref{e:F.v}, and $F_x$ from \eqref{e:F.x}. Note that we can decompose $F_v = F_{v+}+ F_{v-}$ where         \[
    F_{v+}(\bG,\by)
    \equiv\sum_{j\in J_+}
        \frac{\hv_j}{M}
        \sum_{a\in B_j}
        \frac{(\bg^a,\by)^2}{N}
    = \sum_{j\in J_+}
        \frac{\hv_j}{MN}
        \|\bG^{B_j}\by\|^2\,,
    \]
and $F_{v-}$ is defined analogously. By calculus, we can rewrite
    \begin{align*}
    F_{v+}(\bG,\by)
    &= \sup\bigg\{
    \frac{2(\btheta_+,\bG^{B_+} \by)}{M\sqrt{N}}
            - \sum_{j\in J_+} \frac{\|\btheta_+(B_j)\|^2}{M\hv_j}
            :\btheta_+
            \in\R^{B_+}
    \bigg\}\,,\\
    F_{v-}(\bG,\by)
    &=\inf\bigg\{
    \frac{2(\btheta_-,\bG^{B_-} \by)}{M\sqrt{N}}
            - \sum_{j\in J_-} \frac{\|\btheta_-(B_j)\|^2}{M\hv_j}
    :\btheta_-
            \in\R^{B_-}
    \bigg\}\,.
    \end{align*}
For standard gaussians $Z_+, Z_-$ independent of all else, let
    \begin{align*}
    \tilde{F}_{v+}(\bG,Z_+,\by)
    &\equiv
    \sup\bigg\{
    \frac{2(\btheta_+,\bG^{B_+} \by) + 2\|\btheta_+\|\|\by\| Z_+}{MN^{1/2}}
            - \sum_{j\in J_+} \frac{\|\btheta_+(B_j)\|^2}{M\hv_j}
    :\btheta_+\in\R^{B_+}
    \bigg\}\,,\\
    \tilde{F}_{v-}
    (\bG,Z_-,\by)
    &\equiv
    \inf\bigg\{
    \frac{2(\btheta_-,\bG^{B_-} \by) + 2\|\btheta_-\|\|\by\| Z_-}{MN^{1/2}}
            - \sum_{j\in J_-} \frac{\|\btheta_-(B_j)\|^2}{M\hv_j}
            :\btheta_-\in\R^{B_-}
    \bigg\}\,.
    \end{align*}
Note that we have $Z_+,Z_-\ge0$ with probability $1/4$; on this event, the quantities $F_{v\pm}$ are dominated by the quantities $\tilde{F}_{v\pm}$. Let
    \begin{align*}
    \tilde{F}^{\rv}
    &\equiv
    \sup_{\|\by\|^2=N}
    \bigg\{
    F_w(\by)
    +F_x(\tbmeta,\by)
    +
    \tilde{F}_{v+}(\bG,Z_+,\by)
    +
    \tilde{F}_{v-} (\bG,Z_-,\by)
    \bigg\}\,.
    \end{align*}
Finally, in order to compare $\tilde{F}_{v\pm}$ with $\bar{F}_{v\pm}$ as defined by \eqref{e:bar.F.v.plus} and \eqref{e:bar.F.v.minus}, let $Z$ denote a standard gaussian random variable, and let us compare the gaussian processes
    \begin{align*}
    A(\btheta,\by)
    &\equiv (\btheta,\bG\by)
        + \|\btheta\|\|\by\| Z\,,\\
    B(\btheta,\by)
    &\equiv\|\by\| (\hbg,\btheta) + \|\btheta\| (\dbg,\by)\,.
    \end{align*}
We then calculate
    \begin{align*}
    \E[A(\btheta,\by)
        A(\btheta',\by')]
    &= (\btheta,\btheta')
        (\by,\by')
        +\|\btheta\|\|\btheta'\|
        \|\by\|\|\by'\|\,,\\
    \E[B(\btheta,\by)
        B(\btheta',\by')]
    &=(\btheta,\btheta')
    \|\by\|\|\by'\|
    +\|\btheta\|\|\btheta'\|
    (\by,\by')\,.
    \end{align*}
These quantities are equal whenever $\btheta=\btheta'$ or $\by=\by'$. In general, the $A$-covariances upper bound the $B$-covariances: by scaling, it suffices to show this in the case $\btheta,\btheta',\by,\by'$ are all unit vectors, in which case it reduces to the inequality
    \[
    1-(\btheta,\btheta')
        -(\by,\by')
        +(\btheta,\btheta')
        (\by,\by')
    = \Big(1-(\btheta,\btheta')\Big)
    \Big(1-(\by,\by')\Big) \ge0\,.
    \]
Therefore, we can use Slepian's inequality to compare $\tilde{F}_{v+}$ with $\bar{F}_{v+}$; and we can use Gordon's inequality to compare $\tilde{F}_{v-}$ with $\bar{F}_{v-}$. This implies that $\tilde{F}^{\rv}$ is stochastically dominated by
$\tilde{F}^{\rvi}$. The claim follows by recalling the above observation that
$F^{\rv} \le \tilde{F}^{\rv}$
with probability at least $1/4$.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 34 (Metric form of the Transference Principle) of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $(X,d,\mu)$ be a Polish probability space. Let $G:\R_+\to\R_+$ be a continuous, non-increasing function decaying to zero at infinity and let $\mathcal A,\mathcal D\subset \mathcal{B}(X)$. Then, the following are equivalent:
\begin{enumerate}
    \item For all
$A\in\mathcal A$ and $B\in\mathcal D$, one has
\[
    \mu(A)^{\frac12}\mu(B)^{\frac12}
    \leq
    G(d(A,B));
\]
\item For every pair of measurable functions $f \in \mathcal{F}(\mathcal{A})$ and $ g\in \mathcal{F}\left(\mathcal{D}\right)$ and measurable, non-decreasing function $W \colon \R_+  \to \R_+$ that satisfy \begin{align*}
f(x)^\frac{1}{2}g(y)^\frac{1}{2} &\leq W(d(x,y)) \quad \text{ for all } 
\quad(x,y)\in X\times  X,
\end{align*}
one has
\[
\left(\int_{X} f(x) d\mu(x) \right)^{\frac{1}{2}} \left(\int_{X} g(y) d\mu(y) \right)^{\frac{1}{2}}\leq \int_{\R_+} W(r) d(-G)(r).
\]
\end{enumerate}
We say that the space $(X,d,\mu)$ satisfies the metric-Santal\'o inequality induced by $G$ on the domain $(\mathcal A,\mathcal D)$.

[Lemma 5 (Negligibility of the last mesh interval) of arXiv:2608.16256, 'Error Distribution of the Local Linearization Method for Stochastic Differential Equations'] \label[lemma]{le:ll_principal_boundary_new}
We have
\begin{equation}
    \bar M^n-\widetilde M^n
    \xrightarrow{\mathrm{ucp}}0 .
\end{equation}

[Proposition prop_SMA_1 of arXiv:2411.08846, 'On the Number of Crossings and Bouncings\\ of a Diffusion at a Sticky Threshold'] Let $X$ be the sticky Brownian motion of stickiness parameter $\rho>0 $, defined on the filtered probability space
	$(\Omega, \bF, (\bF_t)_{t\ge 0},\Prob_x) $ such that $\Prob_x $-a.s., $X_0=x $.
	Let $m_{\sqrt n \rho} $ be the measure defined for all $x\in \IR $ by
	\begin{equation} 
		m_{\sqrt n \rho}(\mathrm{d} x) = \,\mathrm{d} x + \sqrt n \rho \, \delta_{0}(\mathrm{d} x)
	\end{equation}
	and $(g_{n})_{n}$ a sequence of measurable real functions such that for all $x\in \IR$ 
	\begin{multline}

		\lim_{n \longrightarrow  \infty} \Bigbraces{ \frac{g_{n}^2(\sqrt n x)}{n} + 
			\frac{m_{\sqrt n \rho}(g^{2}_n)}{\sqrt n}  \\
			+  \frac{ \bigbraces{\int_{-\infty}^{+\infty} |x| g_n(x) \,\mathrm{d} x}  \big( 1 + \log(n) \big)  g_n(\sqrt n x)}{n}
			+   \frac{{   \big( 1 + \log(n) \big)  m_{\sqrt n \rho}(|g_n|)}}{\sqrt n}}
		= 0
	\end{multline}
	and $\lim_{n\to \infty}m_{\sqrt n \rho}(g_n) = M$.
	Then, for all $t \geq 0$,
	\begin{equation}
		\frac{1}{\sqrt n} \sum_{i=1}^{[nt]}g_n(\sqrt n \hfprocess{X}{}{i-1})  \xlongrightarrow[n \rightarrow  \infty]{\Prob_x}  M \loct{X}{0}{t}.
	\end{equation}
	Also, if~(equation eq_connd_gn_aggreg of the paper) holds and $\sup_n \bigbraces{m_{\sqrt n \rho}(|g_n|)} <\infty$ then the above convergence is localy uniform in time, in $\Prob_x$-probability. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm expsum_2 of arXiv:2609.04092, 'Short character sums of inhomogeneous polynomials'] Let $n\geq 1$ and $k\geq 5$. Let $F=G_1(X_1)+\cdots + G_{n}(X_{n})$, where each $G_j$ has degree $k$.  Let
$\mathbf{H}=(H_1,...,H_n)$ with $H\leq H_i\leq 2H$ for some $H>0$, and suppose $p^{2/(k-2)}\ll K \leq H < p$.
Then for all $\varepsilon	>0$,
    \begin{align*}
        p^{-(k+1)}\sum_{\substack{(a_0,...,a_{k})\not\equiv \mathbf{0}\\ \; ( \text{mod} \; p)^{k+1}}}|S({\bf a};F)|^2 \ll_{n,k,\varepsilon} H^{2n}
        K^{2n(1- \sigma(k))+\varepsilon},
    \end{align*}
where $\sigma(k) = 1/k(k-1)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Def_DOA of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] For a point process $\Pi$, we say a point process $\theta$ is in the domain of attraction of $\Pi$, written as  $ \theta \in \textrm{Dom}_{\lambda}(\Pi)$, if $\theta_t^\lambda$ given by (equation theta_t-def of the paper) started from $\theta_0^\lambda = \theta$ converges to $\Pi$ in the sense that for all $f \in C_c^+(\mathbb R),$ 
    \begin{equation}
        \mathbb E[e^{-\langle f , \theta_t^\lambda \rangle}]\longrightarrow \mathbb E[e^{-\langle f , \Pi \rangle}]
    \end{equation}
    as $t \to \infty.$

[Proposition 17 (Frequency-dependent martingale approximation) of arXiv:2608.22342, 'Completely Positive Entropy and Fourier Central Limit Theorems for Stationary Random Measu'] For every $\theta\in E_Y$ and every
$h\in C_c^\infty(\bR^d;\bC)$,
\begin{equation}

    \E\|V_R(h,\theta)-V_R^D(h,\theta)\|_H^2
    \longrightarrow0.
\end{equation}

[Lem diag_error of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] There exists a constant $c>0$ such that
\begin{equation*}
    \frac1{\mathsf{Z}_L} \sum_{\mathbf{n}\in{\mathbb N}^m\setminus\{\mathbf{1}\}}\frac1{(\mathbf{n}!)^2}\abs{\mathsf{Q}_m^{(\mathbf{n})}(\mathbf{M}_L,\mathbf{N}_L,\mathbf{T}_L)} \leq e^{-c L}
\end{equation*}
for all sufficiently large $L>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:pythHS of arXiv:2509.02996, 'Group-averaged Markov chains: mixing improvement'] Let $G$ be a finite group with Haar measure $\mu$ that acts on $\mathcal{X}$ and $\pi$ is assumed to be $G$-invariant. Assume that $P,M$ (and hence $P_{da}$ by Proposition (prop:inheritance of properties of the paper)) are HS operators and $M,P_{da} \in \mathcal{D}(G,\nu)$, where the measure $\nu$ satisfies $(g,h) \overset{D}{=} (g^{-1},h^{-1}) \sim \nu$. We have
	\begin{align*}
		\left\lVert P-M \right\rVert_{\mathrm{HS}}^2 &= \norm{P-P_{da}}_{\mathrm{HS}}^2 + \norm{P_{da}-M}_{\mathrm{HS}}^2.
	\end{align*}
	If $\mathcal{X}$ is finite, we also have
	\begin{align*}
		\left\lVert P-M \right\rVert_{\mathrm{F}}^2 &= \norm{P-P_{da}}_{\mathrm{F}}^2 + \norm{P_{da}-M}_{\mathrm{F}}^2.
	\end{align*}

