body:
[Defi 9 (Diagonal negative dependence) of arXiv:2608.30357, 'Mean convergence for Banach space-valued random elements indexed in measure spaces'] \mbox{ }
\begin{enumerate}[(i)]
\item Two $\cX$-valued random elements $X, Y$ are said to be \textit{diagonally negatively dependent} if 
\begin{align}
\bP(X \in A, Y \in A) \le \bP(X \in A)\,\bP(Y \in A), \quad \forall A \in \cB(\cX),
\end{align}
or equivalently,
$\Cov(\1_{\{X \in A\}}, \1_{\{Y \in A\}}) \le 0$ for all $A \in \cB(\cX)$.

\item Let $\varnothing \neq I \subseteq \bR$ and $M \in \bN \cup \{0\}$.
A family $\{Y_i : i \in I\}$ of $\cX$-valued random elements is \textit{$M$-pairwise diagonally negatively dependent} if $Y_i, Y_j$ are diagonally negatively dependent for all $i, j \in I$ with $|i-j|>M$.
When $M=0$, we then simply call $\{Y_i : i \in I\}$ \textit{pairwise diagonally negatively dependent}.

\end{enumerate}

[Lemma LEM:T2 of arXiv:2512.23957, 'Concentration and fluctuations of sine-Gordon measure around topological multi-soliton man'] There exist a constant $c>0$ such that for sufficiently large $D$, we have
\begin{align*}
\nu^\perp_{m_{\xi_1,\dots,\xi_k}}(B_\varepsilon^c) \lesssim e^{-c D L_\varepsilon  },
\end{align*}

\noindent
uniformly in $\xi_1,\dots,\xi_k \in [-L_\varepsilon, L_\varepsilon]^k$ and $L_\varepsilon \ge 1$, where 
\begin{align*}
B_\varepsilon:=\{ \|v \|_{L^2( [-L_\varepsilon, L_\varepsilon] )}^2 \le  D  L_\varepsilon    \}.
\end{align*}

