body:
[Theorem 64 (Functorial Collapsing) of arXiv:2608.29157, 'Dilator-based analysis of $\KP$'] Suppose that $H = E(F+1+G)$ for $E=\varepsilon$ or $\varphi_\lambda$ for a non-empty well-order $\lambda$, a \emph{flower} $F$, and $\Gamma$ be a sequent of $(\forall \Sigma)^{\ttL(u)_{\ttOmega}}$-formulas in the language of $\RS_H$. Suppose we are given
    \begin{enumerate}
        \item  A preproof of $H[\ttX] \sststile{\ttOmega+1}{\alpha} \Gamma$, and
        \item An order-preserving map $f\colon \ttX\to \ttY + \psi_\Omega H(\ttY+\Omega)$.
    \end{enumerate}
    Now, let us fix $\eta\in H(\ttY +\psi_\Omega H(\ttY+\Omega))$ such that $\hat\sfK(\eta)<\eta$ and
    \begin{equation*}
        \eta > \max\bigl\{\psi^{-1}\bigl(f(v)\bigr) \bigm| v\in \ttX \land f(v) \in \psi_\Omega H(\ttY+\Omega)\bigr\}.
    \end{equation*}
    If we define
    \begin{equation*}
        \hat{\alpha}[\eta] = \eta + \omega^{\ttOmega + H(f)(\alpha)} \in H(\ttY + \psi_\Omega H(\ttY+\Omega)),
    \end{equation*}
    then we have
    \begin{equation*}
        H\bigl(\Id+\psi_\Omega H(\Id+\Omega)\bigr)[\ttY] \sststile{\psi(\hat{\alpha}[\eta])}{\psi(\hat{\alpha}[\eta])} \bfL(u)_{H(f)}[\Gamma]^\eta,
    \end{equation*}
    where $A^\eta$ is the formula obtained from $A$ by replacing every occurrence of $\forall x\in \ttL(u)_\ttOmega$ to $\forall x\in \ttL(u)_{\psi(\eta)}$.

