[Theorem thm:FKG of arXiv:2505.02685, 'On the Spectral Expansion of Monotone Subsets of the Hypercube'] Let $(X,Y)$ be a pair of real-valued random variables with bounded second moment. Suppose there is a constant $c\in[0,1)$ such that for all $a,b\in\mathbb{R}$,
\begin{equation}
\ensuremath{\mathbb{P}} \left[ X\geq a, Y\geq b \right]\geq c\cdot\ensuremath{\mathbb{P}} \left[ X\geq a \right]\cdot\ensuremath{\mathbb{P}} \left[ Y\geq b \right],
\end{equation}
then we must have
\begin{equation}
\Cov{X}{Y}\geq -\sqrt{(1-c)\cdot\mathrm{Var} \left[ X \right]\cdot\mathrm{Var} \left[ Y \right]}.
\end{equation}

[Lemma 4 of arXiv:2606.31936, 'Coupling and Maximal Inequalities for Graph-Dependent Empirical Processes'] Let \(G_n=(N_n,V_n)\) be a uniform doubling with polynomial growth graph of dimension $d$. Then, for every \(q\ge 1\), there exists
 	a partition \(\mathcal P_n(q)=\{B_1,\ldots,B_M\}\) of \(N_n\) such that
 	\begin{align}
 		\max_{1\le m\le M}|B_m|
 		\lesssim q,
 	\end{align}
 	and, for every \(r\ge 1\),
 	\begin{align}
 		\chi\big(H_{n,r}(\mathcal P_n(q))\big)
 		\lesssim
 		1+\frac{r^d}{q}.
 	\end{align}
 Also,
 	\begin{align}
 	\bar N_{B_m}(r)
 	: =
 	\frac{|S_{B_m}(r)|}{|B_m|}
 	\lesssim
 	\min\{r^{d-1},q\}.
 \end{align}
Moreover,
\begin{align}
	\operatorname{diam}(B_m)
	:=
	\max_{i,j\in B_m} d_n(i,j)
	\le 2 q^{1/d},
\end{align}

[Definition 9 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Fix $k \in \mathbb{N}$, $\vec{x}, \vec{y} \in \weyl_k$, $a,b \in \mathbb{R}$ with $a < b$, and two continuous functions $f: [a,b] \rightarrow (-\infty, \infty]$ and $g: [a,b] \rightarrow [-\infty,\infty)$. This means that either $f \in C([a,b])$ or $f \equiv \infty$, and similarly for $g$. In addition, we assume that $f(t) > g(t)$ for $t \in[a,b]$, $f(a) > x_1$, $f(b) > y_1$, $g(a) < x_k$, $g(b) < y_k$. With this data we let $\mathbb{P}_{\mathrm{avoid}}^{a,b,\vec{x},\vec{y}, f,g}$ denote the law of $k$ independent Brownian bridges $\{B_i\}_{i =1}^k$ with law $\mathbb{P}_{\mathrm{free}}^{a,b,\vec{x}, \vec{y}}$, conditioned on the event 
\begin{equation}
E^{f,g}_{\mathrm{avoid}} = \{f(t) > B_1(t) > B_2(t) > \cdots > B_k(t) > g(t) \mbox{ for all } t\in [a,b]\}.
\end{equation}
As explained in \cite[Definition 2.7]{DEA21}, we have that $E^{f,g}_{\mathrm{avoid}}$ is measurable and $\mathbb{P}_{\mathrm{free}}^{a,b,\vec{x}, \vec{y}}(E^{f,g}_{\mathrm{avoid}}) > 0$, so that the law $\mathbb{P}_{\mathrm{avoid}}^{a,b,\vec{x},\vec{y}, f,g}$ on $C(\llbracket 1, k \rrbracket \times [a,b])$ is well-defined. The expectation with respect to $\mathbb{P}_{\mathrm{avoid}}^{a,b,\vec{x},\vec{y}, f,g}$ is denoted by $\mathbb{E}_{\mathrm{avoid}}^{a,b,\vec{x},\vec{y}, f,g}$. When $f = \infty$ and $g = -\infty$, we drop them from the notation and simply write $\mathbb{P}_{\mathrm{avoid}}^{a,b,\vec{x},\vec{y}}$ and $\mathbb{E}_{\mathrm{avoid}}^{a,b,\vec{x},\vec{y}}$.

[Definition of arXiv:2609.02073, 'Existence of closed non-planar $p$-elasticae'] For $p\in (1,\infty)$, the immersed curve $\gamma \in W^{2,p}(0,1;\R^n)$ is called a \textit{$p$-elastica} if there exists $\lambda \in \R$ such that 
  \begin{equation*}
    \frac{d}{d\varepsilon} \left( \mathcal{B}_p[\gamma+\varepsilon \eta] + \lambda \mathcal{L}[\gamma + \varepsilon \eta] \right) \bigg|_{\varepsilon=0} = 0 \qquad \forall \eta \in C_c^\infty(0,1;\R^n).
  \end{equation*}

