body:
[Lemma lem:cancellation of arXiv:2607.07598, 'Universal Central Limit Theorem for non-exchangeable interacting diffusions'] Suppose Assumption (assum.main of the paper) holds with $k \ge 0$. Then, for each $t \in [0,T]$, and each bounded measurable $G : {\mathbb{R}}^d \times {\mathbb{R}}^d\to {\mathbb{R}}^d$,
			\begin{align}
				\sum_{i=1}^n {\mathbb{E}}\Big[\Big|\sum_{j=1}^n \widehat{\xi}_{ij}\,G(X_t^i,X_t^j)\Big|^2\Big]
				&\lesssim \Vert G\Vert_\infty^2\Big( \sum_{i,j=1}^n \widehat{\xi}_{ij}^2
				+ \sum_{i=1}^n\Big(\sum_{j=1}^n|\widehat{\xi}_{ij}|\Big)^2\max_{i,j\in[n]}\xi_{ij}\Big), 
			\end{align}
			and
			\begin{align}
				\begin{split}
					\sum_{i=1}^n {\mathbb{E}}\Big[\Big|\sum_{j=1}^n \widehat{\xi}_{ji}\,G(X_t^j,X_t^i)\Big|^2\Big]
					\lesssim \Vert G\Vert_\infty^2&\Big(  \sum_{i,j=1}^n \widehat{\xi}_{ij}^2 + \sum_{i=1}^n\Big(\sum_{j=1}^n|\widehat{\xi}_{ji}|\Big)^2\max_{i,j\in[n]}\xi_{ij} \\
					&
					+ \sum_{i=1}^n\Big(\sum_{j=1}^n\widehat{\xi}_{ji}\Big)^2\Big).
				\end{split}

			\end{align}
			Also, for each $g_t \in C_b^1({\mathbb{R}}^d\times{\mathbb{R}}^d)$ satisfying $ 		{\mathbb{E}}[g_t(Y_t^1,Y_t^2)] = 0$,
			where $Y^1$ and $Y^2$ are independent copies of the  McKean-Vlasov solution from Proposition (lem:preliminaries of the paper)(equation lem:preliminaries:i of the paper), we have
			\begin{align} 
				{\mathbb{E}} \bigg[\Big( \sum_{i,j=1}^{n} g_t(X_t^i,X_t^j)\Big)^2 \bigg]
				\lesssim
				n^2 \|g_t\|_\infty^2 + n^3 \|\nabla g_t\|_\infty^2.
			\end{align}

