[Proposition 30 of arXiv:2604.03213, 'Asymptotic expansion for transport maps \\ between laws of multimatrix models'] Given the following objects,
	\begin{itemize}
        \item $\cU$ and $\cV$ bases of Hilbert spaces $H_{\cU}$ and $H_{\cV}$,
		\item $Z^N = (Z_i^N)_{1\leq i\leq d}$ deterministic matrices of size $N$,
		\item $X^N = (X_e^N)_{e\in \cU}$ independent GUE random matrices of size $N$,
		\item $x = (x_e)_{e\in \cV}$ free semicircular variables,
		\item $f\in \cL^1(\cB)$ with $\cB$ the basis of $\C^d\oplus H_{\cU}\oplus H_{\cV}$.
	\end{itemize}
	Then if our weights satisfy Assumption \ref{Assum:weight}, with $\tau_N$ the trace on $\cA_N$ the free product of $\M_N(\C)$ and the von Neumann algebra generated by $x$, one has the following,
	\begin{align}

		\forall e\in \cU,\quad \E\left[\tau_N\left( X_e^N f(Z^N,X^N,x) \right)\right] &= \frac{1}{N} \sum_{1\leq i,j\leq N} \E\left[\tau_N\left(E_{i,j}\ \partial_e f(Z^N,X^N,x)\# E_{j,i}\right)\right] \\
        &\quad +\frac{1}{N} \E\left[ \sum_{1\leq i,j\leq N} \tau_N\otimes\tau_N\left( \widetilde{\partial}_e f(Z^N,X^N,x) \#\left(E_{j,i} \otimes E_{i,j} \right)\right) \right]. \nonumber \nonumber
	\end{align}
	\begin{equation}

		\forall e\in \cV,\quad \tau_N\left(x_ef(Z^N,X^N,x)\right) = \tau_N\otimes\tau_N\left(\partial_e f(Z^N,X^N,x)\right).
	\end{equation}

[Proposition lim_moments of arXiv:2607.21443, 'The critical KPZ scale for the averaging process'] Fix $k\ge2$, $t\ge0$, and $\phi_1,\ldots,\phi_k\in\ensuremath{\mathcal C}_b(\mathbb{R})$. Set $\lambda=7/8$ and $\beta_N\coloneqq\beta_{\lambda,N}$. Let $\mathbf x^N=(x_1^N,\ldots,x_k^N)\in\mathbb{Z}^k$ be such that $N^{-1/2}\mathbf x^N\to\mathbf z=(z_1,\ldots,z_k)\in\mathbb{R}^k$. Then,
	\begin{equation}
	\mathbb{E}\bigg[
		\prod_{j=1}^k
		\mathfrak H_{\beta_N,N}(t,x_j^N,\phi_j)
	\bigg]
	\xrightarrow[N\to \infty]{}
	\mathbf E_{\mathbf z}^{{\rm BM}^{\otimes k}}
	\bigg[
		\exp\bigg\{\frac12\sum_{1\le i<j\le k}L_t^{W^i-W^j}\bigg\}
		\prod_{j=1}^k\phi_j(W_t^j)
	\bigg]\; \text{.}
	\end{equation}
	In particular, when $\mathbf x^N=\mathbf 0\in \mathbb{Z}^k$ and $\phi_1=\ldots=\phi_k=\phi\in \ensuremath{\mathcal C}_b(\mathbb{R})$, this gives the $k$-th moment asymptotics of $\ensuremath{\mathcal Y}_{7/8,N}(t,\phi)$.

