body:
[Theorem 2 (OSSS inequality) of arXiv:2605.31344, 'Subcritical sharpness for real-valued spin models'] Let $\Lambda\subset V$ be finite and let $\overline{E}(\Lambda) \subset E$ be the set of edges with at least one endpoint in $\Lambda$. Let $\mu$ be a measure on $(\sfa,\omega)\in (\mathbb{R}^+)^{\Lambda}\times \{0,1\}^{\overline{E}(\Lambda)}$ that satisfies weak monotonicity (Definition \ref{Def: weak monotonicity}) and
    for any vertex $z \in \Lambda$ and any increasing function $f: \{0,1\}^{\overline{E}(\Lambda)} \rightarrow [0, 1]$ depending only on the states of edges,
    \begin{equation}
        \mu [f(\omega) \mid \omega_{xz} = 0 \; \forall x \sim z]
        \leq \mu [f(\omega) \mid  \mathsf{a}_z = 0].
    \end{equation}
    Then for any increasing function $f: \{0, 1\}^{\overline{E}(\Lambda)} \rightarrow [0,1]$ depending only on the states of edges and any admissible decision tree $T$,
    \begin{align*}
        \mathrm{Var}_{\mu}(f) \leq \sum_{xy \in \overline{E}(\Lambda)} \delta_{xy}(f, T) \mathrm{Cov}_{\mu} (f, \omega_{xy}).
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 (\cite{DiC}) of arXiv:2604.00882, 'On some extensions of generalized counting processes'] For all fixed $\nu \in (0, 1]$ we have
	\begin{equation}
		M^\nu(t) \stackrel{d}{=} \sum_{i=1}^{N_\Lambda^\nu(t)} X_i, \qquad t \ge 0,
	\end{equation}
	where $N_\Lambda^\nu(t)$ is a fractional Poisson process (see Section \ref{fractionalPoisson}), with intensity $\Lambda = \lambda_1 + \lambda_2 + \dots + \lambda_k$, and  $\{X_n : n \ge 1\}$ is a sequence of i.i.d. random variables, independent of $N_\Lambda^\nu(t)$, such that for any $n \in \mathbb{N}$
	\begin{equation}
		\mathbb{P}\{X_n = j\} = \frac{\lambda_j}{\Lambda}, \qquad j = 1, 2, \dots, k
	\end{equation}
	and where both $N_\Lambda^\nu(t)$ and $X_n$ depend on the same parameters $\lambda_1, \lambda_2, \dots, \lambda_k$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lmuboundtwo of arXiv:2601.09537, 'Gene genealogies in haploid populations evolving according to sweepstakes reproduction'] Suppose a population evolves according to Def.\ (hapltwo of the paper).  Then there is a constant $B > 0$ with 
\begin{esplit}{lmuboundextwo}
 \frac{(N)_2}{c_N} \EE{ \frac{X_1(X_1 - 1)X_2(X_2 - 1) }{ (S_N)_4 }\ensuremath{\mathds{1}_{\left\{ S_N \ge N \right\}}} | \ensuremath{{\alpha_1}}, \ensuremath{{\kappa}} }\frac{ \varepsilon_N}{(N)_2} \le  \frac{B}{N^{1-\ensuremath{{\alpha_1}}-\ensuremath{{\kappa}} }} \varepsilon_N.
\end{esplit}

[Corollary 7 of arXiv:2506.12632, 'Point process convergence of extremes in $K$-symmetric exclusion'] Suppose $p$ satisfies Condition \ref{lighttail}, $\nu$ satisfies Condition \ref{initialprofilecond}, and $\eta_0 \sim \nu_L$, where $L \uparrow \infty$ as $t \to \infty$. Let $0 \le m_0 < m_1 < \cdots < m_k$. 

\begin{enumerate}[(a)]

\item If $L \big(\frac{\log t}{t}\big)^{1/2} \to \psi \in (0, \infty]$, then 
\begin{align*}
	&\bigg( \frac{X^{(m_0)}_{t/K}}{\sigma b_t} - a_t, \ldots,  \frac{X^{(m_k)}_{t/K}}{\sigma b_t} - a_t \bigg) \underset{t\to\infty}{\Longrightarrow} \bigg( - \log  \frac{T_{m_0}}{c_\nu\sigma(1 - e^{-\psi/\sigma})}, \ldots, - \log  \frac{T_{m_k}}{c_\nu\sigma(1 - e^{-\psi/\sigma})} \bigg). 
\end{align*}

\item If $L \big(\frac{\log t}{t}\big)^{1/2} \to 0$, then 
\begin{align*}
	&\bigg( \frac{X^{(m_0)}_{t/K}}{\sigma b_{t,L}} - a_{t,L}, \ldots,  \frac{X^{(m_k)}_{t/K}}{\sigma b_{t,L}} - a_{t,L} \bigg) \underset{t\to\infty}{\Longrightarrow} \bigg( - \log  \frac{T_{m_0}}{c_\nu}, \ldots, - \log  \frac{T_{m_k}}{c_\nu} \bigg). 
\end{align*}

\end{enumerate}

