[Lemma 10 of arXiv:2608.30991, 'A block-Toeplitz approach to the spectrum of the Neumann-Poincaré operator on self-similar'] For $m \neq 0$, the Toeplitz blocks in Lemma~\ref{lem: Toeplitz structure Single layer} satisfy the exponential decay bounds:
	\begin{equation*}
		\| \tilde{S}_m \|_{\mathcal{L}(W_0^{s,p}(\Gamma_0))} \le \begin{cases} 
			C r^{m}, & m > 0, \\ 
			C r^{|m|(d-1)}, & m < 0, 
		\end{cases}
	\end{equation*}
	for some constant $C > 0$ independent of $m$.

[Lemma lem:LTtoZ of arXiv:2411.18563, 'Lower tails for triangles inside the critical window'] Under Condition~(ConditionThm1 of the paper),
\begin{align}
 \frac{1}{n^{3/2}}\log \mathbb{P}_p(X\leq \eta \mathbb{E} X)= -\frac{c}{2} - \log (1 -\zeta) \eta \frac{c^3}{6} +  \frac{1}{n^{3/2}}\log Z(\lambda,\zeta) +o(1)\,.
\end{align}
Moreover, if $\varepsilon>0$ is fixed and $\mathcal{E}_n$ is any event such that
\begin{equation}
    \mu_{\lambda,\zeta}(\mathcal{E}_n) \le e^{- \varepsilon n^{3/2}} \,,
\end{equation}
then
\begin{equation}
    \mathbb{P}_{p} ( \mathcal{E}_n | X \le \eta \mathbb{E} X )\le e^{-\varepsilon n^{3/2}/2} \, .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

