[Lemma Lem-properties-of-V-L of arXiv:2412.08932, 'Gaussian heat kernel asymptotics for conditioned random walks'] For any  $a\in \supp V$, there exist constants $c_1, c_2 >0$ such that, for any $n\geqslant 1$ and $x\in [a,\infty)$,
\begin{align} 
c_1 \leqslant V(x)L\left(  \frac{x}{\sigma \sqrt{n}} \right) \leqslant  c_2 \sqrt{n}.
\end{align}

[Theorem 14 (\cite{LN}) of arXiv:2604.23656, 'Doubly Reflected Backward SDEs Driven by $G$-Brownian Motion with Quadratic Generator'] Suppose that $\xi$, $f$, $g$, $L$ and $U$ satisfy (A1)-(A4). Then the doubly reflected $G$-BSDE with data $(\xi,f,g,L,U)$ has a unique solution $(Y,Z,A)$. In fact, for any $2\leq \alpha<\beta$, we have $Y\in S^\alpha_G(0,T)$, $Z\in H_G^\alpha(0,T)$ and $A\in S_G^{\alpha}(0,T)$. Moreover,  we have
	\begin{align*}
		\lim_{n\rightarrow \infty}\hat{\mathbb{E}}\left[\sup_{t\in[0,T]}|Y_t-\bar{Y}^n_t|^\alpha\right]=0, 
	\end{align*}
	where for each $n\in\mathbb{N}$, $(\bar{Y}^n,\bar{Z}^n,\bar{A}^n)$ is the solution to the following reflected $G$-BSDE:
	\begin{equation*}
		\begin{cases}

			\bar{Y}^n_t=\xi+\int_t^T f(s,\bar{Y}^n_s,\bar{Z}^n_s)ds+\int_t^T g(s,\bar{Y}^n_s,\bar{Z}^n_s)d\langle B\rangle_s\\
			\ \ \ \ \ \ \ \ -n\int_t^T(\bar{Y}^n_s-U_s)^+ds-\int_t^T \bar{Z}^n_sdB_s+(\bar{A}^n_T-\bar{A}^n_t), \\
			\bar{Y}^n_t\geq L_t, \forall t\in[0,T], \{-\int_0^t (\bar{Y}^n_s-L_s)d\bar{A}^n_s\}_{t\in[0,T]} \textrm{ is a non-increasing $G$-martingale}.
		\end{cases}
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 33 (Bounds on the matrix elements) of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] The following bounds hold,

\begin{align*}

\big| \big( \mf{m}_{0}^{\vsg}\big)_{ij} \big|  &\leq

\left\{  \ba{cc} \ln|\lambda_{j+1}^{\vsg} - \lambda_i^{\vsg}|  - \ln|\lambda_j^{\vsg} - \lambda_i^{\vsg}|  + \pi &  j > i   \vspace{2mm}  \\

\ln 2 + \mathbbm{1}_{\{ \ups_j = -\vsg \}}

\sqrt{ \Big| \tfrac{   \lambda_j^{-\vsg} - \lambda_j^{\vsg}  }{ \lambda_i^{\vsg} \, - \lambda_j^{-\vsg} }  \Big| }

                        \ln\frac{\sqrt{2}+1}{\sqrt{2}-1}   &  j < i   \ea \right.  \vspace{2mm} \\

\big| \big( \mf{m}_{1}^{\vsg}\big)_{ij} \big| &\leq

\left\{  \ba{cc} \ln|\lambda_{i}^{\vsg} - \lambda_j^{\vsg}|  - \ln|\lambda_i^{\vsg} - \lambda_{j+1}^{\vsg}|  + \pi &  i >j+1   \vspace{2mm}\\

\ln 2  + \mathbbm{1}_{\{ \ups_j = -\vsg \}} \sqrt{ \Big| \tfrac{  \lambda_{j+1}^{\vsg} - \lambda_{j+1}^{-\vsg}   }

            {\lambda_{j+1}^{-\vsg} - \lambda_{i}^{\vsg} }  \Big| }

                                                            \ln \frac{\sqrt{2}+1}{\sqrt{2}-1} &  i < j+1 \, . \ea \right.

\end{align*}

[Lemma 50 of arXiv:2603.00353, 'Aldous-type Spectral Gaps in Unitary Groups'] We have the following two formulas for $P$ in terms of $Q$:
    \begin{enumerate}
        \item  $P = Q - t\frac{\partial Q}{\partial t}$.
        \item  For $t\in\R_{<1}$, $P = \left(1+\frac{nt}{1-t}\right)Q - \frac{t}{1-t}x\frac{\partial Q}{\partial x}$.
    \end{enumerate}

[Proposition 8 of arXiv:2604.15226, '\bfseries Nonlinear Schrödinger equations with spatial white noise potential on full space'] Let $0<\mu\le1$. There exists a unique solution in $\CC(\IR,L_\mu^2(\IR^d)\cap H^1(\IR^d))$ to the linear equation \eqref{LinearEquation} for $v_0\in L_\mu^2(\IR^d)\cap H^1(\IR^d)$. Denoting as $S_t$ the associated flow, it satisfies
\begin{equation}
\|S_tv_0\|_{L_{\sigma}^2(\IR^d)\cap H^\sigma(\IR^d)}\lesssim\|v_0\|_{L_{\sigma}^2(\IR^d)\cap H^\sigma(\IR^d)}
\end{equation}
for any $\sigma\in[0,1]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 2 of arXiv:2606.10336, 'From Pitman's local times representation to the Gorin-Shkolnikov identity and beyond'] We have:
\begin{equation}

\int_0^1 e(t)dt -\frac{1}{2} \int_0^\infty \ell_x^2 dx = \int_0^\infty \left(I_x - \frac{1}{2} \ell_x^2 \right) dx.
\end{equation}

