[Defn of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] Suppose $\Omega$ is a simply connected domain $(\Omega \subsetneq \mathbb{C})$, let $\partial \Omega$ be its Carathéodory boundary (prime ends) and consider the Schottky double $S=\Omega^{\text {double }}$, which equips with the canonical involution $\iota \equiv \iota_\Omega: S \rightarrow S, z \mapsto z^*$. 

Then, for a double divisor $\left(\boldsymbol{\sigma}^{+}, \boldsymbol{\sigma}^{-}\right)$, we define the associated divisor on the Schottky double $S$ by
\begin{equation}
\boldsymbol{\sigma} = \boldsymbol{\sigma}^{+} + \boldsymbol{\sigma}_*^{-}, \quad \text{where} \quad \boldsymbol{\sigma}_*^{-} := \sum \sigma_j^{-} \cdot z_j^*,
\end{equation}
and each $z_j^*$ denotes the image of $z_j$ under the canonical involution $\iota$ of $S$. Accordingly, $\boldsymbol{\sigma}_*^{-}$ is the pushforward of $\boldsymbol{\sigma}^{-}$ under $\iota$.

[Lemma lem: Diagonalization of arXiv:2608.30443, 'On smooth holosphere solutions to compressible Euler equation'] Assume (equation eq: Parameters of the paper). Let 
\begin{equation}

\left|\begin{array}{l}
w=w_3+W\\
\sigma=\sigma_3+\Sigma\\
\frac{dt}{dx}=-\frac{1}{\Delta}
\end{array}\right., \ \ X=\left|\begin{array}{l} W\\\Sigma\end{array}\right., \ \ Y=P^{-1}X=\left|\begin{array}{ll} \tilde{W}\\\tilde{\Sigma} \end{array}\right.
\end{equation}
then (equation eq: Autonomous System of the paper) becomes:
\begin{equation}

\frac{dY}{dt}=\frac{1}{c_+-c_-}\left|\begin{array}{l}
\mathcal G_1\\
\mathcal G_2
\end{array}\right.
\end{equation}
with
\begin{eqnarray}

\nonumber \mathcal G_1&=&(c_+-c_-)\lambda_+\tilde{W}+\tilde{d}_{20}\tilde{W}^2+\tilde{d}_{11}\tilde{W}\tilde{\Sigma}+\tilde{d}_{02}\tilde{\Sigma}^2+\tilde{d}_{30}\tilde{W}^3+\tilde{d}_{21}\tilde{W}^2\tilde{\Sigma}+\tilde{d}_{12}\tilde{W}\tilde{\Sigma}^2+\tilde{d}_{03}\tilde{\Sigma}^3\\
& = & -\Delta_1+c_+\Delta_2,
\end{eqnarray}
\begin{eqnarray}

\nonumber \mathcal G_2&=&(c_+-c_-)\lambda_-\tilde{\Sigma}+\tilde{e}_{20}\tilde{W}^2+\tilde{e}_{11}\tilde{W}\tilde{\Sigma}+\tilde{e}_{02}\tilde{\Sigma}^2+\tilde{e}_{30}\tilde{W}^3+\tilde{e}_{21}\tilde{W}^2\tilde{\Sigma}+\tilde{e}_{12}\tilde{W}\tilde{\Sigma}^2+\tilde{e}_{03}\tilde{\Sigma}^3\\
& = & \Delta_1-c_-\Delta_2
\end{eqnarray}
and where the values of the coefficients are collected in (equation eq: Coefficients of Autonomous System of the paper), (equation eq: Coefficients of Autonomous System 2 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 74 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Fix $q \in (0,1)$, $c \in [0,1)$, and set $p = \frac{q}{1-q}$, $\sigma = \sqrt{p(1+p)}$. Let $\{d_n \}_{n \geq 1}$ be a sequence of positive reals, such that $d_n \rightarrow \infty$ as $n \rightarrow \infty$. Fix $b > 0$, put $T_n = \lceil b d_n \rceil$, and let $Y^n \in \mathfrak{W}_2$ be a sequence, such that 
\begin{equation}
\lim_{n \rightarrow \infty}\sigma^{-1} d_n^{-1/2} (Y_1^n -Y_2^n) = \alpha > 0.
\end{equation}
Finally, fix $s, t \in \mathbb{R}$, and let $\hat{q}, \hat{c}$ be as in (\ref{Eq.qchatsA}). Then, we have 
\begin{equation}
\lim_{n \rightarrow \infty} \sigma^2 d_n (1-q)^{2T_n} e^{2\im p T_n s \sigma^{-1} d_n^{-1/2} } Z(T_n, Y^n; \hat{q},\hat{c}) = e^{-bs^2} \cdot \frac{1}{(1 - \hat{c})^2} \cdot e^{-\alpha^2/4b} \cdot \frac{\alpha}{b \sqrt{4\pi b}}.
\end{equation}

[Lemma 3 of arXiv:2607.23791, 'Precise cover times for branching random walks on Hamming graphs: (iterated) logarithmic c'] Let $x,y\in\{0,1,\ldots,b-1\}^d$ and
$\ell=d-d_{\rm H}(x,y)$.  Then
\begin{equation}
 \E_x[J_y(t)]=\int_0^t e^{\lambda s}b^{-d}
 A_s^\ell B_s^{d-\ell}H_{d,\ell}(s)\dd s,
\end{equation}
where
\begin{equation}
 H_{d,\ell}(s)=\frac\ell d\frac{B_s}{A_s}
 +\frac{d-\ell}{d(b-1)}\left(\frac{A_s}{B_s}+b-2\right).
\end{equation}
In particular, if $x$ and $y$ are antipodal (meaning $\ell=0$), then
\begin{equation}
 \E_x[J_y(t)]=\int_0^t e^{\lambda s}b^{-d}
 \left(\frac{A_sB_s^{d-1}}{b-1}
       +\frac{b-2}{b-1}B_s^d\right)\dd s.
\end{equation}

[Theorem 10 of arXiv:2604.10244, 'Ergodicity for regime-switching neutral stochastic functional differential equations with '] Suppose that assumptions of Lemma \ref{thm:opao1} hold. Then there exists a constant $C>0$  such that for any   $\xi$, $\eta \in  C_r$,  $i \in \mbb S $, and  $t\geq 0 $,
		\begin{equation}
			\mbb{E}\|X^{\xi, i}_t-X^{\eta, i}_t\|_r^{p} \leq C \|\xi-\eta\|_{r}^{p}\e^{-\lambda t},
		\end{equation}	
		where $\lambda$ is given in \eqref{eq:bushi1}.

