[Theorem 8 of arXiv:2609.01826, 'An extension theory for fully fractional Schr\"odinger equations with memory'] For $z>0$ and $(\xi,\tau)\in L^+\cup L^-$, with $\theta(\xi,\tau)$ as in \eqref{phase}, let
\begin{equation}
m_s(z;\xi,\tau) := \frac{2^{1-s}}{ \G(s)} \left(z \theta(\xi,\tau)  |p(\xi,\tau)|^{1/2}\right)^s K_{s}\left(z \theta(\xi,\tau)  |p(\xi,\tau)|^{1/2}\right).
\end{equation}
Then, setting $a = 1-2s$, we have in $\mathscr S'(\R^{d+1})$
\begin{equation}
\mathscr F^{-1}_{(\xi,\tau)\to (x,t)}(m_s(z;\cdot))
=
P_a(z,t)\,S(x,t),
\end{equation}
where  
\begin{equation}
P_a(z,t)
=
\frac{e^{\,i\frac{(a-1)\pi}{4}}}{2^{1-a}\Gamma\!\left(\frac{1-a}{2}\right)}
\frac{z^{1-a}}{t^{\frac{3-a}{2}}}
e^{i\frac{z^2}{4t}}\mathbf 1_{(0,\infty)}(t).
\end{equation}

[Lemma Phi-eq of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] \noindent  Let $[\delta ,\eta ]\subset (0,1)$ be fixed. Then
for any sequence of indices $\{n_{k}\}_{k=0}^{\infty }$ with $
n_{k}\rightarrow \infty ,$ there exists a subsequence (still denoted $n_{k}$
) and a limit inverse map $T^{\ast }$ such that 
\begin{equation}
\Phi _{\infty }(x)=\Phi _{\infty }(T^{\ast }(x))\quad \text{for all }x\in
\lbrack \delta ,\eta ].  
\end{equation}

