[Lem 2 of arXiv:2506.17979, '\large\bf A remark on subharmonicity for symmetric Dirichlet forms'] We always have $D(\mathscr{E})_{e,D,\loc}^{\dag}\subset D(\mathscr{E})_{e,D,\loc}^{\diamond}\subset D(\mathscr{E})_{e,D,\loc}$. 
For $u\in D(\mathscr{E})_{e,D,\loc}^{\diamond}$ 
{\rm(}resp.~$u\in D(\mathscr{E})_{e,D,\loc}^{\dag}${\rm)} and 
$v\in D(\mathscr{E}_D)_c\cap L^{\infty}(D;{\m})$ {\rm(}resp.~$v\in D(\mathscr{E}_D)_c${\rm)}, 
the integration 
\begin{align}
\int_{D^2\setminus {\sf diag}}
(\tilde{u}(x)-\tilde{u}(y))(\tilde{v}(x)-\tilde{v}(y))J({\d} x{\d} y)
\end{align}
is well-defined.
Moreover, 
for $u\in 
D(\mathscr{E})_{e,\loc}^{\diamond}
$ {\rm(}resp.~$u\in 
D(\mathscr{E})_{e,\loc}^{\dag}
${\rm)}
and 
$v\in D(\mathscr{E}_D)_c\cap L^{\infty}(D;{\m})$ {\rm(}resp.~$v\in D(\mathscr{E}_D)_c${\rm)}, the integration 
\begin{align}
\int_{E^2\setminus {\sf diag}}
(\tilde{u}(x)-\tilde{u}(y))(\tilde{v}(x)-\tilde{v}(y))J({\d} x{\d} y)
\end{align}
is well-defined. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm of arXiv:2602.08591, 'The Yang--Mills measure on compact surfaces as a \\ universal scaling limit of lattice gau'] Assume $\Sigma$ is a smooth closed compact surface, $f$ a Morse function on $\Sigma$ with adapted metric $g$ such that $V=\nabla f$ satisfies the Smale transversality condition and $1$ is the only Lyapunov exponent of $V=\nabla f$. 
For any $L>0$, there exists an order function $m\in C^\infty(T^*\Sigma)$ in the previous sense such that for all $k\in \{0,1,2\}$,
the resolvent $$\left(\mathcal{L}_V+z\right)^{-1}:\mathcal{H}^{m,k}\left( \Sigma\right)\mapsto \mathcal{H}^{m,k}\left(\Sigma \right)$$
has a meromorphic extension to the half--space $\Re(z)>-L$. Moreover for $\Re(z)>0$, the resolvent $\left(\mathcal{L}_V+z\right)^{-1}$ acting on $C^\infty(\Lambda^kT^*\Sigma)$ is given by the formula
\begin{equation}
  \left(\mathcal{L}_V+z\right)^{-1}\psi:=\int_0^\infty e^{-tz} \left(\varphi_f^{-t*} \psi\right) dt 
\end{equation}
for all $\psi\in C^\infty(\Lambda^kT^*\Sigma)$.

For every pair $\psi_1\in \mathcal{H}^{-m,k}, \psi_2\in \mathcal{H}^{m,2-k}$, we have the following asymptotic expansion~:
\begin{equation}
\int_\Sigma \psi_1\wedge \varphi_f^{-t*}\psi_2=\sum_{a\in \text{Crit}(f)} \left(\int_{\Sigma} \psi_1 \wedge U_a \right)   \left(\int_{\Sigma} S_a \wedge \psi_2 \right)+O\left( e^{-t} \Vert \psi_1 \Vert_{\mathcal{H}^{-m,k}} \Vert \psi_2 \Vert_{\mathcal{H}^{m,2-k}} \right)     
\end{equation}
where $(U_a)_{a\in \text{Crit}(f)}$ (resp $(S_a)_{a\in \text{Crit}(f)}$) are anisotropic Sobolev currents supported on the unstable manifolds $\overline{W^u(a)},a\in \text{Crit}(f)$ (resp stable manifolds $\overline{W^s(a)},a\in \text{Crit}(f)$). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lem6 of arXiv:2412.05521, 'Random attractors for the stochastic Nernst-Planck-Navier-Stokes system with multiplicativ'] Let $v^\varepsilon(t_0)$ $\in$  $H^1$ and $c_i(t_0) \in H^1$. Then, there exists a positive constant $a$ depending on $D$, $\varepsilon_0$ and $\nu$, and a positive constant $A$ depending on the initial data, universal constants, $\varepsilon$ and $\omega$ such that 
		\begin{align}
			\|\nabla \rho (t)\|_{L^2}^2+\|\nabla \sigma (t)\|_{L^2}^2 \leq  Ae^{-a(t-t_0)},
		\end{align}
		for all $t \geq t_0$. 
		\begin{proof}
			Adding (equation b26 of the paper) to (equation b32 of the paper) together, the conclusion can be proved.
		\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 of arXiv:2609.04143, 'The Geometry of Real Anisotropic Bohnenblust--Hille Constants'] {Let $\mathbf q\in\mathcal B_m$, let
$q_{\min}:=\min_{1\le i\le m}q_i$, and set $d=d(\mathbf q)$. Then}
\begin{equation}
 C_{\mathbf q}^{(m)}\ge
 2^{\frac{(m-1)d}{2(2-d)}}
 \ge \exp\left(\frac{\log2}{4}(m-1)d\right).
\end{equation}

