[Theorem 2 of arXiv:2604.26026, 'Stochastic Ordering of Dependent Systems under Transformation Models and Archimedean Copul'] {Assume the functional $T$ is differentiable with respect to its first argument, the generators are such that $\phi_2\circ\psi_1$ is super-additive, $\psi_2$ is $d$-monotone with $d\geq 3$, $\boldsymbol{\alpha} \overset{m}\succeq \boldsymbol{\beta}$} and 
\begin{equation}

V(\beta) =\frac{1}{\psi_2^\prime\circ\phi_2(T(\beta,F))}\frac{\partial T}{\partial\beta}(\beta,F),\quad\beta\in A,
\end{equation}
is increasing, then {$X_{n:n}(\boldsymbol{\alpha})\geqst Y_{n:n}(\boldsymbol{\beta})$}.

[Proposition 14 (Fractional Hardy weights) of arXiv:2608.30551, 'Critical Discrete Hardy Inequalities in $L^p$'] Let \(p\in(1,\infty)\), \(\sigma\in(0,1/2)\), and
\(\alpha\in(\sigma,1/2)\). Put
\[
    h_{p,\sigma,\alpha}:=k_{-\alpha}^{q_p}
\]
and
\[
    \mu_{p,\sigma,\alpha}:=\nu_{k_{-\alpha}},
\]
where \(\nu_g\) is defined in
\eqref{abstract one-function reference measure}. Define
\begin{equation}
    w_{p,\sigma,\alpha}(x)
    :=
    \frac{1}{a_p+1}
    \frac{\Delta^\sigma k_{-\alpha}^{a_p}(x)}
         {k_{-\alpha}^{a_p}(x)}
    +
    \frac{a_p}{a_p+1}
    \frac{\Delta^\sigma k_{-\alpha}(x)}
         {k_{-\alpha}(x)},
    \qquad x\in\Z.
\end{equation}
Then
\[
    w_{p,\sigma,\alpha}(x)>0,
    \qquad x\in\Z,
\]
and, for every \(u\in\ell^p(\Z,\mu_{p,\sigma,\alpha})\),
\begin{equation}
    \mathcal E_p^{\Z,\sigma}(u)
    =
    \sum_{x\in\Z} w_{p,\sigma,\alpha}(x)|u(x)|^p
    +
    \mathcal R_{p,\sigma,\alpha}(u),
\end{equation}
where
\begin{align}
    \mathcal R_{p,\sigma,\alpha}(u)
    :={}&
    \frac{1}{p}
    \sum_{x,y\in\Z}
    F_p\left(
        \frac{u(x)}{k_{-\alpha}(x)^{q_p}},
        \frac{u(y)}{k_{-\alpha}(y)^{q_p}}
    \right)
    \notag\\
    &\qquad\times
    k_{-\alpha}(x)^{r_p}
    k_{-\alpha}(y)^{q_p}
    k_\sigma(x-y).

\end{align}
In particular,
\begin{equation}
    \mathcal E_p^{\Z,\sigma}(u)
    \geq
    \sum_{x\in\Z} w_{p,\sigma,\alpha}(x)|u(x)|^p .
\end{equation}

[Lemma 76 of arXiv:2510.27589, 'Geodesic switches and exceptional times in dynamical Brownian last passage percolation'] There exist constants $C,c,g>0$ such that for all $\delta>0$, all $n$ and all $m$ satisfying $ n/2\geq m\geq n^{1-3\delta/4}$, we have
 \begin{equation}

    \PP(\sup_{|x|\geq (1+m)^{2/3}n^{\delta}}Z_{\0}^{\n}(m+x,m)-Z_{\0}^{\n}(m,m)\geq - g(1+m)^{1/3}n^\delta)\leq Ce^{-cn^{3\delta/8}}.
  \end{equation}

