[Lemma 25 of arXiv:2609.01826, 'An extension theory for fully fractional Schr\"odinger equations with memory'] Let $0<s<1$ and set $a=1-2s\in(-1,1)$. Assume that
$u_0\in \Sm$ and define
\begin{equation}
U_0(X) := \int_0^\infty\int_{\R^d}
\mathbb P_a(X,Y_0,\sigma)\,u_0(y,-\sigma)\,dy\,d\sigma.
\end{equation}
Then $U_0\in L_a^2(\R^{d+1}_+)$.

[Lemma 50 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $\eta>0$, $k\geq 0$, $j\geq 1$, $l\geq 0$, with $j+2l\leq 2k+1$, and $b\geq v\vee(2\lambda)$.
Then
\begin{multline*}
\E\Big[\big\Vert
\ell_{0,b}^{2k+1-j-2l}V_{A_{0,b}}^{l}
\,:\Phi_{D\setminus A_{0,b}}^{j} :
\ind_{\{z\in A_{0,b}\text{~or~}\ell_{0,b}(z)=b\}}
\big\Vert_{H^{-\eta}(\C)}^{2}
\Big]
=
\\
j!
b^{4k+2-2j- 4l}
\int_{D^{2}}
\E
\big[
V_{A_{0,b}}(z)^{l}V_{A_{0,b}}(w)^{l}
G_{D\setminus A_{0,b}}(z,w)^{j}
\ind_{\{\ell_{0,b}(z)=\ell_{0,b}(w)=b\}}
\big]
\LK_{\eta}(\vert w-z\vert)
\,d^{2}z\,d^{2}w.
\end{multline*}

