[Thm 16 of arXiv:2609.03819, 'Stochastic damped wave and Euler-Bernoulli equations with singular locally H\"older contin'] Assume that conditions \ref{H0}, \ref{H0.5}, \ref{H1}, \ref{H2b}, \ref{H3} and 
    \begin{equation*}
\beta+\delta<\frac12\min\{\alpha,1-\alpha\}
\end{equation*}
hold true. Then, weak uniqueness in the sense of Definition \ref{uniqueness} holds for \eqref{abstract_formulation}.

[Lemma LEM:part of arXiv:2512.23957, 'Concentration and fluctuations of sine-Gordon measure around topological multi-soliton man'] Let $Q\in \mathbb{Z}$ with $|Q|=k$. Then we have 
\begin{align*}
Z_{\xi_1,\dots,\xi_k}=(Z_0)^k(1+O(e^{-cd_\varepsilon})),
\end{align*}

\noindent
uniformly in $\xi_1,\dots,\xi_k$ satisfying $\min_{i \neq j} |\xi_i-\xi_j| \ge d_\varepsilon \to \infty $ as $\varepsilon \to 0$, where $Z_0$ is the partition function of the Gaussian measure associated with the single-well operator $\mathcal{L}_0=-\partial_x^2+1-\textup{sech}^2(x)$.

