[Lemma 21 (Sasakian analogue of the K\"ahler $F$-formula) of arXiv:2608.29406, 'Partially Totally Real Submanifolds of Sasakian Manifolds'] For all tangent vector fields $X,Y$,
\begin{equation}
 (\bar\nabla_XF)Y=f h(X,Y)-h(X,PY).
\end{equation}
Hence $F$ is parallel if and only if
\begin{equation}
 h(X,PY)=f h(X,Y)
\end{equation}
for all $X,Y\in\Gamma(TM)$.

[Proposition 8 of arXiv:2609.00087, 'Translational tiles without spectra\\ in finite abelian $p$-groups'] The data in Appendix~\ref{app:f2-data} satisfy:
\begin{enumerate}
\item $A_2\oplus C_j=H_2$ for $0\le j\le16$;
\item $|D_2|=108$, and for every nonzero $v\in H_2$,
\[
 W_2(v)=0\quad\Longleftrightarrow\quad v\in D_2;
\]
\item the Cayley graph $\mathcal G_{D_2}$ has clique number $12$;
\item the minimum of $|W_2(v)|$ over
$v\notin D_2\cup\{0\}$ is $4$.
\end{enumerate}

[Lemma lem:multidimcontraction of arXiv:2510.13659, 'On the energy image density conjecture of Bouleau and Hirsch'] Let $(X,d,\mu,\mathcal{E}_p, \mathcal{F}_p, \Gamma_p)$ be a local $p$-Dirichlet space.
		For every $g\in \Lip(\mathbb{R}^n)$ with $g(0)=0$ and every $f=(f_1,\dots, f_n) \in (\mathcal{F}_p \cap C_0(X))^n$, we have  $g \circ f \in \mathcal{F}_p$ and
		\begin{equation} 
			\Gamma_p\langle g \circ f\rangle \le \left(1 \vee n^{(p-2)/2}\right)\LIP[g]^p \cdot \sum_{i=1}^n \Gamma_p\langle f_i\rangle.
		\end{equation}
		Moreover for all $f=(f_1,\dots, f_n) \in (\mathcal{F}_p \cap C_0(X))^n$, we have
		\begin{equation} 
			\Gamma_p\langle g \circ f\rangle \le \left(1 \vee n^{(p-2)/2}\right) (\Lip_a[g] \circ f)^p \cdot \sum_{i=1}^n \Gamma_p\langle f_i\rangle.
		\end{equation}

