[Lemma lem:two-point_duhamel_reminder_estimate of arXiv:2505.10256, 'Stochastic Oscillators out of equilibrium:\\ scaling limits and correlation estimates'] Assume (equation eq:assumption_initial_measure_volume of the paper) and (equation eq:assumption_initial_meaure_energy of the paper).
Then, there exists another constant $C=C(T, v_0,e_0)>0$ such that 
\begin{equation}

\begin{aligned}
\sup_{0\le t\le T} \| g^N_t\|_{\ell^\infty(\mathbb T_N)}
\le 
C\alpha_N^2N^2\Big( 1+ N^{2/3} \sup_{0\le t\le T} \| \varphi^N_t \|_{\ell^\infty(V_N^{(2)})} \Big) .
\end{aligned}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 (Retrieving concepts) of arXiv:2604.25470, 'A mathematical analysis of hierarchical Hopfield models'] In the above setting, assume that there exists an integer $t\in\{0,\dots,L-1\}$ such that the \emph{margin condition}
	\begin{equation}

		t+\rho < (1-\delta)L
	\end{equation}
	holds. 
	Then, for every fixed $\alpha$,
	\begin{equation}

		\mathbb P\bigl(\widehat\alpha(x)=\alpha\bigr)
		\ \ge\
		1
		-\mathbb P\bigl(t_*^{(\alpha)}\ge t+1\bigr)
		-\mathbb P\bigl(\mathcal G_\alpha(\delta,\rho)^c\bigr).
	\end{equation}
	Moreover, in the i.i.d.\ concept model one has the explicit bound
	\begin{equation}

		\mathbb P\bigl(t_*^{(\alpha)}\ge t+1\bigr)
		\ \le\
		P\,\binom{L}{t+1}\Bigl(\frac{L}{M}\Bigr)^{t+1}.
	\end{equation}
	In particular, if $P=P(N_f)$ and $M=M(N_f)$ are such that
	\begin{equation}

		P\,\binom{L}{t+1}\Bigl(\frac{L}{M}\Bigr)^{t+1} \xrightarrow[N_f\to\infty]{} 0
		\quad
		\text{and}
		\quad
		\max_{\alpha\le P}\mathbb P\bigl(\mathcal G_\alpha(\delta,\rho)^c\bigr)
		\xrightarrow[N_f\to\infty]{} 0,
	\end{equation}
	then the hierarchical retrieval \emph{succeeds with vanishing error} in the sense that
	\[
	\max_{\alpha\le P}\mathbb P\bigl(\widehat\alpha(x)\neq \alpha\bigr)
	\xrightarrow[N_f\to\infty]{}0 .
	\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:underline_comp of arXiv:2605.21265, 'The non-Hermitian minor process'] Let $X$ satisfy Assumption~(ass:chi of the paper)(i). Fix a (large) $L>0$ and (small) $c_0,\epsilon,\xi>0$. Let $\theta>0$ be a (possibly, $N$-dependent) small parameter. Consider $k_j\in [N]$, $z_j\in\mathbf{C}$, and $w_j=\mathrm{i}\eta_j$ with $\eta_j>0$, for $j=1,2$. Denote $x_j:=k_j/N$, $G_j:=G^{(k_j),z_j}_{x_j}(w_j)$ and assume that $x_1\le x_2$. Recall the definition of $\kappa_4$ from (equation eq:def_kappa_4 of the paper). It holds that
\begin{equation}
\mathbf{E} \langle G_1-\mathbf{E} G_1\rangle \langle G_2-\mathbf{E} G_2\rangle = \frac{1}{2x_1x_2N^2}\left(V_{12}+\bm{1}_{\beta=1}V_{1\overline{2}}+\kappa_4 x_1^2 U_1U_2\right) + \mathcal{O}_\theta\left(\left(\frac{1}{N\eta_*}+\frac{1}{\sqrt{N}}\right)\frac{N^\xi}{N^2\eta_1\eta_2}\right),

\end{equation}
uniformly in $x_j\in [c_0,1]$, $z_j\in\mathbf{C}$ with $\theta\le |\sqrt{x_j}-|z_j||\le L$, and $N^{-1+\epsilon}\le \eta_j\le N^L$, for $j=1,2$. In (equation eq:Cov_UV of the paper) we denoted $\eta_*:=\min\{\eta_1,\eta_2\}$ and
\begin{equation}
\begin{split}
U_j=U_j(x_j,\eta_j,z_j):=&\frac{\mathrm{i}}{\sqrt{2}}\partial_{\eta_j}m_j^2,\quad j=1,2,\\
V_{12}:=V\big((x_1,\eta_1,z_1),(x_2,\eta_2,&z_2)\big),\quad V_{1\overline{2}}:=V\big((x_1,\eta_1,z_1),(x_2,\eta_2,\overline{z}_2)\big),\\ 
V\big((x_1,\eta_1,z_1),(x_2,\eta_2,z_2)\big):=&\frac{1}{2}\partial_{\eta_1}\partial_{\eta_2}\log \left[1+x_1^2\left(u_1u_2|z_1z_2|\right)^2 -x_1^2m_1^2m_2^2 -2x_1u_1u_2\Re [z_1\overline{z}_2]\right],\\
\end{split}

\end{equation}
where $m_j:=m^{z_j}_{x_j}(w_j)$ and $u_j:=u^{z_j}_{x_j}(w_j)$.
The implicit constant in $\mathcal{O}_\theta(\cdot)$ is bounded from above by $\theta^{-D}$ for some (large) fixed $D>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 85 (Endpoint localized deterministic quadratic products) of arXiv:2607.10813, '2607.10813'] Let
\[
  \gamma=s_2-\frac12>0.
\]
For $A,B\in\set{X,Y}$,
\begin{equation}
  \norm{\la D\ra^\gamma\bigl(\chi AB\bigr)}_{L_{t,x}^{4/3}}
  \lesssim T^{1/4}
  \norm{A}_{\wt A_T}\norm{B}_{\wt B_T},
\end{equation}
where $\wt A_T$ denotes the corresponding $X$ or $Y$ intersection norm.  Moreover,
\begin{equation}
  \norm{\chi AB}_{L_T^1B_{2,\infty}^{\sigma-1}}
  \lesssim T^{1/4}
  \norm{A}_{\wt A_T}\norm{B}_{\wt B_T}.
\end{equation}
Both estimates have the corresponding bilinear difference form.

