[Definition 2 of arXiv:2512.08745, 'Variance strikes back: sub-game--perfect Nash equilibria in time‑inconsistent $N$‑player g'] Let $\hat\balpha^N \in \cA^N_N$, and $\varepsilon >0$. We define
\begin{align*}
&\ell_\varepsilon \coloneqq \inf \Big\{ \ell >0 : \exists (i,t,\alpha) \in \{1,\ldots,N\} \times [0,T] \times \cA_N, \;
\P \big[ J^i\big(t,\cdot,\hat\alpha^{i,N};\hat\balpha^{N,\smallertext{-}i}\big) < J^i\big(t,\cdot,\alpha\otimes_{t+\ell}\hat\alpha^{i,N};\hat\balpha^{N,\smallertext{-}i}\big) - \varepsilon \ell \big] >0 \Big\}.
\end{align*}
We say that $\hat\balpha^N$ is a {\rm sub-game--perfect Nash equilibrium} if for any $\varepsilon >0$, it holds that $\ell_\varepsilon >0$. We denote by $\mathcal{N}\!\mathcal{A}_{s,N}$ the set of all {\rm sub-game--perfect Nash equilibria}.

[Theorem mainresult:approximatelowrank of arXiv:2608.23765, '\texorpdfstring{Tight Majorizations and Convergence Rates\\ of Nuclear Norm Minimization I'] Let \allowbreak $\mathbf{X}_\star \in \R^{d_1 \times d_2}$ be arbitrary. Assume that the measurement operator $\mathcal{A}: \R^{d_1 \times d_2} \longrightarrow \R^m $ satisfies the NSP of order $r$ with constant $\eta_r < 1/3$.
If  $\left(  \mathbf{X}^{(k)}\right)_{k\geq 0}$ and $\left(\varepsilon_{k} \right)_{k \geq 0}$ 
are iterates and smoothing parameters of $\texttt{MatrixIRLS}$
with input $\mathbf{y} = \mathcal{A}(\mathbf{X}_\star)$, 
arbitrary initial weight operator $W^{(0)}$, rank estimate $\widetilde{r} = r$ and weight operators $\W{\mathbf{X}^{(k)}}{\varepsilon_{k}}$ that are admissible in the sense of (def:admissible:weightoperators of the paper), set
\begin{equation} 
\hat{k}:=  \min \left\{ k \in \mathbb{N}_0 :   \besterrNuc{\mathbf{X}_\star}{r}  > \frac{1}{9}\nucnorm{   \mathbf{X}^{(k)}  -\mathbf{X}_\star } \right\},
\end{equation}
with the convention $\min\varnothing=\infty$ (which holds whenever $\besterrNuc{\mathbf{X}_\star}{r}=0$).
Then the following two statements hold, in each case for the iterations carried out by (alg:algo1 of the paper).
\begin{enumerate}
\item  For $c_q$ as in (eq:c_q:def of the paper) and $A_{\eta_r}$, $B_{\eta_r}$ and $\widetilde{C}_{\eta_r}$ as in (eq:A_eta_r:def of the paper) and (eq:B_eta_r:def of the paper), it holds for all $k \in \mathbb{N}_0$ that
\begin{align} 
\mathcal{J}_{\varepsilon_{k}}( \mathbf{X}^{(k)}) -  \nucnorm{\mathbf{X}_\star} 
&\le 
\left(  1-  \frac{\widetilde{C}_{\eta_r}}{c_q \eta_1 d}   \right)^{\min ( k, \hat{k} )} 
\left(     \mathcal{J}_{\varepsilon_{0}}( \mathbf{X}^{(0)} ) -  \nucnorm{\mathbf{X}_\star} \right), \text{ and} \\

\nucnorm{\mathbf{X}^{(k)} -\mathbf{X}_\star }    
&\le
A_{\eta_r} \left(  1-  \frac{\widetilde{C}_{\eta_r}}{c_q \eta_1  d}   \right)^{\min (k, \hat{k}  )}   
\nucnorm{\mathbf{X}^{(0)} -\mathbf{X}_\star} + B_{\eta_r}  \besterrNuc{\mathbf{X}_\star}{r},
\end{align}
where $0 < \eta_1 \leq \eta_r$ denotes the order-one NSP constant of $\mathcal{A}$.
\item For all $k \ge \hat{k}$ with $\hat{k}$ as in (eq:hatk:def of the paper), it holds that
\begin{equation}
	\nucnorm{ \mathbf{X}^{(k)}  -\mathbf{X}_\star}    \le 41 \besterrNuc{\mathbf{X}_\star}{r}.
