[Definition of arXiv:2411.06838, 'Generalized Wasserstein Barycenters'] We say that the sequence of functionals $\mathcal{E}_k:\mathcal{P}_2(H) \to \mathbb{R}$ $\Gamma$-converges to the functional $\mathcal{E}:\mathcal{P}_2(H) \to \mathbb{R}$ in $\mathcal{P}_2(H)$, with respect to the weak and strong topologies (or that $\mathcal E_k$ Mosco-converges to $\mathcal E$), if
	\begin{align*}
		&(i)\ \liminf_{k \to \infty} \mathcal E_k(\mu_k) \geq \mathcal E(\mu)\qquad \forall \mu_k \to \mu\quad \text{in }P_2^w(H);\\
		&(ii)\ \forall \mu\in \mathcal{P}_2(H) \ \exists \mu_k \to \mu\ \text{in }(\mathcal{P}_2(H),W_2): \limsup_{k \to \infty}\mathcal E_k(\mu_k) \leq \mathcal E(\mu).
	\end{align*}

[Proposition 8 of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] There exists $c_\star\in(0,\infty)$ such that the quantity $\epsilon_{n,t,u}$ defined for integer $n\ge1$ and real $t>0$ and~$u>0$ by
\begin{equation}

P^\varrho \Bigl(\,\max_{x\in\BbbL_n} \sqrt{L_t(x)} - \sqrt{t} - a_n(t) > u \Bigr)
= c_\star \bigl(1+\epsilon_{n,t,u}\bigr) u\texte^{-2u\slb} 
\end{equation}
obeys
\begin{equation}

\lim_{m\to\infty}\sup_{t,u\ge m} \limsup_{n\to\infty}\,\bigl|\,\epsilon_{n,t,u}\bigr|=0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:age of arXiv:2604.20327, 'Persistent Homology of the Wiener Sausage II: A Central Limit Theorem for Drifted Planar B'] One has
  \begin{equation}
    \frac{A_t}{\sqrt{t}} \to 0 \quad \text{in } L^2,
  \end{equation}
  and therefore
  \begin{equation}
    \frac{R_t - \rho_\psi A_t}{\sqrt{t}} \to 0 \quad \text{in } L^2,
  \end{equation}
