body:
[Theorem thm:ergodic via independece of core of arXiv:2411.00663, 'Ergodicity and Mixing of invariant capacities and applications'] Let $(\Omega,\mathcal{F},V,T)$ be a capacity preserving system, where $V$ is an upper probability. Then the following statements are equivalent:
	\begin{longlist}
		\item $V$ is ergodic;
		\medskip
		\item there exists $Q\in\operatorname{core}(V)\cap \mathcal{ M}^e(T)$ such that for any  $P\in\operatorname{core}(V)$, 
		\[\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}P(B\cap T^{-i}C)=P(B)Q(C)\text{ for any }B,C\in\mathcal{F};\]
		\medskip
		\item there exists $Q\in\operatorname{core}(V)\cap \mathcal{ M}(T)$ such that for any  $P\in\operatorname{core}(V)$, 
		\begin{equation}
			\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}P(B\cap T^{-i}C)=P(B)Q(C)\text{ for any }B,C\in\mathcal{F}.
		\end{equation}
	\end{longlist}

