body:
[Definition 32 of arXiv:2606.13459, 'Symmetric Cooperative Motion in Higher Dimensions'] For $T > 0$, we say that a measurable function $u: Q_{T}\to \R$ is a \emph{nonnegative entropy solution} to the equation $u_{t} - \frac{1}{2d}\Delta(u^{m+1}) = 0$ in $Q_{T}$ if the following holds:
	\begin{enumerate}
		\item $u \in  L^{1}(Q_{T}) \cap L^{\infty}(Q_{T}) \cap C((0,T);L^{1}(\R^{d}))$.
		\item $u \geq 0$ a.e.\@ in $Q_{T}$.
		\item For all $c \in \R$ and all non-negative $\vp \in C^{\infty}_{c}(\R^{d} \times [0,T])$,
		\begin{equation} 
			\int_{\R^{d}}\int_{0}^{T}\left(|u-c|\vp_{t} +\left|u^{m+1}-c^{m+1}\right|\frac{1}{2d}\Delta \vp\right)\,dt\,dx \geq 0.
		\end{equation}
		\item $u^{m+1} \in L^{2}((0,T) ;H^{1}(\R^{d})),$ where $H^{1}(\R^{d})$ is the Sobolev space $W^{1,2}(\R^{d})$.
	\end{enumerate}

[Lemma 6 of arXiv:2609.04143, 'The Geometry of Real Anisotropic Bohnenblust--Hille Constants'] For every $1\le p\le2$,
\begin{equation}
 A_p^{-1}\le \exp\left(\frac{1}p-\frac{1}{2}\right).
\end{equation}
In particular, for $p_k$ as in \eqref{eq:intro-pk-definition},
\begin{equation}
 A_{p_k}^{-1}\le e^{1/(2k)}.
\end{equation}
Moreover, for every $k\ge2$,
\begin{equation}
 A_{p_k}^{-1}\le 2^{1/(k+2)}.
\end{equation}

