[Theorem THM:2 of arXiv:2512.23957, 'Concentration and fluctuations of sine-Gordon measure around topological multi-soliton man'] Let $Q \in \mathbb{Z}$ with $Q\neq 0$, $L_\varepsilon=\varepsilon^{-\frac 12+\eta}$, and let $F$ be a bounded and continuous function. Then 
\begin{align*}
\lim_{\varepsilon \to 0} \int F( \sqrt{\varepsilon}^{-1}(\phi- \pi^\varepsilon(\phi) ) ) \rho_\varepsilon^Q (d\phi)=\int F(\phi) \mu_{\text{OU}} (d\phi), 
\end{align*}

\noindent
where $\mu_{\text{OU}}$ is the Ornstein–Uhlenbeck measure 
\begin{align*} 
\mu_{\text{OU}} (d\phi)=Z^{-1}\exp\Big\{ -\frac 12 \langle  \phi, (-\partial_x^2+1)\phi  \rangle_{L^2(\mathbb{R})}  \Big\} \prod_{x \in \mathbb{R}} d\phi(x).
\end{align*}

\noindent (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop subprop of arXiv:2608.30518, 'Grow-up rates of inhomogeneous semilinear heat equations in the critical dimension'] There exists $\widetilde{T}>0$ independent of $\varepsilon$
such that for any $\varepsilon>0$, we have
\begin{equation*}
\text{$\Psi_2:=\underline{\Psi}+\underline{\psi}\in W^{1,\infty}_{\mathrm{loc}}((0,\infty);H^{1}(B_{1}^2\setminus B_{\varepsilon}^2 ))$}
\end{equation*}
and 
\begin{equation*}
(\partial_t+\mathcal{E})\Psi_2\le -\lambda^{*}e^{u^{*}}r^4 e^{\mu_1 t}\mathcal{F}(r^{-4}e^{-\mu_1 t}\Psi_2) \quad \text{in $B_{1}^2\setminus B_{\varepsilon}^2 \times (\widetilde{T},\infty)$.}
\end{equation*}
In addition, we have
$\Psi_{2}=0$ on $\partial B_{1}^2 \times (\widetilde{T},\infty)$, and $\Psi_2<0$ on $B_{\rho(t)/2}^2 \times [\widetilde{T},\infty)$.

