[Definition 12 of arXiv:2607.28215, 'Almost stochastic dominance via optimal transport'] \begin{enumerate}[label=(\roman*)]
\item For $\gamma\in[0,1]$, let $\mathcal{U}_{\gamma}$ be the class of continuously differentiable functions $u \colon \mathbb{R}^{d} \to \mathbb{R}$ such that
\begin{equation}

\gamma \le \frac{\partial u}{\partial x_i}(\x) \le 1 \quad\text{ for all } \x\in\mathbb{R}^d \text{ and } i\in \{1,\dots, d\}.
\end{equation}
\item We say that $\mathbf{Y}$ dominates $\mathbf{X}$ in $\gamma$-almost stochastic dominance (i.e.~$\mathbf{X}\le_\gamma \mathbf{Y}$), if $\E[u(\mathbf{X})]\le \E[u(\mathbf{Y})]$ for all $u\in \mathcal{U}_\gamma$.
\end{enumerate}

[Proposition prop:eigenvalues of arXiv:2603.24803, 'Critical Spectral Invariants in Random Walks with Geometric Resetting'] The operator $\widetilde{P}$ has eigenvalues
\begin{equation}

\lambda_\nu = 2\sqrt{pq}\, \cos\!\left( \frac{\pi \nu}{a} \right),
\qquad \nu = 1, 2, \dots, a-1.
\end{equation}
The corresponding (unnormalized) eigenfunctions are
\begin{equation}

\psi_\nu(x) = \sin\!\left( \frac{\pi \nu x}{a} \right),
\qquad x = 1, \dots, a-1.
\end{equation}

[Proposition ex1 of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] Let $\textbf{M}$ and $\textbf{E}$ be the controlling functions introduced above. Then we have:
    \begin{equation*}
        \left|r_N\left(\frac{\kappa_N}{\sigma_{n,N}^3}\right)^{\frac{1}{6}}\frac{\mathbf{M}\left(\kappa_N^\frac{2}{3}\zeta\right)}{\tilde{f}^\frac{1}{4}(z)\mathbf{E}\left(\kappa_N^\frac{2}{3}\zeta\right)}\left(\frac{\mu_{n,N}}{x_N(s)}\right)\right|\le C(s_0)e^{-s}
    \end{equation*}
    for any $s\in\left[s_0,\frac{2\mu_{n,N}}{3\sigma_{n,N}}\right]$ when $N$ is large enough where $C(s_0)$ is a constant determined by $s_0$.

