[Theorem 36 of arXiv:2606.12720, 'On McDiarmid's Inequality under Dependence \\ via Approximate Tensorization of Entropy'] {McDiarmid's via Hellinger Integrals (Theorem 1, \cite{esposito:mondelli2023})}


    Let $\nu$ on $\Omega^n$ be a probability measure with marginals $\nu_i$ on $\Omega$. Let $\nu \ll \otimes_{i=1}^n \nu_i$ and $f : \Omega \to \R$ fulfill the bounded differences property with constants $c := (c_1,...,c_n)\T$. Then, for $t > 0$ and $\alpha > 1$, 
    \begin{align*}
        \P\Parent{\Abs{f(X) - \int_\Omega f(x) d\otimes_{i=1}^n \nu_i(x)} \geq t}
        \leq 2^{\frac{\alpha}{\alpha - 1}} \exp\Parent{- \frac{2t^2}{\frac{\alpha}{\alpha - 1} \twonorm{c}^2}} H_\alpha(\nu|| \otimes_{i=1}^n \nu_i)^{\frac 1 \alpha}. 
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 1 of arXiv:2608.11071, 'Scaling Laws for Majority-based Opinion Dynamics in the Presence of Stubborn Agents'] The limiting drift $\Delta_k$ satisfies the following properties for all $k\geq 1$.
\begin{enumerate}
    \item  $\Delta_k(\gamma_1)>0>\Delta_k(1-\gamma_0)$ and $\Delta_k$ has at least one and at most three real roots (counting multiplicity) in the interval $\mc S$.
    \item  Let $r_1$ and $r_2$ denote the smallest and the largest real roots of $\Delta_k$ in $\mc S$, respectively, with the possibility of $r_1=r_2$ when the root is unique. Then, for $\gamma_0\neq\gamma_1$ we have
    \begin{align}
        (\gamma_1-\gamma_0)(r_1+r_2-1+\gamma_0-\gamma_1) > 0,

    \end{align}
    Similarly, for $\gamma_0=\gamma_1$, we have $r_1+r_2=1$ and we always have a root of $\Delta_k$ at $1/2$.








\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 of arXiv:2604.23461, 'Scaling limit of Sinkhorn-rescaled Random Matrices \\ via Stability of Static Schrödinger '] Make the same assumptions as in Theorem \ref{thm: Schrodinger_bridge_existence_uniqueness}. Further, assume $\frac{d\mathcal{R}}{d(\mu_0 \otimes \mu_1)} = e^{-\kappa}$ for some $\kappa \in L^{\infty}(\mu_0 \otimes \mu_1)$. Then
	\begin{align}
		-(\norm{\kappa^{-}}_{\infty} + \norm{\kappa^{+}}_{\infty})  \leq \balpha(x) \leq \norm{\kappa^{+}}_{\infty} \quad \mu_0 \textup{-a.s.}
	\end{align}
	and
	\begin{align}
		-(\norm{\kappa^{-}}_{\infty} + \norm{\kappa^{+}}_{\infty})  \leq \bbeta(y) \leq \norm{\kappa^{+}}_{\infty} \quad \mu_1 \textup{-a.s.}
	\end{align}
	where $\balpha, \bbeta$ are the unique Schr\"{o}dinger potentials satisfying $\langle \bbeta, \mu_1 \rangle = 0$.

