body:
[Proposition prop: existence of arXiv:2609.02073, 'Existence of closed non-planar $p$-elasticae'] Let $p\in (1,\infty)$. 
    \begin{itemize}
        \item If $(\lambda,C^2) \in \partial S_2$, then (equation eq:EL pointwise for w of the paper) has exactly one strictly positive solution $w=w_{\lambda,C^2}:\R \to \R$ with $w(0)=\|w\|_{L^\infty}=1$, namely the constant solution $w \equiv1$.
        \item If $(\lambda,C^2) \in S$, then (equation eq:EL pointwise for w of the paper) has exactly one strictly positive solution $w=w_{\lambda,C^2}:\R \to \R$ with $w(0)=\|w\|_{L^\infty}=1$, which is even, smooth and periodic with period $2P=2P(\lambda,C^2) \in (0,\infty)$. 
        \item If $(\lambda,C^2)=(\lambda,0)$ with $\frac{p-1}{2}<\lambda<p-1$, then (equation eq:EL pointwise for w of the paper) has exactly one strictly positive solution $w=w_{\lambda,C^2}:\R \to \R$ with $w(0)=\|w\|_{L^\infty}=1$, which is even, smooth and periodic with period $2P=2P(\lambda,0) \in (0,\infty)$. 
        \item If $(\lambda,C^2)=(\lambda,0)$ with $\lambda<\frac{p-1}{2}$, then there exists $P=P(\lambda,0)$ and a unique nonnegative continuous function $w=w_{\lambda,C^2}:\R \to \R$ satisfying the following properties:
        \begin{itemize}
            \item $w$ is even;
            \item $w$ is periodic with period $2P=2P(\lambda,0) \in (0,\infty)$;
            \item $w(0)=\|w\|_{L^\infty}=1$;
            \item   $w$ is smooth and satisfies (equation eq:EL pointwise for w of the paper) in $\R \setminus \{(2j-1)P:j\in \Z\}$;
            \item $w((2j-1)P)=0$ for every $j\in \Z$.
        \end{itemize}
    \end{itemize}

