body:
[Lemma 2 of arXiv:2604.13454, 'Invariant and periodic measures in classical spin systems on infinite lattices with highly'] The set $L^{\infty}_{loc}([0,\infty);\ell^{2\theta}_{\rho}(\mathbb{Z}^{+})])\bigcap\Omega_{Spin}$ is a Borel set in $\Omega_{Spin}$. Moreover, 
        \begin{equation*}
            L^{\infty}_{loc}([0,\infty);\ell^{2\theta}_{\rho}(\mathbb{Z}^+))\bigcap \Omega_{Spin}=C([0,\infty);\ell^{2\theta}_{\rho,\sigma}(\mathbb{Z}^+))\bigcap \Omega_{Spin},
        \end{equation*}
        where $\ell^{2\theta}_{\rho,\sigma}(\mathbb{Z}^+)$ denotes the space $\ell^{2\theta}_{\rho}(\mathbb{Z}^+)$ endowed with the weak topology. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:conditional-expectations-next-day of arXiv:2608.06159, 'Majority Dynamics on Resampled Sparse Erd\H{o}s--R\'enyi Graphs:\\[0.5ex] Gaussian Winner '] For all \(t \geq 0\), the conditional expectations of the camp sizes on the next day can be expressed as
    \begin{subequations}
    \begin{align}
        \E\left[ |\gB_{t+1}|\,\middle|\, \rvy_{t} \right]
&\, = |\gR_{t}|p_t^{\gR} + |\gB_{t}|q_t^{\gB}, \\
        \E\left[ |\gR_{t+1}|\,\middle|\, \rvy_{t} \right]
&\, = |\gR_{t}|q_t^{\gR} + |\gB_{t}|p_t^{\gB}. 
    \end{align}
    \end{subequations}
    Furthermore, the conditional expectation of the advantage on the next day can be expressed as
    \begin{subequations}
        \begin{align}
            \E\left[\Delta_{t+1} \,\middle|\, \rvy_{t}\right]
            &\, = \Delta_t + 2 \left( |\gR_{t}|p_t^{\gR} - |\gB_{t}|p_t^{\gB} \right). \\
            &\, = N\bigl(p_t^{\gR}-p_t^{\gB}\bigr)
            +
            \Delta_t
            \bigl(1-p_t^{\gR}-p_t^{\gB}\bigr).

        \end{align}
    \end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem typP poly LB of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] There exist constants $a_2, c_5  \in (0, \infty)$ such that
  the following holds for all sufficiently large $\ell \in \mathbb{N}$.
  For any $x_0 \in M$, 
  \begin{equation}
    \inf_{\bm{x} \in \hat{B}_*(x_0, r_\ell)}
    \hat{P}_{\bm{x}}
    \bigl(
      \Pi_{c_5 h_\ell}(B(x_0,r_\ell))
      \geq a_2  \varphi_2(r_\ell) \log \ell     
    \bigr)
    \geq
    \tilde{c}_1 \ell^{-{1/2}}.
  \end{equation}

