[Definition 176 (The fundamental $L^2$-acoustic geometry-controlling quantities) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $N = \Ntop$ and $\blowuprateofwaveWRTnumberofcommutations(N) = \blowupratetoporderwave$  denote the powers of $\weight$ from Def.\,\ref{D:NOTATIONFORPOWERSOFWEIGHT}. Let $\sumofbrevexvisquared$ denote the function from \eqref{E:FACTORINTOPACOUSTICENERGYNEEDEDFORSHARPCONSTANTS}. Then in terms of the differentiated conventions of Def.\,\ref{D:STRINGSOFCOMMUTATIONVECTORFIELDS}, 
we define the following $L^2$-controlling quantities:
	\begin{itemize}[leftmargin=*]
		\item \underline{\textbf{Precise fully modified controlling quantities}}.
			\begin{subequations} 
				\begin{align}
					\totalfluxcontrolprecisefullymodifiedchi(\ubar,u) & \eqdef \max_{\tander^{N} \in {\mathfrak{P}}^{(N)}} \sup_{\substack{\ubar' \in [\leftubar,\ubar] \\ u' \in [\moreinterestingu_1,u]}}  \left\|\ReciprocalLunitAppliedtoTimeFunction \sumofbrevexvisquared \, \fullymodquant{\tander^{N}}  \right\|^2_{L^2_{\blowupratetoporderwave}\left( \ingoingcharacteristicsurfacetwoarg{\ubar}{[\moreinterestingu_1,u]}\right)},   \\
					\totalbulkcontrolprecisefullymodifiedchi(\ubar,u) & \eqdef    \max_{\tander^{N} \in {\mathfrak{P}}^{(N)}} \newspacetimecoercive{\blowupratetoporderwave-1}\left[ \ReciprocalLunitAppliedtoTimeFunction \sumofbrevexvisquared \, \fullymodquant{\tander^{N}}  \right](\ubar,u). 
				\end{align}
			\end{subequations} 
		\item  \underline{\textbf{Imprecise fully modified controlling quantities}}.
			\begin{subequations}
				\begin{align} 
					\totalfluxcontrolimprecisefullymodifiedchi(\ubar,u) & \eqdef \max_{\tander^{N}  \in {\mathfrak{P}}^{(N)}} \sup_{\substack{\ubar' \in [\leftubar,\ubar] \\ u' \in [\moreinterestingu_1,u]}}  \left\| \fullymodquant{\tander^{N} } \right\|^2_{L^2_{\blowupratetoporderwave + 1}\left( \ingoingcharacteristicsurfacetwoarg{\ubar}{[\moreinterestingu_1,u]}\right)},   \\
					\totalbulkcontrolimprecisefullymodifiedchi(\ubar,u) & \eqdef  \max_{\tander^{N}  \in {\mathfrak{P}}^{(N)}} \newspacetimecoercive{\blowupratetoporderwave}\left[ \fullymodquant{\tander^{N}  } \right](\ubar,u). 
				\end{align} 
			\end{subequations}
		\item \underline{\textbf{Partially modified controlling quantities}}.				
			\begin{subequations}
				\begin{align}				
				 	\totalfluxcontrolpartialmodifiedchi(\ubar,u) & \eqdef \max_{\tanderY^{N-1} \in {\mathfrak{Y}}^{(N-1)} } \left\| \sumofbrevexvisquared \, \partialmodquant{\tanderY^{N-1}} \right\|^2_{L^2_{\blowupratetoporderwave - 1}\left( \ingoingcharacteristicsurfacetwoarg{\ubar}{[\moreinterestingu_1,u]}\right)} , \\
					\totalbulkcontrolpartialmodifiedchi(\ubar,u) & \eqdef \max_{\belowtopordercomforpartialmodifiedchi^{N-1} \in {\mathfrak{Y}}^{(N-1)} }\newspacetimecoercive{\blowupratetoporderwave - 2}\left[\sumofbrevexvisquared \, \partialmodquant{\tanderY^{N-1}}\right](\ubar,u). 
				\end{align}
			\end{subequations} 
	\end{itemize}

