body:
[Prop thm:submatrices_suffice of arXiv:2412.05999, 'Non-Archimedean GUE corners and Hecke modules'] \begin{enumerate}[left=0pt]
\item(Alternating case) Let $A\in\Alt_{2n}(F)$ or $A\in\Alt_{2n+1}(F)$ with $\SN^{\alt}(A)=(\lambda_1,\ldots,\lambda_n)$. Then for any $1\le k\le n$,
\begin{equation}
2(\lambda_n+\cdots+\lambda_{n-k+1}) = \inf_{A' \text{ $2k \times 2k$ principal minor of $A$}} v(\det(A')).
\end{equation}

\item(Hermitian case) Let $A\in\Her_n(F)$ with $\SN^{\her}(A)=(\lambda_1,\ldots,\lambda_n)$. Then for any $1\le k\le n$,
\begin{equation}
\lambda_n+\cdots+\lambda_{n-k+1} = \inf_{A' \text{ $k \times k$ minor of $A$}} v(\det(A')).
\end{equation}
\end{enumerate}

