body:
[Lemma lem:tool_gao_bernstein of arXiv:2609.01576, '\normalfont Pointwise Majorization for sub-Weibull and Mixed Tail Processes with Applicati'] Let $X$ be the stationary diffusion in
Section (sec:pointwise_ergodic_diffusion of the paper). Suppose that it is reversible
with respect to $\pi$ and that,  $\exists\ 0<C_P<\infty$ such that
\begin{align}
\operatorname{Var}_\pi(h)
\le
\frac{C_P}{2}
\int_{\RR}a(x)|h'(x)|^2\pi(x)dx

\end{align}
for every locally absolutely continuous $h\in L^2(\pi)$ for which the
right-hand side is finite. Let $g$ be bounded and Borel with $\pi(g)=0$.
Then, for every $t,u>0$,
\begin{align}
\PP_\pi\cbr{
\left|
\frac1{\sqrt t}\int_0^t g(X_s)ds
\right|
>
2\sqrt{C_P}\|g\|_{L^2(\pi)}\sqrt u
+
\frac{C_P\|g\|_\infty}{\sqrt t}u
}
\le2e^{-u}.

\end{align}
If the long-run variance of $g$ equals $\cV_\pi(g)^2$, i.e., 
$\cV_\pi(g)^2
=
\lim_{t\to\infty}
\frac1t
\operatorname{Var}_{\PP_\pi}
\left(
\int_0^t g(X_s)ds
\right)$, then we have that
\begin{align}
\cV_\pi(g)^2
\le
2C_P\|g\|_{L^2(\pi)}^2,

\end{align}
and
\begin{align}
\PP_\pi\cbr{
\left|
\frac1{\sqrt t}\int_0^t g(X_s)ds
\right|
>
\cV_\pi(g)\sqrt{2u}
+
\frac{C_P\|g\|_\infty}{\sqrt t}u
}
\le2e^{-u}.

\end{align}
The two-sided statements follow by applying the one-sided result of
[gao2014bernstein] to $g$ and $-g$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma LEM:Moment of arXiv:2512.23957, 'Concentration and fluctuations of sine-Gordon measure around topological multi-soliton man'] Let $Y(t)$ and $\Theta(t)$ be as in (equation CY0 of the paper) and (equation CY1 of the paper).

\textup{(i)} 
For any $t\in [0,1]$, we have 
\begin{align}
\mathbb{E} \bigg[ \int_{-L_\varepsilon}^{L_\varepsilon} |\sqrt{\varepsilon} Y(t)|^2 dx \bigg]
& = \frac 23 t \cdot \varepsilon L_\varepsilon^2, \\
\mathbb{E} \bigg[ \int_{-L_\varepsilon}^{L_\varepsilon} |\sqrt{\varepsilon} Y(t)| dx \bigg]
& = \frac{\sqrt{\pi t}}{2} \cdot  \varepsilon^\frac 12  L_\varepsilon^{\frac 32}.

\end{align}

\smallskip

\noindent
\textup{(ii)}
The drift term $ \Theta(t) $ has the regularity
of the Cameron-Martin space, that is, for any $\theta\in \mathbb{H}_a $, we have
\begin{align}
\| \Theta(1)\|_{  \dot{H}^{1}_x}^2 \leq \int_0^1 \|  \dot{\Theta}(t) \|_{\dot{H}^1_x}^2dt=\int_0^1 \| \theta(t) \|_{L^2_x}^2 dt,

\end{align}

\noindent
where $\dot{\Theta}(t)=(-\partial_x^2)^{-\frac 12}\theta(t)$.

