[Lemma lem:503 of arXiv:2411.14921, 'A boundary Harnack principle and its application to analyticity of 3D Brownian intersectio'] \textnormal{(i) (Cylinder vs Cylinder)}
    Let $d<1/2$. Consider two concentric cylinders
    $$
    D=\{(z_1,z_2,z_3):0\leq z_3\leq \pi, z_1^2+z_2^2\leq 1\},
    $$
    and
    $$
    D_1=\{(z_1,z_2,z_3):0\leq z_3\leq \pi, z_1^2+z_2^2\leq d^2\}.
    $$
    There exists an absolute constant $c>0$, such that for any $z\in B((0,0,\pi/2),1/2)$, we have
    \begin{equation}
        \mathbb{P}_z\Big(\tau_{D_1}\le \tau_{\partial D}\Big)
        \geq \frac{c}{\log(1/d)}.
    \end{equation}    
    \textnormal{(ii) (Sphere vs Cylinder)}
    Let $0\leq a\leq 1/2$, $d<1/16$ and $ D_2=\{(z_1,z_2,z_3):z_1^2+(z_2-a)^2<d^2\}$. Recall $\tau=\tau_{\partial B(0,1)}$. There exists an absolute constant $c'>0$ such that
    \begin{equation}
        \mathbb{P}_0\Big(\tau_{D_2}\le \tau\Big)
        \geq \frac{c'}{\log(1/d)}.
    \end{equation}

[Defi of arXiv:2604.21663, 'Large deviations for non-irreducible Markov chains on Euclidean spaces'] For every measurable set $A$ of $\mathcal P(\mathbb R^d)$, we set 
	\begin{align*}
		\underline s(A)&=\liminf_{n\to \infty}\frac 1n \log \mathbb P(L_n\in A),\\
		\overline s(A)&=\limsup_{n\to \infty}\frac 1n \log \mathbb P(L_n\in A).
	\end{align*}
	Let $\mu\in \mathcal P(\mathbb R^d)$.
	We set \begin{align*}
		\underline{s}(\mu)&=\lim_{\delta\to 0}\underline s(\mathcal B_{\mathrm{LP}}(\mu,\delta)),\\
		\overline{s}(\mu)&=\lim_{\delta\to 0}\overline s(\mathcal B_{\mathrm{LP}}(\mu,\delta)).
	\end{align*}
	If $\underline s(\mu)=\overline s(\mu)$, we set $I_{\mathrm{RL}}(\mu)=-\underline{s}(\mu)=-\overline s(\mu)$ and we say that the \emph{Ruelle-Lanford function} of $(L_n)$ exists at $\mu$.

[Thm P typ gau of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] There exist a deterministic constant $c_1\in(0,\infty)$
  and a deterministic function $c_2\colon (0,\infty)\to(0,\infty)$ such that the following holds.
  \begin{enumerate} [label = \textup{(\roman*)}]
    \item
    If $\hat{d}_{\mathrm{s}} > 2$, then, $\hat{P}_{\bm{\rho}}$-a.s., for all $t \in (0,\infty)$,
    \begin{equation}
      c_1
      \leq
      \varlimsup_{r\downarrow0}
      \frac{\Pi_t(B(x,r))}{\Psi_{\mathrm{cp}}(r)}
      \leq
      c_2(t),
      \qquad
      \Pi_t\text{-}\mathrm{a.e.}\ x.
    \end{equation}

    \item
    If $\hat{d}_{\mathrm{s}}=2$, then, $\hat{P}_{\bm{\rho}}$-a.s., for all $t \in (0,\infty)$,
    it holds that, for $\Pi_t$-a.e.\ $x$,
    \begin{equation}
      c_1
      \leq
      \varlimsup_{r\downarrow0}
      \frac{\Pi_t(B(x,r))}{r^{d_{\mathrm{f}}}(\log\log(1/r))^2}
      \hspace{1em}\text{and}\hspace{1em}
      \varlimsup_{r\downarrow0}
      \frac{\Pi_t(B(x,r))}{r^{d_{\mathrm{f}}}\log(1/r)\log\log(1/r)}
      \leq
      c_2(t).
    \end{equation}
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

