body:
[Defi Martin kernel of arXiv:2411.02156, 'Martin boundary of a degenerate Reflected Brownian Motion in a wedge'] For $z_0, z_1 \in {\mathbb R}_+^2$, we define the Martin kernel
\begin{equation}
k(z_0,z_1) =\left\{
    \begin{array}{ll}
        \frac{g^{z_0}(z_1)}{g^{(0,0)}(z_1)}    & \textnormal{if} \quad z_1 \neq (0,0)\\
      0 & \textnormal{if} \quad z_1 = (0,0) \quad \textnormal{or} \quad z_0 = z_1
    \end{array}
\right.
\end{equation}
and the Martin metric
\begin{equation}
\rho(z_1, z_2) = \int_{{\mathbb R}_+^2}\frac{|k(x,z_1) - k(x,z_2)|}{1 + |k(x,z_1) - k(x,z_2)|}e^{-|x|^2}dx. 
\end{equation}

[Lem compXscales of arXiv:2604.14122, 'The scaling limit of random walk and\\ the intrinsic metric on planar critical percolation'] For all $\zeta>0$, there exist $R=R(\zeta)$ big enough, $p$ small enough (depending on $R$) and $C=C(R,\zeta,\alpha)>0$ such that for all $0< s\leq 1$, $k\geq1$ and $n> R^k$, 
we have
\begin{equation}
    \mathbf{P}(X_{R^{\kappa-k}}> {s^{\frac{3}{4}-\zeta}}\mathbf{q}_n)\leq C {s^{-\alpha}}R^{-\alpha k}.
\end{equation}

