[Lemma 16 of arXiv:2604.10244, 'Ergodicity for regime-switching neutral stochastic functional differential equations with '] Let assumption (\hyperlink{A0}{A0}) hold. Suppose that there exist a function \( U \in C^{2}\left(\mathbb{R}^{n} \times \mathbb{S} ; \mathbb{R}_{+}\right) \) and positive constants $ p$, $ c_{1} $, $ c_{2} $, $\lambda_{1} $, $ \lambda_{2} $  such that \( \lambda_{1}>\lambda_{2}(1-\kappa_1)^{p}\),
		\begin{equation}
			c_{1}|x|^{p} \leq U(x, k) \leq c_{2}|x|^{p}
		\end{equation}
		for \( (x, k) \in \mathbb{R}^{n} \times \mathbb{S} \) and
		\begin{equation}
			\begin{aligned}
				(\mathbb{L} U)&(\varphi,\psi, k)
				\leq -\lambda_{1}|\varphi(0)-\psi(0)+G(\psi,k)-G(\varphi,k)|^{p}+\lambda_{2} \int_{-\infty}^{0} |\varphi(\theta)-\psi(\theta)|^{p} \rho(\d \theta)
			\end{aligned}
		\end{equation}
		for any \( (\varphi, \psi, k) \in C_r \times C_r\times \mathbb{S} \). Then there exists a constant $C>0$  such that for any   $(\xi,\eta,i)\in C_r\times C_r\times\S$ and  $t\geq 0 $,
		\begin{equation}
			\mbb{E}\left|Y^{\xi, i}(t)-Y^{\eta, i}(t)\right|^{p}\leq  C\|\xi-\eta\|_{r}^{p}\e^{-\lambda t}.
		\end{equation}

