[Prop FV734 of arXiv:2411.07809, 'Pirogov--Sinai Theory Beyond Lattices'] Suppose $G$ satisfies Assumption~(as:3 of the paper).
   For any $\tau$ sufficiently large, there exists $\lambda_\star = \lambda_\star(C_{\text{iso}}, D, \Delta,\tau)$ and an increasing
  sequence $(c_{n})_{n\geq 0}$ with
  $2\leq c_{n}\uparrow c_\infty \leq 3$ so that for  $\lambda_\textsf{e} > \lambda_\star$, $\lambda_{\textsf{o}}\in\mathcal{U}$, and all $n \geq 1$, the following statements hold: 
  \begin{enumerate}
  \item For $\gamma\in\mathcal C_{\leq n}$,
    \begin{equation}

      \widehat{w}_\gamma \leq e^{-\tau |\gamma|}
    \end{equation}
    and if $\gamma\in\mathcal C_{\leq n}^{x}$, $x\in \{\textsf{e},\textsf{o}\}$,
    \begin{equation}

      a^x_n \Delta_x|\mathsf{Int}\gamma|^{1/2} \leq \kappa/2 \text{ implies }
      \widehat{w}_\gamma = \widetilde{w}_\gamma. 
    \end{equation}
    Moreover, $\widehat{w}_\gamma$ is continuously differentiable in
    $\lambda_{y}$, $y\in \{\textsf{e},\textsf{o}\}$, and
    \begin{equation}

      \left| \frac{d \widehat{w}_\gamma}{d
          \lambda_{y}}\right| \leq \frac{R
        |\gamma|^2}{\lambda_{y}} e^{-\tau |\gamma|},
    \end{equation}
    where $R =4(1+\|\chi'\|_{\infty})$, with $\chi$ the $C^1$ cutoff function defined above.
  \item Assume $\Lambda=\mathsf{Int}\gamma$ for $\gamma\in\mathcal C_{\leq n}$.
    Then for $x,y\in \{\textsf{e},\textsf{o}\}$,
  \begin{align}

    Z^x_{\Lambda} &\leq \exp\left( \widehat{\psi}_n \Delta_{x} |\Lambda \cap V_{x}| + c_n |\gamma| \right) 
    \\

  \abs{\frac{d Z^{y}_{\Lambda}}{d\lambda_{x}}} &\leq \frac{|\Lambda\cap V_{x}|}{\lambda_{x}} \exp
    (\widehat \psi_{n} \Delta_{y} |\Lambda\cap V_{y}| +
    c_{n}|\gamma|).
  \end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 14 of arXiv:2608.26642, '2608.26642'] For every $x\in \R$,
  \begin{align}

   \lim_{q\to 0+}r_q(0)\P_x\Big[\Gamma_{\bm{e}_q}^\mu\Big]=\varphi^\mu(x).
 \end{align}
This convergence is uniform on compact sets. In particular, $\varphi^\mu=f^\mu$ on $K.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 19 of arXiv:2608.30077, 'Lie groupoid integration of singular isometries of the Poincaré disk'] We consider a family of Lie groupoids
   \begin{equation}
       \mathcal{G}_{n}' = X_{n} / \sim'
   \end{equation} where the equivalence relation 
    $ \sim'$ is defined as follows:
\begin{equation}
(u(t),z)\sim'(v(t),w)
    \end{equation}
    if and only if
$w=z$ and there exists a smooth homotopy $u(t,s)$ fixing the endpoints such that: 
\begin{equation*}
   u(t,0) = u(t), \quad  u(t,1) = v(t), \quad u(t,s)\cdot z^n \neq 0, \forall\ t,s.
\end{equation*}
The source and target maps of $\mathcal{G}_{n}'$ are defined by the formula
    \begin{equation*}
        \sigma'(u(t), z) = z, \quad \tau'(u(t), z) = z(1).
    \end{equation*}

[Lemma 18 (Dyadic--close harmonic envelope) of arXiv:2609.01570, 'A Proof of Fraenkel's Conjecture'] Let
\[
 H_y^{\rm good}:=\frac1y+
 \sum_{\substack{b\in A\setminus\{1,y\}\\ b\text{ is good}}}
 \frac1{\normQ{yb^{-1}}};
\]
thus the superscript includes the anchor \(b=1\) as well as every selected
good element other than \(y\).  This contribution to the \(y\)-row satisfies
\begin{equation}
 H_y^{\rm good}
 <\frac2m+\frac{10J}{3y}+\frac{2\Harm_{y-1}}{y-1}.
\end{equation}

[Lemma avlemma of arXiv:2411.06006, 'Mixing time of the torus shuffle'] If $\,\mathcal U$ is the uniform distribution on $V$ and $q$ is any distribution on $V$, then
\begin{align}
    d(q, \mathcal U) \geq \frac{C}{\log |V|}{\rm ENT}(q)
\end{align}
for a universal constant $C>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop proposition:ManyToOneL* of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] Fix $r\geq 0$.  For every non-negative measurable function $\Phi$ on $\mathcal{M}^2_f(\mathbb{R}_+) \times \mathcal{W}_{\overline{E}}$, we have:
\begin{align}
     &  \mathbf{N}^{\bullet, L}_{x,r} \big(  \Phi\big( \rho_U,\eta_U, \overline{W}_U\big)  \big)  
  =   E^0 \otimes \mathcal{N}_{x,r} \Big(  \exp\big(- \alpha\cdot  \uptau \big)\Phi\big( \mathcal{J}_{\uptau}, \widecheck{\mathcal{J}}_{\uptau}, (\bar{\xi}_t:~t\in [0,\uptau] ) \big) \Big). 
\end{align}
Under $\mathbf{N}_{x,r}^{\bullet, L}$, conditionally on $(\rho_U,\eta_U, \overline{W}_U)$ the
processes $(\rho,\overline{W})^{U,\leftarrow}$ and  $(\rho,\overline{W})^{U,\rightarrow}$ are independent and their  conditional distributions are as follows:
\begin{itemize}
\item the process $(\rho,\overline{W})^{U,\leftarrow}$ is distributed as  $(\eta, \overline{W})$ under $\mathbb{P}_{\eta_U, \rho_U,\overline{W}_U}^\dagger$; 
\item the process $(\rho, \overline{W})^{U,\rightarrow}$ is distributed as  $(\rho, \overline{W})$ under $\mathbb{P}_{\rho_U,\overline{W}_U}^\dagger$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 11 of arXiv:2608.28964, '2608.28964'] {\rm(}\hspace{-0.1mm}{\rm\cite[Theorems 3.4, 4.5]{HM-08})}
    Let $Z(t,x)$ be a stochastic semiflow on a Hilbert space $X$, with $C^1$ dependence on $x\in X$, and let $\{P_t\}_{t\geq0}$ and $\{P_t^*\}_{t\geq0}$ be the associated Markov semigroups. Assume that 
    \begin{itemize}
        \item[(1)] There exist constants $C,\gamma>0$ and a decreasing function $\xi\colon[0,1]\to(0,\infty)$ with $\xi(1)<1$ such that for any $x\in X$, $r\in[1/4,3]$ and $t\in[0,1]$,
	\begin{equation}
	\E\exp\left(r\gamma\|Z(t,x)\|_{X}^2\right)\left(1+\|\nabla_xZ(t,x)\|_{\mathcal L(X)}\right)\leq C\exp\left(r\gamma\xi(t)\|x\|_{X}^2\right).
	\end{equation}
        \item[(2)] There exist constants $C,\alpha>0$ such that for any Fr\'echet differentiable function $\varphi\colon X\to\R$, $x\in X$ and $t\geq0$,
	\begin{equation}
	\|\nabla P_t\varphi(x)\|_{X}\leq C\exp\left(\tfrac{\gamma}{2}\|x\|_{X}^2\right)\left(\sqrt{P_t(|\varphi|^2)(x)}+e^{-\alpha t}\sqrt{P_t(\|\nabla\varphi\|_{X}^2)(x)}\right).
	\end{equation}
        \item[(3)] For any $\varepsilon,R>0$ and $r\in(0,1)$, there exists $T>0$ such that for any $t\geq T$,
	\begin{equation}
	\inf_{x,x'\in B_{X}(0,R)}\sup_{\Gamma\in\mathscr C(P_t^*\delta_x,P_t^*\delta_{x'})}\Gamma\left\{(y,y')\in X\times X:\rho_r(y,y')\leq\varepsilon\right\}>0,
	\end{equation}
        where $\mathscr C(\mu,\mu')$ is the set of couplings of $\mu$ and $\mu'$, and
	\begin{equation*}
	\rho_s(x,y):=\inf_{\substack{\ell\in C^1([0,1];X),\\
	\ell(0)=x,\ \ell(1)=y}}\int_0^1\exp\left(s\gamma\|\ell(r)\|_{X}^2\right)\|\ell'(r)\|_{X}dr,\quad s\in(0,1].
	\end{equation*}
    \end{itemize}

    Then there exist constants $C,\alpha>0$ such that
	\begin{equation*}
	\rho_1(P_t^*\mu,P_t^*\mu')\leq Ce^{-\alpha t}\rho_1(\mu,\mu')\quad\forall\,\mu,\mu'\in\mathcal P(X),\;t\geq0.
	\end{equation*}
    In particular, $\{P_t^*\}_{t\geq0}$ admits a unique invariant measure $\mu_*\in\mathcal P(X)$, and
	\begin{equation*}
	\left|P_t\varphi(x)-\int_{X}\varphi d\mu_*\right|\leq Ce^{-\alpha t}\exp\left(\gamma\|x\|_{X}^2\right)\left\|\varphi-\int_{X}\varphi d\mu_*\right\|_\gamma
	\end{equation*}
    for any $\varphi\in\mathcal O_\gamma$, $x\in X$ and $t\geq0$, where
	\begin{equation*}
	\mathcal O_\gamma:=\left\{\varphi\in C^1(X):\|\varphi\|_\gamma<\infty\right\},\quad\|\varphi\|_\gamma:=\sup_{x\in X}\left(e^{-\gamma\|x\|_{X}^2}\left(|\varphi(x)|+\|\nabla\varphi(x)\|_{X}\right)\right).
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

