body:
[Lemma lem:lemma4 of arXiv:2411.12076, 'Explicit solutions of the SI and Bass models on sparse Erd\H{o}s-R\'enyi and regular netwo'] Let 
	\begin{equation}

		y(t):=\frac{\overline{\big[S^\infty_{B_{1}}\big]}}{e^{-pt}(1-I^0)}.
	\end{equation}
	Then
	\begin{enumerate}
		\item $y(t)$ is the solution of equation~(equation eq:y-ER of the paper). 
		\item 
		$
		f^{\rm ER}(t) = 1-(1-I^0) e^{-\lambda  -pt +\lambda y(t)}
		$. 
	\end{enumerate}

[Lemma l.d_eps_Phi^eps of arXiv:2411.14105, 'Simultaneous replica-symmetry breaking \\ for vector spin glasses'] Let $(L,\alpha)$ be any composition of some $q\in\mathcal Q_\infty$ defined on $[0,T]$. Let $L':[0,T]\to S^{D}_+$ be any smooth increasing path. For each $\varepsilon\in[0,1)$, let $\Phi^\varepsilon$ be associated with $(L+\varepsilon L',\alpha)$. Let $\Phi=\Phi^0$ and let $X$ be the process associated with $(L,\alpha)$ with $X_0 = x_0\in\mathbb{R}^{D}$. We have
\begin{align}
    \frac{\mathrm{d}}{\mathrm{d}\varepsilon}\Big|_{\varepsilon=0} \Phi^\varepsilon(0,x_0) & = -L'(0)\cdot \left(A_0 + \alpha(0)R(0)\right)-\int_0^T L'(t)\cdot R(t)\mathrm{d}\alpha(t) 
\end{align}
where $R(\cdot)$ and $A_\cdot$ are given in~(equation e.R(t)=A_t= of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 (WKB expansion) of arXiv:2603.29473, '$\chi^2$--cut-off phenomenon for Galerkin projections of Fokker--Planck equations with mon'] \hfill

	\noindent
	Let $\lambda>0$ be fixed and $n \in \N$. Assuming \cref{eq:spectralcondition} there exists a turning point $x^\ast$ of
	\begin{equation*}
		T(x):=\frac{|V'(x)|^2}{4} - \frac{V''(x)}{2} - \lambda,
	\end{equation*}
	that is,  the point $x^*$ for which $T(x)\geq 0$ for all $x \geq x^*$.
	Denote $f = V'$ and let $f \in \mathcal{C}^1([x^*,\infty))$.
	Let $v$ be a solution to \cref{eq:Wittenprime} in $[x^*,\infty)$. Write $v(x) = e^{\sum_{i=0}^{n} S_i(x)+R_n(x)}$, where
	\begin{equation}
		\begin{split}
			S_0(x)=   & -\int_{x^*}^{x} \frac{f(s)}{2}
			\ds, \quad
			S_1(x)=  \int_{x^*}^x \frac{\lambda}{f(s)} \ds,                                                                                           \\
			S_k'(x) = & \frac{1}{f(x)} S_{k-1}''(x) + \frac{1}{f(x)} \sum_{j=1}^{k-1} S_j'(x) S_{k-j}'(x), \quad S_k(x^*) = 0, \quad 2 \leq k \leq n,
		\end{split}
	\end{equation}
	for all $x\geq x^*$.
	Then the remainder term $R_{n}$ satisfies for $\widehat u =e^{R_{n}}$
	\begin{equation} 
		-\widehat u''(x) - 2\widehat u'(x) \sum_{j=0}^{n} S_j'(x) = \widehat u(x)  \left ( S_n''(x) +\sum_{n_1+n_2 \geq n+1}^{n_1 \leq n; n_2 \leq n} S_{n_1}'(x)S_{n_2}'(x) \right ),
	\end{equation}
	with initial condition $\widehat u(x^*) = v(x^*)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2412.03366, 'Regularity of Weighted Tensorized Fractional Brownian Fields and associated function space'] For $0 \leq p, \, q \leq \infty$ and $s, \, \beta \in \mathbb{R}$, the hyperbolic Besov space with hyperbolic scale is defined by
\begin{equation}
 \widetilde{B}^{s}_{p,q,\vert \log \vert^{\beta}}(\mathbb{R}^2)  :  = \Big\{ f \in \mathcal{S}'(\mathbb{R}^2)~:~ \,   \sum_{\bar{j} \in \mathbb{N}^2 } (\max(\bar{j})) ^{-\beta q} 2^{\max(\bar{j})sq} \Vert \Delta_{\bar{j}} f \Vert_p^q < \infty \Big\}
\end{equation}
with the norm
$$
\Vert f \Vert_{\widetilde{B}^{s}_{p,q,\vert \log \vert^{\beta}}(\mathbb{R}^2)} = \left( \sum_{\bar{j} \in \mathbb{N}^2 } (\max(\bar{j})) ^{-\beta q} 2^{\max(\bar{j})sq} \Vert \Delta_{\bar{j}} f \Vert_p^q \right)^{1/q},
$$
with the usual modification if $q= \infty$.

[Proposition 53 of arXiv:2607.08536, 'Soft edge limit of the Laguerre beta-ensemble at the lower edge'] For  $k\ge n_1$ and for $n$ large enough we have 
\begin{align*}
\Big\{\frac{u_k}{u_{k-1}}\ge 1\Big\}\cap\mathcal{A}_n^G \subset \left\{\frac{u_{k+1}}{u_k}>1+\min\Big\{\tfrac12\sqrt{\tfrac{k}{n-k}},n^{1/4}\Big\}\right\}\cap\mathcal{A}_n^G.
\end{align*}

