[Definition def-class A of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] \begin{enumerate}
    \item We denote by  $\mathscr{A}_0$ the set of Borel sets $A \subsetU^\prime \setminus\{0\}$ such that
{\color{black}\begin{equation}
\overline{\mathbb{E}} \left[ \sum\limits_{0<s\leq T} \1_A(\Delta \overline{M}(s)) \right] < \infty.
\end{equation}}

\item Let $(\alpha,\beta)  \in (0, \infty)^{2}_{+}$. We denote 
\begin{align*}
 S_{\alpha,\beta} &\coloneqq \{ u \inU^\prime : \alpha \leq \@ifstar{\oldabs}{\oldabs*}{u}_{U^\prime} \leq \beta \},
 \\
 S_\alpha&\coloneqq\{u\in U^\prime: \alpha \le \@ifstar{\oldabs}{\oldabs*}{u}_{U^\prime}\}.
\end{align*}

By $\mathscr{A}_1(\alpha,\beta)$, respectively $\mathscr{A}_{2}(\alpha)$, we will denote  the set of all closed subsets $A$ of $U^\prime \setminus\{0\}$ such that 
\begin{equation*}
  A \subset S_{\alpha,\beta} \mbox{ or  respectively, }A\subset S_\alpha .
\end{equation*}
\item  We put
\[
\mathscr{A}_1\coloneqq\bigcup_{(\alpha,\beta)  \in (0, \infty)^{2}_{+}} \mathscr{A}_1(\alpha,\beta).
\]
\end{enumerate}

