[Cor Corid4 of arXiv:2411.14766, 'Axis-Driven Random Walks on $\Z^2$ \\ (transient cases)'] Assume $0<\alpha<\nicefrac{1}{2}$, for any fixed $x$, $z=(x,1)$ or $z=(1,x)$ and $i$ large 
   \begin{align} \mathbb{E}_{z}(\overline{Z}_{\rho_i})  =  {\mathbf{c_{_1}}} \cdot (i+g_{\alpha} \cdot i^{\frac{1-2\alpha}{1-\alpha}})^{\frac{1}{1-\alpha}}+o_i(1)


   \end{align}
   where $ {\mathbf{c_{_1}}}=(2(1-\alpha))^{\frac{1}{1-\alpha}}$ and $g_{\alpha}=\frac{ {\mathbf{c}}}{2( {\mathbf{c_{_1}}})^{\alpha}}$.
   Also, 
   \begin{align}
    \sum_{m \leq i} \mathbb{E}_z(\overline{Z}_{\rho_m}-\overline{Z}_{\eta_m} )  \sim   {\mathbf{c_{_1}}} i^{1/(1-\alpha)}\ and\ \mathbb{E}_{z}(\overline{Z}_{\eta_i}) \sim  {\mathbf{c_{_1}}} i^{1/(1-\alpha)}. 

    \end{align}

[Thm1 9 of arXiv:2608.29797, 'Mean-field branching SDEs: propagation of chaos, scaling limits and phase transitions'] Suppose that Condition \ref{con2} holds.  Then, for every
$0<A<a_*$, there exist strictly positive constants
$C_1,C_2$ and $\lambda$, depending on $A$ and $\mu_0$, such that
for all $t\geq0$, $N\geq2$ and $a\in(0,A]$,
\begin{equation}
W_{d^N}(\mu^{\bigotimes N}_t, \mu_t^N) \leq C_1 e^{-\lambda t}W_{d^N}(\mu^{\bigotimes N}_0, (\mu_0^N)^{\bigotimes N}) + C_2 N^{-1/2},
\end{equation}
where $\mu^{\bigotimes N}_t$ is the product law of $N$ independent solutions to \eqref{X} with initial distribution $\mu_0$, and $\mu^N_t$ is the law of the particles driven by \eqref{Xi} with  initial distribution $(\mu_0^N)^{\bigotimes N}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:groundstate of arXiv:2608.30831, 'Sharp discrete Hardy constants in dimensions three and four\\ and strict upper bounds from'] Let $h>0$ on $\mathbb Z^N\setminus\{0\}$ and set $h(0)=0$.  For every finitely
supported $u$ with $u(0)=0$,
\begin{align}
 \mathcal E_N[u]
 &-\sum_{n\ne0}\frac{(-\Delta_{\!d} h)(n)}{h(n)}|u(n)|^2\notag\\
 &=\sum_{\substack{\{n,m\}\in E_N\\n,m\ne0}}
 h(n)h(m)
 \left|\frac{u(n)}{h(n)}-\frac{u(m)}{h(m)}\right|^2.
\end{align}
In particular, if
\begin{equation}
 |n|^2\frac{(-\Delta_{\!d} h)(n)}{h(n)}\ge\lambda
 \qquad(n\ne0),
\end{equation}
then $C(N)\ge\lambda$.

