[Definition 15 of arXiv:2506.10511, '2506.10511'] For fixed $i\in [1,K]_{\mathds{Z}}$,
\begin{itemize}

\item[(1)] let $E_{i,3}$ be the event that $ V^{(1)}_{i,k}\nsim V^{(2)}_{i,l}\ \text{for all }k\in [1,s_{i,1}]_{\mathds{Z}}$ and all $l\in [1, s_{i,2}]_{\mathds{Z}}$, and $D_i\geq c_{*,1} M_i^{\theta}$, where $c_{*,1}>0$ (depending only on $d$ and $\beta$) is the constant in \eqref{di}.
\medskip

\item[(2)] let $E_{i,4}$ be the event that $ V^{(1)}_{i,k}\sim V^{(2)}_{i,l}\ \text{for all }k\in [1,s_{i,1}]_{\mathds{Z}}$ and all $l\in [1, s_{i,2}]_{\mathds{Z}}$.
\end{itemize}

[Proposition prop:chaos-lns of arXiv:2411.10419, 'Lower bounds on the top Lyapunov exponent for linear PDEs driven by the 2D stochastic Navi'] Fix any $ \mathbf{q} >1 $. Consider the map $ \Phi $ as in (equation e:def-phi of the paper) with $ L [u] = u \cdot \nabla
+ \Delta u \cdot \nabla^{-1} $.  For any $ 2 <\alpha < \beta < \mathbf{a}/2 $, we can estimate uniformly
over $ \kappa \in (0, 1] $ and $ M \geqslant \kappa^{-\mathbf{q}} $:
\begin{equ}
\mathbb{E} \bigl\| \mathcal{L}_{\sqrt{2}}  \bigl[  \Pi^{(1)}S_{t_{\star}^{\kappa} (M)} \bigr] \bigr\|^{2}\lesssim
(t_{\star}^{\kappa} (M))^{4} \kappa^{-1} (\| u_{0}
\|+1)^{4}_{\mathcal{C}^{\beta}} \| \varrho_{0} \|_{H^{- (\alpha+1)}}^{2} \;.
\end{equ}

[Corollary 48 of arXiv:2608.29585, '2608.29585'] For every zero-framed knot $K$, every $n\ge2$, and every $k\ge0$,
\begin{equation}
 \Delta_k^{(n)}(J(K))\in
 V_k^{(n)}\Z[q^{\pm1}].
\end{equation}

[Definition def:KLDobrushin of arXiv:2411.08295, 'Improving the convergence of Markov chains via permutations and projections'] Let $\pi \in \mathcal{P}(\mathcal{X}), P \in \mathcal{S}(\pi)$. Then the KL-divergence Dobrushin coefficient of $P$, $c_{KL}(P)$, is defined to be
	\begin{align*}
		c_{KL}(P) := \max_{M,N \in \mathcal{S}(\pi), M \neq N} \dfrac{D^{\pi}_{KL}(MP \| NP)}{D^{\pi}_{KL}(M \| N)} \in [0,1].
	\end{align*}

[Corollary 12 (Descents in symmetric shelf shuffle) of arXiv:2606.18047, 'Analysis of the asymmetric shelf shuffle'] When $p=q=1/2$, we have 
\begin{align*}
\mathbb{E}[D_n] &= \frac{n-1}{2}, \\
\Var(D_n) &=\frac{n+1}{4}-\frac{m}{2}
+\frac{(n+1)mS_n(m)-(n+2)S_{n+1}(m)}{m^n}.

\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma prop:M_expansion of arXiv:2412.04579, 'Solvable Families of Random Block Tridiagonal Matrices'] Let $\lambda_i, i \in [\![rn ]\!]$, and $Q_{a,b}, a\in [\![r ]\!], b\in [\![rn ]\!]$ be fixed numbers. For $m\in [\![r ]\!]$, $\mathcal{A}\subset [\![rn ]\!]$, let $Q_m(\mathcal{A})=\prod_{a\in \mathcal{A}} Q_{m,a}$.

 Then
\begin{align*}
 \det \mathbf{M}({\lambda}, \mathbf{Q})&= \sum_{(\mathcal{A}_1,\dots,\mathcal{A}_r)\in {\mathcal P}_{r,n}} \!\!\operatorname{sgn}(\sigma_{\underline{\mathcal{A}}}) \prod_{m=1}^r Q_{m}(\mathcal{A}_m) \Delta(\mathcal{A}_m).
\end{align*}

[Corollary 135 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Estimate \eqref{5.25,1} says that the operator
$f\to bP_{\alpha,k}f$ is bounded in $L_{q_{1},q_{2}}$. Its conjugate (with time reversed)
is then also bounded as an operator in 
$L_{q'_{1},q'_{2}}$, where $q_{i}'=q_{i}
/(q_{i}-1)$, that is
$$
\|P_{\alpha,k}(bf)\|_{L_{q'_{1},q'_{2}}}
\leq N\|b\|_{\dot E_{q,q,\alpha} }
\|f\|_{L_{q'_{1},q'_{2}}}.
$$
In case $q_{1}=q_{2}=2$ and $\alpha=1$ we have that, if $q>2$, then
$$
\|P_{1,k}(bf)\|_{L_{2} }
\leq N\|b\|_{\dot E_{q,q,1} }
\|f\|_{L_{2} }. 
$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma_new2.1 of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For any $N\ge 1$, $D_1 \subset \widetilde{B}(N)$, $x\in \partial B(2N)$ and $D_2\subset [\widetilde{B}(3N)]^c$ and for each $j\in \{1,2\}$, 
   		\begin{equation} 
				\widetilde{\mathbb{P}}_{x}\big(\tau_{D_j}=\tau_{v}<\tau_{D_{3-j}} \big) \asymp \widetilde{\mathbb{P}}_{x}\big(\tau_{D_j}=\tau_{v}<\infty \big) ,\  \ \ \forall v  \in \widetilde{\partial }D_j.	
				\end{equation}

