[Lemma 25 (Monomial elimination of the earlier-vanishing system) of arXiv:2609.02449, 'Finite Directional Coefficient Modules over Euler Fibers of $A$-Hypergeometric Systems'] The map $\mu_{\Lambda}$ in \eqref{eq:classwise-monomial-elimination-map} satisfies
\begin{equation}

\Ker(\mu_{\Lambda})=U_{\Lambda}^{\mathrm{tr}}.
\end{equation}
Moreover,
\begin{equation}

\mu_{\Lambda}\left(U_{\Lambda,\bm{w}}^{<K}\right)=\mathfrak{Q}_{\Lambda,\bm{w}}^{<K}
\end{equation}
and
\begin{equation}

\mu_{\Lambda}^{-1}\left(\mathfrak{Q}_{\Lambda,\bm{w}}^{<K}\right)=U_{\Lambda,\bm{w}}^{<K}.
\end{equation}

[Definition def:negative-translation of arXiv:2608.29708, 'Intuitionistic and Constructive Modal Logics for Classical Modal Logicians'] We inductively define the \emph{(G\"odel--Gentzen) double negation translation}
  $(\cdot)^N: \mathscr{L}_p \to \mathscr{L}_p$:
  \begin{align*}
    \bot^N &\coloneq \bot, & p^N &\coloneq \neg\neg p, \\
    (\varphi \land \psi)^N &\coloneq \varphi^N \land \psi^N, &
    (\varphi \lor \psi)^N &\coloneq \neg(\neg\varphi^N \land \neg\psi^N), \\
    (\varphi \to \psi)^N &\coloneq \varphi^N \to \psi^N.
  \end{align*}

[Definition def:cQ-def of arXiv:2509.08928, 'The near critical random bond Ising model via embedding deformation'] Given $\mathcal{S} = \mathcal{S}_\mathcal{X}$, the \emph{origami} function, denoted by $\mathcal{Q} = \mathcal{Q}_\mathcal{X} : \Lambda(G) \to \mathbb{R}$, is defined (up to a global additive constant) as a real-valued function. Its increments between two neighboring vertices $v^{\bullet}(c)$ and $v^\circ(c)$ are given by
\begin{equation}

\mathcal{Q}(v^\bullet(c))-\mathcal{Q}(v^\circ(c))\ :=\ |\mathcal{X}(c)|^2\,=\,|\mathcal{S}(v^\bullet(c))-\mathcal{S}(v^\circ(c))|\,.
\end{equation}
We will often shorten $|\mathcal{X}(c)|^2=\delta_c$ the length of the edge of $\Lambda(G)$ attached to the corner $c$. The alternate sum of edge-lengths in a tangential quad vanishes, which ensures the consistent definition for $\mathcal{Q}$. One can see $\mathcal{Q}$ as a folding of the quadrilaterals along their diagonals (see e.g. [CLR1]), which makes $\mathcal{Q}$ a $1$-Lipschitz in the $\mathcal{S} $ plane.

[Lemma lem:distinct-pair of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] If $L_w(\ell)\ge\tfrac12$, then
\begin{equation}
  s^{\times}(S)
  \le
  \frac{M_w+\binom{\ell}{2}}{2}
  -\frac{L_w(\ell)^2-L_w(\ell)}4.
\end{equation}

[Lemma Lem local asymp cut disks expect CR 1 8 of arXiv:2604.15146, 'Renormalised two-point functions of CLE$_4$ gaskets'] As $\max(\varepsilon_1,\varepsilon_2)\to 0$, we have that
\begin{multline*}
\mathbb{P}(E_{\varepsilon_1,\varepsilon_2}^{v,\rm{holes}})
\sim
\mathbb{P}(E_{r_0,\varepsilon_1,\varepsilon_2}
\cap
E_{r_0,\varepsilon_1}^{(1),\rm{holes}}
\cap
\{\mathbb{D}(z_1,r(\varepsilon_1))
\subset
\widehat{D}_{r_0}(z_1)\}
\cap
E_{r_0,\varepsilon_2}^{(2),\rm{holes}}
\cap
\{\mathbb{D}(z_2,r(\varepsilon_2))
\subset
\widehat{D}_{r_0}(z_2)\})
\\=
\dfrac{2}{\pi}
\varepsilon_{1}^{1/8}
\varepsilon_{2}^{1/8}
(1+o(1))
\\
\times
\mathbb{E}
\Big[
\Big(
\prod_{j\in \{1,2\}}
\log\big(
\varepsilon_j^{-1}\CR(z_j,\widehat{D}_{r_0}(z_j))
\big)^{1/2}
\CR(z_j,\widehat{D}_{r_0}(z_j))^{-1/8}
\Big)
\1_{E_{r_0,\varepsilon_1,\varepsilon_2}}
\1_{\{\mathbb{D}(z_j,r(\varepsilon_j))
\subset
\widehat{D}_{r_0}(z_j), j\in\{1,2\}\}}
\Big]
.
\end{multline*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi process of arXiv:2412.09471, 'On the moderate deviation principles in the sparse multi-type Erd\H{o}s R\'enyi random gra'] For all $n$ fixed, let $\{X^n_i\}_{i\ge 1}$ be a sequence of $i.i.d$ random vectors in $${\mathbb S}_{n}:=\{k:k_r\in\{1,\cdots,\lfloor\mu^n_r n\rfloor\},r\in{\mathcal S}\}$$ with  common law
\begin{equation}
    {\mathbb P}(X^{n}=k)=
    \frac{1}{Z_n}
    \frac{n^{|k|-1}p_n(k)\prod_{s\in{\mathcal S}}\left({\mu^n_s}\prod_{r\in{\mathcal S}}\left(1-\frac{\kappa(r,s)}{n}\right)^{\mu^n_rn-\frac{k_r}{2}}\right)^{k_s}}
    {\prod_{s\in{\mathcal S}}k_s!},
\end{equation}
where
\[
    Z_n=\sum_{k\in{\mathbb S}_{n}}
    \frac{n^{|k|-1}p_n(k)\prod_{s\in{\mathcal S}}\left({\mu^n_s}\prod_{r\in{\mathcal S}}\left(1-\frac{\kappa(r,s)}{n}\right)^{\mu^n_rn-\frac{k_r}{2}}\right)^{k_s}}
    {\prod_{s\in{\mathcal S}}k_s!}
\]
is the normalizing constant. Let $N(Z_nn)$ be a Poisson process with intensity $Z_n n$ and independent of the sequence $\{X^{n}_i,i\in{\mathbb N}\}$.

[Theorem thm:general of arXiv:2608.30888, 'Three-term asymptotics for discrete\\ Hardy--Rellich constants in high dimension'] For every fixed $\ell\geq1$, as $N\to\infty$,
\begin{equation}
 C_\ell(N)=2^\ell N^\ell+\gamma_\ell N^{\ell-1}
 +\delta_\ell N^{\ell-2}+O_\ell(N^{\ell-3}),
\end{equation}
where $\gamma_\ell$ is given by (equation eq:gamma of the paper) and $\delta_\ell$ by
(equation eq:delta of the paper).  The remainder is bounded in absolute value by
$A_\ell N^{\ell-3}$ for $N\geq N_0(\ell)$.

[Lemma Holub-NA1-Lemma5 of arXiv:2609.00794, 'On operators whose adjoints or second adjoints attain their norms'] Let $X$ and $Y$ be Banach spaces. Then,
\begin{equation*}
    B_{\mathcal{F}(Y^*, X^*)} \subseteq \overline{B_{\mathcal{F}_{w^*, w^*}(Y^*, X^*)}}^{\tau_c}. 
\end{equation*}

[Lemma varv of arXiv:2608.09589, 'On stochastic stability of systems\\ driven by red noise\thanks{The authors gratefully ack'] Under Assumptions (mju of the paper) and (equation of the paper), there is $h_0>0$ such that,
for $h\leq h_0$,
there exist $0<\delta_1<1$ and $C_1=C_1(h)>0$ such that
\begin{equation}
|x+h\mu(x)+\sigma(x)w|\leq \delta_1 |x|+C_1(1+|w|),\ x,w\in\mathbb{R}^d.
\end{equation}

[Lemma lem:endpoint-transfer-square-sums-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Almost surely, on the event \(\{M>0\}\),
\begin{equation}
\liminf_{n\to\infty}
\frac{\log_2\Sigma_n}{-n}
=
\dim_2(\mu)
=
\liminf_{n\to\infty}
\frac{\log_2\Sigma_n(\mu)}{-n}.
\end{equation}

[Corollary 9 (Finite \(n\) local consequences) of arXiv:2608.04799, '2608.04799'] For every compact \(K\Subset E\), there are \(C_K,c_K>0\) such that, for all
\(n\ge n_\lambda\) and \(m\ge1\),
\begin{equation}
  \Prob\{\Xi_n(K)\ge m\}
  \le \frac{C_K^m}{m!}e^{-c_Km^3}.
\end{equation}
Let \(h:E\to\mathbb C\) be bounded and Borel measurable with
\(\operatorname{supp}h\subset K\), and define
\begin{equation}
  G_n(h)=\E\prod_{z\in\Xi_n}(1+h(z)),
\end{equation}
where atoms are counted with multiplicity.  Then
\begin{equation}
  G_n(h)
  =\sum_{q=0}^\infty\frac1{q!}
    \int_{E^q}\prod_{i=1}^q h(z_i)
    \,\dd\alpha_{\Xi_n}^{(q)}(\mathbf z).
\end{equation}
For every \(T<\infty\), there are \(A=A(K,T)<\infty\) and
\(d=d(K,T)>0\) such that, for every \(Q\in\mathbb Z_{\ge0}\),
\begin{equation}
\begin{aligned}
  \sup_{\substack{n\ge n_\lambda,\ \operatorname{supp}h\subset K\\
                   \|h\|_\infty\le T}}
  \left|G_n(h)-\sum_{q=0}^Q\frac1{q!}
    \int_{E^q}\prod_{i=1}^q h(z_i)
    \,\dd\alpha_{\Xi_n}^{(q)}(\mathbf z)\right|
  \le A e^{-dQ^3}.
\end{aligned}
\end{equation}
For every Borel set \(B\subset K\), the choice \(h=-\one_B\) gives the
finite \(n\) void probability estimate
\begin{equation}
 \sup_{n\ge n_\lambda}
 \left|\Prob\{\Xi_n(B)=0\}
 -\sum_{q=0}^Q\frac{(-1)^q}{q!}
   \E[(\Xi_n(B))_q]\right|
 \le Ae^{-dQ^3},
\end{equation}
where \(A,d\) may be taken from \eqref{eq:Gn-tail} with \(T=1\).
If \(f:E\to\mathbb C\) is bounded and Borel measurable with
\(\operatorname{supp}f\subset K\), then \eqref{eq:Gn-tail} also applies to the
complex local Laplace functional after taking \(h=e^{-f}-1\).  In particular,
for every \(t\ge0\),
\begin{equation}
  \sup_{n\ge n_\lambda}\E e^{t\Xi_n(K)}<\infty.
\end{equation}

[Lemma 5 of arXiv:2506.17061, 'Non-uniform bounds for non-normal approximation via Stein's method with applications to th'] Let $p\ge 2k-1$ and $z \ge 5$. Then for $0<a< 1$, we have
		\begin{equation} 
			\E \left(\Delta^2\mathbf{1}(|\Delta|\le a)\mathbf{1}(z-a \le W \le z+a)\right) \le \dfrac{B^{p}(1+\E|W|^{2p})a(\sqrt{\E R^2} + \lambda)}{(1+z)^p}.
		\end{equation}

