[Proposition prop:tk of arXiv:2606.05830, '{ Biased Random Walk on $\mathbb Z_+$ with Traps of Linearly Increasing Depth}\footnote{Su'] Fix $0<\lambda\ne 1.$ {\rm(i)} We have
\begin{align}
  E[T_k]= \frac{2\lambda(\lambda^2+\lambda-1)}{(\lambda-1)^2(1+\lambda)}\lambda^{k-1}
-\frac{\lambda^2+2\lambda-1}{(\lambda-1)^2}
+\frac{2\lambda^{2-k}}{(\lambda-1)^2(1+\lambda)},\quad k\ge1,
\end{align}
 and \begin{align}
  E[T_k^2]\le c_2\left(\lambda\vee \lambda^{-1}\right)^{2k}, \quad k\ge 1
\end{align} for some constant $c_2$ depending only on $\lambda.$

 {\rm(ii)}
  There exist constants $c_3>0$ and $\delta>0$ depending only on $\lambda$ such that
\begin{equation}
P(T_k \ge c_3 (\lambda\vee\lambda^{-1})^k) \ge \delta,\quad k\ge1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2608.29984, 'On Cauchy Problems for Parabolic Equations with Rough Coefficients'] Assume $u_{0}(x)$ and $f(t,x)$ satisfies the assumptions in Theorem \ref{main}, then
\begin{equation}
\begin{split}
&\|u_{0}^{\epsilon}\|_{\dot{H}^{r}(\R)}\lesssim \|u_{0}\|_{\dot{H}^{1}(\R)}+\|u_{0}\|_{\dot{H}^{r}(\R)}+o_{\epsilon}(1),\ \forall r\in[1,1+s],\\
&\|f^{\epsilon}\|_{L^{2}([0,T]\times H^{t}(\R))}\lesssim \|f\|_{L^{2}([0,T]\times H^{t}(\R))}+o_{\epsilon}(1),\ \forall t\in[0,s].
\end{split}
\end{equation}
Assume $u_{0}(x)$ and $f(t,x)$ satisfies the assumptions in Theorem \ref{maintwo}, then
\begin{equation}
\begin{split}
&\|u_{0}^{\epsilon}\|_{H^{r}(\R)}\lesssim \|u_{0}\|_{H^{r}(\R)}+o_{\epsilon}(1),\ \forall r\in[0,s],\\
&\|f^{\epsilon}\|_{L^{2}([0,T]\times H^{t}(\R))}\lesssim \|f\|_{L^{2}([0,T]\times H^{t}(\R))}+o_{\epsilon}(1).\ \forall t\in [-1,s-1].
\end{split}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma elim of arXiv:2505.11721, 'Variational principles for Hausdorff and packing dimensions of fractal percolation on self'] Recall the constant $C'_1$ defined in (equation C'1 of the paper). Fix $\delta\in(0,\epsilon/C'_1)$. With probability~1, for $N$ large enough, 
\begin{equation}
\Sigma_\omega\cap \Big (\bigcup_{\boldsymbol{p}\in \widetilde {\mathscr{P}}^{\ell,\epsilon,\eta, \lfloor\Lambda_aN\rfloor }_{\mathcal{I}}} E_{\boldsymbol{p}}(M_\delta, m(g_s(N)), \delta)\Big )=\emptyset.
\end{equation}

[Lemma 22 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] \begin{displaymath}
        H \big(\pi_{x} | \pi_{y} \big) = y H \big( \pi_{\frac{x}{y}} | \pi_{1} \big) = y \phi \Big( \frac{x}{y}  \Big), \quad \forall x,y>0.
    \end{displaymath} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma equalitytwomaps of arXiv:2608.01279, 'Stochastic heat equation with nondegenerate Hölder diffusion coefficient: uniqueness below'] The maps $K_\delta,S_\delta$ satisfy that
\begin{equation}
K_\delta K_\delta^*+S_\delta S_\delta^*=I.

\end{equation}

