[Lem 31 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma >0$, $0 \leq s \leq t \leq T$, $n \in \mathbb{N}_+$ and $ \widehat{b}_n \in \mathbb{R}$. Denote $C_{\alpha,\beta}:=8 \chi(\rho_{\alpha}) \chi(\rho_{\beta})$. Then
		\begin{align*}
			\mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{ \widehat{b}_n \int_s^t \dd r \sum_{x}   \nabla H ( \tfrac{ \lfloor x - r v_n \rfloor }{n}  )    \big[  \bar{\xi} _x^{\alpha}( \eta_r^n ) \bar{\xi} _{x+1}^{\beta}( \eta_r^n ) - \Psi_{x, \ell_n}^{\alpha,\beta}(\eta_r^n) \big]  \Bigg\}^{2} \Bigg] \leq C_{\alpha,\beta} (t-s)^2 n (\widehat{b}_n)^2 \| \nabla H \|^{2}_{2,n}.
		\end{align*}

[Definition compatible_W_cobord.def of arXiv:2609.00163, 'Decompositions and diagrams of symplectic surfaces in Weinstein domains'] We call open books $(\Gamma_\pm, \pi_\pm)$ supporting $(M_\pm, \xi_\pm)$ compatible with the Weinstein cobordism $((M_-,\xi_-), \Lambda_-)\to((M_+, \xi_+), \Lambda_+)$ if the following hold:
    \begin{enumerate}
        \item The open books $(\Gamma_\pm, \pi_\pm)$ support the contact structures $(M_\pm,\xi_\pm)$.
        \item The cobordism $(W,\omega)$ is obtained by attaching Weinstein 2-handles along $\Lambda_-$.  We call these curves $\Lambda_-$ the {\it vanishing cycles.}
        \item The link $\Lambda_-$ is included in the core of one of the contact handlebodies corresponding to the contact Heegaard splitting corresponding to $(\Gamma_-, \pi_-)$.
        \item The resulting contact Heegaard splitting of $(M_+,\xi_+)$, obtained by Legendrian surgery on the above Heegaard splitting of $(M_-,\xi_-)$, can be stabilized to ensure $\Lambda_+$ is included in the core of one of the handlebodies.
    \end{enumerate}

[Definition 9 of arXiv:2608.27569, 'Laplace and Dolbeault operators on Sasakian manifolds'] We define the twisted differential $d^{c}:\Omega ^{m}\rightarrow
\Omega ^{m+1}$ by
\begin{equation*}
d^{c} =\sum_{k}(\phi e_{k})^{\flat }\wedge \nabla _{e_{k}}
\end{equation*}
on any $m$-form, where $\{e_{k}\}$ is a local orthonormal frame
for $\xi ^{\bot }$.

[Lem 1 of arXiv:2506.18207, 'Cartan's Path Development, the Logarithmic Signature and a Conjecture of Lyons-Sidorova'] For any simple path $\gamma = (x_t,y_t)$, if $\gamma|_{[0,1]}$ has infinite radius of convergence for its log-signature and $x_t\in[-1,1]$ for all $t\in[0,1]$, then looking at any fixed horizontal level $y=a$ of the image $\gamma([0,1])$, we only have the following two cases: 
\begin{itemize}
       \item The right street copies the left street. In the sense that for any $x\in(0,1)$, $(x,a)\in\gamma([0,1])$, we have $(x-1,a)\in\gamma([0,1])$. For any $x\in(-1,0)$, $(x,a)\in\gamma([0,1])$ we have $(x+1,a)\in\gamma([0,1])$.

       \item Both capture the missing points of the other. In the sense that for any $x\in(0,1)$, $(x,a)\notin\gamma([0,1])$, we have $(x-1,a)\in\gamma([0,1])$. For any $x\in(-1,0)$, $(x,a)\notin\gamma([0,1])$, we have $(x+1,a)\in\gamma([0,1])$.
\end{itemize}

[Lem uniform-lln-horizon of arXiv:2604.07183, 'Stopping on the last success with unknown odds: asymptotic minimax optimality of the plug-'] Let~$(p_n)$ be a sequence in~$(0,1)$ such that~$p_n\to 0$ and~$np_n\to\infty$.
Consider
\begin{equation}
I_n:=\Bigl\{t\in\{1,\dots,n\}:\ t\ge t_n \Bigr\},
\end{equation}
where~$t_n\in\{1,\ldots,n\}$ for any~$n$ and~$n/t_n=O(1)$. 
Then, there exist positive constants~$C,c$ such that
\begin{equation}
\mathbb P
\bigg[
\sup_{t\in I_n}\Bigl|\frac{\hat p_t}{p_n}-1\Bigr| > \varepsilon
\bigg]
\le

C
e^{-c\varepsilon^2 np_n}
\end{equation}
for all~$\varepsilon\in(0,1)$ and all~$n$ large enough. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 (Localized mixed-energy identities) of arXiv:2609.02193, 'State-law dynamics of McKean-Vlasov stochastic reaction-diffusion equations on $\mathbb R^'] Let $I=[a,b]$ and let $\zeta\in W^{1,\infty}(\mathbb R^n)$ be real valued. Suppose that
	\begin{align*}
		w\in C(I;H)\cap L^2(I;V)\cap L^p(I;L^p(\mathbb R^n))
	\end{align*}
	and, in $\mathcal D'(a,b;\mathbb V^*)$,
	\begin{align*}
		\frac{dw}{dt}=F_2+F_p,
		\qquad
		F_2\in L^2(I;V^*),
		\quad
		F_p\in L^{p'}(I;L^{p'}(\mathbb R^n)).
	\end{align*}
	Then, for $a\leq r\leq s\leq b$,
	\begin{align}
		\|\zeta w(s)\|^2-\|\zeta w(r)\|^2
		=2\int_r^s\Big[
		\langle F_2(\tau),\zeta^2w(\tau)\rangle_{V^*,V}
		+\langle F_p(\tau),\zeta^2w(\tau)\rangle_{L^{p'},L^p}
		\Big]d\tau.
	\end{align}
	If $U$ is progressively measurable,
	\begin{align*}
		U\in L^2(\Omega;C(I;H))
		\cap L^2(\Omega\times I;V)
		\cap L^p(\Omega\times I;L^p(\mathbb R^n)),
	\end{align*}
	and, in $\mathbb V^*$, $\mathbb P$-a.s.,
	\begin{align*}
		U(t)=U(a)+\int_a^t(F_2(s)+F_p(s))ds
		+\sum_{j=1}^{m}\int_a^t\sigma_j(s)dW_j(s),
	\end{align*}
	where $F_2\in L^2(\Omega\times I;V^*)$, $F_p\in L^{p'}(\Omega\times I;L^{p'}(\mathbb R^n))$ and $\sigma_j\in L^2(\Omega\times I;H)$ are progressively measurable, then, up to indistinguishability,
	\begin{align}
		\|\zeta U(t)\|^2
		&=\|\zeta U(a)\|^2
		+2\int_a^t\Big[
		\langle F_2(s),\zeta^2U(s)\rangle_{V^*,V}
		+\langle F_p(s),\zeta^2U(s)\rangle_{L^{p'},L^p}
		\Big]ds\notag\\
		&\quad
		+\sum_{j=1}^{m}\int_a^t\|\zeta\sigma_j(s)\|^2ds
		+2\sum_{j=1}^{m}\int_a^t
		(\zeta U(s),\zeta\sigma_j(s))dW_j(s).
	\end{align}
	The same formula is valid under the corresponding local integrability assumptions after stopping-time localization.

