[Lemma 8 of arXiv:2606.22611, 'Upper and Lower Bounds on Expected Soft Maxima\\of Gaussian Processes'] Let $X = (X_t)_{t \in T}$ be a centered Gaussian process with a discrete index set $T$, such that
  $$
 \sup_{t \in T} \Var(X_t) \le \sigma^2 < \infty
 $$
 for some $\sigma > 0$. Let a finite measure $m$ on $T$ be given. Then the random variable
  \begin{align*}
  Z \deq \log \inner{m}{e^X}
  \end{align*}
  is $(\sqrt{2}\sigma)$-subgaussian, i.e., 
  \begin{align*}
  \Ex e^{\lambda(Z-\Ex Z)} \le e^{\lambda^2 \sigma^2 }, \qquad \text{for all } \lambda \in \Reals.
  \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 1 of arXiv:2609.03803, 'List-distance consistent vertices in trees are confined to a path'] Let $G=SP(w;\ell_1,\dots,\ell_k)$ with $k\ge3$, let $1\le i\le k$ and let
$1\le j\le\ell_i$. Then $v_{i,j}\in S_{c_i}(G)$ if and only if
\begin{equation}
  N^{(i)}_s\le s+1
  \qquad\text{for every } s \text{ with } 1\le s\le \ell_i-2j-1 .

\end{equation}

[Lemma LemmaErgodicity of arXiv:2606.13615, 'Data-Driven Subsampling Rates for Diffusion Parameter Estimation of SDEs'] Let $K$ be a Markov kernel on $(\mathbb{R}^d, \mathcal{B}(\mathbb{R}^d))$ with invariant measure $\mu$ and let $\mathbf{Z} = (\mathbf{Z}_n)_{n \in \mathbb{N}_0}$ be a homogeneous Markov chain with kernel $K$ and initial distribution $\mathbf{Z}_0 \sim \mu$. Then $\mathbf{Z}$ is ergodic if and only if
\begin{equation}

\lim_{N \rightarrow \infty} \frac{1}{N} \sum_{n=0}^{N-1} \mathbbm{1}_B(\mathbf{Z}_n) = \mu(B) \quad \text{in probability} \quad \text{for all } B \in \mathcal{B}(\mathbb{R}^d).
\end{equation}

