[Definition 2 (Repeated-pole randomization problem) of arXiv:2608.29143, 'Least Variability in a Polynomial-Square Class\\ of Rational Kernels'] For each $m\geq0$, define the optimal variance among the mean-one
randomizers of polynomial degree $m$ by
\begin{align*}
\mathfrak v_m
:=
\inf_{\substack{a\in\Pcal_m\ \deg a=m}}
\Vcal(a).
\end{align*}

[Lemma 18 of arXiv:2604.22461, 'Large deviation principles for stationary solutions and invariant measures of a class of S'] For any $t_0\in \mathbb{R}$, $\xi\in H$ and $v\in S_M$, let $X^{0,v}_{t;t_0,\xi}$ be the unique solution to Eq. \eqref{eq: skeleton}, if $\gamma_0 \geq  \tilde{\gamma}_0$, then the following results hold.
 \begin{description}
   \item[(i)] For $\gamma\in [0,\lambda_1 \gamma_0/4]$ and $t\geq t_0$, it holds that
   \begin{align}
  & \sup_{s\in [t_0,t]} \big\{ e^{-\gamma(t-s)} \|X^{0,v}_{s;t_0,\xi}\|^{2+\beta}_H+ \frac{\gamma_0}{2} \int^s_{t_0} e^{-\gamma(t-\tau)} \|X^{0,v}_{\tau;t_0,\xi}\|^{\beta}_H \|X^{0,v}_{\tau;t_0,\xi}\|^2_V \, \d \tau \big\} \nonumber   \\
  & \quad \leq e^{-\gamma(t-t_0)} \|\xi\|^{2+\beta}_H+ \big(1+\frac{\beta}{2} \big) \big(\frac{4 C_B}{\lambda_1 \gamma_0}M + \min \big\{ \frac{1}{\gamma} ,t-t_0 \big\} C_{A,\rho,0} \big);   \\
  & \sup_{s\in [t_0,t]} \big\{ e^{-\gamma(t-s)} \|X^{0,v}_{s;t_0,\xi}\|^{2}_H+ \frac{\gamma_0}{2} \int^s_{t_0} e^{-\gamma(t-\tau)} \|X^{0,v}_{\tau;t_0,\xi}\|^2_V \, \d \tau \big\} \nonumber \\
  & \quad  \leq e^{-\gamma(t-t_0)} \|\xi\|^2_H+ \big(\frac{4 C_B}{\lambda_1 \gamma_0}M + \min \big\{ \frac{1}{\gamma} ,t-t_0 \big\} C_{A,\rho,0} \big). 
\end{align}
Taking $s=t$, it implies that $\|X^{0,v}_{t;t_0,\xi}\|_H^2$ is uniformly bounded over $[t_0,+\infty)$. The upper bound is less than $C(\xi,M):= \|\xi\|^2_H+ \frac{4 }{\lambda_1 \gamma_0} \big(C_B M +C_{A,\rho,0} \big)$.
   \item[(ii)] For any $\xi_1,\xi_2\in H$, $\gamma \in (0,(\lambda_1 \gamma_0- C_{\rho_2}) \vee \frac{\lambda_1 \gamma_0}{4}]$ and $t_2 \geq t_1 \geq t_0$, we have
\begin{align}
  & \sup_{s\in [t_1,t_2]} \big\{ \|X^{0,v}_{s;t_0,\xi_1}-X^{0,v}_{s;t_0,\xi_2}\|^2_H +\frac{\gamma_0-\tilde{\gamma}_0}{2} \int^s_{t_0} \|X^{0,v}_{\tau;t_0,\xi_1}-X^{0,v}_{\tau;t_0,\xi_2}\|^2_V \, \d \tau \big\} \nonumber \\
  & \leq  \|\xi_1-\xi_2\|^2_H \exp\Big\{ \frac{2 C_B}{\lambda_1 (\gamma_0-\tilde{\gamma}_0)}M+\frac{ 2 C_{\rho_1}}{\gamma_0}\big( \|\xi_2\|^{2}_H+ \|\xi_2\|^{2+\beta}_H + \frac{2(4+\beta) C_B}{\lambda_1 \gamma_0}M ) \Big\}  e^{-\gamma(t_1-t_0)}. 
\end{align}
It implies the continuity of solution with respect to initial value.
   \item[(iii)] For every $N \in \N$, $\{X^{0,v}_{\cdot;-n,\xi}\}_{n \geq N}$ is a Cauchy sequence in $\sC_{-N}$ that converges to the same limit element $\mathcal{Y}^{0,v} \in \sC_{-\infty}$. The limit element $\mathcal{Y}^{0,v}$ is the unique solution of the controlled Eq. \eqref{eq: skeleton stationary}. And $\sup_{t \in \R} \| \mathcal{Y}^{0,v}(t) \|_{H}^2$ is uniformly bounded by $C(0,M)$ over all $v \in S_{M}$.
\end{description}

