[Theorem thm:main of arXiv:2411.09482, 'Anomalous Regularization in Kazantsev-Kraichnan Model'] Let $d$, $s$ and $\alpha$ satisfy (hp:main_hp of the paper) and let $Q$ be the covariance function given by (equation eq:Q_spectrum of the paper). Then, the following hold.
    \begin{itemize}
    \item \textbf{Strong existence:} For every $M_0$ in $\dot{H}^{-s}_{\div}$, for every given filtered probability probability space $(\Omega,\mathcal{A},(\mathcal{F}_t)_t,\mathbb{P})$ (satisfying the standard assumption) and every given $(\mathcal{F}_t)_t$-adapted Wiener process $W^\mathcal{K}$ with covariance function $Q$, there exists a $\dot{H}^{-s}$ solution $M$ to the vector advection equation (equation eq:KK of the paper), which satisfies in addition $M\in L^\infty_t(\dot{H}^{-s}_{\div})$ $\mathbb{P}$-a.s., $M\in L^\infty_t(L^2_\omega(\dot{H}^{-s}_{\div})) \cap L^2_{t,\omega}(\dot{H}^{-s+1-\alpha}_{\div})$ and
    \begin{align}
        \sup_{t\in [0,T]}\mathbb{E}[\|M_t\|_{\dot{H}^{-s}}^2] +\eta_{d,s,\alpha}\int_0^T \mathbb{E}[\|M_r\|_{\dot{H}^{-s+1-\alpha}}^2] \,\mathrm{d} r \leqslant e^{\rho_{d,s,\alpha}T} \|M_0\|_{\dot{H}^{-s}}^2.
    \end{align}
    for constants $\eta_{d,s,\alpha}>0$, $\rho_{d,s,\alpha}\ge 0$ independent of $M_0$ and $M$.
    \item \textbf{Pathwise uniqueness:} The solution is unique in the class of $\dot{H}^{-s}$-valued solutions $M$ satisfying $M\in L^2_{t,\omega}(\dot{H}^{-s+1-\alpha}_{\div})$.
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem : PointPoint/Entier of arXiv:2412.03320, 'Large deviation principle at speed $n$ for the random metric in first-passage percolation'] For all $x\in \mathbb{Z}^d$ and $\zeta > a \norme[1] x$, the limit
	\begin{equation}

		J_{\mathrm{pp}} (x,\zeta) \coloneqq \lim_{n\to\infty} - \frac1n \log \Pb{\mathbf T(0,nx)\le n\zeta} = \inf_{n\ge 1}- \frac1n \log \Pb{\mathbf T(0,nx)\le n\zeta}
	\end{equation}
	exists, and it is finite. Moreover,
	\begin{enumerate}[(i)]
		\item For all $x\in \mathbb{Z}^d$, $\zeta>a\norme[1] x$ and $k\in \mathbb{N}^*$,
		\begin{equation}

			J_{\mathrm{pp}} (kx,k\zeta) =  kJ_{\mathrm{pp}} (x,\zeta).
		\end{equation}

		\item For all $x_1, x_2 \in \mathbb{Z}^d$, $\zeta_1 > a \norme[1]{x_1}$ and $\zeta_2 > a\norme[1]{x_2}$,
		\begin{equation}

			J_{\mathrm{pp}} (x_1 + x_2, \zeta_1 + \zeta_2) \le J_{\mathrm{pp}} (x_1, \zeta_1) + J_{\mathrm{pp}} (x_2, \zeta_2).
		\end{equation}
		\item For all $x\in \mathbb{Z}^d$ and $\zeta>a\norme[1] x$,
		\begin{equation}

			J_{\mathrm{pp}} \mathopen{}\mathclose\bgroup\originalleft( x, \zeta \aftergroup\egroup\originalright) = J_{\mathrm{pp}} \mathopen{}\mathclose\bgroup\originalleft(  \module x,\zeta \aftergroup\egroup\originalright).
		\end{equation}
		\item For all $x_1, x_2 \in \mathbb{Z}^d$, $\zeta_1 > a \norme[1]{x_1}$ and $\zeta_2 > a\norme[1]{x_2}$, if $0\le x_1 \le x_2$ and $\zeta_1 \ge \zeta_2$ then
		\begin{equation}

			J_{\mathrm{pp}} \mathopen{}\mathclose\bgroup\originalleft( x_1,\zeta_1 \aftergroup\egroup\originalright) \le J_{\mathrm{pp}} \mathopen{}\mathclose\bgroup\originalleft( x_2, \zeta_2 \aftergroup\egroup\originalright).
		\end{equation}
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

