[Lemma lem:genealogy of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] {kkmt2026cle4_part2}}]
		Fix $a>0$ and let $\Gamma_{V_a}$ be a $\CLE_4$ in $V_a$.  Then, there exists $r_0>0$ such that with positive probability we have that 
		\begin{align*}
			D_{\Gamma_{V_a}}^{V_a}(\{0\} \times [0,1] ,  \{a\} \times [0,1]) < r_0 < 2r_0 \leq D_{\Gamma_{V_a}}^{V_a}([0,a] \times \{0\} ,  [0,a] \times \{1\}).
		\end{align*}
		More precisely, the following holds with positive probability. Let us divide $V_a$ into three rectangles $G_1= (0,a) \times (4/5, 1) $, $G_2= (0,a) \times (1/5, 4/5)$ and $G_3=  (0,a) \times (0, 1/5)$. Let $L_2=\{0\} \times [1/5,4/5]$ be the left boundary of $G_2$ and let $L=\{0\}\times [0, 1]$ be the left boundary of $V_a$. Let $\partial_\mathrm{R} \SCB_{r_0}(L; D^{V_a}_{\Gamma_{V_a}})$ be the right boundary of the metric ball $\SCB_{r_0}(L; D^{V_a}_{\Gamma_{V_a}})$, which we define as the intersection of $\SCB_{r_0}(L; D^{V_a}_{\Gamma_{V_a}})$ with the closure of the union of the connected components $C$ of $V_a \setminus \SCB_{r_0}(L; D^{V_a}_{\Gamma_{V_a}})$ such that $\overline{C} \cap (\{a\}\times (0,1)) \neq \emptyset$. Then,
			\begin{enumerate}[label=(\alph*)]
				\item We have $D_{\Gamma_{V_a}}^{V_a}(L_2 ,  \{a\} \times [1/5,4/5]) < r_0$;
				\item The right boundary $\partial_\mathrm{R} \SCB_{r_0}(L; D^{V_a}_{\Gamma_{V_a}})$ intersects $L_2$;
				\item We have $D_{\Gamma_{V_a}}^{V_a}([0,a] \times \{0\}, [0,a] \times \{1/5\})\ge r_0$ and $D_{\Gamma_{V_a}}^{V_a}([0,a] \times \{4/5\}, [0,a] \times \{1\})\ge r_0$.
			\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 6.13 of arXiv:2608.01279, 'Stochastic heat equation with nondegenerate Hölder diffusion coefficient: uniqueness below'] Define the following stopping time
\begin{equation}
\tau_*^n=\inf\{t:r_s(U(t)-V^n(t))\ge r_*\},

\end{equation}
using the convention \(\inf\varnothing=\infty\).  Then for any \(t<\tau_*^n\), we have

\begin{equation}
\mathfrak b(t)
\le
C_3f_\delta(r_s(t))
+C_3\left(
\delta^p+\delta^\gamma
+\varepsilon_n^2\delta^{p-2}
\right),

\end{equation}
where $C_3>0$ depends on $m[g],c_g,[g]_{C^\beta},s,p,T$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem W1 lower-bound of arXiv:2411.15724, 'Wasserstein Convergence Rates for Empirical Measures of Random Subsequence of $\{nα\}$'] Let $\big\{ I_i \, ; \, i = 1, \ldots, K \big\}$ be a family of disjoint closed intervals (more precisely, closed arcs) contained in $\mathbb{T}$. The length of each $I_i$ is denoted by $L_i$. Then for any $\nu \in \mathscr{P}(\mathbb{T})$, which is supported in the complement of $\cup_{i = 1}^{K} I_i$ (namely, $\nu ( \cup_{i = 1}^{K} I_i  ) = 0$), we have
\begin{align*}
\mathbb W_1(\nu, \mu) \geq \frac{\sum_{i = 1}^{K} L_i^2 }{4}.
\end{align*}

