[Proposition 23 of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Let $d=4$ and suppose that the assumptions of Theorem~\ref{thm:localWP_weakened} hold. Moreover, let $u_0\in L^0_{\F_0}(\Omega;H^1(\sO))$ and $T>0$. Let $(u,\sigma)$ be the unique maximal solution to \eqref{eq:SCHtorus} and $\mu$ the chemical potential of Definition~\ref{def:chemPotential}. Then, we have
	\begin{equation}
	       \sup_{t\in[0,T]\cap [0,\sigma)}\|u(t)\|_{H^1}+\int_0^{\sigma \land T} \|\grad \mu(t)\|_{L^2}^2 \dt < \infty  \qquad \mathbb{P}\text{-a.s.}
	\end{equation}
	If, in addition, $u_0\in L_{\F_0}^4(\Omega;L^4(\sO))\cap L_{\F_0}^2(\Omega;H^1(\sO))$, then
    \begin{equation}
    \E\bigg[\sup_{t\in[0,T]\cap[0,\sigma)}  \|u(t)\|^2_{H^1(\sO)} + \int_0^{\sigma \land T} \|\grad \mu(t)\|_{L^2}^2 \dt \bigg] \le C_{\psi,T,\sO}\big(1+\|u_0\|^4_{L^4(\Omega;L^4(\sO))}+\|u_0\|^2_{L^2(\Omega;H^1(\sO))}\big) < \infty.
    \end{equation}

