For a finite system of $N$ particles with states $(\bm{X}_i)_{i \in [N]}$ and weights $(\bm{W}_{i, j})_{i, j \in [N]}$, its empirical structure $\bm{\mathcal{Y}}_N = (\mathsf{X}_N, \mathsf{W}_N)$ is represented on $\Omega = [0, 1]$ equipped with Lebesgue measure by partitioning $[0, 1]$ into $N$ equal intervals $I_i = [\frac{i-1}{N}, \frac{i}{N})$ and setting $\mathsf{X}_N(\xi) = \sum_{i=1}^N \bm{X}_i \mathbf{1}_{I_i}(\xi)$ and $\mathsf{W}_N(\xi, \zeta) = \sum_{i, j = 1}^N \bm{W}_{i, j} \mathbf{1}_{I_i \times I_j}(\xi, \zeta)$.
N \in \mathbb{N}
I_i are equipartition intervals of [0, 1]

[Lemma lemma_final of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For any $3\le d\le 6$, there exists $
	\refstepcounter{newcnstcnt}
	\ensuremath{C_{\thenewcnstcnt}}(d)>0$ such that 
	\begin{equation}
		 \mathbb{P}^{D}\big( A\xleftrightarrow{\ge 0} x,y \big)\lesssim r^{-\frac{d}{2}+1+3\varsigma_d(r)}\mathbb{P}^{D}\big( A\xleftrightarrow{\ge 0} x \big)
	\end{equation}
	if either of the following two conditions (where $N\ge 1 $ and $r:=|x-y|$) holds:	\begin{enumerate}
		\item[(a)] $A \subset \widetilde{B}(N)$, $M\ge \ensuremath{C_{\ref*{const_twopoint_set}}}N^{1+\varsigma_d(N)}$, $x,y \in \partial B(M)$ and $D\subset \widetilde{B}(N)\cup [\widetilde{B}(2M)]^c$; 


		\item[(b)] $A \subset [\widetilde{B}(N)]^c$, $M\le \ensuremath{C_{\ref*{const_twopoint_set}}}^{-1}N^{1-\varsigma_d(N)}$, $x,y\in B(M)$ and $D\subset [\widetilde{B}(N)]^c \cup \widetilde{B}(\frac{M}{2}) $.  

	\end{enumerate}

