[Lemma 5 of arXiv:2605.12269, 'It\^o integral for a two-sided L\'evy process'] Let $p \geq 2$ be an even integer such that $m_p<\infty$. If $X \in \cL_p$, then
\begin{equation}

\|I_K(X)\|_p \leq \cC_p \big[ X\big]_{K,p} \quad \mbox{for any} \ K>0.
\end{equation}

[Lemma 22 ({\cite[Proposition~3.69) of arXiv:2609.04139, 'The conformally invariant metric on CLE$_4$ II:\\ existence of geodesics'] {lawler2008conformally}}]

	For $W>0$, we set $R_{W} \defeq (0,W) \times (0,\pi)$ and let $\partial_1 = [0,\pi \ri]$, $\partial_2 = \partial_{2,W} = [W,W+\pi \ri]$, $\partial_3 = \partial_{3,W} = [0,W]$, and $\partial_4 = \partial_{4,W} = [\pi \ri, W+\pi \ri]$. Let $\tau = \tau_{R_{W}}$ denote the first time that a complex Brownian motion $B$ started from $z \in R_W$ exits $R_{W}$, and set
    \begin{align*}
    	&f_1(z) = f_{1,W}(z) = 2 \min\{\BP_z[B_{\tau} \in \partial_1], \BP_z[B_{\tau} \in \partial_2]\}\\
    	&f_2(z) = f_{2,W}(z) = 2 \min\{\BP_z[B_{\tau} \in \partial_3], \BP_z[B_{\tau} \in \partial_4]\},
    \end{align*}
    and set $\Theta(W) \defeq \Theta(R_{W}; \partial_1, \partial_2) = \sup\{f_1(z) : z \in R_{W}\}$. Then $\Theta(W)$ is a continuous, strictly decreasing function of $W$ such that 
	\begin{align*}
		\Theta(W) = \left(\frac{8}{\pi}\right) e^{-W/2} + O(e^{-W}) \quad \text{as} \quad W \to \infty.
	\end{align*}
	Moreover, the supremum in the definition of $\Theta$ is attained when $z$ is the center $W/2 + \ri \pi/2$; in particular, $f_1(W/2 + \ri\pi/2) = \Theta(W)$, and likewise $\sup\{f_2(z) : z \in R_W\} = \Theta(\pi^2/W)$, by exchanging the two pairs of sides. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 17 (consistency: one-step weighted defect) of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] \label[lemma]{lem:boundary-charge}
  Assume $G'\in C^2_{\mathrm b}([0,\infty))$ and $\delta \in (1,2)$.  There exist $C_{\mathrm b}<\infty$ and $h_0>0$ such that, for all $h\in(0,h_0]$, the one-step defect of the clamped kernel \eqref{eq:clamped-kernel} satisfies
  \begin{equation}
    \|\nu_h\|_{V}=|\nu_h(\{0\})|+\int_0^\infty(1+x^2)|r(x)|\,dx\le C_{\mathrm b}\,h^{\delta}.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 29 of arXiv:2608.29361, 'Convergence of the subcritical $\gamma$-LQG metric to the critical $2$-LQG metric as $\gam'] Fix $\theta \in (0,\xi_c / 8)$ and $\beta > (1+\theta) / \xi_c$. Fix also $\xi_0 \in (((1+\theta) / \beta) \vee (\xi_c / 2) , \xi_c)$. Then, there exists a choice of the functions $b,M$ (depending only on $\theta,\beta$, and $\xi_0$) such that the following holds for all $\xi \in [\xi_0,\xi_c]$. Fix $\varepsilon \in (0,1)$ and let $U \subseteq \CC$ be a bounded open set. Then, there exists a deterministic constant $C>0$ depending only on $\theta,\varepsilon,\beta,\xi_0$, and $U$, such that the following is true with probability at least $1-\varepsilon$. For all $n \in \NN$ and all $z \in U$ for which there exists $t \in [n+1,n+2]$ such that
\begin{equation}
h_{e^{-t}}(z) - h_1(z) \geq 2t -\beta \log t,   
\end{equation}
we have that
\begin{equation*}
    \widetilde{D}_h^{\xi}(\partial B_{e^{-n-40}}(z) , \partial B_{e^{-n/2 - 1}}(z)) \leq C n^{-\theta}.
\end{equation*}

