[Lem L4.2 of arXiv:2609.03848, 'The mean-field limit of the Schr\"{o}dinger-Lohe model\\ and emergent dynamics'] Let  $\{ (\phi_k, V_k) \}$ and $\{ ({\tilde \phi}_k, {\tilde V}_k) \}$ be solutions to (equation C-1 of the paper). Then, one has
\begin{eqnarray*}
&& (i)~|{\mathcal I}_{21} | \leq \frac{L_1}{2N} \sum_{k=1}^N\int_{\Lambda_N\times\Lambda_N}\Big (3\|\phi_k-\tilde\phi_k\|^2_\mathfrak{H}+\|V_k-\tilde V_k\|^2_{L^{\infty}} \Big)  Q_N(t,d\Phi_Nd\mathcal{V}_Nd\tilde\Phi_Nd\tilde\mathcal{V}_N). \cr
&& (ii)~|{\mathcal I}_{22} | \leq \frac7{2N}\sum_{k=1}^N \int_{\Lambda_N\times\Lambda_N}\|\phi_k-\tilde\phi_k\|^2_\mathfrak{H} Q_N(t,d\Phi_Nd\mathcal{V}_Nd\tilde\Phi_Nd\tilde\mathcal{V}_N)  \\
&& \hspace{1.5cm} + \tfrac12 \int_{\Lambda_N\times\Lambda_N}\left\|\frac1N\sum_{l=1}^N\left(\tilde\phi_l-\int_{\mathbf{S}\mathfrak{H}}\tilde\phi\rho_f(t,d\tilde\phi)\right)\right\|^2_\mathfrak{H} Q_N(t,d\Phi_Nd\mathcal{V}_Nd\tilde\Phi_Nd\tilde\mathcal{V}_N),
\end{eqnarray*}
where $L_1$ is a positive constant defined by the following relation:
\begin{equation} 
L_1:=\tfrac1\hbar\max\left \{ \max_{1\le k\le N}\|V_k\|_{L^\infty}+3\|{\omega}\|_{L^\infty},1\right \}.  
\end{equation}

