body:
[Theorem theorem12.234567twovectors of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] In this theorem we take $\nu=2^{-15}$ and $p\in(\frac{1}{2^7B^4},1)$ is a constant depending only on $\zeta$.
    For given $n\in\mathbb{N}$, $0<c_0\leq 2^{-50}B^{-4}$, let $d\leq c_0^2n$ and fix $\alpha_0\in(0,1)$. Let $\mathbf{t}=(t_1,t_2)$ be two positive real numbers. Consider two vectors $X_1,X_2\in\mathbb{R}^d$ that satisfy $\operatorname{LCD}_{\frac{8\sqrt{2}}{\sqrt{\nu p}}+\frac{256\sqrt{2}B^2}{\sqrt{c_0}},\alpha_0}^\mathbf{t}(\frac{c_0}{32\sqrt{n}}\mathbf{X})\geq 512B^2$ (where we denote $\frac{c_0}{32\sqrt{n}}\mathbf{X}=(\frac{c_0}{32\sqrt{n}}X_1,\frac{c_0}{32\sqrt{n}}X_2)$). Let $H$ be an $(n-d)\times 2d$ random matrix with i.i.d. rows of distribution $\Phi_\nu(2d;\zeta)$.  Then whenever $k\leq 2^{-21}B^{-4}d$ and $R^2t_1t_2\geq\exp(-2^{-23}B^{-4}d)$, we have the following 
    \begin{equation}\begin{aligned}
        \mathbb{P}_H&(\sigma_{2d-k+1}(H)\leq c_02^{-4}\sqrt{n}\text{ and }\|H_1X_i\|_2,\|H_2X_i\|_2\leq n\text{ for both }i=1,2)\\&\leq e^{-c_0nk/12}(\prod_{i=1}^2\frac{R t_i}{\alpha_0})^{2n-2d},
   \end{aligned}\end{equation}
    where $H_1=H_{[n-d]\times[d]}$, $H_2=H_{[n-d]\times[d+1,2d]}$ and $R=2^{44}B^2c_0^{-3}(\frac{8}{\sqrt{\nu p}}+\frac{256B^2}{\sqrt{c_0}})$, and $\sigma_1(H)\geq\sigma_2(H)\geq\cdots\sigma_{2d}(H)$ are the singular values of $H$ arranged in a decreasing order. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def: modified transport equation of arXiv:2608.23756, 'Measure-valued fluid limits for partial service queues\\with correlated patience and servi'] Fix $[a, b] \subset \mathbbm{R}_+$ and a Borel function $\map{\bar \boldsymbol{y}}{[a, b]}{[0, \infty]}$. Suppose that $\boldsymbol{\mu} \in D_{\mathcal{M}_F(\mathbbm{R}_+^2)}[a, b]$ is such that $|\boldsymbol{\mu}|$ satisfies (a) and (b) of Definition (def: fluid problem of the paper) and the integrals
	\begin{equation*}
		\int_a^t\int_{U_g} \left[\mathbbm{1}_{\left\{y \leq \bar \boldsymbol{y}_s\right\}}h_g^x(x, y) + h_g^y(x, y)\right]\boldsymbol{\mu}_s(dx, dy)ds
	\end{equation*}
	are finite for all $t \in [a, b]$. Let $\bar \boldsymbol{r}_s(y) \vcentcolon= \mathbbm{1}_{\left\{y \leq \bar \boldsymbol{y}_s\right\}}$ for all $s \in [a, b]$ and $y \in \mathbbm{R}_+$. We say that $\boldsymbol{\mu}$ solves the transport equation (equation eq: transport equation with given threshold of the paper) with prescribed threshold $\bar \boldsymbol{y}$ in the interval $[a, b]$ if
	\begin{equation}

		\begin{split}
			\angled{\varphi_t}{\boldsymbol{\mu}_t} &= \angled{\varphi_a}{\boldsymbol{\mu}_a} + \lambda_0 \int_a^t \varphi_s(0, 0)ds - \int_a^t \angled{\varphi_s\left[\bar \boldsymbol{r}_s h_g^x + h_g^y\right]}{\boldsymbol{\mu}_s} ds \\
			&+ \int_a^t \angled{\partial_t\varphi_s + \bar \boldsymbol{r}_s\partial_x\varphi_s + \partial_y\varphi_s}{\boldsymbol{\mu}_s}ds
		\end{split}
	\end{equation}
	for all $t \in [a, b]$ and $\varphi \in C_c^1(\mathbbm{R}_+^3)$, and we write $\boldsymbol{\mu} \in \mathcal{S}_{\bar \boldsymbol{y}}[a, b]$.

[Proposition prop:detailed-balance-convergence of arXiv:2609.02710, 'Asymptotic Mean Value Laplacian\\ on equiregular sub-Riemannian manifolds'] For $f,g\in C_c^\infty(M)$, the identity
\begin{equation}
  \int_M fA_hg\,D_h\,\,d\mu
  =-\frac1{2h^{Q+2}}
  \iint_{\{d(x,q)<h\}}
  (f(q)-f(x))(g(q)-g(x))
  \,\,d\mu(q)\,d\mu(x)
\end{equation}
holds for all  $h>0$ small enough\footnote{Note that our general assumptions do not a priori imply $\mu(B(x,h))<+\infty$ for every $h>0$.}. Moreover, for every
$f\in C_c^\infty(M)$,
\begin{equation}
  D_hA_hf
  \longrightarrow
  \frac12\operatorname{div}_{\mu}\bigl(M^\sharp(df)\bigr)
\end{equation}
in distributions.

[Theorem 19 of arXiv:2512.07202, 'Hitting Probabilities for Hypoelliptic Differential Equations Driven by Fractional Brownia'] Let $(X_t)_{t\in[0,T]}=(X^1_t,\cdots,X^d_t)_{t\in[0,T]}$ be a continuous Gaussian process with i.i.d. components. Assume that every component of $X$ satisfies Condition $\ref{con1}$ for some $\rho\in[1,2)$, Condition $\ref{coninf}$ with index $\alpha<2/\rho$ and Condition $\ref{concov}$. Consider the RDE \begin{equation*}
d\mathbf{Y}_t=V(Y_t)~d\mathbf{X}_t+V_0(Y_t)~dt,~~Y_0=y_0\in \mathbb{R}^N,
\end{equation*}where $\mathbf{X}$ is viewed as geometric rough path with roughness $p>2\rho$. Suppose that the vector fields $\{V_i\}_{i=1}^d$ satisfy Hypothesis $\ref{h1}$ and $\ref{1.2}$. Then for any $m\geqslant 1$ and $0<t_1<\cdots<t_m\leqslant T$, the joint distribution of $(Y_{t_1},\cdots,Y_{t_m})$ admits a smooth joint density with respect to the Lebesgue measure. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor corollary:exitPx of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] For every  non-negative measurable functions $F,G$ on $\mathbb{D}(\mathbb{R}_+, \mathcal{M}_f(\mathbb{R}_+)\times \mathcal{W}_{\overline{E}}) \times \mathbb{R}$ and $\mathbb{D}(\mathbb{R}_+, \mathcal{M}_f(\mathbb{R}_+)\times \mathcal{W}_{\overline{E}})$ we have 
\begin{equation}
    \mathbb{E}_{0,x,0}\Big[   \sum_{u \in \mathcal{D}} F\big( \,  \emph{\texttt{T}}_u (\rho,\overline{W}), \mathfrak{g}(u) \big) G(\rho^u , \overline{W}^u) \Big]  = 
    \mathbb{E}_{0,x,0}\Big[ \int_0^\infty \mathrm{d} A_s  ~F(\rho,\overline{W}, s ) \mathbf{N}_{x, \widehat{\Lambda}_s}\big(G(\rho,\overline{W})\big)\Big].
\end{equation}

[Lemma 25 of arXiv:2606.22611, 'Upper and Lower Bounds on Expected Soft Maxima\\of Gaussian Processes'] For any $\mu \in \eP(T)$,
\begin{align*}
 \eF_\beta(X ; \mu) = \sup_{\nu \in \eP(T)} 
  \set[\Bigg]{\bm{\phi}_\beta(\nu) - \frac{1}{\beta}D(\nu \| \mu)},
\end{align*}
where, for any $\mu\in \eP(T)$, 
\begin{align*}
  \bm{\phi}_\beta(\mu)
  \deq \lim_{\epsilon\downarrow 0} \bm{\phi}_{\beta,\epsilon}(\mu)
  \deq \lim_{\epsilon\downarrow 0}\lim_{N \to \infty} 
  \frac{1}{N}\eF_\beta(\bm{X}^N ; \su_{\cC_{N,\mu,\epsilon}}),
\end{align*}
with $\su_{\cC_{N,\mu,\epsilon}}$ denoting the uniform probability measure on $\cC_{N,\mu,\epsilon}$. In particular, for any $\mu_\beta^*$ that achieves the supremum
$\sup_{\mu\in \eP(T)}\eF(X;\mu)$,
\begin{align*}
  \sup_{\mu\in \eP(T)}\eF_{\beta}(X;\mu)=\eF_\beta(X ; \mu_\beta^*) = \bm{\phi}_\beta(\mu_\beta^*)=\sup_{\mu\in \eP(T)}\bm{\phi}_{\beta}(\mu).
\end{align*}

