body:
[Prop stoc_monotonicity of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] Let $\Lambda \subset \mathbb Z^d$ be finite, and $\beta\geq0$. Let also $J_1,J_2\in (\mathbb R^+)^{E(\Lambda)}$ be such that $J_1\leq J_2$, and $\mathsf{h}_1,\mathsf{h}_2\in \mathbb R^\Lambda$ be such that $\mathsf{h}_1\leq \mathsf{h}_2$. For any increasing and bounded function $F:\mathbb{R}^{\Lambda}\to\mathbb{R}$ we have 
\begin{equation}
\langle F(\tau) \rangle_{\Lambda,\beta,J_1,\mathsf{h}_1}\leq \langle F(\tau) \rangle_{\Lambda,\beta,J_1,\mathsf{h}_2}.  
\end{equation}
Moreover, if $|\mathsf{h}_1| \leq \mathsf{h}_2$, for any increasing and bounded function $F: (\mathbb{R}^+)^{\Lambda}\to\mathbb{R}$ we have 
\begin{equation}
\langle F(|\tau|) \rangle_{\Lambda,\beta,J_1,\mathsf{h}_1}\leq \langle F(|\tau|) \rangle_{\Lambda,\beta,J_2,\mathsf{h}_2}.  
\end{equation}

[Cor corproofmin of arXiv:2411.18359, 'Large systems of symmetrized trapped Brownian Bridges and Schr\"odinger processes'] There exists a measure $q^*\in {\mathcal M }_1^{(s)}(\mathbb{R} ^d\times\mathbb{R} ^d)$ such that 
    \begin{equation}
        \begin{aligned}
            &H(q^*|\overline{q^*}\otimes {\mathfrak m}) -\int_{\mathbb{R}^ d} \int_{\mathbb{R} ^d}\log \mathbb{E}_{x,y}[e^{-{\tilde W }}]q^*({\rm d} x,{\rm d} y)-\langle \log g,q^*\rangle \big \}\\
            &=\inf_{q\in {\mathcal M }^{(s)}_1(\mathbb{R} ^ d\times \mathbb{R} ^d)}\left\{H(q|\overline{q}\otimes {\mathfrak m}) -\int_{\mathbb{R}^ d} \int_{\mathbb{R} ^d}\log \mathbb{E}_{x,y}[e^{-{\tilde W }}]q({\rm d} x,{\rm d} y)-\langle \log g,q\rangle \right \}.
        \end{aligned}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

