[Theorem 5 of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] The Laplace transform $\phi^{z_0}(x)$ extends to a holomorphic function on $\C \backslash \big( (-\infty,\m] \cup [\M, +\infty) \big)$ and can be expressed as follows:
\begin{equation}
\phi^{z_0}(x) = -\frac{e^{xa_0 + Y^-(x)b_0\fc_{b_0> 0} +  Z^+(x)b_0\fc_{b_0<0}}}{\gamma(x,Y^-(x), Z^+(x))}.
\end{equation}
The points $\M$ and $\m$ are the branching points of $\phi^{z_0}$.
Furthermore, 
\begin{equation}
\phi^{z_0}_+(x,y) = \frac{-\gamma(x,y,Z^+(x))\phi^{z_0}(x) - e^{xa_0 + yb_0 \fc_{b_0 > 0} + z b_0 \fc_{b_0 < 0}}}{\gamma_+(x,y)}.
\end{equation}
Similarly, a symmetric expression holds for $\phi^{z_0}_-$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 4 of arXiv:2608.09419, 'Left-tail expansions for Schr\"oder branching processes with explicit convergence rates'] \lb{L1}
	Let $\mP_E$ be a set of polynomial probability generating functions with the expectation $P'(1)=E$. Denote $N=\lfloor E\rfloor$ the number which rounds $E$
	down to the nearest integer less than or equal to $E$. Then, the unique minimizer of the second derivative at $z=1$ is
	\[\lb{100}
	 {\rm argmin}_{P\in\mP_E}P''(1)=(N+1-E)z^N+(E-N)z^{N+1}.
	\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 26 of arXiv:2608.02103, '$p$-Adic Diffusion and Random Walks on $[0,1]$'] The entries of the average-transition-rate matrix $W_n^a$ attached to $(A_n,w)$ satisfy 
\begin{equation}

    w(x,y)=\lim_{n\rightarrow \infty} w_{I_n(x),J_n(y)}^{(n),a}
\end{equation}
\begin{comment}
\begin{equation}

    w(y|x)=\lim_{n\rightarrow \infty} w_{J_n(y),I_n(x)}^{(n),a}
\end{equation}
\end{comment}
almost everywhere.

[Definition def: approx MILT and SILT 2D of arXiv:2607.17393, 'Optimal Covariance Estimates for Schr\"odinger Semigroups with White Noise in $d=1,2$'] For $d\in\{1,2\}$, $\epsilon>0$, and $A\subset[0,t]^2$ a bounded Borel subset, the approximate self-intersection local time of a Brownian Bridge, $B_t^{x,x}$, is defined as 
\begin{align}

    \beta_A^\epsilon(B^{x,x}_t) =  \int_Ap_\epsilon(B_t^{x,x}(u)-B_t^{x,x}(v))dudv
\end{align}
(note that $\beta_A^\epsilon(B^{x,x}_t)= \beta_A^\epsilon(B^{0,0}_t)$).
For $A\subset[0,t]\times[0,s]$, the approximate mutual intersection local time of the Brownian Bridges $B_t^{x,x}$ and $\overline{B}_s^{y,y}$ is defined as
\begin{align}
    \alpha^\epsilon_A(B_t^{x,x},\overline{B}_s^{y,y}) = \int_Ap_\epsilon(B_t^{x,x}(u)-\overline{B}_s^{y,y}(v))dudv
\end{align}

[Proposition p:asymptotic variance test function 0 of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Suppose that $\Phi$ is a locally square-integrable invariant random complex measure. Further, suppose that $f\in L^1$ is Fourier smooth with exponent $-d+\vartheta$ with $\lambda_d(f)=0$, where $\vartheta>0$. Then, as $r\to \infty$,
\begin{equation}
    \frac{\BV[\Phi(f_r)]}{r^d} = o(r^d)
\end{equation}
\begin{proof}
Choose $\Psi:= \Phi - \lim_{r\to\infty}\frac{\Phi(B_r)}{\lambda_d(B_r)} \cdot \lambda_d$. Note that the limit is taken with respect to the $L^2$-norm and is well defined by the $L^2$-ergodic theorem; see, e.g.,~[Kallenberg_2021]. We can see that $\Phi(f_r)=\Psi(f_r)$, as $\lambda_d(f_r) = r^d\lambda_d(f)=0$, $r>0$. Further, by construction, $\Psi$ is pseudo-ergodic and therefore beyond $(-d)$-uniform by Proposition~(p:pseudo ergodic of the paper). Now the assertion follows from Theorem~(t:asymptotic variance test function of the paper).
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 8 of arXiv:2608.24675, 'Towards Liouville Quantum Gravity on fractals'] \begin{enumerate}[wide=0em,label={\rm (\roman*)},itemsep=.5em]
\item
 The sequence $\{h_{\ell}\}_{\ell\geq 1}$ converges both in $L^2(\Omega)$ and $\mathbb{P}$-a.s. to the FGFF $h$ on $K$. In particular,
 \begin{equation*}
    h\stackrel{d}{=}\sum_{k=1}^\infty\xi_{k}\lambda_{k}^{-\frac{d_S}{4}}\varphi_k
 \end{equation*}
and, $\mathbb{P}$-a.s., it holds that $h\in {H}^{-\varepsilon}(K)$ for any $\varepsilon>0$ and $h\notin L^2(K)$.
\item
    For every $u\in{H}^{-d_S/2}(K)$, the sequence $\{\langle h_{\ell},u\rangle\}_{\ell\geq 1}$ is a centered, $L^2$-bounded martingale with respect to the filtration $\{\mathcal F_\ell\}_{\ell\geq1}$, where
    \begin{equation*}
        \mathcal{F}_{\ell}:=\sigma(\{\xi_1,\ldots,\xi_{N_\ell}\}).
    \end{equation*}
    Moreover, the sequence converges in $L^2(\Omega)$ and $\mathbb{P}$-a.s. to a centered Gaussian random variable, denoted by $h\cdot u$. In particular, $\P$-a.s.
    \begin{equation*}
    h\cdot u=\sum_{k=1}^{\infty}\xi_{k}\lambda_{k}^{-\frac{d_S}{4}}\langle \varphi_k,u\rangle
    \end{equation*}
    and
    \begin{equation*}
        \E[(h\cdot u)^2]=\|u\|_{H^{-d_S/2}}^2.
    \end{equation*}

\end{enumerate}

