[Definition def:reverse-charging of arXiv:2608.12415, 'Sharp Phase Transition for Ellipsoid Fitting'] Fix a block in a given block-walk. We call a step \(u\to v\) \emph{reverse-charging} if the following conditions hold:
    \begin{enumerate}
        \item the underlying edge is making its global last appearance in the walk;
        \item the global first appearance of the same underlying edge also occurs within the current block;
        \item that first appearance traverses the edge in the opposite direction, namely from \(v\) to \(u\).
    \end{enumerate}

[Thm Conformal Invariance under ${\rm Aut}(\mathbb{D}, 0)$ of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] For a rotation map $\rho_{\theta}$, the drift term \( b_i(\boldsymbol{\theta}) \) is invariant under \(\rho_\theta\), i.e.,
\[
b_i = \widetilde{b}_i \circ \rho_{\theta}.
\]

\begin{itemize}
    \item[(i)] The function \( h(\theta) \) in the null vector equation ((null vector equation angular coordinate constant h of the paper)) is rotation-invariant, and there exists a real constant \( h \) such that
   \begin{equation}
    h(\theta) = h.
   \end{equation}

    \item[(ii)] There exists a real rotation constant \( \omega \) such that, for all \( \theta \in \mathbb{R} \),
    \begin{equation}
    \psi(\theta_1 + \theta, \ldots, \theta_n + \theta) = e^{-\omega \theta} \psi(\theta_1, \ldots, \theta_n).
    \end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 19 of arXiv:2608.30990, 'Convergence of symmetries: nilpotency, dimension, and perfectness'] \cite{nsz, carolino}. Let $G_i,$ $G$, $\phi_i$, $B$, $B_i$ be as in Theorem \ref{thm:gleason}. Assume the sequence $G_i$ has the NSS property and  consists of Lie groups, and let $\mathfrak{g}_i$ be the Lie algebra of $G_i$. Then for $i$ large enough there is a genuine norm $\Vert \cdot \Vert _{i} : \mathfrak{g}_i \to \mathbb{R}$ with
    \begin{equation}
     \vert \vv \vert _{B_i} \leq \Vert \vv \Vert _i \leq 2C_0 \vert \vv \vert _{B_i}       
    \end{equation}
    for all $\vv \in \mathfrak{g}_i$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 7 (Stefani \cite{stefani2018}) of arXiv:2608.26501, 'Explicit Bounds on the Entropy of Piecewise H\"{o}lder Graphon Models'] For $d\geq 2$, let $A,B\subset\rr^d$ be convex bodies (compact, convex sets with non-empty interior). If $A\subset B$, then
\begin{equation}S(\partial A)\leq S(\partial B)\end{equation}
where $S(\cdot)$ is the $(d-1)$-dimensional Hausdorff measure and $\partial X$ is the boundary of $X$. In other words, the surface area of convex bodies is monotone with respect to inclusion. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:Gordonpos1 of arXiv:2607.26551, 'An RDT based confirmation of Lehner's formula for Kronecker-Gaussian matrices'] ([Gordon85,Slep62])
 Let $X_{i}$ and $Y_{i}$, $1\leq i\leq n$, be two centered Gaussian processes which satisfy the following inequalities for all choices of indices
\begin{enumerate}
\item ${\mathbb E}(X_{i}^2)={\mathbb E}(Y_{i}^2)$
\item ${\mathbb E}(X_{i}X_{l})\leq {\mathbb E}(Y_{i}Y_{l}), i\neq l$.
\end{enumerate}
 Then
\begin{equation*}
{\mathbb E}(\min_{i} X_{i})\leq {\mathbb E}(\min_i Y_{i}) \quad  \Longleftrightarrow \quad {\mathbb E}(\max_{i} X_{i})\geq {\mathbb E}(\max_i Y_{i}).
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 15 of arXiv:2608.31070, 'Sub-Laplacians on Compact Lie Groups: Heat Kernels, Distance, and Zeta Determinants'] For every $\Omega\in\Lambda^2\pLie$,
		\begin{equation}
			-\lim_{t\downarrow0}4t\log q_t^{\mathrm{free}}(0,\Omega)
			=\Psi_{\pLie}(\Omega).
		\end{equation}
		Equivalently,
		\begin{equation}
			d_{\mathrm{free}}(e,(0,\Omega))^2
			=\Psi_{\pLie}(\Omega).
		\end{equation}

[Corollary 11 of arXiv:2607.28215, 'Almost stochastic dominance via optimal transport'] If $c,g$ and $d$ are chosen according to \eqref{eq:Rd}, then Theorems \ref{thm:main1}-\ref{thm:main3} hold and
\begin{align*}
\mathcal{L}_{c,g}(E) = \mathcal{L}_d(E).
\end{align*}

[Proposition prop:Wishart.deBruijn of arXiv:2606.04859, 'Stein's method for the Wishart distribution'] Assume that there exist constants $m_g,M_g\in (0, \infty)$ such that $m_g \leq g(X)\leq M_g$ for all $X\in \mathcal{S}_{++}^d$. Then, for every $t > 0$, we have $g_t = \mathcal{P}_t^{\mathcal{W}} g$ and
\begin{equation}
\frac{\mathrm{d}}{\mathrm{d} t}\mathrm{Ent}(\mu_t \, \| \, \xi) = - J_{\mathcal{W}, \Sigma}(\mu_t \mid \xi).
\end{equation}
In particular, the map $t\mapsto \mathrm{Ent}(\mu_t \, \| \, \xi)$ is nonincreasing. Equivalently, after the change of variable $\tau = e^{-2t}$ and the definition $\mu_{\tau} \vcentcolon= \mu \mathcal{P}^{\mathcal{W}}_{-(1/2)\log(\tau)}$, we have
\begin{equation}
\frac{\mathrm{d}}{\mathrm{d} \tau}\mathrm{Ent}(\mu_{\tau} \, \| \, \xi) = \frac{1}{2\tau} J_{\mathcal{W}, \Sigma}(\mu_{\tau} \mid \xi), \qquad \tau\in (0, 1).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 (Choice of cocharacter) of arXiv:2609.03954, 'Galois representations ramified at one prime via relative deformation theory'] Let $\cE\subset\Z$ be finite. There exists a cocharacter
$\lambda\in X_*(\TT)$ such that:
\begin{enumerate}[label=\textup{(\arabic*)}]
\item $\langle\alpha,\lambda\rangle$ is odd for every
      $\alpha\in\Delta$;
\item $\langle\beta,\lambda\rangle\notin\cE$ for every
      $\beta\in\Phi$;
\item the integers $\langle\alpha,\lambda\rangle$, for
      $\alpha\in\mathcal B$, are pairwise distinct;
\item if $\dim Z(\GG)=1$, the image
      $\lambda^{\mathrm{ab}}\in X_*(\GG/\Gder)$ is nonzero.
\end{enumerate}

[Proposition 35 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] For all $(Y,Y') \in \scrd_X^{2 \alpha}([0,T],L(V,W))$ we have
\begin{align*}
(Z,Z') := \bigg( \int_0^{\cdot} Y_s \, d \bfx_s, Y \bigg) \in \scrd_X^{2 \alpha}([0,T],W),
\end{align*}
and the estimate
\begin{align*}
\| Z,Z' \|_{X,2 \alpha} &\leq \| Y \|_{\alpha} + \| Y' \|_{\infty} \| \bbx \|_{2 \alpha}
\\ &\quad + C T^{\alpha} \big( \| X \|_{\alpha} \| R^Y \|_{2 \alpha} + \| \bbx \|_{2 \alpha} \| Y' \|_{\alpha} \big)
\end{align*}
with a constant $C > 0$ depending on $\alpha$.

