[Proposition prop:averse of arXiv:2603.17861, 'Gaussian concentration, integral probability metrics, and coupling functionals\\ for infin'] If $\mu\in\mathscr{M}_\tau^1(\Omega)$ satisfies either $\gcb{C,{\mathcal L}\!\!\mathrm{{\scriptscriptstyle oc}}(\Omega_{}),\ell^2}$ or
$\gcb{C|\ensuremath{\Lambda}_n|,{\mathcal L}\!\!\mathrm{{\scriptscriptstyle oc}}(\Omega_{}),\ell^\infty}$ for all $n\geq 1$, then
\begin{equation}
\bar{d}(\mu,\nu)\leq \sqrt{2C \ushort{\scaleto{s}{6pt}}(\nu|\mu)}\,,
\qquad \forall \;\nu\in\mathscr{M}_\tau^1(\Omega).
\end{equation}

[Lem lem12 of arXiv:2609.02795, 'Global smooth behavior in Kuznetsov and Westervelt type\\ viscous wave equations:\\ A unif'] Let $H^{(1)}$ and $H^{(2)}$ be as in Lemma (lem11 of the paper). Then
  \begin{eqnarray}\label{12.1}
	& & \hspace*{-20mm}
	\frac{d}{dt} \bigg\{ \frac{1}{2} \int_\Omega |\nabla u|^2
	+ \int_\Omega H^{(1)}(u,u_t) \bigg\} + a \int_\Omega |\nabla u|^2 \nonumber\\
	&=& \int_\Omega f(u,u_t,\nabla u,\nabla u_t) u
	+ \int_\Omega H^{(1)}_\xi(u,u_t) u_t
  \end{eqnarray}
  and
  \begin{eqnarray}\label{12.2}
	& & \hspace*{-20mm}
	\frac{d}{dt} \bigg\{ \int_\Omega H^{(2)}(u,u_t) + \frac{a}{2} \int_\Omega |\nabla u|^2 \bigg\}
	+ \int_\Omega |\nabla u_t|^2 \nonumber\\
	&=& \int_\Omega H^{(2)}_\xi(u,u_t) u_t
	+ \int_\Omega f(u,u_t,\nabla u,\nabla u_t) u_t
  \end{eqnarray}
  for all $t\in (0,T_{max})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 27 of arXiv:2609.03803, 'List-distance consistent vertices in trees are confined to a path'] Let $c$ be a labeling of a connected graph $G$ and let $u\in V(G)$. Then $u$ is
consistent under $c$ if and only if
\begin{equation}
  \max\bigl\{\,c(u,x) : x\in \Ball{u}{k}\,\bigr\}
  \;\le\;
  \min\bigl\{\,c(u,y) : y\in V(G)\setminus \Ball{u}{k}\,\bigr\}

\end{equation}
for every integer $k\ge0$.

[Definition eq: first variation closed of arXiv:2609.02073, 'Existence of closed non-planar $p$-elasticae'] For $p\in (1,\infty)$, the immersed curve $\gamma \in W^{2,p}(\R/\Z;\R^n)$ is called a \textit{closed $p$-elastica} if there exists $\lambda \in \R$ such that 
  \begin{equation}

    \frac{d}{d\varepsilon} \left( \mathcal{B}_p[\gamma+\varepsilon \eta] + \lambda \mathcal{L}[\gamma + \varepsilon \eta] \right) \bigg|_{\varepsilon=0} = 0 \qquad \forall \eta \in C^\infty(\R/\Z;\R^n).
  \end{equation}

[Defi A variant of the Watts--Strogatz random graph of arXiv:2607.28817, 'Limiting spectral distribution for the adjacency matrix of the Watts--Strogatz random grap'] Let $n\ge1$ be an integer, $K$ a positive even integer with $K<n$, and $p \in [0,1]$. The Watts--Strogatz random graph of size $n$ with parameters $(K,p)$, denoted $\widetilde{WS}_n(K,p)$, is constructed as follows:

\begin{enumerate}
    \item \textbf{Initial lattice.}  
    Let $V_n = \{1,2,\dots,n\}$ denote the set of vertices of $WS_n(K,p)$. Arrange the vertices on a clockwise cycle. Each vertex $i \in V_n$ is connected to its $K/2$ nearest neighbors on each side, forming a regular ring lattice of degree $K$.

    \item \textbf{Rewiring step.}  
    For $i = 1,2,\dots,n$ in increasing order, and for each edge $\{i,j\}$ such that $j$ is one of the $K/2$ rightmost neighbors of $i$ (taken in increasing order), independently with probability $p$, rewire the edge $\{i,j\}$ as follows: remove the edge $\{i,j\}$ and add the edge $\{i,k\}$, where $k$ is chosen uniformly at random from $V_n$.
\end{enumerate}

