body:
[Lemma 33 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Let $k, b, \vec{y}, g$ be as in Definition \ref{Def.PinnedBM}. Suppose that $d_n$ is a sequence of positive reals such that $d_n \rightarrow \infty$, and set $T_n = \lceil b d_n \rceil$. Let $g_n: [0, T_n/d_n] \rightarrow [-\infty, \infty)$ be continuous functions such that $g_n \rightarrow g$ uniformly on $[0,b]$. In the case when $g = -\infty$, the last statement means that $g_n = -\infty$ for all large $n$. We also suppose that 
\begin{equation}
\lim_{n \rightarrow \infty} |g_n(T_n/d_n) - g_n(b)| = 0 \mbox{ if } g \neq -\infty.
\end{equation}

Fix $q\in (0,1)$, $c \in [0,1)$, and put $p = \frac{q}{1-q}$, $\sigma = \sqrt{p(1+p)}$. Define $G_n: [0, T_n] \rightarrow [-\infty, \infty)$ through
$$G_n(s) = \sigma d_n^{1/2} \cdot g_n(s/d_n) + p s,$$
and suppose that $Y^n \in \mathfrak{W}_{2k}$ is a sequence such that 
\begin{equation}
 \lim_{n \rightarrow \infty} \sigma^{-1} d_n^{-1/2} \cdot (Y_i^n - p T_n)   = y_i \mbox{ for } i \in \llbracket 1, 2k \rrbracket.
\end{equation}

Then, we have the following statements.
\begin{enumerate}
\item[(a)] There exists $N_0 \in \mathbb{N}$ such that for $n \geq N_0$ the laws $\mathbb{P}_{\ice;q ,c}^{T_n, Y^n,G_n}$ are well-defined, i.e. for some $(\mathfrak{B}^1, \dots, \mathfrak{B}^k) \in  \Omega_{\ice}(T_n, Y^n, G_n)$, we have $\prod_{i = 1}^k W(\mathfrak{B}^i; q,c) > 0$.
\item[(b)] If $\mathfrak{Q}^n = \{Q_i^n\}_{i = 1}^{2k}$ has law $\mathbb{P}_{\ice;q ,c}^{T_n, Y^n,G_n}$, then the sequence of $\llbracket 1,2k \rrbracket$-indexed line ensembles $\mathcal{Q}^n$ on $[0,b]$ defined by
\begin{equation}
\mathcal{Q}_i^n(t) = \sigma^{-1} d_n^{-1/2} \cdot \left( Q^n_i(t d_n) - ptd_n\right) \mbox{ for } n \geq N_0, \hspace{2mm} t \in [0,b] \mbox{ and } i \in \llbracket 1, 2k \rrbracket,
\end{equation}
converges weakly to $\mathbb{P}_{\mathrm{pin}}^{b,\vec{y},g}$ from Definition \ref{Def.PinnedBM} as $n \rightarrow \infty$.
\end{enumerate}

[Cor PrLT-ambidextrous-fgt of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $A\in T$ arbitrary, let ${\mathcal{E}}$ be a presentable $T$-$\infty$-category, and let $F\colon{\mathcal{C}}\to{\mathcal{D}}$ be a left adjoint functor of presentable $T_{/A}$-$\infty$-categories. Then $\textup{fgt}_*F$ is again a left adjoint, and there exists a diagram of spaces
    \begin{equation}
        \begin{tikzcd}
            {\textup{Hom}}_{\textup{Pr}^{\textup{L}}_{T}}(\textup{fgt}_*{\mathcal{D}},{\mathcal{E}})\arrow[d,"\sim"']\arrow[r, "{-}\circ\textup{fgt}_*F"] &[.25em] {\textup{Hom}}_{\textup{Pr}^{\textup{L}}_{T}}(\textup{fgt}_*{\mathcal{C}},{\mathcal{E}})\arrow[d,"\sim"]\\
            {\textup{Hom}}_{\textup{Pr}^{\textup{L}}_{T_{/A}}}({\mathcal{D}},\textup{fgt}^*{\mathcal{E}})\arrow[r,"{-}\circ F"'] & {\textup{Hom}}_{\textup{Pr}^{\textup{L}}_{T_{/A}}}({\mathcal{C}},\textup{fgt}^*{\mathcal{E}})
        \end{tikzcd}
    \end{equation}
    commuting up to (unspecified) homotopy. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 7 of arXiv:2605.17155, '2605.17155'] Let \(B\) be a Banach space and let \(f:\Nzero\to B\) be
asymptotically almost periodic.  For every \(\eta>0\) there is
\(L=L(f,\eta)\) such that, for every \(h\geq0\), some
\(r\in\{0,\dots,L\}\) satisfies
\begin{equation}
    \sup_{m\geq0}
   \norm{(f(m+h)-f(h))-(f(m+r)-f(r))}<\eta .
\end{equation}

[Cor 18 of arXiv:2607.03924, 'Tree Coordinates and Range Martingales for Positive Operator-Valued Measures'] Convex decompositions 
\[
E=\frac{1}{2}\left(F+G\right),
\]
where $F$ and $G$ are POVMs on $\Omega_{m}$ with values in $B\left(H\right)$,
are in one-to-one correspondence with positive range martingales $\left\{ X_{w}\right\} $
satisfying 
\begin{equation}
0\leq X_{w}\leq2I_{H_{w}}
\end{equation}
for every finite word $w$, and 
\begin{equation}
X_{\varnothing}=I.
\end{equation}
The correspondence is given on cylinders by 
\begin{equation}
F\left(\left[w\right]\right)=E^{1/2}_{w}X_{w}E^{1/2}_{w}
\end{equation}
and 
\begin{equation}
G\left(\left[w\right]\right)=E^{1/2}_{w}\left(2I_{H_{w}}-X_{w}\right)E^{1/2}_{w}.
\end{equation}

[Cor 67 of arXiv:2507.08909, 'Annealed almost periodic entropy'] Let $\tau$ be a tracial state of $\A$, let $\l$ be its GNS representation, and let $\phi \in \B(\A,\rmM_k)_+$.
\begin{enumerate}
\item[a.] Assume that $\phi$ is approximately associated to $\l^{\oplus \infty}$. Then, for every neighbourhood $O$ of $\phi$, there are a positive integer $d_0$ and a neighbourhood $V$ of $\tau$ such that the following holds:
\begin{quote}
If $\pi$ is a $d$-dimensional representation satisfying
\[d \ge d_0 \qquad \hbox{and} \qquad \tr_d\circ \pi \in V\]
then $\X(\pi,O) \ne \emptyset$.
\end{quote}
\item[b.] For every neighbourhood $O$ of $\phi$ there are a positive integer $d_0$ and neighbourhoods $U$ of $\phi_{\rm{sing}}$ and $V$ of $\tau$ such that the following holds:
\begin{quote}
If $\pi$ is a $d$-dimensional representation satisfying
\[d\ge d_0, \qquad \tr_d\circ \pi \in V, \qquad \hbox{and} \qquad \X(\pi,U) \ne \emptyset\]
then $\X(\pi,O) \ne \emptyset$.
\end{quote}
\end{enumerate}

