\[
|f^1-f^2|(\cdot,X^2,Y^2,Z^2,\mathcal{L}^2)\in L^{1,p}_{\mathbb{F}}(0,T).
\]
Then there exists a constant $C_p$ such that
\begin{equation*}
\begin{split}
&\mathbb{E}\sup_{0\le t\le T}|Y^1_t-Y^2_t|^p+\mathbb{E}\Big(\int^T_0|Z^1_r-Z^2_r|^2\,dr\Big)^{\frac{p}{2}}\le C_p\mathbb{E}\Big(|h^1_T-h^2_T|^p+\Big(\int^T_0|X^1_r-X^2_r|\,dr\Big)^p\\
&\quad+\Big(\int^T_0\mathcal{W}_{p}(\mathcal{L}^1_r,\mathcal{L}^2_r)\,dr\Big)^p+\Big(\int^T_0|f^1-f^2|(r,X^2_r,Y^2_r,Z^2_r,\mathcal{L}^2_r)\,dr\Big)^p\Big)
\end{split}
\end{equation*}

