[Thm 8 of arXiv:2606.02570, 'Stochastic completeness for landmark space'] Suppose that the radial scalar function $k\colon [0,\infty)\to\R$ is smooth on $(0,\infty)$ and that it possesses a positive continuous Fourier transform $\widehat{k}\colon\R^d\to\R$. For $M>0$, we set
    \begin{displaymath}
        \widehat{k}_M:=\inf_{\|\xi\|\leq 2M} \widehat{k}(\xi).
    \end{displaymath}
    Fix a landmark configuration $\lm\in \Land$. Then, for any
    \begin{displaymath}
        M\geq \frac{12}{q(\lm)}\left(\frac{\pi\left(\Gamma\left(1+\frac{d}{2}\right)\right)^2}{9}\right)^\frac{1}{1+d}
    \end{displaymath}
    or, simply,
    \begin{displaymath}
        M\geq\frac{7 d}{q(\lm)},
    \end{displaymath}
    the minimal eigenvalue $\lambda_{\min}\left(g^{-1}(\lm)\right)$ of the cometric at the landmark configuration $\lm$ satisfies
    \begin{displaymath}
        \lambda_{\min}\left(g^{-1}(\lm)\right)
        \geq \frac{\widehat{k}_M}{2\Gamma\left(1+\frac{d}{2}\right)}\left(\frac{M}{2^{3/2}}\right)^d.
    \end{displaymath} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:IS6V-seed-linear of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The seed functions $\Psi$ and $\Phi$ satisfy the linear
problem on $\mathcal{V}$ with edge weights
$(C_p, \Lambda_p)$.  For any divisor $p \mid \Pi_{x,y}$
with $1 \leq \deg p < \deg \Pi_{x,y}$:
\begin{equation}
\Psi(S_p u) = \Psi(Tu) C_p - \Psi(u) \Lambda_p,
\end{equation}
and
\begin{equation}
\Phi(Tu) = C_p \Phi(S_p u) - \Lambda_p \Phi(T S_p u).
\end{equation}

[Lem 5 of arXiv:2604.25964, 'Strong convergence rate of Euler-Maruyama approximations in temporal-spatial H\"older-norm'] For $\delta \in \widetilde{\mathbb{S}},$ $s\in [0,T],$ $t\in [s, T],$ $\widetilde{t} \in [t, T],$ $x, \widetilde{x}\in\mathbb{R}$, let $(X^{\delta,x}_{s,t})_{t\in[s,T]}:[s,T]  \times\Omega\to\mathbb{R} $ 
be an $(\mf_t)_{t\in[s,T]}$-adapted stochastic process with c\`adl\`ag  sample paths satisfying equation \eqref{y01}. Let $(a_r, b_r, g_r) = \theta (\psi_r)-\theta(\widetilde{\psi}_r)$ with $\theta = (\mu, \sigma, \gamma)$, $r\in [t, \widetilde{t}]$ and 
 \begin{align*}
     (\psi_r, \widetilde{\psi}_r) = \Big\{(X_r, Y_r), (X_{s,\max\{s,\delta(r)\}}^{\delta,x}, X_{s,\max\{s,\delta(r)\}}^{\delta,\widetilde{x}}), (X^{\iota ,x}_{s,r}, X_{s,\max\{s,\delta(r)\}}^{\delta,x})\Big\}.
     \end{align*}
     Then, for all $p\ge 2,$ there exists a positive constant $C_p=C_p(T, m_2, m_p)$ such that 
 \begin{align*}

 &\left[\mathbb{E} \left[\left| \int_t^{\widetilde{t}} a_r dr \right|^p \right]\right]^{1/p} + \left[\mathbb{E} \left[\left| \int_t^{\widetilde{t}} b_r dW_r \right|^p \right]\right]^{1/p} + \left[\mathbb{E}\left[ \left| \int_t^{\widetilde{t}} \int _{\bR_0} g_{r-} z \widetilde{N}(dr, dz) \right|^p \right]\right]^{1/p} \notag  \\
  & \leq C_p |\widetilde{t} -t|^{1/p} \sup_{r\in [t, \widetilde{t}]} \max \left\{ \left [\mathbb{E} \left[\left| a_r \right|^p\right]\right]^{1/p}, \left [\mathbb{E} \left[\left| b_r \right|^p\right]\right]^{1/p}, \left [\mathbb{E} \left[\left| g_r \right|^p\right]\right]^{1/p} \right\}.
  \end{align*}

