[Definition def:zero of arXiv:2605.03896, 'Dimer models on astroidal zig-zag graphs'] We say that a point~$(x,y)\in \mathcal D_c^\circ$ lies in a \emph{phase region} if it belongs to a rough, smooth, frozen, or quasi-frozen region. For such a point~$(x,y)$, let
\begin{equation} 
\zeta_*=\zeta_*(x,y) := \begin{cases} \Omega(x,y), &\text{if $(x,y) \in \mathcal L$},\\
\text{any point of $A_{(x,y)}$}, &\text{otherwise}.
\end{cases}
\end{equation}

[Theorem 7 of arXiv:2603.25452, 'New approach to optimal control of delayed stochastic Volterra integral equations'] Let $\hat{u}$ be the optimal solution to the consumption problem \eqref{OP}. Then, we derive
\begin{eqnarray*}
\hat{u}(t)&=& \left(\mathbb{E}\left[ \mathbb{E}^{\mathbb{Q}}\left(\Psi(t)\theta\middle|\mathcal{F}_t\right)|\mathcal{G}_t\right]\right)^{-1}\\
&=& \left(\mathbb{E}\left[\frac{\mathbb{E}\left(\Psi(t)M(T)\theta\middle|\mathcal{F}_t\right)}{M(t)}\middle|\mathcal{G}_t\right]\right)^{-1},
\end{eqnarray*}
where $\mathbb{Q}$ is a probability measure defined by
\begin{eqnarray}
	 d\mathbb{Q}=M(T)d\P
\end{eqnarray}
 with
\begin{eqnarray*}
	M(t)=\exp\left(\int_0^t\sigma_0(s)dB(s)-\frac{1}{2}\int_0^t\sigma_0^2(s)ds\right).
\end{eqnarray*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition W SPDE-1 of arXiv:2605.13479, '\LARGE Dean-Kawasaki Equation with Biot-Savart and Keller-Segel Interactions: Existence an'] Let $\mathcal{V}[\cdot]$ and $\rho_0$ be defined as in Definition (RKS smooth spde of the paper), for any $\varepsilon,\eta\in(0,1)$, a weak solution  $\rho$ of (equation SPDE-1 of the paper) with initial data $\rho(\cdot, 0)=\rho_0$ is a nonnegative, $\mathcal{F}_{t}$-predictable process that satisfies the following properties.
\begin{enumerate}
		\item Conservation of mass: almost surely for every $t\in[0,T]$,
		\begin{equation}
		\|\rho(\cdot,t)\|_{L^{1}_{\mathbb{T}^{2}}}=\left\|\rho_0\right\|_{L^{1}_{\mathbb{T}^{2}}}.
		\end{equation}




		\item Pathwise entropy dissipation estimates: almost surely, 
		\begin{align}
 \int_0^t\int_{\mathbb{T}^2}
|\nabla\sqrt{\rho}|^2\mathrm{d}x\mathrm{d}s
\lesssim&\int_{\mathbb{T}^2}\Psi(\rho_0)\mathrm{d}x+\sqrt{\varepsilon}\int_0^t\int_{\mathbb{T}^2}
\frac{s_{\eta}(\rho)}{\rho}\nabla\rho\cdot
\xi_{K}
+\varepsilon N_KT+1,
\end{align}
for all $t \in [0,T]$.  

\item The equation: 
for every $\psi \in C^{\infty}_{\mathbb{T}^2}$, almost surely for every $t \in[0, T]$,
\begin{align}
\int_{\mathbb{T}^2} \rho(x, t) \psi(x) & =\int_{\mathbb{T}^2} \rho_0 \psi-\int_{0}^{t} \int_{\mathbb{T}^2} \nabla \rho \cdot \nabla \varphi+\int_{0}^{t} \int_{\mathbb{T}^2}(\rho \mathcal{V}[\rho]) \cdot \nabla \psi \nonumber\\
&+\sqrt{\varepsilon}\int_{0}^{t} \int_{\mathbb{T}^2} s_{\eta}(\rho) \nabla \psi \cdot \xi_{K}-\frac{\varepsilon F_{1,K}}{2} \int_{0}^{t} \int_{\mathbb{T}^2} \left[s_{\eta}^{\prime}(\rho)\right]^{2} \nabla \rho \cdot \nabla \psi. 
\end{align}
\end{enumerate}

