[Theorem 5 of arXiv:2608.26974, 'Why not to use the Gaussian kernel'] Consider a strictly positive-definite stationary kernel $k(x, y) = \Phi(x - y)$. If $\sigma = 0$ and $X_{n+1} = \{x_1, \ldots, x_{n+1}\} \subset \R^d$, then
  \begin{equation*}
    \mathrm{cond}( \b{K}_{n+1} ) \geq \frac{\Phi(0)}{\V(x_{n+1} \mid \mathcal{D}_{n})} .
  \end{equation*}

[Theorem the: Jakubowski's criteria of arXiv:2608.23756, 'Measure-valued fluid limits for partial service queues\\with correlated patience and servi'] A sequence $\setc{\boldsymbol{\nu}^N}{N \geq 1}$ of processes in $D_{\mathcal{M}_F^+(\mathbbm{R}_+^d)}[0, \infty)$ is tight if and only if the following two conditions are satisfied.
	\begin{enumerate}
		\item[\normalfont{J1.}] For each $T > 0$ and $\varepsilon > 0$, there exists a compact set $C \subset \mathcal{M}_F^+(\mathbbm{R}_+^d)$ such that
		\begin{equation*}
			\liminf_{N \to \infty} P\probarg*{\boldsymbol{\nu}_t^N \in C\ \text{for all}\ t \in [0, T]} \geq 1 - \varepsilon.
		\end{equation*}
		This is called the compact containment condition.

		\item[\normalfont{J2.}] There exists a family $\mathcal{H}$ of continuous functions from $\mathcal{M}_F^+(\mathbbm{R}_+^d)$ into $\mathbbm{R}$ that separates points in $\mathcal{M}_F^+(\mathbbm{R}_+^d)$, is closed under addition and satisfies that
		\begin{equation*}
			\asetc{t \mapsto h\left(\boldsymbol{\nu}_t^N\right)}{N \geq 1} \quad \text{is tight in}\ D_\mathbbm{R}[0, \infty) \quad \text{for all} \quad h \in \mathcal{H}.
		\end{equation*}
		If this property holds, then $\setc{\boldsymbol{\nu}^N}{N \geq 1}$ is called $\mathcal{H}$-weakly tight.
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor_bpbs of arXiv:2507.06522, 'Balanced multi-species spin glasses'] Fix integers $p,q\geqslant2$ and consider the two-species model from (equation wfe78 of the paper).
Assume the prelimiting volume parameters satisfy
\eeq{ 
N = n(p+q)+2, \quad \#\mathcal{I}_{1,N} = np+1, \quad \#\mathcal{I}_{2,N} = nq+1 \quad
\text{for some $n\in\mathbb{Z}_{\geqslant0}$.}
}
We then have
\eeq{ 
\lim_{n\to\infty}\GSE_{N,\mathsf{spherical}}(\vc\Delta,\vc\lambda_N) = \GSE_{N,\mathsf{spherical}}^\mathsf{single}(\beta).
} (Proof in the paper; no proof environment follows the statement in the TeX.)

