    \begin{equation*}
        \norm{\hat P_t f}_{L^2(\hat\mu)} \geq \norm{f}_{L^2(\hat\mu)} - \norm{\hat P_t f-f}_{L^2(\hat\mu)} \geq \norm{f}_{L^2(\hat\mu)} - t\norm{\hatL f}_{L^2(\hat\mu)}\,.
    \end{equation*}
    For any $g\in L_0^2(\mu)$ and $\lambda>0$ such that $\langle g,-\L g\rangle_{L^2(\mu)} = \lambda\norm{g}_{L^2(\mu)}^2$, we have $\norm{\hatL(g\circ\pi)} = \sqrt{2\lambda}\norm{g\circ\pi}_{L^2(\hat\mu)}$ by the ...","release_manifest_digest":"sha256:d9bdc0bdcd5bee61745527371a87241cd604a07c5f8f6361d3892e62daf44b98","revision_digest":"sha256:9d7e5bd9cd5b1422f59c13be89e3f00ae3b74323b2eb63f1b95c33a749ff3224","source_id":"arxiv:2511.23453","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

