[Proposition prop.conv.int.eta of arXiv:2607.07598, 'Universal Central Limit Theorem for non-exchangeable interacting diffusions'] Suppose Assumption (assum.main of the paper) holds with $k\ge \lambda_d+2$. Let $(\eta^n)_{n\in{\mathbb{N}}}$ be a subsequence, still denoted by $(\eta^n)_{n\in{\mathbb{N}}}$, such that $\eta^n \stackrel{d}{\to} \eta$ in $C([0,T];{\mathcal{H}}^{-k})$. Then:
		\begin{enumerate}[(i)]
			\item  $\eta\in L^2([0,T];{\mathcal{H}}_w^{-(k-1)})$ a.s.
			\item 
			For every deterministic  $g \in L^\infty([0,T]; C_b^{k}({\mathbb{R}}^d))$,
			\begin{align} 
				\int_0^T \langle \eta_t^n, g_t\rangle_{{\mathcal{H}}^{-k}_w,{\mathcal{H}}^{k}_w}\,\mathrm{d} t
				\stackrel{d}{\to}
				\int_0^T \langle \eta_t, g_t\rangle_{{\mathcal{H}}^{-k}_w,{\mathcal{H}}^{k}_w}\,\mathrm{d} t,
			\end{align}
			with the integral on the right-hand side being finite a.s.
		\end{enumerate}

