[Proposition prop:small_lambda_asym of arXiv:2509.15446, 'On the pair correlation function of the $\Sineb$ process'] For $\lambda$ near 0, we have 
       \begin{align}
        \rho_{\beta,n}^{(1)}(\lambda) =\frac{1}{2\pi} 
      \binom{2n}{n}^{-1}\frac{\left(\tfrac{\beta}{2}\right)^{2n}}{\left(1+\frac{\beta}{2}\right)^{\uparrow 2n}}   \lambda^{2n}  

        + \mathcal{O}(\lambda^{2n+2}).
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 of arXiv:2608.17493, 'Integrals of some compound processes'] Let $N$ be a renewal process with waiting times $X\sim F$ and $\{A_n\}_{n\ge1}$ be a sequence of real random variables independent of $N$ (and its waiting times),
	\begin{itemize}
		\item[($i$)] with $\gamma\in\mathbb{R}$,
		\begin{equation}
			\mathbb{E} \exp\Biggl( i\gamma \sum_{k=1}^{N(t)} X_k A_k \Biggr) = \sum_{n\ge0}\mathbb{E} \Biggl[\conv_{k=1}^n \Big( e^{i\gamma A_k\sbullet} F(\sbullet) \Big)\ast 1 (t)- \conv_{k=1}^{n} \Big( e^{i\gamma A_k\sbullet}F(\sbullet) \Big)\ast F \ast 1 (t) \Biggr],
		\end{equation}
		where $hF\ast g (t)= \int_0^t g(t-x)h(x)F(\dif x)$ for suitable functions $h,g$ and distribution $F$.
		\item[($ii$)] If $X$ is absolutely continuous with density $f$ and $\mu>0$,
		\begin{equation}
			\mathcal{L} \left\{ \mathbb{E} \exp\Biggl( i\gamma \sum_{k=1}^{N(t)} X_k A_k \Biggr) \right\} (\mu) = \frac{1-\mathcal{L}f(\mu)}{\mu}\sum_{n\ge0}\mathbb{E} \prod_{k=1}^n \mathcal{L}f(\mu+i\gamma A_k).
		\end{equation}
	\end{itemize}

[Lemma 32 (Contribution of $\Omega_{-,\M + \delta}$) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] Let $z_0 \in \R^2$. Suppose that $x_{max}^+ < x_{max}^-$ (i.e., $\alpha_b \in (0,\pi)$), and let $\alpha_0 \in [0, \alpha_b)$.  
If $b_0 \leq 0$, then
\begin{equation}
\frac{1}{2i\pi}\int_{\Omega_{-,\M + \delta} \cup \Omega_{+,\M + \delta}}\Phi(x)e^{-r(\cos(\alpha)x+\sin(\alpha)Y^+(x))}
 dx
\underset{r\to\infty \atop\alpha\to\alpha_0, \alpha \geq 0}{\sim}  C_{br}f_0(z_0)\frac{e^{-r(\cos(\alpha)x(\alpha_b) + \sin(\alpha)y(\alpha_b))}}{r^{3/2}
\sin(\alpha_b - \alpha)^{3/2}}
\end{equation}
where $C_{br} = |\sin(\alpha_b)|^{3/2} C_0$ (see \eqref{eq:C_0}), and where $f_0(z_0)$ is defined in \eqref{f(z_0)branch}. If $b_0 > 0,$ then \begin{equation}
\frac{1}{2i\pi}\int_{\Omega_{-,\M + \delta} \cup \Omega_{+,\M + \delta}}\phi^{z_0}(x)\frac{\gamma(x,Y^+(x),Z^+(x))}{\partial_y\gamma_+(x,Y^+(x))}e^{-r(\cos(\alpha)x+\sin(\alpha)Y^+(x))}
 dx
\end{equation}
$$\underset{r\to\infty \atop\alpha\to\alpha_0, \alpha \geq 0}{\sim}  C_{br}f_0(z_0)\frac{e^{-r(\cos(\alpha)x(\alpha_b) + \sin(\alpha)y(\alpha_b))}}{r^{3/2}
\sin(\alpha_b - \alpha)^{3/2}}.$$

