[Lemma lem:expansion of arXiv:2609.02234, 'An $n(\log n)^{o(1)}$ bound for nested cycles without geometric crossings'] Let $G$ be a $K$-minimal graph of order $n$. If $\varnothing\ne U\subseteq V(G)$ and $u=|U|\le n/2$, then
\begin{align}
|N_G(U)|
 &>\frac{u}{1+\mathrm e^{-2}}
 \left(1-\frac{\omega(u)}{\omega(n)}\right) \\
&\ge\frac u2
\left(1-\frac{\omega(u)}{\omega(n)}\right),\notag
\end{align}
and
\begin{equation}
  |N_G(U)|\ge\frac{u\log(n/u)}{8L\Lambda}.
\end{equation}

[Definition 1 (SRRW on a discrete group) of arXiv:2604.07207, 'Mixing times of step-reinforced random walks'] Let $(G,\cdot)$ be a discrete group with $|G|\geq 2$ and let $\mu$ be a probability measure on $G$. Let $(\xi_n)_{n\geq 2}$ be i.i.d.\ Bernoulli random variables with success parameter $\alpha\in [0,1]$, and let $(u_n)_{n\geq 2}$ be independent random variables where each $u_n$ is uniformly distributed on $\{1,2,\ldots,n-1\}$. Define a walk $(S_n)_{n\in \NN}$ and its the step sequence $(X_n)_{n\geq 1}$ recursively as follows:
\begin{enumerate}[(i)]
  \item Set $S_0:=x \in G$ and at time $n=1$, sample $X_1$ from $\mu$, set $S_1:=X_1$;
  \item For $n> 1$, given $X_1,X_2,\dots,X_{n-1}$: 
  \begin{itemize}
    \item If $\xi_{n}=1$, set $X_{n}:=X_{u_{n}}$;
    \item If $\xi_{n}=0$, sample $X_{n}$ independently from $\mu$.
  \end{itemize}
 Update $S_{n}:=S_{n-1}\cdot X_{n}$.
\end{enumerate}
The process $S=(S_n)_{n\in \NN}$ is called a step-reinforced random walk (SRRW) on $G$ started at $x$, with step distribution $\mu$ and reinforcement parameter $\alpha$.

[Lemma lm:ineqs of arXiv:2601.09537, 'Gene genealogies in haploid populations evolving according to sweepstakes reproduction'] For  any  $0 < a \le  1$ and $k\in \ensuremath{\mathds N}$  we have 
\begin{equation}

    \frac{a}{(k+1)^{1+a} } \le   \frac{1}{k^a} - \frac{1}{(1 + k)^a} \le \frac{1}{k^{1 + a}}
\end{equation}
When $a \ge  1$ and $k\ge 2$  we have 
\begin{equation}

     \frac{1}{k^{1 + a}} \le  \frac{1}{(k-1)^a} - \frac{1}{k^a}  \le  \frac{a}{(k-1)^{a + 1}}
\end{equation}

