[Lemma 12 (Triangular dependence of $\Gamma$ and $d\Gamma$) of arXiv:2605.28677, 'Weak universality for stochastic reaction-diffusion models\\ with long-range correlated no'] ~
\begin{enumerate}
\item If $\pi^{(\n)}$ is such that $\pi^{(\n)}_{\beta'}=0$ for non populated $\beta'$, then for all $\beta,\gamma$
\begin{equation}
\begin{aligned}
\begin{rcases*}
\text{if } \gamma \text{ is populated} \\
\hphantom{\text{if }\gamma}\text{ and not purely polynomial}
\end{rcases*} \quad \text{ then }
\Gamma_{\beta}^{\gamma} \text{ depends on } \pi_{ \beta'}^{(\n)}
\text{ only if} \quad
\begin{cases} 
\beta' \preceq \beta \,.\\
\beta' \prec \beta \,.
 \end{cases} 
\end{aligned}
\end{equation}

\item For all $\beta,\gamma$
\begin{equation}
\begin{aligned}
\begin{rcases*}
\text{if } \gamma \text{ is populated} \\
\hphantom{\text{if }\gamma} \text{ and not purely polynomial} 
\end{rcases*} \quad \text{ then }
d\Gamma_{\beta}^{\gamma} \text{ depends on } d\pi_{ \beta'}^{(\n)}
\text{ only if} \quad
\begin{cases} 
\beta' \preceq \beta \,.\\
\beta' \prec \beta \,.
 \end{cases} 
\end{aligned}
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 21 of arXiv:2609.03736, '2609.03736'] The joint typical subspace contains asymptotically all of the
tensor powers:
\begin{equation}
 \Tr\bigl(\mathcal A_n(I-p_n)\bigr)=o(1).

\end{equation}
Moreover, for every sequence of nonzero positive Hecke operators $\rho_n$
in the generalized Hecke algebra satisfying $\rho_n=p_n\rho_np_n$,
\begin{align}
 \limsup_{n\to\infty}\frac1n\log_2D_{\rho_n}
 &\leq\Ent(K)+\Ent(L),
 \\
 \liminf_{n\to\infty}\frac1n\log_2r_{\rho_n}
 &\geq\Ent(G).

\end{align}
Consequently,
\begin{equation}
 \limsup_{n\to\infty}\frac1n\log_2
 \frac{D_{\rho_n}}{r_{\rho_n}}
 \leq\Phi(K,L).

\end{equation}

