[Lemma 16 of arXiv:2607.08129, '2607.08129'] For $\rho\in(0,1/4)$, let $N_m=\lfloor(1+\rho)^m\rfloor$.  Then, on an event of probability one,
\begin{equation}
 \lim_{\substack{\rho\downarrow0\\ \rho\in\mathbb Q}}
 \limsup_{m\to\infty}
 \max_{N_m\le n\le N_{m+1}}
 \frac{\norm{C_n-C_{N_m}}_\infty}{a_{N_m}}=0.
\end{equation}

[Lemma 3 of arXiv:2511.20519, '\textbf{High-dimensional limits arising from \\ hyperbolic Poisson $k$-plane processes}'] Let \((X_n)_{n\geq 1}\) be a sequence of random variables.
    Assume that their characteristic functions are of the form
    \[ \varphi_{X_n}(t) = \exp(\Psi_n(t)) = \exp\Big(\int_\R (e^{itx} - 1 - itx) \,\nu_n(\dint x)\Big), \quad t \in \R,\]
    with measures \(\nu_n\) on $\R$ that satisfy
    \begin{equation}
        \int_\R x^2 \,\nu_n(\dint x) = 1.
    \end{equation} 
    \begin{enumerate}[label=\emph{(\alph*)}]
    \item If
    \begin{equation}
        \int_{\{|x| > \varepsilon\}} x^2 \,\nu_n(\dint x) \to 0 \quad \text{for all} \quad \varepsilon > 0,
    \end{equation}
    then $X_n \xrightarrow{D}\mathcal{N}(0,1)$.
    \item If
    \begin{equation}
        \int_{\{|x| \leq \varepsilon\}} x^2 \,\nu_n(\dint x) \to 0 \quad \text{for all} \quad \varepsilon > 0,
    \end{equation}
    then $X_n \xrightarrow{D} 0$.
    \end{enumerate}

