{"artifact_digest":"sha256:1587d12f6164382f02f7da7a07bfb3b25233a730dedfbca6f16ad78f83dace33","artifact_path":"objects/sha256/15/1587d12f6164382f02f7da7a07bfb3b25233a730dedfbca6f16ad78f83dace33.md","bundle_digest":"sha256:b1a1543208ada27d990100cd4e7c181718a06413676427e139a887bcd3831fe9","bundle_entry_key":"2607-25694-lemma-1-temporal","bundle_id":"population.tex-extract-s1_047","claim_kind":"lemma","conditions":[],"domain":"probability theory","draft":"tex-extract-v2-20260907/bundle_s1_047.json","evidence_ids":[],"logical_id":"math:harvest.arxiv.mathematics:arxiv-2607-25694-lemma-1-temporal","overlay_schema_version":1,"proof_text":"Paper's own proof, opening: Given, a priori \(\beta>1\), \(t\in[0,T]\), \(x\in\mathbb{R}\), and \(h>0\). Analogously to [AssaadTudor2021], we employ the change of variables \(x-y=z\) and \(t-s=\tilde{s}\), which yields
\begin{align*}
    B_{t,x}(h)&=\int_{\mathbb{R}}\left(\int_{0}^{t}\bigl|G_{t+h-s}(x-y)-G_{t-s}(x-y)\bigr|^{\beta}ds\right)^{\frac{1}{\beta}}dy \\
    &=\int_{\mathbb{R}}\left(\int_{0}^{t}\bigl|G_{s+h}(z)-G_{s}(z)\bigr|^{\beta}ds\right)^{\frac{1}{\beta}}dz.
\end{align*}
