body:
[Prop Prop-Interior-Lower of arXiv:2609.01964, 'The critical exponent for the two-dimensional semilinear wave equation with strong damping'] The following estimates hold in the strict interior region $\frac25t\leqslant r\leqslant\frac34t$.
	\begin{enumerate}[label=(\roman*)]
		\item If $2<p<\frac{10}{3}$ and $\mu_p:=\frac74-\frac p2$, then there exist $T_{\mathrm{int}},C_{\mathrm{int}}>0$ such that
		\begin{align}
			w(t,r)\geqslant C_{\mathrm{int}}t^{\mu_p}\ \ \mbox{for}\ \ t\geqslant T_{\mathrm{int}}.
		\end{align}
		\item If $p=\frac{10}{3}$, then there exist $T_{\mathrm{crit}},C_{\mathrm{crit}},c_{\mathrm{crit}}>0$ such that
		\begin{align}
			w(t,r)\geqslant C_{\mathrm{crit}}t^{-\frac34}\exp\bigl(c_{\mathrm{crit}}(\log t)^\theta\bigr)\ \ \mbox{for}\ \ t\geqslant T_{\mathrm{crit}}.
		\end{align}
	\end{enumerate}

