body:
[Definition recap of arXiv:2608.29708, 'Intuitionistic and Constructive Modal Logics for Classical Modal Logicians'] The satisfaction relations $\Vdash^i$, $\Vdash^{\text{c}}$, $\Vdash^{\text{h}}$, $\Vdash^e$ are defined as follows:
  \begin{itemize}
    \item For the $\bot$ case:
          \begin{itemize}
            \item $x \not \Vdash^\bullet \bot$, for $\bullet \in \set{ i, h, e }$.
            \item $x \Vdash^{\text{c}} \bot \mathrel{\;\ratio\Longleftrightarrow\;} x \in W_\bot$, where $W_\bot$ is the set of fallible worlds.
          \end{itemize}
    \item For the $\Box$ case:
          \begin{itemize}
            \item $x \Vdash^\iota \Box \varphi \mathrel{\;\ratio\Longleftrightarrow\;} \forall x' \geq x \, \forall y' \sqsupset x' \, (y' \Vdash^\iota \varphi)$, for $\iota \in \set{ c, i, h }$.
            \item $x \Vdash^e \Box \varphi \mathrel{\;\ratio\Longleftrightarrow\;} \forall y \sqsupset x \, (y \Vdash^e \varphi)$.
          \end{itemize}
    \item For the $\Diamond$ case:
          \begin{itemize}
            \item $x \Vdash^\iota \Diamond \varphi \mathrel{\;\ratio\Longleftrightarrow\;} \forall x' \geq x \, \exists y' \sqsupset x' \, (y' \Vdash^\iota \varphi)$, for $\iota \in \set{ c, i }$.
            \item $x \Vdash^\varepsilon \Diamond \varphi \mathrel{\;\ratio\Longleftrightarrow\;} \exists y \sqsupset x \, (y \Vdash^\varepsilon \varphi)$, for $\varepsilon \in \set{ h, e }$.
          \end{itemize}
  \end{itemize}

[Proposition 24 of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] For every $R<\infty$, we have
\begin{align}
    \lim_{N\to\infty}\sup_{q\in\mcl Q_\infty^\D:\:|q|_{L^\infty}\leq R}\E_x\Delta_N(x,q)=0.
\end{align}

[Prop geographic ineq decoupling map of arXiv:2604.21663, 'Large deviations for non-irreducible Markov chains on Euclidean spaces'] Let $u\in \widetilde{\mathcal{W}}_n$ be such that $|u|_\gamma\leqslant (\lambda_\gamma+\varepsilon) n$ for $\gamma\in \{1,2\}$ and set $(u^1,\ldots, u^r)=F_{n}(u)$. For $\gamma\in \{1,2\}$, we denote by $\underline v^{(\gamma)}$ the list $ (u^{j_\gamma(1)},\ldots, u^{j_\gamma(r_\gamma)})$. 
	Assume that $\underline v^{(\gamma)}\neq(e,\ldots,e)$ for $\gamma\in \{1,2\}$.
	Then, for all $w\in \Phi_n(u)$, 
	\begin{equation}

		d_{\mathrm{LP}}(L^{(\gamma)}[u],L[w])\leqslant  h\Big(\frac {{|\underline v^{(\gamma)}|}}{|u|_\gamma}\Big)+2h\Big(\frac{|\underline v^{(\gamma)}|}{T_\gamma}\Big).
	\end{equation}

