[Lemma 14 of arXiv:2609.00245, 'Higher-order Gaussian bounds for maximally subelliptic boundary value problems'] For \(f\in \DomainL\),
    \begin{equation}
        \opLOne \left( f\circ \Phi_{\xi,\delta} \right) = \left(\delta^{2\kappa} \opL f \right)\circ \Phi_{\xi,\delta},\quad (\xi,\delta)\in \SSetOne,
    \end{equation}
    \begin{equation}
        \opLTwo \left( f\circ \Psi_{\xi,\delta} \right) = \left(\delta^{2\kappa} \opL f \right)\circ \Psi_{\xi,\delta},\quad (\xi,\delta)\in \SSetTwo,
    \end{equation}
    where \eqref{Eqn::Proof::Completion::PullBackOfopLisOpLk::One} is interpreted in the sense
    of distributions and \eqref{Eqn::Proof::Completion::PullBackOfopLisOpLk::Two} is interpreted
    in the sense of \(\DistributionsZero\).

[Cor 9 of arXiv:2605.15501, 'Well-posedness of the obstacle problem for generalized Dean--Kawasaki equation\thanks{ The'] Let Assumption \ref{assu:assum for F} and Assumption \ref{assu:assu for unique} hold for two initial functions $u_{1,\mathrm{init}}$ and $u_{2,\mathrm{init}}$.
Let $(u_{1},\nu_{1})$ and $(u_{2},\nu_{2})$ be stochastic kinetic solutions of the obstacle problem for \eqref{eq:main} in the
sense of Definition \ref{def:def of stochastic kinetic solution} with initial data $u_{1,\mathrm{init}}$ and $u_{2,\mathrm{init}}$, respectively.
Let $\chi_{1}$ and $\chi_{2}$ be the kinetic functions of $u_{1}$ and $u_{2}$.

Then, we have, almost surely, for almost every $t\in(0,T)$,
\begin{align}
\|u_1(t)-u_{2}(t)\|_{L^1(\mathbb{T}^d)}
\leq\|u_{1,\mathrm{init}}-u_{2,\mathrm{init}}\|_{L^1(\mathbb{T}^d)}.
\end{align}

[Conjecture 3 of arXiv:2608.13359, 'Fractional moments of the Stochastic Heat Flow and\\2D Directed Polymers'] As soon as \(\EE\bigl[ \mathscr{Z}_{t}^{\th}(\cU_r)^2\bigr] \to\infty\)  with \(r\leq \sqrt{t}\), then for any \(p\in \R\) we have that
  \begin{equation}

    \EE\bigl[\mathscr{Z}_{t}^{\th}(\cU_r)^{p}\bigr]
    = \EE\bigl[ \mathscr{Z}_{t}^{\th}(\cU_r)^2\bigr]^{\frac{p(p-1)}{2} +o(1)}  \,,
  \end{equation}
  where \(o(1)\) is a quantity that depends on \(t,\th,r,p\) and goes to \(0\) as soon as \(\EE\bigl[ \mathscr{Z}_{t}^{\th}(\cU_r)^2\bigr] \to\infty\). (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Lemma eq:sph-grad of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:spherical-derivatives}
For \(v,w\in T_\sigma\mathbb S_N\),
\begin{align}
 \nabla_SF(\sigma)&=P_\sigma\nabla F(\sigma),\\
 \operatorname{Hess}_SF(\sigma)[v,w]
 &=D^2F(\sigma)[v,w]
 -\frac{\ip{\nabla F(\sigma)}{\sigma}}N\ip vw.
\end{align}
If \(F\) is homogeneous of degree \(p\), then
\begin{equation}
 \operatorname{Hess}_SF(\sigma)[v,w]
 =D^2F(\sigma)[v,w]-\frac{pF(\sigma)}N\ip vw.
\end{equation}

[Definition 188 of arXiv:2601.16377, '2601.16377'] For each left trapezoid $\mathcal{T}_q$, we define the map $z^{(q)} : \pounds_q \rightarrow \Sigma^{(q)}$ as the unique solution in the \emph{upper} half-plane of \eqref{eq_critical_equation_rescaled}, that is
\begin{equation}
 \frac{-x}{y - z^{(q)}} = e^{-G^{(q)}(z^{(q)})} - 1,
\end{equation}
where $G^{(q)}$ is the function \eqref{eq_x296} for the $q$-th trapezoid. We denote this solution $z^{(q)}$ and treat it as a point in $\Sigma^{(q)}$. For each right trapezoid $\mathcal{T}_q$, we map its liquid region $\pounds_q$ into a unique solution of \eqref{eq_critical_equation_rescaled2} in the \emph{lower} half-plane. We again denote this solution $z^{(q)}$ and treat it as a point in $\Sigma^{(q)}$.

[Theorem 8 (Comparison model approximation) of arXiv:2604.23461, 'Scaling limit of Sinkhorn-rescaled Random Matrices \\ via Stability of Static Schrödinger '] Suppose Assumptions \ref{assump:random_matrix}--\ref{assump:bounded_cost} hold. 
		Fix $D>0$ and let $\tau$, $t_D$ be as in Lemma \ref{lem:spectral norm of centered poisson} with the sub-exponential parameters $(\sigma,R)$ of Assumption \ref{assump:random_matrix}. Let $\eps_0$ be the approximation error defined in \eqref{eq:eps0_Cstar_def} and let $C_*$ be the explicit stability constant defined in Theorem \ref{thm:concentration_margins_rs}. Assume the dimensions are sufficiently large such that $\eps_0 \le \frac{1}{50 C_*^2}$, and define the aggregate potential error $\eps_{\textup{pot}} := 16 C_* \eps_0 \le 1$.
		Define the two events
		\begin{align}
			\mathcal{E}_{2} &:= \{ \X\in \mathcal{S}(\r,\c) \} \cap \left\{\tfrac{1}{N}\bigl\|\D(e^{\balpha_{\X}})(\X-\bLambda)\D(e^{\bbeta_{\X}})-\D(e^{\balpha})(\X-\bLambda)\D(e^{\bbeta})\bigr\|_2 \le \tfrac{3 e^{2K}\eps_{\textup{pot}} t_D}{\|\bLambda\|_1}\right\},\\

			\mathcal{E}_{3} &:= \{ \X\in \mathcal{S}(\r,\c) \} \cap \left\{ \tfrac{1}{N}\left\|\X^{\r,\c} - \hat{\X}^{\r,\c}\right\|_1 \le 2\eps_{\textup{pot}} e^{2K} \right\}.
		\end{align}
		Then there exists an absolute constant $c>0$ such that
		\begin{align}
			\P(\mathcal{E}_{2}) &\ge 1 - 2(m \vee n)^{-D} - m^2 \exp(-c\,\Phi_{\bLambda}), \\
			\P(\mathcal{E}_{3}) &\ge 1 - (m \vee n)^{-D} - m^2 \exp(-c\,\Phi_{\bLambda}) - 2\exp\!\left(-\frac{\|\bLambda\|_1^2/2}{mn\sigma^2+R\|\bLambda\|_1}\right),
		\end{align}
		where $\Phi_{\bLambda}$ is the row-alignment rate from \eqref{eq:Phi_def}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 26 of arXiv:2607.23791, 'Precise cover times for branching random walks on Hamming graphs: (iterated) logarithmic c'] Let $N_y(t)$ be the number of particles at $y$ at time $t$ and denote by 
$\alpha=d_{\rm H}(x,y)/d$.  With $q=e^{-2t/d}$,
\begin{equation}
 \mu:=\E_x[N_y(t)]
 =e^{\lambda t}2^{-d}(1+q)^{(1-\alpha)d}(1-q)^{\alpha d}.
\end{equation}
For $0\le h\le-\log q$, we have
\begin{equation}
 \frac{\E_x[N_y(t)^2]}{\mu^2}
 =\frac1\mu+2\lambda\int_0^t
 \exp\!\left(dG_\alpha\!\left(e^{-2(t-s)/d},q\right)\right)\dd s,
\end{equation}
where
\begin{align}
    G_\alpha(e^{-h},q)={}&-\frac{\lambda h}{2}
 +(1-\alpha)\log\!\left(
 1+\frac{q^2}{(1+q)^2}(e^{2h}-1)\right)+\alpha\log\!\left(
 1+\frac{q^2}{(1-q)^2}(e^{2h}-1)\right).
\end{align}

