[Cor gauge-formal of arXiv:2608.30847, 'An Almgren-type formula for planar $p$-harmonic functions'] Assume that $\Theta\in L^1(0,r_0)$.  Then
\begin{equation}
r\mapsto  \exp\left(\int_{r_0}^r \Theta(s)\,ds\right)N_*(r) 
\end{equation}


is nondecreasing on $(0,r_0)$.

[Theorem th:diff_reg of arXiv:2412.04032, 'Cutoff for the mixing time of the Facilitated Exclusion Process'] For all $\varepsilon \in (0,1)$, for all sequence $K=K(N)$ such that for all $N$, $N/2 < K < N$, 
\begin{itemize}
\item If $\frac{\log (2K-N)}{\log K} \longrightarrow 0$ (e.g. $K = N/2 + \log N$), then 
\eqs{\left|\tau^{\textsc{fep}}_{N,K}(\varepsilon)-\frac{1}{\pi^2}K^2 \log K\right| =\mathcal{O}_\varepsilon\left( N^2 \max\left(\log\log N,  \log (2K-N)\right)\right).}
\item If $\frac{\log (2K-N)}{\log K} \longrightarrow \alpha \in (0,1)$ (e.g. $K = N/2 + N^\alpha$), then
\eqs{\max\Big(\frac{1-\alpha}{\pi^2},\frac{\alpha}{8\pi^2}\Big) \le \varliminf\limits_{N \to \infty} \frac{\tau^{\textsc{fep}}_{N,K}(\varepsilon)}{K^2 \log K} \le \varlimsup\limits_{N \to \infty} \frac{\tau^{\textsc{fep}}_{N,K}(\varepsilon)}{K^2 \log K} \le \frac{1-\alpha}{\pi^2} + \frac{\alpha}{8 \pi^2}.}
\item If $\frac{\log (2K-N)}{\log K} \longrightarrow 1$ and $(N-K)\to \infty$  (e.g. $K/N \longrightarrow \rho \in (\frac12,1)$), then, setting $P=\min(2K-N,N-K)$,
\eqs{\left|\tau^{\textsc{fep}}_{N,K}(\varepsilon)- \frac{1}{8\pi^2}K^2 \log P\right| =\mathcal{O}_\varepsilon \left(K^2\left(1+\log\frac{K}{2K-N}\right)\right).}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 8 (Main theorem) of arXiv:2606.23383, 'Near-Lipschitz stability of the Kim--Milman flow map'] Suppose $\mu$ satisfies \eqref{theta} and $\nu \in \cP_2(\R^d)$ with $\mathsf m_2(\mu),\mathsf m_2(\nu) \leq M$. In addition, let $\mathsf C_\mu \geq 0$ be such that for all $0\leq s\leq t$, it holds that
    \begin{align}
        \int_s^t \theta_u \dd u \leq \mathsf C_\mu\,.
    \end{align}
    Then,
    \begin{align*}
        \|\mathsf T^{\mu} - \mathsf T^{\nu}\|_{L^2(\gamma)} \leq
        W_2(\mu,\nu)\exp(3\mathsf C_\mu) \log\Bigl[e^2\max\Bigl\{1,\, \frac{4M^2 + 8d}{W_2^2(\mu,\nu)\exp(6\mathsf C_\mu)}\Bigr\}\Bigr]\,.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 45 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] Let $\mathbf i=(i_1,\ldots,i_s)$ be a word and suppose that all reciprocal
operators below are defined on the relevant finite boxes.  Put
$C_i^{(z)}=1-(x_i+z)\partial_i$.  Then
\begin{align}
 \mathcal R_{M,r+s}\mathscr K_{i_1}^{(z)}\cdots
 \mathscr K_{i_s}^{(z)}\mathcal R_{M,r}
 &=C_{i_1}^{(z)}\cdots C_{i_s}^{(z)},
 \\
 \mathcal R_{M,r+s}\mathscr D_{i_1}^{(z)}\cdots
 \mathscr D_{i_s}^{(z)}\mathcal R_{M,r}
 &=(-\mathscr K_{i_1}^{(z)})\cdots
   (-\mathscr K_{i_s}^{(z)}).

\end{align}

