[Theorem thm:Wass_p_bnd_new of arXiv:2608.13452, 'Wasserstein stability of the zero cell of a Poisson hyperplane tessellation under directio'] Consider the setting of (lem:mainBound of the paper).  
Assume that $\phi_2$ is sufficiently close to $\phi_1$ such that
    \begin{align} 
    W_{\mathrm{geo}}(\phi_1,\phi_2) \leq \min_{u\in S^{d-1}} h(\Pi_1,u) \eqcolon C_1 .
    \end{align}
Then, for $p \in [1, \infty)$,
\begin{align}
         W_{\rho_p}\bigl(Z_0^{(1)} , Z_0^{(2)} \bigr) 
        \leq \frac{ 6\Gamma(p+1)^{1/p}(d\kappa_d)^{1/p} C_1^{-\frac{p+1}{p}} }{\gamma} W_{\mathrm{geo}}(\phi_1,\phi_2)^{\frac{1}{p}}.   
\end{align}
and
\begin{align} 
    W_{\Delta}\bigl(Z_0^{(1)},Z_0^{(2)}\bigr) 
    &\leq 
    \frac{ 6d\kappa_d\,d!\, \left(1+2^{-d}\right)^{\frac{d-1}{d}} C_1^{-d-\frac1d} }{\gamma^d} W_{\mathrm{geo}}(\phi_1,\phi_2)^{\frac1d}, 
\end{align}
where \(\kappa_d:= \lambda_d(B_d)\) is the volume of the unit ball in \(\mathbb{R}^d\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2604.08127, 'Asymptotics of Brownian occupation measures \\ with unusually large intersections'] Let $W_t$ be a Brownian motion in $\mathbb{R}^d$. For any $k < d$ and $x \in \mathbb{R}^d$, we have the following estimates. Here, $C$ is a constant that may depend on $d$ and $k$ but not on $t$, $x$, or $\epsilon$.
        \begin{align}

            \mathbb{E} \delta(W_t - x) &\le C\min\{ |t|^{-d/2}, |x|^{-d} \} \\

            \left| \mathbb{E} \Delta_{\epsilon}(W_t - x)\right| &\le C  \min\{ |t|^{-d/2}, |x|^{-d}, \epsilon|t|^{-d/2 - 1}, \epsilon|x|^{-d - 2} \} \\

            \mathbb{E}|W_t - x|^{-k} &\le C \min\{ t^{-k/2}, |x|^{-k} \} 
        \end{align}

[Thm pointstationary of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] Let $\mathsf{P}\in \mathcal P_{s,1}(\Gamma)$. Then its Palm measure $\mathsf{P}^0$ is stationary w.r.t.\ the shifts $\theta_{\tau_i}$, $i\in \IZ$, defined  for $\xi\in \Gamma_0$ by 
    \begin{align*}
        \theta_{\tau_i}(\xi):=\theta_{\tau_i(\xi)}\xi,
    \end{align*}
    where $\xi=\{\cdots,\tau_{-1}(\xi),0=\tau_0(\xi),\tau_1(\xi),\cdots\}$ is the  enumeration of $\xi$ defined in (equation eq:numbering of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

Let W be a Brownian motion and X_t = X_0 + int_0^t mu_s ds + int_0^t sigma_s dW_s, with mu and sigma adapted and the integrals well defined (for instance int_0^t |mu_s| ds and int_0^t sigma_s^2 ds finite almost surely). If f(t, x) is once continuously differentiable in t and twice in x, then f(t, X_t) is again an Ito process with df(t, X_t) = (f_t + mu_t f_x + (1/2) sigma_t^2 f_xx) dt + sigma_t f_x dW_t. Equivalently, df = f_t dt + f_x dX + (1/2) f_xx d[X], where d[X]_t = sigma_t^2 dt: the second-order term comes from the nonvanishing quadratic variation of Brownian motion.
W a Brownian motion; mu and sigma adapted, with int |mu| ds and int sigma^2 ds finite almost surely
f in C^{1,2}

[Definition defin:dirichletforms of arXiv:2606.01937, 'Stationary fluctuations for an exclusion process with mass and energy conservation'] Let $\mu$ be any probability measure on $\Omega$. For any $x,y\in\mathbb{Z}$ and any local function $f:\Omega\longrightarrow\mathbb{R}$ we define the Dirichlet forms with respect to the measure~$\mu$ by
    \begin{align}
        & \mathfrak{D}_{x\to y}^p (f;\mu ) \coloneq \frac12\int_{\Omega} c_{x\to y}^p(\eta )\big[ f(\eta^{x,y})-f(\eta )\big]^2\,\mathrm{d}\mu (\eta ), \\
        & \mathfrak{D}_{x\to y}^e(f;\mu )\coloneq \frac12\int_{\Omega}c_{x\to y}^e(\eta )\big[ f(\eta^{x\to y})-f(\eta )\big]^2\,\mathrm{d}\mu (\eta )
    \end{align}
    where the jump rates $c^p$ and $c^e$ are given respectively in (equation def:particlerate of the paper) and (equation def:energyrate of the paper), and the transformations of configurations are given by (equation eq:transformedconfig of the paper). Finally, we define the total Dirichlet form by
    \begin{equation*}
        \mathfrak{D}(f;\mu ) = \sum_{\substack {x,y\in\mathbb{Z}\\ |x-y|=1}} \big( \mathfrak{D}_{x\to y}^p(f;\mu ) + \mathfrak{D}_{x\to y}^e(f;\mu )\big).
    \end{equation*}
    By reversibility of the measure $\mu_{\rho ,\mathcal{E}}$ with respect to the generator $\mathcal{L}_S$ (\textit{cf.}~(prop:invariantmeasures of the paper)), we have the identity $\langle f,(-\mathcal{L}_S)f\rangle_{\rho ,\mathcal{E}} = \mathfrak{D}(f;\mu_{\rho ,\mathcal{E}})$ for any local function $f:\Omega\longrightarrow\mathbb{R}$.

[Proposition 28 (The existence of super Brownian motion (SBM), see e.g. \cite{etheridge2000introduction}) of arXiv:2604.01852, 'The on/off Brownian snake'] Let $\mu \in \mathcal{M}_F(\mathbb{R}^d)$. Then there exists a measure-valued process $(\mathcal{X}_s)_{s \geq 0}$ that takes values in $\mathcal{M}_F(\mathbb{R}^d)$ with $\mathcal{X}_0=\mu$ which is the scaling limit of BBMs in the following sense. Let $\Tilde{\mathcal{Z}}^\varepsilon=(\Tilde{\mathcal{Z}}^\varepsilon_s)_{s \geq 0}$ be $\text{BBM}(\gamma/\varepsilon)$ with $\Tilde{\mathcal{Z}}_0^\varepsilon$ distributed as a Poisson random measure with intensity $\mu/\varepsilon$. Then we have 
\begin{equation*}
    (\varepsilon \Tilde{\mathcal{Z}}^\varepsilon_s)_{s \geq 0} \rightarrow (\mathcal{X}_s)_{s \geq 0}
\end{equation*}
as $\varepsilon$ goes to $0$, in distribution on  $\mathbb{D}([0,\infty), \mathcal{M}_F(\mathbb{R}^d))$. This process $(\mathcal{X}_s)_{s \geq 0}$ is called $\text{SBM}(\gamma)$ started at $\mu$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma2.3 of arXiv:2609.02607, 'Spatial inhomogeneity for a three-dimensional doubly degenerate nutrient system with indir'] Let
$t_0:=\min\{1,\frac{T_{\max,\varepsilon}}{6}\}$ and $\kappa:=\kappa(t_0)>0$ as defined in Lemma (lemma2.2 of the paper). Then for all $t\in(0,T_{\max,\varepsilon})$, we have

\begin{equation}
v_\varepsilon(x,t)\leq e^{2\kappa t_0}\|v_0\|_{L^{\infty}(\Omega)}e^{-\kappa t}.
\end{equation}

[Proposition prop:Feller of arXiv:2606.29352, 'Exponential Mixing for 2D Stochastic Damped Euler Equation Driven by Bounded Noise'] The operator $P_i$ is sequentially weak$\star$ Feller in $W^{1,\infty}$, that is 
    \begin{equation}
        P_i:  SC_b(W^{1,\infty},\mathcal{T}_{w\star}) \rightarrow SC_b(W^{1,\infty} ,\mathcal{T}_{w\star}).    
    \end{equation} 
   Equivalently, one has
\begin{equation}
    P_i:C_b(W^{1,\infty} ,\mathcal{T}_{bw\star} ) \rightarrow C_b(W^{1,\infty} ,\mathcal{T}_{bw\star} ). 
    \end{equation}

[Proposition prop.relaxation of arXiv:2606.13442, 'Scaling limit of additive functionals for reversible non-gradient exclusion process: criti'] There exists a positive exponent $\delta(d,\mathbf{r}, c_{-},c_+)$, such that for every local function $f$, we have 
		\begin{align}
			\mathbb{V}\!\mathrm{ar}_{\rho}[P_t f] = \frac{\overline{f}' (\rho)^2 \chi(\rho)}{\sqrt{(8\pi t)^{d} \det [\mathbf{D}(\rho)]}} + o(t^{-\frac{d+\delta}{2}}).
		\end{align}
		Here the remainder depends on $f$ and satisfies ${\lim_{t \to \infty}t^{\frac{d+\delta}{2}}o(t^{-\frac{d+\delta}{2}}) = 0}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem th:Dobrushin-k>2 of arXiv:2607.21443, 'The critical KPZ scale for the averaging process'] Fix $k\ge 2$.
Let $(\beta_N)_{N\ge1}$ be any sequence such that $\beta_N\to0$ and
$\sup_{N\ge1}\beta_N N^{1/8}<\infty$.
Set $\mathfrak s_N\coloneqq \sinh(\beta_N)$.
Let $f,h:\mathbb{Z}\to\mathbb{R}$ be finite-support functions, with $f$ satisfying
$\sum_{x\in\mathbb{Z}}f(x)=0$.
Consider $N^{-1/2}\mathbf x^N\to\mathbf z\in\mathbb{R}^k$.
Then, under $\mathbf P_{\mathbf x^N}^{(\beta_N,k)}$, the processes
\begin{equation}
	\big(
	N^{-1/2}\tttonde{\mathbf R_{Nt}-tN\mathfrak s_N\mathbf 1}
	\big)_{t\ge0}\; \text{,}\;\;
	\qquad
	\big(
	\tttonde{
	N^{-1/2}\textstyle{\int_0^{Nt}}h(R_s^i-R_s^j)\,{\rm d} s
	}_{1\le i<j\le k}
	\big)_{t\ge0}\; \text{,}\;\;
\end{equation}
\begin{equation}
	\big(
	\tttonde{
	N^{-1/4}\textstyle{\int_0^{Nt}}f(R_s^i-R_s^j)\,{\rm d} s
	}_{1\le i<j\le k}
	\big)_{t\ge0}\; \text{,}\;\;
\end{equation}
jointly converge in law in $\ensuremath{\mathcal D}([0,\infty);\mathbb{R}^{d_k})$, with $d_k\coloneqq k+k(k-1)$, respectively to
\begin{equation}
	\begin{aligned}
		\left(
		\mathbf W_t\right)_{t\ge 0}\; \text{,}\;\;\qquad
		\big(\tttonde{\gamma^2(h)L_t^{W^i-W^j}}_{1\le i<j\le k}\big)_{t\ge 0}\; \text{,}\;\;\qquad
		\big(\tttonde{\sigma(f)B^{ij}_{L_t^{W^i-W^j}}}_{1\le i<j\le k}
		\big)_{t\ge0}\; \text{.}
	\end{aligned}
\end{equation}
Here, $\mathbf W=(W^1,\ldots,W^k)$ is a standard $k$-dimensional Brownian motion started from ${\mathbf z}\in\mathbb{R}^k$, the processes $(B^{ij})_{1\le i<j\le k}$ are independent standard Brownian motions independent of $\mathbf W$, and the noise coefficients $\gamma^2(h)$ and $\sigma(f)$ are given, respectively, in (equation eq:W+local-time of the paper) and (equation eq:sigma-squared of the paper).

