\begin{align*}
    L^*(q_E, q_{E^c})&=2p^*_{E} \ln \frac{p^*_E}{1-p^*_E} - p^*_E\ln\frac{q_E}{1-q_E} - p^*_E\ln\frac{q_{E_c}}{1-q_{E^c}}+\ln \frac{(1-p^*_E)^2}{(1-q_E)q_{E^c}}\\
    &=\ln \frac{(1-p^*_E)^2}{(1-q_E)q_{E^c}}.
\end{align*}
