[Lemma 25 of arXiv:2609.00183, '2609.00183'] Let $u$ be a harmonic map to an $N$-dimensional conical DM-complex $Y_C$ with splitting $u=(V,v):B_{\sigma_j}(0) \to (\mathbb{R}^j \times Y_C^{N-j},d_G)$ satisfying $\Ord_{\phi,v}(0,R_0)\leq \Lambda$ and $\sup_{B_{\sigma_j}(0)}|\nabla u| \leq M$, then there exists $\eta_1>0$ and $\calA\geq 1$, depending only on $\Lambda$, $n$, $M$, and the constant in \cite[(29)--(33)]{dm}, such that for $\sigma\in (0,\eta_1]$ and $\eta\in (0,\eta_1]$, if for $x\in B_{R_0/64}(0)$ there exists a homogeneous Lipschitz map $h:B_{\sigma}(x)\to Y_C$ such that
     \begin{equation*}
         \sup_{B_{\sigma}(x)}d(v,h)\leq \eta\paren{\sigma^{1-n}I_{\phi,v}(x,\sigma)}^{1/2},
     \end{equation*}
     then $\alpha\leq \calA$, where $\alpha$ is the degree of $h$.

[Them Markov_stationnaire of arXiv:2412.10001, 'On the Markov transformation of Gaussian processes'] Consider an interval  $T \subset \mathbb{R}$  and  a continuous positive semi-definite kernel $K : T \times T \to \mathbb{R}$ with constant variance function equal to $1.$ We denote by $P$ the centered Gaussian process with covariance function $K.$ For every $(s,t,h^*) \in T \times T \times \mathbb{R}_+^*$, we set  $$C_{s,t}(h^*) := \ens{(v,h)}{v \in [s,t[, v +h \in [s,t], h \in ] 0, h^*]}.$$

		\begin{enumerate}
			\item Assume $\alpha^K$ is well defined, continuous and for every $ s<t \in T \times T$
			\begin{equation}
				 \sup_{(v,h) \in C_{s,t}(h^*)} \left|L^K_v(h) - \alpha^K(v)\right| \xrightarrow[h^* \to 0^+]{} 0.
			\end{equation} 
			Then  $P_{\alpha^K}$ is the strong local Markov transform of $P.$
			\item Assume, for every $s<t  \in T \times T$ 
			\begin{equation}
				\inf_{(v,h) \in C_{s,t}(h^*)} L^K_v(h) \xrightarrow[h^* \to 0^+]{} + \infty.
			\end{equation}
		Then $P_{+\infty}$ is the strong local Markov transform of $P.$
		\end{enumerate}

[Theorem 5 of arXiv:2607.15903, 'Uniqueness for nonlinear Fokker-Planck equations with general diffusion terms and their as'] Assume that \textbf{Hypothesis (\MakeUppercase{\romannumeral 1})} holds. Let $u_{1}, u_{2} \in L^{1}((0,T)\times \mathbb{R}^{d})\cap L^{\infty}((0,T)\times \mathbb{R}^{d})$ be two distributional solutions to (\ref{1}) in $(0,T)\times \mathbb{R}^{d}$ such that $u_{1}-u_{2} \in L^{\infty}((0,T);H^{-1})$ and
 \begin{equation}
     \displaystyle\lim_{t \rightarrow 0} \displaystyle \esssup_{s \in (0,t)}\left | \left ( u_{1}(s)-u_{2}(s),\varphi  \right )_{2}\right |=0, \quad  \forall \varphi \in C^{\infty}_{0}(\mathbb{R}^{d}). 
 \end{equation}
 Then, $u_{1}\equiv u_{2} $.

