[Theorem 8 of arXiv:2606.15178, 'The distribution of the de Moivre experiment'] Let $X\sim\mathcal{B}^{(s)}(n,p)$ and let $x_i=\sum_{l=1}^{s}l^ip^lq^{s-l}=E(X_1^i)$. Then, for every $r\geq1$,
	\begin{equation}
		\kappa_r(X)=n\sum_{k=1}^{r}(-1)^{k-1}(k-1)!\,B_{r,k}\big(x_1,x_2,\ldots,x_{r-k+1}\big), \quad \text{ for } p\neq q, 
	\end{equation}
	and
	\begin{equation}
		\kappa_r(X)=n\sum_{k=1}^{r}(-1)^{k-1}(k-1)!\,p^{ks}\,B_{r,k}\Big(\sum_{l=1}^{s}l,\sum_{l=1}^{s}l^2,\ldots,\sum_{l=1}^{s}l^{r-k+1}\Big), \quad \text{ for } p=q.
	\end{equation}

