[Theorem 4 (Quenched  heat kernel estimate) of arXiv:2607.14718, 'Anchored Nash inequalities and heat kernel bounds for a class of random conductance models'] Let $d \geq 3$ and suppose there exist $m_{0} > d$, $p \in \big(\max\{1, \frac{d}{m_{0}-2}\}, \infty\big]$ and $q \in (1, \infty]$ satisfying \eqref{a1-1-2} such that $\theta^{\omega}(0), \mu^{\omega}_{m_{0}}(0) \in L^{p}(\prob)$ and $\nu^{\omega}(0) \in L^{q}(\prob)$. Then, there exist random constant $\cM_{1}^{\omega}$ and non-random constant $C_{4} \in (0, \infty)$ such that for every $\omega \in \Omega$ and $t > 0$,

  \begin{align}
    p^{\omega}(t,0,0)
    \;\leq\;
    C_{4}\, \cM_{1}^{\omega}\, t^{-d/2},
  \end{align}

  where $\cM_{1}^{\omega}$ is $\prob$-a.s.\ finite and explicity given by

  \begin{align}
    \cM_{1}^{\omega}
    \;\ldef\;
    \bigl(\cM_{0}^{\omega}\bigr)^{(1+m_{0}\gamma)/\beta}
    \bigg(1 + \frac{\mu_{m_{0}}^{\omega}(0)}{\theta^{\omega}(0)}\bigg)
  \end{align}

  with

  \begin{align}
    \cM_{0}^{\omega}
    \;\ldef\;
    \sup_{R \geq 1}\Bigl(
      \Bigl(
        \Norm{1 \vee \mu_{m_{0}}^{\omega}}{p, B(R)}
        + \Norm{1 \vee \theta^{\omega}}{p, B(R)}
      \Bigr) \cdot \Norm{1 \vee \nu^{\omega}}{q, B(R)}
    \Bigr),
  \end{align}

  and $\alpha, \beta, \gamma \in (0,1)$ are the same constants as in Lemma~\ref{l2-1} below associated with $m = m_{0}$.

[Cor unshuffling-cor of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Let $\mathbb{X}$ be a set and let $\psi$ be an $\mathbb{X}$-shuffling rule.
	If $\psi$ is $\mathfrak{S}$-equivariant, then for every $T,T'\in\trees$, ${\boldsymbol{x}}\in\mathbb{X}^T$, and ${\boldsymbol{\uppi}}\in\mathfrak{S}_{T'}$, we have
	\begin{align}
	\begin{cases}
	{\boldsymbol{\sigma}}^\psi_{T,{\boldsymbol{x}}}\cdotT=T',\\
	{\boldsymbol{\sigma}}^\psi_{T,{\boldsymbol{x}}}={\boldsymbol{\uppi}}^{-1}
	\end{cases}
	\qquad\iff\qquad
	\begin{cases}
	T={\boldsymbol{\uppi}}\cdotT',\\
	{\boldsymbol{\sigma}}^\psi_{T',{\boldsymbol{\uppi}}^{-1}_*{\boldsymbol{x}}}=\overline{\boldsymbol{\uppi}}.
	\end{cases}
	\end{align}

