body:
[Lemma 10 of arXiv:2604.24684, 'Waning Immunity Fails to Restore a Positive Epidemic Threshold on Power--Law Networks'] Fix a graph $G=(V,E)$ and let $G_\star$ denote the star subgraph on vertex set $\{v,u_1,\dots,u_k\}$ with center $v$ (so $G_\star\subseteq G$). Assume that the initial configuration $\boldsymbol{\sigma}(0)$ is arbitrary on $V$ and satisfies $\sigma_v(0)=I$. Let $T_S^{(v)}$ be the first time at which $v$ is susceptible. Then $T_S^{(v)}$ is measurable with respect to $\mathcal{G}(v,\{u_1,\dots,u_k\})$, where $\mathcal{G}(v,\{u_1,\dots,u_k\})$ is defined in Definition~\ref{def:local_graphical_data}. Then there exists an event
\(
A_3^{(v)} \in \mathcal{G}(v,\{u_1,\dots,u_k\})
\)
such that, for all sufficiently large $k$, the following hold:
\begin{enumerate}
    \item[\normalfont (i)] On $A_3^{(v)}$, $T_S^{(v)}\le \frac{1}{6}\log k$, and the vertex $v$ is infected at time $T_S^{(v)}+k^{-1/48}$;
    \item[\normalfont (ii)] On $A_3^{(v)}$, the vertex $v$ is $k^{1/24}$-lit among $\{u_1,\dots,u_k\}$ throughout the time interval  $[0, T_S^{(v)}+k^{-1/48}]$;
    \item[\normalfont (iii)] 
    \(
    \mathbb{P}\big(A_3^{(v)}\big)\ \ge\ 1-2k^{-\min\{1,\rho,\lambda\}/48}.
    \)
\end{enumerate}

[Cor 36 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $n\geq 1$
and let $\alpha_{n}>\alpha_{n-1}>\dots >\alpha_{1}>\alpha_{0}=1$.
Let $(c_{0}, c_{1}, \dots, c_{n})$
be the unique solution (Vandermonde) to the linear system
\begin{equation}

\forall k\in \{0,\dots, n-1\},
\sum_{i=0}^{n} c_{i} \alpha_{i}^{-(k+1/2)} = 0,
\qquad
\sum_{i=0}^{n} c_{i} \alpha_{i}^{-(n+1/2)} = 1.
\end{equation}
Then
\begin{equation}

\psi_{2n+1, A} = \lim_{\varepsilon \to 0} (-1)^{n}\dfrac{2^{n} n! (n+1/2)}{(2\pi)^{n}}\vert\log\varepsilon\vert^{n+1/2}
\sum_{i=0}^{n} c_{i} \ind_{\Ns_{\varepsilon^{\alpha_{i}}}(A)},
\end{equation}
with convergence in $L^{2}(d\PP,\sigma(\Phi),H^{-\eta}(\C))$ for $\eta>0$.

