body:
[Definition 8 of arXiv:2606.02036, 'Self-intersection local times for Volterra Gaussian processes in stochastic flows with int'] The stochastic differential equation
\begin{align}

\begin{cases}
\differential{x}(v,t)=a(x(v,t),\mu_t)\differential{t}+\int_{\mbR^d}b(x(v,t),\mu_t,z)W(\differential{t},\differential{z}), \\	
x(v,0)=v,\ v\in\mbR^d, \\
\mu_t=\mu_0\circ x(\cdot,t)^{-1},\ t\geqslant 0, 
\end{cases}
\end{align}
is said to be the equation with interaction.

[Theorem thm:kl_local_error of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] Let $\boldsymbol{P}$ denote the Markov kernel for~(eq:ULD of the paper), run for time $h$, and let $\hat{\boldsymbol{P}}$, $\hat{\boldsymbol{P}}{}'$ be two other Markov kernels (representing numerical discretizations). Assume that for all $x,\tilde x,p,\tilde p\in\mathbb{R}^d$, there are random variables $(X_h, P_h) \sim \delta_{x,p}\boldsymbol{P}$, $(\hat X_h,\hat P_h) \sim \delta_{x,p} \hat{\boldsymbol{P}}$ such that the following conditions hold.
    \begin{enumerate}
        \item (weak error) $h^{-1}\,\norm{\mathbb{E}\hat X_h - \mathbb{E} X_h} \vee \norm{\mathbb{E}\hat P_h - \mathbb{E} P_h} \leqslant \mathcal{E}^{\rm w}(x,p)$.
        \item (strong error) $h^{-1}\,\norm{\hat X_h - X_h}_{L^2} \vee \norm{\hat P_h - P_h}_{L^2} \leqslant \mathcal{E}^{\rm s}(x,p)$.
        \item (cross-regularity for $\hat{\boldsymbol{P}}{}'$) $\KL(\delta_{x,p} \hat{\boldsymbol{P}}{}' \mathbin{\|} \delta_{\tilde x,\tilde p} \boldsymbol{P}) \lesssim (\gamma h^3)^{-1}\,\norm{x-\tilde x}^2 + (\gamma h)^{-1}\,\norm{p-\tilde p}^2 + {b(x,p)}^2$.
    \end{enumerate}
    Above, for $\mathcal{F} \in \{b, \mathcal{E}^{\rm w}, \mathcal{E}^{\rm s}\}$, we let $\bar{\mathcal{F}} \coloneqq \max_{n=0,1,\dotsc,N-1}{\norm{\mathcal{F}}_{L^2(\bs\mu\hat{\boldsymbol{P}}{}^n)}}$.
    Adopt Assumption~(as:regularity of the paper) and assume that $h\lesssim \gamma^{-1} \wedge \gamma/\beta$ for a sufficiently small implied absolute constant.
    Then, for all $\bs\mu,\bs\nu \in \mathcal{P}_2(\mathbb{R}^d\times\mathbb{R}^d)$,
    \begin{align*}
        \KL(\bs\mu \hat{\boldsymbol{P}}{}^{N-1} \hat{\boldsymbol{P}}{}' \mathbin{\|} \bs\nu\boldsymbol{P}^N)
        &\lesssim C(\alpha,\beta,\gamma,Nh)\,\mathcal{W}_2^2(\bs \mu,\bs \nu) + \mathtt{Err} + \bar b^2\,.
    \end{align*}
    Here, the constant $C(\alpha,\beta,\gamma, Nh)$ is defined in Theorem~(thm:uld_regularity of the paper), $\mathcal{W}_2$ denotes $2$-Wasserstein distance in the twisted norm $(x,p)\mapsto \sqrt{\norm x^2 + \gamma_0^{-2}\,\norm p^2}$, and $\mathtt{Err}$ is bounded in the following cases. Denote $T = Nh$.
    \begin{enumerate}[label=(\roman*)]
        \item \textbf{Strongly convex and high friction setting:} Let $\alpha > 0$, $\gamma = \sqrt{32\beta}$, $\omega \coloneqq \alpha/(3\gamma)$, and assume additionally that $h \lesssim 1/(\beta^{1/2}\kappa)$.
        Then,
        \begin{align*}
            \mathtt{Err}
            &\lesssim \frac{1}{\alpha h^2}\,(\bar{\mathcal{E}}^{\rm w})^2 + \Bigl[\frac{1}{\beta^{1/2} h} \log\frac{1}{\omega h}\Bigr]\,(\bar{\mathcal{E}}^{\rm s})^2\,.
        \end{align*}
        \item \textbf{Weakly convex and high friction setting:} Let $\alpha = 0$ and $\gamma = \sqrt{32\beta}$. Then,
        \begin{align*}
            \mathtt{Err}
            &\lesssim \frac{T}{\beta^{1/2} h^2}\,(\bar{\mathcal{E}}^{\rm w})^2 + \Bigl[\frac{1}{\beta^{1/2} h} \log\frac{T}{h} + \beta^{1/2} T\Bigr]\,(\bar{\mathcal{E}}^{\rm s})^2\,.
        \end{align*}
        \item \textbf{Semi-convex setting:} 
        Let $\alpha = -\beta$ and $\gamma \leqslant \sqrt{32\beta}$.
        Then,
        \begin{align*}
            \mathtt{Err}
            &\lesssim \frac{T}{\gamma h^2}\,(\bar{\mathcal{E}}^{\rm w})^2 + \frac{1}{\gamma h}\, \Bigl[\log\frac{\beta^{-1/2} \wedge T}{h} + \beta^{1/2} T\Bigr]\,(\bar{\mathcal{E}}^{\rm s})^2\,.
        \end{align*}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition Prop:sta-ini of arXiv:2412.01645, 'Regularisation by Gaussian rough path lifts of fractional Brownian motions'] Let $(\phi_{t}^{s,x})_{t\in[s,1]}$ be given by (equation eq:flow-def of the paper), let X be a solution to the SDE (equation eq:main of the paper). Then, for any $p \geq 1$ there exists a constant $C=C( H_-, p, C_{D,p}^X, C_{S,2p}^X, \|\sigma\|_{\mathcal{C}^2}) $, such that for all $(s,t) \in [0, 1]^2_{\leq}$ we have 
    \begin{equs}
        \|X_t-\phi^{s, X_s}_t\|_{L_p(\Omega)} \leq C|t-s|^{1+\alpha H}.
    \end{equs}

