  &= 1 + \int_0^t q(s, \omega) \crochet{A(\omega_s) U(\theta_s \omega), \vun} \, ds.
\end{align*}
Consequently, by the ergodic theorem, we have the almost sure limit,
\begin{align*}
  \frac{1}{t} \ln q(t, \omega) = \frac{1}{t} \int_0^t \crochet{A(\omega_s) U(\theta_s \omega), \vun} \, ds \to \esp{\crochet{A(\omega_0) U(\omega), \vun}},
\end{align*}
which gives the desired identity thanks to","release_manifest_digest":"sha256:547a15de7d14000a51220a0067e00513ed3230b8911353c51a22ee625805ed48","revision_digest":"sha256:a0c80aee41597c6f59b0bfc575639b58b0599909d338afc5006c5fa3f7a8bc1c","source_id":"arxiv:2609.02711","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

