[Thm 2 (\cites{Hei88, NX21}) of arXiv:2608.26723, 'Extrinsic upper bounds for the harmonic mean of eigenvalues in curved manifolds'] Let $M$ be an $m(\ge 2)$-dimensional closed orientable submanifold in an $n$-dimensional Riemannian manifold $N$ of the sectional curvature $K_N \le \delta$.
	If $\delta\le 0$, we assume that $N$ is simply-connected;
	if $\delta> 0$, we assume that $M$ is contained in a convex ball of radius $\le \pi/4\sqrt{\delta}$.
	Then the first nonzero eigenvalue $\lambda_1$ of the Laplacian on $M$ satisfies
	\begin{equation}
		\lambda_1\le \frac{m}{\vol(M)}\int_M\big(\delta+|\mathbf{H}|^2\big).
	\end{equation}

	Equality holds implies that $M$ is minimally immersed in a geodesic sphere of $N$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 (Profile and surface speeds) of arXiv:2609.00501, 'Uniqueness of Finite-Time Varifold Limits for the M\"obius-Invariant Willmore Flow'] Between a normal-gauge Hopf profile evolution and its corresponding
MIWF trajectory, the following identity holds:
\begin{equation}

 \|\partial_t\gamma_t\|_{L^2(\dd s_{\gamma_t})}
 =\frac2{\sqrt\pi}
 \|\partial_tF_t\|_{L^2(\Sigma,\dd\mu_t)} .
\end{equation}

[Proposition 4 (Tropp, Chretien \& Darses) of arXiv:2606.24323, 'Conditioning of incoherent sub-dictionaries sampled from a coherent dictionary'] Let $\hat \P$ be a (discrete) probability measure on $\Delta$, $I$ the set-valued random variable with $I(\delta) = \{i:\delta_i=1\}$ and $\hol \in \R^{K\times K}$ a matrix with zero diagonal, then there exists a subset $T\subseteq [K]$, such that for all $\theta \in \R$
\begin{align*}
    \hat\P( \| D_I \hol D_I \| \geq r )&\leq  36 \cdot \hat\P\left( \max \left\{\| D_I \, D_T \hol D_{T^c} \, D_I \|, \| D_I \, D_{T^c} \hol D_{T} \, D_I \| \right\}\geq \frac{r}{2}\right) . 

\end{align*}

[Defn def:Spectral_NS+NStable of arXiv:2606.29829, ''] Let $\{(X_n(t),\Omega_n,\pi_n)\}_n$ be a sequence of reversible and irreducible continuous-time Markov chains. Here $\Omega_n$ is the state space, and $\pi_n$ is the stationary distribution of the $n$th chain $X_n(t)$. Also, let $t_{\rel}^n$ be the \emph{relaxation time} (will be defined) of the $n$th chain $X_n(t)$. A sequence $\{\mathfrak{f}_n\}_n$ of Boolean functions,
 	$\mathfrak{f}_n : \Omega_n \longrightarrow \{0, 1\}$, is said to be
 	\begin{itemize}
 		\item \emph{Noise sensitive} with respect to $(X_n(t),\Omega_n,\pi_n)$ if for all $\alpha>0$,
 		\begin{equation}
 			\lim_{n\rightarrow\infty}\cov\left(\mathfrak{f}_n(X_n(0)),\;\mathfrak{f}_n(X_n(\alpha t^n_{\rel}))\right)=0,\text{ where }X_n(0)\sim \pi_n.
 		\end{equation}
 		\item \emph{Noise stable} with respect to $(X_n(t),\Omega_n,\pi_n)$ if
 		\begin{equation}
 			\lim_{\alpha\rightarrow0}\sup_n\mathbb{P}\left(\mathfrak{f}_n(X_n(0))\neq \mathfrak{f}_n(X_n(\alpha t^n_{\rel}))\right)=0,\text{ where }X_n(0)\sim \pi_n.
 		\end{equation}
 	\end{itemize}

[Lemma 1 of arXiv:2608.26692, 'Many Facets in Random Polytopes from Product and Log-Concave Measures'] For every fixed integer $m\geq1$,
\begin{equation}
 \sup_{t\in\R}|t|^m\E_t|X-\Lambda_\mu'(t)|^m<\infty.
\end{equation}
Moreover,
\begin{equation}
 \frac{t^2\Lambda_\mu''(t)}
 {\Lambda_\mu^*(\Lambda_\mu'(t))}\longrightarrow2
 \qquad (t\to0).
\end{equation}
Finally,
\begin{equation}
 \frac{-\log\mu([x,\infty))}{\Lambda_\mu^*(x)}\longrightarrow1
 \qquad (x\uparrow x^*).
\end{equation}

