body:
[Lem 45 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Let $(F,R,\mu)$ be in $\bbF^{\circ}$.
Fix $\alpha\in (0,1]$. Suppose that there exists a constant $C=C(\alpha)\in (0,\infty)$ such that $\int_F |g^{\alpha}(x,z)-g^{\alpha}(y,z)|^2\mu(dz)\leq CR(x,y)^2$ for any $x,y,z\in F$.
Then it holds that
\begin{align}
  \|(\alpha-\Delta)^2P_th\|_{\Lip^{1}}\leq C^{1/2}t^{-3}\|h\|_{L^2(F,\mu)}, \qquad t\in (0,1],\;h\in L^2(F,\mu).
\end{align}
In particular, we have the following:
\begin{itemize}
  \item [$\rm{(i)}$]If $F$ is compact, then it holds that
  \begin{align}
     \|(\alpha-\Delta)^2P_th\|_{\Lip^{1}}\lesssim \mu(F)^{1/2}\g{c}{continuity,1}\alpha^{-1} t^{-3}\|h\|_{L^2(F,\mu)},
  \end{align}
  for $\alpha,\;t\in (0,1]$ and $h\in L^2(F,\mu)$.
  \item [$\rm{(ii)}$]If $(F,R,\mu)$ satisfies $\rm{(A2)}$, then it holds that
  \begin{align}
    \|(\alpha-\Delta)^2P_th\|_{\Lip^{1}}\lesssim \g{c}{continuity,1} \left[c_{\rm{A2}}\Gamma\left(1-\frac{s_1}{(1+s_0)\theta}\right)\right]^{-1/2}\alpha^{-(1+\frac{s_1}{(1+s_0)\theta})}t^{-3}\|h\|_{L^2(F,\mu)},
  \end{align}
  for $\alpha,\;t\in (0,1]$ and $h\in L^2(F,\mu)$.
  \item [$\rm{(iii)}$]If $(F,R,\mu)$ satisfies $\rm{(A3)}$, then it holds that
  \begin{align}
     \|(\alpha-\Delta)^2P_th\|_{\Lip^{1}}\lesssim \g{c}{continuity,1} \left[c_{\rm{A3}}\Gamma\left(1-\frac{s_1}{(1+s_0)\theta}\right)\right]^{-1/2}\alpha^{-(1+\frac{s_1}{(1+s_0)\Theta})}t^{-3}\|h\|_{L^2(F,\mu)}, 
  \end{align}
  for $\alpha,\;t\in (0,1]$ and $h\in L^2(F,\mu)$. Here, $\Theta=\frac{1+s_0-s_1}{1-(s_0-s_1)(2+s_0)}$.
\end{itemize}

[Theorem thm3_6 of arXiv:2607.26169, 'Scaling and partial universality of the height zero probability in the 2D Abelian sandpile'] Let \(U, V \subsetneq \mathbb{C}\) be regions satisfying Assumption (a:U of the paper), and assume that
    $\varphi : U \to V$ is a conformal map. Let $z \in U$ and let $w := \varphi(z) \in V$. 
It holds that 
\begin{equation*}
 f_U(z)
 = |\varphi'(z)|^2 f_V(\varphi(z)). \end{equation*}

[Proposition 17 (Minimal Cholesky factor) of arXiv:2604.22159, 'Adapted optimal transport between filtered Gaussian processes'] Let $n \geq 1$ and $A \in \mathscr{S}_+(n)$. Then there exists a unique $L \in \mathscr{L}_+(n)$ with the following properties:
\begin{enumerate}
\item[(i)] $LL^{\intercal} = A$.
\item[(ii)] If $L_{[i, i]} = 0$ then $L_{[j,i]} = 0$ for all $j \geq i$. That is, the $i$-th column $L_{[\cdot, i]}$ vanishes whenever the diagonal element $L_{[i,i]}$ does.
\end{enumerate}
We call $L$ the minimal Cholesky factor of $A$ and write $L = \mathcal{C}_{\min}(A)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma WPD-WIEJDUHFJ-HUD of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] Suppose that $m$ and $n$ are two non-negative integers. Then, there exists a bounded function $\mathfrak{f}\left( t \right)$ on $\left[ 0,T \right]$ such that
\begin{equation}
{\left\| {{{\nabla ^m}\partial _t^n}{\mathfrak{D}_{\tilde \mu }}} \right\|_{{L^p}}} \sim {\mathfrak{f}}\left( t \right)  {\sigma} ^{m + n}{{\tilde \mu }^n}{r^{1 + m - \frac{2}{p}}} , \ \ \forall \, p \geqslant 1  , \ \forall \, t \in \left[ 0,T \right] ,
\end{equation}
and
\begin{equation}
{\left\| {\sum\limits_{\xi  \in \Lambda } {{\nabla ^m}\partial _t^n{\mathbb{W}_\xi }} } \right\|_{{L^p}}} \sim  {\mathfrak{f}}\left( t \right)  {\sigma} ^{m + n}{{\tilde \mu }^n}{r^{1 + m - \frac{2}{p}}} , \ \ \forall \, p \geqslant 1 , \ \forall \, t \in \left[ 0,T \right] .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma preliminary of arXiv:2411.18775, 'Limit Theorems for the Dynamical Foundation of the Fractional Brownian Motion and Related '] Under Assumptions of Theorem~(Thm of the paper)~(i) consider the Ornstein-Uhlenbeck processes given by~(equation eq:OUprocess of the paper). Then we have
		\begin{align}
			&\mathbb{E}\left[\widetilde{U}^{k,N}_t\widetilde{U}^{k,N}_s\,|\,\mathcal{M}\right]= \frac{\sigma}{\gamma m_{k,N}}e^{-\gamma m_{k,N}|t-s|}.
			\end{align}

[Lemma lem: numerics for M 1 for 52 cards of arXiv:2605.28770, 'Cutoff profiles for conjugacy invariant random walks on symmetric groups'] We have the following approximations.
