    \item $m_{52}(186) \approx  1.101\cdot 10^{-2}$, $m_{52}(187) \approx  1.058\cdot 10^{-2}$, $m_{52}(188) \approx  1.016\cdot 10^{-2}$, $m_{52}(189) \approx  (1- 0.024)\cdot 10^{-2}$, $m_{52}(190) \approx  (1- 0.062)\cdot 10^{-2}$, $m_{52}(191) \approx  (1- 0.099)\cdot 10^{-2}$.
    \item $m_{52}(245) \approx  1.039\cdot 10^{-3}$, $m_{52}(246) \approx  (1-0.002)\cdot 10^{-3}$, $m_{52}(247) \approx  (1-0.041)\cdot 10^{-3}$.
    \item $m_{52}(303) \approx  1.021\cdot 10^{-4}$, $m_{52}(304) \approx  (1- 0.019)\cdot 10^{-4}$.
