[Theorem 3 of arXiv:2608.30736, 'Stability results for distribution-dependent stochastic Volterra equations'] Suppose that
  \begin{itemize}
	\item Assumption \ref{ass:volatility} holds,
	\item all pairs of kernels $(K_{b,n}, K_{\sigma,n})$, $n \in \bN$, and $(K_{b}, K_{\sigma})$ satisfy Assumption~\ref{ass:kernel} using the same constants $\gamma, \epsilon, L$,
	\item \eqref{eq:MVSVE_2} and \eqref{eq:MVSVE_2app} have unique strong $L^p$-solutions for each $x \in \bR^d$ and $n \in \bN$, respectively, for $p\geq \eta$ and $p>2+\frac{4}{\epsilon}$,
    \item for any compact subset $K \subset \bR^d$ and $\mathcal K \subset \mathcal P_\eta(\bR^d)$
    \begin{equation*}
      \lim_{n \to \infty} \sup_{t \in [0,T]} \sup_{x \in K} \sup_{\mu \in \mathcal K} |\sigma_n(t,x,\mu)-\sigma(t,x,\mu)|+|b_n(t,x,\mu)-b(t,x,\mu)|=0.
    \end{equation*}
    Additionally
    \begin{equation*}
      \sup_{t \in [0,T]} \int_0^t |K_{b,n}(s,t)-K_b(s,t)|^{1+\epsilon} \dd s \to 0 \text{ as } n \to \infty
    \end{equation*}
    and
    \begin{equation*}
      \sup_{t \in [0,T]} \int_0^t |K_{\sigma,n}(s,t)-K_\sigma(s,t)|^{2+\epsilon} \dd s \to 0 \text{ as } n \to \infty.
    \end{equation*}
  \end{itemize}
  Then
  \begin{align*}
    \lim_{n \to \infty} \sup_{x \in K} \bE\big [\max_{t \in [0,T]} |X_n(t,x)-X(t,x)|^2\big] = 0
  \end{align*}
  for every compact $K \subset \bR^d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lm:a1 of arXiv:2606.12143, 'Continuous stochastic flows driven by white noise and their duals'] Suppose that $(\sigma,b)$ satisfy Assumption~(assu:H of the paper) and conditions~(item:1a of the paper), (item:1b of the paper), (item:2c of the paper), and (item:2d of the paper). Then there exists a sequence $(\sigma_n,b_n)_{n\ge1}$ such that, for any $T\ge r$,
\begin{enumerate}[label=(\roman*), nosep]
    \item (equation eq:assume_sig_b of the paper) holds for any compact set $K \subset {\mathbb R}$;
    \item (equation eq:assume_lin_bound of the paper) holds for all $x\in {\mathbb R}$ and $t\in [r,T]$ with constants $K_b'$ and $K_\sigma'$ independent of $n$;
    \item for each $n$, $(\sigma_n,b_n)$ satisfies Assumptions~(assu:H of the paper) and~(assu:A of the paper) for $t\in [r,T]$, and $\sigma_n$ has the same sign as $\sigma$.
\end{enumerate}

