[Proposition 11 of arXiv:2604.11921, 'Replica symmetry up to the de Almeida--Thouless line in the Sherrington--Kirkpatrick model'] \label[proposition]{prop:hard-small}
If
\begin{equation}
\beta^2(1-q)\le 1,
\end{equation}
then  $\E[m_t^2]\le t$ for all $t\in[q,1]$.

[Lemma Phi-AA-subseq of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Let $\{n_{k}\}_{k\geq 0}$ be any strictly increasing
sequence with $n_{k}\rightarrow \infty $. Then there exists a further
subsequence (still denoted $\{n_{k}\}_{k\geq 0}$) and a map 
\begin{equation}
\Phi ^{\ast }:(0,1)\rightarrow (0,1)  
\end{equation}
such that for every $0<\delta <\tfrac{1}{2}$, 
\begin{equation}
\sup_{x\in \lbrack \delta ,\,1-\delta ]}\left\vert \Phi _{n_{k}}(x)-\Phi
^{\ast }(x)\right\vert \longrightarrow 0\qquad (k\rightarrow \infty ).

\end{equation}
In particular, $\Phi ^{\ast }$ is continuous and increasing on $(0,1)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 3 (Conditional-KL Representation of the Sinkhorn Ambiguity Set) of arXiv:2608.22746, 'Generative Neural Networks for Sinkhorn Distributionally Robust Hypothesis Testing'] The ambiguity sets based on Sinkhorn discrepancy with $\epsilon > 0$ are equivalent to 
    \begin{equation} 
        \mathbb{B}_{\bar{\rho}_k}(\mathbb{P}_k^{\epsilon}) := \left\{ \mathbb{Q}: \inf_{\gamma\in\Gamma(\widehat{ \mathbb{P}}_k, \mathbb{Q})} \, \,  \mathbb{E}_{\boldsymbol{x} \sim \widehat{\mathbb{P}}_k} \Big [ \mathcal{D}_{\mathrm{KL}} (\gamma_{\boldsymbol{x}}\| \mathcal{K}_{\boldsymbol{x}, \epsilon})\Big ] \le \bar{\rho}_k/\Reg \right\}, \quad \forall k \in \mathbb{K}, 
    \end{equation}
    where $\bar{\rho}_k := \rho_k +\Reg \mathbb{E}_{\boldsymbol{x}\sim \widehat{\mathbb{P}}_k}\Big [ \log\, \int_{\mathbb{R}^d}e^{-c(\boldsymbol{x}, \boldsymbol{z})/ \Reg} \diff \boldsymbol{z} \Big]$, probability density $\mathrm{d} \mathbb{P}_k^{\epsilon}(\boldsymbol{z}) := \mathbb{E}_{\boldsymbol{x} \sim \widehat{\mathbb{P}}_k}\left[ \diff \mathcal{K}_{\boldsymbol{x}, \epsilon}(\boldsymbol{z}) \right]$, 
    \begin{equation*}
        \diff \mathcal{K}_{\boldsymbol{x}, \epsilon}(\boldsymbol{z}) := \frac{e^{-c(\boldsymbol{x}, \boldsymbol{z}) / \epsilon}  }{\int_{\mathbb{R}^d} e^{-c(\boldsymbol{x}, \boldsymbol{u}) / \epsilon} \cdot \diff \boldsymbol{u}} \cdot \mathrm{d} v(\boldsymbol{z}). 
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:LA of arXiv:2609.04092, 'Short character sums of inhomogeneous polynomials'] {Dav59}}]
     Let $P_1,...,P_n\in \mathbb{R}[X_1,...,X_n]$ be linear forms given by $P_i=a_{i,1}X_1+\cdots + a_{i,n}X_n$ such that $a_{i,j}=a_{j,i}$. Let $A>1$ be real. Define
        \begin{align*}
            U(Z) = |\{(u_1,...,u_n)\in \mathbb{Z}^{n}: |u_i|<AZ \text{ and } \|P_i(u_1,...,u_n)\|<A^{-1}Z, \ 1 \leq i \leq n\}|.
        \end{align*}
    Then for $0<Z'\leq Z\leq 1$, we have $U(Z)/U(Z') \ll (Z/Z')^n$.

