[Theorem 3 of arXiv:2605.25715, '2605.25715'] Consider
$$
L^{A,\mathbf{G}}f:=\frac12 \mathrm{trace}(A\nabla^2 f) +\langle \mathbf{G},\nabla  f\rangle, \quad f \in C_0^{\infty}(\mathbb{R}^d),
$$
as in \eqref{thegenerator}, and suppose that
\begin{eqnarray}
\mathbf{G} =A\nabla \Phi + \mathbf{B}, \quad \text{with}\ \Phi \in H^{1,2}_{loc}(\mathbb{R}^d) \cap L^{\infty}_{loc}(\mathbb{R}^d), \ \mathbf{B} \in L^2_{loc}(\mathbb{R}^d, \mathbb{R}^d).
\end{eqnarray}
Let $\mu=\rho\,dx$, where $\rho=\exp(2 \Phi)$. Then, it holds:
\begin{itemize}
\item[(i)]
$\mu$ is an infinitesimally invariant measure for $(L^{A,\mathbf{G}}, C_0^{\infty}(\mathbb{R}^d))$, if and only if $
{\mathrm{div}}_{\mu}(\mathbf{B})=0$.
\item[(ii)] 
\begin{equation} 
\mathrm{div}_{\mu}(\mathbf{B})=0\quad \Longleftrightarrow \quad \int_{\mathbb{R}^d}\big (\langle \nabla \Phi, \mathbf{B} \rangle  \varphi -\frac 12\big \langle  \mathbf{B}, \nabla \varphi \big \rangle\big ) \,dx = 0 \quad \forall \varphi \in C_0^{\infty}(\mathbb{R}^d).
\end{equation}
In particular, if $\mathbf{B}$ is weakly differentiable, then using integration by parts in \eqref{equidivfre}, $\mathrm{div}_{\mu}(\mathbf{B})=0$ is equivalent to 
$$
\langle \nabla \Phi, \mathbf{B} \rangle+\frac12\mathrm{div}\mathbf{B}=0.
$$
In general, in the case where $\mathbf{B}$ is not necessarily weakly differentiable, \eqref{equidivfre} implies 
\begin{equation} 
\mathrm{div}_{\mu}(\mathbf{B})=0\quad\text{and} \quad  \mathrm{div}_{dx}(\mathbf{B})=0\quad \Longrightarrow \quad \langle \nabla \Phi, \mathbf{B} \rangle = 0 
\end{equation}
and 
\begin{equation} 
\mathrm{div}_{dx }(\mathbf{B})=0\quad \text{and} \quad \langle \nabla \Phi, \mathbf{B} \rangle = 0 
\quad \Longrightarrow \quad \mathrm{div}_{\mu}(\mathbf{B})=0,
\end{equation}
and
\begin{equation} 
\mathrm{div}_{\mu}(\mathbf{B})=0\quad\text{and} \quad  \langle \nabla \Phi, \mathbf{B} \rangle = 0 
\quad \Longrightarrow \quad \mathrm{div}_{dx}(\mathbf{B})=0. 
\end{equation}\\
Moreover, it follows from \eqref{equidivfre3} that if the decomposition of  
\begin{eqnarray}
\widetilde{\mathbf{G}} = \nabla \Phi + \mathbf{B},
\end{eqnarray}
(where $\mathbf{B}=\mathbf{G} -A\nabla \Phi $ according to \eqref{graddec}) is an OHHD as in Definition \ref{helmdefn}, then it is a WHHD. Conversely, it follows from \eqref{equidivfre} that if the decomposition in \eqref{propstrohelm:eqOHHD} is a WHHD, then it is only an OHHD if either $\mathrm{div}_{dx}(\mathbf{B})=0$ or $\langle \nabla \Phi, \mathbf{B} \rangle = 0$, in which case both are zero, cf. \eqref{equidivfre2} and \eqref{equidivfreadditi}.
\end{itemize}

[Proposition 3 of arXiv:2608.11071, 'Scaling Laws for Majority-based Opinion Dynamics in the Presence of Stubborn Agents'] The parametric form of the boundary $\Gamma_{\text{crit}}^k$ is $$\{(\gamma_0(w),\gamma_1(w)), w\in (w_{\min}, w_{\max})\},$$ where
    \begin{align}
        &\nonumber \gamma_1(w)=w - \frac{P_k(w)(P_k(w)+P_{k}(1-w))}{P'_{k}(1-w)P_k(w)+P_k'(w)P_k(1-w)},
    \end{align}
    $\gamma_0(w)=\gamma_1(1-w)$, $w_{\min}$  solves $\gamma_0(w_{\min})=0$, and $w_{\max} = 1 - w_{\min}$. Here, $P'_k$ denotes differentiation with respect to the argument of $P_k$. 
    Furthermore, we have $\gamma_0(1/2)=\gamma_1(1/2)=\gamma_k^*$, where
    \begin{align}
        \gamma^*_{k} = \frac{1}{2}+\frac{1}{4k}-\frac{2^{2k}}{4k\binom{2k}{k}},
    \end{align}
    is the point at which  $\Gamma_{\text{crit}}^k$ intersects the line $\gamma_0=\gamma_1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

