[Proposition 22 (Panter--Dite optimal point density and the high-rate law \citep{panter1951quantization}) of arXiv:2608.25188, 'Transforms for LLM Quantization:\\ The Great Inversion and Format Co-Design'] Assume the high-resolution regime of \Cref{lem:bennett}. For a \emph{fixed-length} (uncoded) quantizer of $R$ bits, with $p$ smooth and light-tailed enough that $\int p^{1/3}$ converges and overload negligible at the rates considered, ($L=2^R$ points, $\int\lambda=L$), minimizing Bennett's integral over $\lambda$ under the count constraint gives the optimal density $\lambda^\star(x)\propto p(x)^{1/3}$ and distortion
\begin{equation}
D_{\mathrm{fl}} \;\approx\; \frac{1}{12}\Big(\int p(x)^{1/3}dx\Big)^{3}\,2^{-2R}.
\end{equation}
For an \emph{entropy-constrained} (variable-length) quantizer, minimizing $D$ at fixed \emph{index entropy} $H$ instead makes the optimal density \emph{uniform} ($\lambda^\star$ constant) \citep{gish1968asymptotically}, giving $D_{\mathrm{ec}}\approx \tfrac{1}{12}2^{2h(X)}2^{-2H}$, where $h(X)$ is the differential entropy (\Cref{sec:rate}).

[Corollary 38 of arXiv:2608.18075, '2608.18075'] Fix any finite collection of moment orders and polynomial powers.  There
are one base weight $V_*$, an integer $M_*$, and $N_*<\infty$ such that,
for every $N\ge N_*$, the block $\tau=Nt_*$ admits a constant
$C_\tau<\infty$ for which, with
\begin{align*}
 G_*(w,[\mathsf p])=\|w\|_{C^\beta}^{M_*}+\|\mathsf p\|_{H^1}^{M_*},
\end{align*}
where both norms are extended by $+\infty$ off their natural domains,
\begin{align}
 P_\tau^{\rm base}V_*&\le\theta V_*+C_\tau,
 \qquad 0<\theta<1,\notag\\
 P_\tau G_*&\le C_\tau V_*.

\end{align}
Thus
\begin{align*}
 W_0=V_*+\varepsilon G_*:
 H^b\times\PP(H)\longrightarrow[1,\infty]
\end{align*}
is lower semicontinuous, finite on
$\mathsf D_0=C^\beta\times\PP(H^1)$, and has compact finite sublevel
sets in $H^b\times\PP(H)$.  For sufficiently small $\varepsilon>0$,
\begin{align}
 P_\tau W_0\le\varrho_0W_0+C_\tau,
 \qquad 0<\varrho_0<1,

\end{align}
in the extended valued sense.  Moreover,
\begin{align}
 P_\tau W_0(w,[\mathsf p])
 \le C_\tau(1+V_*(w))<\infty
 \qquad\text{for every }(w,[\mathsf p])\in H^b\times\PP(H).

\end{align}
Consequently $P_\tau(z,\mathsf D_0)=1$ for every
$z\in H^b\times\PP(H)$.

[Lemma lem:sde_kin_dens of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] Let Assumptions (assump:hor of the paper) and (assum:sigma_0 of the paper) be in force. 
Setting
\begin{equation}
\beta(t,x) : = B x +  \left( 
\begin{matrix}
\beta_0(t,x)  \\
{\bf 0}_{(d - d_0) \times 1}
\end{matrix}
\right)  , \quad \sigma(t,x) : = \left( 
\begin{matrix}
\sigma_0 (t,x)  \\
{\bf 0}_{(d - d_0) \times 1}
\end{matrix}
\right), \qquad (t,x)\in(0,T)\times\mathbb{R}^d,
\end{equation}
with $\beta_0\in L^{\infty}((0,T)\times \mathbb{R}^d)$, we have:
\begin{itemize}
\item[(i)] SDE$(\beta,\sigma)$ is weakly well-posed (see Definition (def:well_posed_lin of the paper)). For any $(s,x)\in [0,T)$, the law of the (unique in law) solution to SDE$(\beta,\sigma;s,\delta_x)$, at time $t\in (s,T)$, has a density $p(s,x; t, \cdot)$.

\item[(ii)] 
There exists $C>0$, depending only on $\| \sigma_0 \|_{L^{\infty}_{T}\mathcal{C}^{\alpha}_B(\mathbb{R}^d)}$, $\| \beta_0 \|_{L^{\infty}((0,T)\times \mathbb{R}^d)}$, $\lambda$, $T$ and $B$, such that
\begin{equation}
 |  \nabla^{m}_{x^0} p(s,x;t,y)  |  \leq C (t-s)^{-\frac{m}{2}} \, p_{\mathscr{K}_{2\lambda}}(t-s, x  , y).

\end{equation}

for any $0\leq s < t < T$, any $x,y\in\mathbb{R}^d$ and $m=0,1,2$. Here, $p_{\mathscr{K},\cdot}$ is the Gaussian density in (equation eq:kol_dens of the paper).

\item[(iii)] Furthermore, for any $s\in[0,T)$ and $\nu\in\mathcal{P}(\mathbb{R}^d)$, the flow of time-marginal densities of the solution to SDE$(\beta,\sigma;s,\nu)$ is the unique (weak) solution to FP$(\beta,\sigma;s, \nu)$ (see Definition (def:sol_lin_fp of the paper)). In particular, for any $x\in\mathbb{R}^d$, $(p(s,x; t, \cdot))_{t\in(s,T)}$ is a density solution to FP$(\beta,\sigma;s, \delta_x)$.
\end{itemize}

[Theorem 21 of arXiv:2511.13404, 'Asymptotic stability and mean ergodicity of Feller processes on Polish spaces'] Let $\mathfrak{F}=\{f\in B(\X):|f(x)|\le1+V(x)\}$ satisfy Hypothesis $(\mathbf{H_2})$. Then the  following three statements are equivalent: 
		\begin{itemize}
			\item [(\runum{1})] $\Phi$ admits a unique invariant measure $\mu\in\mathcal{P}(\X)$ with $\mathfrak{F}\subset L^1(\mu) $ and for all $x\in\X$,
            \begin{equation*}
                \lim_{t\to\infty}d_V(Q_t^*\delta_x,\mu)=0.
            \end{equation*}
			\item[(\runum{2})] $\Phi$ is uniformly Ces\`aro eventually continuous with respect to $\mathfrak{F}$ on $\X$, and there exists $z\in\X$ such that $\Phi$ satisfies the lower bound condition \eqref{eq:LBC_Q} at $z$.
            \item[(\runum{3})] There exists $z\in\X$ such that $\Phi$ is uniformly Ces\`aro eventually continuous with respect to $\mathfrak{F}$ at $z$ and satisfies the lower bound condition \eqref{eq:LBC_Q} at $z$.
 		\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 23 of arXiv:2609.04139, 'The conformally invariant metric on CLE$_4$ II:\\ existence of geodesics'] There is a universal constant $C > 0$ such that the following is true: Let $K_1, K_2 \subset \overline\BD$ be two disjoint, connected, simply connected, and compact subsets such that $\partial \BD \not\subset K_1 \cup K_2$. Then the extremal distance in $\BD$ between $K_1$ and $K_2$ is at most 
    \begin{equation}
        \left.C\middle/\log\left(\frac{\diam(K_1) \wedge \diam(K_2)}{\dist(K_1, K_2)} \vee 1\right)\right., 
    \end{equation}
    where $\diam$ and $\dist$ denote Euclidean diameter and distance, respectively, with the convention that the bound is $+\infty$ when the logarithm vanishes. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition MBBM exceeding particles num for a subset of arXiv:2606.19207, 'Extrema of cooling branching Brownian motion and related Gaussian fields'] Let $\{\xi_\varepsilon^{\alpha,z}(t)\colon t\geq0,\ z\in V_\varepsilon\}$ be the MBBM defined in (equation eqM: MBBM of the paper), and recall $A_\alpha(\cdot)$ from (equation eqIntroduction: A(t) of the paper). Fix $T_r\geq s_0$, with $s_0$ as in Lemma~(lemma: covariance estimate for MBBM of the paper), and assume that $T_r=N_r\log 2$ for some $N_r\in\mathbb{Z}_+$. Then there exist constants $C,c>0$ and $T_*,\lambda_*>0$ such that, for every $N\in\mathbb{Z}_+$ with $T:=N\log 2\geq T_*$ and $\varepsilon:=2^{-N}$, every subset $\Lambda\subset V_\varepsilon$, and every $\lambda\geq\lambda_*$,
	\begin{equation}
		\mathbb{P}\Bigl(
		\max_{z\in\Lambda}\xi_\varepsilon^{\alpha,z}(T+T_r)
		\geq A_\alpha(T+T_r)+\lambda-n
		\Bigr)
		\leq Ce^{-c(\lambda-n)},
		\qquad n\in\mathbb{Z}_+,\quad n\leq\lambda,
	\end{equation}
	and
	\begin{equation}
		\begin{aligned}
			&\mathbb{P}\Bigl(
			\max_{z\in\Lambda}\xi_\varepsilon^{\alpha,z}(T+T_r)
			\geq A_\alpha(T+T_r)+\lambda-n
			\Bigr)\\
			&\quad\leq
			Ce^{-c(\lambda+n)}
			+C\lvert\Lambda\rvert
			\exp\bigl\{-d(T+T_r)-c\lambda+c(T+T_r)^\alpha(n+1)\bigr\},
			\qquad n\in\mathbb{Z}_+.
		\end{aligned}
	\end{equation}

