[Theorem 5 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] {\em (Wiener-Khintchine)}
    Let $(\mathbf{x}_t)_{t\geq 0}$ be a (weakly) stationary process. Then,
    $AC(\tau)$ is a autocorrelation function of some (weakly) stationary process $\mathbf{x}_t$ if and only if there exists a function $F(\omega)$ having the properties of a distribution function on $(-\infty,\infty)$ such that for all $\tau\in\R$
\begin{align*}
    AC(\tau)=\int_\R e^{i\omega\tau}~\txtd F(\omega),
\end{align*}
where $F(\omega)$ is called the spectral distribution of $(\mathbf{x}_t)_{t\geq 0}$. Moreover, if 
$$\int_\R AC(\tau)~\txtd \tau<\infty,$$
we have
\begin{align*}
    F(\omega)=\int_{-\infty}^\omega \frac{S_\mathbf{x}(\theta)}{V(0)}~\txtd\theta.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Propn 18 of arXiv:2604.27205, 'An Analysis of the Diaconis-Holmes-Neal Markov Chain Sampler Under Generalized Unimodal Un'] The probability that the path, as constructed in Lemma~\ref{step1}, has exactly $cn$ steps is bounded below by
        \begin{equation}
            P' \geq \frac{\tilde{\tilde{c}}m_{j^*}(n)}{z'}, 
        \end{equation}
        \noindent where $\tilde{\tilde{c}}$ is a constant. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor l:meas3 of arXiv:2607.18194, 'Temperature chaos in directed polymers'] Fix $(s,x;t,y)\in\mathbb{R}^{4}_{\uparrow}$ and $s'<t'$ with $[s',t']\subset[s,t]$.
    For any Borel set $S\in \mathcal{B}(C([s,t]))$ and any $z<w$, define
    \begin{align*}
        \mathcal{Z}^S_{B(z,w)^c} &= \mathcal{Z}^S_{B(z,w)^c}(s,x;t,y)\\
        &\coloneqq  \mathcal{Z}_\beta^\xi(s,x;t,y)\cdot \mathbb{P}_{\beta,(s,x),(t,y)}^\xi\left(
            S\cap \{X(r)\in [z,w]^c\text{ for all }r\in[s',t']\}
        \right).
    \end{align*}
    Then $\mathcal{Z}^S_{B(z,w)^c}$ is $\mathcal{F}_{B(z,w)^c}$-measurable.

