body:
[Lemma 13 of arXiv:2608.31070, 'Sub-Laplacians on Compact Lie Groups: Heat Kernels, Distance, and Zeta Determinants'] Identify $\Lambda^2\pLie$ with $\mathfrak{so}(\pLie)$ by \eqref{eq:sp-J} and equip $\mathfrak{so}(\pLie)$ with the metric $\langle A,C\rangle=-\tfrac12\Tr(AC)$. We use the Lebesgue measure induced by this metric on $\mathfrak{so}(\pLie)$ and the normalized Haar measure on $\mathrm O(m)$. Let $\Omega$ be regular, with $\sigma_1>\cdots>\sigma_\kappa>0$. There are nonzero constants $c_{2\kappa}^{\circ}$ and $c_{2\kappa+1}^{\circ}$, fixed by these measure normalizations, such that
		\begin{align}
			q_1^{\mathrm{free}}(0,\Omega)
			&=
			\frac{c_{2\kappa}^{\circ}}
			{\displaystyle\prod_{j<k}(\sigma_j^2-\sigma_k^2)}
			\det\!\left[\widehat w^{(2j-2)}(\sigma_k/2)\right]_{j,k=1}^{\kappa},
			&&m=2\kappa,
			\\
			q_1^{\mathrm{free}}(0,\Omega)
			&=
			\frac{c_{2\kappa+1}^{\circ}}
			{\displaystyle(\prod_j\sigma_j)
				\prod_{j<k}(\sigma_j^2-\sigma_k^2)}
			\det\!\left[\widehat w^{(2j-1)}(\sigma_k/2)\right]_{j,k=1}^{\kappa},
			&&m=2\kappa+1,

		\end{align}
		where $w(a)=(a/2)/\sinh(a/2)$ is the function defined in \Cref{sec:preliminaries}, and
		\begin{equation}
			\widehat w(x):=\int_{\mathbb R}e^{-iax}w(a)\,\mathrm da
			=\pi^2\operatorname{sech}^2(\pi x).
		\end{equation}

