body:
[Lemma 11 of arXiv:2608.13235, 'Mixing Properties of Random Laguerre Tessellations'] Let $k \in \n$. There exist measurable mappings $\pi_n : \mathsf{N}(\R^k)\rightarrow \R^k$, $n \in \n$, such that for any $\varphi \in \mathsf{N}(\R^k)$ we have $\varphi = \sum_{n = 1}^{\varphi(\R^k)}\delta_{\pi_n(\varphi)}$. In particular, the mappings $\Pi_n: \R^k \times \mathsf{N}(\R^k) \rightarrow (\R^k )^{n+1}$,
    \begin{equation}
        \Pi_n(x,\varphi)\coloneqq(x,\pi_1(\varphi),\dots,\pi_n(\varphi)),
    \end{equation}
    are measurable for all $n \in \n$ w.r.t. $\borel(\R^k) \otimes \mathcal{N}(\R^k)$ and $\borel((\R^k)^{n+1})$.

[Theorem thm:decode of arXiv:2608.01253, 'The pseudo-quantum representation of \\finite reversible Markov chains'] Let $Q$ be a finite irreducible reversible generator, with all objects defined from
$Q,\nu,\Lambda$ as in (sec:setup,sec:dilation of the paper). For $s=\Lambda t$,

\begin{equation}
\widehat T_t=e^{t\widehat Q^{T}}=e^{-s}\,B^{-1}W_sB,

\end{equation}

and consequently, for every initial probability law $\pi_0$,

\begin{equation}
\pi_t=T_t\pi_0=\Gamma\!\bigl(e^{-s}\,B^{-1}W_sB\,\widehat\pi_0\bigr),\qquad
s=\Lambda t.

\end{equation}

[Conjecture conj1 of arXiv:2411.19163, '\bfseries Random polytopes in convex bodies:\\ Bridging the gap between extremal container'] Let $m\in\mathbb{N}$. For $i\in\{1,\dotsc,m\}$ let $K_i\subset \mathbb{R}^{d_i}$ be a convex body whose boundary is twice differentiable with positive Gaussian curvature everywhere and such that $\operatorname{Vol}_{d_i}(K_i) = \operatorname{Vol}_{d_i}(B_2^{d_i})$. Consider the product $K=K_1\times\ldots\times K_m\subset \mathbb{R}^d$ with $d=d_1+\ldots+d_m$, and let $\mathcal{P}_{n,d}(K)$ with $n\geq d+1$ be the convex hull of $n$ independent and uniformly distributed random points in $K$. We conjecture that
    \begin{equation*}
        \mathbb{E} f_{j}(\mathcal{P}_{n,\operatorname{bd}}(K)) {\asymp}   \mathbb{E} f_{j}(\mathcal{P}_{n,\operatorname{bd}}(Z_{\operatorname{bd}})) \qquad \text{for $j\in\{0,\dotsc,d-1\}$,}
    \end{equation*}
    and
    \begin{equation*}
        \operatorname{Vol}_d(K) - \mathbb{E} \operatorname{Vol}_{d}(\mathcal{P}_{n,\operatorname{bd}}(K)) {\asymp} \operatorname{Vol}_d(Z_{\operatorname{bd}}) - \mathbb{E} \operatorname{Vol}_{d}(\mathcal{P}_{n,\operatorname{bd}}(Z_{\operatorname{bd}})).
    \end{equation*} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Definition 17 of arXiv:2604.19200, 'Stochastic $\Sigma$-convergence in Orlicz setting and Applications'] A function $u\in L^{\Phi}(Q\times \Omega ;\mathfrak{X}_{A}^{\Phi})$ 
			 is said to be admissible if the trace function $(x,\omega
		)\mapsto u(x,T(x/\varepsilon _{1})\omega ,x/\varepsilon _{2})$
			(denoted by $u^{\varepsilon }$), from $Q\times \Omega $ to $
		\mathbb{C}$, is well-defined as an element of $L^{\Phi}(Q\times \Omega )$ 
		 and satisfies the following convergence result: 
		\begin{equation*}
			\iint_{Q\times \Omega } \Phi\left(\dfrac{\left\vert u^{\varepsilon }\right\vert}{\delta}\right) dxd\mu
			\rightarrow \iint_{Q\times \Omega} \pounds_{A}\int \Phi\left(\dfrac{\left\vert u
				\right\vert}{\delta}\right) dy dxd\mu  \text{\ \emph{as} }\varepsilon \rightarrow 0\text{,
			}  
		\end{equation*}
		for all $\delta>0$.

[Thm eq:B2_0 of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] Let $k_i > -\frac12$, $1 \le i \le d$. Then for $f$ being a polynomial of degree at most $n$ on ${\mathbb V}_0^{d_1,d_2}$, 
\begin{align}
 \sum_{1 \le i< j \le d_1} & \left \| \frac{1}{\sqrt{1-|\bm y|}}  D_{i,j}^{(\bm x)} f \right \|_{{\boldsymbol{\kappa}}}^2   + 
  \sum_{1\le i< j \le d_2} \left\| (\partial_{y_j} - \partial_{y_j}) f \right\|_{{\boldsymbol{\kappa}}} ^2 \\
    & + 
   \sum_{i=1}^{d_2} \left \| \sqrt{y_i  (1-|\bm y|)}  \partial_{y_i} f\right\|_{{\boldsymbol{\kappa}}} ^2 
   \le   n(n+ |{\boldsymbol{\kappa}}| + d_1 + d_2-1)\|f\|_{{\boldsymbol{\kappa}}}^2. \notag
\end{align}
Moreover, the inequality is sharp in the sense that the equality is attainable by some polynomial of degree $n$, and 
so are the next two inequalities,
\begin{align}
 \sum_{1 \le i< j \le d_1}  \left \| \frac{1}{\sqrt{1-|\bm y|}}  D_{i,j}^{(\bm x)} f \right \|_{{\boldsymbol{\kappa}}}^2   
    & +   \sum_{i=1}^{d_2} \left \| \sqrt{y_i  (1-|\bm y|)}  \partial_{y_i} f\right\|_{{\boldsymbol{\kappa}}} ^2 \\
    & \le   n(n+ |{\boldsymbol{\kappa}}| + d_1 + d_2-1)\|f\|_{{\boldsymbol{\kappa}}}^2, \notag
\end{align}
\begin{align}
  \sum_{1\le i< j \le d_2} \left\| (\partial_{y_j} - \partial_{y_j}) f \right\|_{{\boldsymbol{\kappa}}} ^2 & + 
   \sum_{i=1}^{d_2} \left \| \sqrt{y_i  (1-|\bm y|)}  \partial_{y_i} f\right\|_{{\boldsymbol{\kappa}}} ^2 \\
  & \le   n(n+ |{\boldsymbol{\kappa}}| + d_1 + d_2-1)\|f\|_{{\boldsymbol{\kappa}}}^2. \notag
\end{align}

[Lemma local-mean-gradient-refinement of arXiv:2609.03858, 'High-Dimensional Learning Dynamics of \\ Attention-Indexed Models'] Under the conditions of Theorem (theo:untied-SGD of the paper), fix \(T>0\) and let \(J\) be a
stopping time satisfying (equation eq:stopping-time of the paper). Set $N_T:=\left\lfloor\frac{Td}{\alpha_d}\right\rfloor$ and $b_{\mathcal K}^{(n)}:=\left(b_k^{(n)}\right)_{k\in\mathcal K}$,
where \(b_k^{(n)}\) is defined in Lemma (lemma:finite-dimensional-Stein-untied of the paper). Then there exist
constants $C_{\rm tr}=C_{\rm tr}(T,\gamma,C_*,\mathfrak D)
<\infty,c_{\rm tr}=c_{\rm tr}(T,\gamma,C_*,\mathfrak D)
>0,C_b=C_b(C_*,\mathfrak D,\mathcal C,\mathcal L,K,L)<\infty,
c_0^\star=c_0^\star(T,\gamma,C_*,\mathfrak D)
>0$ such that, whenever \(c_0\le c_0^\star\),
\begin{equation}
\lim_{d\to\infty}\mathbb P\left(\sup_{0\le n<N_T\wedge J}
\left[\|b_{\mathcal K}^{(n)}\|-C_{\rm tr}e^{-c_{\rm tr}\alpha_dn}\right]_+>\frac{C_b}{\sqrt d}
\right)=0.

\end{equation}

