[Prop t:AJRS-Z-scaling of arXiv:2607.18194, 'Temperature chaos in directed polymers'] {AJRS22}}]
    Recall
    the families of measure-preserving automorphisms of $(\Xi,\mathcal{F},\mathbb{P})$ defined in (equation e:automorphism-induced of the paper).
    The following statements are true.
    \begin{enumerate}[label={\rm(\roman*)}]
        \item\textup{(Translation).}
        For each $(u,z)\in\mathbb{R}^2$, there exists an event $\mathsf{T}(u,z) \subset \Xi$ with 
        $\mathbb{P}(\mathsf{T}(u,z))=1$ such that on $\mathsf{T}(u,z)$, for all $(s,x;t,y)\in\mathbb{R}^{4}_{\uparrow}$ and all $\beta\geqslant0$,
        \begin{align*}
            \mathcal{Z}_\beta(s+u,x+z;t+u,y+z) \circ \mathcal{T}_{-u, -z}
            = \mathcal{Z}_\beta(s,x;t,y).
        \end{align*}
        \item\textup{(Shearing).}
        For each $(r,\nu)\in\mathbb{R}^2$, there exists an event $\mathsf{S}(r,\nu) \subset \Xi$ with $\mathbb{P}(\mathsf{S}(r,\nu))=1$ such that on $\mathsf{S}(r,\nu)$, for all $(s,x;t,y)\in\mathbb{R}^{4}_{\uparrow}$ and all $\beta\geqslant0$,
        \begin{align*}
            e^{\nu(y-x) + \frac{\nu^2}{2}(t-s)}\mathcal{Z}_\beta(s,x+\nu(s-r); t, y+\nu(t-r))
            \circ \mathcal{S}_{r,-\nu}
            = \mathcal{Z}_\beta(s,x;t,y).
        \end{align*}

        \item\textup{(Diffusive scaling).}
            For each $\lambda>0$, there exists an event $\mathsf{D}(\lambda) \subset \Xi$ with $\mathbb{P}(\mathsf{D}(\lambda))=1$ such that on $\mathsf{D}(\lambda)$,
            for all $(s,x;t,y)\in\mathbb{R}^{4}_{\uparrow}$ and all $\beta\geqslant0$,
            \begin{align*}
                \lambda 
                \mathcal{Z}_{\beta/\sqrt{\lambda}}(\lambda^2s,\lambda x; \lambda^2 t, \lambda y)
                \circ \mathcal{D}_{\lambda^{-2}, \lambda^{-1}} = 
                \mathcal{Z}_\beta(s,x;t,y).
            \end{align*}
    \end{enumerate}
    In the above three equalities, $\mathcal{Z}_\beta(s,x;t,y)$ is regarded as a real-valued function of the white noise, $\xi \mapsto \mathcal{Z}^\xi_\beta(s,x;t,y)$.
    This is why we use the composition notation $\circ$. (Proof in the paper; no proof environment follows the statement in the TeX.)

