[Lemma lem:chapman_kolmogorov of arXiv:2608.11603, 'Continuous-time directed polymers to the Critical SHF via moments'] {}
	For $h, h' \in C_{c}(\mathbb{R}^2),m \geqslant 1$ and $s < t < u$, the following holds:
	\begin{equation*}
		\lim_{\ell \to \infty}\lim_{\varepsilon \to 0}\mathbf{E}\Big[\Big\langle h, \Big(\mathcal{Z}^{\theta,\varepsilon}_{s,t} \bullet_{\ell} \mathcal{Z}^{\theta,\varepsilon}_{t,u} - \mathcal{Z}^{\theta,\varepsilon}_{s,u}\Big) h' \Big\rangle^{2m} \Big] = 0 \, .
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Thm-generalized KB of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Suppose (Hypo-generalized KB of the paper) holds. Let $\nu_{T}^{x_0}$ be defined by (equation eq:approx_measures of the paper) for the fixed initial point $x_0 \in E$ given in Definition (Locally Feller definition of the paper). Assume the following conditions are satisfied:
		\begin{enumerate}[label={{\bf (\arabic*)}},leftmargin=0.79cm]\setlength\itemsep{0.2em}
			\item \textbf{$($Weak Convergence$)$} There exist a sequence $T_n\to\infty$ and a probability measure $\nu\in\mathbf{P}(E_{\widetilde{d}_E})$ such that $\nu_{T_n}^{x_0} \to \nu$ weakly in $\mathbf{P}(E_{\widetilde{d}_E})$ as $n\to\infty$. 		
			\item \textbf{$($Uniform Tail Control$)$} The time-averaged measures satisfy the following uniform tail estimate
			\begin{equation*}
				\lim_{R\to\infty} \sup_{n\ge 1} \nu_{T_n}^{x_0}\big(E \setminus B^{d_E}_R(x_0)\big) = 0,
			\end{equation*}
			where $B^{d_E}_R(x_0)$ is the closed ball defined in (equation eq: ball B-E-R of the paper).

			\item \textbf{$($Restricted Feller Property under Mismatched Metrics$)$} The semigroup $\{\mathscr{P}_t\}_{t\ge 0}$ satisfies the restricted Feller property under mismatched metrics (cf.\ Definition (Locally Feller definition of the paper)).
		\end{enumerate}
		Then $\nu\in\mathbf{P}(E)$ is an invariant probability measure for $\{\mathscr{P}_{t}\}_{t\ge0}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma a_binomial_identity of arXiv:2507.22011, 'Random Lozenge Waterfall:\\Dimensional Collapse of Gibbs Measures'] We have for all $n\in \tfrac12\mathbb{Z}_{\ge0}$:
	\begin{equation}

		\sum_{i=-n}^n\sum_{j=-n}^n
		\frac{(-1)^{2n+i+j}q^{(i-j)^2/2+(i+j)/2}}
		{(q;q)_{n-i} (q;q)_{n+i} (q;q)_{n-j} (q;q)_{n+j}}=\frac{1}{q^n(q;q)_{2n}},
	\end{equation}
	where the sums are over $i,j$ of the same half-parity as $n$.

[Prop 38 ({cf.~\cite[Chapter~3, 1.4. Lemma~(2)) of arXiv:2609.02561, 'NON-NEF LOCI IN MIXED CHARACTERISTIC'] {Nak}}]
With notation as above, 
\[ v(\| D/S \|)=v_{\num}(D/S), \]
and for any affine open neighborhood $S^0$ of $c_{X}(v)$ in $S$,
\begin{equation*}
v_{\num}(D/S)= \inf \left\{ v(D') \middle|
\begin{gathered}
 \text{$D'$ is a $\Q$-Cartier $\Q$-divisor on $f^{-1}(S^0)$} \\
 \text{such that $D|_{f^{-1}(S^0)} \equiv_{S^0} D' \geq 0$}
\end{gathered} 
\right\}. 
\end{equation*}

[Lemma l-jl of arXiv:2412.04015, 'Linear fluctuation of interfaces in Glauber-Kawasaki dynamics'] Let $X$ be a non-negative random variable. Then,
\begin{equation*}
E[X^a] \,\le\,  E[X]^{\theta/c}\, E[X^b]^{(1-\theta)/c}
\end{equation*}
for all $a>0$, $b>0$ and $0<\theta<1$ such that
\begin{equation*}
\theta \,+\, (1-\theta) b \,>\, a\;.
\end{equation*}
In this formula $c = [\, \theta \,+\, (1-\theta) b\,]/ a >1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:dc-clean-scalar-trace-defect of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] If $C_1(u)+\Lambda_2(u)C_2(u)^{-1}=a(u)I$ for a scalar
function~$a$, then
\begin{align}
\frac{
\left(D_1-a(u)D_2-\frac{1}{2}D_2^2\right)
F(S_3u)\cdot F(u)
}{
F(S_3u)F(u)
}
&=
\frac{1}{2}
\left[
\operatorname{tr}_E\bigl(\mathcal B(u)^2\bigr)
-
\bigl(\operatorname{tr}_E\mathcal B(u)\bigr)^2
\right].

\end{align}
When $\dim E = 1$, the trace-defect term vanishes and the
Fredholm determinant satisfies the scalar Hirota equation
\begin{equation}
\left(D_1-a(u)D_2-\frac{1}{2}D_2^2\right)
F(S_3u)\cdot F(u) = 0.
\end{equation}

