The statement follows since the isomorphism in the right side can be checked at $\xi$ by the proof of","release_manifest_digest":"sha256:908e98511f62e123d7cd24f46811aecf2664a2eb94cba7c7d83e5f5a3efc934d","revision_digest":"sha256:a5467583ea28daf50cddc2325008d2e56ebd85c5137e0dd09093050a19b2031a","source_id":"arxiv:2609.02561","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

