[Corollary cor:prn_phi of arXiv:2606.23547, 'The location of the largest exponential spacing and Euler’s generalized pentagonal numbers'] For $1\le r\le n$,
\begin{equation}
p_{r,n}
=\int_0^1 r\,u^{r-1}\frac{\Phi_n(u)}{1-u^r}\,{\rm d}u.
\end{equation}

[Prop mr0 of arXiv:2411.06571, 'Moment-based approach for two erratic KPZ scaling limits'] In the setting of Proposition (mr of the paper), there exists a random four-parameter function $\tilde Z_{s,t}(x,y)$ with $-\infty<s<t<\infty$ and $x,y\in \Bbb R$, H\"older continuous on compact sets of $\{ (s,t,x,y): s<t\}$ and satisfying the following properties: 
    \begin{enumerate}\item $(Z_{s,t},f) = \int_{\Bbb R^2} \tilde Z_{s,t}(x,y)f(x,y)dxdy$ almost surely for all $s,t\in\Bbb Q \;(s<t)$ and all $f\in C_c^\infty(\Bbb R^2)$. In particular, $\tilde Z$ is defined on the same probability space. \item If $(s_j,t_j)$ are disjoint intervals then $\tilde Z_{s_j,t_j} $ are independent.
    \item If $s<t<u$ and $x,z\in\Bbb R$, then we have the a.s. relation 
    \begin{equation}\tilde Z_{s,u}(x,z) = \int_{\Bbb R} \tilde Z_{s,t}(x,y)\tilde Z_{t,u}(y,z)dy.
    \end{equation}
    \end{enumerate}

[Proposition prop:LRPseparation of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] For every $R\ge1$ and $n\ge0$,
\begin{equation}
 \norm{\delta_{z_R^{\mathrm{cyc}}}Q_R^n-
       \delta_{z_R^0}Q_R^n}_{\mathrm{TV}}
 \ge1-4n\exp\left(-\frac{R^2}{8000}\right).
\end{equation}
Moreover, there is a constant $C<\infty$, independent of $R$, such
that $Q_R$ has a unique invariant law $\pi_R$ satisfying
\begin{equation*}
 \int(\lvert x\rvert^2+\lvert v\rvert^2)\,\pi_R(dx,dv)\le CR^2,
 \qquad R\ge1.
\end{equation*}
Consequently the bound (equation eq:LRPexplicitbound of the paper) holds, proving Corollary~(cor:LRPexplicit of the paper).

[Thm Entry Approximation Thm of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] For some constants $C_{k,T}$ and $n_0(k,T)$, we almost surely have 
    \begin{gather*}
        \sup_{t \in [0,T]}|a_j(t)-\tilde{a}_j(t)| \leq C(k,T)\frac{\log(n)^j}{\sqrt{n}},\\        
        \sup_{t \in [0,T]}\frac{1}{\sqrt{n}}\left|b_j(t)^2-\tilde{b}_j(t)^2\right| \leq C(k,T)\frac{\log(n)^{2j}}{\sqrt{n}},
    \end{gather*}
    for all $n \geq n_0(k,T)$ and $j \leq k$. In particular, letting 
    \begin{equation*}
    \Tilde{E}_n(t):=\left(\Tilde{a}_1(t),\dots,\Tilde{a}_k(t), \frac{1}{\sqrt{n}}(\Tilde{b}_1(t)^2-n),\dots,\frac{1}{\sqrt{n}}(\Tilde{b}_k(t)^2-n)\right),
    \end{equation*}
    we almost surely have
    \begin{equation}
        \lim_{n \to \infty} \sup_{t \in [0,T]} \|E_n(t)-\Tilde{E}_n(t)\|=0.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

