body:
[Lemma BW-P-A-1 of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] The simplified building block ${W_\xi }\left( x \right)$ is real-valued, and admits
\begin{equation*}
\mathrm{div}\,   {W_\xi } = 0 , \ \ \int_{{\mathbb{T}^2}} {{W_\xi }\left( x \right) \otimes {W_\xi }\left( x \right)}\ \mathrm{d}x = {\xi } \otimes {\xi} ,
\end{equation*}
and
\begin{equation*}
\mathrm{div}\left( {{W_\xi } \otimes {W_\xi }} \right) = \left( {{W_\xi } \cdot \nabla } \right){W_\xi } = \mathbf{0} .
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi 14 of arXiv:2608.09700, 'A general paracontrolled ansatz for singular SPDEs'] One defines a map from $\scrT$ to $\scrT_\P$ by setting for any $\tau\in\mcB \sqcup \mcB^+$
		\begin{equation} 
			\Psi(\tau) = \sum_{\substack{k\geq 0 \\  k=k_1+k_2}} \sum_{\substack{q\geq 0 \\ \tau_q\prec\dots\prec\tau_1\prec\tau}} \, \frac{1}{k_1!\, k_2!} \, \big\lg \downarrow^k\hspace{-2pt}\tau/\tau_1,\, \tau_1/\tau_2, \dots, \tau_q \big\rg_{k_1} X^{k_2}.
		\end{equation}

[Defn def:mesh-path of arXiv:2607.18194, 'Temperature chaos in directed polymers'] We say that a continuous path $\pi:[0,\delta^{3/2}]\to \mathbb{R}$ is a \emph{mesh path} if
    \begin{itemize}
        \item $\pi(t_k) \in \varepsilon^{50}\mathbb{Z}$ for all $k\in\llbracket 0,n+1\rrbracket$,
        \item $|\pi(t_{k+1})-\pi(t_k)| < (t_{k+1}-t_k)^{2/3}\log(1/\varepsilon)$ for all $k\in\llbracket 0,n\rrbracket$, and
        \item  
        $\pi|_{[t_k,t_{k+1}]} = \Pi_{(t_k,\pi(t_k)), (t_{k+1}, \pi(t_{k+1}))}$ for all $k\in \llbracket 0,n\rrbracket$.
    \end{itemize}
    In other words, a mesh path is obtained by selecting a mesh point $v_k\in \varepsilon^{50}\mathbb{Z}$ corresponding to time $t_k$ for every $k\in\llbracket 0,n+1\rrbracket$, connecting $(t_k,v_k)$ and $(t_{k+1},v_{k+1})$ with a directed landscape geodesic, and then concatenating these geodesics across $k$ (as the reader may have already anticipated, the exponent 50 is an arbitrary large number and any other such choice would have sufficed too).
    Note that we impose a hard constraint on a mesh path's local transversal fluctuations.
    \footnote{
        This is just for technical convenience, and should be viewed as a mild constraint:
        we will be interested in the longest mesh path, which is approximately given by rounding the $\mathcal{L}$-geodesic to $\varepsilon^{50}\mathbb{Z}$, and the $\mathcal{L}$-geodesic satisfies the stated local transversal fluctuation bounds with high probability (Proposition (p:DOV-geodesic-holder of the paper)).
    }
    See Figure (fig:noise-rounding-eps-times of the paper) for a depiction of the spatial mesh $\varepsilon^{50}\mathbb{Z}$ and times $t_0,\dots,t_{n+1}$ involved in this definition.
    Since any mesh path $\pi$ is piecewise geodesic, its length is given by
    \begin{align*}
        \int_0^{\delta^{3/2}} d\mathcal{L}\circ \pi 
        = \sum_{k=0}^n \mathcal{L}(t_k,\pi(t_k); t_{k+1},\pi(t_{k+1})).
    \end{align*}

[Lem 48 of arXiv:2608.30990, 'Convergence of symmetries: nilpotency, dimension, and perfectness'] Let $z _i \in Z_i$ and $\ww _i \in \mathfrak{z}_i$ be such that $\vert \ww _i \vert _{B_i} \leq 1$ and $\exp (\ww _i ) = z_i$ for each $i$. 
    \begin{itemize}
        \item If $\vert \ww _i \vert _{B_i}  < \tfrac{r_0}{2} $ for $i$ large enough, then $z _i \in H_i$ for $i$ large enough. 
        \item If $z_i \in H_i$ for $i$ large enough, then $\vert \ww _i \vert _{B_i} < 2 r_0 $ for $i$ large enough.  
    \end{itemize}
    In particular, 
    \begin{equation}
        \exp ( \{ \vv \in \mathfrak{z}_i \, \vert \, \vert \vv \vert _{B_i} < \tfrac{r_0}{2} \} ) \subset H_i \subset \exp ( \{ \vv \in \mathfrak{z}_i \, \vert \, \vert \vv \vert _{B_i} < 2 r_0 \} )
    \end{equation}
    for $i$ large enough.

[Theorem main-thm of arXiv:2609.00627, 'Global well-posedness of radially symmetric strong solutions to two-dimensional compressib'] Assume that 
	\begin{equation}
		\beta >1, \gamma >1, 
	\end{equation} 
	and the initial data $(\rho_0, \boldsymbol{u}_0, \boldsymbol{d}_0)$ satisfy that for some $q>2$, 
	\begin{equation}
		\rho_0 \in W^{1, q}(\Omega), \boldsymbol{u}_0 \in H^1(\Omega), \nabla \boldsymbol{d}_0 \in H^1(\Omega).
	\end{equation}
Then the system (equation sCEL-sys of the paper)-(equation BC2 of the paper) has a unique global strong solution  satisfying
	\begin{equation}
		\begin{cases}
			\rho \in C([0, T];W^{1, q}(\Omega)), \rho_t\in L^\infty(0,T;L^2),\\
			(\boldsymbol{u},\nabla\boldsymbol{d})\in L^{\infty}(0, T;H^1(\Omega))\cap L^{\frac{q+1}{q}}(0,T;W^{2,q})\\
			(\sqrt{t}\boldsymbol{u},\sqrt{t}\nabla\boldsymbol{d})\in L^2(0,T; W^{2,q}),\\ (\sqrt{t}\nabla^2 \boldsymbol{u}, \sqrt{t}\nabla^3 \boldsymbol{d}) \in L^{\infty}(0, T;L^2(\Omega)),\\
			 \sqrt{t}\boldsymbol{u}_t\in L^2(0, T;H^1(\Omega)),\sqrt{t}\nabla\boldsymbol{d}_t \in L^{\infty}(0, T;L^2(\Omega))\cap L^2(0, T;H^1(\Omega)),\\
			\rho\boldsymbol{u}\in C([0,T];L^2), \sqrt{\rho}\boldsymbol{u}_t\in L^2(\Omega\times(0,T)) 
		\end{cases}
	\end{equation}
	for any $T>0$. Moreover, there is a positive constant $C $ depending only on $\mu, \beta, \gamma$, $\|\rho_{0}\|_{W^{1,q}}$, $\|\boldsymbol{u}_0\|_{H^1}$, and $\|\nabla\boldsymbol{d}_0\|_{H^1}$ such that 
	\begin{equation}
		\sup_{0\le t <\infty} \slnorm{\rho}{\infty} \le  C,
	\end{equation}
	and the following asymptotic behaviors of solution hold
	\begin{equation}
		\lim_{t \rightarrow{\infty}} (\slnorm{\rho-\bar{\rho}_0}{p}+\slnorm{\nabla \boldsymbol{u}}{p} +\slnorm{\nabla^2\boldsymbol{d}}{p})=0, 
	\end{equation}
	for any $p \in [1, +\infty)$, where
	\begin{equation*}
		\bar{\rho}_0=\frac{1}{|\Omega|}\int \rho_0 dx. 
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 47 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] For any $n>0$ and
  $t\geq 0$ on the set $\{\tau<\infty\}$ we have
\begin{equation}

E_{\cF_{\tau}}\sup_{r\in[0,t]}|x_{\tau+r}-x_{\tau}|^{ n}
\leq N(  t ^{ n/2}+ t ^{ n}),
\end{equation}
where $N=N(n, \rho_{b},\sfp_{0})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 21 of arXiv:2609.03653, 'The derived set of multiple star polylogarithms'] If ${\bf k}\succ{\boldsymbol\ell}$, then
\begin{equation}
t\mapsto\frac{\sigma_{\bf k}(t)}{\sigma_{\boldsymbol\ell}(t)}
\end{equation}
is strictly increasing on $(0,1)$.

