[Definition eqSimplefuction of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] Let $ f: \Omega \rightarrow \mathcal{X} $ be an $ \mathcal{X} $-valued function.
    \begin{enumerate}[(i)]
        \item The function $ f(\cdot ) $ is called an $ \mathcal{F} $-simple  function (or simple function when $ \mathcal{F} $ is clear) if 
        \begin{align}

            f (\cdot) = \sum_{j=1}^{k} \chi_{E_{j}}(\cdot) u_{j},
        \end{align}
        for some $ k \in \mathbb{N} $, $ u_{j} \in \mathcal{X} $, and $ \{E_{j}\}_{j=1}^{k} \subset \mathcal{F} $.
        Here, $ \chi_{E}(\cdot) $ is the characteristic function of $ E $.

        \item The function $ f(\cdot ) $ is said to be strongly $ \mathcal{F} $-measurable with respect to $ \mu $ (or simplify strongly measurable) if there exist simple functions $ \{ f_{k} \}_{k = 1}^{\infty} $ converging to $ f $ in $ \mathcal{X} $, $ \mu $-a.e.
    \end{enumerate}

[Definition def_solution of arXiv:2412.01645, 'Regularisation by Gaussian rough path lifts of fractional Brownian motions'] An $\mathbb{F}$-adapted  stochastic process $(X_t)_{t \in [0, 1]}$ is called a solution of (equation eq:main of the paper) if the following are satisfied:
\begin{enumerate}[(i)]
\item There exists an $\mathbb{F}$-adapted  stochastic process $(D^X_t)_{t \in [0, 1]}$ such that $\int_0^\cdot b^n(X_s) \, ds \to D^X $ uniformly in time, in probability, whenever $(b^n)_{n\in\mathbb{N}} \subset \mathcal{C}^\infty$ and $b^n \to b$ in $\mathcal{C}^\alpha({\mathbb{R}}^d)$. 

\item With probability one we have ${\color{blue}X}:=(X, \sigma(X)) \in \mathcal{D}^{2H_-}_B([0, 1])$, and  for all $p\geq 1$, we have 
\begin{equs}
        C_{S,p}^X:= \| {\color{blue}X}\|_{L_p(\Omega ; \mathcal{D}^{2H_-}_B([0, 1])) } < \infty.  
     \end{equs} 

    \item For all $p \geq 1$, we have 
    \begin{equs}
     C_{D,p}^X:= [D^X]_{\mathcal{C}^{1+\alpha H}([0, 1]; L_p(\Omega))} < \infty.      
    \end{equs}


    \item With probability one, for all $t \in [0, 1]$, 
    \begin{equs}
        X_t=D^X_t+ \int_0^t {\color{blue}\sigma(X_s)} \, d {\color{blue}B_s}.
    \end{equs}
\end{enumerate}
If the above holds, we also say \emph{$X$ is a solution with drift component $D^X$}.

[Lemma terms_in_signature_second of arXiv:2411.13707, 'High-degree cubature on Wiener space \\ through unshuffle expansions'] \[
\sum_{1\leq i,j\leq d}(\epsilon_i^2,\epsilon_j^2)=\sum_{1\leq i,j\leq d}\Big (4(\xi_i,\xi_{ijj})+2(\xi_{ij},\xi_{ij})+(\xi_i,\xi_i,\xi_j,\xi_j)\Big ) .
\]
\begin{proof}
Representation (equation eq:expansion of the paper) combined with (cor:parity of the paper) gives,
\begin{equation}
\sum_{1\leq i,j\leq d}(\epsilon_i^2,\epsilon_j^2)=\mathrm{e}^{\star 2}\Big (\sum_{1\leq i,j\leq d}(\epsilon_i^2,\epsilon_j^2)\Big )+\mathrm{e}^{\star 4}\Big (\sum_{1\leq i,j\leq d}(\epsilon_i^2,\epsilon_j^2)\Big ).
\end{equation}
Expanding the symmetric product as a pure tensor and applying linearity we get,
\[
\mathrm{e}^{\star k}\Big (\sum_{1\leq i,j\leq d}(\epsilon_i^2,\epsilon_j^2)\Big )=\mathrm{e}^{\star k}\Big (\sum_{1\leq i,j\leq d}\epsilon_i^2\epsilon_j^2\Big )=\sum_{1\leq i,j\leq d}\mathrm{e}^{\star k} (\epsilon_i^2\epsilon_j^2 ).
\]
For \(k=2\):
\[
\mathrm{e}^{\star 2}(\epsilon_i^2\epsilon_j^2)=2(\xi_i,\xi_{ijj})+2(\xi_j,\xi_{iij})+2(\xi_{ij},\xi_{ij}) .
\]
Substituting \(\xi_{iij}=\xi_{jii}\) (reversal property) before re-indexing the middle term \((i,j)\mapsto (j,i)\) we get,
\begin{equation}
\begin{aligned}
\sum_{1\leq i,j\leq d}\mathrm{e}^{\star 2}(\epsilon_i^2\epsilon_j^2)&=\sum_{1\leq i,j\leq d}\Big (2(\xi_i,\xi_{ijj})+2(\xi_j,\xi_{jii})+2(\xi_{ij},\xi_{ij})\Big )\\
&=\sum_{1\leq i,j\leq d}\Big (4(\xi_i,\xi_{ijj})+2(\xi_{ij},\xi_{ij})\Big ) .
\end{aligned}
\end{equation}
For \(k=4\):
\begin{equation}
\mathrm{e}^{\star 4}(\epsilon_i^2\epsilon_j^2)=(\xi_i,\xi_i,\xi_j,\xi_j) .
\end{equation}
Substituting (equation eq:k2_iijj of the paper) and (equation eq:k4_iijj of the paper) into (equation eq:proof_ei2_ej2 of the paper) we obtain the required result.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem clt for negative graphons of arXiv:2411.13062, 'Graphon-Theoretic Approach to Central Limit Theorems for $\epsilon$-Independence'] Let $(Q_n)_{n \ge 1}$ be a sequence of symmetric $n\times n$ matrices with entries in $[-1,1]$. Assume that $w_{Q_n} \to w$ in the graphon sense. Let $s_1,\ldots,s_n \in \mathcal{A}$ be a mixed $q$-Gaussian system, for every $n \ge 1$. Then 
    \begin{align*}
        S_n=\frac{1}{\sqrt{n}}\sum_{k \in [n]}s_k
    \end{align*}
    converges in distribution to a law $\mu_w$ that depends only on $w$. Moreover, its odd moments vanish, whereas, for any $p\in \mathbb{N}$, we have
    \begin{align*}
        \int x^{2p}\, \text{d}\mu_w=\sum_{\pi \in P_2(2p)}\rho(f_\pi,w).
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 27 (HDMLD Local Stability \cite{hamman2024quantifying}) of arXiv:2609.01397, 'Measuring consistency via ensemble margin and local prediction variability: Auditing decis'] Given a model from the Rashomon set $f_{k} \in \emprashomonset$, and a set $\localtestmat = \{\localtest_{j} : j \in [\nogaussianpts]\} \subseteq \ltwohsphere(x,\sigma)$ of $\nogaussianpts$ perturbed samples of $x$, we define the HDMLD local stability of the model at a fixed instance $x$ as
\begin{align}
    \hammancons(f_k,x)
    =
    \frac{1}{\nogaussianpts}
    \sum_{j=1}^{\nogaussianpts}
    \left(
        f_k(\localtest_j)
        -
        \babs{
            f_k(x)-f_k(\localtest_j)
        }
    \right).
\end{align}

[Lemma lem:int of arXiv:2512.17808, 'Zeros of polynomial powers under the heat flow'] Let $t >0$. Then,
\begin{align}
P_t^n(z)=e^{-\frac{t}{2\alpha n}\partial_z^2}P^n(z)=\frac{-i}{\sqrt{2\pi \frac{t}{\alpha n}}}\int_{i\mathbb{R}}\, \exp \left(\frac{(z-u)^2}{2\frac{t}{\alpha n}}\right)P^n(u)\,du \quad \forall z\in\mathbb{C}.
\end{align}

