[Proposition 1 of arXiv:2608.02319, 'Averaging Principle for Ordinary Differential Equations in a Multiscale Random Environment'] There exists a random process $\mathbf{X}^1 = (\Omega,\mathcal{F}^1,(\mathbf{X}_t^1)_{t\geq0}, (\mathbf{P}_x^1)_{x\in E})$ with state space $E\cup \{\Delta\}$ with lifetime $T_\Delta^1:=\inf\{t\geq 0,\mathbf X_t^1=\Delta\}$, and a random sequence of times $(\tau_k^1)_{k \geq 0}$ such that
\begin{enumerate}
    \item $\tau_0^1 = 0$;
    \item for all $k \geq 0$, conditionally on $\mathbf{X}_{\tau_k^1}^1$
    the distribution function of $\tau_{k+1}^1 - \tau_k^1$ is given by $\nu_{\mathbf{X}_{\tau_k^1}^1}$;
    \item for all $k \geq 0$, conditionally on $\mathbf{X}_{\tau_k^1}^1$,  $(\mathbf{X}_{t-\tau_k^1}^1)_{t\in [\tau_k^1, \tau_{k+1}^1)}$ is distributed as $(X_t)_{t\in[0,\zeta)}$ under $\mathbf P_{\mathbf{X}_{\tau_k^1}^1}$;
    \item at time $t = \tau_{k+1}^1$, $\mathbf{X}_t^1$ transitions to a random position selected according to the kernel $\pi(\mathbf{X}_{\tau_{k+1}^1-}^1,\,\cdot\,)$;
    \item $T_\Delta^1=\lim_{n\to+\infty} \tau_k^1$.
\end{enumerate}
In addition, this process satisfies the strong Markov property at its transition times $(\tau_k^1)_{k \geq 0}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:kernel-mmd of arXiv:2606.28869, '\bfseries A General Theory of Paths:\\ \large Signatures, Jump Lifts, and Expected Signatu'] Let $X,X'$ be independent with law $\mu$ and let $Y,Y'$ be independent with law $\nu$, all with level-$N$ square-integrable signatures.
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.25em]
\item
\begin{equation}
\mathbb{E}_\mu[k_N(X,X')]=\norm{\mathbb{E}_\mu\mathrm{Sig}^{(N)}}^2,
\end{equation}
and the diagonal excess
\begin{equation}
\mathbb{E}_\mu[k_N(X,X)]-\mathbb{E}_\mu[k_N(X,X')]=
\sum_{|w|\le N}\Var_\mu\inner{\mathrm{Sig}(X)}{w}

\end{equation}
is exactly the total coordinate defect mass from (thm:geo-defect of the paper)\textup{(ii)}.
\item
\begin{equation}
\operatorname{MMD}_N(\mu,\nu)^2=\norm{\mathbb{E}_\mu\mathrm{Sig}^{(N)}-\mathbb{E}_\nu\mathrm{Sig}^{(N)}}^2.
\end{equation}
Thus the level-$N$ signature MMD is the Euclidean distance between truncated expected signatures and separates laws up to their level-$N$ expected-signature coordinates.
\end{enumerate}

