[Definition E: initial condition thing of arXiv:2511.11036, 'Analysis of a class of Recursive Distributional Equations Including the Resistance of the '] An upper semicontinuous function $F : \mathbb{R} \times [0,+\infty) \to \mathbb{R}$ is said to be a \emph{viscosity subsolution} of (equation E: initial value problem appendix of the paper) if it satisfies $\partial_{t} F - \mathcal{F} ( \partial_{x} F, \partial_{x}^{2} F ) +Q(F)  \leq 0$ in the viscosity sense in $\mathbb{R} \times (0,+\infty)$ and 
		\begin{align} 
			\lim_{\delta \downarrow 0} \sup \left\{ F(y,0) - F_{\text{in}}(x) \, \mid \, x,y \in \mathbb{R} \, \, \text{such that} \, \, |y - x| \leq \delta \right\} \leq 0.
		\end{align}

	A lower semicontinuous function $G : \mathbb{R} \times [0,+\infty) \to \mathbb{R}$ is said to be a \emph{viscosity supersolution} of (equation E: initial value problem appendix of the paper) if it satisfies $\partial_{t} G - \mathcal{F} ( \partial_{x} G, \partial^{2}_{x} G ) + Q(G) \geq 0$ in the viscosity sense in $\mathbb{R} \times (0,+\infty)$ and 
		\begin{align*}
			\lim_{\delta \downarrow 0} \inf \left\{ G(y,0) - F_{\text{in}}(x) \, \mid \, x,y \in \mathbb{R} \, \, \text{such that} \, \, |y - x| \leq \delta \right\} \geq 0.
		\end{align*}

	A continuous function $F : \mathbb{R} \times [0,+\infty) \to \mathbb{R}$ is said to be a \emph{(continuous) viscosity solution} of (equation E: initial value problem appendix of the paper) if it is both a viscosity subsolution and a viscosity supersolution.

[Lemma 8 of arXiv:2609.02225, '\textbf{The direct moving plane method for weak solutions of the fractional $p$-Laplacian}'] Consider $1<p<\infty$ and $-1<\lambda<1$. Let $0\le u\in W_0^{s,p}(B_1)$. Assume that $\varphi$ is defined by \eqref{eq def of test func}. Then
\begin{equation}
     \left\langle
        (-\Delta)^s_p u-(-\Delta)^s_p u_\lambda,\varphi
        \right\rangle \ge0.
\end{equation}
Moreover, let $\lambda\in\mathbb{R}$ and  $0\le u\in W^{s,p}_{\mathrm{loc}}(\mathbb R^n) \cap L_{sp}^{p-1}(\mathbb R^n) \cap C(\mathbb R^n)$ satisfy the decay condition \hyperref[eq:RD-prime]{\textup{(D)}}, and suppose that $\varphi_\varepsilon$ is defined by \eqref{eq:whole-space-shifted-truncation}. Then
\begin{equation}
\left\langle
(-\Delta)_{p}^{s}u-(-\Delta)_{p}^{s}u_{\lambda},\varphi_\varepsilon
\right\rangle\geq0,
\end{equation}
and
\begin{equation}
  \begin{aligned}
 &\quad \left\langle
 (-\Delta)^s_pu-(-\Delta)^s_pu_\lambda,\varphi_\varepsilon
 \right\rangle\\
  &\ge c_p\int_{A_{\lambda,\varepsilon}}
 \psi(x)\varphi_\varepsilon(x)
 \int_{\Sigma_\lambda}
 \frac{
 \bigl(
 |u(x)-u(y)|+|u_\lambda(x)-u(y)|
 \bigr)^{p-2}}
 {|x-y^\lambda|^{n+sp}}\,dy\,dx.
\end{aligned}
\end{equation}

[Corollary 4 of arXiv:2609.01965, 'A logarithmic Bogomolov--Sommese vanishing theorem on compact K\"ahler manifolds'] Let $X$ be a compact K\"ahler manifold of dimension $n$ and $L$ a pseudo-effective line bundle over $X$.
    Let $D$ be a reduced simple normal crossing divisor on $X$. Then
    \begin{equation*}
        H^n(X,\Omega^p_X(\log D)\otimes L\otimes\mathcal{O}_X(-D))=0 \quad \text{for every } p\geq n-\nd(L)+1.
    \end{equation*}
    In particular, when $D=0$,
    \begin{equation*}
        H^n(X,\Omega^p_X\otimes L)=0 \quad \text{for every } p\geq n-\nd(L)+1.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 10 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] For any $r,\rho>0,\;x\in X$ and $\mu,\nu\in \calM(X)_{\mathrm{fin}}$, it holds that
\begin{align*}
  \nu(B(x,r))\leq\mu(B(x,r+\rho))+(1+\rho^{-\kappa})d_{\BL^{\kappa}}^X(\mu,\nu).
\end{align*}

[Theorem 8 of arXiv:2608.30409, 'Gradient estimates and volume doubling for locally finite weighted graphs with $CD\psi(n,-'] Let $G=\left(V,E\right)$ be a locally finite weighted graph satisfying the $CD\psi\left(n,-K\right)$ condition with $K\geq0$, where $\psi\in C^{1}\left(0,+\infty\right)$ is a concave function. Assume that $W\in C^{1}[0,T)\cap C[0,T]$ satisfies $W\left(0\right)=1, W\left(T\right)=0, W>0 \ on\ [0,T)$ and $W^{\prime}\in L^{2}(0,T)$. Then for any $0<f\in \ell^{\infty}\left(V\right)$, 
    \begin{equation*}
    \begin{aligned}
        \Gamma^{\psi}\left(P_T f\right)&\leq\psi^{\prime}\left(1\right)\left(1+2K\int_{0}^{T}W\left(s\right)^2ds\right)\frac{\Delta P_T f}{P_T f}\\
        &+\frac{n}{2}\left(\int_{0}^{T}W^\prime\left(s\right)^2ds+K^2\int_{0}^{T}W\left(s\right)^2ds+K\right).
    \end{aligned} 
    \end{equation*}

