[Corollary cor:osc1 of arXiv:2412.04579, 'Solvable Families of Random Block Tridiagonal Matrices'] Let $\mathbb{P}$ be the measure on non-intersecting paths ${\mathbf{q}}\colon [0, \infty) \mapsto [-\infty, \infty]^r$
defined~by
\begin{equation*}

 {\rm d} q_{i} = \frac{2}{\sqrt{\beta \gamma}} q_{i} {\rm d} b_i + \left( \left(\frac{a}{\gamma} + \frac{2}{\beta \gamma}\right) q_{i} - q_{i}^2 - \lambda {\rm e}^{-r x} + q_{i} \sum_{j \neq i} \frac{ q_{i} + q_{j}}{ q_{i}- q_{j} } \right) {\rm d} x,
\end{equation*}
started from $\{ \infty\}^r$ with the same ordering and re-indexing conventions upon possible passages to $-\infty$ described in
Corollary {\rm(cor:osc of the paper)}. With $\gamma =\frac{r+s}{r}$ and $0 < \hat{\Lambda}_0< \hat{\Lambda}_1 <\cdots $ defined in Theorem~{\rm(thm:limit_op1 of the paper)},
it holds

$ P \bigl(\hat{\Lambda}_k > \lambda\bigr) = \mathbb{P}$ $( x \mapsto \mathbf{q}(x)$ vanishes at most $ k $ times$)$
for any given $k = 0,1,\dots$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:modulation_ineq of arXiv:2509.02074, 'On the Kolmogorov-Feller weak law of large numbers for the Fr\'{e}chet mean on non-compact'] Suppose that $(M,d)$ is a non-compact symmetric space and Condition (C) holds.
\begin{enumerate}
    \item[(a)] If, for each $1\le i\le n$, $\mathbb{P}_{X_{i}}$ has finite variance, i.e., $\mathbb{E}[d^2(X_{i}, \mu)] < \infty$, then 
     \begin{equation}
        \mathbb{E}[d^2(\mu_n, \mu)]\le \frac{1}{n^2}\sum_{i=1}^{n}\mathbb{E}[d^2(X_i, \mu)].
     \end{equation}

    \item[(b)] In particular, if $X_i$'s are identically distributed and $\mathbb{P}_{X}$ has finite variance, then
    \begin{equation}
        \mathbb{E}[d^2(\mu_n, \mu)]\le \frac{1}{n}\mathbb{E}[d^2(X_1, \mu)].
    \end{equation}
    \end{enumerate}

