body:
[Theorem 2 (Profile cut-off phenomenon for Galerkin projection,
		$\gamma\in (0,1/3\rbrack$) of arXiv:2603.29473, '$\chi^2$--cut-off phenomenon for Galerkin projections of Fokker--Planck equations with mon'] \hfill

	\noindent
	Assume that $\gamma \in (0,1/3]$, $\delta(\varepsilon) = \varepsilon^{\frac{1-\gamma}{1+\gamma}}$, and $n\in \mathbb{N}$.

	\noindent
	For any $x_0\neq 0$  profile cut-off holds true in the sense of~\cref{def:pro},
	where $d_{n,\varepsilon}$ is defined in \cref{eq:Ga}, and for sufficiently small $\varepsilon>0$ the cut-off time $t_\varepsilon$
	is the unique solution to
	\begin{equation}
		e^{-2\lambda_{n,\varepsilon} t_\varepsilon}
		\left ( \int \varrho_{\varepsilon,0}(x) \psi_{n,\varepsilon}(x) \dx  \right )^2 = 1,
	\end{equation}
	equivalently,
	\begin{equation*}
		t_\varepsilon = \frac{1}{\lambda_{n,\varepsilon}} \log \left  ( \left \lvert \int \varrho_{\varepsilon,0}(x) \psi_{n,\varepsilon}(x) \dx  \right \rvert \right ).
	\end{equation*}
	The time window is given by $w_\varepsilon:= \varepsilon^{\frac{1-\gamma}{1+\gamma}}$ and the profile function $\mathfrak{p}(r):=e^{-\lambda_n r}$, $r\in \mathbb{R}$.

	\noindent
	For $x_0 = 0$, let
	\begin{equation*}
		E_n:=\{1\leq j\leq n:\ \psi_j(0)\neq 0\}.
	\end{equation*}
	If $E_n=\emptyset$, then $d_{n,\varepsilon}(t,0)=0$ for all $t\geq 0$. Otherwise, letting $m:=\max E_n$, the centered initial datum exhibits profile cut-off with cut-off time determined by
	\begin{equation*}
		e^{-2\lambda_{m,\varepsilon} t_\varepsilon}\left(\int \varrho_{\varepsilon,0}(x)\psi_{m,\varepsilon}(x)\,\dx\right)^2=1,
	\end{equation*}
	the same time window $w_\varepsilon:=\varepsilon^{\frac{1-\gamma}{1+\gamma}}$, and profile function $\mathfrak p(r)=e^{-\lambda_m r}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 10 (Properties of Bessel functions) of arXiv:2609.04155, 'The subconvexity problem for symmetric square\\ $L$-functions in Level aspect'] For $x>0$, and $r\in\R\cup i\R$
		\begin{equation*}
			J_r(x)=e^{ix}U_r(x)+e^{-ix}U_{-r}(x),\hspace{1.5mm}\text{and}\hspace{1.5mm}x^{j}K_r^{(j)}\ll_{j, r}\frac{e^{-x}}{\sqrt{x}},
		\end{equation*}
		where, 
		\begin{equation*}
			x^jU_{\pm r}^{(j)}(x)\ll_{j, r}1/\sqrt{x}.
		\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

