[Definition 3 of arXiv:2506.22085, '2506.22085'] Fix $T>0$ and $\mu_0,\mu_1\in \ms M_+(\bb T^d)$ which we assume to
  be absolutely continuous with respect to $dx$ and with the same
  mass.
  \begin{itemize}
  \item [(HSP)] The \emph{hydrodynamical Schr\"odinger problem}
    is the optimization problem 
    \begin{equation*}
      V_T(\mu_0,\mu_1) :=
      \inf \big\{ I(\pi,\ms J),\; \pi_0=\mu_0,\, \pi_T=\mu_1 \big\}.
    \end{equation*}
   \item [(MSP)] The \emph{measure Schr\"odinger problem}
    is the optimization problem 
    \begin{equation*}
      \ms V_T(\mu_0,\mu_1)
      :=  \inf \big\{ \mf F(R),\; R_0=\mu_0,\, R_T=\mu_1 \big\}.
    \end{equation*}   
  \end{itemize}

[Lemma lem:beta of arXiv:2605.21265, 'The non-Hermitian minor process'] Fix a (small) $c_0>0$ and a (large) $L>0$. For $w_j=\pm\mathrm{i}\eta_j$ it holds that
\begin{equation}
|\beta_+\beta_-|\gtrsim \rho_2^2|x_2-x_1|+|z_1-z_2|^2 +\rho_1\eta_1 +\rho_2\eta_2,

\end{equation}
uniformly in $x_j\in [c_0,1]$, $x_1\le x_2$, $|z_j|\le L$ and $0<\eta_j\le L$. Additionally, in the regime $\sqrt{x_j}\le |z_1|\le L$, $j=1,2$, we have
\begin{equation}
|\beta_+\beta_-|\gtrsim \left(|z_1|^2-x_1\right)\left(|z_2|^2-x_2\right).

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 6 of arXiv:2608.28991, 'Jigsaw-CRL: Recovering Global Latent Causal Order from Fragmented Multi-Client Interventio'] For $Z$ generated by Eq.~\eqref{eq:gloabl latent}, let $Z_k=Z_{O_k}$. Then
\begin{equation}
Z_k = \bA_k Z_k + E_k,
\end{equation}
where
\begin{align}

    \bA_k
    &=
    [\bA]_{O_k,O_k}
    +
    [\bA]_{O_k,M_k}
    (\bI-[\bA]_{M_k,M_k})^{-1}
    [\bA]_{M_k,O_k}, \\
    E_k
    &=
    E_{O_k}
    +
    [\bA]_{O_k,M_k}
    (\bI-[\bA]_{M_k,M_k})^{-1}
    E_{M_k}.
\end{align}
Moreover, $E_k$ has mean zero and covariance
\begin{equation}

    \bSigma_k
    =
    [\bSigma]_{O_k,O_k}
    +
    [\bA]_{O_k,M_k}
    (\bI-[\bA]_{M_k,M_k})^{-1}
    [\bSigma]_{M_k,M_k}
    (\bI-[\bA]_{M_k,M_k})^{-T}
    [\bA]_{O_k,M_k}^{T}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma_link_V_T_cF_T of arXiv:2503.24372, 'A criterion on the free energy for log-Sobolev inequalities in mean-field particle systems'] Let $\varphi\in \R^d$. 
Then the renormalised potential introduced in (equation eq_def_V_t_quadratic_W of the paper) can be rewritten as 

\begin{align} 
  V_T(\varphi) 
  &= \inf_{\rho\in {\bf M}_1( \R^d )} 
    \left\{ \cF_T(\rho) +\frac{1}{2T}\Big(\varphi -\int x\,\rho(dx) \Big)^2 \right \}
    \nnb
  &
  = \inf_{m\in\R^d} 
\left\{ \hat \cF_T(m) +\frac{1}{2T} | \varphi -m  |^2 \right \} 
,
\end{align}

and 
there are as many global minimisers for the free energy $\cF_T$ as for the renormalised potential $V_T$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop onsager of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] Let $D$ be a bounded, simply connected domain. For any continuous, bounded  function $f:\mathbb C\to\mathbb R$,
    \begin{equation}
        \mathbb E[|(\field{e^{i\alpha\phi}}, f)|^{2k}]\leq\left\lVertf\right\rVert_\infty^{2k}C^{2k}\int_{D^{2k}}\exp\left( \frac{\alpha^2 }{2 }\sum_{n=1}^{2k}\log(1/r(z_n))\right) dz_1\cdots dz_{2k},
    \end{equation}
    where 
    \begin{equation}
        r(z_n) := \frac{1}{2}(\min_{m\neq n}|z_n-z_m|\wedge d(z_n, \partial D)),
    \end{equation}
    and $C<\infty$ is some constant that only depends on the domain $D$.

