[Lemma lemma6.234 of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] For $B>0$ consider $\zeta\in\Gamma_B$ and $X\sim\operatorname{Col}_n(\zeta)$. Let $M_1,M_2$ be two $n\times n$ symmetric matrices, $u\in\mathbb{R}^n$, $t_1,t_2\in\mathbb{R}$ and $s,\delta_1,\delta_2\geq 0$. Then 
\begin{equation}\begin{aligned}
    &\mathbb{P}(|\langle M_iX,X\rangle-t_i|<\delta_i,i=1,2,\langle X,u\rangle\geq s)\\&\lesssim \delta_1\delta_2e^{-s}\int_{\{\theta\in\mathbb{R}^2:\theta_1^2\delta_1^2+\theta_2^2\delta_2^2\leq 2\}}|\mathbb{E}e^{2\pi i\theta_1\langle M_1X,X\rangle+2\pi i\theta_2\langle M_2X,X\rangle+\langle X,u\rangle}|d\theta.
\end{aligned}\end{equation}

