\begin{align}
    \limtoinfty{n}\sum_{\substack{x ,y \in V_{n} \\x \neq y}}
    c_{n,x,y}g(x)(h(x)-h(y))(h^{\prime}(x)-h^{\prime}(y))
    = \int_{X} g\, d\nu_{h, h^{\prime}}.
\end{align}

