[Theorem tflbdpsp of arXiv:2411.09005, 'On Time-Changed Linear Birth-Death Process with Immigration at Extinction'] For $\alpha=\lambda=\mu$,  state probabilities of the TFLBDPwI are given by
	\begin{equation}
		p^\nu(n,t)=\sum_{k=n}^{\infty}\frac{(-1)^{k-n}c_{n,k}(\lambda t^\nu)^k}{\Gamma(k\nu+1)},\ n\ge0,
	\end{equation}
	where $p^\nu(0,t)$ is called the extinction probability. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:one_edge_2_le_delta_1_gamma of arXiv:2509.23496, 'Crossing probabilities in geometric inhomogeneous random graphs'] The one-edge crossing probabilities satisfy, for $|x|=R$,
    \begin{align*}
        \pi_{(u),R}&\asymp u^{-\gamma \delta} R^{d(1-\delta)} \wedge 1
        \asymp \begin{cases}
                    u^{-\gamma \delta} R^{d(1-\delta)} & \text{ on } \{u \geq R^{d(\frac 1 {\gamma \delta}-\frac 1 \gamma)}\},\\
                    1 & \text{ on } \{u \leq R^{d(\frac 1 {\gamma \delta}-\frac 1 \gamma)}\},
                \end{cases}
    \end{align*}
    \begin{align*}
        \pi_{r,(x,u)}&\asymp u^{-\gamma \delta} r^dR^{-d\delta}\wedge 1
        \asymp \begin{cases}
                    u^{-\gamma \delta} r^dR^{-d\delta} & \qquad\quad\text{ on } \{u \geq r^{\frac d {\gamma \delta}}R^{-\frac d \gamma}, R\ge 2r\},\\
                    1 & \qquad\quad\text{ on } \{u \leq r^{\frac d {\gamma \delta}}R^{-\frac d \gamma}, R\ge 2r \},
                \end{cases}
    \end{align*}
    \[
    \pi_{r,R}\asymp r^d R^{d(1-\delta)} \phantom{birnensalatmitkra} \text{ on }\{ R\ge 2r\}.
    \] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem sDHD-th6.10 of arXiv:2604.21591, '\bf Long-time dynamics of stochastic 2D hydrodynamic-type evolution equations driven by mu'] Assume that the hypotheses of Theorem (2DHD-the3.3-0 of the paper) and condition (equation LSWs6.3 of the paper) hold. Then the non-autonomous dynamical system $\Psi$ generated by ((2DHD-1.1 of the paper)) possesses a unique $\mathscr{D}$-pullback measure attractor $\mathscr{A}=\{\mathscr{A}(\tau):\tau\in \mathbb{R}\}\in \mathscr{D}$ in $(\mathcal {P}_4 (H), d_{\mathcal{P}(H)})$. Moreover, for every $\tau\in \mathbb{R}$, $\mathscr{A}(\tau)$ has the following characterizations:
	\begin{align*}
		\begin{split}
			\mathscr{A}(\tau)
			=\omega(\mathcal{K},\tau)&=\{\psi(0,\tau): \psi \text{ is a } \mathscr{D}\text{-complete orbit of } \Psi\}\\
			&=\{\widehat{u}(\tau): \widehat{u} \text{ is a }  \mathscr{D}\text{-complete solution of } \Psi\},
		\end{split}
	\end{align*}
	where $\mathcal{K}=\{\mathcal{K}(\tau):\tau\in \mathbb{R}\}$ denotes the $\mathscr{D}$-pullback absorbing set of $\Psi$ provided by Lemma (sDHD-lemma6.8 of the paper).

[Lemma 13 of arXiv:2608.27433, 'Scalar curvature on K\"ahler blow-ups and systolic inequalities'] There is a constant $C$, independent of $\eps$, such that
\begin{equation}

  \norm{\phi}_{C^{4,\alpha}_\delta}
  \le C\left(
    \norm{\phi}_{C^0_\delta}
    +\norm{\widetilde{\mathcal P}_\eps\phi}_{C^{0,\alpha}_{\delta-4}}
  \right).
\end{equation}

