[Lemma 16 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, uniformly for $z\in\mb D(\tau,\eta_0)$,
        \begin{align}
                \|\Pi^{-1}(z)\|\lesssim1,\qquad \|\Pi(z)\|\lesssim\frac1{\Im m(z)}. \nonumber
        \end{align}
        Moreover,
        \begin{align}
                \|\Pi_{11}(z)\|\lesssim\frac1{\Im m(z)+\dist(z,\supp\bnu_1)},\qquad \|\Pi_{22}(z)\|\lesssim\frac1{\Im m(z)+\dist(z,\supp\bnu_2)}. \nonumber
        \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] We have 

\begin{equation}
g_{\text{{\tiny $\delta$}}} (\tilde{v}_m) \longrightarrow g_{\text{{\tiny $\delta$}}} (\tilde{v}) \quad \text{in} \quad L^2(0,T\,;L^2(\Omega)) \quad 
\text{as} \quad m \to \infty 
\end{equation}

whenever a sequence $\{\tilde{v}_m\}_{m\,\in\,\mathbb{N}} \subset \mathcal{V}_R(v_0,\nu)$ and a function $\tilde{v} \in \mathcal{V}(v_0)$ satisfy the following 
convergences as $m \to \infty$:

\begin{equation}
\tilde{v}_m \longrightarrow \tilde{v} \quad \left\{
\begin{array}{l}
\text{in} \quad C([0,T]\,;L^2(\Omega)),\\[0.1cm]
\text{weakly in} \quad W^{1,2}(0,T\,;L^2(\Omega)),\\[0.1cm]
\text{weakly$^*$ in} \quad L^\infty (0,T\,;H^1(\Omega)).
\end{array}
\right.
\end{equation}

\indent
Moreover, there exists a constant $C_9>0$, which is independent of the approximate parameters $\delta \in (1,\infty)$ and $\nu \in (0,1)$, 
such that the following uniform estimate holds:

\begin{equation*}
\sup_{\nu\,\in\,(0,1)} \left\{ \sup_{\tilde{v}\,\in\,\mathcal{V}_R(v_0,\nu)} 
\left( \sup_{0 \le t \le T} \|(g_{\text{{\tiny $\delta$}}} (\tilde{v}))(t)\|_{L^2(\Omega)} \right) \right\} \le \delta C_9 R^{\frac{1}{2}}.
\end{equation*}

[Theorem 3 ({Crandall-Rabinowitz: \cite[Theorem 1.7) of arXiv:2609.01333, '2609.01333'] {CrRa71}}] 
Let X, Y be Banach spaces, V a neighborhood of 0 in X and $F:(-1,1)\times V\to  Y$
have the properties :
\begin{enumerate}[$(a)$]
\item $F(t,0) = 0 $  for $|t|<1$.
\item The partial derivatives $F_t$, $F_z$ and $F_{tx}$ exist and are continuous,

\item $\ker(F_x(0, 0))$ and $Y\setminus Range(F_x(0, 0))$ are one-dimensional,

\item $F_{tx}(0,0)x_0\notin Range(F_x(0, 0))$, where
\begin{align*}
\ker(F_x(0,0))= \textrm{span}\{x_0\}.
\end{align*}
\end{enumerate}
Let $Z$ be any complement of $\ker(F_x(0, 0))$ in $X$. Then there is a neighborhood $U$ of $(0,0)$ in $\mathbb{R}\times X$, an interval $(-a,a),$ and continuous functions $\varphi: (-a,a) \to  \mathbb{R} $, $\psi: (-a,a) \to  Z $ such that $\varphi(0) =0$, $\psi(0)=0$ and

\begin{align}
F^{-1}(\{0\})\cap U = \lbrace (\varphi(\alpha), \alpha x_0+\alpha\psi(\alpha)): |\alpha|<a\rbrace\cup \lbrace(t,0): (t, 0)\in U\rbrace.
\end{align}
In other word for $(t,x)\in U$ $F(t,x)= 0$  if and only if $ x=0$  or there is $\alpha\in (-a,a)$ such that
\begin{align*}
t=\varphi(\alpha)
\quad \text{and}\quad
x= \alpha x_0+\alpha\psi(\alpha).
\end{align*}
Moreover, if $F_{xx}$ is also continuous, the functions $\varphi$ and $\psi$ are continuously differentiable. (Proof in the paper; no proof environment follows the statement in the TeX.)

