body:
[Theorem 19 of arXiv:2605.14254, '2605.14254'] Let $T$ be a stopping time with compensator $A$. Then:
		\begin{enumerate}
			\item[(i)] $T$ is predictable if and only if $A$ is almost surely constant apart from a possible unit jump;
			\item[(ii)] $T$ is accessible if and only if $A$ is almost surely purely discontinuous;
			\item[(iii)] $T$ is totally inaccessible if and only if $A$ is almost surely continuous.
		\end{enumerate}

[Lem Lemma2.1 of arXiv:2411.11408, 'Multidimensional specific relative entropy between continuous martingales'] Let $n \in \mathbb{N}$ and $\mathbb{P},\mathbb{Q}\in \mathcal{M}_1(C) $ such that $\mathbb{Q}|_{\mathcal{F}^n}\ll \mathbb{P}|_{\mathcal{F}^n}$. Then $\mathbb{P}$-a.s., 
    \begin{equation*}
        \frac{d\mathbb{Q}}{d\mathbb{P}}|_{\mathcal{F}^n}(\omega)=\frac{d\mathcal{L}_{\mathbb{Q}}(X_0, \Delta_1^n X,\dots,\Delta_n^nX)}{d\mathcal{L}_{\mathbb{P}}(X_0, \Delta_1^n X,\dots,\Delta_n^nX)}(\omega(0),\Delta_1^n\omega, \dots, \Delta_n^n\omega).
    \end{equation*}
    In particular, 
    \begin{equation*}
H(\mathbb{Q}|\mathbb{P})|_{\mathcal{F}^n}=H(\mathcal{L}_{\mathbb{Q}}(X_0, \Delta_1^n X,\dots,\Delta _n ^n X)| \mathcal{L}_{\mathbb{P}}(X_0, \Delta_1^n X,\dots,\Delta_n^nX)).
    \end{equation*}
    Moreover, if $\mathbb{P}$ and $\mathbb{Q}$ are such that $X$ has independent increments. Then
    \[H(\mathbb{Q}|\mathbb{P})|_{\mathcal{F}^n}=H(\mathcal{L}_{\mathbb{Q}}(X_0)|\mathcal{L}_{\mathbb{P}}(X_0))+\sum _{k=1}^n H(\mathcal{L}_{\mathbb{Q}}(\Delta _k^n X)|\mathcal{L}_{\mathbb{P}}(\Delta _k^n X)).\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma fNtNlmt of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Following hold for ${\sf f}_N = L^{\frac{d}{2} N} f_N$.
\begin{enumerate}
\item $\lim_{N\rightarrow \infty} ({\sf f}_N,   \tilde{\sf f}_N) = ( \textbf{a}^{(\emptyset)} )^{-1} \norm{f}_{L^2 (\T^d)} $.
\item For any $r \in [0,\infty]$ and each $n \in \N$,  there is a constant $C_n >0$ such that
\begin{align}
	\norm{\nabla^n \tilde{\sf f}_N}_{\ell^{2+r}} \le C_{n} L^{-nN} L^{-\frac{d r}{2(2 +r)} N} \left( L^{(2-\eta)N} + ( \textbf{a}^{(\emptyset)} )^{-1} \right)^{\frac{r}{2+r}} ( \textbf{a}^{(\emptyset)} )^{-\frac{2}{2+r}} \norm{\nabla^n f}_{\ell^{\infty}}  
\end{align}
uniformly in $N$,  with $\frac{r}{2+r} = 1$ when $r = \infty$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 25 (Uniform bounded resolvent on large dilations) of arXiv:2608.30211, '2608.30211'] Assume that $\Omega$ is bounded and uniformly $C^{2,\gamma}$, with nonempty
boundary.  There are $\delta>0$, $\kappa_2>0$, and $C>0$ such that the
following holds.  Let $\kappa\geq\kappa_2$, $\varrho\in[0,1]$, and
$q,g\in L^\infty(D_\kappa)$ satisfy
\begin{equation}
 \|q-f'(\Phi_{\kappa,\varrho})\|_\infty\leq\delta.
\end{equation}
If a bounded weak solution $w$ satisfies
\begin{equation}
 -\Delta w-qw=g\quad\text{in }D_\kappa,\qquad
 \cN_\varrho w=0\quad\text{on }\partial D_\kappa,
\end{equation}
then
\begin{equation}
 \|w\|_\infty\leq C\|g\|_\infty.
\end{equation}

[Corollary coro_1 of arXiv:2412.03774, '{ Refining Concentration for \\Gaussian Quadratic Chaos with\\ Applications in Sonar and C'] Let $A$ be a symmetric matrix. For every $\epsilon>0$ and integer $m\geq2$, 
\begin{eqnarray}

\Pr(\boldsymbol{\Delta}>t)\leq \inf_{0<b<1}e^{\Lambda_m(t,b)}\leq (1+\epsilon)\exp\bigg(-\tilde{\kappa}_{m}\min\bigg\{\frac{t^{1+\frac{1}{m}}}{\|A\|_{m+1}^{1+\frac{1}{m}}}, \frac{t}{\|A\|}\bigg\}\bigg),
\end{eqnarray} 
where $\tilde{\kappa}_{m}>0$ is a constant that depends only on $m, n$ and $\epsilon$.

