body:
[Lemma 35 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $(X,d,\mu)$ be a Polish probability space with enlargement functions
$(R_s)_{s\geq 0}$ and associated function $\Theta$. 

Assume $A,B\in \mathcal{B}(X)$ are non-empty sets with
$0<\mu(A)\mu(B)\leq 1$.

Then,
\begin{equation}

    \mu(A)^{\frac12}\mu(B)^{\frac12}
    \leq
    2\Theta(d(A,B)).
\end{equation}
Moreover, if $A$ and $B$ are essentially disjoint, that is,
$\mu(A\cap B)=0$, then one has the sharp bound
\begin{equation}

    \mu(A)^{\frac12}\mu(B)^{\frac12}
    \leq
    \Theta(d(A,B)).
\end{equation}

Furthermore, assume that, for each $s>0$, the supremum defining $\Theta$ in
\eqref{eq:theta_def} is uniquely achieved at some $v_s\in(0,1)$ and that
$R_s(v_s)<1$. Then equality holds in \eqref{eq:enlargement_sharp} with
$0<\mu(A),\mu(B)<1$ if and only if the following conditions hold:
\begin{enumerate}
    \item If $d(A,B)=0$, then $\mu(A)=\mu(B)=\frac12$ and $B=X\setminus A$ up to a null set.

    \item If $d(A,B)>0$, then
    \begin{enumerate}
        \item $\mu(A)=v_{d(A,B)}$ and $\mu(B)=1-R_{d(A,B)}(v_{d(A,B)})$;
        \item
        \[
            \mu(A_{<d(A,B)})=R_{d(A,B)}(\mu(A));
        \]
        \item
        \[
            \mu\bigl(B\Delta(X\setminus A_{<d(A,B)})\bigr)=0.
        \]
    \end{enumerate}
\end{enumerate}

