[Theorem 10 (Asymptotics for $\alpha \to \alpha_0,$ $\alpha_0 \in [0,2\pi\textnormal{) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] }\backslash \mathcal M$, or $\alpha \to 0, \pi$ with $\alpha \in [0,2\pi\textnormal{]}\backslash \mathcal M$] 
Assume $x^+_{max} > x^-_{max}$ (cases A and D of Figure~\ref{anglesalphab}). Let $z_0 \in \R^2$ and let $0 \leq \alpha_0 < \alpha_b$. Then:
\begin{equation}
g^{z_0}(r\cos(\alpha), r\sin(\alpha))
\underset{r\to\infty \atop\alpha\to\alpha_0, \alpha \geq 0}{\sim} C'_{br}(\alpha_0) f_0(z_0)\frac{e^{-r(\cos(\alpha)x(\alpha_b) + \sin(\alpha)y(\alpha_b))}}{r^{3/2}
}
\end{equation}
where $C'_{br}(\alpha_0) = \left(\frac{\sin(\alpha_b)}{\sin(\alpha_b - \alpha_0)}\right)^{3/2}C_0$ (see \eqref{eq:C_0}) and where $f_0(z_0)$ is given by \eqref{f(z_0)branch}. 

Assume now $x^+_{max} < x^-_{max}$ (cases B and C of Figure~\ref{anglesalphab}) and let $\alpha_b < \alpha_0 \leq 2\pi$. Then,
\begin{equation}
 g^{z_0}(r\cos(\alpha), r\sin(\alpha))
\underset{r\to\infty \atop\alpha\to\alpha_0, \alpha \leq 2\pi}{\sim}  C'_{br}(\alpha_0)f_0(z_0)\frac{e^{-r(\cos(\alpha)x(\alpha_b) + \sin(\alpha)z(\alpha_b))}}{r^{3/2}}
\end{equation}
where $C'_{br}(\alpha_0)$ has the same expression and where $f_0(z_0)$ is given by \eqref{f(z_0)col}.

The symmetric results hold for $\tilde\alpha_b< \alpha_0 \leq\pi$ in the cases A and B and for $ \pi\leq \alpha_0 < \tilde\alpha_b$ in the cases C and D. (Proof in the paper; no proof environment follows the statement in the TeX.)

