body:
[Lemma drift-lemma-2 of arXiv:2504.02207, 'Finite-Time behaviors of M/M/$n$ Queue: Mixing Time, Mean Queue Length and Tail Bounds'] Let $\{\lambda_n\}_{n \in \Z^+}$ be the sequence of arrival rates of the corresponding $M/M/n$ system such that $\lambda_n \in (0,n) \forall n \in \Z^+$ and let $\alpha_n = 1-\frac{\log (n-\lambda_n)}{\log n}$. Set $V(q) = \zeta e^{\theta(q-\lambda_n)} \forall q > n$. If $\lambda_n \in \Z_{\geq 0}$, set $V(q) = |q-\lambda_n| \forall q \leq n$. Otherwise, set
    \begin{align}

    V(q) = 
        \begin{cases}
            |q-\lambda_n| \, &\forall q \leq n, q \not \in \{\lfloor \lambda_n \rfloor, \lceil \lambda_n \rceil\} \\
            |\lfloor \lambda_n \rfloor - \lambda_n - 1| &\textit{if } q = \lfloor \lambda_n \rfloor \\
            |\lceil \lambda_n \rceil - \lambda_n + 1| &\textit{if } q = \lceil \lambda_n \rceil
        \end{cases} 
    \end{align}
     where $\zeta$ is chosen such that $|n-\lambda_n| = \zeta e^{\theta(n-\lambda_n)}$ and $\theta > 0$ is a parameter to be chosen. Then, for $\alpha_n \in (0,1/2) \, \forall n \in \Z^+$ and $\lim_{n \rightarrow \infty} \alpha_n = \alpha \in (0,1/2)$ for some constant $\alpha$, we have there exists $\gamma_n, b$ with $\gamma_n \rightarrow 1$, such that
    \begin{align}
        \cL V \leq -\gamma_n V + b 1_K
    \end{align}
    where $b \leq 2\lambda_n$ and $K = \{\lambda_n\}$ if $\lambda_n \in \Z_{\geq 0}$ and $b \leq \lceil \lambda_n \rceil + 2$ and $K = \{\lfloor \lambda_n \rfloor - 1, \lfloor \lambda_n \rfloor, \lceil \lambda_n \rceil, \lceil \lambda_n \rceil + 1\}$ otherwise. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:Ergodic:ErgodicStrong of arXiv:2608.17031, 'A shape theorem for periodic branching diffusion'] Let $\nu\in C^{2,\alpha}_p(\mathbb{R}^d)$ be the density of the unique invariant measure of $(\dot{Z}_t)_{t\geq 0}$ on $\mathbb{T}^d$ and $f\in C^{0,\alpha}_p(\mathbb{R}^d)$ be such that $\nu(f)=0$. Fix $\epsilon>0$. There exist positive constants $C_1,C_2$ depending on $d$, $\|\sigma\|_{0,\alpha}$ and $\|b\|_{0,\alpha}$ such that, for all $t$ sufficiently large (depending on $d$, $\|\sigma\|_{0,\alpha}$, $\|b\|_{0,\alpha}$, $\|f\|_{0,\alpha}$ and $\epsilon$),
    \begin{equation}
        \sup_{x\in \mathbb{R}^d} \probbb{x}{}{\sup_{\ell \in [0,t]}\bigg|\int_0^\ell f(Z_s)ds \bigg|>t\epsilon}\leq C_1 \frac{\|f \|_{0,\alpha}}{\epsilon t^{1/2}} e^{-C_2t\epsilon^2/\|f\|_{0,\alpha}^2}.
    \end{equation}

