[Lemma lem:Newton-Leibniz of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] Let $f \colon [0, 1] \to \BR$ be a continuous and strictly increasing function. Then $f^\prime(x)$ exists for almost every $x \in [0,1]$ and
    \begin{equation*}
        \int_A f^\prime(x) \, \rd x \le \Leb(f(A))
    \end{equation*}
    for all Borel $A \subset [0, 1]$.

[Prop p:polymer-TF-DZ of arXiv:2607.18194, 'Temperature chaos in directed polymers'] {DZ24}}]
    Fix $L\geqslant 1$ and $T\geqslant 1$ and 
    $(s,x;t,y)\in\mathbb{R}^{4}_{\uparrow}$ with $x,y\in [-L,L]$ and $t-s \leqslant T$.
    There exist $C_1,C_2>0$ depending on $L,T$ such that the following holds.

    Fix $\beta\geqslant (t-s)^{-1/4}$ and let $X\sim \mathrm{CDRP}^{\xi}_\beta(s, x\beta^{2/3}; t,y\beta^{2/3})$.
    Then for all $m\geqslant 0$,
    \begin{align}
        \mathbb{P}\left(\mathbb{P}^{\xi}_{\beta,(s,x\beta^{2/3}),(t,y\beta^{2/3})}
        \left(
            \sup_{r\in[s,t]} \left|X(r)\right| > m \beta^{2/3}
        \right)\geqslant C_{1}e^{-m^{2}/C_{1}}\right)
        \leqslant C_{2}e^{-m^{3}/C_{2}}.
    \end{align} 

    For later convenience, we also record a slight reformulation of the above result.
    For all $\varepsilon\in(0,1)$, all $z\in[-\varepsilon,\varepsilon]$, all $n\geqslant \varepsilon^{-3/2}$, and all $m\geqslant 0$,
    \begin{align}
        \mathbb{P}\left(
            \mathbb{P}^\xi_{1,(sn, zn^{2/3}),((s+\varepsilon^{3/2})n, zn^{2/3})}
            \left(
            \sup_{r\in[s,s+\varepsilon^{3/2}]}\left|
                n^{-2/3}
                X(rn)
            \right|
            \geqslant  m \varepsilon
            \right)
            \geqslant C_1 e^{-m^2/C_1}
        \right)
        \leqslant C_2 e^{-m^3/C_2}.
    \end{align}

