body:
[Prop 11 of arXiv:2609.01413, 'Sharp Threshold for Universality of Rational Canonical Forms over a Finite Field'] We have
\begin{equation}
\Aut\left(\bigoplus_{i=1}^k\bigoplus_{j\ge 1}(\F_p[t]/(f_i^{\l^{(f_i)}_j}))\right)=\prod_{i=1}^k\Aut_{f_i}(\lambda^{(f_i)}),
\end{equation}
where for all $1\le i\le k$, $\Aut_{f_i}(\lambda^{(f_i)})$ is the group of automorphisms of $\bigoplus_{j\ge 1}(\F_p[t]/(f_i^{\l^{(f_i)}_j}))$, and
\begin{equation}
\#\Aut_{f_i}(\lambda^{(f_i)})=p^{\deg f_i\cdot(|\l^{(f_i)}|+2n(\l^{(f_i)}))}\prod_{j\ge 1}(p^{-\deg f_i};p^{-\deg f_i})_{m_j(\l^{(f_i)})}.
\end{equation}
Here, the notation $(a;q)_m:=(1-a)(1-aq)\cdots(1-aq^{m-1}),m\ge 0$ refers to the $q$-Pochhammer symbol with the convention that $(a;q)_0=1$.

[Lemma Lem:ftc of arXiv:2411.13030, 'Classification of the limit shape for 1+1-dimensional FPP'] Let $f(x)$ be a Riemann-integrable function on $[0,1]$ and set $L=\int_0^1 f(x) \,dx$. For $\varepsilon>0$, define the sets
\[
D=\{x\in [0,1]:\, f(x)<0 \} , \quad L_\varepsilon=\{ x\in [0,1]: f(x)\in [0,L+\varepsilon] \}. 
\]
Then one of the following holds:
\begin{equation}

\left| \int_D  f(x) \, dx \right| \ge \frac \varepsilon 2.
\end{equation}
or
\begin{equation}

\mu(L_\varepsilon \cup D) \ge \frac \varepsilon {2(L+\varepsilon)}. 
\end{equation}
where $\mu(\cdot)$ denotes the Lebesgue measure.

[Pro eq:Pro1 of arXiv:2411.02141, '\bf Uniqueness of Maximum Scores in Countable-Outcome Round-Robin Tournaments'] Assuming Model $M_{[0,\,1]}$, we have
\begin{align*}

\lim_{n\rightarrow \infty}\mathbb{P}\left(s^{\star}_n>t_n \right)=1.
\end{align*}

