[Proposition prop:fixed-interface-difference of arXiv:2608.30904, 'Entire monotone solutions of the anisotropic Allen--Cahn equation in dimension 5'] There exist $\theta>0$ and $C<\infty$ such that, for any
$f_1,f_2$ satisfying (equation eq:f-ball of the paper),
\begin{align}
\|\ell_{\varepsilon,f_1}-\ell_{\varepsilon,f_2}\|_{C^{0,\alpha}_{\gamma+2}}
&\le
C\varepsilon
\|f_1-f_2\|_{C^{2,\alpha}_\gamma},
\\
\|\Delta_\varepsilon(f_1)-\Delta_\varepsilon(f_2)\|_{C^{0,\alpha}_{\gamma+2}}
&\le
C\varepsilon^{1+\theta}
\|f_1-f_2\|_{C^{2,\alpha}_\gamma}.

\end{align}
After transporting the two corrections to the same $(Y,s)$ coordinates,
\begin{equation}
|v_{\varepsilon,f_1}-v_{\varepsilon,f_2}|
+\varepsilon|D(v_{\varepsilon,f_1}-v_{\varepsilon,f_2})|
\le
C\varepsilon^\theta
\|f_1-f_2\|_{C^{2,\alpha}_\gamma}\rho^{-\gamma-1}.
\end{equation}
For each $f$ satisfying (equation eq:f-ball of the paper), the small invariant
fiber-orthogonal fixed-interface solution is unique.

[Lemma 17 of arXiv:2512.01483, 'Scaling Limits of Line Models in Degenerate Environment'] Let $A_i :=  \frac{1+ \varepsilon_i^+}{1- \varepsilon_1^+ \varepsilon_2^+}$, $i=1,2$. Let $C,\kappa >0 $, and let $h,v : \mathbb{R}_+ \to \mathbb{R}_+$ be two continuous functions.
\begin{enumerate}
\item If $h$ and $v$ satisfy the system of differential inequalities
\begin{equation}

\forall t \in  [0,T], \quad \begin{cases}
h(t) \leq C(\kappa + A_1  \int_0^{t}  v(s)^{\varepsilon_1^+} \, ds) \\
v(t) \leq C(\kappa +  A_2 \int_0^{t}  h(s)^{\varepsilon_2^+} \, ds), 
\end{cases}
\end{equation}
then, for all $t \in [0,T]$,
$$h(t) \leq [(C\kappa)^{1/A_1}+Ct]^{A_1}, \qquad v(t) \leq [(C\kappa)^{1/A_2}+Ct]^{A_2}. $$ 

\item If $h$ and $v$ satisfy the system of differential inequalities
\begin{equation}

\forall t \in  [0,T], \quad \begin{cases}
h(t) \leq C(\kappa + A_1  \int_0^{t}  v(s)^{\varepsilon_1^+ \varepsilon_2^+} \, ds) \\
v(t) \leq C(\kappa + \frac{A_2}{\varepsilon_2^+} \int_0^{t}  h(s)^{\varepsilon_2^+} v(s)^{1-\varepsilon_2^+} \, ds),
\end{cases}
\end{equation}
then, for all $t \in [0,T]$,
$$h(t) \leq [(C\kappa)^{1/A_1} + C t]^{A_1}, \qquad v(t) \leq [(C\kappa)^{1/B_2} +Ct]^{B_2}, $$
where $B_2=\frac{A_2}{{\varepsilon_2}^+}$.
\end{enumerate}

