\begin{equation}
  \E\bigl(A(Z)P_3^m\bigr)
  =m!\,[z^m]A(z)(1+z)^{m-1}.
\end{equation}
Consequently,
\begin{equation}
  \E(P_3^m)=0,
  \qquad
  \E(Q_3P_3^m)=m!\neq0
  \qquad(m\geq1).
\end{equation}

