body:
[Theorem theo:intro of arXiv:2605.21265, 'The non-Hermitian minor process'] Consider the complex Ginibre minor process $X^{(xN)}$, and fix any $x,y\in (0,1]$ with $x\le y$. Let $f,g$ be smooth functions supported in the open disks\footnote{Here $\mathbf{D}_x:=\{z\in\mathbf{C}:|z|\le \sqrt{x}\}$.} $\mathbf{D}_x$, $\mathbf{D}_y$, respectively. Then, the linear statistics $L^{(xN)}(f), L^{(yN)}(g)$ converge jointly to centered Gaussian random variables $L(x,f), L(y,g)$, with covariance
\begin{equation}
\mathbf{E} L(x,f) L(y,g)= -\frac{1}{\pi^2} \int_{\mathbf{D}_x} \!\!\mathrm{d}^2 z\int_{\mathbf{D}_y}\!\!\mathrm{d}^2 w\,\, \overline{\partial_z f(z)}\partial_w g(w) \partial_z\partial_{\overline{w}} \log K\big((x,z),(y,w)\big),

\end{equation}
where $K$ is given by\footnote{Later in (equation eq:def_K of the paper) we extend the definition of $K$ to general $x,y\in(0,1]$.}
\begin{equation}
K\big((x,z),(y,w)\big):=|z-w|^2+|x-y|\left(1-\frac{|w|^2}{y}\right), \qquad z\in \mathbf{D}_x, \; w\in \mathbf{D}_y.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 34 of arXiv:2605.02002, 'Glauber dynamics for random field Ising models on bounded degree graphs and MLSI'] Suppose $G$ has $\alpha$-stretched-exponential growth for some $\alpha\in(0,1)$ and $\operatorname{WSM}(C)$ holds for RFIM $\mu_G$ for some $C>0$. Then for any fixed $\delta\in(0,1)$, with $\mathbb{P}_h$-probability at least $1-\delta$, we have the following inequality for all functions $\varphi:\{-1,+1\}^V\to\mathbb{R}$:
    \begin{equation}
\operatorname{Var}_{\mu_G}(\varphi)\leq K\delta^{-1/q}|V|^\kappa\mathcal{E}_{\mu_G}(\varphi,\varphi)^{1/p}\cdot\operatorname{osc}(\varphi)^{2/q},        
    \end{equation}
    where the constants $K,\kappa>0$ and $p,q\geq 1,1/p+1/q=1$ all depend on $C,C_\alpha,\alpha$ and $\beta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem upplow0 of arXiv:2607.19660, 'Smallest gaps between zeros of stationary Gaussian processes'] We have the following upper bound on $\Omega_k$,
	\begin{equation}
		\begin{split}&\tilde{\tau}_k(x_1,\ldots, x_k)  \\   \leq  &  R^{k}
			\int_{Rx_1+A_R} \cdots \int_{Rx_k+A_R} \rho_{2k}(Rx_1,y_1,\ldots, Rx_k,y_k)dy_1\cdots dy_k :=L(R),
		\end{split}
	\end{equation}where 
\begin{equation}
		A_R:=R^{-1/2}A= \big\{R^{-1/2}x:x\in A\big\}.
\end{equation}
	We also  have the following lower bound on $\tilde{\Omega}_k$, 
	\begin{equation}
		\begin{split}
			&	\quad\,\,\tilde{\tau}_k(x_1,\ldots, x_k)  \\&
			\geq  R^{k} 
			\int_{Rx_1+A_R} \cdots \int_{Rx_k+A_R} \rho_{2k}(Rx_1,y_1,\ldots, Rx_k,y_k)dy_1\cdots dy_k\\
			&-R^{k} 	\int_{Rx_1+A_R} \cdots \int_{Rx_k+A_R} \int_{D_2} \rho_{2k+1}(Rx_1,y_1,\ldots, Rx_k,y_k,z)dy_1\cdots dy_k dz\\
			&-R^{k} 	\int_{Rx_1+A_R} \cdots \int_{Rx_k+A_R} \int_{D_3} \rho_{2k+2}(Rx_1,y_1,\ldots, Rx_k,y_k,z_1,z_2)dy_1\cdots dy_k dz_1dz_2
			\\ &:= L(R)-E_2(R)-E_3(R).
		\end{split}
	\end{equation}

