[Theorem Th:Catastrofe_aleatoria of arXiv:2605.24671, 'Immigration Processes with Binomial Catastrophes and Random Survival Parameters'] Consider the process $C_{\mathrm{cat}}(\lambda,\nu)$ with $\lambda>0$, and suppose that the probability distribution $\nu$ on $[0,1]$ is not concentrated at $1$. Then:
\begin{enumerate}
    \item The process dies out almost surely.
    \item The expected number of catastrophes until extinction (which equals the expected time to extinction, see Remark~(E(T)=E(M) of the paper)) is finite and given by
    \begin{equation}
    \mathbb E(M_{C_{\mathrm{cat}}}) = -\frac{1}{\lambda} \frac{\mathcal{S}_\nu(\lambda)}{1 + \mathcal{S}_\nu(\lambda)} < \infty,
    \end{equation}
    where $\mathcal{S}_\nu(\lambda)$ is the analytic continuation of the alternating series
    \begin{equation}
    \mathcal{S}_\nu(\lambda) = \sum_{n=1}^\infty \frac{(-\lambda)^n}{\prod_{j=1}^n (1-\mathbb{E}[X^j])},
    \end{equation}
    with $X \sim \nu$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem_flow_3 of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] Under the assumptions of (lem_flow_1 of the paper), we have that for all $t\in [t_0,t_m]$,
    \begin{equation}
        \begin{aligned}
            \left\|\mathbb{E} L_{(1,2), t}-K_{(1,2), t}\right\|_2 \prec&~ \frac{\left(t_c-t_0\right)^2}{\left(t_c-t\right)^2}\left\|\mathbb{E} L_{(1,2), t_0}-K_{(1,2), t_0}\right\|_2\\
            &~+\frac{N^{-\varepsilon_g}}{N\left(t_c-t\right)^2\left(\operatorname{Im} m_t\right)^2}+\frac{N^{2 \varepsilon_g}}{N^2\left(t_c-t\right)^3\left(\operatorname{Im} m_t\right)^4}.
        \end{aligned}
    \end{equation}
    Combining this with (equation t_eta of the paper), (equation im_m_t_sim_through_evolution of the paper), and (equation largG_Ex of the paper), and using the definition of $t_m$, we obtain that for all $t\in\left[{t_0,t_m}\right]$,
    \begin{equation}
        \begin{aligned}
            \left\|\mathbb{E} L_{(1,2), t}-K_{(1,2), t}\right\|_2\prec&~ \frac{N^{-\tau_e\wedge\varepsilon_g}}{N\left(t_c-t\right)^2\left(\operatorname{Im} m_t\right)^2}+\frac{N^{-\varepsilon_g}}{N\left(t_c-t\right)^2\left(\operatorname{Im} m_t\right)^2}+\frac{N^{2 \varepsilon_g}}{N^2\left(t_c-t\right)^3\left(\operatorname{Im} m_t\right)^4}\\
            \sim&~ \frac{N^{-\tau_e\wedge\varepsilon_g}}{N\left(t_c-t\right)^2\left(\operatorname{Im} m_t\right)^2}.
        \end{aligned}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 of arXiv:2608.21701, 'Superdiffusivity of random walks on the three-dimensional randomly oriented Manhattan latt'] For every $n\ge1$ and every $\lambda>0$,
\begin{equation}

\llangle u,(\lambda-G_{2n})^{-1}u\rrangle\le\llangle u,(\lambda-G)^{-1}u\rrangle\le\llangle u,(\lambda-G_{2n+1})^{-1}u\rrangle.
\end{equation}

