[Proposition pr:gapprocess-tilt of arXiv:2607.21443, 'The critical KPZ scale for the averaging process'] Fix $k=2$. Then, for every $\beta\in \mathbb{R} $, the gap process $X\coloneqq R^1-R^2$ is a ${\rm CTRW}$ on $\mathbb{Z}$. Supposing that the gap process sits at $x \in \mathbb{Z}$, its evolution goes as follows:
\begin{enumerate}[(i)]
    \item if $x\neq 0,\pm 1$,  it  jumps to $x\pm 1$ with rate $\cosh(\beta)$;
    \item if $x=0$, it jumps to $\pm 1$ with rate $\frac12\cosh(\beta)$;
    \item if $x=\pm 1$, it jumps to $\pm 2$ with rate $\cosh(\beta)$, to $0$ with rate $\frac12\cosh(\beta)$, and to $\mp 1$ with rate $1/4$.
\end{enumerate}
As a consequence, the counting measure $\pi$ on $\mathbb{Z}$ is reversible for $X$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 2 (Asymptotic flatness) of arXiv:2605.20700, 'The maximum of a strongly \\ correlated Gaussian process'] We say that $K$ is asymptotically flat if there exists a function $w : \R^+ \to \R$ such that $K(x,y) \sim w(|x-y|)$ as $|x-y| \to \infty$, and which satisfies the following:  for every $\eta > 0$ there exists a $\beta > 0$ such that
\begin{equation}

  \limsup_{v \to \infty}  \sup_{u \in [v^{-\beta} , 1] } \Big| \frac{ w( u v) }{ w(v) } - 1 \Big| \le \eta  .
\end{equation}

[Theorem 33 (Adapted Brenier transport) of arXiv:2604.22159, 'Adapted optimal transport between filtered Gaussian processes'] Let $\bX = \bG^{a, L}$ and $\bY = \bG^{b, M}$ be elements of $\cFG$. Let $L_{t,t}^{\intercal} M_{t,t}$ have singular value decomposition $U_t \Sigma_t V_t^{\intercal}$. 
\begin{itemize}
\item[(i)] A Gaussian bicausal coupling $\pi^P$ of the form \eqref{eqn:joint.Gaussian}, where $P = \diag(P_1, \ldots, P_N)$ with $\|P_t\|_{2 \rightarrow 2} \leq 1$, is an adapted Brenier coupling of $(\bX, \bY)$ if and only if
\begin{equation}  
P_t \in \mathscr{P}( L_{t,t}^{\intercal} M_{t,t}), \quad t \in [N].
\end{equation}
Its transport cost is given by
\begin{equation} 
\bE_{\pi^P}[\|X - Y\|_2^2] = \|a- b\|_2^2 + \|L\|_{\mathrm{F}}^2 + \|M\|_{\mathrm{F}}^2 - 2 \sum_{t = 1}^N \tr ( (L^{\intercal} M)_{t,t} P_t ).
\end{equation}
When $L_{t,t}$ and $M_{t,t}$ are non-degenerate, the optimal $P$ is uniquely given by $P_t = V_t U_t^{\intercal}$.
\item[(ii)]  Write $U_t = \begin{bmatrix}U_{t,1} & U_{t,0}\end{bmatrix}$ and $V_t = \begin{bmatrix}V_{t,1} & V_{t,0}\end{bmatrix}$ as in Proposition \ref{prop:trace}(ii). The minimal transport cost
\begin{equation} 
\min_{\substack{P=\diag(P_1,\ldots,P_N)\\ P_t \in \mathscr{P}(L_{t,t}^{\intercal}M_{t,t})}}
\bE_{\pi^P}[\|X-Y\|_2^2]
\end{equation}
among all adapted Brenier couplings of the form $\pi^P$ is given by
\[
\|a - b\|_2^2 + \cD_{\mathrm{AB}}(L, M),
\]
where $\cD_{\mathrm{AB}}$ is the adapted Brenier divergence\footnote{We call this a divergence, rather than (squared) distance, because when $d \geq 2$, $\cD_{\mathrm{AB}}^{1/2}$ is not a (pseudo-)metric as can be shown by numerical examples.
} between $L$ and $M$ defined by
\begin{equation} 
\begin{split}
\cD_{\mathrm{AB}}(L, M) &:= \|L\|_{\mathrm{F}}^2 + \|M\|_{\mathrm{F}}^2 - 2 \sum_{t = 1}^N \Gamma_t(L, M), \quad \text{where}\\
\Gamma_t(L, M) &:= \max_{P_t \in \mathscr{P}( L_{t,t}^{\intercal} M_{t,t})} \tr \left( (L^{\intercal}M)_{t,t} P_t \right) \\
  &= \tr \left( U_{t,1}^{\intercal} (L^{\intercal}M)_{t,t} V_{t,1} \right) + \| U_{t,0}^{\intercal} (L^{\intercal} M)_{t,t} V_{t,0} \|_*.
\end{split}
\end{equation}
\item[(iii)] The adapted Brenier divergence admits the Procrustes representation
\begin{equation} 
\cD_{\mathrm{AB}}(L, M) = \min_{Q \in \mathscr{O}(N, d): Q_t \in \mathscr{P}( L_{t,t}^{\intercal} M_{t,t})} \|L - MQ\|_{\mathrm{F}}^2.
\end{equation}
\end{itemize}

[Lemma Rcont of arXiv:2411.06838, 'Generalized Wasserstein Barycenters'] Let $(\mu_n)_{n\in \mathbb{N}}\subset \mathcal{P}_2(H)$ be a sequence converging to $\mu \in \mathcal{P}_2(H)$ with respect to the (weak) topology of $\mathcal{P}_2^w(H)$ and let $(\nu_n)_{n\in \mathbb{N}}\subset \mathcal{P}_2(H)$ be a sequence converging to $\nu \in \mathcal{P}_2(H)$ with respect to the (strong) topology of $\mathcal{P}_2(H)$. 
Then, 
\begin{equation}

	\lim_{n \to \infty}\mathcal R (\nu_n,\mu_n)=\mathcal R (\nu,\mu).
\end{equation}

