[Lemma 17 of arXiv:2604.23461, 'Scaling limit of Sinkhorn-rescaled Random Matrices \\ via Stability of Static Schrödinger '] Let $\phi, \phi' \in L^{\infty}_{>0}(\mu_0 \otimes \mu_1)$ be probability densities with cost functions $\kappa$ and $\kappa'$. For $t \in [0, 1]$, let
	\begin{align}
		\sqrt{\phi_t} = t\sqrt{\phi} + (1-t)\sqrt{\phi'}. 
	\end{align} 
	There exists $g_t \in L^{\infty}(\mu_0 \otimes \mu_1)$, with $\norm{g_t}_{\infty} \leq e^{\tfrac{3}{2}\norm{\kappa^{+}}_{\infty} \vee \norm{(\kappa')^{+}}_{\infty}}$, and an orthogonal projection $P_t: L^2(\mu_0 \otimes \mu_1) \to L^2(\mu_0 \otimes \mu_1)$ so that 
	\begin{align}
		\partial \Gamma(\sqrt{\varphi_t}) = P_t\text{Diag}(g_t).
	\end{align} 
	Consequently, 
	\begin{align}
		\norm{\partial \Gamma(\sqrt{\varphi_t})f}_{L^2(\mu_0 \otimes \mu_1)} \leq e^{\tfrac{3}{2}(\norm{\kappa^{+}}_{\infty} \vee \norm{(\kappa')^{+}}_{\infty})}\norm{f}_{L^2(\mu_0 \otimes \mu_1)}.
	\end{align}
	for any $f \in L^{\infty}(\mu_0 \otimes \mu_1)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:finite-time-w1 of arXiv:2607.00149, '\bf Uniform-in-time Propagation-of-Chaos for\\ Stein Variational Gradient Descent'] Let Assumption~(ass:w1-normalized-matern of the paper) hold.  Then there exist constants $C_0,c_0<\infty$ such that, for any $R>0$, $N\ge3$ and all $t\ge0$,
\begin{equation}
        \mathbb E\Big[\sup_{0\le s\le t}
        W_1(\mu^N_s,\mu_s)\, \mathbf{1}_{\{\int \|x\|^2 \mu^N_0(dx) \le R\}}\Big]
        \le C_0N^{-\beta}\exp\{c_0(1+R)\exp(c_0t)\}.
\end{equation}

