[Lemma lem:massive-massless-continuous-correction of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] Fix a disk $U\Subset\mathbb R^2$ and $m_0>0$.  Write $\Delta_U$ for the
Dirichlet Laplacian on $U$ and set $L_0^U:=-(2\pi)^{-1}\Delta_U$.  Consider
a centered Gaussian field $Z_U$ with covariance operator
\begin{equation}
 \Cov(Z_U)=C_U^{(m_0)}
 :=(L_0^U)^{-1}-(L_0^U+m_0^2)^{-1}
 =m_0^2(L_0^U)^{-1}
   (L_0^U+m_0^2)^{-1}.

\end{equation}
Then $Z_U$ has a continuous version.  More precisely, for every $K\Subset U$
there is $C_{K,U,m_0}<\infty$ such that
\begin{equation}
 \mathbb E|Z_U(z)-Z_U(z')|^2
 \le C_{K,U,m_0}r^2
 \left(1+\log\frac1r\right),
 \qquad
 z,z'\in K,\quad 0<r:=|z-z'|\le\frac12.

\end{equation}

[Theorem 2 of arXiv:2606.25501, 'An RDT based approach to large deviations of Wishart and Wigner matrices spectral edges'] (\cite{Gordon85,Slep62})
 Let $X_{i}$ and $Y_{i}$, $1\leq i\leq n$, be two centered Gaussian processes which satisfy the following inequalities for all choices of indices
\begin{enumerate}
\item $\mE(X_{i}^2)=\mE(Y_{i}^2)$
\item $\mE(X_{i}X_{l})\leq \mE(Y_{i}Y_{l}), i\neq l$.
\end{enumerate}
 Then
\begin{equation*}
\mE(\min_{i} X_{i})\leq \mE(\min_i Y_{i}) \quad  \Longleftrightarrow \quad \mE(\max_{i} X_{i})\geq \mE(\max_i Y_{i}).
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition W_1 of arXiv:2411.04778, 'Coupling between Brownian motion and random walks on the infinite percolation cluster'] For every $\delta>0$ and $y\in \mathbb{Z}^d$, there exist finite positive constants $C$ and $s$ depending only on $d,\mathfrak{p},\delta$ and  a nonnegative $\omega$-measurable random variable $\mathcal{T}_\delta^{(1)}(y)$ satisfying
		\begin{equation}
			\forall T\geqslant 0, \qquad \mathbb{P}_{\mathfrak{p}}\left(\mathcal{T}^{(1)}_\delta (y)\geqslant T\right)\leqslant C \exp\left(-\frac{T^s}{C}\right),
		\end{equation}
		such that on the event $\{y\in\mathscr{C}_\infty\}$, when $t>\mathcal{T}^{(1)}_\delta(y)$, we have
		\begin{equation}
			W_1(p^\omega(t,\cdot+y,y), \bar{p}(t,\cdot))\leqslant K t^\delta,
		\end{equation}
		where $K$ is a finite positive constant depending on $d,\mathfrak{p},\delta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:SP of arXiv:2607.00800, 'Brownian motion in Minkowski normed spaces'] Let $a^0 = (a^0_{ij})_{1 \leq i,j \leq d}$ and $b^0 = (b^0_1,\ldots,b^0_d)$ consist of Borel measurable coefficients 
    \[
    a^0_{ij}, b^0_i: (0,\infty)\times \mathbb{R}^d \to \mathbb{R}
    \]
    such that $a^0$ is pointwise symmetric and non-negative definite.
    Suppose that $u: (0,\infty)\times \mathbb{R}^d \to [0,\infty)$ is a probability solution to the linear Fokker--Planck equation
    \begin{equation}
        \partial_t u(t,x) = \partial_{ij}\bigl(a^0_{ij}(t,x) u(t,x)\bigr) - \partial_i \bigl(b^0_i(t,x) u(t,x)\bigr)
    \end{equation}
with a probability measure-valued initial datum $\zeta$, satisfying
\begin{equation}
    a^0_{ij}, b^0_i \in L^1\bigl( [0,T]\times \mathbb{R}^d;u(t,x) \,\mathrm d x \mathrm d t \bigr),\quad \forall T>0.
\end{equation}

Then there exists a probabilistically weak solution $X = (X_t)_{t\geq 0}$ to the SDE
\begin{equation*}
    \mathrm d X_t = b^0(t,X_t) \,\mathrm d t + \sigma^0(t,X_t) \,\mathrm d W_t,
\end{equation*}

with $\sigma^0:(0,\infty)\times \mathbb{R}^d \to \mathbb{R}^{d\times d}$ such that $\sigma^0 (\sigma^0)^T = 2 a^0$, $\mathcal{L}(X_t) = u(t,x)\,\mathrm d x$ for all $t>0$, and $\mathcal{L}(X_0) = \zeta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

