[Theorem thm:flowpoincare of arXiv:2505.12187, 'Speeding up quantum Markov processes through lifting'] Let $P_t$ be a hypocoercive $C_0$-semigroup on $\mathcal{H}$ with the equilibrium subspace $\mathcal{F}$ as defined in (equation eq:mixsubspace of the paper). Suppose that Assumptions (assp:locoercive of the paper), (assmp:decomposition of the paper), and (assump:est1 of the paper) hold. Then, for any time horizon $T > 0$, and any $x_0 \in \mathcal{F}^\perp \cap \dom(\mathsf{L})$, there holds: 
\begin{align} 
  \alpha_T  \lVertx_t\rVert_{T, \mathcal{H}}^2 \le \mathcal{E}_{T, \mathsf{L}_S}(x_t)\,, \quad \alpha_T := \frac{1}{\gamma^2 C_0(T) + C_1(T)}\,, 
\end{align}
where $x_t: = P_t x_0$, and 
\begin{align*}
    & C_0(T): = 2 c_3^2 K_0^2\,, \\  & C_1(T): = 2 \left(s_{\rm M}^{1/2} \lambda_S^{-1/2} c_4  + K_3 c_2  +  \lambda_S^{-1/2} (K_1 c_1 + K_2 c_3) \right)^2 + \lambda_S^{-1}\,,
\end{align*}
where the constants $\{c_i\}_{i = 1,2,3,4}$ are given in (divergencelemma of the paper), $s_{\rm M}$ is defined in (equation eq:eigss of the paper), and constants $\{K_i\}_{i = 0,1,2,3}$ are given in (equation asspc0 of the paper)--(equation asspc2 of the paper) from (assump:est1 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm conv-DL-infty of arXiv:2411.16376, 'Higher order approximations in arcsine laws for subordinators'] Under the assumptions of Theorem $(Thm:potential-infty of the paper)$ with  $\alpha_0=\alpha\in[0,1]$, let us define a function $\varepsilon_2:(0,+\infty)\to\ensuremath{\mathbb{R}}$ by
\begin{align}
    \Pi((x,+\infty))=
    \mathbbm{1}_{\{\alpha>0\}}
    \frac{c_0 x^{-\alpha}}{\Gamma(1-\alpha)}+\varepsilon_2(x),
    \quad 0<x<+\infty.	
\end{align}
Set
\begin{align}
   \varepsilon_3(s,x)
   =
   s\Pi((s-sx,+\infty))\varepsilon_1(sx),
   \quad 0<s, x<+\infty.	
\end{align}
Then, for $s\in(0,+\infty)$, the finite measure 
\begin{align}
\ensuremath{\mathbb{P}}\bigg(\frac{X_{T(s)-}}{s}\in dx,\; 0<\frac{X_{T(s)-}}{s}<1\bigg),
\quad
0<x<1,
\end{align}
 admits a density expressed in the form
\begin{align}
   s\Pi(&(s-sx,+\infty))u(sx)
   \\
   =\,&\frac{\sin(\pi \alpha)}{\pi}x^{-1+\alpha}(1-x)^{-\alpha}
   +
    \mathbbm{1}_{\{\alpha>0\}}
   \sum_{k=1}^n
   \frac{c_0 s^{\alpha_k-\alpha}}{c_k\Gamma(\alpha_k)\Gamma(1-\alpha)}x^{-1+\alpha_k}(1-x)^{-\alpha}
   \\
   &+\sum_{k=0}^n\frac{s^{\alpha_k}}{c_k\Gamma(\alpha_k)}
   x^{-1+\alpha_k}\varepsilon_2(s-sx)
   +
   O(\varepsilon_3(s,x)),
   \quad
   \text{as $s\to+\infty$,}

\end{align}
uniformly in $x\in I$ for any closed interval $I\subset (0,1)$. 
Therefore, for any closed interval $I\subset (0,1)$,
\begin{align}
	\ensuremath{\mathbb{P}}\bigg(&\frac{X_{T(s)-}}{s}\in I\bigg)
	\\
	=
	\,&\frac{\sin(\pi \alpha)}{\pi}\int_I x^{-1+\alpha}(1-x)^{-\alpha}\,dx
	\\
	&+
	 \mathbbm{1}_{\{\alpha>0\}}
	\sum_{k=1}^n
   \frac{c_0 s^{\alpha_k-\alpha}}{c_k\Gamma(\alpha_k)\Gamma(1-\alpha)}
   \int_I x^{-1+\alpha_k}(1-x)^{-\alpha}\,dx
   \\
   &+\sum_{k=0}^n\frac{s^{\alpha_k}}{c_k\Gamma(\alpha_k)}
   \int_I
   x^{-1+\alpha_k}\varepsilon_2(s-sx)\,dx
   +
  O\bigg(\sup_{x\in I}\varepsilon_3(s,x)\bigg),
   \quad
   \text{as $s\to+\infty$}.

\end{align}

\begin{Rem}
By Remark (Rem:Pi-infty of the paper), if $0<\alpha<1$, then $\varepsilon_2(x)=o(x^{-\alpha})$, as $x\to+\infty$.	
\end{Rem} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem volt-05 of arXiv:2606.25336, '\bfseries Invariant Measures of L\'evy-driven Stochastic Differential Equations'] Assume \textup{(A1)}, \textup{(A2)} and  \textup{(A3)}.  The equation $L^*\rho = 0$ in $\mathcal{S}'({\mathds{R}^d})$ is equivalent to
	\begin{gather}
		\operatorname{div}\left(b_\ell\rho\right) = \operatorname{div}\left(\nabla\widetilde{\psi}(D)(-\Delta)^{-1}\rho\right)
		\quad\text{in}\quad \mathcal{S}'({\mathds{R}^d}).
	\end{gather}
	Moreover, 
	\begin{enumerate} 
		\item
		if $\rho\in L_1$ is a solution in $\mathcal{S}'({\mathds{R}^d})$ either to
		\begin{gather}
			(b_\ell\rho)^{\mathsf{irr}} = \nabla K * \rho,
			\intertext{or to}
			(b_\ell\rho) = \nabla K * \rho,
		\end{gather}
		then the measure $\pi(dx) = \rho(x)\,dx$ satisfies (equation intro-e18 of the paper), i.e.\ it is \textup{(}infinitesimally\textup{)} invariant for the operator $L$.

		\item
		if the measure $\pi(dx) = \rho(x)\,dx$ satisfies (equation intro-e18 of the paper), and if one of the following conditions hold
		\begin{description}
			\item[i)] $d=1$;
			\item[ii)]
			$d=2$,   $\rho \in W^{1,1}\cap W^{1,\infty}$  and  $ \rho b_\ell  \in C^{1,\alpha}({\mathds{R}^d},{\mathds{R}^d})$  for some $\alpha\in (0,1]$,  $\operatorname{div}(\rho b_\ell)\in L_\infty$ and $\Lambda^\epsilon\operatorname{div}(\rho b_\ell)\in L_1$ for some $\epsilon>0$;
			\item[iii)]
			$d\geq 3$,  $\rho \in W^{1,1}\cap W^{1,\infty}$,  $\rho b_\ell  \in C^{ 1,\alpha}({\mathds{R}^d},{\mathds{R}^d})$ for some $\alpha\in (0,1]$ and $\operatorname{div}(\rho b_\ell)\in L_1 \cap L_\infty$;  
			\item[iv)]  
			$d \geq 3$, $\rho\in L_2$, $\rho b_\ell \in  C^{1,\alpha}({\mathds{R}^d},{\mathds{R}^d})\cap L_1\cap L_2$  and $\operatorname{div}(\rho b_\ell)\in L_1$;
		\end{description}  
		then $\rho$ satisfies (equation volt-e06a of the paper) in $\mathcal{S}'({\mathds{R}^d})$. 
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

