[Prop approx_hyper of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] For $\mathsf{P}\in \mathcal P_{s,1}(\Gamma)$ with $\mathcal W^{elec}(\mathsf{P})<\infty$ there exists  $(\mathsf{P}^N)_{N\geq 1}\in \mathcal P_{s,1}(\Gamma)$ with
    $\mathsf{P}^N\xrightarrow{N\to \infty}\mathsf{P}$ weakly and 
    \begin{align*}
        \mathcal E(\mathsf{P}^N)\xrightarrow{N\to \infty}\mathcal E(\mathsf{P})
    \end{align*}and \begin{align*}
       \limsup_{N\to \infty}\limsup_{n\to \infty} (nN)^{-1}\left(\mathcal H(\mathsf{P}^N,nN)-B_{nN}\right)\leq \mathcal W^{elec}(\mathsf{P}). 
    \end{align*}
    Moreover, $\mathcal W^{mod}(\mathsf{P}^N)\to \mathcal W^{elec}(\mathsf{P})$ as $N\to \infty$.
    For $\xi \in \supp(\mathsf{P}^N)$ and $x\in \xi$ we have
    \begin{align}
    \inf\{y\in \supp(\xi):y>x\}-x\leq 2N.
    \end{align}
    Finally, it holds that $\int \xi(\Lambda_1)^2\mathsf{P}^N(d\xi)<\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor eq:liminf_geq_J of arXiv:2411.04690, 'Asymptotic distribution of the derivative of the taut string accompanying Wiener process'] Let $\varphi$ be either an almost everywhere continuous non-negative or a convex function. 
Then for every $r>0$
  \begin{equation}

     \liminf_{T\to\infty} \frac{1}{T}  \int_0^T \varphi(\eta'_{T,r}(t))\, dt
     \stackrel{\text{a.s.}}{\geq} \int\limits_{\mathbb{R}} \varphi(u)  p_{\infty,r}(u)\, du .   
  \end{equation}

[Proposition 3 (cf.\ Section 2 of \cite{Chen2024}) of arXiv:2608.26598, 'Pinching cones for positive isotropic curvature in dimensions seven and eight'] If $S$ evolves by \eqref{eq:pullback-ode}, then
    \begin{equation}
        \begin{split}
            \dt\Ric(S)={}&2\bigl(S*\Ric(S)\bigr)-4b\,\Ric(S)^2
            +\frac4n\bigl(2b+(n-2)a\bigr)\Scal(S)\Ric(S)\\
            &+2\,\frac{n^2b^2-2(n-1)(a-b)(1-2b)}{n\bigl(1+2(n-1)a\bigr)}\,|\Rico(S)|^2\mathrm{id}
            +\frac4{n^2}(a-b)\Scal(S)^2\mathrm{id},
        \end{split}
    \end{equation}
    where $(S*\Ric)_{ik}=\sum_{p,q}S_{ipkq}\Ric_{pq}$, and $\dt\Scal(S)$ is given by
    \eqref{eq:scalar-evol}. In particular, $P+nQ=2+4(n-1)a$.

[Prop unsommetvide of arXiv:2606.24793, '\LARGE Random sequential nearest-neighbor coloring on trees'] Let $\eta>0$. Then, there exist $H,C,N,n_0\ge 0$ such that, if $|T|\ge n_0$, then for any choice of vertices $w_1,\ldots,w_C$ of height greater than or equal to $|T|-2H$, starting from $B_0=\{o\}$ and $R_0=\partial T \cup\{w_1,\ldots,w_C\}$, we have
\begin{equation*}
 \mathbb{P}(\forall 1\le i\le N,\; \mathcal{A}_i^c)\le \eta.
\end{equation*}

[Lemma 16 of arXiv:2604.19924, 'Fluctuation theory for spectrally negative Lévy processes killed by additive functionals'] The function $Z^{(q)}_{
u}$ defined in \eqref{sf_Z} is the unique solution to the integral equation
	 egin{align}
		Z^{(q)}_{
u}(x,c)=Z^{(q)}(x-c)+\int_{[c,x]}W^{(q)}(x-u)Z^{(q)}_{
u}(u,c)
u(du),\qquad x\geq c.
	\end{align}

[Proposition 21 of arXiv:2608.30077, 'Lie groupoid integration of singular isometries of the Poincaré disk'] The map $\Phi:\mathcal{G}_n'\longrightarrow\mathcal{G}(\mathcal{A}_n),$ defined as
\begin{equation*}
\Phi\big([(u,z)]\big)=\big[a(t)\big],
\end{equation*}
with $a(t)=(X(t),z(t))$ such that
\begin{align*}
z(t)^n=u(t)\cdot z^n,\qquad
X(t) &\coloneqq u'(t)u(t)^{-1},
\end{align*}
is a Lie groupoid isomorphism.

