body:
[Lemma lem:Psi-structure of arXiv:2608.30904, 'Entire monotone solutions of the anisotropic Allen--Cahn equation in dimension 5'] In the frame $\{e_0,e_x,e_y\}$,
\begin{equation}
 \Psi_F(\nu)
 =\begin{pmatrix}
 \nu_y^{-3}\phi''(z)&0&0\\
 0&\nu_x^{-1}\phi'(z)&0\\
 0&0&\nu_y^{-1}(\phi(z)-z\phi'(z))
 \end{pmatrix}
\end{equation}
where $z=|\nu_x|/|\nu_y|$. In particular, on the Clifford cone,
\begin{equation}
 \Psi_F(\nu_{\mathcal C})
 =\frac{\sqrt2}{2}
 \operatorname{diag}\!\left(4\phi''(1),1,1\right).
\end{equation}

[Theorem 2 (Predictive regret under posterior approximation) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] Under \cref{ass:predictive-stability},
    \begin{equation}
    \fR\del[1]{(Q_t)_{t=0}^{T-1}}
    \le
    \fR\del[1]{(\Pi_t)_{t=0}^{T-1}}
    +L_{\cM} \sum_{t=1}^{T-1}\cbr{\varepsilon_t\alpha_t+\alpha_t^2}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2511.02725, 'Mixing of general biased adjacent transposition chains'] Suppose $\vec{p}$ is $\eps$-positively biased and $\vec{\ell}\in \mathcal L_n$. For every $k\ge 1$, 
    \begin{align*}
        \mu(\sigma(1)\notin [k] \mid \sigma \in \vec{\ell}\loc)\le \frac{1}{(1+\eps)^k}\,.
    \end{align*}
    Hence, the particle label at location $1$ is stochastically dominated by a $\text{Geom}(\frac{\eps}{1+\eps})$ random variable.

[Prop 10 of arXiv:2607.06745, 'Regularization and asymptotic behaviour of Ornstein-Uhlenbeck evolution operators in infin'] For every $t>s$, the following inclusions hold:
\begin{align*}
 & \overrightarrow{\overrightarrow{P_{s,t}}}\left(C_{b}\left(X;\mathcal{L}\left(X\right)\right)\right)\subseteq C_{b}\left(X;\mathcal{L}\left(X\right)\right),\\
 & \overrightarrow{P_{s,t}}\left(C_{b}^{1}\left(X;X\right)\right)\subseteq C_{b}^{1}\left(X;X\right),
\end{align*}
and for every $\Phi\in C_{b}^{1}\left(X;X\right)$:
\begin{equation}
\nabla_{\mathcal{L}}\overrightarrow{P_{s,t}}\Phi\left(x\right)=\left[\overrightarrow{\overrightarrow{P_{s,t}}}\nabla_{\mathcal{L}}\Phi\right]\left(x\right)U\left(t,s\right).
\end{equation}

