\begin{equation*}
	\phi'(z)=m\int_1^z \frac{(1+s)^{m-1}}{s}\,\rd s\le m 2^{m-1}\int_1^z s^{m-2}\,\rd s
\end{equation*}
while
\begin{equation*}
	\phi'(z)=m\int_1^z \frac{(1+s)^{m-1}}{s}\,\rd s\ge m\int_1^z s^{m-2}\,\rd s\,.
\end{equation*}
