[Theorem 2 of arXiv:2607.22878, 'Clustering of large deviations in heavy-tailed moving averages: the catastrophe principle '] Suppose that both $\Gamma$ and $\Psi$ satisfy
Assumption~\ref{ass:tail_measure}. 
Then for any $\theta_1,\theta_2>0$,
\begin{equation}
\begin{aligned}
    &\lim_{n\to\infty} 
    \PP\big(J_n^{\Psi,+} > n\theta_1,\, J_n^{\Psi,-} < -n\theta_2 \,\big|\, E_0(n,\Gamma)\big) \\
    &\quad= 
    \frac{\int_{-\infty}^\infty  \;
        \nu\!\Big(B_y^{-1} \Gamma \cap \bigcap^*_{-\theta_2\le t \le \theta_1} \!\!  B_{y-t}^{-1}\Psi\Big) dy}
        {\int_{-\infty}^\infty \nu(B_y^{-1} \Gamma) \,dy},
\end{aligned}
\end{equation}
where $\cap^*_{t\in A}$ stands for the intersection over all rational
$t\in A$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm sum over surfaces representation in 't hooft limit of arXiv:2508.13827, 'Surface sums in two-dimensional large-$N$ lattice Yang--Mills: Cancellations and explicit '] {borga2024surfacesumslatticeyangmills}}]
There exists a number $\upbeta_0>0$ such that the following is true. Let $\Lambda_1\subseteq\Lambda_2\subseteq\hdots$ be any sequence of finite subsets of the lattice $\mathbb{Z}^2$ such that $\mathbb{Z}^2 = \cup_{N=1}^{\infty}\Lambda_N$. If $|\upbeta|\leq \upbeta_0$, then for any string $s=\{\ell_1,\dots,\ell_n\}$,
	\begin{align}
		\lim_{N\to\infty}\phi_{\Lambda_N,N,\upbeta}(s) =
		\prod_{i=1}^n\phi(\ell_i),
	\end{align}
	where
	\begin{equation}
		\phi(\ell)=\sum_{K:\mathcal{P}_{\mathbb{Z}^2}\to\mathbb{Z}_{\geq 0}} \phi^K(\ell), \quad\text{with}\quad \phi^K(\ell)=\sum_{M\in\mathcal{N}\mathcal{P}\mathcal{M}(\ell,K)}\upbeta^{\area(K)}w_{\infty}(M).
	\end{equation}
	Here, $\area(K)= \sum_{p\in \mathcal{P}}K(p)$, the set $\mathcal{N}\mathcal{P}\mathcal{M}(\ell,K)$ is a certain collection of connected planar maps with the disk topology and $w_{\infty}(M)$ is a specific (positive or negative) weight associated with each map $M$.\footnote{We do not need the precise (and somewhat lengthy) definitions of the set $\mathcal{N}\mathcal{P}\mathcal{M}(\ell, K)$ and the weights $w_{\infty}(M)$ in this paper; interested readers can refer to the original paper for details. See also the discussion around (equation eq:mle-2 of the paper) for further explanation of why the precise definitions of the set $\mathcal{N}\mathcal{P}\mathcal{M}(\ell, K)$ and the weights $w_{\infty}(M)$ are not needed here.}

The infinite sum $\phi(\ell)$ is only over finite plaquette assignments $K:\mathcal{P}_{\mathbb{Z}^2}\to\mathbb{Z}_{\geq 0}$, i.e.\ plaquette assignments such that $\sum_{p\in\mathcal{P}_{\mathbb{Z}^2}}K(p)<\infty$. Moreover, the infinite sum $\phi(\ell)$ is absolutely convergent.\footnote{The sum $\phi^K(\ell)$ is a finite sum for all $K$ and $\ell$.} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 21 of arXiv:2604.27242, 'Statistical Inference for Homogenization Limits Driven by Wiener or Hermite Processes'] The following asymptotics hold as \(N\) grows
\begin{enumerate}
    \item If \(\alpha\in(-1,0)\): \begin{equation}
        \f{1}{N}\sum_{k=1}^{N-1}(1-k/N)(k/N)^{\alpha} \sim \f{1}{\alpha+1} - \f{1}{\alpha+2}
    \end{equation}
    \item If \(\alpha = -1\): \begin{equation}
        \f{1}{N}\sum_{k=1}^{N-1}(1-k/N)(k/N)^{-1} = \log(N) + \gamma - 1 + \frac{1}{2N} + o(N^{-2})
    \end{equation}
    \item If \(\alpha<-1\): \begin{equation}
        \f{1}{N}\sum_{k=1}^{N-1}(1-k/N)(k/N)^{\alpha} \sim \zeta(-\alpha)(1/N)^{\alpha+1}
    \end{equation}
    where \(\zeta(\cdot)\) is the Riemann zeta function.
\end{enumerate}

