[Proposition 9 of arXiv:2606.24485, 'On the convex hull of a planar Brownian bridge with a random Gaussian endpoint'] For $0\le\sigma\le1$,
	\begin{equation}
		\E [M_\sigma'(0)^2]
		=
		\frac{3\sigma^3+\sigma^2+\sigma+1}{6(\sigma+1)}.
	\end{equation}

[Thm intro-thm-3 of arXiv:2608.30518, 'Grow-up rates of inhomogeneous semilinear heat equations in the critical dimension'] Assume the hypotheses of Theorem (intro-thm-2 of the paper). Let $\Phi:=u^{*}-u$ and $\varphi_1>0$ be the principal eigenfunction of $\mathcal{L}$ with $\|\varphi_1 \|_{L^2(B_1)}=1$. 
Then, there exist $M,C,T>0$ depending only on $u_0$ and $f$ such that 
\begin{equation*}
\frac{1}{C}e^{-\mu_1 t}\Bigl(\zeta_2(t)\varphi_1+\nu |\zeta_2'(t)|r^{-4}\log r \Bigr)- Me^{-\mu_1 t}|\zeta_2'(t)| \varphi_1 \le \Phi \quad \text{in $B_1\times (T,\infty)$}
\end{equation*}
and
\begin{equation*}
   \Phi \le C e^{-\mu_1 t}\Bigl(\zeta_1(t)\varphi_1-\nu |\zeta_1'(t)| r^{-4}\Gamma(r,t) \Bigr) \quad \text{in $B_1 \times (T,\infty)$.}
\end{equation*}
Here, $\Gamma=\Gamma(r,t)$ is a smooth regularization of $-\log r$ near $r=0$ defined in (equation defGam of the paper). The functions $\zeta_1$ and $\zeta_2$ are defined in Lemma (zetalem of the paper), and the constant $\nu>0$ is defined in (equation defb of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[1 8 (\cite{HX24b}) of arXiv:2606.10058, 'Mean First Passage Times and Fundamental Tensors of Higher Order Markov Chains'] Let $i$ be an absorbing state of the chain $X$. Then, for any $k \ge 1$ and $i_3, \ldots, i_m \in S$, 
$p^{(k)}_{iii_3\ldots i_m}=1$, i.e., 
\be

p^{(k)}_{i_1ii_3\ldots i_m}=\delta_{i_1i}
\ee
for any $i_1, i_3, \ldots, i_m \in S$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 22 of arXiv:2604.23656, 'Doubly Reflected Backward SDEs Driven by $G$-Brownian Motion with Quadratic Generator'] For any $\alpha\geq 1$, There exist two constants $C$, $C_\alpha$ independent of $m,n$, such that 
    \begin{align*}
        \|A^{n,m,-}\|_{L^\infty_G}\leq C,  \ \|Z^{n,m}\|_{BMO_G}\leq C, \  \hat{\E}[|A^{n,m,+}_T|^\alpha]\leq C_\alpha, \ \hat{\E}[|K^{n,m}_T|^\alpha]\leq C_\alpha.
    \end{align*}

[Proposition prop:finite-rational of arXiv:2604.25108, 'Terminal Defects, Growing Multiplicity, and Variance Extremality\\in the Double Dixie Cup '] Let $A$ range over nonempty subsets of $[N]$, put $p_A=\sum_{i\in A}p_i$, and for $\alpha=(\alpha_i)_{i\in A}\in\{0,\ldots,m-1\}^A$ write
\[
        |\alpha|=\sum_{i\in A}\alpha_i,
        \qquad
        \alpha!=\prod_{i\in A}\alpha_i!,
        \qquad
        p^\alpha=\prod_{i\in A}p_i^{\alpha_i}.
\]
Then for every integer $r\ge1$,
\begin{equation}
        \mathbb E\bigl[T_{m,p}^{(r)}\bigr]
        =r\sum_{\emptyset\ne A\subseteq[N]}(-1)^{|A|+1}
        \sum_{\alpha\in\{0,\ldots,m-1\}^A}
        {\frac{p^\alpha}{\alpha!}}
        {\frac{(|\alpha|+r-1)!}{p_A^{|\alpha|+r}}}.
\end{equation}

[Theorem 16 of arXiv:2608.12291, 'When should one stop the most exciting game?\\ {\tiny Sequential Inference for win-marting'] The following holds for the optimal stopping problem in \eqref{eq:InfHorizonProblem_hom}: 
    \begin{enumerate}
        \item[(i)] If Assumptions \ref{asmp:state_dynamics}-\ref{asmp:Lg:unimodal} and $\mathcal{L}g(x_0)\geq -c$ hold, then $V\equiv g$.
        \item[(ii)] Under Assumption \ref{asmp:baseline}, the optimal solution is given by
        \begin{equation*}
            V(x)=\begin{cases}
                \widehat V_{A^*}(x),   & x\in(A^*,B^*)\\
                g(x),       & x\in[0,A^*]\cup[B^*,1],
            \end{cases}
        \end{equation*}
        where $\widehat V_{A^*}(x)$ is given by \eqref{ValueGivenA}, and $A^*$ and $B^*$ form the unique solution pair to the equations \eqref{hprime} and \eqref{hsecant}.
    \end{enumerate}

