body:
[Lemma 16 (Finite-variation increment estimates) of arXiv:2608.16256, 'Error Distribution of the Local Linearization Method for Stochastic Differential Equations'] \label[lemma]{le:theta_estimates}
For every \(\rho>0\),
\begin{equation}
    \Exp*{}{
        \int_0^{\tau_{n,\rho}}|\theta_s^n|^2\,ds
    }
    \le
    C_\rho n^{-2} .
\end{equation}
Moreover,
\begin{equation}
    \Exp*{}{
        n\sqrt n
        \int_0^{\tau_{n,\rho}}
        |\theta_s^{n,(2)}|\,|\eta_s^n|\,ds
    }
    \le
    C_\rho n^{-1/2},
\end{equation}
and
\begin{equation}
    \Exp*{}{
        n\sqrt n
        \int_0^{\tau_{n,\rho}}
        |\theta_s^{n,(3)}|\,|\eta_s^n|\,ds
    }
    \le
    C_\rho n^{-1} .
\end{equation}

[Definition Def: grafting of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] For $\tau\in{\mathcal T}, w\in{\mathcal F}$ we recursively define the grafting of trees in $\mathcal{H}$ as
		\begin{equation}
			\tau\curvearrowright\one=0\,,\qquad\tau\curvearrowright [w]_i=[\tau\cdot w+\tau\curvearrowright w]_i\,,\qquad i=1,\ldots, d\,,
		\end{equation}
		where we implicitly extend $\curvearrowright$ to forests on the right by Leibniz rule, i.e, for $\tau_1,\ldots, \tau_k\in{\mathcal T}$
		\begin{equation}
			\tau\curvearrowright(\tau_1\cdots\tau_k)=\sum_{i=1}^k\tau_1\cdots(\tau\curvearrowright\tau_i)\cdots\tau_k\,.
		\end{equation}

[Theorem thm:vertical_decoupling of arXiv:2607.22908, 'Epidemic Phase Transitions in the Zero-Range Process'] There exist positive constants $C_{\textnormal{\tiny (C:vertical_decoupling of the paper)}}$, $c_{\textnormal{\tiny (c:vertical_decoupling of the paper)}}$ and $C_{\textnormal{\tiny (C:V of the paper)}}$ depending only on the dimension and $\Gamma_+$ and $\Gamma_-$, such that, for any two space-time boxes $B^1,B^2$ of side length $w>0$ with vertical distance $\dist_V = \dist_V(B^1, B^2) \ge C_{\textnormal{\tiny (C:V of the paper)}}$, any two non-decreasing bounded measurable functions $f_1, f_2: \mathbb{N}_0^{\mathbb{Z}^d \times \mathbb{R}_+} \to [0, 1]$ with supports in $B^1$ and $B^2$, any $\rho >0$, and any sprinkling increment $\varepsilon \in (0,1)$, we have
  \begin{equation}

    \begin{split}
    \mathbb{E}_\rho & [f_1(\eta) f_2(\eta)] - \mathbb{E}_{\rho(1 + \varepsilon)}[f_1(\eta)] \mathbb{E}_{\rho(1 + \varepsilon)}[f_2(\eta)] \\
    &\quad \leq C_{\textnormal{\tiny (C:vertical_decoupling of the paper)}} (w + \dist_V)^{d + 1} \Big(\rho \exp\braces{-c_{\textnormal{\tiny (c:vertical_decoupling of the paper)}} \dist_V^{1/3}} + \exp\braces{-c_{\textnormal{\tiny (c:vertical_decoupling of the paper)}} \rho\varepsilon^2 \dist_V^{1/3}}\Big).
    \end{split}
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 of arXiv:2608.04853, 'Minimal-Norm Extensions of Stationary Kernels on Subgroups of Locally Compact Abelian Grou'] Let $H \subseteq G$ be a closed subgroup. Given a stationary kernel $k$ on $G$, the spectral density $\hat{k}_H:\hat{H} \to \R$ of the restricted kernel is given by 
\begin{align*}
    \hat{k}_H(\xi_H)= \int_{H^\perp} \hat{k}(\xi_H+\xi^\perp) \d \xi^\perp.
\end{align*}
If 
\begin{align}
    \sup_{\xi_H \in \hat{G}/H^\perp} \int_{H^\perp} \hat{k}(\xi_H + \xi^\perp) \d \xi^\perp < \infty,
\end{align}
additionally holds, then $\mathcal{N}(H) \subseteq L^2(H)$. 

If $G$ is compact, \eqref{eq:L2Condition} is satisfied.

