[Proposition 6 ($L_p$-estimate, $1< p \leqslant +\infty$) of arXiv:2604.24392, 'Numerical approximation of Markovian BSDEs in infinite horizon and elliptic PDEs'] ~

Assume  \eqref{as:generatorf}, \eqref{as:b:sigma} and \eqref{as:int:X:nablaX}.
\begin{description} 
\item [$\rhd$ The case $p=+\infty$.] Assume \eqref{as:suprho}, $a>\theta$, $\ta>\ttheta$ and $c_{\infty,\eqref{eq:condition:normA:rho}} \vee \tilde{c}_{\infty,\eqref{eq:condition:normA:rho}} < +\infty$. Then, for any functions $w_1$, $w_2$ in $C^0(\bR^d, \bR^{d'}\times \bR^{d'\times d})$, we have
\begin{align*}
\normr{\Phi(w_1)-\Phi(w_2)}\leqslant  \kappa_\infty \normr{w_1-w_2},
\end{align*}
where 
{$$\kappa_\infty = \sqrt{ c_{\infty,\eqref{eq:condition:normA:rho}}^2  \left(\sqrt{K_{f,y}^2 - 2\mu a + a^2} \lor  K_{f,z} \right)^2 + \tilde{c}_{\infty,\eqref{eq:condition:normA:rho}}^2 \left(\sqrt{K_{f,y}^2 - 2\mu \ta + \ta^2} \lor K_{f,z} \right)^2}. $$}
\item [$\rhd$ The case $p\in (1,+\infty)$.] 
Assume that there exist finite positive constants $c_{p,\eqref{eq:condition:stability:rho}}$, $\tilde{c}_{p,\eqref{eq:condition:stability:rho}}$, $\tilde{c}_{p,\eqref{eq:condition:stability:rho:bis}}$ {and a probability measure $\meas$ on $\bR^d$}, satisfying $\int_{\mathbb{R}^d} |x|^r \meas(\dx)<+\infty$, such that for any measurable function $w:\bR^d \to \bR^{d'}\times \bR^{d'\times d}$ with a polynomial growth $r$ we have
\begin{equation}
\begin{aligned}

\left(\int_{\bR^d} \E{ {\norm{w(\xxe)} }^p} \meas(\dx) \right)^{1/p} &\leqslant 
c_{p,\eqref{eq:condition:stability:rho}} \left(\int_{\bR^d} {\norm{w(x)}}^p \meas(\dx)\right)^{1/p}<+\infty, \\
\left(\int_{\bR^d} \E{ {\norm{w(\xxet)} }^p} \meas(\dx) \right)^{1/p} &\leqslant 
\tilde{c}_{p,\eqref{eq:condition:stability:rho}} \left(\int_{\bR^d} {\norm{w(x)}}^p \meas(\dx)\right)^{1/p}<+\infty,
\end{aligned}
\end{equation}
and 
\begin{equation}

\sup_{x \in \bR^d}\Exp{\left|\sqrt{\frac{\pi}{\ttheta}}U_\tE^x \sqrt{\tE}e^{-(\ta-\ttheta)\tE}\right|^{\frac{p}{p-1}}}^{p-1} = \tilde{c}_{p,\eqref{eq:condition:stability:rho:bis}}<+\infty.
\end{equation}

Then, for any measurable functions $w_1,w_2 : \bR^d \to \bR^{d'}\times \bR^{d'\times d}$ with a polynomial growth $r$, we have
\begin{align}
\left(\int_{\bR^d} { \norm{\Phi(w_1)(x)-\Phi(w_2)(x)}} ^p \meas(\dx)\right)^\frac{1}{p } &\leqslant 
  \kappa_p \left(\int_{\bR^d} { \norm{w_1(x)-w_2(x)}}^p \meas(\dx)\right)^\frac{1}{p},
\end{align}
where
\begin{align}

\kappa_p =& \Bigg( \dfrac{1}{\theta}\left(\dfrac{p-1}{ap-\theta}\right)^{p-1}c_{p,\eqref{eq:condition:stability:rho}}^p  \left(\sqrt{K_{f,y}^2 - 2\mu a + a^2} \vee K_{f,z} \right)^p  \\
&  +\tilde{c}_{p,\eqref{eq:condition:stability:rho:bis}} \tilde{c}_{p,\eqref{eq:condition:stability:rho}}^p  \left(\sqrt{K_{f,y}^2 - 2\mu \ta + \ta^2} \vee K_{f,z} \right)^p \Bigg)^\frac{1}{p}.
\end{align}
\end{description}

