{"artifact_digest":"sha256:5ada783a8bfe018403feeb8f63d85ce0408c898a6a779cd8738f3bcf7beabc70","artifact_path":"objects/sha256/5a/5ada783a8bfe018403feeb8f63d85ce0408c898a6a779cd8738f3bcf7beabc70.md","bundle_digest":"sha256:d03a98ed318e435227783962eea32d93f3393421dbdce6c9fa87bdaac6cbe5ad","bundle_entry_key":"2601-04079-theorem-5-pb-tv-symmetric-bcv","bundle_id":"population.tex-extract-s0_097","claim_kind":"theorem","conditions":[],"domain":"probability theory","draft":"tex-extract-v2-20260907/bundle_s0_097.json","evidence_ids":[],"logical_id":"math:harvest.arxiv.mathematics:arxiv-2601-04079-theorem-5-pb-tv-symmetric-bcv","overlay_schema_version":1,"proof_text":"Paper's own proof, opening: The proof uses three standard ingredients.

