{"artifact_digest":"sha256:fa6de45ffc30924f4ce77555b1cd69cfecc75065d12809979cf1e97a034e1115","artifact_path":"objects/sha256/fa/fa6de45ffc30924f4ce77555b1cd69cfecc75065d12809979cf1e97a034e1115.md","bundle_digest":"sha256:d05a680ed878a7d299e8b402a54cb266f3962f9e1541bc5620259cafd043b5c2","bundle_entry_key":"2608-02772-theorem-82-diamond-gauge-equiv-nahm","bundle_id":"population.tex-extract-s0_113","claim_kind":"theorem","conditions":[],"domain":"probability theory","draft":"tex-extract-v2-20260907/bundle_s0_113.json","evidence_ids":[],"logical_id":"math:harvest.arxiv.mathematics:arxiv-2608-02772-corollary-82-diamond-gauge-equiv-nahm","overlay_schema_version":1,"proof_text":"Paper's own proof, opening: \noindent\textit{Explicit form.}
