[Definition ESM of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] Given an Hermitian matrix $H\in M^n(\mathbb{C})$, the ESM of $H$ is defined as:
    \begin{equation*}
        \mu_H:=\frac{1}{n}\sum_{j=1}^n\delta_{\lambda_j}
    \end{equation*}
    where $\lambda_j$'s are eigenvalues of $H$.

[Theorem thm:homogeneous-monomial-weight-complexity of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] For all $k\geq2$ and $h\geq1$,
\begin{equation}
 1+h+\cdots+h^{k-2}
 \leq W_k^{\mathrm{hom}}(h)
 \leq(k-1)h^{k-2}.
\end{equation}
Thus $W_k^{\mathrm{hom}}(h)=\Theta_k(h^{k-2})$ for fixed $k$.

[Prop transf_pant_to_alph of arXiv:2411.00629, '\Large Transformation of Stochastic Recursions and Critical Phenomena in the Analysis of t'] Suppose $\mathscr{X}(t)$ is a nonnegative binary-tree solution process of (equation markovsspantographeq of the paper), i.e.\ satisfying
\begin{equation}
\mathscr{X}(t)=\left\{ \begin{array}{*{35}{l}}
   0 & \text{if} & T_\theta\ge t  \\
   \mathscr{X}^{(1)}(\alpha (t-T_\theta))+\mathscr{X}^{(2)}(\alpha (t-T_\theta)) & \text{if} & T_\theta<t  \\
\end{array} \right.
\end{equation}
\begin{enumerate}[(i)]
\item $w(t)=\mathbb{E}(\mathscr{X}(t))$, if finite for all $t$, satisfies (equation markovsspantographeq of the paper).
\item For any $\lambda\ge 0$, $X(t)=e^{-\lambda\mathscr{X}(t)}$ satisfies (equation alphrecursion of the paper) and 
$u(t)=\mathbb{E}\left(e^{-\lambda\mathscr{X}(t)}\right)$ satisfies (equation diffalpha-ricc of the paper).
\end{enumerate}

[Proposition prop:Dn_limit of arXiv:2603.28936, 'Composition of random functions and word reconstruction'] Let $w$ be a word of exponent $d\geq 1$, i.e. $w=\pi^d$ for some primitive word $\pi$. For any $g\geq 1$ and any tuple $(z_0,\dots,z_{g-1})\in \mathbb{C}^g$ we have the convergence in distribution
\begin{align}
		\lim_{L\rightarrow \infty}
	\lim_{n\rightarrow \infty}
		\frac{1}{\log L} D_n^w(L,g; z_0,\dots,z_{g-1})
=
		\rho(d,g; z_0,\dots,z_{g-1}).
	\end{align}
	Moreover, the convergence also holds in expectation, and in probability in the sense of Definition~(def:bivariate of the paper).

