[Definition 32 of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] A function $\bar\xi:\R^\D_+\to\R$ is called a \textbf{regularization} of $\xi:\R^\D\to\R$ if the following conditions hold.
\begin{enumerate}
    \item  The function $\bar\xi$ agrees with $\xi$ on the intersection of $\R^\D_+$ with the closed unit ball in $\R^\D$.
    \item  The function $\bar\xi$ is Lipschitz and \textbf{proper} in the following sense: $\bar\xi$ is $\R^\D_+$-increasing and, for every $b\in\R^\D_+$, the map $\R^\D_+\ni a\mapsto \bar\xi(a+b)-\bar\xi(a)$ is also $\R^\D_+$-increasing.
\end{enumerate}

[Proposition prop:many-PDEs_new_intro_summ of arXiv:2604.25851, '{Non-uniqueness of nonlinear Markov processes in the sense of McKean associated with parab'] Let $(u(t,\cdot))_{t>0} \subseteq  \mathcal P_* $ be a solution to the FPE (equation intro:nl-PDE of the paper) (in the sense of (def:FPE-sol of the paper)) with initial condition $\zeta \in \mathcal P$ and coefficients $(a, b): \mathbb{R}^d \times \mathcal P_* \to \mathbb{R} \times \mathbb{R}^d$ for some $\mathcal P_* \subseteq \mathcal P_{\textup{ac}} $ satisfying the integrability condition (equation eq:integrability_our_paper of the paper). Let $f: \mathbb{R}^d \times \mathcal D(f) \to \mathbb{R} $ with $\mathcal D(f) \subseteq \mathcal P_{\textup{ac}}$, be such that $(u(t,\cdot))_{t >0} \subseteq\mathcal D(f)$, and 
        $f(x,u(t,\cdot)) + a(x,u(t,\cdot))u(t,x) \geq 0 \,  u(t,x)dxdt\text{-a.e.,}$
        and that (equation eq:assumption_f_strong of the paper) holds.
        Then $(u(t,\cdot))_{t> 0}$ also solves
        \begin{equation}
            \partial_t u = \Delta \Big( \big(a(x,u) + \frac{f(x,u)}{u} \big)  u \Big) - \nabla \cdot \Big( \big( b (x,  u ) + \frac{\nabla f(x,u)}{u} \big) u\Big),
    \end{equation}
    where the new coefficients are defined on $\hat{\mathcal P}_* \coloneqq \mathcal P_* \cap \{ u \in \mathcal D(f): \, f(\cdot,u) \in W^{1,1}_{\textup{loc}}(\mathbb{R}^d)\}$, with the convention $\frac {f(\cdot,u)} {u} := 0, \,\frac{\nabla f(\cdot, u)}{u} := 0$ on $\{u = 0\}$, and there exists a weak solution $(X_t)_{t\geq 0}$ to the corresponding MV-SDE 
        \begin{equation}
        \begin{dcases}
            dX_t = \left( b(X_t,u(t,\cdot)) + \frac{\nabla f(X_t,u(t,\cdot))}{u(t,X_t)} \right) dt + \sqrt{2}\left( a(X_t,u(t,\cdot)) + \frac{f(X_t,u(t,\cdot))}{u(t,X_t)} \right)^{\frac{1}{2}} dW_t, \\
            \mathcal{L}(X_t) = u(t,x)dx,\,  t>0, \,\,\, \mathcal{L}(X_0) = \zeta.
        \end{dcases}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:finL2 of arXiv:2506.17168, '{\bf Scaling limits for sample autocovariance operators of Hilbert space-valued linear pro'] Recall the kernel $\mathfrak{f}$ from (equation equality_f^(u,l)_t,(m,s) of the paper) and let $d(r) \in \left(\frac{1}{4},\frac{1}{2} \right)$. If 
\begin{equation}
    \int_{\mathbb{Y}} \frac{\sigma^2(r)}{(1- 2d(r))(2d(r) - 1/2)} \mu(dr) < \infty,
\end{equation}
then $\mathfrak{f}^{\sigma}(r,s,x,y) = \mathfrak{f}^{(r,s)}(x,y) \sigma(r) \sigma(s)$ takes values in $ L^2(\mathbb R^2:L^2(\mathbb Y^2))$.

