body:
[Theorem thm:main of arXiv:2606.24465, 'History estimation in random recursive trees:\\Pointwise approach via iterated Jordan cent'] For every $\varepsilon > 0$, there exist constants $c, C > 0$ such that for any $n \ge 1$, any $v \in [n]$ and any $S\in \left[ 1,c (n/v)^{1-\varepsilon} \right]$, the upper tail satisfies
    \begin{equation}
        c\frac{1+\log S}{S^2} 
        \ \leq\ \mathbb{P} \big( \widehat{\sigma}_{2}(v) \geq S v \big) 
        \ \leq\ C\frac{ 1+\log S}{S^2}.
    \end{equation}
    The upper bound holds for all $S\ge  1$.

    Moreover, there exist constants $c', C', \delta > 0$ such that for any $n \ge 1$, any $v \in [n/4]$, and any $S\in[1,\delta\sqrt{v}]$, the lower tail satisfies
    \begin{equation}
        \frac{c'}{S^2} 
        \ \leq\  \mathbb{P}\Big(\widehat{\sigma}_2(v) \leq \frac{1}{S}v\Big) 
        \ \leq\ \frac{C'}{S^2}.
    \end{equation}
    The upper bound holds for all $S \geq 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 ({\cite{Bou02}}) of arXiv:2609.01965, 'A logarithmic Bogomolov--Sommese vanishing theorem on compact K\"ahler manifolds'] Let $X$ be a compact K\"ahler manifold and $L$ a pseudo-effective line bundle over $X$. 
    Then
    \begin{equation*}
        H^0(X,\Omega^p_X\otimes L^{-1})=0 \quad \text{for every } p<\nd(L),
    \end{equation*}
    where $\nd(L)$ denotes the numerical dimension of $L$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 32 (Properties of the underdamped transient) of arXiv:2609.02728, 'Momentum in large-batch training: Polyak enlarges the critical batch size, Nesterov improv'] Let $\cS_{\mathrm{under}}(k)$ denote the deterministic bias contributed by the underdamped modes ($j \le J_{\max}$). Under the conditions of Proposition~\ref{prop:nes_deterministic_bias}, define the piecewise envelope $\mathcal{E}_{\mathrm{env}}(k)$ by:
\begin{equation*}
    \mathcal{E}_{\mathrm{env}}(k) := 
    \begin{cases}
    \rho^k, &\qquad k\lesssim\frac{1}{\eta},\\[2mm]
    \dfrac{\rho^k}{(\eta k)^s}, &\qquad \dfrac{1}{\eta} \lesssim k \lesssim \dfrac{1}{(1-\rho)^2},\\[3mm]
    \dfrac{1}{\eta k}\left(\dfrac{(1-\rho)^2}{\eta}\right)^{s-1}p_{\nesterov}^{\,k}, &\qquad \dfrac{1}{(1-\rho)^2} \lesssim k \lesssim \eta^{1/\beta}(1-\rho)^{-2-\frac{2}{\beta}},\\[3mm]
    \left(\dfrac{(1-\rho)^2}{\eta}\right)^{s+\frac{1}{\beta}}p_{\nesterov}^{\,k}, &\qquad k \gtrsim \eta^{1/\beta}(1-\rho)^{-2-\frac{2}{\beta}},
    \end{cases}
\end{equation*}
where $p_{\nesterov} := \rho\left(1 - \frac{(1-\rho)^2}{(1+\rho)^2}\right) = \frac{4\rho^2}{(1+\rho)^2} < \rho$. Then for every step $k \ge 0$, $\cS_{\mathrm{under}}(k)$ satisfies:
\begin{equation*}
    0 \le \cS_{\mathrm{under}}(k) \le C \mathcal{E}_{\mathrm{env}}(k).
\end{equation*}

[Proposition pro:covering-packing-3 of arXiv:2606.21556, 'Mean field limit of non-exchangeable interacting diffusions on co-evolutionary networks'] Consider a metric space $(\mathcal{X},d_\mathcal{X})$ and two compact subsets $K_1\subset K_2\subset \mathcal{X}$. Then,
$$\mathcal{M}_\varepsilon(K_1)\leq \mathcal{M}_\varepsilon(K_2)\quad \mbox{and}\quad \mathcal{N}_\varepsilon(K_1)\leq \mathcal{N}_{\frac{\varepsilon}{2}}(K_2),$$
for every $\varepsilon>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 2 of arXiv:2606.15178, 'The distribution of the de Moivre experiment'] Let $ X $ be a random variable that follows an $s$-Bernoulli distribution with parameter $ p $, $ X \sim \mathcal {B}^{(s)} (p) $. Then the expectation and the variance of $ X $ are
	\begin{equation}
		E(X) =	\frac{p \left((s+1) p^{s}-1\right)}{(p-q)},\qquad V(X) =\frac{p q\left( 1-(s+1)^2 (p q)^s\right) }{(p-q)^2}, \text{ for } p\neq q, 
	\end{equation}
	and
	\begin{equation}
		E(X)= s/2,\qquad V(X)=s(s+2)/12, \qquad \text{ for }p=q.
	\end{equation}

